(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("lucian-3-e", [{"sp": "HDR", "t": "Ῥητόρων Διδάσκαλος"}, {"sp": "N", "t": "ἐρωτᾷς, ὦ μειράκιον, ὅπως ἂν ῥήτωρ γένοιο καὶ τὸ σεμνότατον τοῦτο καὶ πάντιμον ὄνομα σοφιστὴς εἶναι δόξαις· ἀβίωτα γὰρ εἶναί σοι φής, εἰ μὴ τοιαύτην τινὰ τὴν δύναμιν περιβάλοιο ἐν τοῖς λόγοις ὡς ἄμαχον εἶναι καὶ ἀνυπόστατον καὶ θαυμάζεσθαι πρὸς ἁπάντων καὶ ἀποβλέπεσθαι, περισπούδαστον ἄκουσμα τοῖς Ἕλλησι δοκοῦντα· καὶ δὴ τὰς ἐπὶ τοῦτο ἀγούσας ὁδοὺς αἵτινές ποτέ εἰσιν ἐθέλεις ἐκμαθεῖν. ἀλλ’ οὐδεὶς φθόνος, ὦ παῖ, καὶ μάλιστα ὁπότε νέος τις αὐτὸς ὤν, ὀρεγόμενος τῶν ἀρίστων, οὐκ εἰδὼς ὅθεν ἂν ταῦτα ἐκπορίσαιτο, ἱερόν τι χρῆμα τὴν συμβουλὴν οὖσαν, καθάπερ νῦν σύ, τοῦτο αἰτοίη προσελθών. ὥστε ἄκουε, τό γε ἐπ’ ἐμοὶ καὶ πάνυ θαρρῶν ὡς τάχιστα δεινὸς ἀνὴρ ἔσῃ γνῶναί τε τὰ δέοντα καὶ ἑρμηνεῦσαι αὐτά, ἢν τὸ μετὰ τοῦτο ἐθελήσῃς αὐτὸς ἐμμένειν οἷς ἂν ἀκούσῃς παρ’ ἡμῶν καὶ φιλοπόνως αὐτὰ μελετᾶν καὶ προθύμως ἀνύειν τὴν ὁδὸν ἔστ’ ἂν ἀφίκῃ πρὸς τὸ τέρμα.", "st": "37.1"}, {"sp": "N", "t": "τὸ μὲν οὖν θήραμα οὐ σμικρὸν οὐδὲ ὀλίγης τῆς σπουδῆς δεόμενον, ἀλλὰ ἐφ’ ὅτῳ καὶ πονῆσαι πολλὰ καὶ ἀγρυπνῆσαι καὶ πᾶν ὁτιοῦν ὑπομεῖναι ἄξιον. σκόπει γοῦν ὁπόσοι τέως μηδὲν ὄντες ἔνδοξοι καὶ πλούσιοι καὶ νὴ Δία εὐγενέστατοι ἔδοξαν ἀπὸ τῶν λόγων.", "st": "37.2"}, {"sp": "N", "t": "ὅμως δὲ μὴ δέδιθι, μηδὲ πρὸς τὸ μέγεθος τῶν ἐλπιζομένων ἀποδυσπετήσῃς, μυρίους τινὰς τοὺς πόνους προπονῆσαι οἰηθείς. οὐ γάρ σε τραχεῖάν τινα οὐδὲ ὄρθιον καὶ ἱδρῶτος μεστὴν ἡμεῖς ἄξομεν, ὡς ἐκ μέσης αὐτῆς ἀναστρέψαι καμόντα, ἐπεὶ οὐδὲν ἂν διεφέρομεν τῶν ἄλλων ὅσοι τὴν συνήθη ἐκείνην ἡγοῦνται, μακρὰν καὶ ἀνάντη καὶ καματηρὰν καὶ ὡς τὸ πολὺ ἀπεγνωσμένην. ἀλλὰ παρ’ ἡμῶν ἐξαίρετον τῆς συμβουλῆς τοῦτό ἐστιν, ὅτι ἡδίστην τε ἅμα καὶ ἐπιτομωτάτην καὶ ἱππήλατον καὶ κατάντη σὺν πολλῇ τῇ θυμηδίᾳ καὶ τρυφῇ διὰ λειμώνων εὐανθῶν καὶ σκιᾶς ἀκριβοῦς σχολῇ καὶ βάδην ἀνιὼν ἀνιδρωτὶ ἐπιστήσῃ τῇ ἄκρᾳ καὶ ἀγρεύσεις οὐ καμὼν καὶ νὴ Δί’ εὐωχήσῃ κατακείμενος, ἐκείνους ὁπόσοι τὴν ἑτέραν ἐτράποντο ἀπὸ τοῦ ὑψηλοῦ ἐπισκοπῶν ἐν τῇ ὑπωρείᾳ τῆς ἀνόδου ἔτι, κατὰ δυσβάτων καὶ ὀλισθηρῶν τῶν κρημνῶν μόλις ἀνέρποντας, ἀποκυλιομένους ἐπὶ κεφαλὴν ἐνίοτε καὶ πολλὰ τραύματα λαμβάνοντας περὶ τραχείαις ταῖς πέτραις· σὺ δὲ πρὸ πολλοῦ ἄνω ἐστεφανωμένος εὐδαιμονέστατος ἔσῃ, ἅπαντα ἐν βραχεῖ ὅσα ἐστὶν ἀγαθὰ παρὰ τῆς ῥητορικῆς μονονουχὶ καθεύδων λαβών.", "st": "37.3"}, {"sp": "N", "t": "ἡ μὲν δὴ ὑπόσχεσις οὕτω μεγάλη· σὺ δὲ πρὸς Φιλίου μὴ ἀπιστήσῃς, εἰ ῥᾷστά τε ἅμα καὶ ἥδιστά σοι ταῦτα ἐπιδείξειν φαμέν. τί γάρ; Ἡσίοδος μὲν ὀλίγα φύλλα ἐκ τοῦ Ἑλικῶνος λαβὼν αὐτίκα μάλα ποιητὴς ἐκ ποιμένος κατέστη καὶ ᾖδε θεῶν καὶ ἡρώων γένη κάτοχος ἐκ Μουσῶν γενόμενος, ῥήτορα δέ, ὃ πολὺ ἔνερθε ποιητικῆς μεγαληγορίας ἐστίν, ἐν βραχεῖ καταστῆναι ἀδύνατον, εἴ τις ἐκμάθοι τὴν ταχίστην ὁδόν;", "st": "37.4"}, {"sp": "N", "t": "ὡς ἔγωγε καὶ διηγήσασθαι σοι βούλομαι Σιδωνίου τινὸς ἐμπόρου ἐπίνοιαν δι’ ἀπιστίαν ἀτελῆ γενομένην καὶ τῷ ἀκούσαντι ἀνόνητον. ἦρχε μὲν γὰρ ἤδη Ἀλέξανδρος Περσῶν, μετὰ τὴν ἐν Ἀρβήλοις μάχην Δαρεῖον καθῃρηκώς· ἔδει δὲ πανταχόσε τῆς ἀρχῆς διαθεῖν τοὺς γραμματοφόρους τὰ ἐπιτάγματα τοῦ Ἀλεξάνδρου κομίζοντας. ἐκ Περσῶν δὲ πολλὴ εἰς Αἴγυπτον ἐγίγνετο ἡ ὁδός· ἐκπεριιέναι γὰρ ἔδει τὰ ὄρη, εἶτα διὰ τῆς Βαβυλωνίας εἰς τὴν Ἀραβίαν ἐλθεῖν, εἶτα ἐρήμην πολλὴν περάσαντα ἀφικέσθαι ποτὲ μόλις εἰς Αἴγυπτον, εἴκοσι μηκίστους ἀνδρὶ εὐζώνῳ σταθμοὺς τούτους διανύσαντα. ἤχθετο οὖν ὁ Ἀλέξανδρος ἐπὶ τούτῳ, διότι Αἰγυπτίους τι παρακινεῖν ἀκούων οὐκ εἶχε διὰ ταχέων ἐκπέμπειν τοῖς σατράπαις τὰ δοκοῦντά οἱ περὶ αὐτῶν. τότε δὴ ὁ Σιδώνιος ἔμπορος, “ἐγώ σοι,” ἔφη, “ὦ βασιλεῦ, ὑπισχνοῦμαι δείξειν ὁδὸν οὐ πολλὴν ἐκ Περσῶν εἰς Αἴγυπτον. εἰ γάρ τις ὑπερβαίη τὰ ὄρη ταῦτα — ὑπερβαίη δ’ ἂν τριταῖος — αὐτίκα μάλα ἐν Αἰγύπτῳ οὗτός ἐστιν.” καὶ εἶχεν οὕτω. πλὴν ὅ γε Ἀλέξανδρος οὐκ ἐπίστευσεν, ἀλλὰ γόητα ᾤετο εἶναι τὸν ἔμπορον. οὕτω τὸ παράδοξον τῆς ὑποσχέσεως ἄπιστον δοκεῖ τοῖς πολλοῖς.", "st": "37.5"}, {"sp": "N", "t": "ἀλλὰ μὴ σύ γε πάθῃς τὸ αὐτό· εἴσῃ γὰρ πειρώμενος ὡς οὐδέν σε κωλύσει ῥήτορα δοκεῖν μιᾶς οὐδὲ ὅλης ἡμέρας ὑπερπετασθέντα τὸ ὄρος ἐκ Περσῶν εἰς Αἴγυπτον.", "st": "37.6"}, {"sp": "N", "t": "ἐθέλω δέ σοι πρῶτον ὥσπερ ὁ Κέβης ἐκεῖνος εἰκόνα γραψάμενος τῷ λόγῳ ἑκατέραν ἐπιδεῖξαι τὴν ὁδόν· δύο γάρ ἐστον, αἳ πρὸς τὴν Ῥητορικὴν ἄγετον, ἧς ἐρᾶν οὐ μετρίως μοι δοκεῖς. καὶ δῆτα ἡ μὲν ἐφ’ ὑψηλοῦ καθήσθω πάνυ καλὴ καὶ εὐπρόσωπος, τὸ τῆς Ἀμαλθείας κέρας ἔχουσα ἐν τῇ δεξιᾷ παντοίοις καρποῖς ὑπερβρύον· ἐπὶ θατέρᾳ δέ μοι τὸν πλοῦτον δόκει παρεστῶτα ὁρᾶν, χρυσοῦν ὅλον καὶ ἐπέραστον. καὶ ἡ δόξα δὲ καὶ ἡ ἰσχὺς παρέστωσαν, καὶ οἱ ἔπαινοι περὶ πᾶσαν αὐτὴν Ἔρωσι μικροῖς ἐοικότες πολλοὶ ἁπανταχόθεν περιπλεκέσθωσαν ἐκπετόμενοι. εἰ που τὸν Νεῖλον εἶδες γραφῇ μεμιμημένον, αὐτὸν μὲν κείμενον ἐπὶ κροκοδείλου τινὸς ἢ ἵππου τοῦ ποταμίου, οἷοι πολλοὶ ἐν αὐτῷ, μικρὰ δέ τινα παιδία παρ’ αὐτὸν παίζοντα — πήχεις δὲ αὐτοὺς οἱ Αἰγύπτιοι καλοῦσι, — τοιοῦτοι καὶ περὶ τὴν Ῥητορικὴν οἱ ἔπαινοι.", "st": "37.6"}, {"sp": "N", "t": "πρόσει δὴ σὺ ὁ ἐραστὴς ἐπιθυμῶν δηλαδὴ ὅτι τάχιστα γενέσθαι ἐπὶ τῆς ἄκρας, ὡς γαμήσειάς τε αὐτὴν ἀνελθὼν καὶ πάντα ἐκεῖνα ἔχοις, τὸν πλοῦτον τὴν δόξαν τοὺς ἐπαίνους· νόμῳ γὰρ ἅπαντα γίγνεται τοῦ γεγαμηκότος.", "st": "37.6"}, {"sp": "N", "t": "εἶτ’ ἐπειδὰν πλησιάσῃς τῷ ὄρει, τὸ μὲν πρῶτον ἀπογιγνώσκεις τὴν ἄνοδον, καὶ τὸ πρᾶγμα ὅμοιον εἶναί σοι δοκεῖ οἵα ἡ Ἄορνος ἐφάνη τοῖς Μακεδόσιν ἀπόξυρον αὐτὴν ἁπανταχόθεν ἰδοῦσιν, ἀτεχνῶς οὐδὲ ὀρνέοις ὑπερπτῆναι ῥᾳδίαν, Διονύσου τινὸς ἢ Ἡρακλέους, εἰ μέλλοι καθαιρεθήσεσθαι, δεομένην.", "st": "37.7"}, {"sp": "N", "t": "ταῦτά σοι δοκεῖ τὸ πρῶτον· εἶτα μετ’ ὀλίγον ὁρᾷς δύο τινὰς ὁδούς. μᾶλλον δὲ ἡ μὲν ἀτραπός ἐστι στενὴ καὶ ἀκανθώδης καὶ τραχεῖα, πολὺ τὸ δίψος ἐμφαίνουσα καὶ ἱδρῶτα· καὶ ἔφθη γὰρ ἤδη Ἡσίοδος εὖ μάλα ὑποδείξας αὐτήν, ὥστε οὐδὲν ἐμοῦ δεήσει. ἡ ἑτέρα δὲ πλατεῖα καὶ ἀνθηρὰ καὶ εὔυδρος, τοιαύτη οἵαν μικρῷ πρόσθεν εἶπον, ἵνα μὴ πολλάκις τὰ αὐτὰ λέγων ἐπέχω σε ἤδη ῥήτορα εἶναι δυνάμενον.", "st": "37.7"}, {"sp": "N", "t": "πλὴν τό γε τοσοῦτον προσθήσειν μοι δοκῶ, διότι ἡ μὲν τραχεῖα ἐκείνη καὶ ἀνάντης οὐ πολλὰ ἴχνη τῶν ὁδοιπόρων εἶχεν, εἰ δέ τινα, πάνυ παλαιά. καὶ ἔγωγε κατ’ ἐκείνην ἄθλιος ἀνῆλθον τοσαῦτα καμὼν οὐδὲν δέον· ἡ ἑτέρα δὲ ἅτε ὁμαλὴ οὖσα καὶ ἀγκύλον οὐδὲν ἔχουσα πόρρωθέν μοι ἐφάνη οἵα ἐστὶν οὐχ ὁδεύσαντι αὐτῷ. οὐ γὰρ ἑώρων νέος ὢν ἔτι τὸ βέλτιον, ἀλλὰ τὸν ποιητὴν ἐκεῖνον ἀληθεύειν ᾤμην λέγοντα ἐκ τῶν πόνων φύεσθαι τὰ ἀγαθά. τὸ δ’ οὐκ εἶχεν οὕτως· ἀπονητὶ γοῦν ὁρῶ τοὺς πολλοὺς μειζόνων ἀξιουμένους εὐμοιρίᾳ τῆς αἱρέσεως τῶν λόγων καὶ ὁδῶν.", "st": "37.8"}, {"sp": "N", "t": "ἐπὶ δ’ οὖν τὴν ἀρχὴν ἀφικόμενος εὖ οἶδ’ ὅτι ἀπορήσεις, καὶ ἤδη ἀπορεῖς, ποτέραν τρεπτέον. ὡς οὖν ποιήσας ἤδη ῥᾷστα ἐπὶ τὸ ἀκρότατον ἀναβήσῃ καὶ εὐδαιμονήσεις καὶ γαμήσεις καὶ θαυμαστὸς πᾶσι δόξεις, ἐγώ σοι φράσω· ἱκανὸν γὰρ τὸ αὐτὸν ἐξαπατηθῆναι καὶ πονῆσαι. σοὶ δὲ ἄσπορα καὶ ἀνήροτα πάντα φυέσθω καθάπερ ἐπὶ τοῦ Κρόνου.", "st": "37.8"}, {"sp": "N", "t": "εὐθὺς οὖν σοι πρόσεισι καρτερός τις ἀνήρ, ὑπόσκληρος, ἀνδρώδης τὸ βάδισμα, πολὺν τὸν ἥλιον ἐπὶ τῷ σώματι δεικνύων, ἀρρενωπὸς τὸ βλέμμα, ἐγρηγορώς, τῆς τραχείας ὁδοῦ ἐκείνης ἡγεμών, λήρους τινὰς ὁ μάταιος διεξιὼν πρὸς σέ. ἕπεσθαι γάρ οἱ παρακελευόμενος, ὑποδεικνὺς τὰ Δημοσθένους ἴχνη καὶ Πλάτωνος καὶ ἄλλων τινῶν, μεγάλα μὲν καὶ ὑπὲρ τοὺς νῦν, ἀμαυρὰ δὲ ἤδη καὶ ἀσαφῆ τὰ πολλὰ ὑπὸ τοῦ χρόνου, φήσει εὐδαίμονά σε ἔσεσθαι καὶ νόμῳ γαμήσειν τὴν Ῥητορικήν, εἰ κατὰ τούτων ὁδεύσειας ὥσπερ οἱ ἐπὶ τῶν κάλων βαίνοντες· εἰ δὲ κἂν μικρόν τι παραβαίης ἢ ἔξω πατήσειας ἢ ἐπὶ θάτερα μᾶλλον κλιθείης τῇ ῥοπῇ, ἐκπεσεῖσθαί σε τῆς ὀρθῆς ὁδοῦ καὶ ἀγούσης ἐπὶ τὸν γάμον. εἶτά σε κελεύσει ζηλοῦν ἐκείνους τοὺς ἀρχαίους ἄνδρας ἕωλα παραδείγματα παρατιθεὶς τῶν λόγων οὐ ῥᾴδια μιμεῖσθαι, οἷα τὰ τῆς παλαιᾶς ἐργασίας ἐστίν, Ἡγησίου καὶ τῶν ἀμφὶ Κριτίον καὶ Νησιώτην, ἀπεσφιγμένα καὶ νευρώδη καὶ σκληρὰ καὶ ἀκριβῶς ἀποτεταμένα ταῖς γραμμαῖς. πόνον δὲ καὶ ἀγρυπνίαν καὶ ὑδατοποσίαν καὶ τὸ ἀλιπαρὲς ἀναγκαῖα ταῦτα καὶ ἀπαραίτητα φήσει· ἀδύνατον γὰρ εἶναι ἄνευ τούτων διανύσαι τὴν ὁδόν. ὃ δὲ πάντων ἀνιαρότατον, ὅτι σοι καὶ τὸν χρόνον πάμπολυν ὑπογράψει τῆς ὁδοιπορίας, ἔτη πολλά, οὐ κατὰ ἡμέρας καὶ τριακάδας, ἀλλὰ κατὰ ὀλυμπιάδας ὅλας ἀριθμῶν, ὡς καὶ προαποκαμεῖν ἀκούοντα καὶ ἀπαγορεῦσαι, πολλὰ χαίρειν φράσαντα τῇ ἐλπιζομένῃ ἐκείνῃ εὐδαιμονίᾳ. πρὸς δὲ τούτοις οὐδὲ μισθοὺς ὀλίγους ἀπαιτεῖ τῶν τοσούτων κακῶν, ἀλλὰ οὐκ ἂν ἡγήσαιτό σοι, εἰ μὴ μεγάλα πρότερον λάβοι.", "st": "37.9"}, {"sp": "N", "t": "ὁ μὲν ταῦτα φήσει, ἀλαζὼν καὶ ἀρχαῖος ὡς ἀληθῶς καὶ Κρονικὸς ἄνθρωπος, νεκροὺς εἰς μίμησιν παλαιοὺς προτιθεὶς καὶ ἀνορύττειν ἀξιῶν λόγους πάλαι κατορωρυγμένους ὥς τι μέγιστον ἀγαθόν, μαχαιροποιοῦ υἱὸν καὶ ἄλλον Ἀτρομήτου τινὸς γραμματιστοῦ ζηλοῦν ἀξιῶν, καὶ ταῦτα ἐν εἰρήνῃ μήτε Φιλίππου ἐπιόντος μήτε Ἀλεξάνδρου ἐπιτάττοντος, ὅπου τὰ ἐκείνων ἴσως ἐδόκει χρήσιμα, οὐκ εἰδὼς ὁποία νῦν κεκαινοτόμηται ταχεῖα καὶ ἀπράγμων καὶ εἰς τὸ εὐθὺ τῆς ῥητορικῆς ὁδός. σὺ δὲ μήτε πείθεσθαι μήτε προσέχειν αὐτῷ, μή σε ἐκτραχηλίσῃ που παραλαβὼν ἢ τὸ τελευταῖον προγηρᾶσαι τοῖς πόνοις παρασκευάσῃ. ἀλλὰ εἰ πάντως ἐρᾷς καὶ τάχιστα ἐθέλεις τῇ ῥητορικῇ συνεῖναι ἀκμάζων ἔτι, ὡς καὶ σπουδάζοιο πρὸς αὐτῆς, ἴθι, τῷ μὲν δασεῖ τούτῳ καὶ πέρα τοῦ μετρίου ἀνδρικῷ μακρὰ χαίρειν λέγε, ἀναβαίνειν αὐτὸν καὶ ἄλλους ὁπόσους ἂν ἐξαπατᾶν δύνηται ἀνάγειν καταλιπὼν ἀσθμαίνοντα καὶ ἱδρῶτι πολλῷ συνόντα.", "st": "37.10"}, {"sp": "N", "t": "πρὸς δὲ τὴν ἑτέραν ἐλθὼν εὑρήσεις πολλοὺς καὶ ἄλλους, ἐν τούτοις δὲ καὶ πάνσοφόν τινα καὶ πάγκαλον ἄνδρα, διασεσαλευμένον τὸ βάδισμα, ἐπικεκλασμένον τὸν αὐχένα, γυναικεῖον τὸ βλέμμα, μελιχρὸν τὸ φώνημα, μύρων ἀποπνέοντα, τῷ δακτύλῳ ἄκρῳ τὴν κεφαλὴν κνώμενον, ὀλίγας μὲν ἔτι, οὔλας δὲ καὶ ὑακινθίνας τὰς τρίχας εὐθετίζοντα, πάναβρόν τινα Σαρδανάπαλλον ἢ Κινύραν ἢ αὐτὸν Ἀγάθωνα, τὸν τῆς τραγῳδίας ἐπέραστον ἐκεῖνον ποιητήν. λέγω δὲ ὡς ἀπὸ τούτων γνωρίζοις αὐτόν, μηδέ σε οὕτω θεσπέσιον χρῆμα καὶ φίλον Ἀφροδίτῃ καὶ Χάρισι διαλάθοι. καίτοι τί φημί; κἂν εἰ μύοντι γάρ σοι προσελθὼν εἴποι τι, τὸ Ὑμήττιον ἐκεῖνο ἀνοίξας στόμα, καὶ τὴν συνήθη φωνὴν ἀφείη, μάθοις ἂν ὡς οὐχὶ τῶν καθ’ ἡμᾶς ἐστιν, οἳ ἀρούρης καρπὸν ἔδομεν, ἀλλά τι ξένον φάσμα δρόσῳ ἢ ἀμβροσίᾳ τρεφόμενον. τούτῳ τοίνυν προσελθὼν καὶ παραδοὺς σεαυτὸν αὐτίκα μάλα ῥήτωρ καὶ περίβλεπτος καί, ὡς ὀνομάζει αὐτός, βασιλεὺς ἐν τοῖς λόγοις ἀπονητὶ καταστήσῃ τὰ τέθριππα ἐλαύνων τοῦ λόγου. διδάξεται γάρ σε παραλαβὼν τὰ πρῶτα μὲν ἐκεῖνα — μᾶλλον δὲ αὐτὸς εἰπάτω πρὸς σέ·", "st": "37.11"}, {"sp": "N", "t": "γελοῖον γὰρ ὑπὲρ τοιούτου ῥήτορος ἐμὲ ποιεῖσθαι τοὺς λόγους, φαῦλον ὑποκριτὴν ἴσως τῶν τοιούτων καὶ τηλικούτων, μὴ καὶ συντρίψω που πεσὼν τὸν ἥρωα ὃν ὑποκρίνομαι.", "st": "37.12"}, {"sp": "N", "t": "φαίη τοιγαροῦν ἂν πρὸς σὲ ὧδέ πως ἐπισπασάμενος ὁπόσον ἔτι λοιπὸν τῆς κόμης καὶ ὑπομειδιάσας τὸ γλαφυρὸν ἐκεῖνο καὶ ἁπαλὸν οἷον εἴωθεν, Αὐτοθαΐδα τὴν κωμικὴν ἢ Μαλθάκην ἢ Γλυκέραν τινὰ μιμησάμενος τῷ προσηνεῖ τοῦ φθέγματος· ἄγροικον γὰρ τὸ ἀρρενωπὸν καὶ οὐ πρὸς ἁβροῦ καὶ ἐρασμίου ῥήτορος.", "st": "37.12"}, {"sp": "N", "t": "φήσει δ’ οὖν πάνυ μετριάζων ὑπὲρ αὐτόν, Μῶν σε, ὦγαθέ, ὁ Πύθιος ἔπεμψε πρός με ῥητόρων τὸν ἄριστον προσειπών, ὥσπερ ὅτε Χαιρεφῶν ἤρετο αὐτόν, ἔδειξεν ὅστις ἦν ὁ σοφώτατος ἐν τοῖς τότε; εἰ δὲ μὴ τοῦτο, ἀλλὰ κατὰ κλέος αὐτὸς ἥκεις ἀκούων ἁπάντων ὑπερεκπεπληγμένων τὰ ἡμέτερα καὶ ὑμνούντων καὶ τεθηπότων καὶ ὑπεπτηχότων, αὐτίκα μάλα εἴσῃ πρὸς οἷόν τινα δαιμόνιον ἄνδρα ἥκεις. προσδοκήσῃς δὲ μηδὲν τοιοῦτον ὄψεσθαι οἷον τῷδε ἢ τῷδε παραβαλεῖν, ἀλλ’ εἴ τις ἢ Τιτυὸς ἢ Ὦτος ἢ Ἐφιάλτης, ὑπὲρ ἐκείνους πολὺ φανεῖταί σοι τὸ πρᾶγμα ὑπερφυὲς καὶ τεράστιον· ἐπεὶ τούς γε ἄλλους τοσοῦτον ὑπερφωνοῦντα εὑρήσεις ὁπόσον ἡ σάλπιγξ τοὺς αὐλοὺς καὶ οἱ τέττιγες τὰς μελίττας καὶ οἱ χοροὶ τοὺς ἐνδιδόντας.", "st": "37.13"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ ῥήτωρ αὐτὸς ἐθέλεις γενέσθαι καὶ τοῦτο οὐκ ἂν παρ’ ἄλλου ῥᾷον μάθοις, ἕπου μόνον, ὦ μέλημα, οἷς ἂν εἴπω καὶ ζήλου πάντα, καὶ τοὺς νόμους οἷς ἂν ἐπιτάξω χρῆσθαι ἀκριβῶς μοι παραφύλαττε. μᾶλλον δὲ ἤδη προχώρει μηδὲν ὀκνήσας μηδὲ πτοηθείς, εἰ μὴ προετελέσθης ἐκεῖνα τὰ πρὸ τῆς ῥητορικῆς, ὁπόσα ἡ ἄλλη προπαιδεία τοῖς ἀνοήτοις καὶ ματαίοις μετὰ πολλοῦ καμάτου ὁδοποιεῖ· οὐδὲν γὰρ αὐτῶν δεήσει. ἀλλ’ ἀνίπτοις ποσίν — ἡ παροιμία φησίν — ἔμβαινε, οὐ μεῖον ἕξων διὰ τοῦτο, οὐδ’ ἄν, τὸ κοινότατον, μηδὲ γράφειν τὰ γράμματα εἰδῇς· ἄλλο γάρ τι παρὰ ταῦτα ὁ ῥήτωρ.", "st": "37.14"}, {"sp": "N", "t": "λέξω δὲ πρῶτον μὲν ὁπόσα χρὴ αὐτόν σε οἴκοθεν ἔχοντα ἥκειν ἐφόδια πρὸς τὴν πορείαν καὶ ὅπως ἐπισιτίσασθαι, ὡς ἂν τάχιστα διανύσαι δυνηθείης. ἔπειτα καὐτὸς ἃ μὲν προϊόντι ἐπιδεικνὺς κατὰ τὴν ὁδόν, ἃ δὲ καὶ παραινῶν, πρὶν ἥλιον δῦναι ῥήτορά σε ὑπὲρ τοὺς πάντας ἀποφανῶ, οἷος αὐτός εἰμι, ἀναμφιλέκτως τὰ πρῶτα καὶ μέσα καὶ τελευταῖα τῶν λέγειν ἐπιχειρούντων.", "st": "37.15"}, {"sp": "N", "t": "κόμιζε τοίνυν τὸ μέγιστον μὲν τὴν ἀμαθίαν, εἶτα θράσος, ἐπὶ τούτοις δὲ τόλμαν καὶ ἀναισχυντίαν. αἰδῶ δὲ ἢ ἐπιείκειαν ἢ μετριότητα ἢ ἐρύθημα οἴκοι ἀπόλιπε· ἀχρεῖα γὰρ καὶ ὑπεναντία τῷ πράγματι. ἀλλὰ καὶ βοὴν ὅτι μεγίστην καὶ μέλος ἀναίσχυντον καὶ βάδισμα οἷον τὸ ἐμόν. ταῦτα δὲ ἀναγκαῖα πάνυ καὶ μόνα ἔστιν ὅτε ἱκανά. καὶ ἡ ἐσθὴς δὲ ἔστω εὐανθὴς ἢ λευκή, ἔργον τῆς Ταραντίνης ἐργασίας, ὡς διαφαίνεσθαι τὸ σῶμα, καὶ ἢ κρηπὶς Ἀττικὴ γυναικεία, τὸ πολυσχιδές, ἢ ἐμβὰς Σικυωνία πίλοις τοῖς λευκοῖς ἐπιπρέπουσα, καὶ ἀκόλουθοι πολλοὶ καὶ βιβλίον ἀεί.", "st": "37.15"}, {"sp": "N", "t": "ταῦτα μὲν αὐτὸν χρὴ συντελεῖν· τὰ δ’ ἄλλα καθ’ ὁδὸν ἤδη προϊὼν ὅρα καὶ ἄκουε.", "st": "37.15"}, {"sp": "N", "t": "καὶ δή σοι τοὺς νόμους δίειμι, οἷς χρώμενόν σε ἡ Ῥητορικὴ γνωριεῖ καὶ προσήσεται, οὐδὲ ἀποστραφήσεται καὶ σκορακιεῖ καθάπερ ἀτέλεστόν τινα καὶ κατάσκοπον τῶν ἀπορρήτων. σχήματος μὲν τὸ πρῶτον ἐπιμεληθῆναι χρὴ μάλιστα καὶ εὐμόρφου τῆς ἀναβολῆς, ἔπειτα πεντεκαίδεκα ἢ οὐ πλείω γε τῶν εἴκοσιν Ἀττικὰ ὀνόματα ἐκλέξας ποθὲν ἀκριβῶς ἐκμελετήσας, πρόχειρα ἐπ’ ἄκρας τῆς γλώττης ἔχε — τὸ ἄττα καὶ κᾆτα καὶ μῶν καὶ ἀμηγέπη καὶ λῷστε καὶ τὰ τοιαῦτα, — καὶ ἐν ἅπαντι λόγῳ καθάπερ τι ἥδυσμα ἐπίπαττε αὐτῶν. μελέτω δὲ μηδὲν τῶν ἄλλων, εἰ ἀνόμοια τούτοις καὶ ἀσύμφυλα καὶ ἀπῳδά. ἡ πορφύρα μόνον ἔστω καλὴ καὶ εὐανθής, κἂν σισύρα τῶν παχειῶν τὸ ἱμάτιον ᾖ.", "st": "37.16"}, {"sp": "N", "t": "μέτει δὲ ἀπόρρητα καὶ ξένα ῥήματα, σπανιάκις ὑπὸ τῶν πάλαι εἰρημένα, καὶ ταῦτα συμφορήσας ἀποτόξευε προχειριζόμενος εἰς τοὺς προσομιλοῦντας. οὕτω γάρ σε ὁ λεὼς ὁ πολὺς ἀποβλέψονται καὶ θαυμαστὸν ὑπολήψονται καὶ τὴν παιδείαν ὑπὲρ αὐτούς, εἰ “ἀποστλεγγίσασθαι τὸ” ἀποξύσασθαι λέγοις, τὸ δὲ ἡλίῳ θέρεσθαι “εἱληθερεῖσθαι,” τὸν ἀρραβῶνα δὲ “προνόμιον,” τὸν ὄρθρον δὲ “ἀκροκνεφές.” ἐνίοτε δὲ καὶ αὐτὸς ποίει καινὰ καὶ ἀλλόκοτα ὀνόματα καὶ νομοθέτει τὸν μὲν ἑρμηνεῦσαι δεινὸν “εὔλεξιν” καλεῖν, τὸν συνετὸν “σοφόνουν,” τὸν ὀρχηστὴν δὲ “χειρίσοφον.” ἂν σολοικίσῃς δὲ ἢ βαρβαρίσῃς, ἓν ἔστω φάρμακον ἡ ἀναισχυντία, καὶ πρόχειρον εὐθὺς ὄνομα οὔτε ὄντος τινὸς οὔτε γενομένου ποτέ, ἢ ποιητοῦ ἢ συγγραφέως, ὃς οὕτω λέγειν ἐδοκίμαζε σοφὸς ἀνὴρ καὶ τὴν φωνὴν εἰς τὸ ἀκρότατον ἀπηκριβωμένος. ἀλλὰ καὶ ἀναγίγνωσκε τὰ παλαιὰ μὲν μὴ σύ γε, μηδὲ εἴ τι ὁ λῆρος Ἰσοκράτης ἢ ὁ χαρίτων ἄμοιρος Δημοσθένης ἢ ὁ ψυχρὸς Πλάτων, ἀλλὰ τοὺς τῶν ὀλίγον πρὸ ἡμῶν λόγους καὶ ἅς φασι ταύτας μελέτας, ὡς ἔχῃς ἀπ’ ἐκείνων ἐπισιτισάμενος ἐν καιρῷ καταχρῆσθαι καθάπερ ἐκ ταμιείου προαιρῶν.", "st": "37.17"}, {"sp": "N", "t": "ἐπειδὰν δὲ καὶ δέῃ λέγειν καὶ οἱ παρόντες ὑποβάλωσί τινας ὑποθέσεις καὶ ἀφορμὰς τῶν λόγων, ἅπαντα μὲν ὁπόσα ἂν ᾖ δυσχερῆ, ψεγέσθω καὶ ἐκφαυλιζέσθω ὡς οὐδὲν ὅλως ἀνδρῶδες αὐτῶν. ἑλομένων δέ, μὴ μελλήσας λέγε ὅττι κεν ἐπ’ ἀκαιρίμαν γλῶτταν ἔλθῃ, μηδὲν ἐκείνων ἐπιμεληθείς, ὡς τὸ πρῶτον, ὥσπερ οὖν καὶ ἔστι πρῶτον, ἐρεῖς ἐν καιρῷ προσήκοντι καὶ τὸ δεύτερον μετὰ τοῦτο καὶ τὸ τρίτον μετ’ ἐκεῖνο, ἀλλὰ τὸ πρῶτον ἐμπεσὸν πρῶτον λεγέσθω, καὶ ἢν οὕτω τύχῃ, περὶ τῷ μετώπῳ μὲν ἡ κνημίς, περὶ τῇ κνήμῃ δὲ ἡ κόρυς. πλὴν ἀλλ’ ἔπειγε καὶ σύνειρε καὶ μὴ σιώπα μόνον. κἂν περὶ ὑβριστοῦ τινος ἢ μοιχοῦ λέγῃς Ἀθήνησι, τὰ ἐν Ἰνδοῖς καὶ Ἐκβατάνοις λεγέσθω. ἐπὶ πᾶσι δὲ ὁ Μαραθὼν καὶ ὁ Κυνέγειρος, ὧν οὐκ ἄν τι ἄνευ γένοιτο. καὶ ἀεὶ ὁ Ἄθως πλείσθω καὶ ὁ Ἑλλήσποντος πεζευέσθω καὶ ὁ ἥλιος ὑπὸ τῶν Μηδικῶν βελῶν σκεπέσθω καὶ Ξέρξης φευγέτω καὶ Λεωνίδας θαυμαζέσθω καὶ τὰ Ὀθρυάδου γράμματα ἀναγιγνωσκέσθω, καὶ ἡ Σαλαμὶς καὶ τὸ Ἀρτεμίσιον καὶ αἱ Πλαταιαὶ πολλὰ ταῦτα καὶ πυκνά. καὶ ἐπὶ πᾶσι τὰ ὀλίγα ἐκεῖνα ὀνόματα ἐπιπολαζέτω καὶ ἐπανθείτω, καὶ συνεχὲς τὸ ἄττα καὶ τὸ δήπουθεν, κἂν μηδὲν αὐτῶν δέῃ· καλὰ γάρ ἐστι καὶ εἰκῆ λεγόμενα.", "st": "37.18"}, {"sp": "N", "t": "ἢν δέ ποτε καὶ ᾆσαι καιρὸς εἶναι δοκῇ, πάντα σοι ᾀδέσθω καὶ μέλος γιγνέσθω. κἄν ποτε ἀπορήσῃς πράγματος ᾠδικοῦ, τοὺς ἄνδρας τοὺς δικαστὰς ὀνομάσας ἐμμελῶς πεπληρωκέναι οἴου τὴν ἁρμονίαν. τὸ δὲ οἴμοι τῶν κακῶν πολλάκις, καὶ ὁ μηρὸς πατασσέσθω, καὶ λαρύγγιζε καὶ ἐπιχρέμπτου τοῖς λεγομένοις καὶ βάδιζε μεταφέρων τὴν πυγήν. καὶ ἢν μέν σε μὴ ἐπαινῶσιν, ἀγανάκτει καὶ λοιδοροῦ αὐτοῖς· ἢν δὲ ὀρθοὶ ἑστήκωσιν ὑπὸ τῆς αἰσχύνης ἤδη πρὸς τὴν ἔξοδον ἕτοιμοι, καθέζεσθαι κέλευε, καὶ ὅλως τυραννὶς τὸ πρᾶγμα ἔστω.", "st": "37.19"}, {"sp": "N", "t": "ὅπως δὲ καὶ τὸ πλῆθος τῶν λόγων θαυμάζωσιν, ἀπὸ τῶν Ἰλιακῶν ἀρξάμενος ἢ καὶ νὴ Δία ἀπὸ τῶν Δευκαλίωνος καὶ Πύρρας γάμων, ἢν δοκῇ, καταβίβαζε τὸν λόγον ἐπὶ τὰ νῦν καθεστῶτα. οἱ μὲν γὰρ συνιέντες ὀλίγοι, οἳ μάλιστα μὲν σιωπήσονται ὑπ’ εὐγνωμοσύνης· ἢν δὲ καὶ λέγωσί τι, ὑπὸ φθόνου αὐτὸ δόξουσι δρᾶν. οἱ πολλοὶ δὲ τὸ σχῆμα καὶ φωνὴν καὶ βάδισμα καὶ περίπατον καὶ μέλος καὶ κρηπῖδα καὶ τὸ ἄττα σου ἐκεῖνο τεθήπασι, καὶ τὸν ἱδρῶτα ὁρῶντες καὶ τὸ ἆσθμα οὐκ ἔχουσιν ὅπως ἀπιστήσουσι μὴ οὐχὶ πάνδεινόν τινα ἐν τοῖς λόγοις ἀγωνιστὴν εἶναί σε. ἄλλως τε καὶ τὸ ταχὺ τοῦτο οὐ μικρὰν ἔχει τὴν ἀπολογίαν καὶ θαῦμα παρὰ τοῖς πολλοῖς· ὥστε ὅρα μή ποτε γράψῃς ἢ σκεψάμενος παρέλθῃς, ἔλεγχος γὰρ σαφὴς ταῦτά γε.", "st": "37.20"}, {"sp": "N", "t": "οἱ φίλοι δὲ ἀναπηδάτωσαν ἀεὶ καὶ μισθὸν τῶν δείπνων ἀποτινέτωσαν, εἴ ποτε αἴσθοιντό σε καταπεσούμενον, χεῖρα ὀρέγοντες καὶ παρέχοντες εὑρεῖν τὸ λεχθησόμενον ἐν τοῖς μεταξὺ τῶν ἐπαίνων διαλείμμασι· καὶ γὰρ αὖ καὶ τοῦδε μελέτω σοι τὸν χορὸν ἔχειν οἰκεῖον καὶ συνᾴδοντα.", "st": "37.21"}, {"sp": "N", "t": "ταῦτα μέν σοι τὰ ἐν τοῖς λόγοις. μετὰ ταῦτα δὲ προϊόντα σε δορυφορείτωσαν ἐγκεκαλυμμένον αὐτὸν καὶ περὶ ὧν ἔφης μεταξὺ διαλαμβάνοντα. καὶ ἤν τις ἐντύχῃ, θαυμάσια περὶ σαυτοῦ λέγε καὶ ὑπερεπαίνει καὶ ἐπαχθὴς γίγνου αὐτῷ. “τί γὰρ ὁ Παιανιεὺς πρὸς ἐμὲ;” καί, “πρὸς ἕνα ἴσως μοι τῶν παλαιῶν ὁ ἀγών” καὶ τὰ τοιαῦτα.", "st": "37.21"}, {"sp": "N", "t": "ὃ δὲ μέγιστον καὶ πρὸς τὸ εὐδοκιμεῖν ἀναγκαιότατον ὀλίγου δεῖν παρέλιπον, ἁπάντων καταγέλα τῶν λεγόντων. καὶ ἢν μέν τις καλῶς εἴπῃ, ἀλλότρια καὶ οὐχ ἑαυτοῦ δεικνύειν δοκείτω· ἢν δὲ μετρίως ἐλεγχθῇ, πάντα ἔστω ἐπιλήψιμα. καὶ ἐν ταῖς ἀκροάσεσι μετὰ πάντας εἰσιέναι χρή, ἐπίσημον γάρ· καὶ σιωπησάντων ἁπάντων ξένον τινὰ ἔπαινον ἐπειπεῖν τὰς ἀκοὰς τῶν παρόντων ἐπιστρέψοντα καὶ ἐνοχλήσοντα, ὡς ναυτιᾶν ἅπαντας ἐπὶ τῷ φορτικῷ τῶν ὀνομάτων καὶ ἐπιφράττεσθαι τὰ ὦτα. καὶ ἐπισείσῃς δὲ μὴ πολλάκις τὴν χεῖρα, εὐτελὲς γάρ, μηδ’ ἀναστῇς, πλὴν ἅπαξ γε ἢ δὶς τὸ πλεῖστον. ὑπομειδία δὲ τὰ πολλὰ καὶ δῆλος γίγνου μὴ ἀρεσκόμενος τοῖς λεγομένοις. ἀμφιλαφεῖς δὲ αἱ ἀφορμαὶ τῶν μέμψεων τοῖς συκοφαντικοῖς τὰ ὦτα.", "st": "37.22"}, {"sp": "N", "t": "τὰ δ’ ἄλλα χρὴ θαρρεῖν· ἡ τόλμα γὰρ καὶ ἡ ἀναισχυντία καὶ ψεῦδος πρόχειρον καὶ ὅρκος ἐπ’ ἄκροις ἀεὶ τοῖς χείλεσι καὶ φθόνος πρὸς ἅπαντας καὶ μῖσος καὶ βλασφημία καὶ διαβολαὶ πιθαναί — ταῦτά σε ἀοίδιμον ἐν βραχεῖ καὶ περίβλεπτον ἀποφανεῖ.", "st": "37.22"}, {"sp": "N", "t": "τοιαῦτα μὲν τὰ φανερὰ καὶ τὰ ἔξω. ἰδίᾳ δὲ πάντα πράγματα ποιεῖν σοι δεδόχθω, κυβεύειν μεθύσκεσθαι λαγνεύειν μοιχεύειν, ἢ αὐχεῖν γε, κἂν μὴ ποιῇς, καὶ πρὸς ἅπαντας λέγειν καὶ γραμματεῖα ὑποδεικνύναι ὑπὸ γυναικῶν δῆθεν γραφέντα. καλὸς γὰρ εἶναι θέλε καὶ σοὶ μελέτω ὑπὸ τῶν γυναικῶν σπουδάζεσθαι δοκεῖν· εἰς τὴν ῥητορικὴν γὰρ καὶ τοῦτο ἀνοίσουσιν οἱ πολλοί, ὡς διὰ τοῦτό σου καὶ ἄχρι τῆς γυναικωνίτιδος εὐδοκιμοῦντος. καὶ τὸ δεῖνα δέ, μὴ αἰδεσθῇς, εἰ καὶ πρὸς ἀνδρῶν ἐπὶ τῷ ἑτέρῳ ἐρᾶσθαι δοκοίης, καὶ ταῦτα γενειήτης ἢ καὶ νὴ Δία φαλακρὸς ἤδη ὤν. ἀλλ’ ἔστωσαν οἱ καὶ ἐπὶ τούτῳ συνόντες· ἢν δὲ μὴ ὦσιν, οἰκέται ἱκανοί. πολλὰ γὰρ καὶ ἐκ τοῦ τοιούτου πρὸς τὴν ῥητορικὴν χρήσιμα παραγίγνεται· πλείων ἡ ἀναισχυντία καὶ θράσος. ὁρᾷς ὡς λαλίστεραι αἱ γυναῖκες καὶ λοιδοροῦνται περιττῶς καὶ ὑπὲρ τοὺς ἄνδρας; εἰ δὴ τὰ ὅμοια πάσχοις, καὶ ταῦτα διοίσεις τῶν ἄλλων. καὶ μὴν καὶ πιττοῦσθαι χρή, μάλιστα μὲν τὰ πάντα, εἰ δὲ μή, πάντως ἐκεῖνα. καὶ αὐτὸ δέ σοι τὸ στόμα πρὸς ἅπαντα ὁμοίως κεχηνέτω, καὶ ἡ γλῶττα ὑπηρετείτω καὶ πρὸς τοὺς λόγους καὶ πρὸς τὰ ἄλλα ὁπόσα ἂν δύνηται. δύναται δὲ οὐ σολοικίζειν μόνον καὶ βαρβαρίζειν οὐδὲ ληρεῖν ἢ ἐπιορκεῖν ἢ λοιδορεῖσθαι ἢ διαβάλλειν καὶ ψεύδεσθαι, ἀλλὰ καὶ νύκτωρ τι ἄλλο ὑποτελεῖν, καὶ μάλιστα ἢν πρὸς οὕτω πολλοὺς τοὺς ἔρωτας μὴ διαρκέσῃς. πάντα αὐτή γε ἐπιστάσθω καὶ γονιμωτέρα γιγνέσθω καὶ μηδὲν ἀποστρεφέσθω.", "st": "37.23"}, {"sp": "N", "t": "ἢν ταῦτα, ὦ παῖ, καλῶς ἐκμάθῃς — δύνασαι δέ· οὐδὲν γὰρ ἐν αὐτοῖς βαρύ—θαρρῶν ἐπαγγέλλομαι οὐκ εἰς μακράν σε ἄριστον ῥήτορα καὶ ἡμῖν ὅμοιον ἀποτελεσθήσεσθαι. τὸ μετὰ τοῦτο δὲ οὐκ ἐμὲ χρὴ λέγειν, ὅσα ἐν βραχεῖ παρέσται σοι τὰ ἀγαθὰ παρὰ τῆς Ῥητορικῆς. ὁρᾷς ἐμέ, ὃς πατρὸς μὲν ἀφανοῦς καὶ οὐδὲ καθαρῶς ἐλευθέρου ἐγενόμην ὑπὲρ Ξόϊν καὶ Θμοῦιν δεδουλευκότος, μητρὸς δὲ ἀκεστρίας ἐπ’ ἀμφοδίου τινός. αὐτὸς δὲ τὴν ὥραν οὐ παντάπασιν ἀδόκιμος εἶναι δόξας τὸ μὲν πρῶτον ἐπὶ ψιλῷ τῷ τρέφεσθαι συνῆν τινι κακοδαίμονι καὶ γλίσχρῳ ἐραστῇ. ἐπεὶ δὲ τὴν ὁδὸν ταύτην ῥᾴστην οὖσαν κατεῖδον καὶ διεκπαίσας ἐπὶ τῷ ἄκρῳ ἐγενόμην — ὑπῆρχε γάρ μοι, ὦ φίλη Ἀδράστεια, πάντα ἐκεῖνα ἃ προεῖπον ἐφόδια, τὸ θράσος, ἡ ἀμαθία, ἡ ἀναισχυντία — πρῶτον μὲν οὐκέτι Ποθεινὸς ὀνομάζομαι, ἀλλ’ ἤδη τοῖς Διὸς καὶ Λήδας παισὶν ὁμώνυμος γεγένημαι. ἔπειτα δὲ γραῒ συνοικήσας τὸ πρῶτον μὲν ἐγαστριζόμην πρὸς αὐτῆς ἐρᾶν προσποιούμενος γυναικὸς ἑβδομηκοντούτιδος τέτταρας ἔτι λοιποὺς ὀδόντας ἐχούσης, χρυσίῳ καὶ τούτους ἐνδεδεμένους. πλὴν ἀλλά γε διὰ τὴν πενίαν ὑφιστάμην τὸν ἆθλον καὶ τὰ ψυχρὰ ἐκεῖνα τὰ ἐκ τῆς σοροῦ φιλήματα ὑπερήδιστά μοι ἐποίει ὁ λιμός. εἶτα ὀλίγου δεῖν κληρονόμος ὧν εἶχεν ἁπάντων κατέστην, εἰ μὴ κατάρατός τις οἰκέτης ἐμήνυσεν ὡς φάρμακον εἴην ἐπ’ αὐτὴν ἐωνημένος.", "st": "37.24"}, {"sp": "N", "t": "ἐξωσθεὶς δὲ ἐπὶ κεφαλὴν ὅμως οὐδὲ τότε ἠπόρησα τῶν ἀναγκαίων, ἀλλὰ καὶ ῥήτωρ δοκῶ κἀν ταῖς δίκαις ἐξετάζομαι προδιδοὺς τὰ πολλὰ καὶ τοὺς δικαστὰς τοῖς ἀνοήτοις καθυπισχνούμενος, καὶ ἡττῶμαι μὲν τὰ πλεῖστα, οἱ φοίνικες δὲ ἐπὶ τῇ θύρᾳ χλωροὶ καὶ ἐστεφανωμένοι· τούτοις γὰρ ἐπὶ τοὺς δυστυχεῖς χρῶμαι τοῖς δελέασιν. ἀλλὰ καὶ τὸ μισεῖσθαι πρὸς ἁπάντων καὶ ἐπίσημον εἶναί με ἐπὶ τῇ μοχθηρίᾳ τοῦ τρόπου καὶ πολὺ πρότερον τῶν λόγων καὶ τὸ δείκνυσθαι τῷ δακτύλῳ τοῦτον ἐκεῖνον τὸν ἀκρότατον ἐν πάσῃ κακίᾳ λεγόμενον, οὐ μικρὸν εἶναι ἐμοί γε δοκεῖ.", "st": "37.25"}, {"sp": "N", "t": "Ταῦτά σοι παραινῶ, νὴ τὴν πάνδημον, πολὺ πρότερον ἐμαυτῷ παραινέσας καὶ χάριν ἐμαυτῷ οὐ μικρὰν ἐπιστάμενος.", "st": "37.25"}, {"sp": "N", "t": "Εἶεν· ὁ μὲν γεννάδας εἰπὼν ταῦτα πεπαύσεται· σὺ δὲ ἢν πεισθῇς τοῖς εἰρημένοις, καὶ δὴ παρεῖναι νόμιζε οἷπερ ἐξ ἀρχῆς ἐπόθεις ἐλθεῖν, καὶ οὐδέν σε κωλύσει ἑπόμενον τοῖς νόμοις ἔν τε τοῖς δικαστηρίοις κρατεῖν καὶ ἐν τοῖς πλήθεσιν εὐδοκιμεῖν καὶ ἐπέραστον εἶναι καὶ γαμεῖν οὐ γραῦν τινα τῶν κωμικῶν, καθάπερ ὁ νομοθέτης καὶ διδάσκαλος, ἀλλὰ καλλίστην γυναῖκα τὴν Ῥητορικήν, ὡς τὸ τοῦ Πλάτωνος ἐκεῖνο πτηνὸν ἅρμα ἐλαύνοντα φέρεσθαι σοὶ μᾶλλον πρέπειν περὶ σεαυτοῦ εἰπεῖν ἢ ἐκείνῳ περὶ τοῦ Διός· ἐγὼ δὲ — ἀγεννὴς γὰρ καὶ δειλός εἰμι — ἐκστήσομαι τῆς ὁδοῦ ὑμῖν καὶ παύσομαι τῇ Ῥητορικῇ ἐπιπολάζων, ἀσύμβολος ὢν πρὸς αὐτὴν τὰ ὑμέτερα· μᾶλλον δὲ ἤδη πέπαυμαι, ὥστε ἀκονιτὶ ἀνακηρύττεσθε καὶ θαυμάζεσθε, μόνον τοῦτο μεμνημένοι, ὅτι μὴ τῷ τάχει ἡμῶν κεκρατήκατε ὠκύτεροι φανέντες, ἀλλὰ τῷ ῥᾴστην καὶ πρανῆ τραπέσθαι τὴν ὁδόν.", "st": "37.26"}, {"sp": "HDR", "t": "Ἀλέξανδρος ἢ Ψευδόμαντις"}, {"sp": "N", "t": "σὺ μὲν ἴσως, ὦ φίλτατε Κέλσε, μικρόν τι καὶ φαῦλον οἴει τὸ πρόσταγμα, προστάττειν τὸν Ἀλεξάνδρου σοι τοῦ Ἀβωνοτειχίτου γόητος βίον καὶ ἐπινοίας αὐτοῦ καὶ τολμήματα καὶ μαγγανείας εἰς βιβλίον ἐγγράψαντα πέμψαι· τὸ δέ, εἴ τις ἐθέλοι πρὸς τὸ ἀκριβὲς ἕκαστον ἐπεξιέναι, οὐ μεῖόν ἐστιν ἢ τὰς Ἀλεξάνδρου τοῦ Φιλίππου πράξεις ἀναγράψαι· τοσοῦτος εἰς κακίαν οὗτος, ὅσος εἰς ἀρετὴν ἐκεῖνος. ὅμως δὲ εἰ μετὰ συγγνώμης ἀναγνώσεσθαι μέλλοις καὶ τὰ ἐνδέοντα τοῖς ἱστορουμένοις προσλογιεῖσθαι, ὑποστήσομαί σοι τὸν ἆθλον, καὶ τὴν Αὐγέου βουστασίαν, εἰ καὶ μὴ πᾶσαν, ἀλλ’ εἰς δύναμίν γε τὴν ἐμαυτοῦ ἀνακαθάρασθαι πειράσομαι, ὀλίγους ὅσους τῶν κοφίνων ἐκφορήσας, ὡς ἀπ’ ἐκείνων τεκμαίροιο πόση πᾶσα καὶ ὡς ἀμύθητος ἦν ἡ κόπρος ἣν τρισχίλιοι βόες ἐν πολλοῖς ἔτεσιν ποιῆσαι ἐδύναντο.", "st": "38.1"}, {"sp": "N", "t": "αἰδοῦμαι μὲν οὖν ὑπὲρ ἀμφοῖν, ὑπέρ τε σοῦ καὶ ἐμαυτοῦ· σοῦ μέν, ἀξιοῦντος μνήμῃ καὶ γραφῇ παραδοθῆναι ἄνδρα τρισκατάρατον, ἐμαυτοῦ δέ, σπουδὴν ποιουμένου ἐπὶ τοιαύτῃ ἱστορίᾳ καὶ πράξεσιν ἀνθρώπου, ὃν οὐκ ἀναγιγνώσκεσθαι πρὸς τῶν πεπαιδευμένων ἦν ἄξιον, ἀλλ’ ἐν πανδήμῳ τινὶ μεγίστῳ θεάτρῳ ὁρᾶσθαι ὑπὸ πιθήκων ἢ ἀλωπέκων σπαραττόμενον. ἀλλ’ ἤν τις ἡμῖν ταύτην ἐπιφέρῃ τὴν αἰτίαν, ἕξομεν καὶ αὐτοὶ εἰς παράδειγμά τι τοιοῦτον ἀνενεγκεῖν. καὶ Ἀρριανὸς γὰρ ὁ τοῦ Ἐπικτήτου μαθητής, ἀνὴρ Ῥωμαίων ἐν τοῖς πρώτοις καὶ παιδείᾳ παρ’ ὅλον τὸν βίον συγγενόμενος, ὅμοιόν τι παθὼν ἀπολογήσαιτ’ ἂν καὶ ὑπὲρ ἡμῶν· Τιλλορόβου γοῦν τοῦ λῃστοῦ κἀκεῖνος βίον ἀναγράψαι ἠξίωσεν. ἡμεῖς δὲ πολὺ ὠμοτέρου λῃστοῦ μνήμην ποιησόμεθα, ὅσῳ μὴ ἐν ὕλαις καὶ ἐν ὄρεσιν, ἀλλ’ ἐν πόλεσιν οὗτος ἐλῄστευεν, οὐ Μυσίαν μόνην οὐδὲ τὴν Ἴδην κατατρέχων οὐδὲ ὀλίγα τῆς Ἀσίας μέρη τὰ ἐρημότερα λεηλατῶν, ἀλλὰ πᾶσαν ὡς εἰπεῖν τὴν Ῥωμαίων ἀρχὴν ἐμπλήσας τῆς λῃστείας τῆς αὑτοῦ.", "st": "38.2"}, {"sp": "N", "t": "πρότερον δέ σοι αὐτὸν ὑπογράψω τῷ λόγῳ πρὸς τὸ ὁμοιότατον εἰκάσας, ὡς ἂν δύνωμαι, καίτοι μὴ πάνυ γραφικός τις ὤν. τὸ γὰρ δὴ σῶμα, ἵνα σοι καὶ τοῦτο δείξω, μέγας τε ἦν καὶ καλὸς ἰδεῖν καὶ θεοπρεπὴς ὡς ἀληθῶς, λευκὸς τὴν χρόαν, τὸ γένειον οὐ πάνυ λάσιος, κόμην τὴν μὲν ἰδίαν, τὴν δὲ καὶ πρόσθετον ἐπικείμενος εὖ μάλα εἰκασμένην καὶ τοὺς πολλοὺς ὅτι ἦν ἀλλοτρία λεληθυῖαν· ὀφθαλμοὶ πολὺ τὸ γοργὸν καὶ ἔνθεον διεμφαίνοντες, φώνημα ἥδιστόν τε ἅμα καὶ λαμπρότατον· καὶ ὅλως οὐδαμόθεν μεμπτὸς ἦν ταῦτά γε.", "st": "38.3"}, {"sp": "N", "t": "τοιόσδε μὲν τὴν μορφήν· ἡ ψυχὴ δὲ καὶ ἡ γνώμη — ἀλεξίκακε Ἡράκλεις καὶ Ζεῦ ἀποτρόπαιε καὶ Διόσκουροι σωτῆρες, πολεμίοις καὶ ἐχθροῖς ἐντυχεῖν γένοιτο καὶ συγγενέσθαι τοιούτῳ τινί. συνέσει μὲν γὰρ καὶ ἀγχινοίᾳ καὶ δριμύτητι πάμπολυ τῶν ἄλλων διέφερεν, καὶ τό τε περίεργον καὶ εὐμαθὲς καὶ μνημονικὸν καὶ πρὸς τὰ μαθήματα εὐφυές, πάντα ταῦτα εἰς ὑπερβολὴν ἑκασταχοῦ ὑπῆρχεν αὐτῷ. ἐχρῆτο δὲ αὐτοῖς εἰς τὸ χείριστον, καὶ ὄργανα ταῦτα γενναῖα ὑποβεβλημένα ἔχων αὐτίκα μάλα τῶν ἐπὶ κακίᾳ διαβοήτων ἀκρότατος ἀπετελέσθη, ὑπὲρ τοὺς Κέρκωπας, ὑπὲρ τὸν Εὐρύβατον ἢ Φρυνώνδαν ἢ Ἀριστόδημον ἢ Σώστρατον. αὐτὸς μὲν γὰρ τῷ γαμβρῷ Ῥουτιλιανῷ ποτε γράφων καὶ τὰ μετριώτατα ὑπὲρ αὑτοῦ λέγων Πυθαγόρᾳ ὅμοιος εἶναι ἠξίου. ἀλλ’ ἵλεως μὲν ὁ Πυθαγόρας εἴη, σοφὸς ἀνὴρ καὶ τὴν γνώμην θεσπέσιος, εἰ δὲ κατὰ τοῦτον ἐγεγένητο, παῖς ἂν εὖ οἶδ’ ὅτι πρὸς αὐτὸν εἶναι ἔδοξε. καὶ πρὸς Χαρίτων μή με νομίσῃς ἐφ’ ὕβρει ταῦτα τοῦ Πυθαγόρου λέγειν ἢ συνάπτειν πειρώμενον αὐτοὺς πρὸς ὁμοιότητα τῶν πράξεων· ἀλλ’ εἴ τις τὰ χείριστα καὶ βλασφημότατα τῶν ἐπὶ διαβολῇ περὶ τοῦ Πυθαγόρου λεγομένων, οἷς ἔγωγε οὐκ ἂν πεισθείην ὡς ἀληθέσιν οὖσιν, ὅμως συναγάγοι εἰς τὸ αὐτό, πολλοστὸν ἂν μέρος ἅπαντα ἐκεῖνα γένοιτο τῆς Ἀλεξάνδρου δεινότητος. ὅλως γὰρ ἐπινόησόν μοι καὶ τῷ λογισμῷ διατύπωσον ποικιλωτάτην τινὰ ψυχῆς κρᾶσιν ἐκ ψεύδους καὶ δόλων καὶ ἐπιορκιῶν καὶ κακοτεχνιῶν συγκειμένην, ῥᾳδίαν, τολμηράν, παράβολον, φιλόπονον ἐξεργάσασθαι τὰ νοηθέντα, καὶ πιθανὴν καὶ ἀξιόπιστον καὶ ὑποκριτικὴν τοῦ βελτίονος καὶ τῷ ἐναντιωτάτῳ τῆς βουλήσεως ἐοικυῖαν. οὐδεὶς γοῦν τὸ πρῶτον ἐντυχὼν οὐκ ἀπῆλθε δόξαν λαβὼν ὑπὲρ αὐτοῦ ὡς εἴη πάντων ἀνθρώπων χρηστότατος καὶ ἐπιεικέστατος καὶ προσέτι ἁπλοϊκώτατός τε καὶ ἀφελέστατος. ἐπὶ πᾶσι δὲ τούτοις τὸ μεγαλουργὸν προσῆν καὶ τὸ μηδὲν μικρὸν ἐπινοεῖν, ἀλλ’ ἀεὶ τοῖς μεγίστοις ἐπέχειν τὸν νοῦν.", "st": "38.4"}, {"sp": "N", "t": "μειράκιον μὲν οὖν ἔτι ὢν πάνυ ὡραῖον, ὡς ἐνῆν ἀπὸ τῆς καλάμης τεκμαίρεσθαι καὶ ἀκούειν τῶν διηγουμένων, ἀνέδην ἐπόρνευε καὶ συνῆν ἐπὶ μισθῷ τοῖς δεομένοις. ἐν δὲ τοῖς ἄλλοις λαμβάνει τις αὐτὸν ἐραστὴς γόης τῶν μαγείας καὶ ἐπῳδὰς θεσπεσίους ὑπισχνουμένων καὶ χάριτας ἐπὶ τοῖς ἐρωτικοῖς καὶ ἐπαγωγὰς τοῖς ἐχθροῖς καὶ θησαυρῶν ἀναπομπὰς καὶ κλήρων διαδοχάς. οὗτος ἰδὼν εὐφυᾶ παῖδα καὶ πρὸς ὑπηρεσίαν τῶν ἑαυτοῦ πράξεων ἑτοιμότατον, οὐ μεῖον ἐρῶντα τῆς κακίας τῆς αὐτοῦ ἢ αὐτὸς τῆς ὥρας τῆς ἐκείνου, ἐξεπαίδευσέ τε αὐτὸν καὶ διετέλει ὑπουργῷ καὶ ὑπηρέτῃ καὶ διακόνῳ χρώμενος. ὁ δ’ αὐτὸς ἐκεῖνος δημοσίᾳ μὲν ἰατρὸς δῆθεν ἦν, ἠπίστατο δὲ κατὰ τὴν Θῶνος τοῦ Αἰγυπτίου γυναῖκα<br>φάρμακα πολλὰ μὲν ἐσθλὰ μεμιγμένα, πολλὰ δὲ λυγρά·<br>ὧν ἁπάντων κληρονόμος καὶ διάδοχος οὗτος ἐγένετο. ἦν δὲ ὁ διδάσκαλος ἐκεῖνος καὶ ἐραστὴς τὸ γένος Τυανεύς, τῶν Ἀπολλωνίῳ τῷ πάνυ συγγενομένων καὶ τὴν πᾶσαν αὐτοῦ τραγῳδίαν εἰδότων. ὁρᾷς ἐξ οἵας σοι διατριβῆς ἄνθρωπον λέγω.", "st": "38.5"}, {"sp": "N", "t": "ἤδη δὲ πώγωνος ὁ Ἀλέξανδρος πιμπλάμενος καὶ τοῦ Τυανέως ἐκείνου ἀποθανόντος ἐν ἀπορίᾳ καθεστώς, ἀπηνθηκυίας ἅμα τῆς ὥρας, ἀφ’ ἧς τρέφεσθαι ἐδύνατο, οὐκέτι μικρὸν οὐδὲν ἐπενόει, ἀλλὰ κοινωνήσας Βυζαντίῳ τινὶ χορογράφῳ τῶν καθιέντων εἰς τοὺς ἀγῶνας, πολὺ καταρατοτέρῳ τὴν φύσιν — Κοκκωνᾶς δέ, οἶμαι, ἐπεκαλεῖτο — περιῄεσαν γοητεύοντες καὶ μαγγανεύοντες καὶ τοὺς παχεῖς τῶν ἀνθρώπων — οὕτως γὰρ αὐτοὶ τῇ πατρίῳ τῶν μάγων φωνῇ τοὺς πολλοὺς ὀνομάζουσιν — ἀποκείροντες. ἐν δὴ τούτοις καὶ Μακέτιν γυναῖκα πλουσίαν, ἔξωρον μέν, ἐράσμιον δὲ ἔτι εἶναι βουλομένην, ἐξευρόντες ἐπεσιτίσαντό τε τὰ ἀρκοῦντα παρ’ αὐτῆς καὶ ἠκολούθησαν ἐκ τῆς Βιθυνίας εἰς τὴν Μακεδονίαν. Πελλαία δὲ ἦν ἐκείνη, πάλαι μὲν εὐδαίμονος χωρίου κατὰ τοὺς τῶν Μακεδόνων βασιλέας, νῦν δὲ ταπεινοῦ καὶ ὀλιγίστους οἰκήτορας ἔχοντος.", "st": "38.6"}, {"sp": "N", "t": "ἐνταῦθα ἰδόντες δράκοντας παμμεγέθεις, ἡμέρους πάνυ καὶ τιθασούς, ὡς καὶ ὑπὸ γυναικῶν τρέφεσθαι καὶ παιδίοις συγκαθεύδειν καὶ πατουμένους ἀνέχεσθαι καὶ θλιβομένους μὴ ἀγανακτεῖν καὶ γάλα πίνειν ἀπὸ θηλῆς κατὰ ταὐτὰ τοῖς βρέφεσι — πολλοὶ δὲ γίγνονται παρ’ αὐτοῖς τοιοῦτοι, ὅθεν καὶ τὸν περὶ τῆς Ὀλυμπιάδος μῦθον διαφοιτῆσαι πάλαι εἰκός, ὁπότε ἐκύει τὸν Ἀλέξανδρον, δράκοντός τινος, οἶμαι, τοιούτου συγκαθεύδοντος αὐτῇ — ὠνοῦνται τῶν ἑρπετῶν ἓν κάλλιστον ὀλίγων ὀβολῶν.", "st": "38.7"}, {"sp": "N", "t": "καὶ κατὰ τὸν Θουκυδίδην ἄρχεται ὁ πόλεμος ἐνθένδε ἤδη.", "st": "38.8"}, {"sp": "N", "t": "ὡς γὰρ ἂν δύο κάκιστοι καὶ μεγαλότολμοι καὶ πρὸς τὸ κακουργεῖν προχειρότατοι εἰς τὸ αὐτὸ συνελθόντες, ῥᾳδίως κατενόησαν τὸν τῶν ἀνθρώπων βίον ὑπὸ δυοῖν τούτοιν μεγίστοιν τυραννούμενον, ἐλπίδος καὶ φόβου, καὶ ὅτι ὁ τούτων ἑκατέρῳ εἰς δέον χρήσασθαι δυνάμενος τάχιστα πλουτήσειεν ἄν· ἀμφοτέροις γάρ, τῷ τε δεδιότι καὶ τῷ ἐλπίζοντι, ἑώρων τὴν πρόγνωσιν ἀναγκαιοτάτην τε καὶ ποθεινοτάτην οὖσαν, καὶ Δελφοὺς οὕτω πάλαι πλουτῆσαι καὶ ἀοιδίμους γενέσθαι καὶ Δῆλον καὶ Κλάρον καὶ Βραγχίδας, τῶν ἀνθρώπων ἀεὶ δι’ οὓς προεῖπον τυράννους, τὴν ἐλπίδα καὶ τὸν φόβον, φοιτώντων εἰς τὰ ἱερὰ καὶ προμαθεῖν τὰ μέλλοντα δεομένων, καὶ δι’ αὐτὸ ἑκατόμβας θυόντων καὶ χρυσᾶς πλίνθους ἀνατιθέντων. ταῦτα πρὸς ἀλλήλους στρέφοντες καὶ κυκῶντες μαντεῖον συστήσασθαι καὶ χρηστήριον ἐβουλεύοντο· εἰ γὰρ τοῦτο προχωρήσειεν αὐτοῖς, αὐτίκα πλούσιοί τε καὶ εὐδαίμονες ἔσεσθαι ἤλπιζον — ὅπερ ἐπὶ μεῖζον ἢ κατὰ τὴν πρώτην προσδοκίαν ἀπήντησεν αὐτοῖς καὶ κρεῖττον διεφάνη τῆς ἐλπίδος.", "st": "38.8"}, {"sp": "N", "t": "τοὐντεῦθεν τὴν σκέψιν ἐποιοῦντο, πρῶτον μὲν περὶ τοῦ χωρίου, δεύτερον δὲ ἥτις ἡ ἀρχὴ καὶ ὁ τρόπος ἂν γένοιτο τῆς ἐπιχειρήσεως. ὁ μὲν οὖν Κοκκωνᾶς τὴν Καλχηδόνα ἐδοκίμαζεν ἐπιτήδειον εἶναι καὶ εὔκαιρον χωρίον, τῇ τε Θρᾴκῃ καὶ τῇ Βιθυνίᾳ πρόσοικον, οὐχ ἑκὰς οὐδὲ τῆς Ἀσίας καὶ Γαλατίας καὶ τῶν ὑπερκειμένων ἐθνῶν ἁπάντων· ὁ δὲ Ἀλέξανδρος ἔμπαλιν τὰ οἴκοι προὔκρινεν, λέγων ὅπερ ἀληθὲς ἦν, πρὸς τὴν τῶν τοιούτων ἀρχὴν καὶ ἐπιχείρησιν ἀνθρώπων δεῖν παχέων καὶ ἠλιθίων τῶν ὑποδεξομένων, οἵους τοὺς Παφλαγόνας εἶναι ἔφασκεν ὑπεροικοῦντας τὸ τοῦ Ἀβώνου τεῖχος, δεισιδαίμονας τοὺς πολλοὺς καὶ πλουσίους, καὶ μόνον εἰ φανείη τις αὐλητὴν ἢ τυμπανιστὴν ἢ κυμβάλοις κροτοῦντα ἐπαγόμενος, κοσκίνῳ τὸ τοῦ λόγου μαντευόμενος, αὐτίκα μάλα πάντας κεχηνότας πρὸς αὐτὸν καὶ ὥσπερ τινὰ τῶν ἐπουρανίων προσβλέποντας.", "st": "38.9"}, {"sp": "N", "t": "οὐκ ὀλίγης δὲ τῆς περὶ τοῦτο στάσεως αὐτοῖς γενομένης τέλος ἐνίκησεν ὁ Ἀλέξανδρος, καὶ ἀφικόμενοι εἰς τὴν Χαλκηδόνα — χρήσιμον γάρ τι ὅμως ἡ πόλις αὐτοῖς ἔχειν ἔδοξε — ἐν τῷ Ἀπόλλωνος ἱερῷ, ὅπερ ἀρχαιότατόν ἐστι τοῖς Χαλκηδονίοις, κατορύττουσι δέλτους χαλκᾶς, λεγούσας ὡς αὐτίκα μάλα ὁ Ἀσκληπιὸς σὺν τῷ πατρὶ Ἀπόλλωνι μέτεισιν εἰς τὸν Πόντον καὶ καθέξει τὸ τοῦ Ἀβώνου τεῖχος. αὗται αἱ δέλτοι ἐξεπίτηδες εὑρεθεῖσαι διαφοιτῆσαι ῥᾳδίως τὸν λόγον τοῦτον εἰς πᾶσαν τὴν Βιθυνίαν καὶ τὸν Πόντον ἐποίησαν, καὶ πολὺ πρὸ τῶν ἄλλων εἰς τὸ τοῦ Ἀβώνου τεῖχος· κἀκεῖνοι γὰρ καὶ νεὼν αὐτίκα ἐψηφίσαντο ἐγεῖραι καὶ τοὺς θεμελίους ἤδη ἔσκαπτον. κἀνταῦθα ὁ μὲν Κοκκωνᾶς ἐν Χαλκηδόνι καταλείπεται, διττούς τινας καὶ ἀμφιβόλους καὶ λοξοὺς χρησμοὺς συγγράφων, καὶ μετ’ ὀλίγον ἐτελεύτησε τὸν βίον, ὑπὸ ἐχίδνης, οἶμαι, δηχθείς.", "st": "38.10"}, {"sp": "N", "t": "προεισπέμπεται δὲ ὁ Ἀλέξανδρος, κομῶν ἤδη καὶ πλοκάμους καθειμένος καὶ μεσόλευκον χιτῶνα πορφυροῦν ἐνδεδυκὼς καὶ ἱμάτιον ὑπὲρ αὐτοῦ λευκὸν ἀναβεβλημένος, ἅρπην ἔχων κατὰ τὸν Περσέα, ἀφ’ οὗ ἑαυτὸν ἐγενεαλόγει μητρόθεν· καὶ οἱ ὄλεθροι ἐκεῖνοι Παφλαγόνες, εἰδότες αὐτοῦ ἄμφω τοὺς γονέας ἀφανεῖς καὶ ταπεινούς, ἐπίστευον τῷ χρησμῷ λέγοντι<br>Περσείδης γενεὴν Φοίβῳ φίλος οὗτος ὁρᾶται,<br>δῖος Ἀλέξανδρος, Ποδαλειρίου αἷμα λελογχώς.<br>οὕτως ἄρα ὁ Ποδαλείριος μάχλος καὶ γυναικομανὴς τὴν φύσιν, ὡς ἀπὸ Τρίκκης μέχρι Παφλαγονίας στύεσθαι ἐπὶ τὴν Ἀλεξάνδρου μητέρα.", "st": "38.11"}, {"sp": "N", "t": "εὕρητο δὲ χρησμὸς ἤδη, ὡς Σιβύλλης προμαντευσαμένης·<br>Εὐξείνου Πόντοιο παρ’ ᾐόσιν ἄγχι Σινώπης<br>ἔσται τις κατὰ Τύρσιν ὑπ’ Αὐσονίοισι προφήτης,<br>ἐκ πρώτης δεικνὺς μονάδος τρισσῶν δεκάδων τε<br>πένθ’ ἑτέρας μονάδας καὶ εἰκοσάδα τρισάριθμον,<br>ἀνδρὸς ἀλεξητῆρος ὁμωνυμίην τετράκυκλον.", "st": "38.11"}, {"sp": "N", "t": "εἰσβαλὼν οὖν ὁ Ἀλέξανδρος μετὰ τοιαύτης τραγῳδίας διὰ πολλοῦ εἰς τὴν πατρίδα περίβλεπτός τε καὶ λαμπρὸς ἦν, μεμηνέναι προσποιούμενος ἐνίοτε καὶ ἀφροῦ ὑποπιμπλάμενος τὸ στόμα· ῥᾳδίως δὲ τοῦτο ὑπῆρχεν αὐτῷ, στρουθίου τῆς βαφικῆς βοτάνης τὴν ῥίζαν διαμασησαμένῳ· τοῖς δὲ θεῖόν τι καὶ φοβερὸν ἐδόκει καὶ ὁ ἀφρός. ἐπεποίητο δὲ αὐτοῖς πάλαι καὶ κατεσκεύαστο κεφαλὴ δράκοντος ὀθονίνη ἀνθρωπόμορφόν τι ἐπιφαίνουσα, κατάγραφος, πάνυ εἰκασμένη, ὑπὸ θριξὶν ἱππείαις ἀνοίγουσά τε καὶ αὖθις ἐπικλείουσα τὸ στόμα·, καὶ γλῶττα οἵα δράκοντος διττὴ μέλαινα προέκυπτεν, ὑπὸ τριχῶν καὶ αὐτὴ ἑλκομένη. καὶ ὁ Πελλαῖος δὲ δράκων προϋπῆρχεν καὶ οἴκοι ἐτρέφετο, κατὰ καιρὸν ἐπιφανησόμενος αὐτοῖς καὶ συντραγῳδήσων, μᾶλλον δὲ πρωταγωνιστὴς ἐσόμενος.", "st": "38.12"}, {"sp": "N", "t": "ἤδη δὲ ἄρχεσθαι δέον, μηχανᾶται τοιόνδε τι· νύκτωρ γὰρ ἐλθὼν ἐπὶ τοὺς θεμελίους τοῦ νεὼ τοὺς ἄρτι ὀρυττομένους — συνειστήκει δὲ ἐν αὐτοῖς ὕδωρ ἢ αὐτόθεν ποθὲν συλλειβόμενον ἢ ἐξ οὐρανοῦ πεσόν — ἐνταῦθα κατατίθεται χήνειον ᾠὸν προκεκενωμένον, ἔνδον φυλάττον ἑρπετόν τι ἀρτιγέννητον, καὶ βυθίσας τοῦτο ἐν μυχῷ τοῦ πηλοῦ ὀπίσω αὖθις ἀπηλλάττετο. ἕωθεν δὲ γυμνὸς εἰς τὴν ἀγορὰν προπηδήσας, διάζωμα περὶ τὸ αἰδοῖον ἔχων, κατάχρυσον καὶ τοῦτο, καὶ τὴν ἅρπην ἐκείνην φέρων, σείων ἅμα τὴν κόμην ἄνετον ὥσπερ οἱ τῇ μητρὶ ἀγείροντές τε καὶ ἐνθεαζόμενοι, ἐδημηγόρει ἐπὶ βωμόν τινα ὑψηλὸν ἀναβὰς καὶ τὴν πόλιν ἐμακάριζεν αὐτίκα μάλα δεξομένην ἐναργῆ τὸν θεόν. οἱ παρόντες δέ — συνδεδραμήκει γὰρ σχεδὸν ἅπασα ἡ πόλις ἅμα γυναιξὶ καὶ γέρουσι καὶ παιδίοις — ἐτεθήπεσαν καὶ εὔχοντο καὶ προσεκύνουν. ὁ δὲ φωνάς τινας ἀσήμους φθεγγόμενος, οἷαι γένοιντο ἂν Ἑβραίων ἢ Φοινίκων, ἐξέπληττε τοὺς ἀνθρώπους οὐκ εἰδότας ὅ τι καὶ λέγοι, πλὴν τοῦτο μόνον, ὅτι πᾶσιν ἐγκατεμίγνυ τὸν Ἀπόλλω καὶ τὸν Ἀσκληπιόν.", "st": "38.13"}, {"sp": "N", "t": "εἶτ’ ἔθει δρόμῳ ἐπὶ τὸν ἐσόμενον νεών· καὶ ἐπὶ τὸ ὄρυγμα ἐλθὼν καὶ τὴν προῳκονομημένην τοῦ χρηστηρίου πηγήν, ἐμβὰς εἰς τὸ ὕδωρ ὕμνους τε ᾖδεν Ἀσκληπιοῦ καὶ Ἀπόλλωνος μεγάλῃ τῇ φωνῇ καὶ ἐκάλει τὸν θεὸν ἥκειν τύχῃ τῇ ἀγαθῇ εἰς τὴν πόλιν. εἶτα φιάλην αἰτήσας, ἀναδόντος τινός, ῥᾳδίως ὑποβαλὼν ἀνιμᾶται μετὰ τοῦ ὕδατος καὶ τοῦ πηλοῦ τὸ ᾠὸν ἐκεῖνο ἐν ᾧ ὁ θεὸς αὐτῷ κατεκέκλειστο, κηρῷ λευκῷ καὶ ψιμυθίῳ τὴν ἁρμογὴν τοῦ πώματος συγκεκολλημένον· καὶ λαβὼν αὐτὸ εἰς τὰς χεῖρας ἔχειν ἔφασκεν ἤδη τὸν Ἀσκληπιόν. οἱ δὲ ἀπενὲς ἀπέβλεπον ὅ τι καὶ γίγνοιτο, πολὺ πρότερον θαυμάσαντες τὸ ᾠὸν ἐν τῷ ὕδατι εὑρημένον. ἐπεὶ δὲ καὶ κατάξας αὐτὸ εἰς κοίλην τὴν χεῖρα ὑπεδέξατο τὸ τοῦ ἑρπετοῦ ἐκείνου ἔμβρυον καὶ οἱ παρόντες εἶδον κινούμενον καὶ περὶ τοῖς δακτύλοις εἰλούμενον, ἀνέκραγον εὐθὺς καὶ ἠσπάζοντο τὸν θεὸν καὶ τὴν πόλιν ἐμακάριζον καὶ χανδὸν ἕκαστος ἐνεπίμπλατο τῶν εὐχῶν, θησαυροὺς καὶ πλούτους καὶ ὑγιείας καὶ τὰ ἄλλα ἀγαθὰ αἰτῶν παρ’ αὐτοῦ. ὁ δὲ δρομαῖος αὖθις ἐπὶ τὴν οἰκίαν ἵετο φέρων ἅμα καὶ τὸν ἀρτιγέννητον Ἀσκληπιόν, “δὶς τεχθέντα, ὅτε ἄλλοι ἅπαξ τίκτοντ’ ἄνθρωποι,” οὐκ ἐκ Κορωνίδος μὰ Δί’ οὐδέ γε κορώνης, ἀλλ’ ἐκ χηνὸς γεγεννημένον. ὁ δὲ λεὼς ἅπας ἠκολούθει, πάντες ἔνθεοι καὶ μεμηνότες ὑπὸ τῶν ἐλπίδων.", "st": "38.14"}, {"sp": "N", "t": "ἡμέρας μὲν οὖν τινας οἴκοι ἔμεινεν ἐλπίζων ὅπερ ἦν, ὑπὸ τῆς φήμης αὐτίκα μάλα παμπόλλους τῶν Παφλαγόνων συνδραμεῖσθαι. ἐπεὶ δὲ ὑπερεπέπληστο ἀνθρώπων ἡ πόλις, ἁπάντων τοὺς ἐγκεφάλους καὶ τὰς καρδίας προεξῃρημένων οὐδὲν ἐοικότων σιτοφάγοις ἀνδράσιν, ἀλλὰ μόνῃ τῇ μορφῇ μὴ οὐχὶ πρόβατα εἶναι διαφερόντων, ἐν οἰκίσκῳ τινὶ ἐπὶ κλίνης καθεζόμενος μάλα θεοπρεπῶς ἐσταλμένος ἐλάμβανεν εἰς τὸν κόλπον τὸν Πελλαῖον ἐκεῖνον Ἀσκληπιόν, μέγιστόν τε καὶ κάλλιστον, ὡς ἔφην, ὄντα, καὶ ὅλον τῷ αὑτοῦ τραχήλῳ περιειλήσας καὶ τὴν οὐρὰν ἔξω ἀφείς — πολὺς δὲ ἦν — ἐν τῷ προκολπίῳ προκεχύσθαι αὐτοῦ καὶ χαμαὶ τὸ μέρος ἐπισύρεσθαι, μόνην τὴν κεφαλὴν ὑπὸ μάλης ἔχων καὶ ἀποκρύπτων, ἀνεχομένου πάντα ἐκείνου, προὔφαινεν τὴν ὀθονίνην κεφαλὴν κατὰ θάτερον τοῦ πώγωνος, ὡς δῆθεν ἐκείνου τοῦ φαινομένου πάντως οὖσαν.", "st": "38.15"}, {"sp": "N", "t": "εἶτά μοι ἐπινόησον οἰκίσκον οὐ πάνυ φαιδρὸν οὐδὲ εἰς κόρον τοῦ φωτὸς δεχόμενον καὶ πλῆθος ἀνθρώπων συγκλύδων, τεταραγμένων καὶ προεκπεπληγμένων καὶ ταῖς ἐλπίσιν ἐπαιωρουμένων, οἷς εἰσελθοῦσι τεράστιον ὡς εἰκὸς τὸ πρᾶγμα ἐφαίνετο, ἐκ τοῦ τέως μικροῦ ἑρπετοῦ ἐντὸς ἡμερῶν ὀλίγων τοσοῦτον δράκοντα πεφηνέναι, ἀνθρωπόμορφον καὶ ταῦτα καὶ τιθασόν. ἠπείγοντο δὲ αὐτίκα πρὸς τὴν ἔξοδον, καὶ πρὶν ἀκριβῶς ἰδεῖν, ἐξηλαύνοντο ὑπὸ τῶν ἀεὶ ἐπεισιόντων· ἐτετρύπητο δὲ κατὰ τὸ ἀντίθυρον ἄλλη ἔξοδος. οἷόν τι καὶ τοὺς Μακεδόνας ἐν Βαβυλῶνι ποιῆσαι ἐπ’ Ἀλεξάνδρῳ νοσοῦντι λόγος, ὅτε ὁ μὲν ἤδη πονήρως εἶχεν, οἱ δὲ περιστάντες τὰ βασίλεια ἐπόθουν ἰδεῖν αὐτὸν καὶ προσειπεῖν τὸ ὕστατον. τὴν δὲ ἐπίδειξιν ταύτην οὐχ ἅπαξ ὁ μιαρός, ἀλλὰ πολλάκις ποιῆσαι λέγεται, καὶ μάλιστα εἴ τινες τῶν πλουσίων ἀφίκοιντο νεαλέστεροι.", "st": "38.16"}, {"sp": "N", "t": "ἐνταῦθα, ὦ φίλε Κέλσε, εἰ δεῖ τἀληθῆ λέγειν, συγγνώμην χρὴ ἀπονέμειν τοῖς Παφλαγόσι καὶ Ποντικοῖς ἐκείνοις, παχέσι καὶ ἀπαιδεύτοις ἀνθρώποις, εἰ ἐξηπατήθησαν ἁπτόμενοι τοῦ δράκοντος — καὶ γὰρ τοῦτο παρεῖχεν τοῖς βουλομένοις ὁ Ἀλέξανδρος — ὁρῶντές τε ἐν ἀμυδρῷ τῷ φωτὶ τὴν κεφαλὴν δῆθεν αὐτοῦ ἀνοίγουσάν τε καὶ συγκλείουσαν τὸ στόμα, ὥστε πάνυ τὸ μηχάνημα ἐδεῖτο Δημοκρίτου τινὸς ἢ καὶ αὐτοῦ Ἐπικούρου ἢ Μητροδώρου ἤ τινος ἄλλου ἀδαμαντίνην πρὸς τὰ τοιαῦτα τὴν γνώμην ἔχοντος, ὡς ἀπιστῆσαι καὶ ὅπερ ἦν εἰκάσαι, καὶ εἰ μὴ εὑρεῖν τὸν τρόπον ἐδύνατο, ἐκεῖνο γοῦν προπεπεισμένου, ὅτι λέληθεν αὐτὸν ὁ τρόπος τῆς μαγγανείας, τὸ δ’ οὖν πᾶν ψεῦδός ἐστι καὶ γενέσθαι ἀδύνατον.", "st": "38.17"}, {"sp": "N", "t": "κατ’ ὀλίγον οὖν καὶ ἡ Βιθυνία καὶ ἡ Γαλατία καὶ ἡ Θρᾴκη συνέρρει, ἑκάστου τῶν ἀπαγγελλόντων κατὰ τὸ εἰκὸς λέγοντος ὡς καὶ γεννώμενον ἴδοι τὸν θεὸν καὶ ὕστερον ἅψαιτο μετ’ ὀλίγον παμμεγέθους αὐτοῦ γεγενημένου καὶ τὸ πρόσωπον ἀνθρώπῳ ἐοικότος. γραφαί τε ἐπὶ τούτῳ καὶ εἰκόνες καὶ ξόανα, τὰ μὲν ἐκ χαλκοῦ, τὰ δὲ ἐξ ἀργύρου εἰκασμένα, καὶ ὄνομά γε τῷ θεῷ ἐπιτεθέν· Γλύκων γὰρ ἐκαλεῖτο ἔκ τινος ἐμμέτρου καὶ θείου προστάγματος. ἀνεφώνησε γὰρ ὁ Ἀλέξανδρος<br>Εἰμὶ Γλύκων, τρίτον αἷμα Διός, φάος ἀνθρώποισιν.", "st": "38.18"}, {"sp": "N", "t": "καὶ ἐπειδὴ καιρὸς ἦν, οὗπερ ἕνεκα τὰ πάντα ἐμεμηχάνητο, καὶ χρᾶν τοῖς δεομένοις καὶ θεσπίζειν, παρ’ Ἀμφιλόχου τοῦ ἐν Κιλικίᾳ τὸ ἐνδόσιμον λαβών — καὶ γὰρ ἐκεῖνος, μετὰ τὴν τοῦ πατρὸς τελευτὴν τοῦ Ἀμφιάρεω καὶ τὸν ἐν Θήβαις ἀφανισμὸν αὐτοῦ ἐκπεσὼν τῆς οἰκείας εἰς τὴν Κιλικίαν ἀφικόμενος, οὐ πονήρως ἀπήλλαξεν, προθεσπίζων καὶ αὐτὸς τοῖς Κίλιξι τὰ μέλλοντα καὶ δύ’ ὀβολοὺς ἐφ’ ἑκάστῳ χρησμῷ λαμβάνων — ἐκεῖθεν οὖν τὸ ἐνδόσιμον λαβὼν ὁ Ἀλέξανδρος προλέγει πᾶσι τοῖς ἀφικομένοις ὡς μαντεύσεται ὁ θεός, ῥητήν τινα ἡμέραν προειπών. ἐκέλευσεν δὲ ἕκαστον, οὗ δέοιτο ἂν καὶ ὃ μάλιστα μαθεῖν ἐθέλοι, εἰς βιβλίον ἐγγράψαντα καταρράψαι τε καὶ κατασημήνασθαι κηρῷ ἢ πηλῷ ἢ ἄλλῳ τοιούτῳ. αὐτὸς δὲ λαβὼν τὰ βιβλία καὶ εἰς τὸ ἄδυτον κατελθὼν — ἤδη γὰρ ὁ νεὼς ἐγήγερτο καὶ ἡ σκηνὴ παρεσκεύαστο — καλέσειν ἔμελλε κατὰ τάξιν τοὺς δεδωκότας ὑπὸ κήρυκι καὶ θεολόγῳ, καὶ παρὰ τοῦ θεοῦ ἀκούων ἕκαστα τὸ μὲν βιβλίον ἀποδώσειν σεσημασμένον ὡς εἶχε, τὴν δὲ πρὸς αὐτὸ ἀπόκρισιν ὑπογεγραμμένην, πρὸς ἔπος ἀμειβομένου τοῦ θεοῦ περὶ ὅτου τις ἔροιτο.", "st": "38.19"}, {"sp": "N", "t": "ἦν δὲ τὸ μηχάνημα τοῦτο ἀνδρὶ μὲν οἵῳ σοί, εἰ δὲ μὴ φορτικὸν εἰπεῖν, καὶ οἵῳ ἐμοί, πρόδηλον καὶ γνῶναι ῥᾴδιον, τοῖς δὲ ἰδιώταις καὶ κορύζης μεστοῖς τὴν ῥῖνα τεράστιον καὶ πάνυ ἀπίστῳ ὅμοιον. ἐπινοήσας γὰρ ποικίλας τῶν σφραγίδων τὰς λύσεις ἀνεγίγνωσκέν τε τὰς ἐρωτήσεις ἑκάστας καὶ τὰ δοκοῦντα πρὸς αὐτὰς ἀπεκρίνετο, εἶτα κατειλήσας αὖθις καὶ σημηνάμενος ἀπεδίδου μετὰ πολλοῦ θαύματος τοῖς λαμβάνουσιν. καὶ πολὺ ἦν παρ’ αὐτοῖς τὸ “πόθεν γὰρ οὗτος ἠπίστατο ἃ ἐγὼ πάνυ ἀσφαλῶς σημηνάμενος αὐτῷ ἔδωκα ὑπὸ σφραγῖσιν δυσμιμήτοις, εἰ μὴ θεός τις ὡς ἀληθῶς ὁ πάντα γιγνώσκων ἦν·”", "st": "38.20"}, {"sp": "N", "t": "τίνες οὖν αἱ ἐπίνοιαι, ἴσως γὰρ ἐρήσῃ με. ἄκουε τοίνυν, ὡς ἔχοις ἐλέγχειν τὰ τοιαῦτα. ἡ πρώτη μὲν ἐκείνη, ὦ φίλτατε Κέλσε· βελόνην πυρώσας τὸ ὑπὸ τὴν σφραγῖδα μέρος τοῦ κηροῦ διατήκων ἐξῄρει καὶ μετὰ τὴν ἀνάγνωσιν τῇ βελόνῃ αὖθις ἐπιχλιάνας τὸν κηρόν, τόν τε κάτω ὑπὸ τῷ λίνῳ καὶ τὸν αὐτὴν τὴν σφραγῖδα ἔχοντα, ῥᾳδίως συνεκόλλα. ἕτερος δὲ τρόπος ὁ διὰ τοῦ λεγομένου κολλυρίου· σκευαστὸν δὲ τοῦτό ἐστιν ἐκ πίττης Βρεττίας καὶ ἀσφάλτου καὶ λίθου τοῦ διαφανοῦς τετριμμένου καὶ κηροῦ καὶ μαστίχης. ἐκ γὰρ τούτων ἁπάντων ἀναπλάσας τὸ κολλύριον καὶ θερμήνας πυρί, σιάλῳ τὴν σφραγῖδα προχρίσας ἐπετίθει καὶ ἀπέματτε τὸν τύπον. εἶτα αὐτίκα ξηροῦ ἐκείνου γενομένου, λύσας ῥᾳδίως καὶ ἀναγνούς, ἐπιθεὶς τὸν κηρὸν ἀπετύπου ὥσπερ ἐκ λίθου τὴν σφραγῖδα εὖ μάλα τῷ ἀρχετύπῳ ἐοικυῖαν. τρίτον ἄλλο πρὸς τούτοις ἄκουσον· τιτάνου γὰρ εἰς κόλλαν ἐμβαλὼν ᾗ κολλῶσι τὰ βιβλία, καὶ κηρὸν ἐκ τούτου ποιήσας, ἔτι ὑγρὸν ὄντα ἐπετίθει τῇ σφραγῖδι καὶ ἀφελών — αὐτίκα δὲ ξηρὸν γίγνεται καὶ κέρατος, μᾶλλον δὲ σιδήρου παγιώτερον — τούτῳ ἐχρῆτο πρὸς τὸν τύπον. ἔστι δὲ καὶ ἄλλα πολλὰ πρὸς τοῦτο ἐπινενοημένα, ὧν οὐκ ἀναγκαῖον μεμνῆσθαι ἁπάντων, ὡς μὴ ἀπειρόκαλοι εἶναι δοκοίημεν, καὶ μάλιστα σοῦ ἐν οἷς κατὰ μάγων συνέγραψας, καλλίστοις τε ἅμα καὶ ὠφελιμωτάτοις συγγράμμασιν καὶ δυναμένοις σωφρονίζειν τοὺς ἐντυγχάνοντας, ἱκανὰ παραθεμένου καὶ πολλῷ τούτων πλείονα.", "st": "38.21"}, {"sp": "N", "t": "ἔχρη οὖν καὶ ἐθέσπιζε, πολλῇ τῇ συνέσει ἐνταῦθα χρώμενος καὶ τὸ εἰκαστικὸν τῇ ἐπινοίᾳ προσάπτων, τοῖς μὲν λοξὰ καὶ ἀμφίβολα πρὸς τὰς ἐρωτήσεις ἀποκρινόμενος, τοῖς δὲ καὶ πάνυ ἀσαφῆ· χρησμῳδικὸν γὰρ ἐδόκει αὐτῷ τοῦτο. τοὺς δὲ ἀπέτρεπεν ἢ προὔτρεπεν, ὡς ἄμεινον ἔδοξεν αὐτῷ εἰκάζοντι· τοῖς δὲ θεραπείας προὔλεγεν καὶ διαίτας, εἰδώς, ὅπερ ἐν ἀρχῇ ἔφην, πολλὰ καὶ χρήσιμα φάρμακα. μάλιστα δὲ εὐδοκίμουν παρ’ αὐτῷ αἱ κυτμίδες, ἀκόπου τι ὄνομα πεπλασμένον, ἐκ λίπους ἀρκείου συντεθειμένου. τὰς μέντοι ἐλπίδας καὶ προκοπὰς καὶ κλήρων διαδοχὰς εἰσαῦθις ἀεὶ ἀνεβάλλετο, προστιθεὶς ὅτι “ἔσται πάντα ὁπόταν ἐθελήσω ἐγὼ καὶ Ἀλέξανδρος ὁ προφήτης μου δεηθῇ καὶ εὔξηται ὑπὲρ ὑμῶν.”", "st": "38.22"}, {"sp": "N", "t": "ἐτέτακτο δὲ ὁ μισθὸς ἐφ’ ἑκάστῳ χρησμῷ δραχμὴ καὶ δύ’ ὀβολώ. μὴ μικρὸν οἰηθῇς, ὦ ἑταῖρε, μηδ’ ὀλίγον γεγενῆσθαι τὸν πόρον τοῦτον, ἀλλ’ εἰς ἑπτὰ ἢ ὀκτὼ μυριάδας ἑκάστου ἔτους ἤθροιζεν, ἀνὰ δέκα καὶ πεντεκαίδεκα χρησμοὺς τῶν ἀνθρώπων ὑπὸ ἀπληστίας ἀναδιδόντων. λαμβάνων δὲ οὐκ αὐτὸς ἐχρῆτο μόνος οὐδ’ εἰς πλοῦτον ἀπεθησαύριζεν, ἀλλὰ πολλοὺς ἤδη περὶ αὑτὸν ἔχων συνεργοὺς καὶ ὑπηρέτας καὶ πευθῆνας καὶ χρησμοποιοὺς καὶ χρησμοφύλακας καὶ ὑπογραφέας καὶ ἐπισφραγιστὰς καὶ ἐξηγητάς, ἅπασιν ἔνεμεν ἑκάστῳ τὸ κατ’ ἀξίαν.", "st": "38.23"}, {"sp": "N", "t": "ἤδη δέ τινας καὶ ἐπὶ τὴν ἀλλοδαπὴν ἐξέπεμπεν, φήμας ἐμποιήσοντας τοῖς ἔθνεσιν ὑπὲρ τοῦ μαντείου καὶ διηγησομένους ὡς προείποι καὶ ἀνεύροι δραπέτας καὶ κλέπτας καὶ λῃστὰς ἐξελέγξειε καὶ θησαυροὺς ἀνορύξαι παράσχοι καὶ νοσοῦντας ἰάσαιτο, ἐνίους δὲ καὶ ἤδη ἀποθανόντας ἀναστήσειεν. δρόμος οὖν καὶ ὠθισμὸς ἁπανταχόθεν ἐγίγνετο καὶ θυσίαι καὶ ἀναθήματα, καὶ διπλάσια τῷ προφήτῃ καὶ μαθητῇ τοῦ θεοῦ. καὶ γὰρ αὖ καὶ οὗτος ἐξέπεσεν ὁ χρησμός·<br>Τιέμεναι κέλομαι τὸν ἐμὸν θεράπονθ’ ὑποφήτην· οὐ γάρ μοι κτεάνων μέλεται ἄγαν, ἀλλ’ ὑποφήτου·", "st": "38.24"}, {"sp": "N", "t": "ἐπεὶ δὲ ἤδη πολλοὶ τῶν νοῦν ἐχόντων ὥσπερ ἐκ μέθης βαθείας ἀναφέροντες συνίσταντο ἐπ’ αὐτόν, καὶ μάλιστα ὅσοι Ἐπικούρου ἑταῖροι ἦσαν, καὶ ἐν ταῖς πόλεσιν ἐπεφώρατο ἠρέμα ἡ πᾶσα μαγγανεία καὶ συσκευὴ τοῦ δράματος, ἐκφέρει φόβητρόν τι ἐπ’ αὐτούς, λέγων ἀθέων ἐμπεπλῆσθαι καὶ Χριστιανῶν τὸν Πόντον, οἳ περὶ αὐτοῦ τολμῶσι τὰ κάκιστα βλασφημεῖν· οὓς ἐκέλευε λίθοις ἐλαύνειν, εἴ γε θέλουσιν ἵλεω ἔχειν τὸν θεόν. περὶ δὲ Ἐπικούρου καὶ τοιοῦτόν τινα χρησμὸν ἀπεφθέγξατο· ἐρομένου γάρ τινος τί πράττει ἐν Ἅιδου ὁ Ἐπίκουρος;<br>“Μολυβδίνας ἔχων,” ἔφη, “πέδας ἐν βορβόρῳ κάθηται.”<br>εἶτα θαυμάζεις εἰ ἐπὶ μέγα ἤρθη τὸ χρηστήριον, ὁρῶν τὰς ἐρωτήσεις τῶν προσιόντων συνετὰς καὶ πεπαιδευμένας;", "st": "38.25"}, {"sp": "N", "t": "ὅλως δὲ ἄσπονδος καὶ ἀκήρυκτος αὐτῷ ὁ πόλεμος πρὸς Ἐπίκουρον ἦν· μάλα εἰκότως. τίνι γὰρ ἂν ἄλλῳ δικαιότερον προσεπολέμει γόης ἄνθρωπος καὶ τερατείᾳ φίλος, ἀληθείᾳ δὲ ἔχθιστος, ἢ Ἐπικούρῳ ἀνδρὶ τὴν φύσιν τῶν πραγμάτων καθεωρακότι καὶ μόνῳ τὴν ἐν αὐτοῖς ἀλήθειαν εἰδότι; οἱ μὲν γὰρ ἀμφὶ τὸν Πλάτωνα καὶ Χρύσιππον καὶ Πυθαγόραν φίλοι, καὶ εἰρήνη βαθεῖα πρὸς ἐκείνους ἦν· ὁ δὲ ἄτεγκτος Ἐπίκουρος — οὕτως γὰρ αὐτὸν ὠνόμαζεν — ἔχθιστος δικαίως, πάντα ταῦτα ἐν γέλωτι καὶ παιδιᾷ τιθέμενος. διὸ καὶ τὴν Ἄμαστριν ἐμίσει μάλιστα τῶν Ποντικῶν πόλεων, ὅτι ἠπίστατο τοὺς περὶ Λέπιδον καὶ ἄλλους ὁμοίους αὐτοῖς πολλοὺς ἐνόντας ἐν τῇ πόλει· οὐδὲ ἐχρησμῴδησε πώποτε Ἀμαστριανῷ ἀνδρί. ὁπότε δὲ καὶ ἐτόλμησεν ἀδελφῷ συγκλητικοῦ χρησμῳδῆσαι, καταγελάστως ἀπήλλαξεν, οὐχ εὑρὼν οὔτε αὐτὸς πλάσασθαι χρησμὸν δεξιὸν οὔτε τὸν ποιῆσαι πρὸς καιρὸν αὐτῷ δυνησόμενον. μεμφομένῳ γὰρ αὐτῷ στομάχου ὀδύνην προστάξαι βουλόμενος ὕειον πόδα μετὰ μαλάχης ἐσκευασμένον ἐσθίειν οὕτως ἔφη·<br>Μάλβακα χοιράων ἱερῇ κυμίνευε σιπύδνῳ.", "st": "38.25"}, {"sp": "N", "t": "πολλάκις μὲν οὖν, ὡς προεῖπον, ἔδειξε τὸν δράκοντα τοῖς δεομένοις, οὐχ ὅλον, ἀλλὰ τὴν οὐρὸν μάλιστα καὶ τὸ ἄλλο σῶμα προβεβληκώς, τὴν κεφαλὴν δὲ ὑπὸ κόλπου ἀθέατον φυλάττων. ἐθελήσας δὲ καὶ μειζόνως ἐκπλῆξαι τὸ πλῆθος, ὑπέσχετο καὶ λαλοῦντα παρέξειν τὸν θεόν, αὐτὸν ἄνευ ὑποφήτου χρησμῳδοῦντα. εἶτα οὐ χαλεπῶς γεράνων ἀρτηρίας συνάψας καὶ διὰ τῆς κεφαλῆς ἐκείνης τῆς μεμηχανημένης πρὸς ὁμοιότητα διείρας, ἄλλου τινὸς ἔξωθεν ἐμβοῶντος, ἀπεκρίνετο πρὸς τὰς ἐρωτήσεις, τῆς φωνῆς διὰ τοῦ ὀθονίνου ἐκείνου Ἀσκληπιοῦ προπιπτούσης.", "st": "38.26"}, {"sp": "N", "t": "ἐκαλοῦντο δὲ οἱ χρησμοὶ οὗτοι αὐτόφωνοι, καὶ οὐ πᾶσιν ἐδίδοντο οὐδὲ ἀνέδην, ἀλλὰ τοῖς εὐπαρύφοις καὶ πλουσίοις καὶ μεγαλοδώροις.", "st": "38.26"}, {"sp": "N", "t": "ὁ γοῦν Σευηριανῷ δοθεὶς ὑπὲρ τῆς εἰς Ἀρμενίαν εἰσόδου τῶν αὐτοφώνων καὶ αὐτὸς ἦν. προτρέπων γὰρ αὐτὸν ἐπὶ τὴν εἰσβολὴν οὕτως ἔφη·<br>Πάρθους Ἀρμενίους τε θοῷ ὑπὸ δουρὶ δαμάσσας<br>νοστήσεις Ῥώμην καὶ Θύβριδος ἀγλαὸν ὕδωρ<br>στέμμα φέρων κροτάφοισι μεμιγμένον ἀκτίνεσσιν.<br>εἶτ’ ἐπειδὴ πεισθεὶς ὁ ἠλίθιος ἐκεῖνος Κελτὸς εἰσέβαλε καὶ ἀπήλλαξεν αὐτῇ στρατιᾷ ὑπὸ τοῦ Ὀσρόου κατακοπείς, τοῦτον μὲν τὸν χρησμὸν ἐξαιρεῖ ἐκ τῶν ὑπομνημάτων, ἐντίθησιν δ’ ἄλλον ἀντ’ αὐτοῦ·<br>μὴ σύ γ’ ἐπ’ Ἀρμενίους ἐλάαν στρατόν, οὐ γὰρ ἄμεινον,<br>μή σοι θηλυχίτων τις ἀνὴρ τόξου ἄπο λυγρὸν<br>πότμον ἐπιπροϊεὶς παύσῃ βιότοιο φάους τε.", "st": "38.27"}, {"sp": "N", "t": "καὶ γὰρ αὖ καὶ τοῦτο σοφώτατον ἐπενόησε, τοὺς μεταχρονίους χρησμοὺς ἐπὶ θεραπείᾳ τῶν κακῶς προτεθεσπισμένων καὶ ἀποτετευγμένων. πολλάκις γὰρ πρὸ μὲν τῆς τελευτῆς τοῖς νοσοῦσιν ὑγίειαν ἐπηγγέλλετο, ἀποθανόντων δὲ χρησμὸς ἄλλος ἕτοιμος ἦν παλινῳδῶν·<br>Μηκέτι δίζησθαι νούσοιο λυγρῆς ἐπαρωγήν·<br>πότμος γὰρ προφανὴς οὐδ’ ἐκφυγέειν δυνατόν σοι.", "st": "38.28"}, {"sp": "N", "t": "εἰδὼς δὲ τοὺς ἐν Κλάρῳ καὶ Διδύμοις καὶ Μαλλῷ καὶ αὐτοὺς εὐδοκιμοῦντας ἐπὶ τῇ ὁμοίᾳ μαντικῇ ταύτῃ, φίλους αὐτοὺς ἐποιεῖτο, πολλοὺς τῶν προσιόντων πέμπων ἐπ’ αὐτοὺς λέγων·<br>Ἐς Κλάρον ἵεσο νῦν, τοὐμοῦ πατρὸς ὡς ὄπ’ ἀκούσῃς.<br>καὶ πάλιν·<br>Βραγχιδέων ἀδύτοισι πελάζεο καὶ κλύε χρησμῶν.<br>καὶ αὖθις·<br>ἐς Μαλλὸν χώρει θεσπίσματά τ’ Ἀμφιλόχοιο.", "st": "38.29"}, {"sp": "N", "t": "ταῦτα μὲν ἐντὸς τῶν ὅρων μέχρι τῆς Ἰωνίας καὶ Κιλικίας καὶ Παφλαγονίας καὶ Γαλατίας. ὡς δὲ καὶ εἰς τὴν Ἰταλίαν διεφοίτησεν τοῦ μαντείου τὸ κλέος καὶ εἰς τὴν Ῥωμαίων πόλιν ἐνέπεσεν, οὐδεὶς ὅστις οὐκ ἄλλος πρὸ ἄλλου ἠπείγετο, οἱ μὲν αὐτοὶ ἰόντες, οἱ δὲ πέμποντες, καὶ μάλιστα οἱ δυνατώτατοι καὶ μέγιστον ἀξίωμα ἐν τῇ πόλει ἔχοντες· ὧν πρῶτος καὶ κορυφαιότατος ἐγένετο Ῥουτιλιανός, ἀνὴρ τὰ μὲν ἄλλα καλὸς καὶ ἀγαθὸς καὶ ἐν πολλαῖς τάξεσι Ῥωμαϊκαῖς ἐξητασμένος, τὰ δὲ περὶ τοὺς θεοὺς πάνυ νοσῶν καὶ ἀλλόκοτα περὶ αὐτῶν πεπιστευκώς, εἰ μόνον ἀληλιμμένον που λίθον ἢ ἐστεφανωμένον θεάσαιτο, προσπίπτων εὐθὺς καὶ προσκυνῶν καὶ ἐπὶ πολὺ παρεστὼς καὶ εὐχόμενος καὶ τἀγαθὰ παρ’ αὐτοῦ αἰτῶν.", "st": "38.30"}, {"sp": "N", "t": "οὗτος τοίνυν ἀκούσας τὰ περὶ τοῦ χρηστηρίου μικροῦ μὲν ἐδέησεν ἀφεὶς τὴν ἐγκεχειρισμένην τάξιν εἰς τὸ τοῦ Ἀβώνου τεῖχος ἀναπτῆναι. ἔπεμπε δ’ οὖν ἄλλους ἐπ’ ἄλλοις· οἱ δὲ πεμπόμενοι, ἰδιῶταί τινες οἰκέται, ῥᾳδίως ἐξαπατηθέντες ἂν ἐπανῄεσαν, τὰ μὲν ἰδόντες, τὰ δὲ ὡς ἰδόντες καὶ ἀκούσαντες διηγούμενοι καὶ προσεπιμετροῦντες ἔτι πλείω τούτων, ὡς ἐντιμότεροι εἶεν παρὰ τῷ δεσπότῃ. ἐξέκαιον οὖν τὸν ἄθλιον γέροντα καὶ εἰς μανίαν ἐρρωμένην ἐνέβαλον.", "st": "38.30"}, {"sp": "N", "t": "ὁ δέ, ὡς ἂν τοῖς πλείστοις καὶ δυνατωτάτοις φίλος ὤν, περιῄει τὰ μὲν διηγούμενος ὡς ἀκούσειε παρὰ τῶν πεμφθέντων, τὰ δὲ καὶ παρ’ αὑτοῦ προστιθείς. ἐνέπλησεν οὖν τὴν πόλιν καὶ διεσάλευσεν οὗτος, καὶ τῶν ἐν τῇ αὐλῇ τοὺς πλείστους διεθορύβησεν, οἳ αὐτίκα καὶ αὐτοὶ ἠπείγοντο ἀκοῦσαί τι τῶν καθ’ αὑτούς.", "st": "38.31"}, {"sp": "N", "t": "ὁ δὲ τοὺς ἀφικνουμένους πάνυ φιλοφρόνως ὑποδεχόμενος ξενίοις τε καὶ ταῖς ἄλλαις δωρεαῖς πολυτελέσιν εὔνους ἐργαζόμενος αὑτῷ ἀπέπεμπεν οὐκ ἀπαγγελοῦντας μόνον τὰς ἐρωτήσεις, ἀλλὰ καὶ ὑμνήσοντας τὸν θεὸν καὶ τεράστια ὑπὲρ τοῦ μαντείου καὶ αὐτοὺς ψευσομένους.", "st": "38.31"}, {"sp": "N", "t": "ἀλλὰ καὶ μηχανᾶταί τι ὁ τρισκατάρατος οὐκ ἄσοφον οὐδὲ τοῦ προστυχόντος λῃστοῦ ἄξιον. λύων γὰρ τὰ πεπεμμένα βιβλία καὶ ἀναγιγνώσκων, εἴ τι εὕροι ἐπισφαλὲς καὶ παρακεκινδυνευμένον ἐν ταῖς ἐρωτήσεσιν, κατεῖχεν αὐτὸς καὶ οὐκ ἀπέπεμπεν, ὡς ὑποχειρίους καὶ μονονουχὶ δούλους διὰ τὸ δέος ἔχοι τοὺς πεπομφότας, μεμνημένους οἷα ἦν ἃ ἤροντο. συνίης δὲ οἵας εἰκὸς τοὺς πλουσίους καὶ μέγα δυναμένους τὰς πύστεις πυνθάνεσθαι. ἐλάμβανεν οὖν πολλὰ παρ’ ἐκείνων, εἰδότων ὅτι ἐντὸς αὐτοὺς ἔχοι τῶν ἀρκύων.", "st": "38.32"}, {"sp": "N", "t": "βούλομαι δέ σοι καὶ τῶν Ῥουτιλιανῷ δοθέντων χρησμῶν ἐνίους εἰπεῖν. πυνθανομένῳ γὰρ αὐτῷ ὑπὲρ τοῦ παιδὸς ἐκ προτέρας γυναικός, παιδείας ὥραν ἔχοντος, ὅντινα προστήσεται διδάσκαλον τῶν μαθημάτων αὐτοῦ, ἔφη·<br>Πυθαγόρην πολέμων τε διάκτορον ἐσθλὸν ἀοιδόν.<br>εἶτα μετ’ ὀλίγας ἡμέρας τοῦ παιδὸς ἀποθανόντος, ὁ μὲν ἠπόρει καὶ οὐδὲν εἶχεν λέγειν πρὸς τοὺς αἰτιωμένους, παρὰ πόδας οὕτως ἐληλεγμένου τοῦ χρησμοῦ· ὁ δὲ Ῥουτιλιανὸς αὐτὸς φθάσας ὁ βέλτιστος ἀπελογεῖτο ὑπὲρ τοῦ μαντείου λέγων, τοῦτο αὐτὸ προδεδηλωκέναι τὸν θεὸν καὶ διὰ τοῦτο ζῶντα μὲν κελεῦσαι μηδένα διδάσκαλον ἑλέσθαι αὐτῷ, Πυθαγόραν δὲ καὶ Ὅμηρον πάλαι τεθνεῶτας, οἷς εἰκὸς τὸ μειράκιον ἐν Ἅιδου νῦν συνεῖναι. τί τοίνυν μέμφεσθαι ἄξιον Ἀλεξάνδρῳ, εἰ τοιούτοις ἀνθρωπίσκοις ἐνδιατρίβειν ἠξίου;", "st": "38.33"}, {"sp": "N", "t": "αὖθις δὲ πυνθανομένῳ αὐτῷ τὴν τίνος ψυχὴν αὐτὸς διεδέξατο, ἔφη·<br>πρῶτον Πηλείδης ἐγένου, μετὰ ταῦτα Μένανδρος,<br>εἶθ’ ὃς νῦν φαίνῃ, μετὰ δ’ ἔσσεαι ἡλιὰς ἀκτίς,<br>ζήσεις δ’ ὀγδώκοντ’ ἐπὶ τοῖς ἑκατὸν λυκάβαντας.<br>ὁ δὲ ἑβδομηκοντούτης ἀπέθανεν μελαγχολήσας, οὐ περιμείνας τὴν τοῦ θεοῦ ὑπόσχεσιν.", "st": "38.34"}, {"sp": "N", "t": "καὶ οὗτος ὁ χρησμὸς τῶν αὐτοφώνων ἦν.", "st": "38.35"}, {"sp": "N", "t": "ἐρομένῳ δὲ αὐτῷ ποτε καὶ περὶ γάμου ῥητῶς ἔφη·<br>γῆμον Ἀλεξάνδρου τε Σεληναίης τε θύγατρα.<br>διεδεδώκει δὲ πάλαι λόγον ὡς τῆς θυγατρός, ἣν εἶχεν, ἐκ Σελήνης αὐτῷ γενομένης· τὴν γὰρ Σελήνην ἔρωτι ἁλῶναι αὐτοῦ καθεύδοντά ποτε ἰδοῦσαν, ὅπερ αὐτῇ ἔθος, κοιμωμένων ἐρᾶν τῶν καλῶν. ὁ δ’ οὐδὲν μελλήσας ὁ συνετώτατος Ῥουτιλιανὸς ἔπεμπεν εὐθὺς ἐπὶ τὴν κόρην καὶ τοὺς γάμους συνετέλει ἑξηκοντούτης νυμφίος καὶ συνῆν, τὴν πενθερὰν Σελήνην ἑκατόμβαις ὅλαις ἱλασκόμενος καὶ τῶν ἐπουρανίων εἷς καὶ αὐτὸς οἰόμενος γεγονέναι.", "st": "38.35"}, {"sp": "N", "t": "ὁ δ’ ὡς ἅπαξ τῶν ἐν Ἰταλίᾳ πραγμάτων ἐλάβετο, μείζω ἀεὶ προσεπενόει καὶ πάντοσε τῆς Ῥωμαίων ἀρχῆς ἔπεμπε χρησμολόγους, ταῖς πόλεσι προλέγων λοιμοὺς καὶ πυρκαϊὰς φυλάσσεσθαι καὶ σεισμούς· καὶ ἀσφαλῶς βοηθήσειν, ὡς μὴ γένοιτό τι τούτων, αὐτὸς ὑπισχνεῖτο αὐτοῖς. ἕνα δέ τινα χρησμόν, αὐτόφωνον καὶ αὐτόν, εἰς ἅπαντα τὰ ἔθνη ἐν τῷ λοιμῷ διεπέμψατο· ἦν δὲ τὸ ἔπος ἕν·<br>Φοῖβος ἀκειρεκόμης λοιμοῦ νεφέλην ἀπερύκει.<br>καὶ τοῦτο ἦν ἰδεῖν τὸ ἔπος πανταχοῦ ἐπὶ τῶν πυλώνων γεγραμμένον ὡς τοῦ λοιμοῦ ἀλεξιφάρμακον. τὸ δ’ εἰς τοὐναντίον τοῖς πλείστοις προὐχώρει· κατὰ γάρ τινα τύχην αὗται μάλιστα αἱ οἰκίαι ἐκενώθησαν αἷς τὸ ἔπος ἐπεγέγραπτο. καὶ μή με νομίσῃς τοῦτο λέγειν, ὅτι διὰ τὸ ἔπος ἀπώλλυντο· ἀλλὰ τύχῃ τινὶ οὕτως ἐγένετο. τάχα δὲ καὶ οἱ πολλοὶ θαρροῦντες τῷ στίχῳ ἠμέλουν καὶ ῥᾳθυμότερον διῃτῶντο, οὐδὲν τῷ χρησμῷ πρὸς τὴν νόσον συντελοῦντες, ὡς ἂν ἔχοντες προμαχομένας αὑτῶν τὰς συλλαβὰς καὶ τὸν ἀκειρεκόμην Φοῖβον ἀποτοξεύοντα τὸν λοιμόν.", "st": "38.36"}, {"sp": "N", "t": "Πευθῆνας μέντοι ἐν αὐτῇ Ῥώμῃ κατεστήσατο πάνυ πολλοὺς τῶν συνωμοτῶν, οἳ τὰς ἑκάστου γνώμας διήγγελλον αὐτῷ καὶ τὰς ἐρωτήσεις προεμήνυον καὶ ὧν μάλιστα ἐφίενται, ὡς ἕτοιμον αὐτὸν πρὸς τὰς ἀποκρίσεις καὶ πρὶν ἥκειν τοὺς πεμπομένους καταλαμβάνεσθαι.", "st": "38.37"}, {"sp": "N", "t": "καὶ πρὸς μὲν τὰ ἐν τῇ Ἰταλίᾳ ταῦτα προεμηχανᾶτο· ⟨οἴκοι δὲ καὶ τὰ τοιαῦτα.⟩ τελετήν τε γάρ τινα συνίσταται καὶ δᾳδουχίας καὶ ἱεροφαντίας, τριῶν ἑξῆς ἀεὶ τελουμένων ἡμερῶν. καὶ ἐν μὲν τῇ πρώτῃ πρόρρησις ἦν ὥσπερ Ἀθήνησι τοιαύτη· “εἴ τις ἄθεος ἢ Χριστιανὸς ἢ Ἐπικούρειος ἥκει κατάσκοπος τῶν ὀργίων, φευγέτω· οἱ δὲ πιστεύοντες τῷ θεῷ τελείσθωσαν τύχῃ τῇ ἀγαθῇ.” εἶτ’ εὐθὺς ἐν ἀρχῇ ἐξέλασις ἐγίγνετο· καὶ ὁ μὲν ἡγεῖτο λέγων “ἔξω Χριστιανούς,” τὸ δὲ πλῆθος ἅπαν ἐπεφθέγγετο “ἔξω Ἐπικουρείους.” εἶτα Λητοῦς ἐγίγνετο λοχεία καὶ Ἀπόλλωνος γοναὶ καὶ Κορωνίδος γάμος καὶ Ἀσκληπιὸς ἐτίκτετο. ἐν δὲ τῇ δευτέρᾳ Γλύκωνος ἐπιφάνεια καὶ γέννησις τοῦ θεοῦ.", "st": "38.38"}, {"sp": "N", "t": "τρίτῃ δὲ ἡμέρᾳ Ποδαλειρίου ἦν καὶ τῆς μητρὸς Ἀλεξάνδρου γάμος· Δᾳδὶς δὲ ἐκαλεῖτο καὶ δᾷδες δὲ ἐκαίοντο. καὶ τελευταῖον Σελήνης καὶ Ἀλεξάνδρου ἔρως καὶ τικτομένη τοῦ Ῥουτιλιανοῦ ἡ γυνή. ἐδᾳδούχει δὲ καὶ ἱεροφάντει ὁ Ἐνδυμίων Ἀλέξανδρος. καὶ ὁ μὲν καθεύδων δῆθεν κατέκειτο ἐν τῷ μέσῳ, κατῄει δὲ ἐπ’ αὐτὸν ἀπὸ τῆς ὀροφῆς ὡς ἐξ οὐρανοῦ ἀντὶ τῆς Σελήνης Ῥουτιλία τις ὡραιοτάτη, τῶν Καίσαρος οἰκονόμων τινὸς γυνή, ὡς ἀληθῶς ἐρῶσα τοῦ Ἀλεξάνδρου καὶ ἀντερωμένη ὑπ’ αὐτοῦ, καὶ ἐν ὀφθαλμοῖς τοῦ ὀλεθρίου ἐκείνου ἀνδρὸς φιλήματά τε ἐγίγνετο ἐν τῷ μέσῳ καὶ περιπλοκαί. εἰ δὲ μὴ πολλαὶ ἦσαν αἱ δᾷδες, τάχα ἄν τι καὶ τῶν ὑπὸ κόλπου ἐπράττετο. μετὰ μικρὸν δὲ εἰσῄει πάλιν ἱεροφαντικῶς ἐσκευασμένος ἐν πολλῇ τῇ σιωπῇ, καὶ αὐτὸς μὲν ἔλεγε μεγάλῃ τῇ φωνῇ, “ἰὴ Γλύκων” ἐπεφθέγγοντο δὲ αὐτῷ ἐπακολουθοῦντες Εὐμολπίδαι δῆθεν καὶ Κήρυκές τινες Παφλαγόνες, καρβατίνας ὑποδεδεμένοι, πολλὴν τὴν σκοροδάλμην ἐρυγγάνοντες, “ἰὴ Ἀλέξανδρε.”", "st": "38.39"}, {"sp": "N", "t": "πολλάκις δὲ ἐν τῇ δᾳδουχίᾳ καὶ τοῖς μυστικοῖς σκιρτήμασιν γυμνωθεὶς ὁ μηρὸς αὐτοῦ ἐξεπίτηδες χρυσοῦς διεφάνη, δέρματος ὡς εἰκὸς ἐπιχρύσου περιτεθέντος καὶ πρὸς τὴν αὐγὴν τῶν λαμπάδων ἀποστίλβοντος. ὥστε καὶ γενομένης ποτὲ ζητήσεως δύο τισὶ τῶν μωροσόφων ὑπὲρ αὐτοῦ, εἴτε Πυθαγόρου τὴν ψυχὴν ἔχοι διὰ τὸν χρυσοῦν μηρὸν εἴτε ἄλλην ὁμοίαν αὐτῇ, καὶ τὴν ζήτησιν ταύτην αὐτῷ Ἀλεξάνδρῳ ἐπανενεγκόντων, ὁ βασιλεὺς Γλύκων χρησμῷ ἔλυσεν τὴν ἀπορίαν·<br>Πυθαγόρου ψυχὴ ποτὲ μὲν φθίνει, ἄλλοτε δ’ αὔξει·<br>ἡ δὲ προφητείη δίης φρενός ἐστιν ἀπορρώξ.<br>καί μιν ἔπεμψε πατὴρ ἀγαθῶν ἀνδρῶν ἐπαρωγόν·<br>καὶ πάλιν ἐς Διὸς εἶσι Διὸς βληθεῖσα κεραυνῷ.", "st": "38.40"}, {"sp": "N", "t": "προλέγων δὲ πᾶσιν ἀπέχεσθαι παιδίου συνουσίας, ὡς ἀσεβὲς ὄν, αὐτὸς τοιόνδε τι ὁ γεννάδας ἐτεχνήσατο. ταῖς γὰρ πόλεσι ταῖς Ποντικαῖς καὶ ταῖς Παφλαγονικαῖς ἐπήγγελλε θεηκόλους πέμπειν εἰς τριετίαν, ὑμνήσοντας παρ’ αὐτῷ τὸν θεόν, καὶ ἔδει δοκιμασθέντας καὶ προκριθέντας τοὺς εὐγενεστάτους καὶ ὡραιοτάτους καὶ κάλλει διαφέροντας πεμφθῆναι· οὓς ἐγκλεισάμενος ὥσπερ ἀργυρωνήτοις ἐχρῆτο, συγκαθεύδων καὶ πάντα τρόπον ἐμπαροινῶν. καὶ νόμον δὲ ἐπεποίητο, ὑπὲρ τὰ ὀκτωκαίδεκα ἔτη μηδένα τῷ αὐτοῦ στόματι δεξιοῦσθαι μηδὲ φιλήματι ἀσπάζεσθαι, ἀλλὰ τοῖς ἄλλοις προτείνων τὴν χεῖρα κύσαι μόνους τοὺς ὡραίους κατεφίλει, καὶ ἐκαλοῦντο οἱ ἐντὸς τοῦ φιλήματος.", "st": "38.41"}, {"sp": "N", "t": "τοιαῦτα ἐντρυφῶν τοῖς ἀνοήτοις διετέλει, γυναῖκάς τε ἀνέδην διαφθείρων καὶ παισὶ συνών. καὶ ἦν μέγα καὶ εὐκτὸν ἑκάστῳ, εἴ τινος γυναικὶ προσβλέψειεν· εἰ δὲ καὶ φιλήματος ἀξιώσειεν, ἀθρόαν τὴν ἀγαθὴν τύχην ᾤετο ἕκαστος εἰς τὴν οἰκίαν αὐτῷ εἰσρυήσεσθαι. πολλαὶ δὲ καὶ ηὔχουν τετοκέναι παρ’ αὐτοῦ, καὶ οἱ ἄνδρες ἐπεμαρτύρουν ὅτι ἀληθῆ λέγουσιν.", "st": "38.42"}, {"sp": "N", "t": "ἐθέλω δέ σοι καὶ διάλογον διηγήσασθαι τοῦ Γλύκωνος καὶ Σακερδῶτός τινος, Τιανοῦ ἀνθρώπου· ὁποίου τινὸς τὴν σύνεσιν, εἴσῃ ἀπὸ τῶν ἐρωτήσεων. ἀνέγνων δὲ αὐτὸν χρυσοῖς γράμμασιν γεγραμμένον ἐν Τίῳ, ἐν τῇ τοῦ Σακερδῶτος οἰκίᾳ. “εἰπὲ γάρ μοι,” ἔφη, “ὦ δέσποτα Γλύκων, τίς εἶ;” “ἐγώ,” ἦ δ’ ὅς, “Ἀσκληπιὸς νέος.” “ἄλλος παρ’ ἐκεῖνον τὸν πρότερον; πῶς λέγεις;” “οὐ θέμις ἀκοῦσαί σε τοῦτό γε.” “πόσα δὲ ἡμῖν ἔτη παραμενεῖς χρησμῳδῶν;” “τρίτον πρὸς τοῖς χιλίοις.” “εἶτα ποῖ μεταστήσῃ; ἐς” “Βάκτρα καὶ τὴν ἐκεῖ γῆν· δεῖ γὰρ ἀπολαῦσαι καὶ τοὺς βαρβάρους τῆς ἐπιδημίας τῆς ἐμῆς.” “τὰ δ’ ἄλλα χρηστήρια, τὸ ἐν Διδύμοις καὶ τὸ ἐν Κλάρῳ καὶ τὸ ἐν Δελφοῖς, ἔχουσι τὸν πατέρα τὸν Ἀπόλλω χρησμῳδοῦντα, ἢ ψευδεῖς εἰσιν οἱ νῦν ἐκπίπτοντες ἐκεῖ χρησμοί;” “μηδὲ τοῦτο ἐθελήσῃς εἰδέναι· οὐ γὰρ θέμις.” “ἐγὼ δὲ τίς ἔσομαι μετὰ τὸν νῦν βίον;” “κάμηλος, εἶτα ἵππος, εἶτ’ ἀνὴρ σοφὸς καὶ προφήτης οὐ μείων Ἀλεξάνδρου.”", "st": "38.43"}, {"sp": "N", "t": "Τοιαῦτα μὲν ὁ Γλύκων τῷ Σακερδῶτι διελέχθη. ἐπὶ τέλει δὲ χρησμὸν ἔμμετρον ἐφθέγξατο, εἰδὼς αὐτὸν Λεπίδῳ ἑταῖρον ὄντα·<br>Μὴ πείθου Λεπίδῳ, ἐπεὶ ἦ λυγρὸς οἶτος ὀπηδεῖ.<br>πάνυ γὰρ ἐδεδίει τὸν Ἐπίκουρον, ὡς προεῖπον, ὥς τινα ἀντίτεχνον καὶ ἀντισοφιστὴν τῆς μαγγανείας αὐτοῦ.", "st": "38.43"}, {"sp": "N", "t": "ἕνα γοῦν τινα τῶν Ἐπικουρείων, τολμήσαντα καὶ διελέγχειν αὐτὸν ἐπὶ πολλῶν τῶν παρόντων, εἰς κίνδυνον οὐ μικρὸν κατέστησεν. ὁ μὲν γὰρ προσελθὼν ἔλεγεν μεγάλῃ τῇ φωνῇ· “σὺ μέντοι γε, ὦ Ἀλέξανδρε, τὸν δεῖνα Παφλαγόνα προσαγαγεῖν οἰκέτας αὐτοῦ τῷ ἡγουμένῳ τῆς Γαλατίας τὴν ἐπὶ θανάτῳ ἀνέπεισας ὡς ἀπεκτονότας τὸν υἱὸν αὐτοῦ ἐν Ἀλεξανδρείᾳ παιδευόμενον, ὁ δὲ νεανίσκος ζῇ καὶ ἐπανελήλυθε ζῶν μετὰ τὴν τῶν οἰκετῶν ἀπώλειαν, θηρίοις ὑπὸ σοῦ παραδοθέντων.” τοιοῦτον δέ τι ἐγεγένητο· ἀναπλεύσας ὁ νεανίσκος εἰς Αἴγυπτον ἄχρι τοῦ Κλύσματος, πλοίου ἀναγομένου ἐπείσθη καὶ αὐτὸς εἰς Ἰνδίαν πλεῦσαι, κἀπειδήπερ ἐβράδυνεν, οἱ δυστυχεῖς ἐκεῖνοι οἰκέται αὐτοῦ, οἰηθέντες ἢ ἐν τῷ Νείλῳ πλέοντα διεφθάρθαι τὸν νεανίσκον ἢ καὶ ὑπὸ λῃστῶν — πολλοὶ δὲ ἦσαν τότε — ἀνῃρῆσθαι, ἐπανῆλθον ἀπαγγέλλοντες αὐτοῦ τὸν ἀφανισμόν. εἶτα ὁ χρησμὸς καὶ ἡ καταδίκη, μεθ’ ἣν ἐπέστη ὁ νεανίσκος διηγούμενος τὴν ἀποδημίαν.", "st": "38.44"}, {"sp": "N", "t": "ὃ μὲν ταῦτα ἔλεγεν. ὁ δὲ Ἀλέξανδρος ἀγανακτήσας ἐπὶ τῷ ἐλέγχῳ καὶ μὴ φέρων τοῦ ὀνείδους τὴν ἀλήθειαν ἐκέλευεν τοὺς παρόντας λίθοις βάλλειν αὐτόν, ἢ καὶ αὐτοὺς ἐναγεῖς ἔσεσθαι καὶ Ἐπικουρείους κληθήσεσθαι. τῶν δὲ βάλλειν ἀρξαμένων Δημόστρατός τις ἐπιδημῶν, τοῦ Πόντου πρῶτος, περιχυθεὶς ἐρρύσατο τοῦ θανάτου τὸν ἄνθρωπον μικροῦ δεῖν καταλευσθέντα, πάνυ δικαίως. τί γὰρ ἔδει μόνον φρονεῖν ἐν τοσούτοις μεμηνόσιν καὶ παραπολαῦσαι τῆς Παφλαγόνων μωρίας;", "st": "38.45"}, {"sp": "N", "t": "καὶ τὰ μὲν κατ’ ἐκεῖνον τοιαῦτα. εἰ δέ τινι, προσκαλουμένων κατὰ τάξιν τῶν χρησμῶν — πρὸ μιᾶς δὲ τοῦτο τοῦ θεσπίζειν ἐγίγνετο — καὶ ἐρομένου τοῦ κήρυκος εἰ θεσπίζει τῷδε, ἀνεῖπεν ἔνδοθεν· “ἐς κόρακας,” οὐκέτι τὸν τοιοῦτον οὔτε στέγῃ τις ἐδέχετο οὔτε πυρὸς ἢ ὕδατος ἐκοινώνει, ἀλλ’ ἔδει γῆν πρὸ γῆς ἐλαύνεσθαι ὡς ἀσεβῆ καὶ ἄθεον καὶ Ἐπικούρειον, ἥπερ ἦν ἡ μεγίστη λοιδορία.", "st": "38.46"}, {"sp": "N", "t": "ἓν γοῦν καὶ γελοιότατον ἐποίησεν ὁ Ἀλέξανδρος· εὑρὼν γὰρ τὰς Ἐπικούρου κυρίας δόξας, τὸ κάλλιστον, ὡς οἶσθα, τῶν βιβλίων καὶ κεφαλαιώδη περιέχον τῆς τἀνδρὸς σοφίας τὰ δόγματα, κομίσας εἰς τὴν ἀγορὰν μέσην ἔκαυσεν ἐπὶ ξύλων συκίνων ὡς δῆθεν αὐτὸν καταφλέγων, καὶ τὴν σποδὸν εἰς τὴν θάλασσαν ἐξέβαλεν, ἔτι καὶ χρησμὸν ἐπιφθεγξάμενος·<br>Πυρπολέειν κέλομαι δόξας ἀλαοῖο γέροντος·<br>οὐκ εἰδὼς ὁ κατάρατος ὅσων ἀγαθῶν τὸ βιβλίον ἐκεῖνο τοῖς ἐντυχοῦσιν αἴτιον γίγνεται, καὶ ὅσην αὐτοῖς εἰρήνην καὶ ἀταραξίαν καὶ ἐλευθερίαν ἐνεργάζεται, δειμάτων μὲν καὶ φασμάτων καὶ τεράτων ἀπαλλάττον καὶ ἐλπίδων ματαίων καὶ περιττῶν ἐπιθυμιῶν, νοῦν δὲ καὶ ἀλήθειαν ἐντιθὲν καὶ καθαῖρον ὡς ἀληθῶς τὰς γνώμας, οὐχ ὑπὸ δᾳδὶ καὶ σκίλλῃ καὶ ταῖς τοιαύταις φλυαρίαις, ἀλλὰ λόγῳ ὀρθῷ καὶ ἀληθείᾳ καὶ παρρησίᾳ.", "st": "38.47"}, {"sp": "N", "t": "ἐν δὲ τοῖς ἄλλοις ἕν τι καὶ μέγιστον τόλμημα τοῦ μιαροῦ ἀνδρὸς ἄκουσον. ἔχων γὰρ οὐ μικρὰν ἐπίβασιν ἐπὶ τὰ βασίλεια καὶ τὴν αὐλὴν τὸν Ῥουτιλιανὸν εὐδοκιμοῦντα, διαπέμπεται χρησμὸν τοῦ ἐν Γερμανίᾳ πολέμου ἀκμάζοντος, ὅτε θεὸς Μάρκος ἤδη τοῖς Μαρκομάνοις καὶ Κουάδοις συνεπλέκετο. ἠξίου δὲ ὁ χρησμὸς δύο λέοντας ἐμβληθῆναι ζῶντας εἰς τὸν Ἴστρον μετὰ πολλῶν ἀρωμάτων καὶ θυσιῶν μεγαλοπρεπῶν. ἄμεινον δὲ αὐτὸν εἰπεῖν τὸν χρησμόν·<br>Ἐς δίνας Ἴστροιο διιπετέος ποταμοῖο<br>ἐσβαλέειν κέλομαι δοιοὺς Κυβέλης θεράποντας,<br>θῆρας ὀριτρεφέας, καὶ ὅσα τρέφει Ἰνδικὸς ἀὴρ<br>ἄνθεα καὶ βοτάνας εὐώδεας· αὐτίκα δ’ ἔσται<br>νίκη καὶ μέγα κῦδος ἅμ’ εἰρήνῃ ἐρατεινῇ.<br>γενομένων δὲ τούτων ὡς προσέταξεν, τοὺς μὲν λέοντας ἐκνηξαμένους εἰς τὴν πολεμίαν οἱ βάρβαροι ξύλοις κατειργάσαντο ὥς τινας κύνας ἢ λύκους ξενικούς· αὐτίκα δὲ τὸ μέγιστον τραῦμα τοῖς ἡμετέροις ἐγένετο, δισμυρίων που σχεδὸν ἀθρόων ἀπολομένων. εἶτα ἐπηκολούθησε τὰ περὶ Ἀκυληΐαν γενόμενα καὶ ἡ παρὰ μικρὸν τῆς πόλεως ἐκείνης ἅλωσις. ὁ δὲ πρὸς τὸ ἀποβεβηκὸς τὴν Δελφικὴν ἐκείνην ἀπολογίαν καὶ τὸν τοῦ Κροίσου χρησμὸν ψυχρῶς παρῆγεν· νίκην μὲν γὰρ προειπεῖν τὸν θεόν, μὴ μέντοι δηλῶσαι Ῥωμαίων ἢ τῶν πολεμίων.", "st": "38.48"}, {"sp": "N", "t": "ἤδη δὲ πολλῶν ἐπὶ πολλοῖς ἐπεισρεόντων καὶ τῆς πόλεως αὐτῶν θλιβομένης ὑπὸ τοῦ πλήθους τῶν ἐπὶ τὸ χρηστήριον ἀφικνουμένων καὶ τὰ ἐπιτήδεια διαρκῆ μὴ ἐχούσης, ἐπινοεῖ τοὺς νυκτερινοὺς καλουμένους χρησμούς. λαμβάνων γὰρ τὰ βιβλία ἐπεκοιμᾶτο, ὡς ἔφασκεν, αὐτοῖς καὶ ὡς ὄναρ παρὰ τοῦ θεοῦ ἀκούων ἀπεκρίνετο, οὐ μέντοι σαφεῖς τοὺς πολλούς, ἀλλ’ ἀμφιβόλους καὶ τεταραγμένους καὶ μάλιστα εἴ ποτε θεάσαιτο περιεργότερον τὸ βιβλίον κατεσφραγισμένον. οὐ γὰρ παρακινδυνεύων, τὸ ἐπελθὸν ἄλλως ὑπέγραφε, χρησμοῖς πρέπον καὶ τὸ τοιοῦτον οἰόμενος. καὶ ἦσάν τινες ἐξηγηταὶ ἐπὶ τοῦτο καθήμενοι καὶ μισθοὺς οὐκ ὀλίγους ἐκλέγοντες παρὰ τῶν τοὺς τοιούτους χρησμοὺς λαμβανόντων ἐπὶ τῇ ἐξηγήσει καὶ διαλύσει αὐτῶν. καὶ τοῦτο αὐτῶν τὸ ἔργον ὑπόμισθον ἦν· ἐτέλουν γὰρ οἱ ἐξηγηταὶ τῷ Ἀλεξάνδρῳ τάλαντον Ἀττικὸν ἑκάτερος.", "st": "38.49"}, {"sp": "N", "t": "ἐνίοτε δὲ μήτε ἐρομένου τινὸς μήτε πεμφθέντος, ἀλλ’ οὐδὲ ὅλως ὄντος ἐχρησμῴδει πρὸς ἔκπληξιν τῶν ἀνοήτων, οἷον καὶ τοῦτο·<br>Δίζεαι ὅστις σὴν ἄλοχον μάλα πάγχυ λεληθὼς<br>Καλλιγένειαν ὑπὲρ λεχέων σαλαγεῖ κατὰ δῶμα;<br>δοῦλος Πρωτογένης, τῷ δὴ σύ γε πάντα πέποιθας.<br>ὤπυιες γὰρ ἐκεῖνον, ὁ δ’ αὖθις σὴν παράκοιτιν,<br>ἀντίδοσιν ταύτην ὕβρεως ἄκρην ἀποτίνων.<br>ἀλλ’ ἐπὶ σοὶ δὴ φάρμακ’ ἀπ’ αὐτῶν λυγρὰ τέτυκται,<br>ὡς μήτ’ εἰσαΐοις μήτ’ εἰσοράοις ἃ ποιοῦσιν.<br>εὑρήσεις δὲ κάτω ὑπὸ σῷ λέχει ἀγχόθι τοίχου<br>πρὸς κεφαλῆς. καὶ σὴ θεράπαινα σύνοιδε Καλυψώ.<br>τίς οὐκ ἂν Δημόκριτος διεταράχθη ἀκούσας ὀνόματα καὶ τόπους ἀκριβῶς, εἶτα μετ’ ὀλίγον κατέπτυσεν ἄν, συνεὶς τὴν ἐπίνοιαν αὐτῶν;", "st": "38.50"}, {"sp": "N", "t": "ἀλλὰ καὶ βαρβάροις πολλάκις ἔχρησεν, εἴ τις τῇ πατρίῳ ἔροιτο φωνῇ, Συριστὶ ἢ Κελτιστί, ῥᾳδίως ἐξευρίσκων τινὰς ἐπιδημοῦντας ὁμοεθνεῖς τοῖς δεδωκόσιν. διὰ τοῦτο καὶ πολὺς ὁ ἐν μέσῳ χρόνος ἦν τῆς τε δόσεως τῶν βιβλίων καὶ τῆς χρησμῳδίας, ὡς ἐν τοσούτῳ κατὰ σχολὴν λύοιντό τε οἱ χρησμοὶ ἀσφαλῶς καὶ εὑρίσκοιντο οἱ ἑρμηνεῦσαι δυνάμενοι ἕκαστα. οἷος καὶ ὁ τῷ Σκύθῃ δοθεὶς χρησμὸς ἦν·<br>“μορφὴν εὐβάργουλις εἰς σκιὰν χνεχικραγη λείψει φάος.”", "st": "38.51"}, {"sp": "N", "t": "Ἄλλῳ πάλιν οὔτε παρόντι οὔτε ὅλως τινὶ ὄντι ἔφη ἄνευ μέτρου ἀναστρέφειν ὀπίσω “ὁ γὰρ πέμψας σε τέθνηκεν ὑπὸ τοῦ γείτονος Διοκλέους τήμερον, λῃστῶν ἐπαχθέντων Μάγνου καὶ Βουβάλου, οἳ καὶ ἤδη δέδενται ληφθέντες.”", "st": "38.52"}, {"sp": "N", "t": "ὀλίγους δὲ καὶ τῶν ἐμοὶ δοθέντων ἄκουσον· ἐρομένου γάρ μου εἰ φαλακρός ἐστιν Ἀλέξανδρος, καὶ κατασημηναμένου περιέργως καὶ προφανῶς ὑπογράφεται χρησμὸς νυκτερήσιος,<br>Σαβαρδαλαχου μαλαχααττηαλος ἦν.", "st": "38.53"}, {"sp": "N", "t": "Καὶ πάλιν ἐμοῦ ἐρομένου ἐν δύο βιβλίοις διαφόροις τὴν αὐτὴν ἐρώτησιν, πόθεν ἦν Ὅμηρος ὁ ποιητής, ἐπ’ ἄλλου καὶ ἄλλου ὀνόματος, τῷ ἑτέρῳ μὲν ὑπέγραψεν ἐξαπατηθεὶς ὑπὸ τοῦ ἐμοῦ νεανίσκου — ἐρωτηθεὶς γὰρ ἐφ’ ὅ τι ἧκεν, “θεραπείας,” ἔφη, “αἰτήσων πρὸς ὀδύνην πλευροῦ” —<br>Κυτμίδα χρίεσθαι κέλομαι δροσίην τε κέλητος·<br>τῷ δὲ ἑτέρῳ, ἐπειδὴ καὶ τοῦτο ἠκηκόει ὡς ἐρομένου τοῦ πέμψαντος, εἴτε οἱ πλεῦσαι ἐπ’ Ἰταλίαν εἴτε πεζοπορῆσαι λῷον, ἀπεκρίνατο οὐδὲν πρὸς τὸν Ὅμηρον·<br>μὴ σύ γε πλωέμεναι, πεζὴν δὲ κατ’ οἶμον ὅδευε.", "st": "38.53"}, {"sp": "N", "t": "πολλὰ γὰρ τοιαῦτα καὶ αὐτὸς ἐπεμηχανησάμην αὐτῷ, οἷον καὶ ἐκεῖνο· μίαν ἐρώτησιν ἐρωτήσας ἐπέγραψα τῷ βιβλίῳ κατὰ τὸ ἔθος· “τοῦ δεῖνος χρησμοὶ ὀκτώ,” ψευσάμενός τι ὄνομα, καὶ τὰς ὀκτὼ δραχμὰς καὶ τὸ γιγνόμενον ἔτι πρὸς ταύταις πέμψας· ὁ δὲ πιστεύσας τῇ ἀποπομπῇ τοῦ μισθοῦ καὶ τῇ ἐπιγραφῇ τοῦ βιβλίου, πρὸς μίαν ἐρώτησιν — ἦν δὲ αὕτη· “πότε ἁλώσεται μαγγανεύων Ἀλέξανδρος;” — ὀκτώ μοι χρησμοὺς ἔπεμψεν, οὔτε γῆς φασιν οὔτε οὐρανοῦ ἁπτομένους, ἀνοήτους δὲ καὶ δυσνοήτους ἅπαντας.", "st": "38.54"}, {"sp": "N", "t": "ἅπερ ὕστερον αἰσθόμενος, καὶ ὅτι Ῥουτιλιανὸν ἐγὼ ἀπέτρεπον τοῦ γάμου καὶ τοῦ πάνυ προσκεῖσθαι ταῖς τοῦ χρηστηρίου ἐλπίσιν, ἐμίσει, ὡς τὸ εἰκός, καὶ ἔχθιστον ἡγεῖτο. καί ποτε περὶ ἐμοῦ ἐρομένῳ τῷ Ῥουτιλιανῷ ἔφη·<br>Νυκτιπλάνοις ὀάροις χαίρει κοίταις τε δυσάγνοις.<br>καὶ ὅλως ἔχθιστος εἰκότως ἦν ἐγώ.", "st": "38.54"}, {"sp": "N", "t": "κἀπειδὴ εἰσελθόντα με εἰς τὴν πόλιν ᾔσθετο καὶ ἔμαθεν ὡς ἐκεῖνος εἴην ὁ Λουκιανός — ἐπηγόμην δὲ καὶ στρατιώτας δύο, λογχοφόρον καὶ κοντοφόρον, παρὰ τοῦ ἡγουμένου τῆς Καππαδοκίας, φίλου τότε ὄντος, λαβών, ὥς με παραπέμψειαν μέχρι πρὸς τὴν θάλατταν — αὐτίκα μεταστέλλεται δεξιῶς πάνυ καὶ μετὰ πολλῆς φιλοφροσύνης. ἐλθὼν δὲ ἐγὼ πολλοὺς καταλαμβάνω περὶ αὐτόν· συνεπηγόμην δὲ καὶ τοὺς στρατιώτας τύχῃ τινὶ ἀγαθῇ. καὶ ὁ μὲν προὔτεινέ μοι κύσαι τὴν δεξιάν, ὥσπερ εἰώθει τοῖς πολλοῖς, ἐγὼ δὲ προσφὺς ὡς φιλήσων, δήγματι χρηστῷ πάνυ μικροῦ δεῖν χωλὴν αὐτῷ ἐποίησα τὴν χεῖρα.", "st": "38.55"}, {"sp": "N", "t": "οἱ μὲν οὖν παρόντες ἄγχειν με καὶ παίειν ἐπειρῶντο ὡς ἱερόσυλον, καὶ πρότερον ἔτι ἀγανακτήσαντες ὅτι Ἀλέξανδρον αὐτόν, ἀλλὰ μὴ προφήτην προσεῖπον· ὁ δὲ πάνυ γεννικῶς καρτερήσας κατέπαυέν τε αὐτοὺς καὶ ὑπισχνεῖτο τιθασόν με ῥᾳδίως ἀποφανεῖν καὶ δείξειν τὴν Γλύκωνος ἀρετήν, ὅτι καὶ τοὺς πάνυ τραχυνομένους φίλους ἀπεργάζεται. καὶ μεταστησάμενος ἅπαντας ἐδικαιολογεῖτο πρός με, λέγων πάνυ με εἰδέναι καὶ τὰ ὑπ’ ἐμοῦ Ῥουτιλιανῷ συμβουλευόμενα, καὶ “τί παθὼν ταῦτά με εἰργάσω, δυνάμενος ὑπ’ ἐμοῦ ἐπὶ μέγα προαχθῆναι παρ’ αὐτῷ;” κἀγὼ ἄσμενος ἤδη ἐδεχόμην τὴν φιλοφροσύνην ταύτην ὁρῶν οἷ κινδύνου καθειστήκειν, καὶ μετ’ ὀλίγον προῆλθον φίλος γεγενημένος. καὶ τοῦτο οὐ μικρὸν θαῦμα τοῖς ὁρῶσιν ἔδοξεν, οὕτω ῥᾳδία γενομένη μου ἡ μεταβολή.", "st": "38.55"}, {"sp": "N", "t": "εἶτα δή μου ἐκπλεῖν προαιρουμένου ξένια καὶ δῶρα πολλὰ πέμψας — μόνος δὲ σὺν τῷ Ξενοφῶντι ἔτυχον ἐπιδημῶν, τὸν πατέρα καὶ τοὺς ἐμοὺς εἰς Ἄμαστριν προεκπεπομφώς — ὑπισχνεῖται καὶ πλοῖον αὐτὸς παρέξειν καὶ ἐρέτας τοὺς ἀπάξοντας. κἀγὼ μὲν ᾤμην ἁπλοῦν τι τοῦτο εἶναι καὶ δεξιόν· ἐπεὶ δὲ κατὰ μέσον τὸν πόρον ἐγενόμην, δακρύοντα ὁρῶν τὸν κυβερνήτην καὶ τοῖς ναύταις τι ἀντιλέγοντα οὐκ ἀγαθὰς εἶχον περὶ τῶν μελλόντων ἐλπίδας. ἦν δὲ αὐτοῖς ἐπεσταλμένον ὑπὸ τοῦ Ἀλεξάνδρου ἀραμένους ῥῖψαι ἡμᾶς εἰς τὴν θάλασσαν· ὅπερ εἰ ἐγένετο, ῥᾳδίως ἂν αὐτῷ διεπεπολέμητο τὰ πρὸς ἐμέ. ἀλλὰ δακρύων ἐκεῖνος ἔπεισεν καὶ τοὺς συνναύτας μηδὲν ἡμᾶς δεινὸν ἐργάσασθαι, καὶ πρὸς ἐμὲ ἔφη, “ἔτη ἑξήκοντα, ὡς ὁρᾷς, ἀνεπίληπτον βίον καὶ ὅσιον προβεβηκὼς οὐκ ἂν βουλοίμην, ἐν τούτῳ τῆς ἡλικίας καὶ γυναῖκα καὶ τέκνα ἔχων, μιᾶναι φόνῳ τὰς χεῖρας,” δηλῶν ἐφ’ ὅπερ ἡμᾶς ἀνειλήφει, καὶ τὰ ὑπὸ τοῦ Ἀλεξάνδρου προστεταγμένα.", "st": "38.56"}, {"sp": "N", "t": "καταθέμενος δὲ ἡμᾶς ἐν Αἰγιαλοῖς, ὧν καὶ ὁ καλὸς Ὅμηρος μέμνηται, ὀπίσω ἀπήλαυνον.", "st": "38.57"}, {"sp": "N", "t": "ἔνθα ἐγὼ παραπλέοντας εὑρὼν Βοσποριανούς τινας, πρέσβεις παρ’ Εὐπάτορος τοῦ βασιλέως εἰς τὴν Βιθυνίαν ἀπιόντας ἐπὶ κομιδῇ τῆς ἐπετείου συντάξεως, καὶ διηγησάμενος αὐτοῖς τὸν περιστάντα ἡμᾶς κίνδυνον, καὶ δεξιῶν αὐτῶν τυχών, ἀναληφθεὶς ἐπὶ τὸ πλοῖον διασώζομαι εἰς τὴν Ἄμαστριν, παρὰ τοσοῦτον ἐλθὼν ἀποθανεῖν.", "st": "38.57"}, {"sp": "N", "t": "τοὐντεῦθεν καὶ αὐτὸς ἐπεκορυσσόμην αὐτῷ καὶ πάντα κάλων ἐκίνουν ἀμύνασθαι βουλόμενος, καὶ πρὸ τῆς ἐπιβουλῆς ἤδη μισῶν αὐτὸν καὶ ἔχθιστον ἡγούμενος διὰ τὴν τοῦ τρόπου μιαρίαν, καὶ πρὸς τὴν κατηγορίαν ὡρμήμην πολλοὺς συναγωνιστὰς ἔχων καὶ μάλιστα τοὺς ἀπὸ Τιμοκράτους τοῦ Ἡρακλεώτου φιλοσόφου· ἀλλ’ ὁ τότε ἡγούμενος Βιθυνίας καὶ τοῦ Πόντου Αὔειτος ἐπέσχε, μονονουχὶ ἱκετεύων καὶ ἀντιβολῶν παύσασθαι· διὰ γὰρ τὴν πρὸς Ῥουτιλιανὸν εὔνοιαν μὴ ἂν δύνασθαι, καὶ εἰ φανερῶς λάβοι ἀδικοῦντα, κολάσαι αὐτόν. οὕτω μὲν ἀνεκόπην τῆς ὁρμῆς καὶ ἐπαυσάμην οὐκ ἐν δέοντι θρασυνόμενος ἐφ’ οὕτω δικαστοῦ διακειμένου.", "st": "38.57"}, {"sp": "N", "t": "ἐκεῖνο δὲ πῶς οὐ μέγα ἐν τοῖς ἄλλοις τὸ τόλμημα τοῦ Ἀλεξάνδρου, τὸ αἰτῆσαι παρὰ τοῦ αὐτοκράτορος μετονομασθῆναι τὸ τοῦ Ἀβώνου τεῖχος καὶ Ἰωνόπολιν κληθῆναι, καὶ νόμισμα καινὸν κόψαι ἐγκεχαραγμένον τῇ μὲν τοῦ Γλύκωνος, κατὰ θάτερα δὲ Ἀλεξάνδρου, στέμματά τε τοῦ πάππου Ἀσκληπιοῦ καὶ τὴν ἅρπην ἐκείνην τοῦ πατρομήτορος Περσέως ἔχοντος;", "st": "38.58"}, {"sp": "N", "t": "προειπὼν δὲ διὰ χρησμοῦ περὶ αὑτοῦ ὅτι ζῆσαι εἵμαρται αὐτῷ ἔτη πεντήκοντα καὶ ἑκατόν, εἶτα κεραυνῷ βληθέντα ἀποθανεῖν, οἰκτίστῳ τέλει οὐδὲ ἑβδομήκοντα ἔτη γεγονὼς ἀπέθανεν, ὡς Ποδαλειρίου υἱὸς διασαπεὶς τὸν πόδα μέχρι τοῦ βουβῶνος καὶ σκωλήκων ζέσας· ὅτεπερ καὶ ἐφωράθη φαλακρὸς ὤν, παρέχων τοῖς ἰατροῖς ἐπιβρέχειν αὐτοῦ τὴν κεφαλὴν διὰ τὴν ὀδύνην, ὃ οὐκ ἂν ποιῆσαι ἐδύναντο μὴ οὐχὶ τῆς φενάκης ἀφῃρημένης.", "st": "38.59"}, {"sp": "N", "t": "τοιοῦτο τέλος τῆς Ἀλεξάνδρου τραγῳδίας καὶ αὕτη τοῦ παντὸς δράματος ἡ καταστροφὴ ἐγένετο, ὡς εἰκάζειν προνοίας τινὸς τὸ τοιοῦτον, εἰ καὶ κατὰ τύχην συνέβη. ἔδει δὲ καὶ τὸν ἐπιτάφιον αὐτοῦ ἄξιον γενέσθαι τοῦ βίου, καὶ ἀγῶνά τινα συστήσασθαι ὑπὲρ τοῦ χρηστηρίου, τῶν συνωμοτῶν ἐκείνων καὶ γοήτων, ὅσοι κορυφαῖοι ἦσαν, ἀνελθόντων ἐπὶ διαιτητὴν τὸν Ῥουτιλιανόν, τίνα χρὴ προκριθῆναι αὐτῶν καὶ διαδέξασθαι τὸ μαντεῖον καὶ στεφανωθῆναι τῷ ἱεροφαντικῷ καὶ προφητικῷ στέμματι. ἦν δὲ ἐν αὐτοῖς καὶ Παῖτος, ἰατρὸς τὴν τέχνην, πολιός τις, οὔτε ἰατρῷ πρέποντα οὔτε πολιῷ ἀνδρὶ ταῦτα ποιῶν. ἀλλ’ ὁ ἀγωνοθέτης Ῥουτιλιανὸς ἀστεφανώτους αὐτοὺς ἀπέπεμψεν αὐτῷ τὴν προφητείαν φυλάττων μετὰ τὴν ἐντεῦθεν ἀπαλλαγήν.", "st": "38.60"}, {"sp": "N", "t": "ταῦτα, ὦ φιλότης, ὀλίγα ἐκ πολλῶν δείγματος ἕνεκα γράψαι ἠξίωσα, καὶ σοὶ μὲν χαριζόμενος, ἀνδρὶ ἑταίρῳ καὶ φίλῳ καὶ ὃν ἐγὼ πάντων μάλιστα θαυμάσας ἔχω ἐπί τε σοφίᾳ καὶ τῷ πρὸς ἀλήθειαν ἔρωτι καὶ τρόπου πραότητι καὶ ἐπιεικείᾳ καὶ γαλήνῃ βίου καὶ δεξιότητι πρὸς τοὺς συνόντας, τὸ πλέον δέ, — ὅπερ καὶ σοὶ ἥδιον, — Ἐπικούρῳ τιμωρῶν, ἀνδρὶ ὡς ἀληθῶς ἱερῷ καὶ θεσπεσίῳ τὴν φύσιν καὶ μόνῳ μετ’ ἀληθείας τὰ καλὰ ἐγνωκότι καὶ παραδεδωκότι καὶ ἐλευθερωτῇ τῶν ὁμιλησάντων αὐτῷ γενομένῳ. οἶμαι δὲ ὅτι καὶ τοῖς ἐντυχοῦσι χρήσιμόν τι ἔχειν δόξει ἡ γραφή, τὰ μὲν διεξελέγχουσα, τὰ δὲ ἐν ταῖς τῶν εὖ φρονούντων γνώμαις βεβαιοῦσα.", "st": "38.61"}, {"sp": "HDR", "t": "Εἰκόνες"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἀλλ’ ἦ τοιοῦτόν τι ἔπασχον οἱ τὴν Γοργὼ ἰδόντες οἷον ἐγὼ ἔναγχος ἔπαθον, ὦ Πολύστρατε, παγκάλην τινὰ γυναῖκα ἰδών· αὐτὸ γὰρ τὸ τοῦ μύθου ἐκεῖνο, μικροῦ δέω λίθος ἐξ ἀνθρώπου σοι γεγονέναι πεπηγὼς ὑπὸ τοῦ θαύματος.", "st": "39.1"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> Ἡράκλεις, ὑπερφυές τι τὸ θέαμα φὴς καὶ δεινῶς βίαιον, εἴ γε καὶ Λυκῖνον ἐξέπληξε γυνή τις οὖσα· σὺ γὰρ ὑπὸ μὲν τῶν μειρακίων καὶ πάνυ ῥᾳδίως αὐτὸ πάσχεις, ὥστε θᾶττον ἄν τις ὅλον τὸν Σίπυλον μετακινήσειεν ἢ σὲ τῶν καλῶν ἀπάγοι μὴ οὐχὶ παρεστάναι αὐτοῖς κεχηνότα καὶ ἐπιδακρύοντά γε πολλάκις ὥσπερ ἐκείνην αὐτὴν τὴν τοῦ Ταντάλου. ἀτὰρ εἰπέ μοι, τίς ἡ λιθοποιὸς αὕτη Μέδουσα ἡμῖν ἐστιν καὶ πόθεν, ὡς καὶ ἡμεῖς ἴδοιμεν· οὐ γάρ, οἶμαι, φθονήσεις ἡμῖν τῆς θέας οὐδὲ ζηλοτυπήσεις, εἰ μέλλοιμεν πλησίον που καὶ αὐτοὶ παραπεπηγέναι σοι ἰδόντες.", "st": "39.1"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> καὶ μὴν εὖ εἰδέναι χρή σε, ὡς κἂν ἐκ περιωπῆς μόνον ἀπίδῃς εἰς αὐτήν, ἀχανῆ σε καὶ τῶν ἀνδριάντων ἀκινητότερον ἀποφανεῖ. καίτοι τοῦτο μὲν ἴσως εἰρηνικώτερόν ἐστιν καὶ τὸ τραῦμα ἧττον καίριον, εἰ αὐτὸς ἴδοις· εἰ δὲ κἀκείνη προσβλέψειέ σε, τίς ἔσται μηχανὴ ἀποστῆναι αὐτῆς; ἀπάξει γάρ σε ἀναδησαμένη ἔνθα ἂν ἐθέλῃ, ὅπερ καὶ ἡ λίθος ἡ Ἡρακλεία δρᾷ τὸν σίδηρον.", "st": "39.1"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> παύου, ὦ Λυκῖνε, τεράστιόν τι κάλλος ἀναπλάττων, ἀλλ’ εἰπέ, τίς ἡ γυνή ἐστιν.", "st": "39.2"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> οἴει γάρ με ὑπερβαλέσθαι τῷ λόγῳ, ὃς δέδια μή σοι ἰδόντι ἀσθενής τις ἐπαινέσαι δόξω, παρὰ τοσοῦτον ἀμείνων φανεῖται; πλὴν ἀλλὰ ἥτις μέν, οὐκ ἂν εἰπεῖν ἔχοιμι, θεραπεία δὲ πολλὴ καὶ ἡ ἄλλη περὶ αὐτὴν παρασκευὴ λαμπρὰ καὶ εὐνούχων τι πλῆθος καὶ ἅβραι πάνυ πολλαί, καὶ ὅλως μεῖζόν γε ἢ κατὰ ἰδιωτικὴν τύχην ἐδόκει τὸ πρᾶγμα εἶναι.", "st": "39.2"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> οὐδὲ τοὔνομα ἐπύθου σύ γε ἥτις καλοῖτο;", "st": "39.2"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> οὐδαμῶς, ἢ τοῦτο μόνον, τῆς Ἰωνίας ἐστίν· τῶν θεατῶν γάρ τις ἀπιδὼν εἰς τὸν πλησίον, ἐπεὶ παρῆλθεν, “τοιαῦτα μέντοι,” ἔφη, “τὰ Σμυρναϊκὰ κάλλη· καὶ θαυμαστὸν οὐδέν, εἰ ἡ καλλίστη τῶν Ἰωνικῶν πόλεων τὴν καλλίστην γυναῖκα ἤνεγκεν.” ἐδόκει δέ μοι Σμυρναῖος καὶ αὐτὸς ὁ λέγων εἶναι, οὕτως ἐσεμνύνετο ἐπ’ αὐτῇ.", "st": "39.2"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> οὐκοῦν ἐπεὶ λίθου τοῦτό γε ὡς ἀληθῶς ἐποίησας οὔτε παρακολουθήσας οὔτε τὸν Σμυρναῖον ἐκεῖνον ἐρόμενος, ὅστις ἦν, κἂν τὸ εἶδος ὡς οἷόν τε ὑπόδειξον τῷ λόγῳ· τάχα γὰρ ἂν οὕτως γνωρίσαιμι.", "st": "39.3"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ὁρᾷς ἡλίκον τοῦτο ᾔτησας; οὐ κατὰ λόγων δύναμιν, καὶ μάλιστά γε τῶν ἐμῶν, ἐμφανίσαι θαυμασίαν οὕτως εἰκόνα, πρὸς ἣν μόλις ἂν ἢ Ἀπελλῆς ἢ Ζεῦξις ἢ Παρράσιος ἱκανοὶ ἔδοξαν, ἢ εἴ τις Φειδίας ἢ Ἀλκαμένης· ἐγὼ δὲ λυμανοῦμαι τὸ ἀρχέτυπον ἀσθενείᾳ τῆς τέχνης.", "st": "39.3"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> ὅμως, ὦ Λυκῖνε, ποία τις τὴν ὄψιν; οὐ γὰρ ἐπισφαλὲς τὸ τόλμημα, εἰ φίλῳ ἀνδρὶ ἐπιδείξαις τὴν εἰκόνα, ὅπως ἂν τῆς γραμμῆς ἔχῃ.", "st": "39.3"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> καὶ μὴν ἀσφαλέστερον αὐτὸς ποιήσειν μοι δοκῶ τῶν παλαιῶν τινας ἐκείνων τεχνιτῶν παρακαλέσας ἐπὶ τὸ ἔργον, ὡς ἀναπλάσειάν μοι τὴν γυναῖκα.", "st": "39.3"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> πῶς τοῦτο φής; ἢ πῶς ἂν ἀφίκοιντό σοι πρὸ τοσούτων ἐτῶν ἀποθανόντες;", "st": "39.3"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ῥᾳδίως, ἤνπερ σὺ μὴ ὀκνήσῃς ἀποκρίνασθαί τί μοι.", "st": "39.3"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> ἐρώτα μόνον.", "st": "39.3"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἐπεδήμησάς ποτε, ὦ Πολύστρατε, τῇ Κνιδίων;", "st": "39.4"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> καὶ μάλα.", "st": "39.4"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> οὐκοῦν καὶ τὴν Ἀφροδίτην εἶδες πάντως αὐτῶν;", "st": "39.4"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> νὴ Δία, τῶν Πραξιτέλους ποιημάτων τὸ κάλλιστον.", "st": "39.4"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἀλλὰ καὶ τὸν μῦθον ἤκουσας, ὃν λέγουσιν οἱ ἐπιχώριοι περὶ αὐτῆς, ὡς ἐρασθείη τις τοῦ ἀγάλματος καὶ λαθὼν ὑπολειφθεὶς ἐν ἱερῷ συγγένοιτο, ὡς δυνατὸν ἀγάλματι. τοῦτο μέντοι ἄλλως ἱστορείσθω. σὺ δὲ — ταύτην γάρ, ὡς φής, εἶδες — ἴθι μοὶ καὶ τόδε ἀπόκριναι, εἰ καὶ τὴν ἐν κήποις Ἀθήνησι τὴν Ἀλκαμένους ἑώρακας.", "st": "39.4"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> ἦ πάντων γ’ ἄν, ὦ Λυκῖνε, ὁ ῥᾳθυμότατος ἦν, εἰ τὸ κάλλιστον τῶν Ἀλκαμένους πλασμάτων παρεῖδον.", "st": "39.4"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἐκεῖνο μέν γε, ὦ Πολύστρατε, οὐκ ἐξερήσομαί σε, εἰ πολλάκις εἰς τὴν ἀκρόπολιν ἀνελθὼν καὶ τὴν Καλάμιδος Σωσάνδραν τεθέασαι.", "st": "39.4"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> εἶδον κἀκείνην πολλάκις.", "st": "39.4"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἀλλὰ καὶ ταῦτα μὲν ἱκανῶς. τῶν δὲ Φειδίου ἔργων τί μάλιστα ἐπῄνεσας;", "st": "39.4"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> τί δ’ ἄλλο ἢ τὴν Λημνίαν, ᾗ καὶ ἐπιγράψαι τοὔνομα ὁ Φειδίας ἠξίωσε; καὶ νὴ Δία τὴν Ἀμαζόνα τὴν ἐπερειδομένην τῷ δορατίῳ.", "st": "39.4"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> τὰ κάλλιστα, ὦ ἑταῖρε, ὥστ’ οὐκέτ’ ἄλλων τεχνιτῶν δεήσει. φέρε δή, ἐξ ἁπασῶν ἤδη τούτων ὡς οἷόν τε συναρμόσας μίαν σοι εἰκόνα ἐπιδείξω, τὸ ἐξαίρετον παρ’ ἑκάστης ἔχουσαν.", "st": "39.5"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> καὶ τίνα ἂν τρόπον τουτὶ γένοιτο;", "st": "39.5"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> οὐ χαλεπόν, ὦ Πολύστρατε, εἰ τὸ ἀπὸ τοῦδε παραδόντες τὰς εἰκόνας τῷ λόγῳ, ἐπιτρέψαιμεν αὐτῷ μετακοσμεῖν καὶ συντιθέναι καὶ ἁρμόζειν ὡς ἂν εὐρυθμότατα δύναιτο, φυλάττων ἅμα τὸ συμμιγὲς ἐκεῖνο καὶ ποικίλον.", "st": "39.5"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> εὖ λέγεις· καὶ δὴ παραλαβὼν δεικνύτω· ἐθέλω γὰρ εἰδέναι ὅ τι καὶ χρήσεται αὐταῖς, ἢ ὅπως ἐκ τοσούτων μίαν τινὰ συνθεὶς οὐκ ἀπᾴδουσαν ἀπεργάσεται.", "st": "39.5"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> καὶ μὴν ἤδη σοι ὁρᾶν παρέχει γιγνομένην τὴν εἰκόνα, ὧδε συναρμόζων, τῆς ἐκ Κνίδου ἡκούσης μόνον τὴν κεφαλὴν λαβών·· οὐδὲν γὰρ τοῦ ἄλλου σώματος γυμνοῦ ὄντος δεήσεται· τὰ μὲν ἀμφὶ τὴν κόμην καὶ μέτωπον ὀφρύων τε τὸ εὔγραμμον ἐάσει ἔχειν ὥσπερ ὁ Πραξιτέλης ἐποίησεν, καὶ τῶν ὀφθαλμῶν δὲ τὸ ὑγρὸν ἅμα τῷ φαιδρῷ καὶ κεχαρισμένῳ, καὶ τοῦτο διαφυλάξει κατὰ τὸ Πραξιτέλει δοκοῦν· τὰ μῆλα δὲ καὶ ὅσα τῆς ὄψεως ἀντωπὰ παρ’ Ἀλκαμένους καὶ τῆς ἐν κήποις λήψεται, καὶ προσέτι χειρῶν ἄκρα καὶ καρπῶν τὸ εὔρυθμον καὶ δακτύλων τὸ εὐάγωγον εἰς λεπτὸν ἀπολῆγον παρὰ τῆς ἐν κήποις καὶ ταῦτα. τὴν δὲ τοῦ παντὸς προσώπου περιγραφὴν καὶ παρειῶν τὸ ἁπαλὸν καὶ ῥῖνα σύμμετρον ἡ Λημνία παρέξει καὶ Φειδίας· ἔτι καὶ στόματος ἁρμογὴν αὐτὸς καὶ τὸν αὐχένα, παρὰ τῆς Ἀμαζόνος λαβών· ἡ Σωσάνδρα δὲ καὶ Κάλαμις αἰδοῖ κοσμήσουσιν αὐτήν, καὶ τὸ μειδίαμα σεμνὸν καὶ λεληθὸς ὥσπερ τὸ ἐκείνης ἔσται· καὶ τὸ εὐσταλὲς δὲ καὶ κόσμιον τῆς ἀναβολῆς παρὰ τῆς Σωσάνδρας, πλὴν ὅτι ἀκατακάλυπτος αὕτη ἔσται τὴν κεφαλήν. τῆς ἡλικίας δὲ τὸ μέτρον ἡλίκον ἂν γένοιτο, κατὰ τὴν ἐν Κνίδῳ ἐκείνην μάλιστα. καὶ γὰρ καὶ τοῦτο κατὰ τὸν Πραξιτέλη μεμετρήσθω.", "st": "39.6"}, {"sp": "N", "t": "τί σοι, ὦ Πολύστρατε, δοκεῖ; καλὴ γενήσεσθαι ἡ εἰκών;", "st": "39.6"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> καὶ μάλιστα, ἐπειδὰν εἰς τὸ ἀκριβέστατον ἀποτελεσθῇ·", "st": "39.6"}, {"sp": "N", "t": "ἔτι γάρ, ὦ πάντων γενναιότατε, καταλέλοιπάς τι κάλλος ἔξω τοῦ ἀγάλματος οὕτως πάντα εἰς τὸ αὐτὸ συμπεφορηκώς.", "st": "39.7"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> τί τοῦτο;", "st": "39.7"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> οὐ τὸ μικρότατον, ὦ φιλότης, εἰ μή σοι δόξει ὀλίγα πρὸς εὐμορφίαν συντελεῖν χρόα καὶ τὸ ἑκάστῳ πρέπον, ὡς μέλανα μὲν εἶναι ἀκριβῶς ὁπόσα μέλανα, λευκὰ δὲ ὅσα τοιαῦτα χρή, καὶ τὸ ἐρύθημα ἐπανθεῖν καὶ τὰ τοιαῦτα· κινδυνεύει τοῦ μεγίστου ἔτι ἡμῖν προσδεῖν.", "st": "39.7"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> πόθεν οὖν καὶ ταῦτα πορισαίμεθ’ ἄν; ἢ παρακαλέσαιμεν δηλαδὴ τοὺς γραφέας, καὶ μάλιστα ὁπόσοι αὐτῶν ἄριστοι ἐγένοντο κεράσασθαι τὰ χρώματα καὶ εὔκαιρον ποιεῖσθαι τὴν ἐπιβολὴν αὐτῶν; καὶ δὴ παρακεκλήσθω Πολύγνωτος καὶ Εὐφράνωρ ἐκεῖνος καὶ Ἀπελλῆς καὶ Ἀετίων· οὗτοι δὲ διελόμενοι τὸ ἔργον ὁ μὲν Εὐφράνωρ χρωσάτω τὴν κόμην οἵαν τῆς Ἥρας ἔγραψεν, ὁ Πολύγνωτος δὲ ὀφρύων τὸ ἐπιπρεπὲς καὶ παρειῶν τὸ ἐνερευθὲς οἵαν τὴν Κασάνδραν ἐν τῇ λέσχῃ ἐποίησεν τοῖς Δελφοῖς, καὶ ἐσθῆτα δὲ οὗτος ποιησάτω εἰς τὸ λεπτότατον ἐξειργασμένην, ὡς συνεστάλθαι μὲν ὅσα χρή, διηνεμῶσθαι δὲ τὰ πολλά· τὸ δὲ ἄλλο σῶμα ὁ Ἀπελλῆς δειξάτω κατὰ τὴν Πακάτην μάλιστα, μὴ ἄγαν λευκὸν ἀλλὰ ἔναιμον ἁπλῶς· τὰ χείλη δὲ οἷα Ῥωξάνης ὁ Ἀετίων ποιησάτω.", "st": "39.7"}, {"sp": "N", "t": "μᾶλλον δὲ τὸν ἄριστον τῶν γραφέων Ὅμηρον παρόντος Εὐφράνορος καὶ Ἀπελλοῦ δεδέγμεθα· οἷον γάρ τι τοῖς Μενελάου μηροῖς τὸ χρῶμα ἐκεῖνος ἐπέβαλεν ἐλέφαντι εἰκάσας ἠρέμα πεφοινιγμένῳ, τοιόνδε ἔστω τὸ πᾶν· ὁ δ’ αὐτὸς οὗτος καὶ τοὺς ὀφθαλμοὺς γραψάτω βοῶπίν τινα ποιήσας αὐτήν. συνεπιλήψεται δὲ τοῦ ἔργου αὐτῷ καὶ ὁ Θηβαῖος ποιητής, ὡς ἰοβλέφαρον ἐξεργάσασθαι· καὶ φιλομειδῆ δὲ Ὅμηρος ποιήσει καὶ λευκώλενον καὶ ῥοδοδάκτυλον, καὶ ὅλως τῇ χρυσῇ Ἀφροδίτῃ εἰκάσει πολὺ δικαιότερον ἢ τὴν τοῦ Βρισέως.", "st": "39.8"}, {"sp": "N", "t": "ταῦτα μὲν οὖν πλαστῶν καὶ γραφέων καὶ ποιητῶν παῖδες ἐργάσονται. ὃ δὲ πᾶσιν ἐπανθεῖ τούτοις, ἡ χάρις, μᾶλλον δὲ πᾶσαι ἅμα ὁπόσαι Χάριτες καὶ ὁπόσοι Ἔρωτες περιχορεύοντες, τίς ἂν μιμήσασθαι δύναιτο;", "st": "39.9"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> θεσπέσιόν τι χρῆμα, ὦ Λυκῖνε, φὴς καὶ διιπετὲς ὡς ἀληθῶς, οἷόν τι τῶν ἐξ οὐρανοῦ γένοιτο. τί δὲ πράσσουσαν εἶδες αὐτήν;", "st": "39.9"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> βιβλίον ἐν ταῖν χεροῖν εἶχεν εἰς δύο συνειλημένον, καὶ ἐῴκει τὸ μέν τι ἀναγιγνώσκεσθαι αὐτοῦ, τὸ δὲ ἤδη ἀνεγνωκέναι. μεταξὺ δὲ προϊοῦσα διελέγετο τῶν παρομαρτούντων τινὶ οὐκ οἶδα ὅ τι· οὐ γὰρ εἰς ἐπήκοον ἐφθέγγετο. πλὴν μειδιάσασά γε, ὦ Πολύστρατε, ὀδόντας ἐξέφηνε πῶς ἂν εἴποιμί σοι ὅπως μὲν λευκούς, ὅπως δὲ συμμέτρους καὶ πρὸς ἀλλήλους συνηρμοσμένους; εἴ που κάλλιστον ὅρμον εἶδες ἐκ τῶν στιλπνοτάτων καὶ ἰσομεγεθῶν μαργαριτῶν, οὕτως ἐπὶ στίχου ἐπεφύκεσαν· ἐκοσμοῦντο δὲ μάλιστα τῷ τῶν χειλῶν ἐρυθήματι. ὑπεφαίνοντο γοῦν, αὐτὸ δὴ τὸ τοῦ Ὁμήρου, ἐλέφαντι τῷ πριστῷ ὅμοιοι, οὐχ οἱ μὲν πλατύτεροι αὐτῶν, οἱ δὲ γυροί, οἱ δὲ προέχοντες ἢ διεστηκότες οἷοι ταῖς πλείσταις, ἀλλά τις πάντων ἰσοτιμία καὶ ὁμόχροια καὶ μέγεθος ἓν καὶ προσεχεῖς ὁμοίως, καὶ ὅλως μέγα τι θαῦμα καὶ θέαμα πᾶσαν τὴν ἀνθρωπίνην εὐμορφίαν ὑπερπεπαικός.", "st": "39.9"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> ἔχ’ ἀτρέμας. συνίημι γὰρ ἤδη πάνυ σαφῶς ἥντινα καὶ λέγεις τὴν γυναῖκα, τούτοις τε αὐτοῖς γνωρίσας καὶ τῇ πατρίδι. καὶ εὐνούχους δέ τινας ἕπεσθαι αὐτῇ ἔφης.", "st": "39.10"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> νὴ Δία, καὶ στρατιώτας τινάς.", "st": "39.10"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> τὴν βασιλεῖ συνοῦσαν, ὦ μακάριε, τὴν ἀοίδιμον ταύτην λέγεις.", "st": "39.10"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> τί δέ ἐστιν αὐτῇ τοὔνομα;", "st": "39.10"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> πάνυ καὶ τοῦτο γλαφυρόν, ὦ Λυκῖνε, καὶ ἐπέραστον· ὁμώνυμος γάρ ἐστιν τῇ τοῦ Ἀβραδάτα ἐκείνῃ τῇ καλῇ· οἶσθα πολλάκις ἀκούσας Ξενοφῶντος ἐπαινοῦντός τινα σώφρονα καὶ καλὴν γυναῖκα.", "st": "39.10"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> νὴ Δία, καὶ ὥσπερ γε ὁρῶν αὐτὴν οὕτω διατέθειμαι, ὁπόταν κατ’ ἐκεῖνό που ἀναγιγνώσκων γένωμαι, καὶ μονονουχὶ καὶ ἀκούω λεγούσης αὐτῆς ἃ πεποίηται λέγουσα, καὶ ὡς ὥπλιζε τὸν ἄνδρα καὶ οἵα ἦν παραπέμπουσα αὐτὸν ἐπὶ τὴν μάχην.", "st": "39.10"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> ἀλλ’, ὦ ἄριστε, σὺ μὲν ὥσπερ τινὰ ἀστραπὴν παραδραμοῦσαν ἅπαξ εἶδες αὐτήν, καὶ ἔοικας τὰ πρόχειρα ταῦτα, λέγω δὲ τὸ σῶμα καὶ τὴν μορφήν, ἐπαινεῖν· τῶν δὲ τῆς ψυχῆς ἀγαθῶν ἀθέατος εἶ, οὐδὲ οἶσθα ὅσον τὸ κάλλος ἐκεῖνό ἐστιν αὐτῆς, μακρῷ τινι ἄμεινον καὶ θεοειδέστερον τοῦ σώματος. ἐγὼ δὲ συνήθης γάρ εἰμι καὶ λόγων ἐκοινώνησα πολλάκις ὁμοεθνὴς ὤν. καὶ γάρ, ὡς οἶσθα καὶ αὐτός, τὸ ἥμερον καὶ φιλάνθρωπον καὶ τὸ μεγαλόφρον καὶ σωφροσύνην καὶ παιδείαν πρὸ τοῦ κάλλους ἐπαινῶ· ἄξια γὰρ προκεκρίσθαι ταῦτα τοῦ σώματος· ἐπεὶ ἄλογον ἂν εἴη καὶ γελοῖον, ὥσπερ εἴ τις τὴν ἐσθῆτα πρὸ τοῦ σώματος θαυμάζοι. τὸ δ’ ἐντελὲς κάλλος, οἶμαι, τοῦτό ἐστιν, ὁπόταν εἰς τὸ αὐτὸ συνδράμῃ ψυχῆς ἀρετὴ καὶ εὐμορφία σώματος. ἀμέλει πολλὰς ἄν σοι δείξαιμι μορφῆς μὲν εὖ ἡκούσας, τὰ δ’ ἄλλα αἰσχυνούσας τὸ κάλλος, ὡς καὶ μόνον φθεγξαμένων ἀπανθεῖν αὐτὸ καὶ ἀπομαραίνεσθαι ἐλεγχόμενόν τε καὶ ἀσχημονοῦν καὶ παρ’ ἀξίαν συνὸν πονηρᾷ τινι δεσποίνῃ τῇ ψυχῇ. καὶ αἵ γε τοιαῦται ὅμοιαί μοι δοκοῦσιν τοῖς Αἰγυπτίοις ἱεροῖς· κἀκεῖ γὰρ αὐτὸς μὲν ὁ νεὼς κάλλιστός τε καὶ μέγιστος, λίθοις τοῖς πολυτελέσιν ἠσκημένος καὶ χρυσῷ καὶ γραφαῖς διηνθισμένος, ἔνδον δὲ ἢν ζητῇς τὸν θεόν, ἢ πίθηκός ἐστιν ἢ ἶβις ἢ τράγος ἢ αἴλουρος. τοιαύτας πολλὰς ἰδεῖν ἔνεστιν.", "st": "39.11"}, {"sp": "N", "t": "Οὐ τοίνυν ἀπόχρη τὸ κάλλος, εἰ μὴ κεκόσμηται τοῖς δικαίοις κοσμήμασι, λέγω δὴ οὐκ ἐσθῆτι ἁλουργεῖ καὶ ὅρμοις, ἀλλ’ οἷς προεῖπον ἐκείνοις, ἀρετῇ καὶ σωφροσύνῃ καὶ ἐπιεικείᾳ καὶ φιλανθρωπίᾳ καὶ τοῖς ἄλλοις ὁπόσα ταύτης ὅρος ἐστίν.", "st": "39.11"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> οὐκοῦν, ὦ Πολύστρατε, μῦθον ἀντὶ μύθου ἄμειψαι αὐτῷ τῷ μέτρῳ, φασίν, ἢ καὶ λώϊον, δύνασαι γάρ, καί τινα εἰκόνα γραψάμενος τῆς ψυχῆς ἐπίδειξον, ὡς μὴ ἐξ ἡμισείας θαυμάζοιμι αὐτήν.", "st": "39.12"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> οὐ μικρόν, ὦ ἑταῖρε, τὸ ἀγώνισμα προστάττεις· οὐ γὰρ ὅμοιον τὸ πᾶσι προφανὲς ἐπαινέσαι καὶ τὰ ἄδηλα ἐμφανίσαι τῷ λόγῳ. καί μοι δοκῶ συνεργῶν καὶ αὐτὸς δεήσεσθαι πρὸς τὴν εἰκόνα, οὐ πλαστῶν οὐδὲ γραφέων μόνον, ἀλλὰ καὶ φιλοσόφων, ὡς πρὸς τοὺς ἐκείνων κανόνας ἀπευθῦναι τὸ ἄγαλμα καὶ δεῖξαι κατὰ τὴν ἀρχαίαν πλαστικὴν κατεσκευασμένον.", "st": "39.13"}, {"sp": "N", "t": "καὶ δὴ πεποιήσθω. αὐδήεσσα μὲν τὸ πρῶτον καὶ λίγεια, καὶ τὸ “γλυκίων μέλιτος ἀπὸ τῆς γλώττης” περὶ αὐτῆς μᾶλλον ἢ περὶ τοῦ Πυλίου γέροντος ἐκείνου ὁ Ὅμηρος εἴρηκεν. πᾶς δὲ ὁ τόνος τοῦ φθέγματος οἷος ἁπαλώτατος, οὔτε βαρὺς ὡς εἰς τὸ ἀνδρεῖον ἡρμόσθαι οὔτε πάνυ λεπτὸς ὡς θηλύτατός τε εἶναι καὶ κομιδῇ ἔκλυτος, ἀλλ’ οἷος γένοιτ’ ἂν παιδὶ μήπω ἡβάσκοντι, ἡδὺς καὶ προσηνὴς καὶ πράως παραδυόμενος εἰς τὴν ἀκοήν, ὡς καὶ παυσαμένης ἔναυλον εἶναι τὴν βοὴν καί τι λείψανον ἐνδιατρίβειν καὶ περιβομβεῖν τὰ ὦτα, καθάπερ ἠχώ τινα παρατείνουσαν τὴν ἀκρόασιν καὶ ἴχνη τῶν λόγων μελιχρὰ ἄττα καὶ πειθοῦς μεστὰ ἐπὶ τῆς ψυχῆς ἀπολιμπάνουσαν. ὁπόταν δὲ καὶ τὸ καλὸν ἐκεῖνο ᾄδῃ, καὶ μάλιστα πρὸς τὴν κιθάραν, τότε δὴ τότε ὥρα μὲν σιωπᾶν τάχιστα ἀλκυόσι καὶ τέττιξι καὶ τοῖς κύκνοις· ἄμουσα γὰρ ὡς πρὸς ἐκείνην ἅπαντα· κἂν τὴν Πανδίονος εἴπῃς, ἰδιῶτις κἀκείνη καὶ ἄτεχνος, εἰ καὶ πολυηχέα τὴν φωνὴν ἀφίησιν.", "st": "39.13"}, {"sp": "N", "t": "Ὀρφεὺς δὲ καὶ Ἀμφίων, οἵπερ ἐπαγωγότατοι ἐγένοντο τῶν ἀκροατῶν, ὡς καὶ τὰ ἄψυχα ἐπικαλέσασθαι πρὸς τὸ μέλος, αὐτοὶ ἄν, οἶμαι, εἴ γε ἤκουσαν, καταλιπόντες ἂν τὰς κιθάρας παρεστήκεσαν σιωπῇ ἀκροώμενοι. τὸ γὰρ τῆς τε ἁρμονίας τὸ ἀκριβέστατον διαφυλάττειν, ὡς μὴ παραβαίνειν τι τοῦ ῥυθμοῦ, ἀλλ’ εὐκαίρῳ τῇ ἄρσει καὶ θέσει διαμεμετρῆσθαι τὸ ᾆσμα καὶ συνῳδὸν εἶναι τὴν κιθάραν καὶ ὁμοχρονεῖν τῇ γλώττῃ τὸ πλῆκτρον, καὶ τὸ εὐαφὲς τῶν δακτύλων καὶ τὸ εὐκαμπὲς τῶν μελῶν, πόθεν ἂν ταῦτα ὑπῆρχε τῷ Θρᾳκὶ ἐκείνῳ καὶ τῷ ἀνὰ τὸν Κιθαιρῶνα μεταξὺ βουκολοῦντι καὶ κιθαρίζειν μελετῶντι;", "st": "39.14"}, {"sp": "N", "t": "ὥστε ἤν ποτε, ὦ Λυκῖνε, καὶ ᾀδούσης ἀκούῃς αὐτῆς, οὐκέτι τὸ τῶν Γοργόνων ἐκεῖνο ἔσῃ μόνον πεπονθώς, λίθος ἐξ ἀνθρώπου γενόμενος, ἀλλὰ καὶ τὸ τῶν Σειρήνων εἴσῃ ὁποῖόν τι ἦν· παρεστήξῃ γὰρ εὖ οἶδα κεκηλημένος, πατρίδος καὶ οἰκείων ἐπιλαθόμενος. καὶ ἢν κηρῷ ἐπιφράξῃ τὰ ὦτα, καὶ διὰ τοῦ κηροῦ διαδύσεταί σοι τὸ μέλος. τοιοῦτόν τι ἄκουσμά ἐστι, Τερψιχόρης τινὸς ἢ Μελπομένης ἢ Καλλιόπης αὐτῆς παίδευμα, μυρία τὰ θέλγητρα καὶ παντοῖα ἐν ἑαυτῷ ἔχον. ἑνί τε λόγῳ συνελὼν φαίην ἄν, τοιαύτης μοι τῆς ᾠδῆς ἀκούειν νόμιζε, οἵαν εἰκὸς εἶναι τὴν διὰ τοιούτων χειλῶν, δι’ ἐκείνων δὲ τῶν ὀδόντων ἐξιοῦσαν. ἑώρακας δὲ καὶ αὐτὸς ἥν φημι, ὥστε ἀκηκοέναι νόμιζε.", "st": "39.14"}, {"sp": "N", "t": "τὸ μὲν γὰρ ἀκριβὲς τοῦτο τῆς φωνῆς καὶ καθαρῶς Ἰωνικὸν καὶ ὅτι ὁμιλῆσαι στωμύλη καὶ πολὺ τῶν Ἀττικῶν χαρίτων ἔχουσα οὐδὲ θαυμάζειν ἄξιον· πάτριον γὰρ αὐτῇ καὶ προγονικόν, οὐδὲ ἄλλως ἐχρῆν μετέχουσαν τῶν Ἀθηναίων κατὰ τὴν ἀποικίαν. οὐδὲ γὰρ οὐδὲ ἐκεῖνο θαυμάσαιμ’ ἄν, εἰ καὶ ποιήσει χαίρει καὶ τὰ πολλὰ ταύτῃ ὁμιλεῖ, τοῦ Ὁμήρου πολῖτις οὖσα.", "st": "39.15"}, {"sp": "N", "t": "μία μὲν δή σοι, ὦ Λυκῖνε, καλλιφωνίας αὕτη καὶ ᾠδῆς εἰκών, ὡς ἄν τις ἐπὶ τὸ ἔλαττον εἰκάσειεν. σκόπει δὲ δὴ καὶ τὰς ἄλλας· οὐ γὰρ μίαν ὥσπερ σὺ ἐκ πολλῶν συνθεὶς ἐπιδεῖξαι διέγνωκα — ἧττον γὰρ τοῦτο καὶ γραφικόν, συντελεσθὲν κάλλη τοσαῦτα καὶ πολυειδές τι ἐκ πολλῶν ἀποτελεῖν αὐτὸ αὑτῷ ἀνθαμιλλώμενον — ἀλλ’ αἱ πᾶσαι τῆς ψυχῆς ἀρεταὶ καθ’ ἑκάστην εἰκὼν μία γεγράψεται πρὸς τὸ ἀρχέτυπον μεμιμημένη.", "st": "39.15"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἑορτήν, ὦ Πολύστρατε, καὶ πανδαισίαν ἐπαγγέλλεις. ἔοικας γοῦν λώϊον ὡς ἀληθῶς ἀποδώσειν μοι τὸ μέτρον. ἐπιμέτρει δ’ οὖν· ὡς οὐκ ἔστιν ὅ τι ἂν ἄλλο ποιήσας μᾶλλον χαρίσαιό μοι.", "st": "39.15"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> οὐκοῦν ἐπειδὴ πάντων καλῶν παιδείαν ἡγεῖσθαι ἀνάγκη, καὶ μάλιστα τούτων ὁπόσα μελετητά, φέρε καὶ ταύτην ἤδη συστησώμεθα, ποικίλην μέντοι καὶ πολύμορφον, ὡς μηδὲ κατὰ τοῦτο ἀπολιποίμεθα τῆς σῆς πλαστικῆς. καὶ δὴ γεγράφθω πάντα συλλήβδην τὰ ἐκ τοῦ Ἑλικῶνος ἀγαθὰ ἔχουσα, οὐχ ὥσπερ ἡ Κλειὼ καὶ ἡ Πολύμνια καὶ ἡ Καλλιόπη καὶ αἱ ἄλλαι ἕν τι ἑκάστη ἐπισταμένη, ἀλλὰ τὰ πασῶν καὶ προσέτι τὰ Ἑρμοῦ καὶ Ἀπόλλωνος. ὁπόσα γὰρ ἢ ποιηταὶ μέτροις διακοσμήσαντες ἢ ῥήτορες δεινότητι κρατύναντες ἐξενηνόχασιν ἢ συγγραφεῖς ἱστορήκασιν ἢ φιλόσοφοι παρῃνέκασι, πᾶσι τούτοις ἡ εἰκὼν κεκοσμήσθω, οὐκ ἄχρι τοῦ ἐπικεχρῶσθαι μόνον, ἀλλ’ εἰς βάθος δευσοποιοῖς τισι φαρμάκοις εἰς κόρον καταβαφεῖσα. καὶ συγγνώμη, εἰ μηδὲν ἀρχέτυπον ἐπιδεῖξαι ταύτης δυναίμην τῆς γραφῆς· οὐ γὰρ ἔσθ’ ὅ τι τοιοῦτον ἐν τοῖς πάλαι παιδείας πέρι μνημονεύεται. πλὴν ἀλλά, εἴ γε δοκεῖ, ἀνακείσθω καὶ αὕτη· οὐ μεμπτὴ γάρ, ὡς ἐμοὶ φαίνεται.", "st": "39.16"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> καλλίστη μὲν οὖν, ὦ Πολύστρατε, καὶ πάσαις ταῖς γραμμαῖς ἀπηκριβωμένη.", "st": "39.16"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> μετὰ δὲ ταύτην ἡ τῆς σοφίας καὶ συνέσεως εἰκὼν γραπτέα. δεήσει δὲ ἡμῖν ἐνταῦθα πολλῶν τῶν παραδειγμάτων, ἀρχαίων τῶν πλείστων, ἑνὸς μὲν καὶ αὐτοῦ Ἰωνικοῦ· γραφεῖς δὲ καὶ δημιουργοὶ αὐτοῦ Αἰσχίνης Σωκράτους ἑταῖρος καὶ αὐτὸς Σωκράτης, μιμηλότατοι τεχνιτῶν ἁπάντων, ὅσῳ καὶ μετ’ ἔρωτος ἔγραφον. τὴν δὲ ἐκ τῆς Μιλήτου ἐκείνην Ἀσπασίαν, ᾗ καὶ ὁ Ὀλύμπιος θαυμασιώτατος αὐτὸς συνῆν, οὐ φαῦλον συνέσεως παράδειγμα προθέμενοι, ὁπόσον ἐμπειρίας πραγμάτων καὶ ὀξύτητος εἰς τὰ πολιτικὰ καὶ ἀγχινοίας καὶ δριμύτητος ἐκείνῃ προσῆν, τοῦτο πᾶν ἐπὶ τὴν ἡμετέραν εἰκόνα μεταγάγωμεν ἀκριβεῖ τῇ στάθμῃ· πλὴν ὅσον ἐκείνη μὲν ἐν μικρῷ πινακίῳ ἐγέγραπτο, αὕτη δὲ κολοσσιαία τὸ μέγεθός ἐστιν.", "st": "39.17"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> πῶς τοῦτο φής;", "st": "39.17"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> ὅτι, ὦ Λυκῖνε, οὐκ ἰσομεγέθεις εἶναί φημι τὰς εἰκόνας ὁμοίας οὔσας· οὐ γὰρ ἴσον οὐδὲ ἐγγὺς Ἀθηναίων ἡ τότε πολιτεία καὶ ἡ παροῦσα τῶν Ῥωμαίων δύναμις. ὥστε εἰ καὶ τῇ ὁμοιότητι ἡ αὐτή, ἀλλὰ τῷ μεγέθει γε ἀμείνων αὕτη ὡς ἂν ἐπὶ πλατυτάτου πίνακος καταγεγραμμένη.", "st": "39.17"}, {"sp": "N", "t": "δεύτερον δὲ καὶ τρίτον παράδειγμα Θεανώ τε ἐκείνη καὶ ἡ Λεσβία μελοποιός, καὶ Διοτίμα ἐπὶ ταύταις, ἡ μὲν τὸ μεγαλόνουν ἡ Θεανὼ συμβαλλομένη εἰς τὴν γραφήν, ἡ Σαπφὼ δὲ τὸ γλαφυρὸν τῆς προαιρέσεως· τῇ Διοτίμᾳ δὲ οὐχ ἃ Σωκράτης ἐπῄνεσεν αὐτὴν ἐοικυῖα ἔσται μόνον, ἀλλὰ καὶ τὴν ἄλλην σύνεσίν τε καὶ συμβουλίαν. τοιαύτη σοι καὶ αὕτη, Λυκῖνε, ἀνακείσθω ἡ εἰκών.", "st": "39.18"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> νὴ Δί’, ὦ Πολύστρατε, θαυμάσιος οὖσα. σὺ δὲ ἄλλας γράφου.", "st": "39.19"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> τὰς τῆς χρηστότητος, ὦ ἑταῖρε, καὶ φιλανθρωπίας, ἣ τὸ ἥμερον ἐμφανιεῖ τοῦ τρόπου καὶ πρὸς τοὺς δεομένους προσηνές; εἰκάσθω οὖν καὶ αὐτὴ Θεανοῖ τε ἐκείνῃ τῇ Ἀντήνορος καὶ Ἀρήτῃ καὶ τῇ θυγατρὶ αὐτῆς τῇ Ναυσικάᾳ, καὶ εἴ τις ἄλλη ἐν μεγέθει πραγμάτων ἐσωφρόνησε πρὸς τὴν τύχην.", "st": "39.19"}, {"sp": "N", "t": "ἑξῆς δὲ μετὰ ταύτην ἡ τῆς σωφροσύνης αὐτῆς γεγράφθω καὶ τῆς πρὸς τὸν συνόντα εὐνοίας, ὡς κατὰ τὴν τοῦ Ἰκαρίου μάλιστα εἶναι τὴν σαόφρονα καὶ τὴν περίφρονα ὑπὸ τοῦ Ὁμήρου γεγραμμένην — τοιαύτην γὰρ τὴν τῆς Πηνελόπης εἰκόνα ἐκεῖνος ἔγραψεν — ἢ καὶ νὴ Δία κατὰ τὴν ὁμώνυμον αὐτῆς τὴν τοῦ Ἀβραδάτα, ἧς μικρὸν ἔμπροσθεν ἐμνημονεύσαμεν.", "st": "39.20"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> παγκάλην καὶ ταύτην, ὦ Πολύστρατε, ἀπειργάσω, καὶ σχεδὸν ἤδη τέλος σοι ἔχουσιν αἱ εἰκόνες· ἅπασαν γὰρ ἐπελήλυθας τὴν ψυχὴν κατὰ μέρη ἐπαινῶν.", "st": "39.20"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> οὐχ ἅπασαν· ἔτι γὰρ τὰ μέγιστα τῶν ἐπαίνων περιλείπεται. λέγω δὲ τὸ ἐν τηλικούτῳ ὄγκῳ γενομένην αὐτὴν μήτε τῦφον ἐπὶ τῇ εὐπραξίᾳ περιβαλέσθαι μήτε ὑπὲρ τὸ ἀνθρώπινον μέτρον ἐπαρθῆναι πιστεύσασαν τῇ τύχῃ, φυλάττειν δὲ ἐπὶ τοῦ ἰσοπέδου ἑαυτὴν μηδὲν ἀπειρόκαλον ἢ φορτικὸν φρονοῦσαν καὶ τοῖς προσιοῦσιν δημοτικῶς τε καὶ ἐκ τοῦ ὁμοίου προσφέρεσθαι καὶ δεξιώσεις καὶ φιλοφροσύνας φιλοφρονεῖσθαι τοσούτῳ ἡδίους τοῖς προσομιλοῦσιν, ὅσῳ καὶ παρὰ μείζονος ὅμως γιγνόμεναι οὐδὲν τραγικὸν ἐμφαίνουσιν. ὡς ὁπόσοι τῷ μέγα δύνασθαι μὴ πρὸς ὑπεροψίαν, ἀλλὰ καὶ πρὸς εὐποιίαν ἐχρήσαντο, οὗτοι καὶ ἄξιοι μάλιστα τῶν παρὰ τῆς τύχης δοθέντων ἀγαθῶν ὤφθησαν, καὶ μόνοι ἂν οὗτοι δικαίως τὸ ἐπίφθονον διαφύγοιεν· οὐδεὶς γὰρ ἂν φθονήσειε τῷ ὑπερέχοντι, ἢν μετριάζοντα ἐπὶ τοῖς εὐτυχήμασιν αὐτὸν ὁρᾷ καὶ μὴ κατὰ τὴν τοῦ Ὁμήρου Ἄτην ἐκείνην ἐπ’ ἀνδρῶν κράατα βεβηκότα καὶ τὸ ὑποδεέστερον πατοῦντα· ὅπερ οἱ ταπεινοὶ τὰς γνώμας πάσχουσιν ἀπειροκαλίᾳ τῆς ψυχῆς· ἐπειδὰν γὰρ αὐτοὺς ἡ τύχη μηδὲν τοιοῦτον ἐλπίσαντας ἄφνω ἀναβιβάσῃ εἰς πτηνόν τι καὶ μετάρσιον ὄχημα, οὐ μένουσιν ἐπὶ τῶν ὑπαρχόντων οὐδ’ ἀφορῶσιν κάτω, ἀλλὰ ἀεὶ πρὸς τὸ ἄναντες βιάζονται. τοιγαροῦν ὥσπερ ὁ Ἴκαρος, τακέντος αὐτοῖς τάχιστα τοῦ κηροῦ καὶ τῶν πτερῶν περιρρυέντων, γέλωτα ὀφλισκάνουσιν ἐπὶ κεφαλὴν εἰς πελάγη καὶ κλύδωνα ἐμπίπτοντες· ὅσοι δὲ κατὰ τὸν Δαίδαλον ἐχρήσαντο τοῖς πτεροῖς καὶ μὴ πάνυ ἐπήρθησαν, εἰδότες ὅτι ἐκ κηροῦ ἦν αὐτοῖς πεποιημένα, ἐταμιεύσαντο δὲ πρὸς τὸ ἀνθρώπινον τὴν φορὰν καὶ ἠγάπησαν ὑψηλότεροι μόνον τῶν κυμάτων ἐνεχθέντες, ὥστε μέντοι νοτίζεσθαι αὐτοῖς ἀεὶ τὰ πτερὰ καὶ μὴ παρέχειν αὐτὰ μόνῳ τῷ ἡλίῳ, οὗτοι δὲ ἀσφαλῶς τε ἅμα καὶ σωφρόνως διέπτησαν· ὅπερ καὶ ταύτην ἄν τις μάλιστα ἐπαινέσειε. τοιγαροῦν καὶ ἄξιον παρὰ πάντων ἀπολαμβάνει τὸν καρπόν, εὐχομένων ταῦτά τε αὐτῇ παραμεῖναι τὰ πτερὰ καὶ ἔτι πλείω ἐπιρρεῖν τἀγαθά.", "st": "39.21"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> καὶ οὕτως, ὦ Πολύστρατε, γιγνέσθω· ἀξία γὰρ οὐ τὸ σῶμα μόνον ὥσπερ ἡ Ἑλένη καλὴ οὖσα, καλλίω δὲ καὶ ἐρασμιωτέραν ὑπ’ αὐτῷ τὴν ψυχὴν σκέπουσα. ἔπρεπε δὲ καὶ βασιλεῖ τῷ μεγάλῳ χρηστῷ καὶ ἡμέρῳ ὄντι καὶ τοῦτο μετὰ τῶν ἄλλων ἀγαθῶν, ὁπόσα ἐστὶν αὐτῷ, εὐδαιμονῆσαι, ὡς ἐπ’ αὐτοῦ καὶ φῦναι γυναῖκα τοιαύτην καὶ συνοῦσαν αὐτῷ ποθεῖν αὐτόν· οὐ γὰρ μικρὸν τοῦτο εὐδαιμόνημα, γυνὴ περὶ ἧς ἄν τις εὐλόγως τὸ Ὁμηρικὸν ἐκεῖνο εἴποι, χρυσείῃ μὲν αὐτὴν Ἀφροδίτῃ ἐρίζειν τὸ κάλλος, ἔργα δὲ αὐτῇ Ἀθηναίῃ ἰσοφαρίζειν. γυναικῶν γὰρ συνόλως οὐκ ἄν τις παραβληθείη αὐτῇ “οὐ δέμας οὐδὲ φυήν,” φησὶν Ὅμηρος, “οὔτ’ ἂρ φρένας οὔτε τι ἔργα.”", "st": "39.22"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> ἀληθῆ φής, ὦ Λυκῖνε· ὥστε εἰ δοκεῖ, ἀναμίξαντες ἤδη τὰς εἰκόνας, ἥν τε σὺ ἀνέπλασας τὴν τοῦ σώματος καὶ ἃς ἐγὼ τῆς ψυχῆς ἐγραψάμην, μίαν ἐξ ἁπασῶν συνθέντες εἰς βιβλίον καταθέμενοι παρέχωμεν ἅπασι θαυμάζειν τοῖς τε νῦν οὖσι καὶ τοῖς ἐν ὑστέρῳ ἐσομένοις. μονιμωτέρα γοῦν τῶν Ἀπελλοῦ καὶ Παρρασίου καὶ Πολυγνώτου γένοιτ’ ἄν, καὶ αὐτῇ ἐκεινῇ παρὰ πολὺ τῶν τοιούτων κεχαρισμένη, ὅσῳ μὴ ξύλου καὶ κηροῦ καὶ χρωμάτων πεποίηται, ἀλλὰ ταῖς παρὰ Μουσῶν ἐπιπνοίαις εἴκασται, ἥπερ ἀκριβεστάτη εἰκὼν γένοιτ’ ἂν σώματος κάλλος καὶ ψυχῆς ἀρετὴν ἅμα ἐμφανίζουσα.", "st": "39.23"}, {"sp": "HDR", "t": "Ὑπὲρ τῶν Εἰκόνων"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> “ἐγώ σοι, ὦ Λυκῖνε,” φησὶν ἡ γυνή, “τὰ μὲν ἄλλα πολλὴν ἐνεῖδον τὴν εὔνοιαν πρὸς ἐμὲ καὶ τιμὴν ἐκ τοῦ συγγράμματος· οὐ γὰρ ἂν οὕτως ὑπερεπῄνει τις, εἰ μὴ καὶ μετ’ εὐνοίας συνέγραφε. τὸ δὲ ἐμὸν ὡς ἂν εἰδῇς, τοιόνδε ἐστίν. οὐδὲ ἄλλως μὲν χαίρω τοῖς κολακικοῖς τὸν τρόπον, ἀλλά μοι δοκοῦσιν οἱ τοιοῦτοι γόητες εἶναι καὶ ἥκιστα ἐλεύθεροι τὴν φύσιν· ἐν δὲ τοῖς ἐπαίνοις μάλιστα, ὅταν τις ἐπαινῇ με φορτικὰς καὶ ὑπερμέτρους ποιούμενος τὰς ὑπερβολάς, ἐρυθριῶ τε καὶ ὀλίγου δεῖν ἐπιφράττομαι τὰ ὦτα καὶ τὸ πρᾶγμα χλεύῃ μᾶλλον ἢ ἐπαίνῳ ἐοικέναι μοι δοκεῖ.", "st": "40.1"}, {"sp": "N", "t": "μέχρι γὰρ τοῦδε οἱ ἔπαινοι ἀνεκτοί εἰσιν εἰς ὅσον ἂν ὁ ἐπαινούμενος γνωρίζῃ ἕκαστον τῶν λεγομένων προσὸν ἑαυτῷ· τὸ δὲ ὑπὲρ τοῦτο ἀλλότριον ἤδη καὶ κολακεία σαφής.”", "st": "40.2"}, {"sp": "N", "t": "“καίτοι πολλούς,” ἔφη, “οἶδα χαίροντας, εἴ τις αὐτοὺς ἐπαινῶν καὶ ἃ μὴ ἔχουσιν προσάπτοι τῷ λόγῳ, οἷον εἰ γέροντας ὄντας εὐδαιμονίζοι τῆς ἀκμῆς ἢ ἀμόρφοις οὖσι τὸ Νιρέως κάλλος ἢ τὸ Φάωνος περιθείη· οἴονται γὰρ ὑπὸ τῶν ἐπαίνων ἀλλαγήσεσθαι σφίσι καὶ τὰς μορφὰς καὶ αὐτοὶ ἀνηβήσειν αὖθις, ὥσπερ ὁ Πελίας ᾤετο.", "st": "40.2"}, {"sp": "N", "t": "τὸ δὲ οὐχ οὕτως ἔχει· πολλοῦ γὰρ ἂν ὁ ἔπαινος ἦν τίμιος, εἴ τι καὶ ἔργον αὐτοῦ ἀπολαῦσαι δυνατὸν ἦν ἐκ τῆς τοιαύτης ὑπερβολῆς. νῦν δὲ ὅμοιόν μοι δοκοῦσιν,” ἔφη, “πάσχειν, ὥσπερ ἂν εἴ τινι ἀμόρφῳ προσωπεῖον εὔμορφον ἐπιθείη τις φέρων, ὁ δὲ μέγα ἐπὶ τῷ κάλλει φρονοίη, καὶ ταῦτα περιαιρετῷ ὄντι καὶ ὑπὸ τοῦ τυχόντος συντριβῆναι δυναμένῳ, ὅτε καὶ γελοιότερος ἂν γένοιτο αὐτοπρόσωπος φανείς, οἷος ὢν ὑφ’ οἵῳ κέκρυπτο· ἢ καὶ νὴ Δί’ εἴ τις ὑποδησάμενος κοθόρνους μικρὸς αὐτὸς ὢν ἐρίζοι περὶ μεγέθους τοῖς ἀπὸ τοῦ ἰσοπέδου ὅλῳ πήχει ὑπερέχουσιν.”", "st": "40.3"}, {"sp": "N", "t": "ἐμέμνητο γὰρ καὶ τοιούτου τινός. ἔφη γυναῖκά τινα τῶν ἐπιφανῶν τὰ μὲν ἄλλα καλὴν καὶ κόσμιον, μικρὰν δὲ καὶ πολὺ τοῦ συμμέτρου ἀποδέουσαν, ἐπαινεῖσθαι πρός τινος ποιητοῦ ἐν ᾄσματι τά τε ἄλλα καὶ ὅτι καλή τε καὶ μεγάλη ἦν· αἰγείρῳ δ’ αὐτῆς εἴκαζεν ἐκεῖνος τὸ εὔμηκές τε καὶ ὄρθιον. τὴν μὲν δὴ γάνυσθαι τῷ ἐπαίνῳ καθάπερ αὐξανομένην πρὸς τὸ μέλος καὶ τὴν χεῖρα ἐπισείειν, τὸν ποιητὴν δὲ πολλάκις τὸ αὐτὸ ᾄδειν ὁρῶντα ὡς ἥδοιτο ἐπαινουμένη, ἄχρι δὴ τῶν παρόντων τινὰ προσκύψαντα πρὸς τὸ οὖς εἰπεῖν αὐτῷ, “πέπαυσο, ὦ οὗτος, μὴ καὶ ἀναστῆναι ποιήσῃς τὴν γυναῖκα.”", "st": "40.4"}, {"sp": "N", "t": "παραπλήσιον δὲ καὶ μακρῷ τούτου γελοιότερον Στρατονίκην ποιῆσαι τὴν Σελεύκου γυναῖκα. τοῖς γὰρ ποιηταῖς ἀγῶνα προθεῖναι αὐτὴν περὶ ταλάντου, ὅστις ἂν ἄμεινον ἐπαινέσαι αὐτῆς τὴν κόμην, καίτοι φαλακρὰ ἐτύγχανεν οὖσα καὶ οὐδὲ ὅσας ὀλίγας τὰς ἑαυτῆς τρίχας ἔχουσα. καὶ ὅμως οὕτω διακειμένη τὴν κεφαλήν, ἁπάντων εἰδότων ὅτι ἐκ νόσου μακρᾶς τὸ τοιοῦτον ἐπεπόνθει, ἤκουε τῶν καταράτων ποιητῶν ὑακινθίνας τὰς τρίχας αὐτῆς λεγόντων καὶ οὔλους τινὰς πλοκάμους ἀναπλεκόντων καὶ σελίνοις τοὺς μηδὲ ὅλως ὄντας εἰκαζόντων.", "st": "40.5"}, {"sp": "N", "t": "ἁπάντων οὖν τῶν τοιούτων κατεγέλα τῶν παρεχόντων αὑτοὺς τοῖς κόλαξιν, καὶ προσετίθει δὲ ὅτι μὴ ἐν ἐπαίνοις μόνον, ἀλλὰ καὶ ἐν γραφαῖς τὰ ὅμοια πολλοὶ κολακεύεσθαί τε καὶ ἐξαπατᾶσθαι θέλουσι. “χαίρουσι γοῦν,” ἔφη, “τῶν γραφέων ἐκείνοις μάλιστα, οἳ ἂν πρὸς τὸ εὐμορφότερον αὐτοὺς εἰκάσωσιν.” εἶναι δέ τινας, οἳ καὶ προστάττουσιν τοῖς τεχνίταις ἢ ἀφελεῖν τι τῆς ῥινὸς ἢ μελάντερα γράψασθαι τὰ ὄμματα ἢ ὅ τι ἂν ἄλλο ἐπιθυμήσωσιν αὑτοῖς προσεῖναι, εἶτα λανθάνειν αὑτοὺς ἀλλοτρίας εἰκόνας στεφανοῦντας καὶ οὐδὲν αὐτοῖς ἐοικυίας.", "st": "40.6"}, {"sp": "N", "t": "ταῦτα δὲ καὶ τὰ τοιαῦτα ἔλεγεν, τὰ μὲν ἄλλα ἐπαινοῦσα τοῦ συγγράμματος, ἓν δὲ τοῦτο οὐ φέρουσα, ὅτι θεαῖς αὐτήν, Ἥρᾳ καὶ Ἀφροδίτῃ, εἴκασας· “ὑπὲρ ἐμὲ γάρ,” φησίν, “μᾶλλον δὲ ὑπὲρ ἅπασαν τὴν ἀνθρωπίνην φύσιν τὰ τοιαῦτα. ἐγὼ δέ σε οὐδ’ ἐκεῖνα ἠξίουν, ταῖς ἡρωΐναις παραθεωρεῖν με Πηνελόπῃ καὶ Ἀρήτῃ καὶ Θεανοῖ, οὐχ ὅπως θεῶν ταῖς ἀρίσταις. καὶ γὰρ αὖ καὶ τόδε, πάνυ,” ἔφη, “τὰ πρὸς τοὺς θεοὺς δεισιδαιμόνως καὶ ψοφοδεῶς ἔχω. δέδια τοίνυν μὴ κατὰ τὴν Κασσιέπειαν εἶναι δόξω τὸν τοιοῦτον ἔπαινον προσιεμένη· καίτοι Νηρηΐσιν ἐκείνη ἀντεξητάζετο, Ἥραν δὲ καὶ Ἀφροδίτην ἔσεβεν.”", "st": "40.7"}, {"sp": "N", "t": "ὥστε, ὦ Λυκῖνε, μεταγράψαι σε τὰ τοιαῦτα ἐκέλευσεν, ἢ αὐτὴ μὲν μαρτύρεσθαι τὰς θεὰς ὡς ἀκούσης αὐτῆς γέγραφας, σὲ δὲ εἰδέναι ὅτι ἀνιάσει αὐτὴν τὸ βιβλίον οὕτω περινοστοῦν ὥσπερ νῦν σοι διάκειται, οὐ μάλα εὐσεβῶς οὐδὲ ὁσίως τὰ πρὸς τοὺς θεούς. ἐδόκει τε ἀσέβημα ἑαυτῆς καὶ πλημμέλημα τοῦτο δόξειν, εἰ ὑπομένοι τῇ ἐν Κνίδῳ καὶ τῇ ἐν κήποις ὁμοία λέγεσθαι· καί σε ὑπεμίμνησκε τῶν τελευταίων ἐν τῷ βιβλίῳ περὶ αὐτῆς εἰρημένων, ὅτι μετρίαν καὶ ἄτυφον ἔφης αὐτὴν οὐκ ἀνατεινομένην ὑπὲρ τὸ ἀνθρώπινον μέτρον, ἀλλὰ πρόσγειον τὴν πτῆσιν ποιουμένην, ὁ δὲ ταῦτα εἰπὼν ὑπὲρ αὐτὸν τὸν οὐρανὸν ἀναβιβάζεις τὴν γυναῖκα, ὡς καὶ θεαῖς ἀπεικάζειν.", "st": "40.8"}, {"sp": "N", "t": "ἠξίου δέ σε μηδὲ ἀξυνετωτέραν αὐτὴν ἡγεῖσθαι τοῦ Ἀλεξάνδρου, ὃς τοῦ ἀρχιτέκτονος ὑπισχνουμένου τὸν Ἄθω ὅλον μετασχηματίσειν καὶ μορφώσειν πρὸς αὐτόν, ὡς τὸ ὄρος ἅπαν εἰκόνα γενέσθαι τοῦ βασιλέως, ἔχοντα δύο πόλεις ἐν ταῖν χεροῖν, οὐ προσήκατο τὴν τερατείαν τῆς ὑποσχέσεως, ἀλλ’ ὑπὲρ αὐτὸν ἡγησάμενος τὸ τόλμημα ἔπαυσεν τὸν ἄνθρωπον οὐ πιθανῶς κολοσσοὺς ἀναπλάττοντα καὶ τὸν Ἄθω κατὰ χώραν ἐᾶν ἐκέλευσεν μηδὲ κατασμικρύνειν ὄρος οὕτω μέγα πρὸς μικροῦ σώματος ὁμοιότητα. ἐπῄνει δὲ τὸν Ἀλέξανδρον τῆς μεγαλοψυχίας καὶ ἀνδριάντα μείζω τοῦτον τοῦ Ἄθω ἔλεγεν αὐτοῦ ἀνεστάναι ἐν ταῖς τῶν ἀεὶ μεμνησομένων διανοίαις· οὐ γὰρ μικρᾶς εἶναι γνώμης ὑπεριδεῖν οὕτω παραδόξου τιμῆς.", "st": "40.9"}, {"sp": "N", "t": "καὶ ἑαυτὴν οὖν τὸ μὲν πλάσμα σου ἐπαινεῖν καὶ τὴν ἐπίνοιαν τῶν εἰκόνων, μὴ γνωρίζειν δὲ τὴν ὁμοιότητα· μὴ γὰρ εἶναι τῶν τηλικούτων ἀξίαν, μηδὲ ἐγγύς, ὅτι μηδὲ ἄλλην τινά, γυναῖκά γε οὖσαν· ὥστε ἀφίησί σοι ταύτην τὴν τιμὴν καὶ προσκυνεῖ σου τὰ ἀρχέτυπα καὶ παραδείγματα. σὺ δὲ τὰ ἀνθρώπινα ταῦτα ἐπαίνει αὐτήν, μηδὲ ὑπὲρ τὸν πόδα ἔστω τὸ ὑπόδημα, “μὴ καὶ ἐπιστομίσῃ με,” φησίν, “ἐμπεριπατοῦσαν αὐτῷ.”", "st": "40.10"}, {"sp": "N", "t": "κἀκεῖνο δὲ εἰπεῖν σοι ἐνετείλατο. “ἀκούω,” ἔφη, “πολλῶν λεγόντων — εἰ δὲ ἀληθές, ὑμεῖς οἱ ἄνδρες ἴστε — μηδ’ Ὀλυμπίασιν ἐξεῖναι τοῖς νικῶσι μείζους τῶν σωμάτων ἀνεστάναι τοὺς ἀνδριάντας, ἀλλὰ ἐπιμελεῖσθαι τοὺς Ἑλλανοδίκας ὅπως μηδὲ εἷς ὑπερβάληται τὴν ἀλήθειαν, καὶ τὴν ἐξέτασιν τῶν ἀνδριάντων ἀκριβεστέραν γίγνεσθαι τῆς τῶν ἀθλητῶν ἐγκρίσεως. ὥστε ὅρα,” ἔφη, “μὴ αἰτίαν λάβωμεν ψεύδεσθαι ἐν τῷ μέτρῳ, κᾆτα ἡμῶν ἀνατρέψωσιν οἱ Ἑλλανοδίκαι τὴν εἰκόνα.”", "st": "40.11"}, {"sp": "N", "t": "ταῦτα μὲν ἔλεγεν ἐκείνη. σὺ δὲ σκόπει, ὦ Λυκῖνε, ὅπως μετακοσμήσεις τὸ βιβλίον καὶ ἀφαιρήσεις τὰ τοιαῦτα, μηδὲ σφαλῇς πρὸς τὸ θεῖον· ὡς ἐκείνη πάνυ γε αὐτὰ ἐδυσχέραινεν καὶ ὑπέφριττεν μεταξὺ ἀναγιγνωσκομένων καὶ παρῃτεῖτο τὰς θεὰς ἵλεως εἶναι αὐτῇ. καὶ συγγνώμη, εἰ γυναικεῖόν τι ἔπαθεν. καίτοι εἰ χρὴ τἀληθὲς εἰπεῖν, καὶ αὐτῷ ἐμοὶ τοιοῦτόν τι ἔδοξε. τὸ μὲν γὰρ πρῶτον ἀκούων οὐδὲν πλημμέλημα ἐνεώρων τοῖς γεγραμμένοις, ἐπεὶ δὲ ἐκείνη ἐπεσημήνατο, καὶ αὐτὸς ἄρχομαι τὰ ὅμοια γιγνώσκειν περὶ αὐτῶν, καὶ παραπλήσιόν τι ἔπαθον οἷς ἐπὶ τῶν ὁρωμένων πάσχομεν· ἢν μὲν πάνυ ἐγγύθεν σκοπῶμέν τι καὶ ὑπὸ τῶν ὀφθαλμῶν αὐτῶν, οὐδὲν ἀκριβὲς διαγιγνώσκομεν, ἢν δὲ ἀποστάντες ἐκ τοῦ συμμέτρου διαστήματος ἴδωμεν, ἅπαντα σαφῶς καταφαίνεται, τὰ εὖ καὶ τὰ μὴ οὕτως ἔχοντα.", "st": "40.12"}, {"sp": "N", "t": "τὸ δὴ ἄνθρωπον οὖσαν Ἀφροδίτῃ καὶ Ἥρᾳ εἰκάσαι τί ἄλλο ἢ ἄντικρύς ἐστιν εὐτελίζειν τὰς θεάς; ἐν γὰρ τοῖς τοιούτοις οὐχ οὕτω τὸ μικρὸν μεῖζον γίγνεται τῇ παραθέσει, ὡς τὸ μεῖζον ἀπομικρύνεται πρὸς τὸ ταπεινότερον κατασπώμενον· οἷον εἴ τινες ἅμα βαδίζοιεν, ὁ μὲν μέγιστος, ὁ δὲ πάνυ τῇ ἡλικίᾳ χαμαίζηλος, εἶτα δεήσειεν ἀπισῶσαι αὐτοὺς ὡς μὴ ὑπερέχειν θατέρου τὸν ἕτερον, οὐ τοῦ βραχυτέρου ὑπερανατεινομένου τοῦτο γένοιτ’ ἄν, κἂν ὅτι μάλιστα ἀκροποδητὶ ἐπεγείρῃ ἑαυτόν· ἀλλ’ εἰ μέλλουσιν ὁμήλικες φανεῖσθαι, ὁ μείζων ἐκεῖνος ἐπικύψει καὶ ταπεινότερον ἀποφανεῖ ἑαυτόν. ὡσαύτως δὲ καὶ ἐν ταῖς τοιαύταις εἰκόσιν οὐχ οὕτως ἄνθρωπος μείζων γίγνεται, ἤν τις αὐτὸν θεῷ ἀπεικάζῃ, ὡς τὸ θεῖον ἀνάγκη ἐλαττοῦσθαι πρὸς τὸ ἐνδέον ἐπικλώμενον. καὶ γὰρ εἰ μὲν ὑπὸ ἀπορίας τῶν ἐπιγείων ἐπὶ τὰ οὐράνια ἐκτείνοι τις τὸν λόγον, ἧττον ἂν ὁ τοιοῦτος αἰτίαν ἔχοι ὑπὸ ἀσεβείας αὐτὸ δρᾶν· σὺ δὲ τοσαῦτα ἔχων κάλλη γυναικῶν Ἀφροδίτῃ καὶ Ἥρᾳ εἰκάσαι αὐτὴν ἐτόλμησας οὐδὲν δέον.", "st": "40.13"}, {"sp": "N", "t": "ὥστε τὸ ἄγαν τοῦτο καὶ ἐπίφθονον ἀφαίρει, ὦ Λυκῖνε. οὐ γὰρ πρὸς τοῦ σοῦ τρόπου τὸ τοιοῦτον, ὃς οὐδὲ ἄλλως ῥᾴδιος πρὸς τοὺς ἐπαίνους καὶ πρόχειρος ὢν ἐτύγχανες· ἀλλὰ νῦν οὐκ οἶδ’ ὅπως ἀθρόαν πεποίησαι τὴν μεταβολὴν ἐπιδαψιλευόμενος καὶ ἐκ τοῦ τέως φειδομένου ἄσωτος ἐν τοῖς ἐπαίνοις ἀναπέφηνας. ἀλλὰ μηδὲ ἐκεῖνο αἰσχυνθῇς, εἰ μεταρρυθμιεῖς τὸν λόγον ἤδη διαδεδομένον· ἐπεὶ καὶ Φειδίαν φασὶν οὕτω ποιῆσαι, ὁπότε ἐξειργάσατο τοῖς Ἠλείοις τὸν Δία. στάντα γὰρ αὐτὸν κατόπιν τῶν θυρῶν, ὁπότε τὸ πρῶτον ἀναπετάσας ἐπεδείκνυεν τὸ ἔργον, ἐπακούειν τῶν αἰτιωμένων τι ἢ ἐπαινούντων· ᾐτιᾶτο δὲ ὁ μὲν τὴν ῥῖνα ὡς παχεῖαν, ὁ δὲ ὡς ἐπιμηκέστερον τὸ πρόσωπον, ὁ δὲ ἄλλος ἄλλο τι. εἶτ’ ἐπειδὴ ἀπηλλάγησαν οἱ θεαταί, αὖθις τὸν Φειδίαν ἐγκλεισάμενον ἑαυτὸν ἐπανορθοῦν καὶ ῥυθμίζειν τὸ ἄγαλμα πρὸς τὸ τοῖς πλείστοις δοκοῦν· οὐ γὰρ ἡγεῖτο μικρὰν εἶναι συμβουλὴν δήμου τοσούτου, ἀλλ’ ἀεὶ ἀναγκαῖον ὑπάρχειν τοὺς πολλοὺς περιττότερον ὁρᾶν τοῦ ἑνός, κἂν Φειδίας ᾖ. Ταῦτά σοι παρ’ ἐκείνης κομίζω καὶ αὐτὸς παραινῶ ἑταῖρός τε καὶ εὔνους ὤν.", "st": "40.14"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> Πολύστρατε, οἷος ὢν ῥήτωρ ἐλελήθεις με. ῥῆσιν γοῦν οὕτω μακρὰν καὶ κατηγορίαν τοσαύτην ἐξενήνοχας κατὰ τοῦ συγγράμματος, ὥστε μηδὲ ἐλπίδα μοι ἀπολογίας ἔτι καταλείπεσθαι. πλὴν ἀλλὰ ἐκεῖνό γε οὐ δικαστικὸν ἐποιήσατε, καὶ μάλιστα σύ, ἐρήμην καταδιαιτήσας τοῦ βιβλίου μὴ παρόντος αὐτῷ τοῦ συνηγόρου. ῥᾷστον δέ, οἶμαι, τοῦτό ἐστιν κατὰ τὴν παροιμίαν, μόνον θέοντα κρατεῖν. ὥστε οὐδὲν θαυμαστόν, εἰ καὶ ἡμεῖς ἑάλωμεν οὔτε ὕδατος ἡμῖν ἐκχυθέντος οὔτε ἀπολογίας ἀποδοθείσης. μᾶλλον δὲ τοῦτο πάντων ἀτοπώτατον, οἱ αὐτοὶ κατήγοροι καὶ δικασταὶ ἦτε.", "st": "40.15"}, {"sp": "N", "t": "πότερα δ’ οὖν ἐθέλεις; ἀγαπήσας τοῖς ἐγνωσμένοις ἡσυχίαν ἄγω, ἢ κατὰ τὸν Ἱμεραῖον ποιητὴν παλινῳδίαν τινὰ συγγράφω, ἢ δώσετέ μοι ἐφέσιμον ἀγωνίσασθαι τὴν δίκην;", "st": "40.15"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> νὴ Δί’, ἤνπερ ἔχῃς τι δίκαιον εἰπεῖν· οὐ γὰρ ἐν ἀντιδίκοις, ὡς σὺ φής, ἀλλ’ ἐν φίλοις ποιήσῃ τὴν ἀπολογίαν. ἐγὼ δὲ καὶ συνεξετάζεσθαί σοι ἕτοιμος ἐπὶ τῆς δίκης.", "st": "40.15"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἀλλὰ ἐκεῖνο ἀνιαρόν, ὦ Πολύστρατε, ὅτι μὴ ἐκείνης παρούσης ποιήσομαι τοὺς λόγους· μακρῷ γὰρ ἂν οὕτως ἄμεινον ἦν. νῦν δὲ ἀνάγκη ἀπ’ ἐντολῆς ἀπολογήσασθαι. ἀλλ’ εἴ μοι τοιοῦτος ἀγγελιαφόρος γένοιο πρὸς αὐτὴν οἷος παρ’ ἐκείνης πρὸς μὲ γεγένησαι, τολμήσω ἀναρρῖψαι τὸν κύβον.", "st": "40.16"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> θάρρει, ὦ Λυκῖνε, τούτου γε ἕνεκα, ὡς οὐ φαῦλόν με ὑποκριτὴν ἕξων τῆς ἀπολογίας, πειρώμενος διὰ βραχέων εἰπεῖν, ὡς ἂν μᾶλλον μνημονεύσαιμι.", "st": "40.16"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> καὶ μὴν πάνυ μὲν ἔδει μοι μακρῶν τῶν λόγων πρὸς οὕτω σφοδρὰν τὴν κατηγορίαν. ὅμως δὲ σοῦ ἕνεκα ἐπιτεμοῦμαι τὴν ἀπολογίαν. καὶ παρ’ ἐμοῦ τοίνυν τάδε αὐτῇ ἀπάγγελλε.", "st": "40.16"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> μηδαμῶς, ὦ Λυκῖνε, ἀλλ’ ὥσπερ αὐτῆς ἐκείνης παρούσης λέγε τὸν λόγον, εἶτ’ ἐγὼ μιμήσομαί σε πρὸς αὐτήν.", "st": "40.16"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> οὐκοῦν ἐπειδήπερ οὕτω σοι δοκεῖ, ὦ Πολύστρατε, ἡ μὲν πάρεστι καὶ προείρηκε δηλαδὴ ἐκεῖνα ὁπόσα σὺ παρ’ αὐτῆς ἀπήγγειλας, ἡμᾶς δὲ χρὴ τῶν δευτέρων λόγων ἐνάρχεσθαι. καίτοι — οὐ γὰρ ὀκνήσω πρὸς σὲ εἰπεῖν ὃ πέπονθα — οὐκ οἶδ’ ὅπως φοβερώτερόν μοι τὸ πρᾶγμα πεποίηκας, καὶ ὡς ὁρᾷς ἱδρῶ τε ἤδη καὶ δέδοικα καὶ μονονουχὶ καὶ ὁρᾶν αὐτὴν οἴομαι, καὶ τὸ πρᾶγμα πολλήν μοι τὴν ταραχὴν ἐμπεποίηκεν. ἄρξομαι δ’ ὅμως· οὐ γὰρ οἷόν τε ἀναδῦναι ἤδη παρούσης.", "st": "40.16"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> καὶ νὴ Δία πολλὴν τὴν εὐμένειαν ἐπιφαίνει τῷ προσώπῳ· φαιδρὰ γὰρ ὡς ὁρᾷς καὶ προσηνής. ὥστε θαρρῶν λέγε τὸν λόγον.", "st": "40.16"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἐγώ σε, ὦ γυναικῶν ἀρίστη, μεγάλα, ὡς φής, καὶ πέρα τοῦ μέτρου ἐπαινέσας οὐχ ὁρῶ ὅ τι τηλικοῦτον ἐπῄνεσα, ἡλίκον αὐτὴ σὺ τοῦτο ἐγκώμιον ὑπὲρ σεαυτῆς ἐξενήνοχας τὴν πρὸς τὸ θεῖον τιμὴν ἐν μεγάλῳ τιθεμένη. σχεδὸν γὰρ ἁπάντων τοῦτο μεῖζον ὧν εἴρηκα περὶ σοῦ, καὶ συγγνώμη, εἰ μὴ καὶ ταύτην σοι προσέγραψα τὴν εἰκόνα ὑπ’ ἀγνοίας με διαλαθοῦσαν· οὐ γὰρ ἂν ἄλλην πρὸ αὐτῆς ἐγραψάμην. ὥστε ταύτῃ γε οὐχ ὅπως ὑπερβάλλεσθαι τοὺς ἐπαίνους, ἀλλὰ πολὺ καταδεέστερόν μοι δοκῶ τῆς ἀξίας εἰρηκέναι. σκόπει γοῦν ἡλίκον τοῦτο παρέλιπον, ὡς παμμέγεθες εἰς ἐπίδειξιν τρόπου χρηστοῦ καὶ γνώμης ὀρθῆς· ὡς ὅσοι τὸ θεῖον μὴ ἐν παρέργῳ σέβουσιν, οὗτοι καὶ τὰ πρὸς ἀνθρώπους ἄριστοι ἂν εἶεν. ὥστε εἰ πάντως μετακοσμῆσαι δέοι τὸν λόγον καὶ τὸ ἄγαλμα ἐπανορθώσασθαι, ἀφελεῖν μὲν οὐκ ἄν τι τολμήσαιμι αὐτοῦ, προσθήσω δὲ καὶ τοῦτο ὥς τινα κεφαλὴν τοῦ παντὸς ἔργου καὶ κορυφήν.", "st": "40.17"}, {"sp": "N", "t": "Ἐπ’ ἐκείνῳ μέντοι καὶ πάνυ πολλήν σοι εἰδέναι τὴν χάριν ὁμολογῶ· ἐμοῦ γὰρ ἐπαινέσαντος τὸ μέτριον τοῦ σοῦ τρόπου καὶ ὅτι μηδὲν ὑπερπετὲς μηδὲ τύφου μεστὸν ἐνεποίησέ σοι ὁ παρὼν ὄγκος τῶν πραγμάτων, σὺ τὰ τοιαῦτα αἰτιασαμένη τοῦ λόγου ἐπιστώσω τοῦ ἐπαίνου τὴν ἀλήθειαν· τὸ γὰρ μὴ προαρπάζειν τὰ τοιαῦτα τῶν ἐγκωμίων, ἀλλ’ αἰδεῖσθαι ἐπ’ αὐτοῖς καὶ μείζω ἢ κατὰ σὲ εἶναι λέγειν, μετρίας καὶ δημοτικῆς τινος διανοίας δεῖγμά ἐστιν. πλὴν ἀλλὰ ὅσῳπερ ἂν πρὸς τὸ ἐπαινεῖσθαι αὐτὸ οὕτω διακειμένη τυγχάνῃς, τοσούτῳ ἀξιωτέραν ὑπερεπαινεῖσθαι ἀποφαίνεις σεαυτήν, καὶ σχεδὸν εἰς τὸν τοῦ Διογένους λόγον περιελήλυθέν σοι τὸ πρᾶγμα, ὃς ἐρομένου τινὸς ὅπως ἄν τις ἔνδοξος γένοιτο, “εἰ δόξης,” ἔφη, “καταφρονήσειε.” φαίην γὰρ ἂν καὶ αὐτός, εἴ τις ἔροιτό με, “τίνες εἰσὶν μάλιστα ἐπαίνου ἄξιοι;” “ὁπόσοι ἐπαινεῖσθαι μὴ θέλουσιν.”", "st": "40.17"}, {"sp": "N", "t": "ἀλλὰ ταῦτα μὲν ἴσως ἐξαγώνια καὶ πόρρω τοῦ πράγματος. ὑπὲρ δὲ οὗ χρὴ ἀπολογήσασθαι, τοῦτό ἐστιν, ὅτι τῇ ἐν Κνίδῳ καὶ τῇ ἐν κήποις καὶ Ἥρᾳ καὶ Ἀθηνᾷ τὴν μορφὴν ἀναπλάττων εἴκασα. ταῦτά σοι ἔκμετρα ἔδοξεν καὶ ὑπὲρ τὸν πόδα. περὶ αὐτῶν δὴ τούτων ἐρῶ.", "st": "40.18"}, {"sp": "N", "t": "καίτοι παλαιὸς οὗτος ὁ λόγος, ἀνευθύνους εἶναι ποιητὰς καὶ γραφέας, τοὺς δὲ ἐπαινοῦντας καὶ μᾶλλον, οἶμαι, εἰ καὶ χαμαὶ καὶ βάδην, ὥσπερ ἡμεῖς, ἀλλὰ μὴ ἐπὶ μέτρων φέροιντο. ἐλεύθερον γάρ τι ὁ ἔπαινος, οὐδ’ ἔστιν αὐτοῦ μέτρον εἰς μέγεθος ἢ βραχύτητα νενομοθετημένον, ἀλλὰ τοῦτο μόνον ἐξ ἅπαντος ὁρᾷ ὅπως ὑπερθαυμάσεται καὶ ζηλωτὸν ἀποφανεῖ τὸν ἐπαινούμενον. οὐ μὴν ταύτην ἐγὼ βαδιοῦμαι, μὴ καὶ σοὶ δόξω ὑπ’ ἀπορίας αὐτὸ δρᾶν.", "st": "40.18"}, {"sp": "N", "t": "ἐκεῖνο δέ γέ φημι, τοιαύτας ἡμῖν τὰς ἀφορμὰς τῶν ἐπαινετικῶν τούτων λόγων εἶναι, ὡς χρὴ τὸν ἐπαινοῦντα καὶ εἰκόσι καὶ ὁμοιώσεσι προσχρῆσθαι, καὶ σχεδὸν ἐν τούτῳ τὸ μέγιστόν ἐστιν εὖ εἰκάσαι· τὸ δὲ εὖ ὧδε μάλιστ’ ἂν κρίνοιτο, οὐκ ἤν τις τοῖς ὁμοίοις παραβάλλῃ οὐδ’ ἢν πρὸς τὸ ὑποδεέστερον ποιῆται τὴν παράθεσιν, ἀλλ’ ἢν πρὸς τὸ ὑπερέχον ὡς οἷόν τε προσβιβάζῃ τὸ ἐπαινούμενον.", "st": "40.19"}, {"sp": "N", "t": "οἷον εἴ τις κύνα ἐπαινῶν εἴποι ἀλώπεκος εἶναι μείζω αὐτὸν ἢ αἰλούρου, ἆρά σοι δοκεῖ ὁ τοιοῦτος ἐπαινεῖν εἰδέναι; οὐκ ἂν εἴποις. ἀλλὰ μὴν οὐδ’ εἰ λύκῳ φαίη ἴσον αὐτὸν ὑπάρχειν, οὐδὲ οὕτως μεγαλωστὶ ἐπῄνεσεν. ἀλλὰ ποῦ τὸ ἴδιον τοῦ ἐπαίνου ἀποτελεῖται; ἢν ὁ κύων τῷ λέοντι ἐοικέναι λέγηται καὶ μέγεθος καὶ ἀλκήν. ὡς ὁ τὸν Ὠρίωνος κύνα ἐπαινῶν ἔφη ποιητὴς λεοντοδάμαν αὐτόν· οὗτος γὰρ δὴ κυνὸς ἐντελὴς ἔπαινος.", "st": "40.19"}, {"sp": "N", "t": "καὶ πάλιν εἴ τις Μίλωνα τὸν ἐκ Κρότωνος ἢ Γλαῦκον τὸν ἐκ Καρύστου ἢ Πολυδάμαντα ἐπαινέσαι θέλων ἔπειτα λέγοι ἰσχυρότερον ἕκαστον αὐτῶν γυναικὸς γενέσθαι, οὐκ ἂν οἴει γελασθῆναι αὐτὸν ἐπὶ τῇ ἀνοίᾳ τοῦ ἐπαίνου; ὅπου γε καὶ εἰ ἑνὸς ἀνδρὸς ἔλεγεν ἀμείνω εἶναι αὐτόν, οὐδὲ τοῦτο ἀπέχρησεν ἂν εἰς ἔπαινον. ἀλλὰ πῶς ἐπῄνεσε ποιητὴς εὐδόκιμος τὸν Γλαῦκον, οὐδὲ “Πολυδεύκεος βίαν” φήσας ἀνατείνασθαι ἂν αὐτῷ ἐναντίας τὰς χεῖρας “οὐδὲ σιδάρεον Ἀλκμάνας τέκος;” ὁρᾷς ὁποίοις αὐτὸν θεοῖς εἴκασε· μᾶλλον δὲ καὶ αὐτῶν ἐκείνων ἀμείνω ἀπέφαινεν. καὶ οὔτε αὐτὸς ὁ Γλαῦκος ἠγανάκτησεν τοῖς ἐφόροις τῶν ἀθλητῶν θεοῖς ἀντεπαινούμενος, οὔτε ἐκεῖνοι ἠμύναντο ἢ τὸν Γλαῦκον ἢ τὸν ποιητὴν ὡς ἀσεβοῦντα περὶ τὸν ἔπαινον, ἀλλὰ εὐδοκίμουν ἄμφω καὶ ἐτιμῶντο ὑπὸ τῶν Ἑλλήνων, ὁ μὲν ἐπὶ τῇ ἀλκῇ, ὁ Γλαῦκος, ὁ δὲ ποιητὴς ἐπί τε τοῖς ἄλλοις καὶ ἐπ’ αὐτῷ τούτῳ μάλιστα τῷ ᾄσματι. μὴ δὴ θαυμάσῃς εἰ καὶ αὐτὸς εἰκάσαι βουλόμενος, ὅπερ ἦν τῷ ἐπαινοῦντι ἀναγκαῖον, ὑψηλοτέρῳ ἐχρησάμην τῷ παραδείγματι, τοῦτο ὑποβαλόντος τοῦ λόγου.", "st": "40.19"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ κολακείας ἐπεμνήσθης, ὅτι μὲν καὶ σὺ μισεῖς τοὺς κολακικούς, ἐπαινῶ μέν σε, καὶ οὐκ ἐχρῆν ἄλλως. ἐθέλω δέ σοι διακρῖναι καὶ διορίσαι τό τε τοῦ ἐπαινοῦντος ἔργον καὶ τὴν τοῦ κόλακος ὑπερβολήν.", "st": "40.20"}, {"sp": "N", "t": "ὁ μὲν οὖν κόλαξ ἅτε τῆς χρείας ἕνεκα τῆς ἑαυτοῦ ἐπαινῶν, ἀληθείας δὲ ὀλίγην ποιούμενος τὴν πρόνοιαν, ἅπαντα ὑπερεπαινεῖν οἴεται δεῖν, ἐπιψευδόμενος καὶ προστιθεὶς παρ’ αὑτοῦ τὰ πλείω, ὡς μὴ ἂν ὀκνῆσαι καὶ τὸν Θερσίτην εὐμορφότερον ἀποφῆναι τοῦ Ἀχιλλέως καὶ τὸν Νέστορα φάναι τῶν ἐπὶ Ἴλιον στρατευσάντων τὸν νεώτατον εἶναι. διομόσαιτο δ’ ἂν καὶ τὸν Κροίσου υἱὸν ὀξυηκοώτερον εἶναι τοῦ Μελάμποδος καὶ τὸν Φινέα ὀξύτερον δεδορκέναι τοῦ Λυγκέως, ἤνπερ μόνον κερδᾶναί τι ἐλπίσῃ ἐπὶ τῷ ψεύσματι. ὁ δέ γε αὐτὸ τοῦτο ἐπαινῶν οὐχ ὅπως οὐδ’ ἂν ψεύσαιτό τι ἢ προσθείη τῶν μηδὲ ὅλως προσόντων, τὰ δ’ ὑπάρχοντα αὐτῷ φύσει ἀγαθά, κἂν μὴ πάνυ μεγάλα ᾖ, παραλαβὼν ἐπηύξησε καὶ μείζω ἀπέφηνε· καὶ τολμήσειεν ἂν εἰπεῖν, ἵππον ἐπαινέσαι θέλων, φύσει κοῦφον ὧν ἴσμεν ζῴων καὶ δρομικόν, ὅτι<br>Ἄκρον ἐπ’ ἀνθερίκων καρπὸν θέεν οὐδὲ κατέκλα.<br>καὶ πάλιν οὐκ ἂν ὀκνήσειεν φάναι “ἀελλοπόδων δρόμον ἵππων.” καὶ ἢν οἰκίαν ἐπαινῇ καλὴν καὶ ἄριστα κατεσκευασμένην, εἴποι ἄν<br>Ζηνός που τοιήδε γ’ Ὀλυμπίου ἔνδοθεν αὐλή.<br>ὁ δὲ κόλαξ τοῦτο τὸ ἔπος κἂν περὶ τῆς συβώτου καλύβης εἴποι, εἰ μόνον τι παρὰ τοῦ συβώτου λαβεῖν ἐλπίσειεν· ὅπου Κύναιθος ὁ Δημητρίου τοῦ Πολιορκητοῦ κόλαξ ἁπάντων αὐτῷ τῶν πρὸς τὴν κολακείαν καταναλωμένων ἐπῄνει ὑπὸ βηχὸς ἐνοχλούμενον τὸν Δημήτριον, ὅτι ἐμμελῶς ἐχρέμπτετο.", "st": "40.20"}, {"sp": "N", "t": "οὐ μόνον δὲ τοῦτο ἑκατέρου αὐτῶν γνώρισμά ἐστιν, τὸ τοὺς μὲν κόλακας οὐκ ὀκνεῖν καὶ ψεύδεσθαι τοῦ χαρίσασθαι ἕνεκα τοῖς ἐπαινουμένοις, ἐξαίρειν δὲ τοὺς ἐπαινοῦντας τὰ ὑπάρχοντα πειρᾶσθαι· ἀλλὰ κἀκείνῳ οὐ μικρῷ διαλλάττουσιν, ὅτι οἱ μὲν κόλακες, ἐφ’ ὅσον οἷόν τε αὐτοῖς, χρῶνται ταῖς ὑπερβολαῖς, οἱ ἐπαινοῦντες δὲ καὶ ἐν αὐταῖς ταύταις σωφρονοῦσιν καὶ ἐντὸς τῶν ὅρων μένουσιν.", "st": "40.21"}, {"sp": "N", "t": "ταῦτά σοι ἀπὸ πολλῶν ὀλίγα κολακείας καὶ ἐπαίνου ἀληθοῦς δείγματα, ὡς μὴ πάντας ὑποπτεύσῃς τοὺς ἐπαινοῦντας, ἀλλὰ διακρίνῃς καὶ παραμετρῇς τῷ οἰκείῳ μέτρῳ ἑκάτερον.", "st": "40.21"}, {"sp": "N", "t": "φέρ’ οὖν, εἰ δοκεῖ, πρόσαγε τοῖς ὑπ’ ἐμοῦ εἰρημένοις τοὺς κανόνας ἀμφοτέρους, ὡς μάθῃς εἴτε τούτῳ εἴτ’ ἐκείνῳ ἐοίκασιν. ἐγὼ γὰρ εἰ μέν τινα ἄμορφον οὖσαν ἔφην τῷ ἐν Κνίδῳ ἀγάλματι ὁμοίαν, γόης ἂν καὶ τοῦ Κυναίθου κολακικώτερος ὄντως νομιζοίμην· εἰ δὲ τοιαύτην ὑπάρχουσαν οἵαν πάντες ἴσασιν, οὐ πάνυ ἐκ πολλοῦ διαστήματος ἦν τὸ τόλμημα.", "st": "40.22"}, {"sp": "N", "t": "τάχ’ ἂν οὖν φαίης, μᾶλλον δὲ ἤδη εἴρηκας, “ἐπαινεῖν μέν σοι εἰς τὸ κάλλος ἐφείσθω· ἀνεπίφθονον μέντοι ποιήσασθαι τὸν ἔπαινον ἐχρῆν, ἀλλὰ μὴ θεαῖς ἀπεικάζειν ἄνθρωπον οὖσαν.” ἐγὼ δὲ — ἤδη γάρ με προάξεται τἀληθὲς εἰπεῖν — οὐ θεαῖς σε, ὦ βελτίστη, εἴκασα, τεχνιτῶν δὲ ἀγαθῶν δημιουργήμασιν λίθου καὶ χαλκοῦ ἢ ἐλέφαντος πεποιημένοις· τὰ δὲ ὑπ’ ἀνθρώπων γεγενημένα οὐκ ἀσεβές, οἶμαι, ἀνθρώποις εἰκάζειν. ἐκτὸς εἰ μὴ σὺ τοῦτο εἶναι τὴν Ἀθηνᾶν ὑπείληφας τὸ ὑπὸ Φειδίου πεπλασμένον ἢ τοῦτο τὴν οὐρανίαν Ἀφροδίτην ὃ ἐποίησεν Πραξιτέλης ἐν Κνίδῳ οὐ πάνυ πολλῶν ἐτῶν. ἀλλ’ ὅρα μὴ ἄσεμνον ᾖ τὰ τοιαῦτα περὶ τῶν θεῶν δοξάζειν, ὧν τάς γε ἀληθεῖς εἰκόνας ἀνεφίκτους εἶναι ἀνθρωπίνῃ μιμήσει ἔγωγε ὑπολαμβάνω.", "st": "40.23"}, {"sp": "N", "t": "εἰ δὲ καὶ ὅτι μάλιστά σε αὐταῖς ἐκείναις εἴκασα, οὐκ ἐμὸν τοῦτο, οὐδὲ ἐγὼ πρῶτος ταύτην ἐτεμόμην τὴν ὁδόν, ἀλλὰ πολλοὶ καὶ ἀγαθοὶ ποιηταί, καὶ μάλιστα ὁ πολίτης ὁ σὸς Ὅμηρος, ὃν καὶ νῦν ἀναβιβάσομαι συναγορεύσοντά μοι, ἢ οὐδεμία μηχανὴ μὴ οὐχὶ καὶ αὐτὸν σὺν ἐμοὶ ἁλῶναι.", "st": "40.24"}, {"sp": "N", "t": "ἐρήσομαι τοίνυν αὐτόν, μᾶλλον δὲ σὲ ὑπὲρ αὐτοῦ — καὶ γὰρ διαμνημονεύεις εὖ ποιοῦσα τὰ χαριέστατα τῶν ἐρραψῳδημένων αὐτῷ — τί σοι ἐκεῖνος δοκεῖ, ὁπόταν περὶ τῆς αἰχμαλώτου λέγῃ τῆς Βρισηΐδος ὅτι χρυσῇ Ἀφροδίτῃ ἰκέλη ἐπένθει τὸν Πάτροκλον; εἶτα μετὰ μικρόν, ὡς οὐχ ἱκανὸν εἰ μόνῃ τῇ Ἀφροδίτῃ ἐοικυῖα ἔσται,<br>εἶπε δ’ ἄρα — φησίν — κλαίουσα γυνὴ εἰκυῖα θεῇσιν.", "st": "40.24"}, {"sp": "N", "t": "ὁπόταν οὖν τὰ τοιαῦτα λέγῃ, μισεῖς κἀκεῖνον καὶ ἀπορρίπτεις τὸ βιβλίον, ἢ δίδως αὐτῷ ἐλευθεριάζειν ἐν τῷ ἐπαίνῳ; ἀλλὰ κἂν σὺ μὴ δῷς, ὅ γε τοσοῦτος αἰὼν δέδωκεν, οὐδ’ ἔστιν ὅστις αὐτὸν ἐπὶ τούτῳ ᾐτιάσατο, οὐδὲ ὁ μαστίξαι τολμήσας αὐτοῦ τὴν εἰκόνα οὐδ’ ὁ τὰ νόθα ἐπισημηνάμενος τῶν ἐπῶν ἐν τῇ παραγραφῇ τῶν ὀβελῶν.", "st": "40.24"}, {"sp": "N", "t": "εἶτα ἐκείνῳ μὲν ἐφεθήσεται βάρβαρον γυναῖκα, καὶ ταῦτα κλαίουσαν, τῇ χρυσῇ Ἀφροδίτῃ εἰκάσαι, ἐγὼ δ’, ἵνα μὴ τὸ κάλλος εἴπω, διότι μὴ ἀνέχῃ ἀκούουσα, οὐκ ἂν παραβάλλοιμι θεῶν εἰκόσι γυναῖκα φαιδρὰν καὶ μειδιῶσαν τὰ πολλά, ὅπερ θεοῖς ὅμοιον ἄνθρωποι ἔχουσιν;", "st": "40.24"}, {"sp": "N", "t": "ἐπὶ μέν γε τοῦ Ἀγαμέμνονος ὅρα ὅσην αὐτὸς φειδὼ ἐποιήσατο τῶν θεῶν καὶ ὡς ἐταμιεύσατο τὰς εἰκόνας εἰς τὸ σύμμετρον· ὡς ὄμματα μέν φησιν καὶ κεφαλὴν ἴκελον αὐτὸν εἶναι τῷ Διί, τῷ Ἄρεϊ δὲ τὴν ζώνην, στέρνον δὲ τῷ Ποσειδῶνι, διαιρῶν τὸν ἄνθρωπον κατὰ μέλη πρὸς τοσούτων θεῶν εἰκόνας· καὶ αὖ πάλιν βροτολοιγῷ Ἄρεΐ φησίν τιν’ ὅμοιον εἶναι καὶ ἄλλον ἄλλῳ, θεοειδῆ τὸν Φρύγα τὸν τοῦ Πριάμου, καὶ θεοείκελον πολλάκις τὸν Πηλέως.", "st": "40.25"}, {"sp": "N", "t": "ἀλλὰ ἐπάνειμι αὖθις ἐπὶ τὰ γυναικεῖα τῶν παραδειγμάτων· ἀκούεις γὰρ δή που αὐτοῦ λέγοντος<br>Ἀρτέμιδι ἰκέλη ἠὲ χρυσέῃ Ἀφροδίτῃ.<br>καὶ<br>οἵη δ’ Ἄρτεμις εἶσι κατ’ οὔρεος.", "st": "40.25"}, {"sp": "N", "t": "οὐ μόνον δὲ τοὺς ἀνθρώπους αὐτοὺς θεοῖς ἀπεικάζει, ἀλλὰ καὶ τὴν Εὐφόρβου κόμην ταῖς Χάρισιν ἀπείκασε, καὶ ταῦτα αἵματι δεδευμένην. καὶ ὅλως τοσαῦτά ἐστιν τὰ τοιαῦτα ὡς μηδὲν εἶναι μέρος τῆς ποιήσεως ὃ μὴ ταῖς θείαις εἰκόσιν διακεκόσμηται. ὥστε ἢ κἀκεῖνα ἐξαληλίφθω, ἢ καὶ ἡμῖν τὰ ὅμοια τολμᾶν ἐφείσθω. οὕτω δὲ τὸ κατὰ τὰς εἰκόνας καὶ τὰς ὁμοιώσεις ἀνεύθυνόν ἐστιν ὥστε Ὅμηρος καὶ τὰς θεὰς αὐτὰς οὐκ ὤκνησεν ἀπὸ τῶν ἐλαττόνων ἐπαινέσαι· τοὺς γοῦν τῆς Ἥρας ὀφθαλμοὺς τοῖς τῶν βοῶν εἴκασεν· ἕτερος δέ τις ἰοβλέφαρον τὴν Ἀφροδίτην ἔφη. τὴν μὲν γὰρ ῥοδοδάκτυλον τίς ἀγνοεῖ τῶν κἂν ἐπ’ ἐλάχιστον τῇ Ὁμήρου ποιήσει ὡμιληκότων;", "st": "40.26"}, {"sp": "N", "t": "Καίτοι τὰ μὲν τῆς μορφῆς ἔτι μετριώτερα, εἰ τις θεῷ ἐοικέναι λέγεται· ἀλλὰ τὰς προσηγορίας αὐτὰς πόσοι ἐμιμήσαντο τὰς τῶν θεῶν, Διονύσιοι καὶ Ἡφαιστίωνες καὶ Ζήνωνες καὶ Ποσειδώνιοι καὶ Ἑρμαῖ προσαγορευόμενοι; Λητὼ δὲ γυνή τις ἐγένετο Εὐαγόρου τοῦ Κυπρίων βασιλέως, καὶ ὅμως οὐκ ἠγανάκτησεν ἡ θεὸς δυναμένη λίθον αὐτὴν ὥσπερ τὴν Νιόβην ἀπεργάσασθαι. ἐῶ γὰρ τοὺς Αἰγυπτίους, οἵπερ καὶ δεισιδαιμονέστατοί εἰσιν πάντων, ὅμως τοῖς θείοις ὀνόμασιν εἰς κόρον ἐπιχρωμένους· σχεδὸν γοῦν τὰ πλεῖστα αὐτοῖς ἐξ οὐρανοῦ ἐστιν.", "st": "40.27"}, {"sp": "N", "t": "ὥστε οὐ πρός γε σοῦ τὸ τοιοῦτον, ψοφοδεῶς διακεῖσθαι πρὸς τὸν ἔπαινον· εἰ γάρ τι ἐν τῷ συγγράμματι πεπλημμέληται εἰς τὸ θεῖον, σὺ μὲν ἀνεύθυνος αὐτοῦ, ἐκτὸς εἰ μή τινα νομίζεις ἀκροάσεως εὔθυναν εἶναι, ἐμὲ δὲ ἀμυνοῦνται οἱ θεοί, ἐπειδὰν πρὸ ἐμοῦ τὸν Ὅμηρον καὶ τοὺς ἄλλους ποιητὰς ἀμύνωνται. ἀλλ’ οὐδέπω οὐδὲ τὸν ἄριστον τῶν φιλοσόφων ἠμύναντο εἰκόνα θεοῦ τὸν ἄνθρωπον εἰπόντα εἶναι.", "st": "40.28"}, {"sp": "N", "t": "πολλὰ ἔτι ἔχων πρὸς σὲ εἰπεῖν Πολυστράτου ἕνεκα τούτου παύσομαι, ἵνα καὶ ἀπομνημονεῦσαι δυνηθῇ τὰ εἰρημένα.", "st": "40.28"}, {"sp": "N", "t": "<em>Πολύστρατος.<\/em> οὐκ οἶδα εἴ μοι τοῦτο δυνατὸν ἔτι, ὦ Λυκῖνε· μακρὰ γὰρ εἴρηταί σοι καὶ ταῦτα, καὶ ὑπὲρ τὸ ὕδωρ τὸ ἐκκεχυμένον. πειράσομαι δ’ ὅμως ἐπιμνησθῆναι αὐτῶν. καὶ ὡς ὁρᾷς, ἤδη ἀποσοβῶ παρ’ αὐτὴν ἐπιβυσάμενος τὰ ὦτα, ὡς μή τι παρεμπεσὸν ἄλλο συγχέῃ τὴν τάξιν αὐτῶν, εἶτά μοι συρίττεσθαι συμβῇ πρὸς τῶν θεατῶν.", "st": "40.29"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> αὐτῷ σοι μελήσει, ὦ Πολύστρατε, ὅπως ἄριστα ὑποκρίνῃ. ἐγὼ δὲ ἐπείπερ ἅπαξ σοι τὸ δρᾶμα παραδέδωκα, νῦν μὲν ἐκποδὼν ἀποστήσομαι· ὁπόταν δὲ τὰς ψήφους ἀνακηρύττωσι τῶν κριτῶν, τότε ἤδη καὶ αὐτὸς παρέσομαι ὀψόμενος ὁποῖόν τι τὸ τέλος τοῦ ἀγῶνος ἔσται.", "st": "40.29"}, {"sp": "HDR", "t": "Περὶ τῆς Περεγρίνου Τελευτῆς"}, {"sp": "N", "t": "Λουκιανὸς Κρονίῳ εὖ πράττειν.", "st": "42.1"}, {"sp": "N", "t": "Λουκιανὸς κακοδαίμων Περεγρῖνος, ἢ ὡς αὐτὸς ἔχαιρεν ὀνομάζων ἑαυτόν, Πρωτεύς, αὐτὸ δὴ ἐκεῖνο τὸ τοῦ Ὁμηρικοῦ Πρωτέως ἔπαθεν· ἅπαντα γὰρ δόξης ἕνεκα γενόμενος καὶ μυρίας τροπὰς τραπόμενος, τὰ τελευταῖα ταῦτα καὶ πῦρ ἐγένετο· τοσούτῳ ἄρα τῷ ἔρωτι τῆς δόξης εἴχετο. καὶ νῦν ἐκεῖνος ἀπηνθράκωταί σοι Λουκιανὸς βέλτιστος κατὰ τὸν Ἐμπεδοκλέα, παρ’ ὅσον Λουκιανὸς μὲν κἂν διαλαθεῖν ἐπειράθη ἐμβαλὼν ἑαυτὸν εἰς τοὺς κρατῆρας, Λουκιανὸς δὲ γεννάδας οὗτος, τὴν πολυανθρωποτάτην τῶν Ἑλληνικῶν πανηγύρεων τηρήσας, πυρὰν ὅτι μεγίστην νήσας ἐνεπήδησεν ἐπὶ τοσούτων μαρτύρων, καὶ λόγους τινὰς ὑπὲρ τούτου εἰπὼν πρὸς τοὺς Ἕλληνας οὐ πρὸ πολλῶν ἡμερῶν τοῦ τολμήματος.", "st": "42.1"}, {"sp": "N", "t": "πολλὰ τοίνυν δοκῶ μοι ὁρᾶν σε γελῶντα ἐπὶ τῇ κορύζῃ τοῦ γέροντος, μᾶλλον δὲ καὶ ἀκούω βοῶντος οἷά σε εἰκὸς βοᾶν, “ὢ τῆς ἀβελτερίας, ὢ τῆς δοξοκοπίας, ὢ —” τῶν ἄλλων ἃ λέγειν εἰώθαμεν περὶ αὐτῶν. σὺ μὲν οὖν πόρρω ταῦτα καὶ μακρῷ ἀσφαλέστερον, ἐγὼ δὲ παρὰ τὸ πῦρ αὐτὸ καὶ ἔτι πρότερον ἐν πολλῷ πλήθει τῶν ἀκροατῶν εἶπον αὐτά, ἐνίων μὲν ἀχθομένων, ὅσοι ἐθαύμαζον τὴν ἀπόνοιαν τοῦ γέροντος· ἦσαν δέ τινες οἳ καὶ αὐτοὶ ἐγέλων ἐπ’ αὐτῷ. ἀλλ’ ὀλίγου δεῖν ὑπὸ τῶν Κυνικῶν ἐγώ σοι διεσπάσθην ὥσπερ ὁ Ἀκταίων ὑπὸ τῶν κυνῶν ἢ ὁ ἀνεψιὸς αὐτοῦ ὁ Πενθεὺς ὑπὸ τῶν Μαινάδων.", "st": "42.2"}, {"sp": "N", "t": "ἡ δὲ πᾶσα τοῦ πράγματος διασκευὴ τοιάδε ἦν. τὸν μὲν ποιητὴν οἶσθα οἷός τε ἦν καὶ ἡλίκα ἐτραγῴδει παρ’ ὅλον τὸν βίον, ὑπὲρ τὸν Σοφοκλέα καὶ τὸν Αἰσχύλον. ἐγὼ δὲ ἐπεὶ τάχιστα εἰς τὴν Ἦλιν ἀφικόμην, διὰ τοῦ γυμνασίου ἀνιὼν ἐπήκουον ἅμα Κυνικοῦ τινος μεγάλῃ καὶ τραχείᾳ τῇ φωνῇ τὰ συνήθη ταῦτα καὶ ἐκ τριόδου τὴν ἀρετὴν ἐπιβοωμένου καὶ ἅπασιν ἁπαξαπλῶς λοιδορουμένου. εἶτα κατέληξεν αὐτῷ ἡ βοὴ ἐς τὸν Πρωτέα, καὶ ὡς ἂν οἷός τε ὦ πειράσομαί σοι αὐτὰ ἐκεῖνα ἀπομνημονεῦσαι ὡς ἐλέγετο. σὺ δὲ γνωριεῖς δηλαδή, πολλάκις αὐτοῖς παραστὰς βοῶσιν.", "st": "42.3"}, {"sp": "N", "t": "“Πρωτέα γάρ τις,” ἔφη, “κενόδοξον τολμᾷ λέγειν, ὦ γῆ καὶ ἥλιε καὶ ποταμοὶ καὶ θάλαττα καὶ πατρῷε Ἡράκλεις — Πρωτέα τὸν ἐν Συρίᾳ δεθέντα, τὸν τῇ πατρίδι ἀνέντα πεντακισχίλια τάλαντα, τὸν ἀπὸ τῆς Ῥωμαίων πόλεως ἐκβληθέντα, τὸν τοῦ Ἡλίου ἐπισημότερον, τὸν αὐτῷ ἀνταγωνίσασθαι τῷ Ὀλυμπίῳ δυνάμενον; ἀλλ’ ὅτι διὰ πυρὸς ἐξάγειν τοῦ βίου διέγνωκεν ἑαυτόν, εἰς κενοδοξίαν τινὲς τοῦτο ἀναφέρουσιν; οὐ γὰρ Ἡρακλῆς οὕτως; οὐ γὰρ Ἀσκληπιὸς καὶ Διόνυσος κεραυνῷ; οὐ γὰρ τὰ τελευταῖα Ἐμπεδοκλῆς εἰς τοὺς κρατῆρας;”", "st": "42.4"}, {"sp": "N", "t": "ὡς δὲ ταῦτα εἶπεν ὁ Θεαγένης — τοῦτο γὰρ ὁ κεκραγὼς ἐκεῖνος ἐκαλεῖτο — ἠρόμην τινὰ τῶν παρεστώτων, “τί βούλεται τὸ περὶ τοῦ πυρός, ἢ τί Ἡρακλῆς καὶ Ἐμπεδοκλῆς πρὸς τὸν Πρωτέα.” ὁ δέ, “οὐκ εἰς μακράν,” ἔφη, “καύσει ἑαυτὸν ὁ Πρωτεὺς Ὀλυμπίασιν.” “πῶς,” ἔφην, “ἢ τίνος ἕνεκα;” εἶτα ὁ μὲν ἐπειρᾶτο λέγειν, ἐβόα δὲ ὁ Κυνικός, ὥστε ἀμήχανον ἦν ἄλλου ἀκούειν. ἐπήκουον οὖν τὰ λοιπὰ ἐπαντλοῦντος αὐτοῦ καὶ θαυμαστάς τινας ὑπερβολὰς διεξιόντος κατὰ τοῦ Πρωτέως· τὸν μὲν γὰρ Σινωπέα ἢ τὸν διδάσκαλον αὐτοῦ Ἀντισθένη οὐδὲ παραβάλλειν ἠξίου αὐτῷ, ἀλλ’ οὐδὲ τὸν Σωκράτη αὐτόν, ἐκάλει δὲ τὸν Δία ἐπὶ τὴν ἅμιλλαν. εἶτα μέντοι ἔδοξεν αὐτῷ ἴσους πως φυλάξαι αὐτούς, καὶ οὕτω κατέπαυε τὸν λόγον·", "st": "42.5"}, {"sp": "N", "t": "“δύο γὰρ ταῦτα,” ἔφη, “ὁ βίος ἄριστα δημιουργήματα ἐθεάσατο, τὸν Δία τὸν Ὀλύμπιον καὶ Πρωτέα· πλάσται δὲ καὶ τεχνῖται, τοῦ μὲν Φειδίας, τοῦ δὲ ἡ φύσις. ἀλλὰ νῦν ἐξ ἀνθρώπων εἰς θεοὺς τὸ ἄγαλμα τοῦτο οἰχήσεται, ὀχούμενον ἐπὶ τοῦ πυρός, ὀρφανοὺς ἡμᾶς καταλιπόν.” ταῦτα ξὺν πολλῷ ἱδρῶτι διεξελθὼν ἐδάκρυε μάλα γελοίως καὶ τὰς τρίχας ἐτίλλετο, ὑποφειδόμενος μὴ πάνυ ἕλκειν· καὶ τέλος ἀπῆγον αὐτὸν λύζοντα μεταξὺ τῶν Κυνικῶν τινες παραμυθούμενοι.", "st": "42.6"}, {"sp": "N", "t": "μετὰ δὲ τοῦτον ἄλλος εὐθὺς ἀναβαίνει, οὐ περιμείνας διαλυθῆναι τὸ πλῆθος ἀλλὰ ἐπ’ αἰθομένοις τοῖς προτέροις ἱερείοις ἐπέχει τῶν σπονδῶν. καὶ τὸ μὲν πρῶτον ἐπὶ πολὺ ἐγέλα καὶ δῆλος ἦν νειόθεν αὐτὸ δρῶν· εἶτα ἤρξατο ὧδέ πως· “ἐπεὶ ὁ κατάρατος Θεαγένης τέλος τῶν μιαρωτάτων αὐτοῦ λόγων τὰ Ἡρακλείτου δάκρυα ἐποιήσατο, ἐγὼ κατὰ τὸ ἐναντίον ἀπὸ τοῦ Δημοκρίτου γέλωτος ἄρξομαι.” καὶ αὖθις ἐγέλα ἐπὶ πολύ, ὥστε καὶ ἡμῶν τοὺς πολλοὺς ἐπὶ τὸ ὅμοιον ἐπεσπάσατο.", "st": "42.7"}, {"sp": "N", "t": "εἶτα ἐπιστρέψας ἑαυτόν, “ἢ τί γὰρ ἄλλο,” ἔφη, ὦ ἄνδρες, χρὴ ποιεῖν ἀκούοντας μὲν οὕτω γελοίων ῥήσεων, ὁρῶντας δὲ ἄνδρας γέροντας δοξαρίου καταπτύστου ἕνεκα μονονουχὶ κυβιστῶντας ἐν τῷ μέσῳ; ὡς δὲ εἰδείητε οἷόν τι τὸ ἄγαλμά ἐστι τὸ καυθησόμενον, ἀκούσατέ μου ἐξ ἀρχῆς παραφυλάξαντος τὴν γνώμην αὐτοῦ καὶ τὸν βίον ἐπιτηρήσαντος· ἔνια δὲ παρὰ τῶν πολιτῶν αὐτοῦ ἐπυνθανόμην καὶ οἷς ἀνάγκη ἦν ἀκριβῶς εἰδέναι αὐτόν.", "st": "42.8"}, {"sp": "N", "t": "τὸ γὰρ τῆς φύσεως τοῦτο πλάσμα καὶ δημιούργημα, ὁ τοῦ Πολυκλείτου κανών, ἐπεὶ εἰς ἄνδρας τελεῖν ἤρξατο, ἐν Ἀρμενίᾳ μοιχεύων ἁλοὺς μάλα πολλὰς πληγὰς ἔλαβεν καὶ τέλος κατὰ τοῦ τέγους ἁλόμενος διέφυγε, ῥαφανῖδι τὴν πυγὴν βεβυσμένος. εἶτα μειράκιόν τι ὡραῖον διαφθείρας τρισχιλίων ἐξωνήσατο παρὰ τῶν γονέων τοῦ παιδός, πενήτων ὄντων, μὴ ἐπὶ τὸν ἁρμοστὴν ἀπαχθῆναι τῆς Ἀσίας.", "st": "42.9"}, {"sp": "N", "t": "ταῦτα καὶ τὰ τοιαῦτα ἐάσειν μοι δοκῶ· πηλὸς γὰρ ἔτι ἄπλαστος ἦν καὶ οὐδέπω ἐντελὲς ἄγαλμα ἡμῖν δεδημιούργητο. ἃ δὲ τὸν πατέρα ἔδρασεν καὶ πάνυ ἀκοῦσαι ἄξιον· καίτοι πάντες ἴστε, καὶ ἀκηκόατε ὡς ἀπέπνιξε τὸν γέροντα, οὐκ ἀνασχόμενος αὐτὸν ὑπὲρ ἑξήκοντα ἔτη ἤδη γηρῶντα. εἶτα ἐπειδὴ τὸ πρᾶγμα διεβεβόητο, φυγὴν ἑαυτοῦ καταδικάσας ἐπλανᾶτο ἄλλοτε ἄλλην ἀμείβων.", "st": "42.10"}, {"sp": "N", "t": "ὅτεπερ καὶ τὴν θαυμαστὴν σοφίαν τῶν Χριστιανῶν ἐξέμαθεν, περὶ τὴν Παλαιστίνην τοῖς ἱερεῦσιν καὶ γραμματεῦσιν αὐτῶν ξυγγενόμενος. καὶ τί γάρ; ἐν βραχεῖ παῖδας αὐτοὺς ἀπέφηνε, προφήτης καὶ θιασάρχης καὶ ξυναγωγεὺς καὶ πάντα μόνος αὐτὸς ὤν, καὶ τῶν βίβλων τὰς μὲν ἐξηγεῖτο καὶ διεσάφει, πολλὰς δὲ αὐτὸς καὶ συνέγραφεν, καὶ ὡς θεὸν αὐτὸν ἐκεῖνοι ᾐδοῦντο καὶ νομοθέτῃ ἐχρῶντο καὶ προστάτην ἐπεγράφοντο, μετὰ γοῦν ἐκεῖνον ὃν ἔτι σέβουσι, τὸν ἄνθρωπον τὸν ἐν τῇ Παλαιστίνῃ ἀνασκολοπισθέντα, ὅτι καινὴν ταύτην τελετὴν εἰσῆγεν ἐς τὸν βίον.", "st": "42.11"}, {"sp": "N", "t": "τότε δὴ καὶ συλληφθεὶς ἐπὶ τούτῳ ὁ Πρωτεὺς ἐνέπεσεν εἰς τὸ δεσμωτήριον, ὅπερ καὶ αὐτὸ οὐ μικρὸν αὐτῷ ἀξίωμα περιεποίησεν πρὸς τὸν ἑξῆς βίον καὶ τὴν τερατείαν καὶ δοξοκοπίαν ὧν ἐρῶν ἐτύγχανεν. ἐπεὶ δ’ οὖν ἐδέδετο, οἱ Χριστιανοὶ συμφορὰν ποιούμενοι τὸ πρᾶγμα πάντα ἐκίνουν ἐξαρπάσαι πειρώμενοι αὐτόν. εἶτ’, ἐπεὶ τοῦτο ἦν ἀδύνατον, ἥ γε ἄλλη θεραπεία πᾶσα οὐ παρέργως ἀλλὰ σὺν σπουδῇ ἐγίγνετο· καὶ ἕωθεν μὲν εὐθὺς ἦν ὁρᾶν παρὰ τῷ δεσμωτηρίῳ περιμένοντα γρᾴδια χήρας τινὰς καὶ παιδία ὀρφανά, οἱ δὲ ἐν τέλει αὐτῶν καὶ συνεκάθευδον ἔνδον μετ’ αὐτοῦ διαφθείραντες τοὺς δεσμοφύλακας. εἶτα δεῖπνα ποικίλα εἰσεκομίζετο καὶ λόγοι ἱεροὶ αὐτῶν ἐλέγοντο, καὶ ὁ βέλτιστος Περεγρῖνος — ἔτι γὰρ τοῦτο ἐκαλεῖτο — καινὸς Σωκράτης ὑπ’ αὐτῶν ὠνομάζετο.", "st": "42.12"}, {"sp": "N", "t": "καὶ μὴν κἀκ τῶν ἐν Ἀσίᾳ πόλεων ἔστιν ὧν ἧκόν τινες, τῶν Χριστιανῶν στελλόντων ἀπὸ τοῦ κοινοῦ, βοηθήσοντες καὶ συναγορεύσοντες καὶ παραμυθησόμενοι τὸν ἄνδρα. ἀμήχανον δέ τι τὸ τάχος ἐπιδείκνυνται, ἐπειδάν τι τοιοῦτον γένηται δημόσιον· ἐν βραχεῖ γὰρ ἀφειδοῦσι πάντων. καὶ δὴ καὶ τῷ Περεγρίνῳ πολλὰ τότε ἧκεν χρήματα παρ’ αὐτῶν ἐπὶ προφάσει τῶν δεσμῶν, καὶ πρόσοδον οὐ μικρὰν ταύτην ἐποιήσατο. πεπείκασι γὰρ αὑτοὺς οἱ κακοδαίμονες τὸ μὲν ὅλον ἀθάνατοι ἔσεσθαι καὶ βιώσεσθαι τὸν ἀεὶ χρόνον, παρ’ ὃ καὶ καταφρονοῦσιν τοῦ θανάτου καὶ ἑκόντες αὑτοὺς ἐπιδιδόασιν οἱ πολλοί. ἔπειτα δὲ ὁ νομοθέτης ὁ πρῶτος ἔπεισεν αὐτοὺς ὡς ἀδελφοὶ πάντες εἶεν ἀλλήλων, ἐπειδὰν ἅπαξ παραβάντες θεοὺς μὲν τοὺς Ἑλληνικοὺς ἀπαρνήσωνται, τὸν δὲ ἀνεσκολοπισμένον ἐκεῖνον σοφιστὴν αὐτὸν προσκυνῶσιν καὶ κατὰ τοὺς ἐκείνου νόμους βιῶσιν. καταφρονοῦσιν οὖν ἁπάντων ἐξ ἴσης καὶ κοινὰ ἡγοῦνται, ἄνευ τινὸς ἀκριβοῦς πίστεως τὰ τοιαῦτα παραδεξάμενοι. ἢν τοίνυν παρέλθῃ τις εἰς αὐτοὺς γόης καὶ τεχνίτης ἄνθρωπος καὶ πράγμασιν χρῆσθαι δυνάμενος, αὐτίκα μάλα πλούσιος ἐν βραχεῖ ἐγένετο ἰδιώταις ἀνθρώποις ἐγχανών.", "st": "42.13"}, {"sp": "N", "t": "πλὴν ἀλλ’ ὁ Περεγρῖνος ἀφείθη ὑπὸ τοῦ τότε τῆς Συρίας ἄρχοντος, ἀνδρὸς φιλοσοφίᾳ χαίροντος, ὃς συνεὶς τὴν ἀπόνοιαν αὐτοῦ καὶ ὅτι δέξαιτ’ ἂν ἀποθανεῖν ὡς δόξαν ἐπὶ τούτῳ ἀπολίποι, ἀφῆκεν αὐτὸν οὐδὲ τῆς κολάσεως ὑπολαβὼν ἄξιον. ὁ δὲ εἰς τὴν οἰκείαν ἐπανελθὼν καταλαμβάνει τὸ περὶ τοῦ πατρῴου φόνου ἔτι φλεγμαῖνον καὶ πολλοὺς τοὺς ἐπανατεινομένους τὴν κατηγορίαν. διήρπαστο δὲ τὰ πλεῖστα τῶν κτημάτων παρὰ τὴν ἀποδημίαν αὐτοῦ καὶ μόνοι ὑπελείποντο οἱ ἀγροὶ ὅσον εἰς πεντεκαίδεκα τάλαντα. ἦν γὰρ ἡ πᾶσα οὐσία τριάκοντά που ταλάντων ἀξία ἣν ὁ γέρων κατέλιπεν, οὐχ ὥσπερ ὁ παγγέλοιος Θεαγένης ἔλεγε πεντακισχιλίων· τοσούτου γὰρ οὐδὲ ἡ πᾶσα τῶν Παριανῶν πόλις πέντε σὺν αὐτῇ τὰς γειτνιώσας παραλαβοῦσα πραθείη ἂν αὐτοῖς ἀνθρώποις καὶ βοσκήμασιν καὶ τῇ λοιπῇ παρασκευῇ.", "st": "42.14"}, {"sp": "N", "t": "ἀλλ’ ἔτι γε ἡ κατηγορία καὶ τὸ ἔγκλημα θερμὸν ἦν, καὶ ἐῴκει οὐκ εἰς μακρὰν ἐπαναστήσεσθαί τις αὐτῷ, καὶ μάλιστα ὁ δῆμος αὐτὸς ἠγανάκτει, χρηστόν, ὡς ἔφασαν οἱ ἰδόντες, γέροντα πενθοῦντες οὕτως ἀσεβῶς ἀπολωλότα. ὁ δὲ σοφὸς οὗτος Πρωτεὺς πρὸς ἅπαντα ταῦτα σκέψασθε οἷόν τι ἐξεῦρεν καὶ ὅπως τὸν κίνδυνον διέφυγεν. παρελθὼν γὰρ εἰς τὴν ἐκκλησίαν τῶν Παριανῶν — ἐκόμα δὲ ἤδη καὶ τρίβωνα πιναρὸν ἠμπείχετο καὶ πήραν παρήρτητο καὶ τὸ ξύλον ἐν τῇ χειρὶ ἦν, καὶ ὅλως μάλα τραγικῶς ἐσκεύαστο — τοιοῦτος οὖν ἐπιφανεὶς αὐτοῖς ἀφεῖναι ἔφη τὴν οὐσίαν ἣν ὁ μακαρίτης πατὴρ αὐτῷ κατέλιπεν δημοσίαν εἶναι πᾶσαν. τοῦτο ὡς ἤκουσεν ὁ δῆμος, πένητες ἄνθρωποι καὶ πρὸς διανομὰς κεχηνότες, ἀνέκραγον εὐθὺς ἕνα φιλόσοφον, ἕνα φιλόπατριν, ἕνα Διογένους καὶ Κράτητος ζηλωτήν. οἱ δὲ ἐχθροὶ ἐπεφίμωντο, κἂν εἴ τις ἐπιχειρήσειεν μεμνῆσθαι τοῦ φόνου, λίθοις εὐθὺς ἐβάλλετο.", "st": "42.15"}, {"sp": "N", "t": "ἐξῄει οὖν τὸ δεύτερον πλανησόμενος, ἱκανὰ ἐφόδια τοὺς Χριστιανοὺς ἔχων, ὑφ’ ὧν δορυφορούμενος ἐν ἅπασιν ἀφθόνοις ἦν. καὶ χρόνον μέν τινα οὕτως ἐβόσκετο· εἶτα παρανομήσας τι καὶ ἐς ἐκείνους — ὤφθη γάρ τι, ὡς οἶμαι, ἐσθίων τῶν ἀπορρήτων αὐτοῖς — οὐκέτι προσιεμένων αὐτὸν ἀπορούμενος ἐκ παλινῳδίας ἀπαιτεῖν ᾤετο δεῖν παρὰ τῆς πόλεως τὰ κτήματα, καὶ γραμματεῖον ἐπιδοὺς ἠξίου ταῦτα κομίσασθαι κελεύσαντος βασιλέως. εἶτα τῆς πόλεως ἀντιπρεσβευσαμένης οὐδὲν ἐπράχθη, ἀλλ’ ἐμμένειν ἐκελεύσθη οἷς ἅπαξ διέγνω μηδενὸς καταναγκάσαντος.", "st": "42.16"}, {"sp": "N", "t": "τρίτη ἐπὶ τούτοις ἀποδημία εἰς Αἴγυπτον παρὰ τὸν Ἀγαθόβουλον, ἵναπερ τὴν θαυμαστὴν ἄσκησιν διησκεῖτο, ξυρόμενος μὲν τῆς κεφαλῆς τὸ ἥμισυ, χριόμενος δὲ πηλῷ τὸ πρόσωπον, ἐν πολλῷ δὲ τῶν περιεστώτων δήμῳ ἀναφλῶν τὸ αἰδοῖον καὶ τὸ ἀδιάφορον δὴ τοῦτο καλούμενον ἐπιδεικνύμενος, εἶτα παίων καὶ παιόμενος νάρθηκι εἰς τὰς πυγὰς καὶ ἄλλα πολλὰ νεανικώτερα θαυματοποιῶν.", "st": "42.17"}, {"sp": "N", "t": "ἐκεῖθεν δὲ οὕτω παρεσκευασμένος ἐπὶ Ἰταλίας ἔπλευσεν καὶ ἀποβὰς τῆς νεὼς εὐθὺς ἐλοιδορεῖτο πᾶσι, καὶ μάλιστα τῷ βασιλεῖ, πρᾳότατον αὐτὸν καὶ ἡμερώτατον εἰδώς, ὥστε ἀσφαλῶς ἐτόλμα· ἐκείνῳ γάρ, ὡς εἰκός, ὀλίγον ἔμελεν τῶν βλασφημιῶν καὶ οὐκ ἠξίου τὴν φιλοσοφίαν ὑποδυόμενόν τινα κολάζειν ἐπὶ ῥήμασι καὶ μάλιστα τέχνην τινὰ τὸ λοιδορεῖσθαι πεποιημένον. τούτῳ δὲ καὶ ἀπὸ τούτων τὰ τῆς δόξης ηὐξάνετο, παρὰ γοῦν τοῖς ἰδιώταις, καὶ περίβλεπτος ἦν ἐπὶ τῇ ἀπονοίᾳ, μέχρι δὴ ὁ τὴν πόλιν ἐπιτετραμμένος ἀνὴρ σοφὸς ἀπέπεμψεν αὐτὸν ἀμέτρως ἐντρυφῶντα τῷ πράγματι, εἰπὼν μὴ δεῖσθαι τὴν πόλιν τοιούτου φιλοσόφου. πλὴν ἀλλὰ καὶ τοῦτο κλεινὸν αὐτοῦ καὶ διὰ στόματος ἦν ἅπασιν, ὁ φιλόσοφος διὰ τὴν παρρησίαν καὶ τὴν ἄγαν ἐλευθερίαν ἐξελαθείς, καὶ προσήλαυνε κατὰ τοῦτο τῷ Μουσωνίῳ καὶ Δίωνι καὶ Ἐπικτήτῳ καὶ εἴ τις ἄλλος ἐν περιστάσει τοιαύτῃ ἐγένετο.", "st": "42.18"}, {"sp": "N", "t": "οὕτω δὴ ἐπὶ τὴν Ἑλλάδα ἐλθὼν ἄρτι μὲν Ἠλείοις ἐλοιδορεῖτο, ἄρτι δὲ τοὺς Ἕλληνας ἔπειθεν ἀντάρασθαι ὅπλα Ῥωμαίοις, ἄρτι δὲ ἄνδρα παιδείᾳ καὶ ἀξιώματι προὔχοντα, διότι καὶ ἐν τοῖς ἄλλοις εὖ ἐποίησεν τὴν Ἑλλάδα καὶ ὕδωρ ἐπήγαγεν τῇ Ὀλυμπίᾳ καὶ ἔπαυσε δίψει ἀπολλυμένους τοὺς πανηγυριστάς, κακῶς ἠγόρευεν ὡς καταθηλύναντα τοὺς Ἕλληνας, δέον τοὺς θεατὰς τῶν Ὀλυμπίων διακαρτερεῖν διψῶντας καὶ νὴ Δία γε καὶ ἀποθνήσκειν πολλοὺς αὐτῶν ὑπὸ σφοδρῶν τῶν νόσων, αἳ τέως διὰ τὸ ξηρὸν τοῦ χωρίου ἐν πολλῷ τῷ πλήθει ἐπεπόλαζον. καὶ ταῦτα ἔλεγε πίνων τοῦ αὐτοῦ ὕδατος.", "st": "42.19"}, {"sp": "N", "t": "ὡς δὲ μικροῦ κατέλευσαν αὐτὸν ἐπιδραμόντες ἅπαντες, τότε μὲν ἐπὶ τὸν Δία καταφυγὼν ὁ γενναῖος εὕρετο μὴ ἀποθανεῖν,", "st": "42.19"}, {"sp": "N", "t": "ἐς δὲ τὴν ἑξῆς Ὀλυμπιάδα λόγον τινὰ διὰ τεττάρων ἐτῶν συνθεὶς τῶν διὰ μέσου ἐξήνεγκε πρὸς τοὺς Ἕλληνας, ἔπαινον ὑπὲρ τοῦ τὸ ὕδωρ ἐπαγαγόντος καὶ ἀπολογίαν ὑπὲρ τῆς τότε φυγῆς.", "st": "42.20"}, {"sp": "N", "t": "ἤδη δὲ ἀμελούμενος ὑφ’ ἁπάντων καὶ μηκέθ’ ὁμοίως περίβλεπτος ὤν — ἕωλα γὰρ ἦν ἅπαντα καὶ οὐδὲν ἔτι καινουργεῖν ἐδύνατο ἐφ’ ὅτῳ ἐκπλήξει τοὺς ἐντυγχάνοντας καὶ θαυμάζειν καὶ πρὸς αὐτὸν ἀποβλέπειν ποιήσει, οὗπερ ἐξ ἀρχῆς δριμύν τινα ἔρωτα ἐρῶν ἐτύγχανεν — τὸ τελευταῖον τοῦτο τόλμημα ἐβουλεύσατο περὶ τῆς πυρᾶς, καὶ διέδωκε λόγον ἐς τοὺς Ἕλληνας εὐθὺς ἀπ’ Ὀλυμπίων τῶν ἔμπροσθεν ὡς ἐς τοὐπιὸν καύσων ἑαυτόν.", "st": "42.20"}, {"sp": "N", "t": "καὶ νῦν αὐτὰ ταῦτα θαυματοποιεῖ, ὥς φασι, βόθρον ὀρύττων καὶ ξύλα συγκομίζων καὶ δεινήν τινα τὴν καρτερίαν ὑπισχνούμενος.", "st": "42.21"}, {"sp": "N", "t": "ἐχρῆν δέ, οἶμαι, μάλιστα μὲν περιμένειν τὸν θάνατον καὶ μὴ δραπετεύειν ἐκ τοῦ βίου· εἰ δὲ καὶ πάντως διέγνωστό οἱ ἀπαλλάττεσθαι, μὴ πυρὶ μηδὲ τοῖς ἀπὸ τῆς τραγῳδίας τούτοις χρῆσθαι, ἀλλ’ ἕτερόν τινα θανάτου τρόπον, μυρίων ὄντων, ἑλόμενον ἀπελθεῖν. εἰ δὲ καὶ τὸ πῦρ ὡς Ἡράκλειόν τι ἀσπάζεται, τί δή ποτε οὐχὶ κατὰ σιγὴν ἑλόμενος ὄρος εὔδενδρον ἐν ἐκείνῳ ἑαυτὸν ἐνέπρησεν μόνος, ἕνα τινὰ οἷον Θεαγένη τοῦτον Φιλοκτήτην παραλαβών; ὁ δὲ ἐν Ὀλυμπίᾳ τῆς πανηγύρεως πληθούσης μόνον οὐκ ἐπὶ σκηνῆς ὀπτήσει ἑαυτόν, οὐκ ἀνάξιος ὤν, μὰ τὸν Ἡρακλέα, εἴ γε χρὴ καὶ τοὺς πατραλοίας καὶ τοὺς ἀθέους δίκας διδόναι τῶν τολμημάτων. καὶ κατὰ τοῦτο πάνυ ὀψὲ δρᾶν αὐτὸ ἔοικεν, ὃν ἐχρῆν πάλαι ἐς τὸν τοῦ Φαλάριδος ταῦρον ἐμπεσόντα τὴν ἀξίαν ἀποτετικέναι, ἀλλὰ μὴ ἅπαξ χανόντα πρὸς τὴν φλόγα ἐν ἀκαρεῖ τεθνάναι. καὶ γὰρ αὖ καὶ τόδε οἱ πολλοί μοι λέγουσιν, ὡς οὐδεὶς ὀξύτερος ἄλλος θανάτου τρόπος τοῦ διὰ πυρός· ἀνοῖξαι γὰρ δεῖ μόνον τὸ στόμα καὶ αὐτίκα τεθνάναι.", "st": "42.21"}, {"sp": "N", "t": "τὸ μέντοι θέαμα ἐπινοεῖται, οἶμαι, ὡς σεμνόν, ἐν ἱερῷ χωρίῳ καιόμενος ἄνθρωπος, ἔνθα μηδὲ θάπτειν ὅσιον τοὺς ἄλλους ἀποθνήσκοντας. ἀκούετε δέ, οἶμαι, ὡς καὶ πάλαι θέλων τις ἔνδοξος γενέσθαι, ἐπεὶ κατ’ ἄλλον τρόπον οὐκ εἶχεν ἐπιτυχεῖν τούτου, ἐνέπρησε τῆς Ἐφεσίας Ἀρτέμιδος τὸν νεών. τοιοῦτόν τι καὶ αὐτὸς ἐπινοεῖ, τοσοῦτος ἔρως τῆς δόξης ἐντέτηκεν αὐτῷ.", "st": "42.22"}, {"sp": "N", "t": "καίτοι φησὶν ὅτι ὑπὲρ τῶν ἀνθρώπων αὐτὸ δρᾷ, ὡς διδάξειεν αὐτοὺς θανάτου καταφρονεῖν καὶ ἐγκαρτερεῖν τοῖς δεινοῖς. ἐγὼ δὲ ἡδέως ἂν ἐροίμην οὐκ ἐκεῖνον ἀλλ’ ὑμᾶς, εἰ καὶ τοὺς κακούργους βούλοισθε ἂν μαθητὰς αὐτοῦ γενέσθαι τῆς καρτερίας ταύτης καὶ καταφρονεῖν θανάτου καὶ καύσεως καὶ τῶν τοιούτων δειμάτων. ἀλλ’ οὐκ ἂν εὖ οἶδ’ ὅτι βουληθείητε. πῶς οὖν ὁ Πρωτεὺς τοῦτο διακρινεῖ καὶ τοὺς μὲν χρηστοὺς ὠφελήσει, τοὺς δὲ πονηροὺς οὐ φιλοκινδυνοτέρους καὶ τολμηροτέρους ἀποφανεῖ;", "st": "42.23"}, {"sp": "N", "t": "καίτοι δυνατὸν ἔστω ἐς τοῦτο μόνους ἀπαντήσεσθαι τοὺς πρὸς τὸ ὠφέλιμον ὀψομένους τὸ πρᾶγμα. ὑμᾶς δ’ οὖν αὖθις ἐρήσομαι, δέξαισθ’ ἂν ὑμῶν τοὺς παῖδας ζηλωτὰς τοῦ τοιούτου γενέσθαι; οὐκ ἂν εἴποιτε. καὶ τί τοῦτο ἠρόμην, ὅπου μηδ’ αὐτῶν τις τῶν μαθητῶν αὐτοῦ ζηλώσειεν ἄν; τὸν γοῦν Θεαγένη τοῦτο μάλιστα αἰτιάσαιτο ἄν τις, ὅτι τἄλλα ζηλῶν τἀνδρὸς οὐχ ἕπεται τῷ διδασκάλῳ καὶ συνοδεύει παρὰ τὸν Ἡρακλέα, ὥς φησιν, ἀπιόντι, δυνάμενος ἐν βραχεῖ πανευδαίμων γενέσθαι συνεμπεσὼν ἐπὶ κεφαλὴν ἐς τὸ πῦρ.", "st": "42.24"}, {"sp": "N", "t": "οὐ γὰρ ἐν πήρᾳ καὶ βάκτρῳ καὶ τρίβωνι ὁ ζῆλος, ἀλλὰ ταῦτα μὲν ἀσφαλῆ καὶ ῥᾴδια καὶ παντὸς ἂν εἴη, τὸ τέλος δὲ καὶ τὸ κεφάλαιον χρὴ ζηλοῦν καὶ πυρὰν συνθέντα κορμῶν συκίνων ὡς ἔνι μάλιστα χλωρῶν ἐναποπνιγῆναι τῷ καπνῷ· τὸ πῦρ γὰρ αὐτὸ οὐ μόνον Ἡρακλέους καὶ Ἀσκληπιοῦ, ἀλλὰ καὶ τῶν ἱεροσύλων καὶ ἀνδροφόνων, οὓς ὁρᾶν ἔστιν ἐκ καταδίκης αὐτὸ πάσχοντας. ὥστε ἄμεινον τὸ διὰ τοῦ καπνοῦ· ἴδιον γὰρ καὶ ὑμῶν ἂν μόνων γένοιτο.", "st": "42.24"}, {"sp": "N", "t": "ἄλλως τε ὁ μὲν Ἡρακλῆς, εἴπερ ἄρα καὶ ἐτόλμησέν τι τοιοῦτο, ὑπὸ νόσου αὐτὸ ἔδρασεν, ὑπὸ τοῦ Κενταυρείου αἵματος, ὥς φησιν ἡ τραγῳδία, κατεσθιόμενος· οὗτος δὲ τίνος αἰτίας ἕνεκεν ἐμβάλλει φέρων ἑαυτὸν εἰς τὸ πῦρ; νὴ Δί’, ὅπως τὴν καρτερίαν ἐπιδείξηται καθάπερ οἱ Βραχμᾶνες· ἐκείνοις γὰρ αὐτὸν ἠξίου Θεαγένης εἰκάζειν, ὥσπερ οὐκ ἐνὸν καὶ ἐν Ἰνδοῖς εἶναί τινας μωροὺς καὶ κενοδόξους ἀνθρώπους. ὅμως δ’ οὖν κἂν ἐκείνους μιμείσθω· ἐκεῖνοι γὰρ οὐκ ἐμπηδῶσιν ἐς τὸ πῦρ, ὡς Ὀνησίκριτος ὁ Ἀλεξάνδρου κυβερνήτης ἰδὼν Κάλανον καόμενόν φησιν, ἀλλ’ ἐπειδὰν νήσωσι, πλησίον παραστάντες ἀκίνητοι ἀνέχονται παροπτώμενοι, εἶτ’ ἐπιβάντες κατὰ σχῆμα καίονται, οὐδ’ ὅσον ὀλίγον ἐντρέψαντες τῆς κατακλίσεως.", "st": "42.25"}, {"sp": "N", "t": "οὗτος δὲ τί μέγα εἰ ἐμπεσὼν τεθνήξεται συναρπασθεὶς ὑπὸ τοῦ πυρός; οὐκ ἀπ’ ἐλπίδος μὴ ἀναπηδήσασθαι αὐτὸν καὶ ἡμίφλεκτον, εἰ μή, ὅπερ φασί, μηχανήσεται βαθεῖαν γενέσθαι καὶ ἐν βόθρῳ τὴν πυράν.", "st": "42.25"}, {"sp": "N", "t": "εἰσὶ δ’ οἳ καὶ μεταβαλέσθαι φασιν αὐτὸν καί τινα ὀνείρατα διηγεῖσθαι, ὡς τοῦ Διὸς οὐκ ἐῶντος μιαίνειν ἱερὸν χωρίον. ἀλλὰ θαρρείτω τούτου γε ἕνεκα· ἐγὼ γὰρ διομοσαίμην ἂν ἦ μὴν μηδένα τῶν θεῶν ἀγανακτήσειν, εἰ Περεγρῖνος κακῶς ἀποθάνοι. οὐ μὴν οὐδὲ ῥᾴδιον αὐτῷ ἔτ’ ἀναδῦναι· οἱ γὰρ συνόντες κύνες παρορμῶσιν καὶ συνωθοῦσιν ἐς τὸ πῦρ καὶ ὑπεκκάουσι τὴν γνώμην, οὐκ ἐῶντες ἀποδειλιᾶν· ὧν εἰ δύο συγκατασπάσας ἐμπέσοι εἰς τὴν πυράν, τοῦτο μόνον χάριεν ἂν ἐργάσαιτο.", "st": "42.26"}, {"sp": "N", "t": "ἤκουον δὲ ὡς οὐδὲ Πρωτεὺς ἔτι καλεῖσθαι ἀξιοῖ, ἀλλὰ Φοίνικα μετωνόμασεν ἑαυτόν, ὅτι καὶ φοῖνιξ, τὸ Ἰνδικὸν ὄρνεον, ἐπιβαίνειν πυρᾶς λέγεται πορρωτάτω γήρως προβεβηκώς. ἀλλὰ καὶ λογοποιεῖ καὶ χρησμούς τινας διέξεισιν παλαιοὺς δή, ὡς χρεὼν εἴη δαίμονα νυκτοφύλακα γενέσθαι αὐτόν, καὶ δῆλός ἐστι βωμῶν ἤδη ἐπιθυμῶν καὶ χρυσοῦς ἀναστήσεσθαι ἐλπίζων.", "st": "42.27"}, {"sp": "N", "t": "καὶ μὰ Δία οὐδὲν ἀπεικὸς ἐν πολλοῖς τοῖς ἀνοήτοις εὑρεθήσεσθαί τινας τοὺς καὶ τεταρταίων ἀπηλλάχθαι δι’ αὐτοῦ φήσοντας καὶ νύκτωρ ἐντετυχηκέναι τῷ δαίμονι τῷ νυκτοφύλακι. οἱ κατάρατοι δὲ οὗτοι μαθηταὶ αὐτοῦ καὶ χρηστήριον, οἶμαι, καὶ ἄδυτον ἐπὶ τῇ πυρᾷ μηχανήσονται, διότι καὶ Πρωτεὺς ἐκεῖνος ὁ Διός, ὁ προπάτωρ τοῦ ὀνόματος, μαντικὸς ἦν. μαρτύρομαι δὲ ἦ μὴν καὶ ἱερέας αὐτοῦ ἀποδειχθήσεσθαι μαστίγων ἢ καυτηρίων ἤ τινος τοιαύτης τερατουργίας, ἢ καὶ νὴ Δία τελετήν τινα ἐπ’ αὐτῷ συστήσεσθαι νυκτέριον καὶ δᾳδουχίαν ἐπὶ τῇ πυρᾷ.", "st": "42.28"}, {"sp": "N", "t": "Θεαγένης δὲ ἔναγχος, ὥς μοί τις τῶν ἑταίρων ἀπήγγειλεν, καὶ Σίβυλλαν ἔφη προειρηκέναι περὶ τούτων· καὶ τὰ ἔπη γὰρ ἀπεμνημόνευεν·<br>ἀλλ’ ὁπόταν Πρωτεὺς Κυνικῶν ὄχ’ ἄριστος ἁπάντων<br>Ζηνὸς ἐριγδούπου τέμενος κάτα πῦρ ἀνακαύσας<br>ἐς φλόγα πηδήσας ἔλθῃ ἐς μακρὸν Ὄλυμπον,<br>δὴ τότε πάντας ὁμῶς, οἳ ἀρούρης καρπὸν ἔδουσιν,<br>νυκτιπόλον τιμᾶν κέλομαι ἥρωα μέγιστον<br>σύνθρονον Ἡφαίστῳ καὶ Ἡρακλῆϊ ἄνακτι.", "st": "42.29"}, {"sp": "N", "t": "ταῦτα μὲν Θεαγένης Σιβύλλης ἀκηκοέναι φησίν. ἐγὼ δὲ Βάκιδος αὐτῷ χρησμὸν ὑπὲρ τούτων ἐρῶ· φησὶν δὲ ὁ Βάκις οὕτω, σφόδρα εὖ ἐπειπών,<br>Ἀλλ’ ὁπόταν Κυνικὸς πολυώνυμος ἐς φλόγα πολλὴν<br>πηδήσῃ δόξης ὑπ’ ἐρινύι θυμὸν ὀρινθείς,<br>δὴ τότε τοὺς ἄλλους κυναλώπεκας, οἵ οἱ ἕπονται,<br>μιμεῖσθαι χρὴ πότμον ἀποιχομένοιο λύκοιο.<br>ὃς δέ κε δειλὸς ἐὼν φεύγῃ μένος Ἡφαίστοιο,<br>λάεσσιν βαλέειν τοῦτον τάχα πάντας Ἀχαιούς,<br>ὡς μὴ ψυχρὸς ἐὼν θερμηγορέειν ἐπιχειρῇ<br>χρυσῷ σαξάμενος πήρην μάλα πολλὰ δανείζων,<br>ἐν καλαῖς Πάτραισιν ἔχων τρὶς πέντε τάλαντα.<br>τί ὑμῖν δοκεῖ, ἄνδρες; ἆρα φαυλότερος χρησμολόγος ὁ Βάκις τῆς Σιβύλλης εἶναι; ὥστε ὥρα τοῖς θαυμαστοῖς τούτοις ὁμιληταῖς τοῦ Πρωτέως περισκοπεῖν ἔνθα ἑαυτοὺς ἐξαερώσουσιν· τοῦτο γὰρ τὴν καῦσιν καλοῦσιν.", "st": "42.30"}, {"sp": "N", "t": "ταῦτ’ εἰπόντος ἀνεβόησαν οἱ περιεστῶτες ἅπαντες, “ἤδη καιέσθωσαν ἄξιοι τοῦ πυρός.” καὶ ὁ μὲν κατέβη γελῶν, “Νέστορα δ’ οὐκ ἔλαθεν ἰαχή,” τὸν Θεαγένη, ἀλλ’ ὡς ἤκουσεν τῆς βοῆς, ἧκεν εὐθὺς καὶ ἀναβὰς ἐκεκράγει καὶ μυρία κακὰ διεξῄει περὶ τοῦ καταβεβηκότος· οὐ γὰρ οἶδα ὅστις ἐκεῖνος ὁ βέλτιστος ἐκαλεῖτο. ἐγὼ δὲ ἀφεὶς αὐτὸν διαρρηγνύμενον ἀπῄειν ὀψόμενος τοὺς ἀθλητάς· ἤδη γὰρ οἱ Ἑλλανοδίκαι ἐλέγοντο εἶναι ἐν τῷ Πλεθρίῳ.", "st": "42.31"}, {"sp": "N", "t": "ταῦτα μέν σοι τὰ ἐν Ἤλιδι. ἐπεὶ δὲ ἐς τὴν Ὀλυμπίαν ἀφικόμεθα, μεστὸς ἦν ὁ ὀπισθόδομος τῶν κατηγορούντων Πρωτέως ἢ ἐπαινούντων τὴν προαίρεσιν αὐτοῦ, ὥστε καὶ εἰς χεῖρας αὐτῶν ἦλθον οἱ πολλοί, ἄχρι δὴ παρελθὼν αὐτὸς ὁ Πρωτεὺς μυρίῳ τῷ πλήθει παραπεμπόμενος κατόπιν τοῦ τῶν κηρύκων ἀγῶνος λόγους τινὰς διεξῆλθεν περὶ ἑαυτοῦ, τὸν βίον τε ὡς ἐβίω καὶ τοὺς κινδύνους οὓς ἐκινδύνευσεν διηγούμενος καὶ ὅσα πράγματα φιλοσοφίας ἕνεκα ὑπέμεινεν. τὰ μὲν οὖν εἰρημένα πολλὰ ἦν, ἐγὼ δὲ ὀλίγων ἤκουσα ὑπὸ πλήθους τῶν περιεστώτων. εἶτα φοβηθεὶς μὴ συντριβείην ἐν τοσαύτῃ τύρβῃ, ἐπεὶ καὶ πολλοὺς τοῦτο πάσχοντας ἑώρων, ἀπῆλθον μακρὰ χαίρειν φράσας θανατιῶντι σοφιστῇ τὸν ἐπιτάφιον ἑαυτοῦ πρὸ τελευτῆς διεξιόντι.", "st": "42.32"}, {"sp": "N", "t": "πλὴν τό γε τοσοῦτον ἐπήκουσα· ἔφη γὰρ βούλεσθαι χρυσῷ βίῳ χρυσῆν κορώνην ἐπιθεῖναι· χρῆναι γὰρ τὸν Ἡρακλείως βεβιωκότα Ἡρακλείως ἀποθανεῖν καὶ ἀναμιχθῆναι τῷ αἰθέρι. “καὶ ὠφελῆσαι,” ἔφη, “βούλομαι τοὺς ἀνθρώπους δείξας αὐτοῖς ὃν χρὴ τρόπον θανάτου καταφρονεῖν· πάντας οὖν δεῖ μοι τοὺς ἀνθρώπους Φιλοκτήτας γενέσθαι.” οἱ μὲν οὖν ἀνοητότεροι τῶν ἀνθρώπων ἐδάκρυον καὶ ἐβόων “σώζου τοῖς Ἕλλησιν,” οἱ δὲ ἀνδρωδέστεροι ἐκεκράγεσαν “τέλει τὰ δεδογμένα,” ὑφ’ ὧν ὁ πρεσβύτης οὐ μετρίως ἐθορυβήθη ἐλπίζων πάντας ἕξεσθαι αὐτοῦ καὶ μὴ προήσεσθαι τῷ πυρί, ἀλλὰ ἄκοντα δὴ καθέξειν ἐν τῷ βίῳ. τὸ δὲ “τέλει τὰ δεδογμένα” πάνυ ἀδόκητον αὐτῷ προσπεσὸν ὠχριᾶν ἔτι μᾶλλον ἐποίησεν, καίτοι ἤδη νεκρικῶς τὴν χροιὰν ἔχοντι, καὶ νὴ Δία καὶ ὑποτρέμειν, ὥστε κατέπαυσε τὸν λόγον.", "st": "42.33"}, {"sp": "N", "t": "ἐγὼ δέ, εἰκάζεις, οἶμαι, πῶς ἐγέλων· οὐδὲ γὰρ ἐλεεῖν ἄξιον ἦν οὕτω δυσέρωτα τῆς δόξης ἄνθρωπον ὑπὲρ ἅπαντας ὅσοι τῇ αὐτῇ Ποινῇ ἐλαύνονται. παρεπέμπετο δὲ ὅμως ὑπὸ πολλῶν καὶ ἐνεφορεῖτο τῆς δόξης ἀποβλέπων ἐς τὸ πλῆθος τῶν θαυμαζόντων, οὐκ εἰδὼς ὁ ἄθλιος ὅτι καὶ τοῖς ἐπὶ τὸν σταυρὸν ἀπαγομένοις ἢ ὑπὸ τοῦ δημίου ἐχομένοις πολλῷ πλείους ἕπονται.", "st": "42.34"}, {"sp": "N", "t": "καὶ δὴ τὰ μὲν Ὀλύμπια τέλος εἶχεν, κάλλιστα Ὀλυμπίων γενόμενα ὧν ἐγὼ εἶδον, τετράκις ἤδη ὁρῶν. ἐγὼ δέ — οὐ γὰρ ἦν εὐπορῆσαι ὀχήματος ἅμα πολλῶν ἐξιόντων — ἄκων ὑπελειπόμην. ὁ δὲ ἀεὶ ἀναβαλλόμενος νύκτα τὸ τελευταῖον προειρήκει ἐπιδείξασθαι τὴν καῦσιν· καί με τῶν ἑταίρων τινὸς παραλαβόντος περὶ μέσας νύκτας ἐξαναστὰς ἀπῄειν εὐθὺ τῆς Ἁρπίνης, ἔνθα ἦν ἡ πυρά. στάδιοι πάντες οὗτοι εἴκοσιν ἀπὸ τῆς Ὀλυμπίας κατὰ τὸν ἱππόδρομον ἀπιόντων πρὸς ἕω. καὶ ἐπεὶ τάχιστα ἀφικόμεθα, καταλαμβάνομεν πυρὰν νενησμένην ἐν βόθρῳ ὅσον ἐς ὀργυιὰν τὸ βάθος. δᾷδες ἦσαν τὰ πολλὰ καὶ παρεβέβυστο τῶν φρυγάνων, ὡς ἀναφθείη τάχιστα.", "st": "42.35"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἡ σελήνη ἀνέτελλεν — ἔδει γὰρ κἀκείνην θεάσασθαι τὸ κάλλιστον τοῦτο ἔργον — πρόεισιν ἐκεῖνος ἐσκευασμένος ἐς τὸν ἀεὶ τρόπον καὶ ξὺν αὐτῷ τὰ τέλη τῶν κυνῶν, καὶ μάλιστα ὁ γεννάδας ὁ ἐκ Πατρῶν, δᾷδα ἔχων, οὐ φαῦλος δευτεραγωνιστής· ἐδᾳδοφόρει δὲ καὶ ὁ Πρωτεύς. καὶ προσελθόντες ἄλλος ἀλλαχόθεν ἀνῆψαν τὸ πῦρ μέγιστον ἅτε ἀπὸ δᾴδων καὶ φρυγάνων. ὁ δέ — καί μοι πάνυ ἤδη πρόσεχε τὸν νοῦν — ἀποθέμενος τὴν πήραν καὶ τὸ τριβώνιον καὶ τὸ Ἡράκλειον ἐκεῖνο ῥόπαλον, ἔστη ἐν ὀθόνῃ ῥυπώσῃ ἀκριβῶς. εἶτα ᾔτει λιβανωτόν, ὡς ἐπιβάλοι ἐπὶ τὸ πῦρ, καὶ ἀναδόντος τινὸς ἐπέβαλέν τε καὶ εἶπεν ἐς τὴν μεσημβρίαν ἀποβλέπων — καὶ γὰρ καὶ τοῦτ’ αὐτὸ πρὸς τὴν τραγῳδίαν ἦν, ἡ μεσημβρία — “δαίμονες μητρῷοι καὶ πατρῷοι, δέξασθέ με εὐμενεῖς.” ταῦτα εἰπὼν ἐπήδησεν ἐς τὸ πῦρ, οὐ μὴν ἑωρᾶτό γε, ἀλλὰ περιεσχέθη ὑπὸ τῆς φλογὸς πολλῆς ἠρμένης.", "st": "42.36"}, {"sp": "N", "t": "αὖθις ὁρῶ γελῶντά σε, ὦ καλὲ Κρόνιε, τὴν καταστροφὴν τοῦ δράματος. ἐγὼ δὲ τοὺς μητρῴους μὲν δαίμονας ἐπιβοώμενον μὰ τὸν Δί’ οὐ σφόδρα ᾐτιώμην· ὅτε δὲ καὶ τοὺς πατρῴους ἐπεκαλέσατο, ἀναμνησθεὶς τῶν περὶ τοῦ φόνου εἰρημένων οὐδὲ κατέχειν ἠδυνάμην τὸν γέλωτα. οἱ Κυνικοὶ δὲ περιστάντες τὴν πυρὰν οὐκ ἐδάκρυον μέν, σιωπῇ δὲ ἐνεδείκνυντο λύπην τινὰ εἰς τὸ πῦρ ὁρῶντες, ἄχρι δὴ ἀποπνιγεὶς ἐπ’ αὐτοῖς, “ἀπίωμεν,” φημί, “ὦ μάταιοι· οὐ γὰρ ἡδὺ τὸ θέαμα ὠπτημένον γέροντα ὁρᾶν κνίσης ἀναπιμπλαμένους πονηρᾶς. ἢ περιμένετε ἔστ’ ἂν γραφεύς τις ἐπελθὼν ἀπεικάσῃ ὑμᾶς οἵους τοὺς ἐν τῷ δεσμωτηρίῳ ἑταίρους τῷ Σωκράτει παραγράφουσιν;” ἐκεῖνοι μὲν οὖν ἠγανάκτουν καὶ ἐλοιδοροῦντό μοι, ἔνιοι δὲ καὶ ἐπὶ τὰς βακτηρίας ᾖξαν. εἶτα, ἐπειδὴ ἠπείλησα ξυναρπάσας τινὰς ἐμβαλεῖν εἰς τὸ πῦρ, ὡς ἂν ἕποιντο τῷ διδασκάλῳ, ἐπαύσαντο καὶ εἰρήνην ἦγον.", "st": "42.37"}, {"sp": "N", "t": "ἐγὼ δὲ ἐπανιὼν ποικίλα, ὦ ἑταῖρε, πρὸς ἐμαυτὸν ἐνενόουν, τὸ φιλόδοξον οἷόν τί ἐστιν ἀναλογιζόμενος, ὡς μόνος οὗτος ὁ ἔρως ἄφυκτος καὶ τοῖς πάνυ θαυμαστοῖς εἶναι δοκοῦσιν, οὐχ ὅπως ἐκείνῳ τἀνδρὶ καὶ τἄλλα ἐμπλήκτως καὶ ἀπονενοημένως βεβιωκότι καὶ οὐκ ἀναξίως τοῦ πυρός.", "st": "42.38"}, {"sp": "N", "t": "εἶτα ἐνετύγχανον πολλοῖς ἀπιοῦσιν ὡς θεάσαιντο καὶ αὐτοί· ᾤοντο γὰρ ἔτι καταλήψεσθαι ζῶντα αὐτόν. καὶ γὰρ καὶ τόδε τῇ προτεραίᾳ διεδέδοτο ὡς πρὸς ἀνίσχοντα τὸν ἥλιον ἀσπασάμενος, ὥσπερ ἀμέλει καὶ τοὺς Βραχμᾶνάς φασι ποιεῖν, ἐπιβήσεται τῆς πυρᾶς. ἀπέστρεφον δ’ οὖν τοὺς πολλοὺς αὐτῶν λέγων ἤδη τετελέσθαι τὸ ἔργον, οἷς μὴ καὶ τοῦτ’ αὐτὸ περισπούδαστον ἦν, κἂν αὐτὸν ἰδεῖν τὸν τόπον καί τι λείψανον καταλαμβάνειν τοῦ πυρός.", "st": "42.39"}, {"sp": "N", "t": "ἔνθα δή, ὦ ἑταῖρε, μυρία πράγματα εἶχον ἅπασι διηγούμενος καὶ ἀνακρίνουσιν καὶ ἀκριβῶς ἐκπυνθανομένοις. εἰ μὲν οὖν ἴδοιμί τινα χαρίεντα, ψιλὰ ἂν ὥσπερ σοὶ τὰ πραχθέντα διηγούμην, πρὸς δὲ τοὺς βλᾶκας καὶ πρὸς τὴν ἀκρόασιν κεχηνότας ἐτραγῴδουν τι παρ’ ἐμαυτοῦ, ὡς ἐπειδὴ ἀνήφθη μὲν ἡ πυρά, ἐνέβαλεν δὲ φέρων ἑαυτὸν ὁ Πρωτεύς, σεισμοῦ πρότερον μεγάλου γενομένου σὺν μυκηθμῷ τῆς γῆς, γὺψ ἀναπτάμενος ἐκ μέσης τῆς φλογὸς οἴχοιτο ἐς τὸν οὐρανὸν ἀνθρωπιστὶ μεγάλῃ τῇ φωνῇ λέγων<br>“ἔλιπον γᾶν, βαίνω δ’ ἐς Ὄλυμπον.”<br>ἐκεῖνοι μὲν οὖν ἐτεθήπεσαν καὶ προσεκύνουν ὑποφρίττοντες καὶ ἀνέκρινόν με πότερον πρὸς ἕω ἢ πρὸς δυσμὰς ἐνεχθείη ὁ γύψ· ἐγὼ δὲ τὸ ἐπελθὸν ἀπεκρινάμην αὐτοῖς.", "st": "42.39"}, {"sp": "N", "t": "ἀπελθὼν δὲ ἐς τὴν πανήγυριν ἐπέστην τινὶ πολιῷ ἀνδρὶ καὶ νὴ τὸν Δί’ ἀξιοπίστῳ τὸ πρόσωπον ἐπὶ τῷ πώγωνι καὶ τῇ λοιπῇ σεμνότητι, τά τε ἄλλα διηγουμένῳ περὶ τοῦ Πρωτέως καὶ ὡς μετὰ τὸ καυθῆναι θεάσαιτο αὐτὸν ἐν λευκῇ ἐσθῆτι μικρὸν ἔμπροσθεν, καὶ νῦν ἀπολίποι περιπατοῦντα φαιδρὸν ἐν τῇ ἑπταφώνῳ στοᾷ κοτίνῳ τε ἐστεμμένον. εἶτ’ ἐπὶ πᾶσι προσέθηκε τὸν γῦπα, διομνύμενος ἦ μὴν αὐτὸς ἑωρακέναι ἀναπτάμενον ἐκ τῆς πυρᾶς, ὃν ἐγὼ μικρὸν ἔμπροσθεν ἀφῆκα πέτεσθαι καταγελῶντα τῶν ἀνοήτων καὶ βλακικῶν τὸν τρόπον.", "st": "42.40"}, {"sp": "N", "t": "ἐννόει τὸ λοιπὸν οἷα εἰκὸς ἐπ’ αὐτῷ γενήσεσθαι, ποίας μὲν οὐ μελίττας ἐπιστήσεσθαι ἐπὶ τὸν τόπον, τίνας δὲ τέττιγας οὐκ ἐπᾴσεσθαι, τίνας δὲ κορώνας οὐκ ἐπιπτήσεσθαι καθάπερ ἐπὶ τὸν Ἡσιόδου τάφον, καὶ τὰ τοιαῦτα. εἰκόνας μὲν γὰρ παρά τε Ἠλείων αὐτῶν παρά τε τῶν ἄλλων Ἑλλήνων, οἷς καὶ ἐπεσταλκέναι ἔλεγεν, αὐτίκα μάλα οἶδα πολλὰς ἀναστησομένας. φασὶ δὲ πάσαις σχεδὸν ταῖς ἐνδόξοις πόλεσιν ἐπιστολὰς διαπέμψαι αὐτόν, διαθήκας τινὰς καὶ παραινέσεις καὶ νόμους· καί τινας ἐπὶ τούτῳ πρεσβευτὰς τῶν ἑταίρων ἐχειροτόνησεν, νεκραγγέλους καὶ νερτεροδρόμους προσαγορεύσας.", "st": "42.41"}, {"sp": "N", "t": "τοῦτο τέλος τοῦ κακοδαίμονος Πρωτέως ἐγένετο, ἀνδρός, ὡς βραχεῖ λόγῳ περιλαβεῖν, πρὸς ἀλήθειαν μὲν οὐδεπώποτε ἀποβλέψαντος, ἐπὶ δόξῃ δὲ καὶ τῷ παρὰ τῶν πολλῶν ἐπαίνῳ ἅπαντα εἰπόντος ἀεὶ καὶ πράξαντος, ὡς καὶ εἰς πῦρ ἁλέσθαι, ὅτε μηδὲ ἀπολαύειν τῶν ἐπαίνων ἔμελλεν ἀναίσθητος αὐτῶν γενόμενος.", "st": "42.42"}, {"sp": "N", "t": "ἓν ἔτι σοι προσδιηγησάμενος παύσομαι, ὡς ἔχῃς ἐπὶ πολὺ γελᾶν. ἐκεῖνα μὲν γὰρ πάλαι οἶσθα, εὐθὺς ἀκούσας μου ὅτε ἥκων ἀπὸ Συρίας διηγούμην ὡς ἀπὸ Τρῳάδος συμπλεύσαιμι αὐτῷ καὶ τήν τε ἄλλην τὴν ἐν τῷ πλῷ τρυφὴν καὶ τὸ μειράκιον τὸ ὡραῖον ὃ ἔπεισε κυνίζειν ὡς ἔχοι τινὰ καὶ αὐτὸς Ἀλκιβιάδην, καὶ ὡς ἐπεὶ ταραχθείημεν τῆς νυκτὸς ἐν μέσῳ τῷ Αἰγαίῳ γνόφου καταβάντος καὶ κῦμα παμμέγεθες ἐγείραντος ἐκώκυε μετὰ τῶν γυναικῶν ὁ θαυμαστὸς καὶ θανάτου κρείττων εἶναι δοκῶν.", "st": "42.43"}, {"sp": "N", "t": "ἀλλὰ μικρὸν πρὸ τῆς τελευτῆς, πρὸ ἐννέα σχεδόν που ἡμερῶν, πλεῖον, οἶμαι, τοῦ ἱκανοῦ ἐμφαγὼν ἤμεσέν τε τῆς νυκτὸς καὶ ἑάλω πυρετῷ μάλα σφοδρῷ. ταῦτα δέ μοι Ἀλέξανδρος ὁ ἰατρὸς διηγήσατο μετακληθεὶς ὡς ἐπισκοπήσειεν αὐτόν. ἔφη οὖν καταλαβεῖν αὐτὸν χαμαὶ κυλιόμενον καὶ τὸν φλογμὸν οὐ φέροντα καὶ ψυχρὸν αἰτοῦντα πάνυ ἐρωτικῶς, ἑαυτὸν δὲ μὴ δοῦναι. καίτοι εἰπεῖν ἔφη πρὸς αὐτὸν ὡς εἰ πάντως θανάτου δέοιτο, ἥκειν αὐτὸν ἐπὶ τὰς θύρας αὐτόματον, ὥστε καλῶς ἔχειν ἕπεσθαι μηδὲν τοῦ πυρὸς δεόμενον· τὸν δ’ αὖ φάναι, “ἀλλ’ οὐχ ὁμοίως ἔνδοξος ὁ τρόπος γένοιτ’ ἂν, πᾶσιν κοινὸς ὤν.”", "st": "42.44"}, {"sp": "N", "t": "ταῦτα μὲν ὁ Ἀλέξανδρος. ἐγὼ δὲ οὐδ’ αὐτὸς πρὸ πολλῶν ἡμερῶν εἶδον αὐτὸν ἐγκεχρισμένον, ὡς ἀποδακρύσειε τῷ δριμεῖ φαρμάκῳ. ὁρᾷς; οὐ πάνυ τοὺς ἀμβλυωποῦντας ὁ Αἰακὸς παραδέχεται. ὅμοιον ὡς εἴ τις ἐπὶ σταυρὸν ἀναβήσεσθαι μέλλων τὸ ἐν τῷ δακτύλῳ πρόσπταισμα θεραπεύοι. τί σοι δοκεῖ ὁ Δημόκριτος, εἰ ταῦτα εἶδε; κατ’ ἀξίαν γελάσαι ἂν ἐπὶ τῷ ἀνδρί; καίτοι πόθεν εἶχεν ἐκεῖνος τοσοῦτον γέλωτα; σὺ δ’ οὖν, ὦ φιλότης, γέλα καὶ αὐτός, καὶ μάλιστα ὁπόταν τῶν ἄλλων ἀκούῃς θαυμαζόντων αὐτόν.", "st": "42.45"}, {"sp": "HDR", "t": "Δραπέται"}, {"sp": "N", "t": "<em>Ἀπόλλων.<\/em> ἀληθῆ ταῦτά φασιν, πάτερ, ὡς ἐμβάλοι τις φέρων αὑτὸν εἰς τὸ πῦρ κατέναντι Ὀλυμπίων, ἤδη πρεσβύτης ἄνθρωπος, οὐκ ἀγεννὴς θαυματοποιὸς τὰ τοιαῦτα; ἡ Σελήνη γὰρ ἡμῖν διηγεῖτο, αὐτὴ ἑωρακέναι καιόμενον λέγουσα.", "st": "43.1"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> καὶ πάνυ ἀληθῆ, ὦ Ἄπολλον· ὡς μή ποτε γενέσθαι ὤφελεν.", "st": "43.1"}, {"sp": "N", "t": "<em>Ἀπόλλων.<\/em> οὕτω χρηστὸς ὁ γέρων ἦν καὶ ἀνάξιος ἐν πυρὶ ἀπολωλέναι;", "st": "43.1"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> καὶ τοῦτο μὲν ἴσως· ἀλλ’ ἐγὼ πολλὴν τὴν ἀηδίαν μέμνημαι ἀνασχόμενος τότε ὑπὸ κνίσης πονηρᾶς, οἵαν εἰκὸς ἀποφέρεσθαι ὀπτωμένων ἀνθρωπείων σωμάτων. εἰ γοῦν μὴ εἰς τὴν Ἀραβίαν ὡς εἶχον εὐθὺς ἀπιὼν ᾠχόμην, ἀπολώλειν ἄν, εὖ ἴσθι, ἀτοπίᾳ τοῦ καπνοῦ· καὶ ὅμως ἐν τοσαύτῃ εὐωδίᾳ καὶ ἀφθονίᾳ τῶν ἀρωμάτων καὶ ἐν λιβανωτῷ παμπόλλῳ μόλις αἱ ῥῖνες ἐπιλαθέσθαι μοι καὶ ἀπομαθεῖν ἤθελον τὴν κηλῖδα ἐκείνην τῆς ὀσμῆς, ἀλλὰ καὶ νῦν ὀλίγου δέω ναυτιᾶν ὑπομνησθεὶς αὐτῆς.", "st": "43.1"}, {"sp": "N", "t": "<em>Ἀπόλλων.<\/em> τί δὲ βουλόμενος, ὦ Ζεῦ, τοιαῦτα εἴργασται ἑαυτόν; ἢ τί τὸ ἀγαθόν, ἀπανθρακωθῆναι ἐμπεσόντα εἰς τὴν πυράν;", "st": "43.2"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> τοῦτο μὲν οὐκ ἄν, ὦ παῖ, φθάνοις καὶ Ἐμπεδοκλεῖ πρὸ αὐτοῦ ἐγκαλῶν, ὃς ἐς τοὺς κρατῆρας ἥλατο καὶ αὐτὸς ἐν Σικελίᾳ.", "st": "43.2"}, {"sp": "N", "t": "<em>Ἀπόλλων.<\/em> μελαγχολίαν τινὰ δεινὴν λέγεις. ἀτὰρ οὗτός γε τίνα ποτὲ ἄρα τὴν αἰτίαν ἔσχε τῆς ἐπιθυμίας;", "st": "43.2"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> αὐτοῦ σοι λόγον ἐρῶ ὃν ἔλεξε πρὸς τὴν πανήγυριν, ἀπολογούμενος πρὸς αὐτοὺς ὑπὲρ τῆς τελευτῆς.", "st": "43.2"}, {"sp": "N", "t": "ἔφη γάρ, εἴ γε μέμνημαι — ἀλλὰ τίς αὕτη σπουδῇ πρόσεισι τεταραγμένη καὶ δακρύουσα, πάνυ ἀδικουμένῃ ἐοικυῖα; μᾶλλον δὲ Φιλοσοφία ἐστίν, καὶ τοὔνομά γε τοὐμὸν ἐπιβοᾶται σχετλιάζουσα. τί, ὦ θύγατερ, δακρύεις; ἢ τί ἀπολιποῦσα τὸν βίον ἐλήλυθας; ἆρα μὴ οἱ ἰδιῶται αὖθις ἐπιβεβουλεύκασί σοι ὡς τὸ πρόσθεν, ὅτε τὸν Σωκράτην ἀπέκτειναν ὑπὸ Ἀνύτου κατηγορηθέντα, εἶτα φεύγεις διὰ τοῦτο αὐτούς;", "st": "43.3"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> οὐδὲν τοιοῦτον, ὦ πάτερ, ἀλλ’ ἐκεῖνοι μέν, ὁ πολὺς λεώς, ἐπῄνουν καὶ διὰ τιμῆς ἦγον, αἰδούμενοι καὶ θαυμάζοντές με καὶ μονονουχὶ προσκυνοῦντες, εἰ καὶ μὴ σφόδρα ξυνίεσαν ὧν λέγοιμι. οἱ δέ — πῶς ἂν εἴποιμι; — οἱ ξυνήθεις καὶ φίλοι φάσκοντες εἶναι καὶ τοὔνομα τοὐμὸν ὑποδυόμενοι, ἐκεῖνοί με τὰ δεινότατα εἰργάσαντο.", "st": "43.3"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> οἱ φιλόσοφοι ἐπιβουλήν τινα ἐπιβεβουλεύκασί σοι;", "st": "43.4"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> οὐδαμῶς, ὦ πάτερ, οἵ γε ξυνηδίκηνταί μοι καὶ αὐτοί.", "st": "43.4"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> πρὸς τίνων οὖν ἠδίκησαι, εἰ μήτε τοὺς ἰδιώτας μήτε τοὺς φιλοσόφους αἰτιᾷ;", "st": "43.4"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> εἰσίν τινες, ὦ Ζεῦ, ἐν μεταιχμίῳ τῶν τε πολλῶν καὶ τῶν φιλοσοφούντων, τὸ μὲν σχῆμα καὶ βλέμμα καὶ βάδισμα ἡμῖν ὅμοιοι καὶ κατὰ τὰ αὐτὰ ἐσταλμένοι· ἀξιοῦσι γοῦν ὑπ’ ἐμοὶ τάττεσθαι καὶ τοὔνομα τὸ ἡμέτερον ἐπιγράφονται, μαθηταὶ καὶ ὁμιληταὶ καὶ θιασῶται ἡμῶν εἶναι λέγοντες· ὁ βίος δὲ παμμίαρος αὐτῶν, ἀμαθίας καὶ θράσους καὶ ἀσελγείας ἀνάπλεως, ὕβρις οὐ μικρὰ καθ’ ἡμῶν. ὑπὸ τούτων, ὦ πάτερ, ἠδικημένη πέφευγα.", "st": "43.4"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> δεινὰ ταῦτα, ὦ θύγατερ. ἀλλὰ τί μάλιστα ἠδικήκασί σε;", "st": "43.5"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> σκόπει, ὦ πάτερ, εἰ μικρά. σὺ γὰρ κατιδὼν τὸν βίον ἀδικίας καὶ παρανομίας μεστὸν ἅτε ἀμαθίᾳ καὶ ὕβρει ξυνόντα καὶ ταραττόμενον ὑπ’ αὐτῶν, κατελεήσας τὸ ἀνθρώπειον ὑπὸ τῇ ἀγνοίᾳ ἐλαυνόμενον ἐμὲ κατέπεμψας, ἐντειλάμενος ἐπιμεληθῆναι ὡς παύσαιντο μὲν ἀδικοῦντες ἀλλήλους καὶ βιαζόμενοι καὶ ὅμοια τοῖς θηρίοις βιοῦντες, ἀναβλέψαντες δὲ πρὸς τὴν ἀλήθειαν εἰρηνικώτερον ξυμπολιτεύοιντο. ἔφης γοῦν πρός με καταπέμπων, “ἅ μὲν πράττουσιν οἱ ἄνθρωποι καὶ ὡς διάκεινται ὑπὸ τῆς ἀμαθίας, ὦ θύγατερ, καὶ αὐτὴ ὁρᾷς· ἐγὼ δέ (ἐλεῶ γὰρ αὐτούς) σέ, ἣν μόνην ἰάσασθαι ἂν τὰ γιγνόμενα οἶμαι, προκρίνας ἐξ ἁπάντων ἡμῶν πέμπω ἰασομένην.”", "st": "43.5"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> οἶδα πολλὰ καὶ ταῦτα εἰπὼν τότε. σὺ δὲ τὰ μετὰ ταῦτα ἤδη λέγε, ὅπως μὲν ὑπεδέξαντό σε καταπταμένην τὸ πρῶτον, ἅτινα δὲ νῦν ὑπ’ αὐτῶν πέπονθας.", "st": "43.6"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἦιξα μέν, ὦ πάτερ, οὐκ ἐπὶ τοὺς Ἕλληνας εὐθύς, ἀλλ’ ὅπερ ἐδόκει μοι χαλεπώτερον τοῦ ἔργου εἶναι, τὸ βαρβάρους παιδεύειν καὶ διδάσκειν, τοῦτο πρῶτον ἠξίουν ἐργάσασθαι· τὸ Ἑλληνικὸν δὲ εἴων ὡς ῥᾷστα ὑποβαλέσθαι οἷόν τε καὶ τάχιστα, ὥς γε ᾤμην, ἐνδεξόμενον τὸν χαλινὸν καὶ ὑπαχθησόμενον τῷ ζυγῷ. ὁρμήσασα δὲ εἰς Ἰνδοὺς τὸ πρῶτον, ἔθνος μέγιστον τῶν ἐν τῷ βίῳ, οὐ χαλεπῶς ἔπεισα καταβάντας ἀπὸ τῶν ἐλεφάντων ἐμοὶ συνεῖναι, ὥστε καὶ γένος ὅλον, οἱ Βραχμᾶνες, τοῖς Νεχραίοις καὶ Ὀξυδράκαις ὅμορον, οὗτοι πάντες ὑπ’ ἐμοὶ τάττονται καὶ βιοῦσίν τε κατὰ τὰ ἡμῖν δοκοῦντα, τιμώμενοι πρὸς τῶν περιοίκων ἁπάντων, καὶ ἀποθνήσκουσι παράδοξόν τινα τοῦ θανάτου τρόπον.", "st": "43.6"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> τοὺς γυμνοσοφιστὰς λέγεις. ἀκούω γοῦν τά τε ἄλλα περὶ αὐτῶν καὶ ὅτι ἐπὶ πυρὰν μεγίστην ἀναβάντες ἀνέχονται καιόμενοι, οὐδὲν τοῦ σχήματος ἢ τῆς καθέδρας ἐντρέποντες. ἀλλ’ οὐ μέγα τοῦτο· ἔναγχος γοῦν καὶ Ὀλυμπίασιν τὸ ὅμοιον ἐγὼ εἶδον γενόμενον, εἰκὸς δὲ καὶ σὲ παρεῖναι καιομένου τότε τοῦ γέροντος.", "st": "43.7"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> οὐδὲ ἀνῆλθον, ὦ πάτερ, εἰς Ὀλυμπίαν δέει τῶν καταράτων ἐκείνων οὓς ἔφην, ὅτι πολλοὺς αὐτῶν ἑώρων ἀπιόντας, ὡς λοιδορήσαιντο τοῖς ξυνεληλυθόσι καὶ βοῆς τὸν ὀπισθόδομον ἐμπλήσωσιν ὑλακτοῦντες, ὥστε οὐδὲ εἶδον ἐκεῖνον ὅπως ἀπέθανεν.", "st": "43.7"}, {"sp": "N", "t": "μετὰ δ’ οὖν τοὺς Βραχμᾶνας εἰς Αἰθιοπίαν εὐθύς, εἶτα εἰς Αἴγυπτον κατέβην, καὶ ξυγγενομένη τοῖς ἱερεῦσιν καὶ προφήταις αὐτῶν καὶ τὰ θεῖα παιδεύσασα ἐς Βαβυλῶνα ἀπῆρα Χαλδαίους καὶ μάγους μυήσουσα, εἶτα εἰς Σκυθίαν ἐκεῖθεν, εἶτα εἰς Θρᾴκην, ἔνθα μοι Εὔμολπός τε καὶ Ὀρφεὺς συνεγενέσθην, οὓς καὶ προαποστείλασα ἐς τὴν Ἑλλάδα, τὸν μὲν ὡς τελέσειεν αὐτούς, τὸν Εὔμολπον — ἐμεμαθήκει γὰρ τὰ θεῖα παρ’ ἡμῶν ἅπαντα — τὸν δὲ ὡς ἐπᾴδων προσβιβάζοι τῇ μουσικῇ, κατὰ πόδας εὐθὺς εἱπόμην.", "st": "43.8"}, {"sp": "N", "t": "καὶ τὸ μὲν πρῶτον εὐθὺς ἐλθοῦσαν οὔτε πάνυ ἠσπάσαντο οἱ Ἕλληνες οὔτε ὅλως ἀπέκλεισαν· κατ’ ὀλίγον δὲ προσομιλοῦσα ἑπτὰ ἐκ τῶν ἁπάντων ἑταίρους καὶ μαθητὰς προσηγαγόμην, καὶ ἄλλον ἐξ Σάμου καὶ ἄλλον ἐξ Ἐφέσου καὶ Ἀβδηρόθεν ἄλλον, ὀλίγους παντάπασιν.", "st": "43.9"}, {"sp": "N", "t": "μεθ’ οὓς τὸ σοφιστῶν φῦλον οὐκ οἶδ’ ὅπως μοι παρενεφύετο, οὔτε ζηλοῦν τἀμὰ ἐς βάθος οὔτε κομιδῇ ἀπᾷδον, ἀλλ’ οἷον τὸ Ἱπποκενταύρων γένος, σύνθετόν τι καὶ μικτὸν ἐν μέσῳ ἀλαζονείας καὶ φιλοσοφίας πλαζόμενον, οὔτε τῇ ἀγνοίᾳ τέλεον προσεχόμενον οὔτε ἡμᾶς ἀτενέσι τοῖς ὀφθαλμοῖς καθορᾶν δυνάμενον, ἀλλ’ οἷον λημῶντες ὑπὸ τοῦ ἀμβλυώττειν ἀσαφές τι καὶ ἀμυδρὸν ἡμῶν εἴδωλον ἢ σκιὰν ἐνίοτε ἰδόντες ἄν· οἱ δὲ ᾤοντο ἀκριβῶς πάντα κατανενοηκέναι. ὅθεν παρ’ αὐτοῖς ἡ ἀχρεῖος ἐκείνη καὶ περιττὴ σοφία καί, ὡς αὐτοὶ ᾤοντο, ἀπρόσμαχος ἀνεφλέγετο, αἱ κομψαὶ καὶ ἄποροι καὶ ἄτοποι ἀποκρίσεις καὶ δυσέξοδοι καὶ λαβυρινθώδεις ἐρωτήσεις.", "st": "43.10"}, {"sp": "N", "t": "εἶτα κωλυόμενοι καὶ ἐλεγχόμενοι πρὸς τῶν ἑταίρων τῶν ἐμῶν ἠγανάκτουν καὶ συνίσταντο ἐπ’ αὐτούς, καὶ τέλος δικαστηρίοις ὑπῆγον καὶ παρεδίδοσαν πιομένους τοῦ κωνείου. ἐχρῆν μὲν οὖν ἴσως τότε φυγεῖν εὐθὺς καὶ μηκέτι ἀνέχεσθαι τὴν συνουσίαν αὐτῶν· νῦν δὲ Ἀντισθένης με καὶ Διογένης καὶ μετὰ μικρὸν Κράτης καὶ Μένιππος οὗτος ἔπεισαν ὀλίγον ὅσον ἐπιμετρῆσαι τῆς μονῆς, ὡς μήποτε ὤφελον· οὐ γὰρ ἂν τοσαῦτα ἐπεπόνθειν ὕστερον.", "st": "43.11"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> οὐδέπω μοι λέγεις, ὦ Φιλοσοφία, τίνα ἠδίκησαι, ἀλλὰ ἀγανακτεῖς μόνον.", "st": "43.12"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> καὶ μὴν ἄκουε, ὦ Ζεῦ, ἡλίκα ἐστίν. μιαρὸν γάρ τι φῦλον ἀνθρώπων καὶ ὡς τὸ πολὺ δουλικὸν καὶ θητικόν, οὐ ξυγγενόμενον ἡμῖν ἐκ παίδων ὑπ’ ἀσχολίας· ἐδούλευεν γὰρ ἢ ἐθήτευεν ἢ ἄλλας τινὰς τέχνας οἵας εἰκὸς τοὺς τοιούτους ἐμάνθανεν, σκυτεύειν ἢ τεκταίνειν ἢ περὶ πλυνοὺς ἔχειν ἢ ἔρια ξαίνειν, ὡς εὐεργὰ εἴη ταῖς γυναιξὶν καὶ εὐμήρυτα καὶ κατάγοιτο εὐμαρῶς ὁπότε ἢ κρόκην ἐκεῖναι στρέφοιεν ἢ μίτον κλώθοιεν. τοιαῦτα τοίνυν ἐν παισὶ μελετῶντες οὐδὲ ὄνομα τὸ ἡμέτερον ᾔδεσαν. ἐπεὶ δὲ εἰς ἄνδρας τελεῖν ἤρξαντο καὶ κατεῖδον τὴν αἰδῶ, ὅση παρὰ τῶν πολλῶν ἐστιν τοῖς ἑταίροις τοῖς ἐμοῖς, καὶ ὡς ἀνέχονται οἱ ἄνθρωποι τὴν παρρησίαν αὐτῶν καὶ χαίρουσιν θεραπευόμενοι καὶ συμβουλεύουσι πείθονται καὶ ἐπιτιμώντων ὑποπτήσσουσι, ταῦτα πάντα τυραννίδα οὐ μικρὰν ἡγοῦντο εἶναι.", "st": "43.12"}, {"sp": "N", "t": "τὸ μὲν δὴ μανθάνειν ὅσα τῇ τοιαύτῃ προαιρέσει πρόσφορα μακρὸν ἦν, μᾶλλον δὲ κομιδῇ ἀδύνατον, αἱ τέχναι δὲ γλίσχραι, καὶ σὺν πόνῳ καὶ μόγις ἱκανὰ παρέχειν ἐδύναντο. ἐνίοις δὲ καὶ ἡ δουλεία βαρὺ καί (ὥσπερ οὖν ἐστιν) ἀφόρητον ἐφαίνετο. ἔδοξε δὴ σκοπουμένοις τὴν ὑστάτην ἄγκυραν, ἣν ἱερὰν οἱ ναυτιλλόμενοί φασιν, καθιέναι, καὶ ἐπὶ τὴν βελτίστην ἀπόνοιαν ὁρμήσαντες, ἔτι τε καὶ τόλμαν καὶ ἀμαθίαν καὶ ἀναισχυντίαν προσπαρακαλέσαντες, αἵπερ αὐτοῖς μάλιστα συναγωνίζονται, καὶ λοιδορίας καινὰς ἐκμελετήσαντες, ὡς πρόχειροι εἶεν καὶ ἀνὰ στόμα, ταύτας μόνας ξυμβολὰς ἔχοντες — ὁρᾷς ὁποῖα πρὸς φιλοσοφίαν ἐφόδια; — σχηματίζουσιν καὶ μετακοσμοῦσιν αὑτοὺς εὖ μάλα εἰκότως καὶ πρὸς ἐμέ, οἷόν τι ἀμέλει ὁ Αἴσωπός φησι ποιῆσαι τὸν ἐν τῇ Κύμῃ ὄνον, ὃς λεοντῆν περιβαλόμενος καὶ τραχὺ ὀγκώμενος ἠξίου λέων καὶ αὐτὸς εἶναι· καί πού τινες καὶ ἦσαν ἴσως οἱ πιστεύοντες αὐτῷ.", "st": "43.13"}, {"sp": "N", "t": "τὰ δ’ ἡμέτερα πάνυ ῥᾷστα, ὡς οἶσθα, καὶ ἐς μίμησιν πρόχειρα — τὰ προφανῆ λέγω — καὶ οὐ πολλῆς τῆς πραγματείας δεῖ τριβώνιον περιβαλέσθαι καὶ πήραν ἐξαρτήσασθαι καὶ ξύλον ἐν τῇ χειρὶ ἔχειν καὶ βοᾶν, μᾶλλον δὲ ὀγκᾶσθαι ἢ ὑλακτεῖν, καὶ λοιδορεῖσθαι ἅπασιν· τὴν ἀσφάλειαν γὰρ αὐτοῖς τοῦ μηδὲν ἐπὶ τούτῳ παθεῖν ἡ πρὸς τὸ σχῆμα αἰδὼς παρέξειν ἔμελλεν. ἡ ἐλευθερία δὲ πρόχειρος ἄκοντος τοῦ δεσπότου, κἂν εἰ βούλοιτο ἀπάγειν, παταχθησομένου τῷ ξύλῳ. καὶ τὰ ἄλφιτα οὐκέτ’ ὀλίγα οὐδὲ ὡς πρὸ τοῦ μᾶζα ψιλή, τὸ δὲ ὄψον οὐ τάριχος ἢ θύμον, ἀλλὰ κρέα παντοδαπὰ καὶ οἶνος οἷος ἥδιστος, καὶ χρυσίον παρ’ ὅτου ἂν ἐθέλωσι· δασμολογοῦσι γὰρ ἐπιφοιτῶντες ἤ, ὡς αὐτοί φασιν, ἀποκείρουσιν τὰ πρόβατα, δώσειν τε πολλοὺς οἴονται ἢ αἰδοῖ τοῦ σχήματος ἢ δέει τοῦ μὴ ἀκοῦσαι κακῶς.", "st": "43.14"}, {"sp": "N", "t": "καὶ γὰρ αὖ κἀκεῖνο ἑώρων, οἶμαι, ὡς ἐξ ἴσου καταστήσονται τοῖς ὀρθῶς φιλοσοφοῦσιν, οὐδέ τις ὁ δικάσων καὶ διακρινῶν τὰ τοιαῦτα ἔσται, ἢν μόνον τὰ ἔξω ᾖ ὅμοια. ἀρχὴν γὰρ οὐδὲ τὸν ἔλεγχον δέχονται, ἢν ἔρηταί τις οὑτωσὶ κοσμίως καὶ κατὰ βραχύ, ἀλλ’ εὐθὺς βοῶσιν καὶ ἐπὶ τὴν ἀκρόπολιν τὴν ἑαυτῶν ἀναφεύγουσι, τὴν λοιδορίαν, καὶ πρόχειρον τὸ ξύλον. καὶ ἢν μὲν τὰ ἔργα ζητῇς, οἱ λόγοι πολλοί, ἢν δὲ ἀπὸ τῶν λόγων κρίνειν ἐθέλῃς, τὸν βίον ἀξιοῦσι σκοπεῖν.", "st": "43.15"}, {"sp": "N", "t": "τοιγαροῦν ἐμπέπλησται πᾶσα πόλις τῆς τοιαύτης ῥᾳδιουργίας, καὶ μάλιστα τῶν Διογένη καὶ Ἀντισθένη καὶ Κράτητα ἐπιγραφομένων καὶ ὑπὸ τῷ κυνὶ ταττομένων, οἳ τὸ μὲν χρήσιμον ὁπόσον ἔνεστι τῇ φύσει τῶν κυνῶν, οἷον τὸ φυλακτικὸν ἢ οἰκουρικὸν ἢ φιλοδέσποτον ἢ μνημονικόν, οὐδαμῶς ἐζηλώκασιν, ὑλακὴν δὲ καὶ λιχνείαν καὶ ἁρπαγὴν καὶ ἀφροδίσια συχνὰ καὶ κολακείαν καὶ τὸ σαίνειν τὸν διδόντα καὶ περὶ τραπέζας ἔχειν, ταῦτα ἀκριβῶς ἐκπεπονήκασιν.", "st": "43.16"}, {"sp": "N", "t": "ὄψει τοίνυν μετὰ μικρὸν οἷα ἔσται. οἱ γὰρ ἐκ τῶν ἐργαστηρίων ἅπαντες ἀναπηδήσαντες ἐρήμους τὰς τέχνας ἐάσουσιν ὅταν ὁρῶσι σφᾶς μέν, πονοῦντας καὶ κάμνοντας ἕωθεν ἐς ἑσπέραν ἐπικεκυφότας τοῖς ἔργοις, μόγις ἀποζῶντας ἐκ τῆς τοιαύτης μισθαρνίας, ἀργοὺς δὲ καὶ γόητας ἀνθρώπους ἐν ἅπασιν ἀφθόνοις βιοῦντας, αἰτοῦντας μὲν τυραννικῶς, λαμβάνοντας δὲ προχείρως, ἀγανακτοῦντας δέ, εἰ μὴ λάβοιεν, οὐκ ἐπαινοῦντας δέ, οὐδ’ εἰ λάβοιεν. ταῦτα ὁ ἐπὶ Κρόνου βίος δοκεῖ αὐτοῖς καὶ ἀτεχνῶς τὸ μέλι αὐτὸ ἐς τὰ στόματα ἐσρεῖν ἐκ τοῦ οὐρανοῦ.", "st": "43.17"}, {"sp": "N", "t": "καὶ ἧττον ἂν δεινὸν τὸ πρᾶγμα ἦν, εἰ τοιοῦτοι ὄντες μηδὲν εἰς ἡμᾶς ἄλλο ἐξύβριζον· οἱ δέ, μάλα σεμνοὶ καὶ σκυθρωποὶ τὰ ἔξω καὶ τὰ δημόσια φαινόμενοι, ἢν παιδὸς ὡραίου ἢ γυναικὸς λάβωνται καλῆς ἢ ἐλπίσωσιν, σιωπᾶν ἄξιον οἷα ποιοῦσιν. ἔνιοι δὲ καὶ ξένων τῶν σφετέρων γυναῖκας ἀπάγουσι μοιχεύσοντες κατὰ τὸν Ἰλιέα ἐκεῖνον νεανίσκον, ὡς φιλοσοφοῖεν δὴ καὶ αὗται· εἶτα κοινὰς αὐτὰς ἅπασι τοῖς ξυνοῦσι προθέμενοι Πλάτωνός τι δόγμα οἴονται ποιεῖν, οὐκ εἰδότες ὅπως ὁ ἱερὸς ἐκεῖνος ἠξίου κοινὰς ἡγεῖσθαι τὰς γυναῖκας.", "st": "43.18"}, {"sp": "N", "t": "ἃ μὲν γὰρ ἐν τοῖς συμποσίοις δρῶσιν καὶ ἃ μεθύσκονται, μακρὸν ἂν εἴη λέγειν. καὶ ταῦτα ποιοῦσι πῶς οἴει κατηγοροῦντες αὐτοὶ μέθης καὶ μοιχείας καὶ λαγνείας καὶ φιλαργυρίας· οὐδὲν γοῦν οὕτως εὕροις ἂν ἄλλο ἄλλῳ ἐναντίον ὡς τοὺς λόγους αὐτῶν καὶ τὰ ἔργα. οἷον κολακείαν μισεῖν φασιν, κολακείας ἕνεκα τὸν Γναθωνίδην ἢ τὸν Στρουθίαν ὑπερβαλέσθαι δυνάμενοι. ἀληθεύειν τοὺς ἄλλους προτρέποντες, οὐκ ἂν οὐδὲ κινῆσαι τὴν γλῶτταν μὴ μετὰ τοῦ καὶ ψεύσασθαι δύναιντο. ἡδονὴ πᾶσιν ἐχθρὸν τῷ λόγῳ καὶ ὁ Ἐπίκουρος πολέμιος, ἔργῳ δὲ διὰ ταύτην ἅπαντα πράττουσιν. τὸ δ’ ὀξύχολον καὶ μικραίτιον καὶ πρὸς ὀργὴν ῥᾴδιον ὑπὲρ τὰ βρεφύλλια τὰ νεογνά· γέλωτα γοῦν οὐ μικρὸν παρέχουσι τοῖς θεωμένοις, ὁπόταν ὑπὸ τῆς τυχούσης αἰτίας ἐπιζέσῃ μὲν αὐτοῖς ἡ χολή, πελιδνοὶ δὲ τὴν χροιὰν βλέπωνται, ἰταμόν τι καὶ παράφορον δεδορκότες, καὶ ἀφροῦ, μᾶλλον δὲ ἰοῦ, μεστὸν αὐτοῖς ᾖ τὸ στόμα.", "st": "43.19"}, {"sp": "N", "t": "μὴ σύ γε κεῖθι τύχοις, ὅτε ὁ μιαρὸς ἐκεῖνος ἐκχεῖται βόρβορος, “χρυσίον μὲν ἢ ἀργύριον, Ἡράκλεις, οὐδὲ κεκτῆσθαι ἀξιῶ· ὀβολὸς ἱκανός, ὡς θέρμους πριαίμην· ποτὸν γὰρ ἢ κρήνη ἢ ποταμὸς παρέξει.” καὶ μετ’ ὀλίγον αἰτοῦσιν οὐκ ὀβολοὺς οὐδὲ δραχμὰς ὀλίγας, ἀλλὰ πλούτους ὅλους, ὥστε τίς ἔμπορος τοσοῦτον ἀπὸ τοῦ φόρτου ἐμπολήσειεν ἂν ὅσον τούτοις φιλοσοφία ἐς χρηματισμὸν συντελεῖ; εἶτ’ ἐπειδὰν ἱκανῶς συλλέξωνται καὶ ἐπισιτίσωνται, ἀπορρίψαντες ἐκεῖνο τὸ δύστηνον τριβώνιον ἀγροὺς ἐνίοτε καὶ ἐσθῆτας τῶν μαλθακῶν ἐπρίαντο καὶ παῖδας κομήτας καὶ συνοικίας ὅλας, μακρὰ χαίρειν φράσαντες τῇ πήρᾳ τῇ Κράτητος καὶ τῷ τρίβωνι τῷ Ἀντισθένους καὶ τῷ πίθῳ τῷ Διογένους.", "st": "43.20"}, {"sp": "N", "t": "οἱ ἰδιῶται δὲ ταῦτα ὁρῶντες καταπτύουσιν ἤδη φιλοσοφίας καὶ ἅπαντας εἶναι τοιούτους οἴονται κἀμὲ τῆς διδασκαλίας αἰτιῶνται, ὥστε πολλοῦ ἤδη χρόνου ἀδύνατόν μοι γεγένηται κἂν ἕνα τινὰ προσαγαγέσθαι αὐτῶν, ἀλλὰ τὸ τῆς Πηνελόπης ἐκεῖνο πάσχω· ὁπόσον γὰρ δὴ ἐγὼ ἐξυφήνω, τοῦτο ἐν ἀκαρεῖ αὖθις ἀναλύεται. ἡ Ἀμαθία δὲ καὶ ἡ Ἀδικία ἐπιγελῶσιν, ὁρῶσαι ἀνεξέργαστον ἡμῖν τὸ ἔργον καὶ ἀνήνυτον τὸν πόνον.", "st": "43.21"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> οἷα, ὦ θεοί, πέπονθεν ἡμῖν ἡ Φιλοσοφία πρὸς τῶν καταράτων ἐκείνων. ὥστε ὥρα σκοπεῖν ὅ τι καὶ πρακτέον ἢ ὅπως αὐτοὺς μετελευστέον. ὁ μὲν γὰρ κεραυνὸς ἀπάγει μιᾷ πληγῇ καὶ ὁ θάνατος ταχύς.", "st": "43.22"}, {"sp": "N", "t": "<em>Ἀπόλλων.<\/em> ἐγώ σοι, ὦ πάτερ, ὑποθήσομαι· μισῶ γὰρ καὶ αὐτὸς ἤδη τοὺς ἀλαζόνας ἀμούσους ὄντας, ὑπὲρ τῶν Μουσῶν ἀγανακτῶν. κεραυνοῦ μὲν γὰρ ἢ τῆς σῆς δεξιᾶς οὐδαμῶς ἐκεῖνοι ἄξιοι, τὸν Ἑρμῆν δὲ αὐτοκράτορα, εἰ δοκεῖ, τῆς κολάσεως κατάπεμψον ἐπ’ αὐτούς, ὃς ἅτε δὴ περὶ λόγους ἔχων καὶ αὐτὸς τάχιστα εἴσεται τούς τε ὀρθῶς φιλοσοφοῦντας καὶ τοὺς μή. εἶτα τοὺς μὲν ἐπαινέσεται, ὡς τὸ εἰκός, οἱ δὲ κολασθήσονται ὅπως ἂν ἐκείνῳ παρὰ τὸν καιρὸν δοκῇ.", "st": "43.22"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> εὖ λέγεις, ὦ Ἄπολλον. ἀλλὰ καὶ σύ, ὦ Ἡράκλεις, ἅμα καὶ τὴν Φιλοσοφίαν αὐτὴν ἔχοντες ἄπιτε ὡς τάχιστα εἰς τὸν βίον. τρισκαιδέκατον γοῦν ἆθλον οἴου τοῦτον οὐ σμικρὸν ἐκτελέσειν, ἢν ἐκκόψῃς μιαρὰ οὕτω καὶ ἀναίσχυντα θηρία.", "st": "43.23"}, {"sp": "N", "t": "<em>Ἡρακλῆς.<\/em> καὶ μὴν ἄμεινον ἦν, ὦ πάτερ, τὴν κόπρον ἐκκαθᾶραι αὖθις τὴν Αὐγέου ἢ τούτοις συμπλέκεσθαι. ἀπίωμεν δ’ ὅμως.", "st": "43.23"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἄκουσα μέν, ἀκολουθητέον δὲ κατὰ τὰ δόξαντα τῷ πατρί.", "st": "43.23"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Κατίωμεν, ὡς κἂν ὀλίγους αὐτῶν ἐπιτρίψωμεν σήμερον. ποίαν δὲ χρὴ τραπέσθαι, ὦ Φιλοσοφία; σὺ γὰρ οἶσθα ὅπου εἰσίν. ἢ πρόδηλον ὅτι ἐν τῇ Ἑλλάδι;", "st": "43.24"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> οὐδαμῶς, ἢ πάνυ ὀλίγοι, ὅσοι ὀρθῶς φιλοσοφοῦσιν, ὦ Ἑρμῆ. οὗτοι δὲ οὐδὲν Ἀττικῆς πενίας δέονται, ἀλλ’ ἔνθα πολὺς χρυσὸς ἢ ἄργυρος ὀρύττεται, ἐκεῖ που ζητητέοι εἰσὶν ἡμῖν.", "st": "43.24"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐκοῦν εὐθὺ τῆς Θρᾴκης ἀπιτέον.", "st": "43.24"}, {"sp": "N", "t": "<em>Ἡρακλῆς.<\/em> εὖ λέγεις, καὶ ἡγήσομαί γε ὑμῖν τῆς ὁδοῦ. οἶδα γὰρ τὰ Θρᾳκῶν ἅπαντα, συχνάκις ἐπελθών. καί μοι τήνδε ἤδη τραπώμεθα.", "st": "43.24"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ποίαν λέγεις;", "st": "43.24"}, {"sp": "N", "t": "<em>Ἡρακλῆς.<\/em> ὁρᾶτε, ὦ Ἑρμῆ καὶ Φιλοσοφία, δύο μὲν ὄρη μέγιστα καὶ κάλλιστα ὀρῶν ἁπάντων (Αἷμός ἐστιν τὸ μεῖζον, ἡ καταντικρὺ δὲ Ῥοδόπη) πεδίον δὲ ὑποπεπταμένον πάμφορον, ἀπὸ τῶν προπόδων ἑκατέρων εὐθὺς ἀρξάμενον, καί τινας λόφους τρεῖς πάνυ καλοὺς ἀνεστηκότας, οὐκ ἀμόρφους τὴν τραχύτητα, οἷον ἀκροπόλεις πολλὰς τῆς ὑποκειμένης πόλεως. καὶ ἡ πόλις γὰρ ἤδη φαίνεται.", "st": "43.25"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> νὴ Δί’, ὦ Ἡράκλεις, μεγίστη καὶ καλλίστη ἁπασῶν· πόρρωθεν γοῦν ἀπολάμπει τὸ κάλλος. καί τις καὶ ποταμὸς μέγιστος παραμείβεται, πάνυ ἐν χρῷ ψαύων αὐτῆς.", "st": "43.25"}, {"sp": "N", "t": "<em>Ἡρακλῆς.<\/em> Ἕβρος μὲν οὗτος, ἡ δὲ πόλις ἔργον Φιλίππου ἐκείνου. καὶ ἡμεῖς ἤδη πρόσγειοι καὶ ὑπονέφελοι· ὥστε ἐπιβαίνωμεν ἀγαθῇ τύχῃ.", "st": "43.25"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὕτω γινέσθω. τί δ’ οὖν χρὴ ποιεῖν, ἢ πῶς τὰ θηρία ἐξιχνευτέον;", "st": "43.26"}, {"sp": "N", "t": "<em>Ἡρακλῆς.<\/em> τοῦτο μὲν σὸν ἤδη ἔργον, ὦ Ἑρμῆ· κῆρυξ γὰρ εἶ, ὥστε οὐκ ἂν φθάνοις κηρύττων.", "st": "43.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐδὲν τοῦτο χαλεπόν, ἀλλὰ τά γε ὀνόματα οὐκ ἐπίσταμαι αὐτῶν. σὺ οὖν, Φιλοσοφία, λέγε οὕστινας ὀνομαστέον, καὶ τὰ σημεῖα προσέτι.", "st": "43.26"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> οὐδὲ αὐτὴ μὲν οἶδα τὸ σαφὲς οἵτινες ὀνομάζονται διὰ τὸ μὴ ξυγγεγενῆσθαί ποτε αὐτοῖς· ἀπὸ δ’ οὖν τῆς ἐπιθυμίας ἣν ἔχουσι περὶ τὰ κτήματα, οὐκ ἂν ἁμάρτοις προσκαλῶν Κτήσωνας ἢ Κτησίππους ἢ Κτησικλέας ἢ Εὐκτήμονας ἢ Πολυκτήτους.", "st": "43.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εὖ λέγεις. ἀλλὰ τίνες οὗτοί εἰσιν ἢ τί περισκοποῦσιν καὶ αὐτοί; μᾶλλον δὲ καὶ προσίασιν καί τι καὶ ἐρέσθαι θέλουσιν.", "st": "43.27"}, {"sp": "N", "t": "<em>Ἀνήρ.<\/em> ἆρ’ ἂν ἔχοιτε ἡμῖν, ὦ ἄνδρες, εἰπεῖν, ἢ σύ, ὦ βελτίστη, εἴ τινας τρεῖς γόητας ἅμα εἴδετε καί τινα γυναῖκα ἐν χρῷ κεκαρμένην εἰς τὸ Λακωνικόν, ἀρρενωπὴν καὶ κομιδῇ ἀνδρικήν;", "st": "43.27"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> παπαῖ, τὰ ἡμέτερα οὗτοι ζητοῦσιν.", "st": "43.27"}, {"sp": "N", "t": "<em>Ἀνήρ.<\/em> πῶς τὰ ὑμέτερα; δραπέται γὰρ ἐκεῖνοι ἅπαντες. ἡμεῖς δὲ τὴν γυναῖκα μάλιστα μέτιμεν ἠνδραποδισμένην πρὸς αὐτῶν.", "st": "43.27"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εἴσεσθε δὴ καθ’ ὅ τι καὶ ζητοῦμεν αὐτούς. τὸ νῦν δὲ ἅμα κηρύττωμεν.", "st": "43.27"}, {"sp": "N", "t": "εἴ τις εἶδεν ἀνδράποδον Παφλαγονικὸν τῶν ἀπὸ Σινώπης βαρβάρων, ὄνομα τοιοῦτον οἷον ἀπὸ κτημάτων, ὕπωχρον, ἐν χρῷ κουρίαν, ἐν γενείῳ βαθεῖ, πήραν ἐξημμένον καὶ τριβώνιον ἀμπεχόμενον, ὀργίλον, ἄμουσον, τραχύφωνον, λοίδορον, μηνύειν ἐπὶ ῥητῷ αὐτόν.", "st": "43.27"}, {"sp": "N", "t": "<em>Δεσπότης αʹ.<\/em> ἀνόμοιον, ὦ οὗτος, ὃ κηρύττεις· ὡς ἐκείνῳ γε ὄνομα ἦν παρ’ ἐμοὶ Κάνθαρος, καὶ ἐκόμα δὲ καὶ τὸ γένειον ἐτίλλετο καὶ τέχνην τὴν ἐμὴν ἠπίστατο· ἀπέκειρεν γὰρ ἐν τῷ γναφείῳ καθήμενος ὁπόσον περιττὸν τοῖς ἱματίοις τῶν κροκύδων ἐπανθεῖ.", "st": "43.28"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἐκεῖνος αὐτός ἐστιν, ὁ οἰκέτης ὁ σός, ἀλλὰ νῦν φιλοσόφῳ ἔοικεν ἀκριβῶς ἑαυτὸν ἐπιγνάψας.", "st": "43.28"}, {"sp": "N", "t": "<em>Δεσπότης αʹ.<\/em> ὢ τῆς τόλμης, ὁ Κάνθαρος φιλοσοφεῖ, φησίν, ἡμῶν δὲ οὐδεὶς λόγος.", "st": "43.28"}, {"sp": "N", "t": "<em>Δεσπότης βʹ.<\/em> Ἀμέλει ἅπαντας ἀνευρήσομεν· ξυνίησιν γάρ, ὥς φησιν, αὕτη.", "st": "43.28"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τίς δ’ οὗτος ἄλλος ὁ προσιών ἐστιν, ὦ Ἡράκλεις, ὁ καλός, ὁ τὴν κιθάραν;", "st": "43.29"}, {"sp": "N", "t": "<em>Ἡρακλῆς.<\/em> Ὀρφεύς ἐστιν, σύμπλους ἐπὶ τῆς Ἀργοῦς ἐμός, ἥδιστος κελευστῶν ἁπάντων· πρὸς γοῦν τὴν ᾠδὴν αὐτοῦ ἥκιστα ἐκάμνομεν ἐρέττοντες. χαῖρε, ὦ ἄριστε καὶ μουσικώτατε Ὀρφεῦ· οὐκ ἐπιλέλησαι γάρ που Ἡρακλέους.", "st": "43.29"}, {"sp": "N", "t": "<em>Ὀρφεύς.<\/em> νὴ καὶ ὑμεῖς γε, ὦ Φιλοσοφία καὶ Ἡράκλεις καὶ Ἑρμῆ. ἀλλὰ καιρὸς ἀποδιδόναι τὰ μήνυτρα, ὡς ἔγωγε πάνυ σαφῶς ὃν ζητεῖτε οἶδα.", "st": "43.29"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐκοῦν δεῖξον, ὦ παῖ Καλλιόπης, ἔνθα ἐστίν· χρυσίου γὰρ οὐδέν, οἶμαι, δέῃ σοφὸς ὤν.", "st": "43.29"}, {"sp": "N", "t": "<em>Ὀρφεύς.<\/em> εὖ φής. ἐγὼ δὲ τὴν μὲν οἰκίαν δείξαιμ’ ἂν ὑμῖν ἔνθα οἰκεῖ, αὐτὸν δὲ οὐκ ἄν, ὡς μὴ κακῶς ἀκούοιμι πρὸς αὐτοῦ· μιαρὸς γὰρ εἰς ὑπερβολὴν καὶ μόνον τοῦτο ἐκμεμελέτηκεν.", "st": "43.29"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> δεῖξον μόνον.", "st": "43.29"}, {"sp": "N", "t": "<em>Ὀρφεύς.<\/em> αὕτη πλησίον. ἐγὼ δὲ ἄπειμι ὑμῖν ἐκποδών, ὡς μηδ’ ἴδοιμι αὐτόν.", "st": "43.29"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἐπίσχες. οὐ γυναικός ἐστι φωνὴ ῥαψῳδούσης τι τῶν Ὁμήρου;", "st": "43.30"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> νὴ Δία· ἀλλ’ ἀκούσωμεν ὅ τι καὶ λέγει.", "st": "43.30"}, {"sp": "N", "t": "<em>Γυνή.<\/em> ἐχθρὸς γάρ μοι κεῖνος ὁμῶς Ἀΐδαο πύλῃσιν,<br>ὃς χρυσὸν φιλέει μὲν ἐνὶ φρεσίν, ἄλλο δὲ εἴπῃ.", "st": "43.30"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐκοῦν τὸν Κάνθαρόν σοι μισητέον.", "st": "43.30"}, {"sp": "N", "t": "<em>Γυνή.<\/em> ξεινοδόκον κακὰ ῥέξεν, ὅ κεν φιλότητα παράσχῃ.", "st": "43.30"}, {"sp": "N", "t": "<em>Ἀνήρ.<\/em> περὶ ἐμοῦ τοῦτο τὸ ἔπος, οὗ τὴν γυναῖκα ᾤχετο ἀπάγων διότι αὐτὸν ὑπεδεξάμην.", "st": "43.30"}, {"sp": "N", "t": "<em>Γυνή.<\/em> οἰνοβαρές, κυνὸς ὄμματ’ ἔχων, κραδίην δ’ ἐλάφοιο,<br>οὔτε ποτ’ ἐν πολέμῳ ἐναρίθμιος οὔτ’ ἐνὶ βουλῇ,<br>Θερσίτ’ ἀκριτόμυθε, κακῶν πανάριστε κολοιῶν<br>μάψ, ἀτὰρ οὐ κατὰ κόσμον, ἐριζέμεναι βασιλεῦσιν.", "st": "43.30"}, {"sp": "N", "t": "<em>Δεσπότης αʹ.<\/em> Εἰκότως τῷ καταράτῳ τὰ ἔπη.", "st": "43.30"}, {"sp": "N", "t": "<em>Γυνή.<\/em> Πρόσθε κύων, ὄπιθεν δὲ λέων, μέσση δὲ χίμαιρα<br>δεινὸν ἀποπνείουσα τρίτου κυνὸς ἄγριον ὁρμήν.", "st": "43.30"}, {"sp": "N", "t": "<em>Ἀνήρ.<\/em> οἴμοι, γύναι, ὅσα πέπονθας ὑπὸ κυνῶν τοσούτων. φασὶ δ’ αὐτὴν καὶ κυεῖν ἀπ’ αὐτῶν.", "st": "43.31"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> θάρρει, Κέρβερόν τινα τέξεταί σοι ἢ Γηρυόνην, ὡς ἔχοι ὁ Ἡρακλῆς οὗτος αὖθις πόνον. ἀλλὰ καὶ προΐασιν, ὥστε οὐδὲν δεῖ κόπτειν τὴν θύραν.", "st": "43.31"}, {"sp": "N", "t": "<em>Δεσπότης αʹ.<\/em> ἔχω σε, ὦ Κάνθαρε. νῦν σιωπᾷς; φέρ’ ἴδωμεν ἅτινά σοι ἡ πήρα ἔχει, θέρμους ἴσως ἢ ἄρτου τρύφος. οὐ μὰ Δί’, ἀλλὰ ζώνην χρυσίου.", "st": "43.31"}, {"sp": "N", "t": "<em>Ἡρακλῆς.<\/em> μὴ θαυμάσῃς· κυνικὸς γὰρ ἔφασκεν εἶναι τὸ πρόσθεν ἐπὶ τῆς Ἑλλάδος, ἐνταῦθα δὲ Χρυσίππειος ἀκριβῶς ἐστιν. τοιγαροῦν Κλεάνθην οὐκ εἰς μακρὰν αὐτὸν ὄψει· κρεμήσεται γὰρ ἀπὸ τοῦ πώγωνος οὕτω μιαρὸς ὤν.", "st": "43.31"}, {"sp": "N", "t": "<em>Δεσπότης βʹ.<\/em> σὺ δέ, ὦ κακέ, οὐ Ληκυθίων οὑμὸς δραπέτης τυγχάνεις; οὐ μὲν οὖν ἄλλος. ὢ τοῦ γέλωτος. εἶτα τί οὐκ ἂν γένοιτο; καὶ Ληκυθίων φιλοσοφεῖ.", "st": "43.32"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ὁ τρίτος δὲ οὗτος ἀδέσποτος ὑμῖν ἐστιν;", "st": "43.32"}, {"sp": "N", "t": "<em>Δεσπότης γʹ.<\/em> Οὐδαμῶς, ἀλλ’ ὁ δεσπότης ἐγὼ ἑκὼν ἀφίημι αὐτὸν ἀπολωλέναι.", "st": "43.32"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ὅτι τί;", "st": "43.32"}, {"sp": "N", "t": "<em>Δεσπότης γʹ.<\/em> ὅτι δεινῶς τῶν ὑποσάθρων ἐστίν. τὸ δ’ ὄνομα Μυρόπνουν αὐτὸν ἐκαλοῦμεν.", "st": "43.32"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Ἡράκλεις ἀλεξίκακε, ἀκούεις; ἔπειτα πήρα καὶ βάκτρον. — καὶ αὐτὸς ἀπόλαβε τὴν γυναῖκα σύ.", "st": "43.32"}, {"sp": "N", "t": "<em>Ἀνήρ.<\/em> μηδαμῶς. οὐκ ἂν ἀπολάβοιμι βιβλίον μοι τῶν παλαιῶν κυοῦσαν.", "st": "43.32"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> πῶς βιβλίον;", "st": "43.32"}, {"sp": "N", "t": "<em>Ἀνήρ.<\/em> ἔστιν τι, ὦ ἀγαθέ, Τρικάρανος βιβλίον.", "st": "43.32"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Οὐδὲν ἄτοπον, ἐπεὶ καὶ Τριφάλης.", "st": "43.32"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> σόν, ὦ Ἑρμῆ, δικάζειν τὸ μετὰ τοῦτο.", "st": "43.33"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὕτω μοι δοκεῖ, ταύτην μέν, ἵνα μηδὲν τέρας μηδὲ πολυκέφαλον τέκῃ, οἴχεσθαι παρὰ τὸν ἄνδρα ὀπίσω ἐς τὴν Ἑλλάδα, τὼ δύο δὲ τούτω δραπετίσκω παραδοθέντε τοῖν δεσπόταιν μανθάνειν ἃ πρὸ τοῦ, τὸν μὲν ἀποπλύνειν τὰς ῥυπώσας τῶν ὀθονῶν, τὸν Ληκυθίωνα, τὸν Μυρόπνουν δὲ αὖθις ἀκεῖσθαι τῶν ἱματίων τὰ διερρωγότα, μαλάχῃ γε πρότερον μαστιγωθέντε. ἔπειτα καὶ τοῦτον παραδοθῆναι τοῖς πιττωταῖς, ὡς ἀπόλοιτο παρατιλλόμενος τὰ πρῶτα, ῥυπώσῃ προσέτι καὶ γυναικείᾳ τῇ πίττῃ, εἶτα ἐς τὸν Αἷμον ἀναχθέντα γυμνὸν ἐπὶ τῆς χιόνος μένειν συμπεποδισμένον τὼ πόδε.", "st": "43.33"}, {"sp": "N", "t": "<em>Κάνθαρος.<\/em> φεῦ τῶν κακῶν, ὀτοτοῖ, παππαπαιάξ.", "st": "43.33"}, {"sp": "N", "t": "<em>Δεσπότης αʹ.<\/em> τί τοῦτο παρεντίθης τῶν τραγικῶν σου διαλόγων; ἀλλ’ ἀκολούθει παρὰ τοὺς πιττωτὰς ἤδη, ἀποδυσάμενός γε πρότερον τὴν λεοντῆν, ὡς γνωσθῇς ὄνος ὤν.", "st": "43.33"}, {"sp": "HDR", "t": "Τόξαρις ἢ Φιλία"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> τί φής, ὦ Τόξαρι; θύετε Ὀρέστῃ καὶ Πυλάδῃ ὑμεῖς οἱ Σκύθαι καὶ θεοὺς εἶναι πεπιστεύκατε αὐτούς;", "st": "44.1"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> θύομεν, ὦ Μνήσιππε, θύομεν, οὐ μὴν θεούς γε οἰόμενοι εἶναι, ἀλλὰ ἄνδρας ἀγαθούς.", "st": "44.1"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> νόμος δὲ ὑμῖν καὶ ἀνδράσιν ἀγαθοῖς ἀποθανοῦσι θύειν ὥσπερ θεοῖς;", "st": "44.1"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> οὐ μόνον, ἀλλὰ καὶ ἑορταῖς καὶ πανηγύρεσιν τιμῶμεν αὐτούς.", "st": "44.1"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> τί θηρώμενοι παρ’ αὐτῶν; οὐ γὰρ δὴ ἐπ’ εὐμενείᾳ θύετε αὐτοῖς, νεκροῖς γε οὖσιν.", "st": "44.1"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> οὐ χεῖρον μὲν ἴσως, εἰ καὶ οἱ νεκροὶ ἡμῖν εὐμενεῖς εἶεν· οὐ μὴν ἀλλὰ πρὸς τοὺς ζῶντας ἄμεινον οἰόμεθα πράξειν μεμνημένοι τῶν ἀρίστων, καὶ τιμῶμεν ἀποθανόντας, ἡγούμεθα γὰρ οὕτως ἂν ἡμῖν πολλοὺς ὁμοίους αὐτοῖς ἐθελῆσαι γενέσθαι.", "st": "44.1"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ἀλλὰ ταῦτα μὲν ὀρθῶς γιγνώσκετε. Ὀρέστην δὲ καὶ Πυλάδην τίνος μάλιστα θαυμάσαντες ἰσοθέους ἐποιήσασθε, καὶ ταῦτα ἐπήλυδας ὑμῖν ὄντας καὶ τὸ μέγιστον πολεμίους; οἵ γε, ἐπεὶ σφᾶς ναυαγίᾳ περιπεσόντας οἱ τότε Σκύθαι συλλαβόντες ἀπῆγον ὡς τῇ Ἀρτέμιδι καταθύσοντες, ἐπιθέμενοι τοῖς δεσμοφύλαξι καὶ τῆς φρουρᾶς ἐπικρατήσαντες τόν τε βασιλέα κτείνουσι καὶ τὴν ἱέρειαν παραλαβόντες, ἀλλὰ καὶ τὴν Ἄρτεμιν αὐτὴν ἀποσυλήσαντες ᾤχοντο ἀποπλέοντες, καταγελάσαντες τοῦ κοινοῦ τῶν Σκυθῶν. ὥστε εἰ διὰ ταῦτα τιμᾶτε τοὺς ἄνδρας, οὐκ ἂν φθάνοιτε πολλοὺς ὁμοίους αὐτοῖς ἐξεργασάμενοι. καὶ τοὐντεῦθεν αὐτοὶ ἤδη πρὸς τὰ παλαιὰ σκοπεῖτε, εἰ καλῶς ἔχει ὑμῖν πολλοὺς ἐς τὴν Σκυθίαν Ὀρέστας καὶ Πυλάδας καταίρειν. ἐμοὶ μὲν γὰρ δοκεῖτε τάχιστα ἂν οὕτως ἀσεβεῖς αὐτοὶ καὶ ἄθεοι γενέσθαι, τῶν περιλοίπων θεῶν τὸν αὐτὸν τρόπον ὑμῖν ἐκ τῆς χώρας ἀποξενωθέντων. εἶτ’, οἶμαι, ἀντὶ τῶν θεῶν ἁπάντων τοὺς ἐπ’ ἐξαγωγῇ αὐτῶν ἥκοντας ἄνδρας ἐκθειάσετε καὶ ἱεροσύλοις ὑμῶν οὖσιν θύσετε ὡς θεοῖς.", "st": "44.2"}, {"sp": "N", "t": "εἰ γὰρ μὴ ἀντὶ τούτων Ὀρέστην καὶ Πυλάδην τιμᾶτε, ἀλλ’ εἰπέ, τί ἄλλο, ὦ Τόξαρι, ἀγαθὸν ὑμᾶς εἰργάσαντο ἀνθ’ ὅτου, πάλαι οὐ θεοὺς εἶναι δικαιώσαντες αὐτούς, νῦν τὸ ἔμπαλιν θύσαντες αὐτοῖς θεοὺς νενομίκατε, καὶ ἱερείοις ὀλίγου δεῖν τότε γενομένοις ἱερεῖα νῦν προσάγετε; γελοῖα γὰρ ἂν ταῦτα δόξειε καὶ ὑπεναντία τοῖς πάλαι.", "st": "44.3"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> καὶ ταῦτα μέν, ὦ Μνήσιππε, γενναῖα τῶν ἀνδρῶν ἐκείνων ἃ κατέλεξας. τὸ γὰρ δύο ὄντας οὕτω μέγα τόλμημα τολμῆσαι καὶ τοσοῦτον ἀπὸ τῆς αὐτῶν ἀπάραντας ἐκπλεῦσαι ἐς τὸν Πόντον ἀπείρατον ἔτι τοῖς Ἕλλησιν ὄντα πλὴν μόνων τῶν ἐπὶ τῆς Ἀργοῦς ἐς τὴν Κολχίδα στρατευσάντων, μὴ καταπλαγέντας μήτε τοὺς μύθους τοὺς ἐπ’ αὐτῷ μήτε τὴν προσηγορίαν καταδείσαντας ὅτι ἄξενος ἐκαλεῖτο, οἷα, οἶμαι, ἀγρίων ἐθνῶν περιοικούντων, καὶ ἐπειδὴ ἑάλωσαν, οὕτως ἀνδρείως χρήσασθαι τῷ πράγματι καὶ μὴ ἀγαπῆσαι εἰ διαφεύξονται μόνον, ἀλλὰ τιμωρησαμένους τὸν βασιλέα τῆς ὕβρεως καὶ τὴν Ἄρτεμιν ἀναλαβόντας ἀποπλεῦσαι, πῶς ταῦτα οὐ θαυμαστὰ καὶ θείας τινὸς τιμῆς ἄξια παρὰ πάντων ὁπόσοι ἀρετὴν ἐπαινοῦσιν; ἀτὰρ οὐ ταῦτα ἡμεῖς Ὀρέστῃ καὶ Πυλάδῃ ἐνιδόντες ἥρωσιν αὐτοῖς χρώμεθα.", "st": "44.3"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> λέγοις ἂν ἤδη ὅ τι τὸ σεμνὸν καὶ θεῖον ἄλλο ἐξειργάσαντο· ἐπεὶ ὅσον ἐπὶ τῷ πλῷ καὶ τῇ ἀποδημίᾳ πολλοὺς ἄν σοι θειοτέρους ἐκείνων ἀποδείξαιμι, τοὺς ἐμπόρους, καὶ μάλιστα τοὺς Φοίνικας αὐτῶν, οὐκ εἰς τὸν Πόντον οὐδὲ ἄχρι τῆς Μαιώτιδος καὶ τοῦ Βοσπόρου μόνον ἐσπλέοντας, ἀλλὰ πανταχοῦ τῆς Ἑλληνικῆς καὶ βαρβαρικῆς θαλάττης ναυτιλλομένους· ἅπασαν γὰρ οὗτοι ἀκτὴν καὶ πάντα αἰγιαλόν, ὡς εἰπεῖν, διερευνησάμενοι καθ’ ἕκαστον ἔτος ὀψὲ τοῦ μετοπώρου εἰς τὴν αὐτῶν ἐπανίασιν. οὓς κατὰ τὸν αὐτὸν λόγον θεοὺς νόμιζε, καὶ ταῦτα καπήλους καὶ ταριχοπώλας, εἰ τύχοι, τοὺς πολλοὺς αὐτῶν ὄντας.", "st": "44.4"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> ἄκουε δή, ὦ θαυμάσιε, καὶ σκόπει καθ’ ὅσον ἡμεῖς οἱ βάρβαροι εὐγνωμονέστερον ὑμῶν περὶ τῶν ἀγαθῶν ἀνδρῶν κρίνομεν, εἴ γε ἐν Ἄργει μὲν καὶ Μυκήναις οὐδὲ τάφον ἔνδοξον ἔστιν ἰδεῖν Ὀρέστου ἢ Πυλάδου, παρ’ ἡμῖν δὲ καὶ νεὼς ἀποδέδεικται αὐτοῖς ἅμα ἀμφοτέροις, ὥσπερ εἰκὸς ἦν, ἑταίροις γε οὖσι, καὶ θυσίαι προσάγονται καὶ ἡ ἄλλη τιμὴ ἅπασα, κωλύει τε οὐδὲν ὅτι ξένοι ἦσαν ἀλλὰ μὴ Σκύθαι ἀγαθοὺς κεκρίσθαι καὶ ὑπὸ Σκυθῶν τῶν ἀρίστων θεραπεύεσθαι. οὐ γὰρ ἐξετάζομεν ὅθεν οἱ καλοὶ καὶ ἀγαθοί εἰσιν, οὐδὲ φθονοῦμεν εἰ μὴ φίλοι ὄντες ἀγαθὰ εἰργάσαντο, ἐπαινοῦντες δὲ ἃ ἔπραξαν, οἰκείους αὐτοὺς ἀπὸ τῶν ἔργων ποιούμεθα.", "st": "44.5"}, {"sp": "N", "t": "Ὃ δὲ δὴ μάλιστα καταπλαγέντες τῶν ἀνδρῶν ἐκείνων ἐπαινοῦμεν τοῦτό ἐστιν, ὅτι ἡμῖν ἔδοξαν φίλοι οὗτοι δὴ ἄριστοι ἁπάντων γεγενῆσθαι καὶ τοῖς ἄλλοις νομοθέται καταστῆναι ὡς χρὴ τοῖς φίλοις ἁπάσης τύχης κοινωνεῖν.", "st": "44.5"}, {"sp": "N", "t": "καὶ ἅ γε μετ’ ἀλλήλων ἢ ὑπὲρ ἀλλήλων ἔπαθον ἀναγράψαντες οἱ πρόγονοι ἡμῶν ἐπὶ στήλης χαλκῆς ἀνέθεσαν εἰς τὸ Ὀρέστειον, καὶ νόμον ἐποιήσαντο πρῶτον τοῦτο μάθημα καὶ παίδευμα τοῖς παισὶ τοῖς σφετέροις εἶναι τὴν στήλην ταύτην καὶ τὰ ἐπ’ αὐτῆς γεγραμμένα διαμνημονεῦσαι. θᾶττον γοῦν τοὔνομ’ ἂν ἕκαστος αὐτῶν ἐπιλάθοιτο τοῦ πατρὸς ἢ τὰς Ὀρέστου καὶ Πυλάδου πράξεις ἀγνοήσειεν.", "st": "44.6"}, {"sp": "N", "t": "ἀλλὰ καὶ ἐν τῷ περιβόλῳ τοῦ νεὼ τὰ αὐτὰ ὁπόσα ἡ στήλη δηλοῖ γραφαῖς ὑπὸ τῶν παλαιῶν εἰκασμένα δείκνυται, πλέων Ὀρέστης ἅμα τῷ φίλῳ, εἶτα ἐν τοῖς κρημνοῖς διαφθαρείσης αὐτῷ τῆς νεὼς συνειλημμένος καὶ πρὸς τὴν θυσίαν παρεσκευασμένος, καὶ ἡ Ἰφιγένεια ἤδη κατάρχεται αὐτῶν. καταντικρὺ δὲ ἐπὶ τοῦ ἑτέρου τοίχου ἤδη ἐκδεδυκὼς τὰ δεσμὰ γέγραπται καὶ φονεύων τὸν Θόαντα καὶ πολλοὺς ἄλλους τῶν Σκυθῶν, καὶ τέλος ἀποπλέοντες, ἔχοντες τὴν Ἰφιγένειαν καὶ τὴν θεόν. οἱ Σκύθαι δὲ ἄλλως ἐπιλαμβάνονται τοῦ σκάφους ἤδη πλέοντος, ἐκκρεμαννύμενοι τῶν πηδαλίων καὶ ἐπαναβαίνειν πειρώμενοι· εἶτ’ οὐδὲν ἀνύσαντες οἱ μὲν αὐτῶν τραυματίαι, οἱ δὲ καὶ δέει τούτου, ἀπονήχονται πρὸς τὴν γῆν. ἔνθα δὴ καὶ μάλιστα ἴδοι τις ἂν ὁπόσην ὑπὲρ ἀλλήλων εὔνοιαν ἐπεδείκνυντο, ἐν τῇ πρὸς τοὺς Σκύθας συμπλοκῇ. πεποίηκεν γὰρ ὁ γραφεὺς ἑκάτερον ἀμελοῦντα μὲν τῶν καθ’ ἑαυτὸν πολεμίων, ἀμυνόμενον δὲ τοὺς ἐπιφερομένους θατέρῳ καὶ πρὸ ἐκείνου ἀπαντᾶν πειρώμενον τοῖς τοξεύμασιν καὶ παρ’ οὐδὲν τιθέμενον εἰ ἀποθανεῖται σώσας τὸν φίλον καὶ τὴν ἐπ’ ἐκεῖνον φερομένην πληγὴν προαρπάσας τῷ ἑαυτοῦ σώματι.", "st": "44.6"}, {"sp": "N", "t": "τὴν δὴ τοσαύτην εὔνοιαν αὐτῶν καὶ τὴν ἐν τοῖς δεινοῖς κοινωνίαν καὶ τὸ πιστὸν καὶ φιλέταιρον καὶ τὸ ἀληθὲς καὶ βέβαιον τοῦ πρὸς ἀλλήλους ἔρωτος, οὐκ ἀνθρώπινα ταῦτα ᾠήθημεν εἶναι, ἀλλά τινος γνώμης βελτίονος ἢ κατὰ τοὺς πολλοὺς τούτους ἀνθρώπους, οἳ μέχρι μὲν κατ’ οὖρον ὁ πλοῦς εἴη τοῖς φίλοις, ἀγανακτοῦσιν εἰ μὴ ἐπ’ ἴσης κοινωνήσουσιν τῶν ἡδέων, εἰ δέ τι καὶ μικρὸν ἀντιπνεύσειεν αὐτοῖς, οἴχονται μόνους τοῖς κινδύνοις ἀπολιπόντες. καὶ γὰρ οὖν καὶ τόδε ὅπως εἰδῇς, οὐδὲν Σκύθαι φιλίας μεῖζον οἴονται εἶναι, οὐδὲ ἔστιν ἐφ’ ὅτῳ ἄν τις Σκύθης μᾶλλον σεμνύναιτο ἢ ἐπὶ τῷ συμπονῆσαι φίλῳ ἀνδρὶ καὶ κοινωνῆσαι τῶν δεινῶν, ὥσπερ οὐδὲν ὄνειδος μεῖζον παρ’ ἡμῖν τοῦ προδότην φιλίας γεγενῆσθαι δοκεῖν. διὰ ταῦτα Ὀρέστην καὶ Πυλάδην τιμῶμεν, ἀρίστους γενομένους τὰ Σκυθῶν ἀγαθὰ καὶ ἐν φιλίᾳ διενεγκόντας, ὃ πρῶτον ἡμεῖς ἁπάντων θαυμάζομεν, καὶ τοὔνομα ἐπὶ τούτοις αὐτῶν ἐθέμεθα Κοράκους καλεῖσθαι· τοῦτο δέ ἐστιν ἐν τῇ ἡμετέρᾳ φωνῇ ὥσπερ ἂν εἴ τις λέγοι “φίλιοι δαίμονες.”", "st": "44.7"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ὦ Τόξαρι, οὐ μόνον ἄρα τοξεύειν ἀγαθοὶ ἦσαν Σκύθαι καὶ τὰ πολεμικὰ τῶν ἄλλων ἀμείνους, ἀλλὰ καὶ ῥῆσιν εἰπεῖν ἁπάντων πιθανώτατοι. ἐμοὶ γοῦν τέως ἄλλως γιγνώσκοντι ἤδη καὶ αὐτῷ δίκαια ποιεῖν δοκεῖτε οὕτως Ὀρέστην καὶ Πυλάδην ἐκθειάσαντες. ἐλελήθεις δέ με, ὦ γενναῖε, καὶ γραφεὺς ἀγαθὸς ὤν. πάνυ γοῦν ἐναργῶς ἐπέδειξας ἡμῖν τὰς ἐν τῷ Ὀρεστείῳ εἰκόνας καὶ τὴν μάχην τῶν ἀνδρῶν καὶ τὰ ὑπὲρ ἀλλήλων τραύματα. πλὴν ἀλλ’ οὐκ ᾠήθην ἂν οὕτω ποτὲ περισπούδαστον εἶναι φιλίαν ἐν Σκύθαις· ἅτε γὰρ ἀξένους καὶ ἀγρίους ὄντας αὐτοὺς ἔχθρᾳ μὲν ἀεὶ συνεῖναι καὶ ὀργῇ καὶ θυμῷ, φιλίαν δὲ μηδὲ πρὸς τοὺς οἰκειοτάτους ἐπαναιρεῖσθαι, τεκμαιρόμενος τοῖς τε ἄλλοις ἃ περὶ αὐτῶν ἀκούομεν καὶ ὅτι κατεσθίουσι τοὺς πατέρας ἀποθανόντας.", "st": "44.8"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> εἰ μὲν καὶ τὰ ἄλλα ἡμεῖς τῶν Ἑλλήνων καὶ δικαιότεροι τὰ πρὸς τοὺς γονέας καὶ ὁσιώτεροί ἐσμεν, οὐκ ἂν ἐν τῷ παρόντι φιλοτιμηθείην πρὸς σέ. ὅτι δὲ οἱ φίλοι οἱ Σκύθαι πολὺ πιστότεροι τῶν Ἑλλήνων φίλων εἰσὶν καὶ ὅτι πλείων φιλίας λόγος παρ’ ἡμῖν ἢ παρ’ ὑμῖν, ῥᾴδιον ἐπιδεῖξαι· καὶ πρὸς θεῶν τῶν Ἑλλήνων μὴ πρὸς ἀχθηδόνα μου ἀκούσῃς ἢν εἴπω τι ὧν κατανενόηκα πολὺν ἤδη χρόνον ὑμῖν συγγινόμενος.", "st": "44.9"}, {"sp": "N", "t": "ὑμεῖς γάρ μοι δοκεῖτε τοὺς μὲν περὶ φιλίας λόγους ἄμεινον ἄλλων ἂν εἰπεῖν δύνασθαι, τἄργα δὲ αὐτῆς οὐ μόνον οὐ κατ’ ἀξίαν τῶν λόγων ἐκμελετᾶν, ἀλλ’ ἀπόχρη ὑμῖν ἐπαινέσαι τε αὐτὴν καὶ δεῖξαι ἡλίκον ἀγαθόν ἐστιν· ἐν δὲ ταῖς χρείαις προδόντες τοὺς λόγους δραπετεύετε οὐκ οἶδ’ ὅπως ἐκ μέσων τῶν ἔργων. καὶ ὁπόταν ὑμῖν οἱ τραγῳδοὶ τὰς τοιαύτας φιλίας ἐπὶ τὴν σκηνὴν ἀναβιβάσαντες δεικνύωσιν ἐπαινεῖτε καὶ ἐπικροτεῖτε καὶ κινδυνεύουσιν αὐτοῖς ὑπὲρ ἀλλήλων οἱ πολλοὶ καὶ ἐπιδακρύετε, αὐτοὶ δὲ οὐδὲν ἄξιον ἐπαίνου ὑπὲρ τῶν φίλων παρέχεσθαι τολμᾶτε, ἀλλ’ ἤν του φίλος δεηθεὶς τύχῃ, αὐτίκα μάλα ὥσπερ τὰ ὀνείρατα οἴχονται ὑμῖν ἐκποδὼν ἀποπτάμεναι αἱ πολλαὶ ἐκεῖναι τραγῳδίαι, τοῖς κενοῖς τούτοις καὶ κωφοῖς προσωπείοις ἐοικότας ὑμᾶς ἀπολιποῦσαι, ἃ διηρμένα τὸ στόμα καὶ παμμέγεθες κεχηνότα οὐδὲ τὸ σμικρότατον φθέγγεται. ἡμεῖς δὲ ἔμπαλιν· ὅσῳ γὰρ δὴ λειπόμεθα ἐν τοῖς περὶ φιλίας λόγοις, τοσοῦτον ἐν τοῖς ἔργοις αὐτῆς πλεονεκτοῦμεν.", "st": "44.9"}, {"sp": "N", "t": "Εἴ δ’ οὖν δοκεῖ, οὕτω νῦν ποιῶμεν. τοὺς μὲν παλαιοὺς φίλους ἀτρεμεῖν ἐάσωμεν, εἴ τινας ἢ ἡμεῖς ἢ ὑμεῖς τῶν πάλαι καταριθμεῖν ἔχομεν, ἐπεὶ κατά γε τοῦτο πλεονεκτοῖτε ἄν, πολλοὺς καὶ ἀξιοπίστους μάρτυρας τοὺς ποιητὰς παρεχόμενοι τὴν Ἀχιλλέως καὶ Πατρόκλου φιλίαν καὶ τὴν Θησέως καὶ Πειρίθου καὶ τῶν ἄλλων ἑταιρείαν ἐν καλλίστοις ἔπεσι καὶ μέτροις ῥαψῳδοῦντας· ὀλίγους δέ τινας προχειρισάμενοι τῶν καθ’ ἡμᾶς αὐτοὺς καὶ τὰ ἔργα αὐτῶν διηγησάμενοι, ἐγὼ μὲν τὰ Σκυθικά, σὺ δὲ τὰ Ἑλληνικά, ὁπότερος ἂν ἐν τούτοις κρατῇ καὶ ἀμείνους παράσχηται τοὺς φίλους, αὐτός τε νενικηκὼς ἔσται καὶ τὴν αὑτοῦ ἀνακηρύξει, κάλλιστον ἀγῶνα καὶ σεμνότατον ἀγωνισάμενος. ὡς ἔγωγε πολὺ ἥδιον ἄν μοι δοκῶ μονομαχῶν ἡττηθεὶς ἀποτμηθῆναι τὴν δεξιάν, ὅπερ ἥττης Σκυθικῆς ἐπιτίμιόν ἐστιν, ἢ χείρων ἄλλου κατὰ φιλίαν κεκρίσθαι, καὶ ταῦτα Ἕλληνος, Σκύθης αὐτὸς ὤν.", "st": "44.10"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ἔστιν μέν, ὦ Τόξαρι, οὐ φαῦλον τὸ ἔργον ἀνδρὶ οἵῳ σοὶ πολεμιστῇ μονομαχῆσαι, πάνυ εὐστόχους καὶ τεθηγμένους παρεσκευασμένῳ τοὺς λόγους. οὐ μὴν ἀγεννῶς γε οὕτως καταπροδοὺς ἐν βραχεῖ τὸ Ἑλληνικὸν ἅπαν ὑποχωρήσομαί σοι· καὶ γὰρ ἂν εἴη πάνδεινον ὑπὸ δυοῖν μὲν ἐκείνοιν ἡττηθῆναι τοσούτους τῶν Σκυθῶν ὁπόσους οἵ τε μῦθοι δηλοῦσι καὶ αἱ ὑμέτεραι παλαιαὶ γραφαί, ἃς μικρῷ πρόσθεν εὖ μάλα ἐξετραγῴδησας, Ἕλληνας δὲ πάντας, τοσαῦτα ἔθνη καὶ τοσαύτας πόλεις, ἐρήμην ὑπὸ σοῦ ἁλῶναι. εἰ γὰρ τοῦτο γένοιτο, οὐ τὴν δεξιὰν ὥσπερ ὑμεῖς ἀλλὰ τὴν γλῶτταν ἀποτμηθῆναι καλόν. πότερον δὲ ὡρίσθαι χρὴ τὸν ἀριθμὸν ἡμῖν τῶν φιλικῶν τούτων πράξεων, ἢ ὁπόσῳ ἄν τις πλείους ἔχῃ λέγειν, τοσούτῳ εὐπορώτερος ἂν δόξειεν πρὸς τὴν νίκην;", "st": "44.11"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> οὐδαμῶς, ἀλλ’ ὡρίσθω μὴ ἐν τῷ πλήθει αὐτῶν τὸ κράτος, ἀλλ’ εἰ ἀμείνους καὶ τομώτεραι φαίνοιντο αἱ σαὶ τῶν ἐμῶν ἴσαι τὸν ἀριθμὸν οὖσαι, καιριώτερα δῆλον ὅτι ἐργάσονταί μοι τραύματα καὶ θᾶττον ἐνδώσω πρὸς τὰς πληγάς.", "st": "44.11"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> εὖ λέγεις, καὶ ὡρίσθωσαν ὁπόσαι ἱκαναί. πέντε ἔμοιγε δοκοῦσιν ἑκατέρῳ.", "st": "44.11"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> κἀμοὶ δοκεῖ. πρότερος δὲ λέγε, ἀλλ’ ἐπομοσάμενος ἦ μὴν ἀληθῆ ἐρεῖν· ἄλλως γὰρ ἀναπλάττειν τὰ τοιαῦτα οὐ πάνυ χαλεπὸν καὶ ὁ ἔλεγχος ἀφανής. εἰ δὲ ὀμόσειας, οὐχ ὅσιον ἀπιστεῖν.", "st": "44.11"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ὀμούμεθα, εἴ τι καὶ ὅρκου δεῖν νομίζεις. τίς δέ σοι τῶν ἡμετέρων θεῶν ἄρ’ ἱκανός; ὁ Φίλιος;", "st": "44.11"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> καὶ μάλα· ἐγὼ δὲ τὸν ἐπιχώριον ὀμοῦμαί σοι ἐν τῷ ἐμαυτοῦ λόγῳ.", "st": "44.11"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ἴστω τοίνυν ὁ Ζεὺς ὁ Φίλιος, ἦ μὴν ὁπόσα ἂν λέγω πρὸς σὲ ἢ αὐτὸς εἰδὼς ἢ παρ’ ἄλλων ὁπόσον οἷόν τε ἦν δι’ ἀκριβείας ἐκπυνθανόμενος ἐρεῖν, μηδὲν παρ’ ἐμαυτοῦ ἐπιτραγῳδῶν. καὶ πρώτην γέ σοι τὴν Ἀγαθοκλέους καὶ Δεινίου φιλίαν διηγήσομαι, ἀοίδιμον ἐν τοῖς Ἴωσι γενομένην.", "st": "44.12"}, {"sp": "N", "t": "Ἀγαθοκλῆς γὰρ οὗτος ὁ Σάμιος οὐ πρὸ πολλοῦ ἐγένετο, ἄριστος μὲν πρὸς φιλίαν, ὡς ἔδειξεν, τὰ ἄλλα δὲ οὐδὲν ἀμείνων Σαμίων τῶν πολλῶν οὔτε ἐς τὸ γένος οὔτε ἐς τὴν ἄλλην περιουσίαν. Δεινίᾳ δὲ τῷ Λύσωνος Ἐφεσίῳ φίλος ἐκ παίδων ἦν. ὁ δὲ Δεινίας ἐπλούτει ἄρα εἰς ὑπερβολήν, καὶ ὥσπερ εἰκὸς νεόπλουτον ὄντα, πολλοὺς καὶ ἄλλους εἶχε περὶ ἑαυτόν, ἱκανοὺς μὲν συμπιεῖν καὶ πρὸς ἡδονὴν συνεῖναι, φιλίας δὲ πλεῖστον ὅσον ἀποδέοντας.", "st": "44.12"}, {"sp": "N", "t": "τέως μὲν οὖν ἐν τούτοις καὶ ὁ Ἀγαθοκλῆς ἐξητάζετο, καὶ συνῆν καὶ συνέπινεν αὐτοῖς οὐ πάνυ χαίρων τῇ τοιαύτῃ διατριβῇ, καὶ ὁ Δεινίας οὐδὲν αὐτὸν ἐντιμότερον εἶχεν τῶν κολάκων. τελευταῖον δὲ καὶ προσέκρουε τὰ πολλὰ ἐπιτιμῶν, καὶ φορτικὸς ἐδόκει ὑπομιμνήσκων ἀεὶ τῶν προγόνων καὶ φυλάττειν παραγγέλλων ἃ μετὰ πολλῶν καμάτων ὁ πατὴρ αὐτῷ κτησάμενος κατέλιπεν, ὥστε διὰ ταῦτα οὐδὲ ἐπὶ τοὺς κώμους ἀπῆγεν ἔτι αὐτόν, ἀλλὰ μόνος μετ’ ἐκείνων ἐκώμαζε, λανθάνειν πειρώμενος τὸν Ἀγαθοκλέα.", "st": "44.12"}, {"sp": "N", "t": "καὶ δή ποτε ὑπὸ τῶν κολάκων ἐκείνων ὁ ἄθλιος ἀναπείθεται ὡς ἐρῴη αὐτοῦ Χαρίκλεια Δημώνακτος γυνή, ἀνδρὸς ἐπιφανοῦς καὶ πρώτου Ἐφεσίων τὰ πολιτικά· καὶ γραμματεῖά τε εἰσεφοίτα παρὰ τῆς γυναικὸς αὐτῷ καὶ στέφανοι ἡμιμάραντοι καὶ μῆλά τινα ἀποδεδηγμένα καὶ ἄλλα ὁπόσα αἱ μαστροποὶ ἐπὶ τοῖς νέοις μηχανῶνται, κατὰ μικρὸν αὐτοῖς ἐπιτεχνώμεναι τοὺς ἔρωτας καὶ ἀναφλέγουσαι τὸ πρῶτον ἐρᾶσθαι νομίζοντας (ἐπαγωγότατον γὰρ τοῦτό γε, καὶ μάλιστα τοῖς καλοῖς εἶναι οἰομένοις), ἄχρι ἂν λάθωσιν εἰς τὰ δίκτυα ἐμπεσόντες.", "st": "44.13"}, {"sp": "N", "t": "ἡ Χαρίκλεια δὲ ἦν ἀστεῖον μέν τι γύναιον, ἑταιρικὸν δὲ ἐκτόπως καὶ τοῦ προστυχόντος ἀεί, καὶ εἰ πάνυ ἐπ’ ὀλίγῳ ἐθελήσειέ τις· καὶ εἰ προσίδοι τις μόνον, εὐθὺς ἐπένευε, καὶ δέος οὐδὲν ἦν μή πη ἀντείποι Χαρίκλεια. δεινὴ δὲ καὶ τὰ ἄλλα, καὶ τεχνῖτις παρ’ ἥντινα βούλει τῶν ἑταιρῶν ἐπισπάσασθαι ἐραστὴν καὶ ἀμφίβολον ἔτι ὄντα ὅλον ὑποποιήσασθαι καὶ ἐνεχόμενον ἤδη ἐπιτεῖναι καὶ προσεκκαῦσαι ἄρτι μὲν ὀργῇ, ἄρτι δὲ κολακείᾳ, καὶ μετὰ μικρὸν ὑπεροψίᾳ καὶ τῷ πρὸς ἕτερον ἀποκλίνειν δοκεῖν, καὶ ὅλη συνεκεκρότητο ἁπανταχόθεν ἡ γυνὴ καὶ πολλὰ μηχανήματα παρεσκεύαστο κατὰ τῶν ἐραστῶν.", "st": "44.13"}, {"sp": "N", "t": "ταύτην οὖν τότε οἱ Δεινίου κόλακες παραλαμβάνουσιν ἐπὶ τὸ μειράκιον, καὶ τὰ πολλὰ ὑπεκωμῴδουν, συνωθοῦντες αὐτὸν εἰς τὸν ἔρωτα τῆς Χαρικλείας. ἡ δὲ πολλοὺς ἤδη νέους ἐκτραχηλίσασα καὶ μυρίους ἔρωτας ὑποκριναμένη καὶ οἴκους πολυταλάντους ἀνατρέψασα, ποικίλον τι καὶ πολυγύμναστον κακόν, παραλαβοῦσα εἰς τὰς χεῖρας ἁπλοϊκὸν καὶ ἄπειρον τῶν τοιούτων μηχανημάτων νεανίσκον οὐκ ἀνῆκεν ἐκ τῶν ὀνύχων, ἀλλὰ περιέχουσα πανταχόθεν καὶ διαπείρασα, ὅτε ἤδη παντάπασιν ἐκράτει, αὐτή τε ἀπώλετο ὑπὸ τῆς ἄγρας καὶ τῷ κακοδαίμονι Δεινίᾳ μυρίων κακῶν αἰτία ἐγένετο.", "st": "44.14"}, {"sp": "N", "t": "τὸ μὲν γὰρ πρῶτον εὐθὺς ἐκεῖνα ἐπ’ αὐτὸν καθίει τὰ γραμματεῖα, συνεχῶς πεμπομένη τὴν ἅβραν, ὡς ἐδάκρυσε καὶ ἐπηγρύπνησε καὶ τέλος ὡς ἀπάγξει ἑαυτὴν ἡ ἀθλία ὑπὸ τοῦ ἔρωτος, ἕως δὴ ὁ μακάριος ἐπείσθη καλὸς εἶναι καὶ ταῖς Ἐφεσίων γυναιξὶ περιπόθητος, καί που συνηνέχθη πολλὰ ἱκετευθείς.", "st": "44.14"}, {"sp": "N", "t": "τὸ ἐντεῦθεν ἤδη ῥᾷον, ὡς τὸ εἰκός, ἁλώσεσθαι ἔμελλεν ὑπὸ γυναικὸς καλῆς καὶ πρὸς ἡδονήν τε ὁμιλῆσαι ἐπισταμένης καὶ ἐν καιρῷ δακρῦσαι καὶ μεταξὺ τῶν λόγων ἐλεεινῶς ὑποστενάξαι καὶ ἀπιόντος ἤδη λαβέσθαι καὶ εἰσελθόντι προσδραμεῖν καὶ καλλωπίζεσθαι ὡς ἂν μάλιστα ἀρέσειε, καί που καὶ ᾆσαι καὶ κιθαρίσαι. οἷς ἅπασι κατὰ τοῦ Δεινίου ἐκέχρητο· καὶ ἐπεὶ ᾔσθετο πονηρῶς ἔχοντα καὶ διάβροχον ἤδη τῷ ἔρωτι καὶ τακερὸν γεγενημένον, ἄλλο ἐπὶ τούτοις ἐπενόει καὶ τὸν ἄθλιον ἀπώλλυε· κύειν τε γὰρ ἐξ αὐτοῦ σκήπτεται — ἱκανὸν δὲ καὶ τοῦτο βλᾶκα ἐραστὴν προσεκπυρῶσαι — καὶ οὐκέτι ἐφοίτα πρὸς αὐτόν, φυλάττεσθαι ὑπὸ τἀνδρὸς λέγουσα πεπυσμένου τὸν ἔρωτα.", "st": "44.15"}, {"sp": "N", "t": "ὁ δ’ οὐκέτι οἷός τε ἦν φέρειν τὸ πρᾶγμα, οὐδὲ ἠνείχετο μὴ ὁρῶν αὐτήν, ἀλλὰ ἐδάκρυε καὶ τοὺς κόλακας εἰσέπεμπεν καὶ τοὔνομα τῆς Χαρικλείας ἐπεβοᾶτο καὶ τὴν εἰκόνα περιβαλὼν αὐτῆς — ἐπεποίητο δὲ λίθου λευκοῦ — ἐκώκυε, καὶ τέλος καταβαλὼν ἑαυτὸν εἰς τοὔδαφος ἐκυλίνδετο καὶ λύττα ἦν ἀκριβὴς τὸ πρᾶγμα. τὰ μὲν γὰρ δῶρα οὐ κατὰ μῆλα καὶ στεφάνους ἀντεδίδοτο αὐτῇ, ἀλλὰ συνοικίαι ὅλαι καὶ ἀγροὶ καὶ θεράπαιναι καὶ ἐσθῆτες εὐανθεῖς καὶ χρυσὸν ὁπόσον ἐθελήσειε.", "st": "44.15"}, {"sp": "N", "t": "Καὶ τί γάρ; ἐν βραχεῖ ὁ Λύσωνος οἶκος, ὀνομαστότατος τῶν ἐν Ἰωνίᾳ γενόμενος, ἐξήντλητο ἤδη καὶ ἐξεκεκένωτο.", "st": "44.15"}, {"sp": "N", "t": "εἶτα, ὡς ἤδη αὖος ἦν, ἀπολιποῦσα αὐτὸν ἄλλον τινὰ Κρῆτα νεανίσκον τῶν ὑποχρύσων ἐθήρα καὶ μετέβαινεν ἐπ’ ἐκεῖνον καὶ ἤρα ἤδη αὐτοῦ, κἀκεῖνος ἐπίστευεν.", "st": "44.16"}, {"sp": "N", "t": "ἀμελούμενος οὖν ὁ Δεινίας οὐχ ὑπὸ τῆς Χαρικλείας μόνον ἀλλὰ καὶ ὑπὸ τῶν κολάκων (κἀκεῖνοι γὰρ ἐπὶ τὸν Κρῆτα ἤδη τὸν ἐρώμενον μετεληλύθεσαν) ἔρχεται παρὰ τὸν Ἀγαθοκλέα καὶ πάλαι εἰδότα ὡς ἔχοι πονηρῶς τὰ πράγματα αὐτῷ, καὶ αἰδούμενος τὸ πρῶτον ὅμως διηγεῖτο πάντα — τὸν ἔρωτα, τὴν ἀπορίαν, τὴν ὑπεροψίαν τῆς γυναικός, τὸν ἀντεραστὴν τὸν Κρῆτα, καὶ τέλος ὡς οὐ βιώσεται μὴ οὐχὶ συνὼν τῇ Χαρικλείᾳ. ὁ δὲ ἄκαιρον εἶναι νομίσας ἐν τούτῳ ἀπομνημονεύειν τῷ Δεινίᾳ διότι οὐ προσίετο μόνον αὐτὸν τῶν φίλων ἀλλὰ τοὺς κόλακας αὐτοῦ προετίμα τότε, ἣν μόνον εἶχεν πατρῴαν οἰκίαν ἐν Σάμῳ ἀπεμπολήσας ἧκεν αὐτῷ τὴν τιμὴν κομίζων, τρία τάλαντα.", "st": "44.16"}, {"sp": "N", "t": "λαβὼν δὲ ὁ Δεινίας οὐκ ἀφανὴς εὐθὺς ἦν τῇ Χαρικλείᾳ καλός ποθεν αὖθις γεγενημένος, καὶ αὖθις ἡ ἅβρα καὶ τὰ γραμματεῖα, καὶ μέμψις ὅτι μὴ πολλοῦ χρόνου ἀφίκετο, καὶ οἱ κόλακες συνέθεον ἐπικαλαμησόμενοι, ὁρῶντες ἐδώδιμον ἔτι ὄντα τὸν Δεινίαν.", "st": "44.16"}, {"sp": "N", "t": "ὡς δὲ ὑπέσχετο ἥξειν παρ’ αὐτὴν καὶ ἧκε περὶ πρῶτον ὕπνον καὶ ἔνδον ἦν, ὁ Δημῶναξ, ὁ τῆς Χαρικλείας ἀνήρ, εἴτε ἄλλως αἰσθόμενος εἴτε καὶ ἀπὸ συνθήματος τῆς γυναικός (ἄμφω γὰρ λέγεται) ἐπαναστὰς ὥσπερ ἐκ λόχου τήν τε αὔλειον ἀποκλείειν ἐκέλευεν καὶ συλλαμβάνειν τὸν Δεινίαν, πῦρ καὶ μάστιγας ἀπειλῶν καὶ ξίφος ὡς ἐπὶ μοιχὸν σπασάμενος.", "st": "44.17"}, {"sp": "N", "t": "ὁ δὲ συνιδὼν οὗ κακῶν ἦν, μοχλόν τινα πλησίον κείμενον ἁρπάσας αὐτόν τε ἀποκτείνει τὸν Δημώνακτα, πατάξας εἰς τὸν κρόταφον, καὶ τὴν Χαρίκλειαν, οὐ μιᾷ πληγῇ ταύτην, ἀλλὰ καὶ τῷ μοχλῷ πολλάκις καὶ τῷ ξίφει τοῦ Δημώνακτος ὕστερον. οἱ δ’ οἰκέται τέως μὲν ἑστήκεσαν ἄφωνοι, τῷ παραδόξῳ τοῦ πράγματος ἐκπεπληγμένοι, εἶτα πειρώμενοι συλλαμβάνειν, ὡς καὶ αὐτοῖς ἐπῄει μετὰ τοῦ ξίφους, ἐκεῖνοι μὲν ἔφευγον, ὁ Δεινίας δὲ ὑπεξέρχεται τηλικοῦτον ἔργον εἰργασμένος.", "st": "44.17"}, {"sp": "N", "t": "καὶ τὸ μέχρι τῆς ἕω παρὰ τῷ Ἀγαθοκλεῖ διέτριβεν, ἀναλογιζόμενοι τὰ πεπραγμένα καὶ περὶ τῶν μελλόντων ὅ τι ἀποβήσεται σκοποῦντες· ἕωθεν δὲ οἱ στρατηγοὶ παρῆσαν — ἤδη γὰρ τὸ πρᾶγμα διεβεβόητο — καὶ συλλαβόντες τὸν Δεινίαν, οὐδ’ αὐτὸν ἔξαρνον ὄντα μὴ οὐχὶ πεφονευκέναι, ἀπάγουσι παρὰ τὸν ἁρμοστὴν ὃς ἥρμοζε τὴν Ἀσίαν τότε. ὁ δὲ βασιλεῖ τῷ μεγάλῳ ἀναπέμπει αὐτόν· καὶ μετ’ οὐ πολὺ κατεπέμφθη ὁ Δεινίας εἰς Γύαρον νῆσον τῶν Κυκλάδων, ἐν ταύτῃ φεύγειν εἰς ἀεὶ τεταγμένος ὑπὸ βασιλέως.", "st": "44.17"}, {"sp": "N", "t": "ὁ δὲ Ἀγαθοκλῆς καὶ τἄλλα μὲν συνῆν καὶ συναπῆρεν εἰς τὴν Ἰταλίαν καὶ συνεισῆλθεν εἰς τὸ δικαστήριον μόνος τῶν φίλων καὶ πρὸς οὐδὲν ἐνεδέησεν. ἐπεὶ δὲ ἤδη ἔφευγεν ὁ Δεινίας, οὐδὲ τότε ἀπελείφθη τοῦ ἑταίρου, καταδικάσας δὲ αὐτὸς αὑτοῦ διέτριβεν ἐν Γυάρῳ καὶ συνέφευγεν αὐτῷ, καὶ ἐπειδὴ παντάπασιν ἠπόρουν τῶν ἀναγκαίων, παραδοὺς ἑαυτὸν τοῖς πορφυρεῦσι συγκατεδύετο καὶ τὸ γινόμενον ἐκ τούτου ἀποφέρων ἔτρεφε τὸν Δεινίαν· καὶ νοσήσαντά τε ἐπὶ μήκιστον ἐθεράπευσε καὶ ἀποθανόντος οὐκέτι ἐπανελθεῖν εἰς τὴν ἑαυτοῦ ἠθέλησεν, ἀλλ’ αὐτοῦ ἐν τῇ νήσῳ ἔμεινεν αἰσχυνόμενος καὶ τεθνεῶτα ἀπολιπεῖν τὸν φίλον.", "st": "44.18"}, {"sp": "N", "t": "τοῦτό σοι ἔργον φίλου Ἕλληνος οὐ πρὸ πολλοῦ γενόμενον· ἔτη γὰρ οὐκ οἶδα εἰ πέντε ἤδη διελήλυθεν ἀφ’ οὗ Ἀγαθοκλῆς ἐν Γυάρῳ ἀπέθανεν.", "st": "44.18"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> καὶ εἴθε γε, ὦ Μνήσιππε, ἀνώμοτος ὢν ταῦτα ἔλεγες, ἵνα καὶ ἀπιστεῖν ἂν ἐδυνάμην αὐτοῖς· οὕτω Σκυθικόν τινα φίλον τὸν Ἀγαθοκλέα τοῦτον διηγήσω. πλὴν οὐ δέδια μή τινα καὶ ἄλλον ὅμοιον εἴπῃς αὐτῷ.", "st": "44.18"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ἄκουε τοίνυν καὶ ἄλλον, ὦ Τόξαρι, Εὐθύδικον τὸν Χαλκιδέα. διηγεῖτο δέ μοι περὶ αὐτοῦ Σιμύλος ὁ ναύκληρος ὁ Μεγαρικός, ἐπομοσάμενος ἦ μὴν αὐτὸς ἑωρακέναι τὸ ἔργον. πλεῖν μὲν γὰρ ἔφη ἐξ Ἰταλίας Ἀθήναζε περὶ δύσιν Πλειάδος συλλογιμαίους τινὰς ἀνθρώπους κομίζων, ἐν δὲ τούτοις εἶναι τὸν Εὐθύδικον καὶ μετ’ αὐτοῦ Δάμωνα, Χαλκιδέα καὶ τοῦτον, ἑταῖρον αὐτοῦ· ἡλικιώτας δὲ εἶναι, τὸν μὲν Εὐθύδικον ἐρρωμένον καὶ καρτερόν, τὸν δὲ Δάμωνα ὕπωχρον καὶ ἀσθενικόν, ἄρτι ἐκ νόσου μακρᾶς, ὡς ἐδόκει, ἀνιστάμενον.", "st": "44.19"}, {"sp": "N", "t": "Ἄχρι μὲν οὖν Σικελίας εὐτυχῶς διαπλεῦσαι ἔφη ὁ Σιμύλος σφᾶς· ἐπεὶ δὲ τὸν πορθμὸν διαπεράσαντες ἐν αὐτῷ ἤδη τῷ Ἰονίῳ ἔπλεον, χειμῶνα μέγιστον ἐπιπεσεῖν αὐτοῖς. καὶ τὰ μὲν πολλὰ τί ἄν τις λέγοι, τρικυμίας τινὰς καὶ στροβίλους καὶ χαλάζας καὶ ἄλλα ὅσα χειμῶνος κακά; ἐπεὶ δὲ ἤδη σφᾶς κατὰ τὴν Ζάκυνθον εἶναι ἀπὸ ψιλῆς τῆς κεραίας πλέοντας, ἔτι καὶ σπείρας τινὰς ἐπισυρομένους, ὡς τὸ ῥόθιον ἐπιδέχεσθαι τῆς ὁρμῆς, περὶ μέσας νύκτας οἷον ἐν τοσούτῳ σάλῳ ναυτιάσαντα τὸν Δάμωνα ἐμεῖν ἐκκεκυφότα ἐς τὴν θάλασσαν· εἶτα, οἶμαι, τῆς νεὼς βιαιότερον ἐς ὃ ἐκεκύφει μέρος ἐπικλιθείσης καὶ τοῦ κύματος συναπώσαντος, ἐκπεσεῖν αὐτὸν ἐπὶ τὴν κεφαλὴν ἐς τὸ πέλαγος, οὐδὲ γυμνὸν τὸν ἄθλιον, ὡς ἂν καὶ ῥᾷον δύνασθαι νεῖν. εὐθὺς οὖν βοᾶν πνιγόμενον καὶ μόγις ἑαυτὸν ὑπερέχοντα τοῦ κλύδωνος.", "st": "44.19"}, {"sp": "N", "t": "τὸν δὲ Εὐθύδικον, ὡς ἤκουσε — τυχεῖν δὲ γυμνὸν ἐν τῇ εὐνῇ ὄντα — ῥῖψαι ἑαυτὸν εἰς τὴν θάλασσαν καὶ καταλαβόντα τὸν Δάμωνα ἤδη ἀπαγορεύοντα — φαίνεσθαι γὰρ ἐπὶ πολὺ ταῦτα τῆς σελήνης καταλαμπούσης — συμπαρανήχεσθαι καὶ συγκουφίζειν. σφᾶς δὲ ἐπιθυμεῖν μὲν αὐτοῖς βοηθεῖν καὶ ἐλεεῖν τὴν συμφορὰν τῶν ἀνδρῶν, μὴ δύνασθαι δέ, μεγάλῳ τῷ πνεύματι ἐλαυνομένους. πλὴν ἐκεῖνά γε ποιῆσαι, φελλούς τε γὰρ πολλοὺς ἀφεῖναι αὐτοῖς καὶ τῶν κοντῶν τινας, ὡς ἐπὶ τούτων ἀπονήξαιντο, εἴ τινι αὐτῶν περιτύχοιεν, καὶ τέλος καὶ τὴν ἀποβάθραν αὐτὴν οὐ μικρὰν οὖσαν.", "st": "44.20"}, {"sp": "N", "t": "Ἐννόησον τοίνυν πρὸς θεῶν ἥντινα ἄν τις ἄλλην ἐπίδειξιν ἐπιδείξαιτο εὐνοίας βεβαιοτέραν πρὸς ἄνδρα φίλον ἐν νυκτὶ ἐκπεσόντα ἐς πέλαγος οὕτως ἠγριωμένον ἢ κοινωνήσας τοῦ θανάτου; καί μοι ἐπ’ ὀφθαλμῶν λαβὲ τὴν ἐπανάστασιν τῶν κυμάτων, τὸν ἦχον τοῦ ὕδατος ἐπικλωμένου, τὸν ἀφρὸν περιζέοντα, τὴν νύκτα καὶ τὴν ἀπόγνωσιν· εἶτα ἀποπνιγόμενον ἐκεῖνον καὶ μόγις ἀνακύπτοντα καὶ τὰς χεῖρας ὀρέγοντα τῷ ἑταίρῳ, τὸν δὲ ἐπιπηδῶντα εὐθὺς καὶ συννέοντα καὶ δεδιότα μὴ προαπόληται αὐτοῦ ὁ Δάμων. οὕτω γὰρ ἂν μάθοις ὡς οὐκ ἀγεννῆ σοι καὶ τοῦτον φίλον τὸν Εὐθύδικον διηγησάμην.", "st": "44.20"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> πότερον δὲ ἀπώλοντο, ὦ Μνήσιππε, οἱ ἄνδρες, ἤ τις αὐτοῖς ἐκ παραλόγου σωτηρία ἐγένετο; ὡς ἔγωγε οὐ μετρίως δέδοικα ὑπὲρ αὐτῶν.", "st": "44.21"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> θάρρει, ὦ Τόξαρι, ἐσώθησαν, καὶ ἔτι καὶ νῦν εἰσιν Ἀθήνησιν ἄμφω φιλοσοφοῦντες. ὁ μὲν γὰρ Σιμύλος ταῦτα μόνα εἶχε λέγειν ἅ ποτε εἶδε τῆς νυκτός, τὸν μὲν ἐκπίπτοντα, τὸν δὲ ἐπιπηδῶντα, καὶ νηχομένους ἐς ὅσον ἐν νυκτὶ καθορᾶν ἐδύνατο. τὰ δὲ ἀπὸ τούτου οἱ ἀμφὶ τὸν Εὐθύδικον αὐτοὶ διηγοῦνται. τὸ μὲν γὰρ πρῶτον φελλοῖς τισι περιπεσόντας ἀνέχειν ἐπὶ τούτων ἑαυτοὺς καὶ ἀπονήχεσθαι πονηρῶς, ὕστερον δὲ τὴν ἀποβάθραν ἰδόντας ἤδη πρὸς ἕω προσνήξασθαί τε αὐτῇ καὶ τὸ λοιπὸν ἐπιβάντας εὐμαρῶς προσενεχθῆναι τῇ Ζακύνθῳ.", "st": "44.21"}, {"sp": "N", "t": "μετὰ δὲ τούτους οὐ φαύλους ὄντας, ὡς ἔγωγ’ ἂν εἴποιμι, ἄκουσον ἤδη τρίτον ἄλλον οὐδέν τι χείρονα αὐτῶν.", "st": "44.22"}, {"sp": "N", "t": "Εὐδαμίδας Κορίνθιος Ἀρεταίῳ τῷ Κορινθίῳ καὶ Χαριξένῳ τῷ Σικυωνίῳ φίλοις ἐκέχρητο εὐπόροις οὖσι πενέστατος αὐτὸς ὤν· ἐπεὶ δὲ ἀπέθνησκε, διαθήκας ἀπέλιπε τοῖς μὲν ἄλλοις ἴσως γελοίους, σοὶ δὲ οὐκ οἶδα εἰ τοιαῦται δόξουσιν ἀνδρὶ ἀγαθῷ καὶ φιλίαν τιμῶντι καὶ περὶ τῶν ἐν αὐτῇ πρωτείων ἁμιλλωμένῳ· ἐγέγραπτο γὰρ ἐν αὐταῖς, “ἀπολείπω Ἀρεταίῳ μὲν τὴν μητέρα μου τρέφειν καὶ γηροκομεῖν, Χαριξένῳ δὲ τὴν θυγατέρα μου ἐκδοῦναι μετὰ προικὸς ὁπόσην ἂν πλείστην ἐπιδοῦναι παρ’ αὑτοῦ δύνηται —” ἦν δὲ αὐτῷ καὶ μήτηρ πρεσβῦτις καὶ θυγάτριον ὡραῖον ἤδη γάμου — “ἢν δέ τι ἅτερος αὐτῶν ἐν τοσούτῳ πάθῃ, τὴν ἐκείνου μερίδα,” φησίν, “ἐχέτω ὁ ἕτερος.” τούτων ἀναγνωσθεισῶν τῶν διαθηκῶν οἱ τὴν πενίαν μὲν εἰδότες τοῦ Εὐδαμίδα, τὴν φιλίαν δὲ ἣ πρὸς τοὺς ἄνδρας ἦν αὐτῷ ἀγνοοῦντες ἐν παιδιᾷ τὸ πρᾶγμα ἐποιοῦντο καὶ οὐδεὶς ὅστις οὐ γελῶν ἀπηλλάττετο, “οἷον Ἀρεταῖος καὶ Χαρίξενος οἱ εὐδαίμονες κλῆρον διαδέξονται,” λέγοντες, “εἴπερ ἀποτίσουσιν Εὐδαμίδᾳ καὶ ζῶντες αὐτοὶ κληρονομήσονται ὑπὸ τοῦ νεκροῦ.”", "st": "44.22"}, {"sp": "N", "t": "οἱ κληρονόμοι δὲ οἷς ταῦτα κατελέλειπτο, ὡς ἤκουσαν, ἧκον εὐθὺς διαιτῶντες τὰ ἐκ τῶν διαθηκῶν. ὁ μὲν οὖν Χαρίξενος πέντε μόνας ἡμέρας ἐπιβιοὺς ἀπέθανεν, ὁ δὲ Ἀρεταῖος ἄριστος κληρονόμων γενόμενος τήν τε αὑτοῦ καὶ τὴν ἐκείνου μερίδα παραλαβὼν τρέφει τε τοῦ Εὐδαμίδα τὴν μητέρα καὶ τὴν θυγατέρα οὐ πρὸ πολλοῦ ἐκδέδωκεν, ἀπὸ ταλάντων πέντε ὧν εἶχεν δύο μὲν τῇ ἑαυτοῦ θυγατρί, δύο δὲ τῇ τοῦ φίλου ἐπιδούς, καὶ τὸν γάμον γε αὐταῖν ἐπὶ μιᾶς ἡμέρας ἠξίωσε γενέσθαι.", "st": "44.23"}, {"sp": "N", "t": "τί σοι δοκεῖ, ὦ Τόξαρι, ὁ Ἀρεταῖος οὗτος; ἆρα φαῦλον παράδειγμα φιλίας παρεσχῆσθαι τοιαῦτα κληρονομήσας καὶ μὴ προδοὺς τὰς διαθήκας τοῦ φίλου; ἢ τίθεμεν καὶ τοῦτον ἐν ταῖς τελείαις ψήφοις μίαν τῶν πέντε εἶναι;", "st": "44.23"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> καὶ οὗτος μὲν καλός· ἐγὼ δὲ τὸν Εὐδαμίδαν πολὺ μᾶλλον ἐθαύμασα τοῦ θάρσους ὃ εἶχεν ἐπὶ τοῖς φίλοις. ἐδήλου γὰρ ὡς καὶ αὐτὸς ἂν τὰ ὅμοια ἔπραξεν ἐπ’ αὐτοῖς, εἰ μὴ καὶ ἐν διαθήκαις ταῦτα ἐνεγέγραπτο, ἀλλὰ πρὸ τῶν ἄλλων ἧκεν ἂν ἄγραφος κληρονόμος τῶν τοιούτων.", "st": "44.23"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> εὖ λέγεις. τέταρτον δέ σοι διηγήσομαι Ζηνόθεμιν τὸν Χαρμόλεω Μασσαλίηθεν.", "st": "44.24"}, {"sp": "N", "t": "ἐδείχθη δέ μοι ἐν Ἰταλίᾳ πρεσβεύοντι ὑπὲρ τῆς πατρίδος, καλὸς ἀνὴρ καὶ μέγας καὶ πλούσιος, ὡς ἐδόκει· παρεκάθητο δὲ αὐτῷ γυνὴ ἐπὶ ζεύγους ὁδοιποροῦντι τά τε ἄλλα εἰδεχθὴς καὶ ξηρὰ τὸ ἥμισυ τὸ δεξιὸν καὶ τὸν ὀφθαλμὸν ἐκκεκομμένη, παλλώβητόν τι καὶ ἀπρόσιτον μορμολυκεῖον. εἶτα ἐπεὶ ἐθαύμασα εἰ καλὸς οὗτος καὶ ὡραῖος ὢν ἀνέχεται παροχουμένην τοιαύτην αὐτῷ γυναῖκα, ὁ δείξας αὐτὸν διηγεῖτό μοι τὴν ἀνάγκην τοῦ γάμου ἀκριβῶς εἰδὼς ἕκαστα· Μασσαλιώτης δὲ καὶ αὐτὸς ἦν.", "st": "44.24"}, {"sp": "N", "t": "“Μενεκράτει γάρ,” ἔφη, “τῷ πατρὶ τῆς δυσμόρφου ταύτης φίλος ἦν ὁ Ζηνόθεμις, πλουτοῦντι καὶ τιμωμένῳ ὁμότιμος ὤν. χρόνῳ δὲ ὁ Μενεκράτης ἀφῃρέθη τὴν οὐσίαν ἐκ καταδίκης, ὅτεπερ καὶ ἄτιμος ἐγένετο ὑπὸ τῶν ἑξακοσίων ὡς ἀποφηνάμενος γνώμην παράνομον. οὕτω δὲ οἱ Μασσαλιῶται κολάζομεν,” ἔφη, “εἴ τις παράνομα γράψειεν. ἐλυπεῖτο οὖν ὁ Μενεκράτης καὶ ἐπὶ τῇ καταδίκῃ, ἐπεὶ ἐκ πλουσίου πένης καὶ ἐξ ἐνδόξου ἄδοξος ἐν ὀλίγῳ ἐγένετο· μάλιστα δὲ αὐτὸν ἠνία θυγάτηρ αὕτη, ἐπίγαμος ἤδη καὶ ὀκτωκαιδεκαέτις οὖσα, ἣν οὐδὲ μετὰ πάσης τῆς οὐσίας τοῦ πατρὸς ἣν πρὸ τῆς καταδίκης ἐκέκτητο ἠξίωσεν ἄν τις τῶν γε εὐγενῶν καὶ πενήτων ῥᾳδίως παραλαβεῖν, οὕτως κακοδαίμονα οὖσαν τὴν ὄψιν. ἐλέγετο δὲ καὶ καταπίπτειν πρὸς τὴν σελήνην αὐξανομένην.", "st": "44.24"}, {"sp": "N", "t": "ὡς δὲ ταῦτα πρὸς τὸν Ζηνόθεμιν ἀπωδύρετο, ‘θάρρει,’ ἔφη, ‘ὦ Μενέκρατες, οὔτε γὰρ ἀπορήσεις τῶν ἀναγκαίων καὶ ἡ θυγάτηρ σου ἄξιον τοῦ γένους τινὰ εὑρήσει νυμφίον.’ καὶ ταῦτα ἅμα διεξιὼν λαβόμενος αὐτὸν τῆς δεξιᾶς ἦγεν εἰς τὴν οἰκίαν καὶ τήν τε οὐσίαν πολλὴν οὖσαν ἐνείματο πρὸς αὐτὸν καὶ δεῖπνον παρασκευασθῆναι κελεύσας εἱστία τοὺς φίλους καὶ τὸν Μενεκράτη, ὡς δή τινα τῶν ἑταίρων πεπεικὼς ὑποστῆναι τῆς κόρης τὸν γάμον. ἐπεὶ δὲ ἐδεδείπνητο αὐτοῖς καὶ ἔσπεισαν τοῖς θεοῖς, ἐνταῦθα δὴ μεστὴν αὐτῷ τὴν φιάλην προτείνας, ‘δέδεξο,’ εἶπεν, ‘ὦ Μενέκρατες, παρὰ τοῦ γαμβροῦ φιλοτησίαν· ἄξομαι γὰρ ἐγὼ τήμερον τὴν σὴν θυγατέρα Κυδιμάχην· τὴν προῖκα δὲ πάλαι εἴληφα, τάλαντα πέντε καὶ εἴκοσι.’ τοῦ δέ, ‘ἄπαγε,’ λέγοντος, ‘μὴ σύ γε, ὦ Ζηνόθεμι· μὴ οὕτω μανείην ὡς περιιδεῖν σε νέον καὶ καλὸν ὄντα κόρῃ αἰσχρᾷ καὶ λελωβημένῃ συγκαταζευγνύμενον,’ ὁ δέ, ταῦτα διεξιόντος, ἀράμενος τὴν νύμφην ἀπῄει εἰς τὸν θάλαμον καὶ μετ’ ὀλίγον προῆλθεν διακορήσας αὐτήν.", "st": "44.25"}, {"sp": "N", "t": "καὶ τὸ ἀπ’ ἐκείνου σύνεστιν ὑπεραγαπῶν καὶ πάντῃ ὡς ὁρᾷς περιαγόμενος αὐτήν.", "st": "44.25"}, {"sp": "N", "t": "καὶ οὐχ ὅπως αἰσχύνεται τῷ γάμῳ, ἀλλὰ καὶ σεμνυνομένῳ ἔοικεν, ἐπιδεικνύμενος ὡς καταφρονεῖ μὲν τῶν ἐν τῷ σώματι καλῶν ἢ αἰσχρῶν καὶ πλούτου καὶ δόξης, ἀφορᾷ δὲ ἐς τὸν φίλον καὶ τὸν Μενεκράτη, οὐδὲ οἴεται χείρω πρὸς φιλίαν ὑπὸ τῆς ψήφου τῶν ἑξακοσίων γεγονέναι.", "st": "44.26"}, {"sp": "N", "t": "πλὴν ἤδη γε τούτων οὕτως αὐτὸν ἠμείψατο ἡ τύχη. παιδίον γὰρ πάγκαλον ἐκ τῆς αἰσχίστης αὐτῷ ταύτης ἐγένετο, καὶ πρῴην γε, ἐπεὶ ἀράμενος αὐτὸ εἰσεκόμισεν ὁ πατὴρ εἰς τὸ βουλευτήριον θαλλῷ ἐστεμμένον καὶ μέλανα ἀμπεχόμενον, ὡς ἐλεεινότερον φανείη ὑπὲρ τοῦ πάππου, τὸ μὲν βρέφος ἀνεγέλασε πρὸς τοὺς βουλευτὰς καὶ συνεκρότει τὼ χεῖρε, ἡ βουλὴ δὲ ἐπικλασθεῖσα πρὸς αὐτὸ ἀφίησι τῷ Μενεκράτει τὴν καταδίκην καὶ ἤδη ἐπίτιμός ἐστι, τηλικούτῳ συνηγόρῳ χρησάμενος πρὸς τὸ συνέδριον.”", "st": "44.26"}, {"sp": "N", "t": "Τοιαῦτα ὁ Μασσαλιώτης ἔλεγεν τὸν Ζηνόθεμιν εἰργάσθαι ὑπὲρ τοῦ φίλου, ὡς ὁρᾷς, οὐ μικρὰ οὐδὲ ὑπὸ πολλῶν ἂν Σκυθῶν γενόμενα, οἵ γε κἂν τὰς παλλακὰς ἀκριβῶς τὰς καλλίστας ἐκλέγεσθαι λέγονται.", "st": "44.26"}, {"sp": "N", "t": "λοιπὸς ἡμῖν ὁ πέμπτος, καί μοι δοκῶ οὐκ ἄλλον ἐρεῖν Δημητρίου τοῦ Σουνιέως ἐπιλαθόμενος.", "st": "44.27"}, {"sp": "N", "t": "συνεκπλεύσας γὰρ ἐς τὴν Αἴγυπτον ὁ Δημήτριος Ἀντιφίλῳ τῷ Ἀλωπεκῆθεν, ἑταίρῳ ἐκ παίδων ὄντι καὶ συνεφήβῳ, συνῆν καὶ συνεπαιδεύετο, αὐτὸς μὲν τὴν ἄσκησιν τὴν Κυνικὴν ἀσκούμενος ὑπὸ τῷ Ῥοδίῳ ἐκείνῳ σοφιστῇ, ὁ δὲ Ἀντίφιλος ἰατρικὴν ἄρα ἐμελέτα. καὶ δή ποτε ὁ μὲν Δημήτριος ἔτυχεν ἐς τὴν Αἴγυπτον ἀποδημῶν κατὰ θέαν τῶν πυραμίδων καὶ τοῦ Μέμνονος· ἤκουε γὰρ ταύτας ὑψηλὰς οὔσας μὴ παρέχεσθαι σκιάν, τὸν δὲ Μέμνονα βοᾶν πρὸς ἀνατέλλοντα τὸν ἥλιον. τούτων ἐπιθυμήσας Δημήτριος, θέας μὲν τῶν πυραμίδων, ἀκροάσεως δὲ τοῦ Μέμνονος, ἀναπεπλεύκει κατὰ τὸν Νεῖλον ἕκτον ἤδη μῆνα, ὀκνήσαντα πρὸς τὴν ὁδὸν καὶ τὸ θάλπος ἀπολιπὼν τὸν Ἀντίφιλον.", "st": "44.27"}, {"sp": "N", "t": "ὁ δὲ ἐν τοσούτῳ συμφορᾷ ἐχρήσατο μάλα γενναίου τινὸς φίλου δεομένῃ. οἰκέτης γὰρ αὐτοῦ, Σύρος καὶ τοὔνομα καὶ τὴν πατρίδα, ἱεροσύλοις τισὶ κοινωνήσας συνεισῆλθέν τε αὐτοῖς εἰς τὸ Ἀνουβίδειον καὶ ἀποσυλήσαντες τὸν θεὸν χρυσᾶς τε φιάλας δύο καὶ κηρύκιον, χρυσοῦν καὶ τοῦτο, καὶ κυνοκεφάλους ἀργυροῦς καὶ ἄλλα τοιαῦτα, κατέθεντο πάντα παρὰ τῷ Σύρῳ· εἶτ’ ἐμπεσόντες — ἑάλωσαν γάρ τι ἀπεμπολῶντες — ἅπαντα εὐθὺς ἔλεγον στρεβλούμενοι ἐπὶ τοῦ τροχοῦ, καὶ ἀγόμενοι ἧκον ἐπὶ τὴν οἰκίαν τοῦ Ἀντιφίλου, καὶ τὰ φώρια ἐξέφερον ὑπὸ κλίνῃ τινὶ ἐν σκοτεινῷ κείμενα. ὅ τε οὖν Σύρος ἐδέδετο εὐθὺς καὶ ὁ δεσπότης αὐτοῦ Ἀντίφιλος, οὗτος μὲν καὶ μεταξὺ ἀκροώμενος τοῦ διδασκάλου ἀνασπασθείς. ἐβοήθει δὲ οὐδείς, ἀλλὰ καὶ οἱ τέως ἑταῖροι ἀπεστρέφοντο ὡς τὸ Ἀνουβίδειον σεσυληκότα καὶ ἀσέβημα αὐτῶν ἡγοῦντο εἶναι εἰ συνέπιόν ποτε ἢ συνειστιάθησαν αὐτῷ. καὶ οἱ λοιποὶ δὲ τῶν οἰκετῶν, δύο ὄντες, ἅπαντα ἐκ τῆς οἰκίας συσκευασάμενοι ᾤχοντο φεύγοντες.", "st": "44.28"}, {"sp": "N", "t": "ἐδέδετο οὖν ὁ ἄθλιος Ἀντίφιλος πολὺν ἤδη χρόνον, ἁπάντων ὅσοι ἦσαν κακοῦργοι ἐν τῷ δεσμωτηρίῳ μιαρώτατος εἶναι δοκῶν, καὶ ὁ ἐπὶ τῶν δεσμῶν Αἰγύπτιος, δεισιδαίμων ἄνθρωπος, ᾤετο χαριεῖσθαι καὶ τιμωρήσειν τῷ θεῷ βαρὺς τῷ Ἀντιφίλῳ ἐφεστώς. εἰ δ’ ἀπολογοῖτό ποτε, λέγων ὡς οὐδὲν τοιοῦτον εἴργασται, ἀναίσχυντος ἐδόκει καὶ πολὺ πλέον ἐπὶ τούτῳ ἐμισεῖτο. ὑπενόσει τοιγαροῦν ἤδη καὶ πονηρῶς εἶχεν οἷον εἰκὸς χαμαὶ καθεύδοντα καὶ τῆς νυκτὸς οὐδὲ ἀποτείνειν τὰ σκέλη δυνάμενον ἐν τῷ ξύλῳ κατακεκλειμένα· τῆς μὲν γὰρ ἡμέρας ὁ κλοιὸς ἤρκει καὶ ἡ ἑτέρα χεὶρ πεπεδημένη, εἰς δὲ τὴν νύκτα ἔδει ὅλον καταδεδέσθαι. καὶ μὴν καὶ τοῦ οἰκήματος ἡ δυσοσμία καὶ τὸ πνῖγος, ἐν ταὐτῷ πολλῶν δεδεμένων καὶ ἐστενοχωρημένων καὶ μόλις ἀναπνεόντων, καὶ τοῦ σιδήρου ὁ ψόφος καὶ ὕπνος ὀλίγος — ταῦτα πάντα χαλεπὰ ἦν καὶ ἀφόρητα οἵῳ ἀνδρὶ ἐκείνων ἀήθει καὶ ἀμελετήτῳ πρὸς οὕτω σκληρὰν τὴν δίαιταν.", "st": "44.29"}, {"sp": "N", "t": "ἀπαγορεύοντος δὲ αὐτοῦ καὶ μηδὲ σῖτον αἱρεῖσθαι θέλοντος, ἀφικνεῖταί ποτε καὶ ὁ Δημήτριος, οὐδὲν εἰδὼς τῶν ἤδη γεγενημένων. καὶ ἐπειδὴ ἔμαθεν, ὡς εἶχεν εὐθὺς ἐπὶ τὸ δεσμωτήριον δρομαῖος ἐλθών, τότε μὲν οὐκ εἰσεδέχθη, ἑσπέρα γὰρ ἦν, καὶ ὁ δεσμοφύλαξ πάλαι κεκλεικὼς τὴν θύραν ἐκάθευδε, φρουρεῖν τοῖς οἰκέταις παρακελευσάμενος· ἕωθεν δὲ εἰσέρχεται πολλὰ ἱκετεύσας. καὶ παρελθὼν ἐπὶ πολὺ μὲν ἐζήτει τὸν Ἀντίφιλον ἄδηλον ὑπὸ τῶν κακῶν γεγενημένον, καὶ περιιὼν ἀνεσκοπεῖτο καθ’ ἕκαστον τῶν δεδεμένων, ὥσπερ εἰώθασιν οἱ τοὺς οἰκείους νεκρούς, ἤδη ἑώλων ὄντων, ἀναζητοῦντες ἐν ταῖς παρατάξεσιν. καὶ εἴ γε μὴ τοὔνομα ἐβόησεν, Ἀντίφιλον Δεινομένους, κἂν ἐπὶ πολὺ ἠγνόησεν ἂν ὅστις ἦν, τοσοῦτον ἤλλακτο ὑπὸ τῶν δεινῶν. ὡς δὲ τὴν φωνὴν αἰσθόμενος ἀνεβόησεν καὶ προσιόντος διαστείλας τὴν κόμην καὶ ἀπάγων τοῦ προσώπου αὐχμηρὰν καὶ συμπεπιλημένην ἔδειξεν αὑτὸν ὅστις ἦν, ἄμφω μὲν αὐτίκα πίπτουσιν ἰλιγγιάσαντες ἐπὶ τῇ ἀπροσδοκήτῳ θέᾳ.", "st": "44.30"}, {"sp": "N", "t": "χρόνῳ δὲ ἀναλαβὼν αὑτόν τε καὶ τὸν Ἀντίφιλον ὁ Δημήτριος καὶ σαφῶς ἕκαστα ὡς εἶχεν ἐκπυθόμενος παρ’ αὐτοῦ θαρρεῖν τε παρακελεύεται καὶ διελὼν τὸ τριβώνιον τὸ μὲν ἥμισυ αὐτὸς ἀναβάλλεται, τὸ λοιπὸν δὲ ἐκείνῳ δίδωσιν, ἃ εἶχε πιναρὰ καὶ ἐκτετρυχωμένα ῥάκη περισπάσας.", "st": "44.30"}, {"sp": "N", "t": "καὶ τὸ ἀπὸ τούτου πάντα τρόπον συνῆν ἐπιμελούμενος αὐτοῦ καὶ θεραπεύων· παραδοὺς γὰρ ἑαυτὸν τοῖς ἐν τῷ λιμένι ἐμπόροις ἕωθεν εἰς μέσην ἡμέραν οὐκ ὀλίγον ἀπέφερεν ἀχθοφορῶν. εἶτ’ ἐπανελθὼν ἂν ἐκ τοῦ ἔργου, μέρος μὲν τοῦ μισθοῦ τῷ δεσμοφύλακι καταβαλὼν τιθασὸν αὑτῷ καὶ εἰρηνικὸν ἀπειργάζετο αὐτόν, τὸ λοιπὸν δὲ εἰς τὴν τοῦ φίλου θεραπείαν ἱκανῶς αὐτῷ διήρκει. καὶ τὰς μὲν ἡμέρας συνῆν τῷ Ἀντιφίλῳ παραμυθούμενος, ἐπεὶ δὲ νὺξ καταλάβοι, ὀλίγον πρὸ τῆς θύρας τοῦ δεσμωτηρίου στιβάδιόν τι ποιησάμενος καὶ φύλλα ὑποβαλόμενος ἀνεπαύετο.", "st": "44.31"}, {"sp": "N", "t": "χρόνον μὲν οὖν τινα οὕτω διῆγον, εἰσιὼν μὲν ὁ Δημήτριος ἀκωλύτως, ῥᾷον δὲ φέρων τὴν συμφορὰν ὁ Ἀντίφιλος.", "st": "44.31"}, {"sp": "N", "t": "ὕστερον δὲ ἀποθανόντος ἐν τῷ δεσμωτηρίῳ λῃστοῦ τινος ὑπὸ φαρμάκων, ὡς ἐδόκει, φυλακή τε ἀκριβὴς ἐγένετο καὶ οὐκέτι παρῄει εἰς τὸ οἴκημα οὐδὲ εἷς τῶν δεομένων. ἐφ’ οἷς ἀπορῶν καὶ ἀνιώμενος, οὐκ ἔχων ἄλλως παρεῖναι τῷ ἑταίρῳ, προσαγγέλλει ἑαυτὸν ἐλθὼν πρὸς τὸν ἁρμοστήν, ὡς εἴη κεκοινωνηκὼς τῆς ἐπὶ τὸν Ἄνουβιν ἐπιβουλῆς.", "st": "44.32"}, {"sp": "N", "t": "ὡς δὲ τοῦτο εἶπεν, ἀπήγετο εὐθὺς ἐς τὸ δεσμωτήριον, καὶ ἀχθεὶς παρὰ τὸν Ἀντίφιλον τοῦτο γοῦν μόλις, πολλὰ ἱκετεύσας τὸν δεσμοφύλακα, ἐξειργάσατο παρ’ αὐτοῦ, πλησίον τῷ Ἀντιφίλῳ καὶ ὑπὸ τῷ αὐτῷ κλοιῷ δεδέσθαι. ἔνθα δὴ καὶ μάλιστα ἔδειξε τὴν εὔνοιαν ἣν εἶχε πρὸς αὐτόν, ἀμελῶν μὲν τῶν καθ’ ἑαυτὸν δεινῶν (καίτοι ἐνόσησε καὶ αὐτός), ἐπιμελούμενος δὲ ὅπως ἐκεῖνος μάλιστα καθευδήσει καὶ ἧττον ἀνιάσεται· ὥστε ῥᾷον ἔφερον μετ’ ἀλλήλων κακοπαθοῦντες.", "st": "44.32"}, {"sp": "N", "t": "χρόνῳ δὲ καὶ τοιόνδε τι προσπεσὸν ἔπαυσεν ἐπὶ πλέον αὐτοὺς δυστυχοῦντας. εἷς γὰρ τῶν δεδεμένων, οὐκ οἶδ’ ὅθεν ῥίνης εὐπορήσας καὶ συνωμότας πολλοὺς τῶν δεσμωτῶν προσλαβών, ἀποπρίει τε τὴν ἅλυσιν ᾗ ἐδέδεντο ἑξῆς, τῶν κλοιῶν εἰς αὐτὴν διειρομένων, καὶ ἀπολύει ἅπαντας· οἱ δὲ ἀποκτείναντες εὐμαρῶς ὀλίγους ὄντας τοὺς φύλακας ἐκπηδῶσιν ἀθρόοι. ἐκεῖνοι μὲν οὖν τὸ παραυτίκα ἔνθα ἐδύναντο ἕκαστος διασπαρέντες ὕστερον συνελήφθησαν οἱ πολλοί· ὁ Δημήτριος δὲ καὶ ὁ Ἀντίφιλος κατὰ χώραν ἔμειναν, καὶ τοῦ Σύρου λαβόμενοι ἤδη ἀπιόντος. ἐπεὶ δὲ ἡμέρα ἐγένετο, μαθὼν ὁ τὴν Αἴγυπτον ἐπιτετραμμένος τὸ συμβεβηκὸς ἐπ’ ἐκείνους μὲν ἔπεμψεν τοὺς διωξομένους, μεταστειλάμενος δὲ τοὺς ἀμφὶ τὸν Δημήτριον ἀπέλυσε τῶν δεσμῶν, ἐπαινέσας ὅτι μόνοι οὐκ ἀπέδρασαν.", "st": "44.33"}, {"sp": "N", "t": "ἀλλ’ οὐκ ἐκεῖνοί γε ἠγάπησαν οὕτως ἀφιέμενοι, ἐβόα δὲ ὁ Δημήτριος καὶ δεινὰ ἐποίει, ἀδικεῖσθαι σφᾶς οὐ μικρὰ εἰ δόξουσι κακοῦργοι ὄντες ἐλέῳ ἢ ἐπαίνῳ τοῦ μὴ ἀποδρᾶναι ἀφεῖσθαι· καὶ τέλος ἠνάγκασαν τὸν δικαστὴν ἀκριβῶς τὸ πρᾶγμα ἐξετάσαι. ὁ δὲ ἐπεὶ ἔμαθεν οὐδὲν ἀδικοῦντας, ἐπαινέσας αὐτούς, τὸν Δημήτριον δὲ καὶ πάνυ θαυμάσας, ἀφίησι παραμυθησάμενος ἐπὶ τῇ κολάσει ἣν ἠνέσχοντο ἀδίκως δεθέντες, καὶ ἑκάτερον δωρησάμενος παρ’ αὑτοῦ, δραχμαῖς μὲν μυρίαις τὸν Ἀντίφιλον, δὶς τοσαύταις δὲ τὸν Δημήτριον.", "st": "44.33"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἀντίφιλος ἔτι καὶ νῦν ἐν Αἰγύπτῳ ἐστίν, ὁ δὲ Δημήτριος καὶ τὰς αὑτοῦ δισμυρίας ἐκείνῳ καταλιπὼν ᾤχετο ἀπιὼν εἰς τὴν Ἰνδικὴν παρὰ τοὺς Βραχμᾶνας, τοσοῦτον εἰπὼν πρὸς τὸν Ἀντίφιλον, ὡς συγγνωστὸς ἂν εἰκότως νομίζοιτο ἤδη ἀπολιπὼν αὐτόν· οὔτε γὰρ αὐτὸς δεῖσθαι τῶν χρημάτων, ἔστ’ ἂν αὐτὸς ᾖ ὅπερ ἐστίν, ἀρκεῖσθαι ὀλίγοις δυνάμενος, οὔτε ἐκείνῳ ἔτι δεῖν φίλου, εὐμαρῶν αὐτῷ τῶν πραγμάτων γεγενημένων.", "st": "44.34"}, {"sp": "N", "t": "τοιοῦτοι, ὦ Τόξαρι, οἱ Ἕλληνες φίλοι. εἰ δὲ μὴ προδιεβεβλήκεις ἡμᾶς ὡς ἐπὶ ῥήμασι μέγα φρονοῦντας, καὶ αὐτοὺς ἄν σοι τοὺς λόγους διεξῆλθον, πολλοὺς καὶ ἀγαθοὺς ὄντας, οὓς ὁ Δημήτριος εἶπεν ἐν τῷ δικαστηρίῳ, ὑπὲρ αὑτοῦ μὲν οὐδὲν ἀπολογούμενος, ὑπὲρ τοῦ Ἀντιφίλου δέ, καὶ δακρύων προσέτι καὶ ἱκετεύων καὶ τὸ πᾶν ἐφ’ ἑαυτὸν ἀναδεχόμενος, ἄχρι μαστιγούμενος ὁ Σύρος ἀμφοτέρους ἀφίησιν αὐτούς.", "st": "44.34"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν τούτους ὀλίγους ἀπὸ πλειόνων, οὓς πρώτους ἡ μνήμη ὑπέβαλε, διηγησάμην σοι ἀγαθοὺς καὶ βεβαίους φίλους. καὶ τὸ λοιπὸν ἤδη καταβὰς ἀπὸ τοῦ λόγου σοὶ τὴν ῥήτραν παραδίδωμι· σὺ δὲ ὅπως μὴ χείρους ἐρεῖς τοὺς Σκύθας, ἀλλὰ πολλῷ τούτων ἀμείνους, αὐτῷ σοὶ μελήσει, εἴ τι καὶ τῆς δεξιᾶς πεφρόντικας, ὡς μὴ ἀποτμηθείης αὐτήν. ἀλλὰ χρὴ ἄνδρα ἀγαθὸν εἶναι· ἐπεὶ καὶ γελοῖα ἂν πάθοις Ὀρέστην μὲν καὶ Πυλάδην πάνυ σοφιστικῶς ἐπαινέσας, ὑπὲρ δὲ τῆς Σκυθίας φαῦλος ῥήτωρ φαινόμενος.", "st": "44.35"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> εὖ γε, ὦ Μνήσιππε, ὅτι καὶ παροτρύνεις με πρὸς τὸν λόγον, ὥσπερ οὐ πάνυ σοι μέλον εἰ ἀποτμηθείης τὴν γλῶτταν κρατηθεὶς ἐν τοῖς λόγοις. πλὴν ἄρξομαί γε ἤδη, μηδὲν ὥσπερ σὺ καλλιλογησάμενος· οὐ γὰρ Σκυθικὸν τοῦτο, καὶ μάλιστα ἐπειδὰν τὰ ἔργα ὑπερφθέγγηται τοὺς λόγους. προσδοκήσῃς δὲ μηδὲν τοιοῦτο παρ’ ἡμῶν οἷα σὺ διεξελήλυθας, ἐπαινῶν εἴ τις ἄπροικον ἔγημεν αἰσχρὰν γυναῖκα ἢ εἴ τις ἀργύριον ἐπέδωκε γαμουμένῃ φίλου ἀνδρὸς θυγατρὶ δύο τάλαντα, ἢ καὶ νὴ Δί’ εἴ τις παρέσχεν ἑαυτὸν δεδησόμενον ἐπὶ προδήλῳ τῷ μικρὸν ὕστερον λυθήσεσθαι· πάνυ γὰρ εὐτελῆ ταῦτα καὶ μεγαλουργὸν ἐν αὐτοῖς ἢ ἀνδρεῖον ἔνι οὐδέν.", "st": "44.35"}, {"sp": "N", "t": "ἐγὼ δέ σοι διηγήσομαι φόνους πολλοὺς καὶ πολέμους καὶ θανάτους ὑπὲρ τῶν φίλων, ἵν’ εἰδῇς ὡς παιδιὰ τὰ ὑμέτερά ἐστιν παρὰ τὰ Σκυθικὰ ἐξετάζεσθαι.", "st": "44.36"}, {"sp": "N", "t": "καίτοι οὐδὲ ἀλόγως αὐτὸ πεπόνθατε, ἀλλὰ εἰκότως τὰ μικρὰ ταῦτα ἐπαινεῖτε· οὐδὲ γὰρ οὐδέ εἰσιν ὑμῖν ἀφορμαὶ ὑπερμεγέθεις πρὸς ἐπίδειξιν φιλίας ἐν εἰρήνῃ βαθείᾳ βιοῦσιν, ὥσπερ οὐδ’ ἂν ἐν γαλήνῃ μάθοις εἰ ἀγαθὸς ὁ κυβερνήτης ἐστί· χειμῶνος γὰρ δεήσει σοὶ πρὸς τὴν διάγνωσιν. παρ’ ἡμῖν δὲ συνεχεῖς οἱ πόλεμοι, καὶ ἢ ἐπελαύνομεν ἄλλοις ἢ ὑποχωροῦμεν ἐπιόντας ἢ συμπεσόντες ὑπὲρ νομῆς ἢ λείας μαχόμεθα, ἔνθα μάλιστα δεῖ φίλων ἀγαθῶν· καὶ διὰ τοῦτο ὡς βεβαιότατα συντιθέμεθα τὰς φιλίας, μόνον τοῦτο ὅπλον ἄμαχον καὶ δυσπολέμητον εἶναι νομίζοντες.", "st": "44.36"}, {"sp": "N", "t": "πρότερον δέ σοι εἰπεῖν βούλομαι ὃν τρόπον ποιούμεθα τοὺς φίλους, οὐκ ἐκ τῶν πότων, ὥσπερ ὑμεῖς, οὐδὲ εἰ συνέφηβός τις ἢ γείτων ἦν, ἀλλ’ ἐπειδάν τινα ἴδωμεν ἀγαθὸν ἄνδρα καὶ μεγάλα ἐργάσασθαι δυνάμενον, ἐπὶ τοῦτον ἅπαντες σπεύδομεν, καὶ ὅπερ ὑμεῖς ἐν τοῖς γάμοις, τοῦτο ἡμεῖς ἐπὶ τῶν φίλων ποιεῖν ἀξιοῦμεν, ἐπὶ πολὺ μνηστευόμενοι καὶ πάντα ὁμοῦ πράττοντες ὡς μὴ διαμαρτάνοιμεν τῆς φιλίας μηδὲ ἀπόβλητοι δόξωμεν εἶναι. κἀπειδὰν προκριθείς τις ἤδη φίλος ᾖ, συνθῆκαι τὸ ἀπὸ τούτου καὶ ὅρκος ὁ μέγιστος, ἦ μὴν καὶ βιώσεσθαι μετ’ ἀλλήλων καὶ ἀποθανεῖσθαι, ἢν δέῃ, ὑπὲρ τοῦ ἑτέρου τὸν ἕτερον· καὶ οὕτω ποιοῦμεν. ἀφ’ οὗ γὰρ ἂν ἐντεμόντες ἅπαξ τοὺς δακτύλους ἐνσταλάξωμεν τὸ αἷμα εἰς κύλικα καὶ τὰ ξίφη ἄκρα βάψαντες ἅμα ἀμφότεροι ἐπισχόμενοι πίωμεν, οὐκ ἔστιν ὅ τι τὸ μετὰ τοῦτο ἡμᾶς διαλύσειεν ἄν. ἐφεῖται δὲ τὸ μέγιστον ἄχρι τριῶν ἐς τὰς συνθήκας εἰσιέναι· ὡς ὅστις ἂν πολύφιλος ᾖ, ὅμοιος ἡμῖν δοκεῖ ταῖς κοιναῖς ταύταις καὶ μοιχευομέναις γυναιξί, καὶ οἰόμεθα οὐκέθ’ ὁμοίως ἰσχυρὰν αὐτοῦ τὴν φιλίαν εἶναι, πρὸς πολλὰς εὐνοίας διαιρεθεῖσαν.", "st": "44.37"}, {"sp": "N", "t": "ἄρξομαι δὲ ἀπὸ τῶν Δανδάμιδος πρῴην γενομένων. ὁ γὰρ Δάνδαμις ἐν τῇ πρὸς Σαυρομάτας συμπλοκῇ, ἀπαχθέντος αἰχμαλώτου Ἀμιζώκου τοῦ φίλου αὐτοῦ — μᾶλλον δὲ πρότερον ὀμοῦμαί σοι τὸν ἡμέτερον ὅρκον, ἐπεὶ καὶ τοῦτο ἐν ἀρχῇ διωμολογησάμην· οὐ μὰ γὰρ τὸν Ἄνεμον καὶ τὸν Ἀκινάκην, οὐδὲν πρὸς σέ, ὦ Μνήσιππε, ψεῦδος ἐρῶ περὶ τῶν φίλων τῶν Σκυθῶν.", "st": "44.38"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ἐγὼ μὲν οὐ πάνυ σου ὀμνύντος ἐδεόμην· σὺ δὲ ὅμως εὖ ποιῶν οὐδένα θεῶν ἐπωμόσω.", "st": "44.38"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> τί σὺ λέγεις; οὔ σοι δοκοῦσιν ὁ Ἄνεμος καὶ ὁ Ἀκινάκης θεοὶ εἶναι; οὕτως ἄρα ἠγνόησας ὅτι ἀνθρώποις μεῖζον οὐδέν ἐστιν ζωῆς τε καὶ θανάτου; ὁπόταν τοίνυν τὸν Ἄνεμον καὶ τὸν Ἀκινάκην ὀμνύωμεν, ταῦτα ὀμνύομεν ὡς τὸν μὲν ἄνεμον ζωῆς αἴτιον ὄντα, τὸν ἀκινάκην δὲ ὅτι ἀποθνήσκειν ποιεῖ.", "st": "44.38"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> καὶ μὴν εἰ διά γε τοῦτο, καὶ ἄλλους ἂν ἔχοιτε πολλοὺς θεοὺς οἷος ὁ Ἀκινάκης ἐστί, τὸν Ὀιστὸν καὶ τὴν Λόγχην καὶ Κώνειον δὲ καὶ Βρόχον καὶ τὰ τοιαῦτα· ποικίλος γὰρ οὗτος ὁ θεὸς ὁ θάνατος καὶ ἀπείρους τὰς ἐφ’ ἑαυτὸν παρέχεται ἀγούσας ὁδούς.", "st": "44.38"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> ὁρᾷς τοῦτο ὡς ἐριστικὸν ποιεῖς καὶ δικανικόν, ὑποκρούων μεταξὺ καὶ διαφθείρων μου τὸν λόγον; ἐγὼ δὲ ἡσυχίαν ἦγον σοῦ λέγοντος.", "st": "44.38"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ἀλλ’ οὐκ αὖθίς γε, ὦ Τόξαρι, ποιήσω τοῦτο, πάνυ γὰρ ὀρθῶς ἐπετίμησας· ὥστε θαρρῶν τό γε ἐπὶ τούτῳ λέγε, ὡς μηδὲ παρόντος ἐμοῦ τοῖς λόγοις, οὕτω σιωπήσομαί σοι.", "st": "44.38"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> τετάρτη μὲν ἦν ἡμέρα τῆς φιλίας Δανδάμιδι καὶ Ἀμιζώκῃ, ἀφ’ οὗ τὸ ἀλλήλων αἷμα συνεπεπώκεσαν· ἧκον δὲ ἡμῖν ἐπὶ τὴν χώραν Σαυρομάται μυρίοις μὲν ἱππεῦσιν, οἱ πεζοὶ δὲ τρὶς τοσοῦτοι ἐπεληλυθέναι ἐλέγοντο. οἷα δὲ οὐ προϊδομένοις τὴν ἔφοδον αὐτῶν ἐπιπεσόντες ἅπαντας μὲν τρέπουσι, πολλοὺς δὲ τῶν μαχίμων κτείνουσι, τοὺς δὲ καὶ ζῶντας ἀπάγουσι, πλὴν εἴ τις ἔφθη διανηξάμενος εἰς τὸ πέραν τοῦ ποταμοῦ, ἔνθα ἡμῖν τὸ ἥμισυ τοῦ στρατοπέδου καὶ μέρος τῶν ἁμαξῶν ἦν· οὕτω γὰρ ἐσκηνώσαμεν τότε, οὐκ οἶδα ὅ τι δόξαν τοῖς ἀρχιπλάνοις ἡμῶν, ἐπ’ ἀμφοτέρας τὰς ὄχθας τοῦ Τανάϊδος.", "st": "44.39"}, {"sp": "N", "t": "εὐθὺς οὖν ἥ τε λεία περιηλαύνετο καὶ τὰ αἰχμάλωτα συνείχετο καὶ τὰς σκηνὰς διήρπαζον καὶ τὰς ἁμάξας κατελαμβάνοντο, αὐτάνδρους τὰς πλείστας ἁλισκομένας, καὶ ἐν ὀφθαλμοῖς ἡμῶν ὑβρίζοντες τὰς παλλακίδας καὶ τὰς γυναῖκας· ἡμεῖς δὲ ἠνιώμεθα τῷ πράγματι.", "st": "44.39"}, {"sp": "N", "t": "ὁ δὲ Ἀμιζώκης ἀγόμενος — ἑαλώκει γάρ — ἐβόα τὸν φίλον ὀνομαστί, κακῶς δεδεμένος, καὶ ὑπεμίμνησκεν τῆς κύλικος καὶ τοῦ αἵματος. ὧν ἀκούσας ὁ Δάνδαμις οὐδὲν ἔτι μελλήσας ἁπάντων ὁρώντων διανήχεται εἰς τοὺς πολεμίους· καὶ οἱ μὲν Σαυρομάται διηρμένοι τοὺς ἄκοντας ὥρμησαν ἐπ’ αὐτὸν ὡς κατακεντήσοντες, ὁ δὲ ἐβόα τὸ “Ζίριν.” τοῦτο δὲ ἤν τις εἴπῃ, οὐκέτι φονεύεται ὑπ’ αὐτῶν, ἀλλὰ δέχονται αὐτὸν ὡς ἐπὶ λύτροις ἥκοντα.", "st": "44.40"}, {"sp": "N", "t": "καὶ δὴ ἀναχθεὶς πρὸς τὸν ἄρχοντα αὐτῶν ἀπῄτει τὸν φίλον, ὁ δὲ λύτρα ᾔτει· μὴ γὰρ προήσεσθαι, εἰ μὴ μεγάλα ὑπὲρ αὐτοῦ λάβοι. ὁ Δάνδαμις δέ, “ἃ μὲν εἶχον,” φησίν, “ἅπαντα διήρπασται ὑφ’ ὑμῶν, εἰ δέ τι δύναμαι γυμνὸς ὑποτελέσαι, ἕτοιμος ὑποστῆναι ὑμῖν, καὶ πρόσταττε ὅ τι ἂν θέλῃς. εἰ βούλει δέ, ἐμὲ ἀντὶ τούτου λαβὼν κατάχρησαι πρὸς ὅ τι σοι φίλον.” ὁ δὲ Σαυρομάτης, “οὐδέν,” ἔφη, “δεῖ ὅλον κατέχεσθαί σε, καὶ ταῦτα Ζίριν ἥκοντα, σὺ δὲ ὧν ἔχεις μέρος καταβαλὼν ἄγου τὸν φίλον.” ἤρετο ὁ Δάνδαμις ὅ τι καὶ βούλεται λαβεῖν· ὁ δὲ τοὺς ὀφθαλμοὺς ᾔτησεν. ὁ δὲ αὐτίκα παρέσχεν ἐκκόπτειν αὐτούς· κἀπειδὴ ἐξεκέκοπτο καὶ ἤδη τὰ λύτρα εἶχον οἱ Σαυρομάται, παραλαβὼν τὸν Ἀμιζώκην ἐπανῄει ἐπερειδόμενος αὐτῷ, καὶ ἅμα διανηξάμενοι ἀπεσώθησαν πρὸς ἡμᾶς.", "st": "44.40"}, {"sp": "N", "t": "τοῦτο γενόμενον παρεμυθήσατο ἅπαντας Σκύθας καὶ οὐκέτι ἡττᾶσθαι ἐνόμιζον, ὁρῶντες ὅτι τὸ μέγιστον ἡμῖν τῶν ἀγαθῶν οὐκ ἀπήγαγον οἱ πολέμιοι, ἀλλ’ ἔτι ἦν παρ’ ἡμῖν ἡ ἀγαθὴ γνώμη καὶ ἡ πρὸς τοὺς φίλους πίστις. καὶ τοὺς Σαυρομάτας δὲ τὸ αὐτὸ οὐ μετρίως ἐφόβησε, λογιζομένους πρὸς οἵους ἄνδρας ἐκ παρασκευῆς μαχοῦνται, εἰ καὶ ἐν τῷ ἀπροσδοκήτῳ τότε ὑπερέσχον· ὥστε νυκτὸς ἐπιγενομένης ἀπολιπόντες τὰ πλεῖστα τῶν βοσκημάτων καὶ τὰς ἁμάξας ἐμπρήσαντες ᾤχοντο φεύγοντες. ὁ μέντοι Ἀμιζώκης οὐκέτι ἠνέσχετο βλέπειν αὐτὸς ἐπὶ τυφλῷ τῷ Δανδάμιδι, ἀλλὰ τυφλώσας καὶ αὐτὸς ἑαυτὸν ἀμφότεροι κάθηνται ὑπὸ τοῦ κοινοῦ τῶν Σκυθῶν δημοσίᾳ μετὰ πάσης τιμῆς τρεφόμενοι.", "st": "44.41"}, {"sp": "N", "t": "τί τοιοῦτον, ὦ Μνήσιππε, ὑμεῖς ἔχοιτε ἂν εἰπεῖν, εἰ καὶ ἄλλους σοι δέκα δοίη τις ἐπὶ τοῖς πέντε καταριθμήσασθαι, ἀνωμότους, εἰ βούλει, ὡς καὶ πολλὰ ἐπιψεύδοιο αὐτοῖς; καίτοι ἐγὼ μέν σοι γυμνὸν τὸ ἔργον διηγησάμην· εἰ δὲ σύ τινα τοιοῦτον ἔλεγες, εὖ οἶδα, ὁπόσα ἂν κομψὰ ἐγκατέμιξας τῷ λόγῳ, οἷα ἱκέτευεν ὁ Δάνδαμις καὶ ὡς ἐτυφλοῦτο καὶ ἃ εἶπεν καὶ ὡς ἐπανῆκεν καὶ ὡς ὑπεδέξαντο αὐτὸν ἐπευφημοῦντες οἱ Σκύθαι καὶ ἄλλα ὁποῖα ὑμεῖς μηχανᾶσθαι εἰώθατε πρὸς τὴν ἀκρόασιν.", "st": "44.42"}, {"sp": "N", "t": "ἄκουε δ’ οὖν καὶ ἄλλον ἰσότιμον, Βελίτταν, Ἀμιζώκου τούτου ἀνεψιόν, ὃς ἐπεὶ κατασπασθέντα ἐκ τοῦ ἵππου ὑπὸ λέοντος εἶδε Βάσθην τὸν φίλον (ἅμα δὲ ἔτυχον θηρῶντες) καὶ ἤδη ὁ λέων περιπλακεὶς αὐτῷ ἐνεπεφύκει τῷ λαιμῷ καὶ τοῖς ὄνυξιν ἐσπάρασσε, καταπηδήσας καὶ αὐτὸς ἐπιπίπτει κατόπιν τῷ θηρίῳ καὶ περιέσπα, πρὸς ἑαυτὸν παροξύνων καὶ μετάγων καὶ διὰ τῶν ὀδόντων μεταξὺ διείρων τοὺς δακτύλους καὶ τὸν Βάσθην, ὡς οἷόν τε ἦν, ὑπεξελεῖν πειρώμενος τοῦ δήγματος, ἄχρι δὴ ὁ λέων ἀφεὶς ἐκεῖνον ἡμιθνῆτα ἤδη ἐπὶ τὸν Βελίτταν ἀπεστράφη καὶ συμπλακεὶς ἀπέκτεινε κἀκεῖνον· ὁ δὲ ἀποθνήσκων τὸ γοῦν τοσοῦτον ἔφθη πατάξας τῷ ἀκινάκῃ τὸν λέοντα εἰς τὸ στέρνον ὥστε ἅμα πάντες ἀπέθανον, καὶ ἡμεῖς ἐθάψαμεν αὐτοὺς δύο τάφους ἀναχώσαντες πλησίον, ἕνα μὲν τῶν φίλων, ἕνα δὲ καταντικρὺ τοῦ λέοντος.", "st": "44.43"}, {"sp": "N", "t": "τρίτην δέ σοι διηγήσομαι, ὦ Μνήσιππε, τὴν Μακέντου φιλίαν καὶ Λογχάτου καὶ Ἀρσακόμα. ὁ γὰρ Ἀρσακόμας οὗτος ἠράσθη Μαζαίας τῆς Λευκάνορος, τοῦ βασιλεύσαντος ἐν Βοσπόρῳ, ὁπότε ἐπρέσβευεν ὑπὲρ τοῦ δασμοῦ ὃν οἱ Βοσπορανοὶ ἀεὶ φέροντες ἡμῖν τότε ἤδη τρίτον μῆνα ὑπερήμεροι ἐγεγένηντο. ἐν τῷ δείπνῳ οὖν ἰδὼν τὴν Μαζαίαν μεγάλην καὶ καλὴν παρθένον ἤρα καὶ πονηρῶς εἶχε. τὰ μὲν οὖν περὶ τῶν φόρων διεπέπρακτο ἤδη, καὶ ἐχρημάτιζεν αὐτῷ ὁ βασιλεὺς καὶ εἱστία, ἤδη αὐτὸν ἀποπέμπων. ἔθος δέ ἐστιν ἐν Βοσπόρῳ τοὺς μνηστῆρας ἐπὶ τῷ δείπνῳ αἰτεῖν τὰς κόρας καὶ λέγειν οἵτινες ὄντες ἀξιοῦσι καταδεχθῆναι ἐπὶ τὸν γάμον, καὶ δὴ καὶ τότε ἔτυχον ἐν τῷ δείπνῳ πολλοὶ μνηστῆρες παρόντες, βασιλεῖς καὶ βασιλέων παῖδες· καὶ Τιγραπάτης ἦν ὁ Λαζῶν δυνάστης καὶ Ἀδύρμαχος ὁ Μαχλυηνῆς ἄρχων καὶ ἄλλοι πολλοί. δεῖ δὲ τῶν μνηστήρων ἕκαστον, προσαγγείλαντα ἑαυτὸν διότι μνηστευσόμενος ἥκει, δειπνεῖν ἐν τοῖς ἄλλοις κατακείμενον ἐφ’ ἡσυχίας· ἐπὰν δὲ παύσωνται δειπνοῦντες, αἰτήσαντα φιάλην ἐπισπεῖσαι κατὰ τῆς τραπέζης καὶ μνηστεύεσθαι τὴν παῖδα πολλὰ ἐπαινοῦντα ἑαυτόν, ὥς τις ἢ γένους ἢ πλούτου ἢ δυνάμεως ἔχει.", "st": "44.44"}, {"sp": "N", "t": "πολλῶν οὖν κατὰ τόνδε τὸν νόμον σπεισάντων καὶ αἰτησάντων καὶ βασιλείας καὶ πλούτους καταριθμησαμένων τελευταῖος ὁ Ἀρσακόμας αἰτήσας τὴν φιάλην οὐκ ἔσπεισεν, οὐ γὰρ ἔθος ἡμῖν ἐκχεῖν τὸν οἶνον, ἀλλὰ ὕβρις εἶναι δοκεῖ τοῦτο εἰς τὸν θεόν· πιὼν δὲ ἀμυστί, “δός μοι,” εἶπεν, “ὦ βασιλεῦ, τὴν θυγατέρα σου Μαζαίαν γυναῖκα ἔχειν πολὺ ἐπιτηδειοτέρῳ τούτων ὄντι ὁπόσα γε ἐπὶ τῷ πλούτῳ καὶ τοῖς κτήμασι.” τοῦ δὲ Λευκάνορος θαυμάσαντος — ἠπίστατο γὰρ πένητα τὸν Ἀρσακόμαν καὶ Σκυθῶν τῶν πολλῶν — καὶ ἐρομένου, “πόσα δὲ βοσκήματα ἢ πόσας ἁμάξας ἔχεις, ὦ Ἀρσακόμα; ταῦτα γὰρ ὑμεῖς πλουτεῖτε,” “ἀλλ’ οὐχ ἁμάξας,” ἔφη, “ἔχω οὐδὲ ἀγέλας, ἀλλ’ εἰσί μοι δύο φίλοι καλοὶ καὶ ἀγαθοὶ οἷοι οὐκ ἄλλῳ Σκυθῶν.”", "st": "44.45"}, {"sp": "N", "t": "Τότε μὲν οὖν ἐγελάσθη ἐπὶ τούτοις καὶ παρώφθη καὶ μεθύειν ἔδοξεν, ἕωθεν δὲ προκριθεὶς τῶν ἄλλων Ἀδύρμαχος ἔμελλεν ἀπάξειν τὴν νύμφην παρὰ τὴν Μαιῶτιν ἐς τοὺς Μάχλυας.", "st": "44.45"}, {"sp": "N", "t": "ὁ δὲ Ἀρσακόμας ἐπανελθὼν οἴκαδε μηνύει τοῖς φίλοις ὡς ἀτιμασθείη ὑπὸ τοῦ βασιλέως καὶ γελασθείη ἐν τῷ συμποσίῳ, πένης εἶναι δόξας. “καίτοι,” ἔφη, “ἐγὼ διηγησάμην αὐτῷ τὸν πλοῦτον ὁπόσος ἐστίν μοι, ὑμᾶς, ὦ Λογχάτα καὶ Μακέντα, καὶ τὴν εὔνοιαν τὴν ὑμετέραν, πολὺ ἀμείνω καὶ βεβαιοτέραν τῆς Βοσπορανῶν δυνάμεως. ἀλλ’ ἐμοῦ ταῦτα διεξιόντος ἡμᾶς μὲν ἐχλεύαζεν καὶ κατεφρόνει, Ἀδυρμάχῳ δὲ τῷ Μάχλυϊ παρέδωκεν ἀπάγειν τὴν νύμφην, ὅτι χρυσᾶς τε φιάλας ἐλέγετο ἔχειν δέκα καὶ ἁμάξας τετρακλίνους ὀγδοήκοντα καὶ πρόβατα καὶ βοῦς πολλούς. οὕτως ἄρα προετίμησεν ἀνδρῶν ἀγαθῶν βοσκήματα πολλὰ καὶ ἐκπώματα περίεργα καὶ ἁμάξας βαρείας.", "st": "44.46"}, {"sp": "N", "t": "ἐγὼ δέ, ὦ φίλοι, δι’ ἀμφότερα ἀνιῶμαι· καὶ γὰρ ἐρῶ τῆς Μαζαίας, καὶ ἡ ὕβρις ἐν τοσούτοις ἀνθρώποις οὐ μετρίως μου καθίκετο. οἶμαι δὲ καὶ ὑμᾶς ἐπ’ ἴσης ἠδικῆσθαι· τὸ γὰρ τρίτον μετῆν ἑκάστῳ ἡμῶν τῆς ἀτιμίας, εἴ γε οὕτω βιοῦμεν ὡς ἀφ’ οὗ συνεληλύθαμεν εἷς ἄνθρωπος ὄντες καὶ τὰ αὐτὰ ἀνιώμενοι καὶ τὰ αὐτὰ χαίροντες.” “οὐ μόνον,” ἐπεῖπεν ὁ Λογχάτης, “ἀλλὰ ἕκαστος ἡμῶν ὅλος ὕβρισται, ὁπότε σὺ τοιαῦτα ἔπαθες.”", "st": "44.46"}, {"sp": "N", "t": "“πῶς οὖν,” ὁ Μακέντης ἔφη, “χρησόμεθα τοῖς παροῦσι; ’” “διελώμεθα,” ἔφη ὁ Λογχάτης, “τὸ ἔργον· καὶ ἐγὼ μὲν ὑπισχνοῦμαι Ἀρσακόμᾳ τὴν κεφαλὴν κομιεῖν τὴν Λευκάνορος, σὲ δὲ χρὴ τὴν νύμφην ἐπανάγειν αὐτῷ.” “οὕτω γινέσθω,” ἔφη· “σὺ δέ, ὦ Ἀρσακόμα, ἐν τοσούτῳ — εἰκὸς γὰρ καὶ στρατιᾶς καὶ πολέμου τὸ μετὰ τοῦτο δεήσειν — ἡμᾶς αὐτοῦ περιμένων συνάγειρε καὶ παρασκεύαζε ὅπλα καὶ ἵππους καὶ τὴν ἄλλην δύναμιν ὡς πλείστην. ῥᾷστα δ’ ἂν πολλοὺς προσαγάγοις αὐτός τε ἀγαθὸς ὢν καὶ ἡμῖν οὐκ ὀλίγων ὄντων οἰκείων, μάλιστα δὲ εἰ καθέζοιο ἐπὶ τῆς βύρσης τοῦ βοός.” ἔδοξε ταῦτα, καὶ ὁ μὲν ἐχώρει ὡς εἶχεν εὐθὺς ἐπὶ τοῦ Βοσπόρου, ὁ Λογχάτης, ὁ Μακέντης δὲ ἐπὶ τοὺς Μάχλυας, ἱππότης ἑκάτερος, ὁ δὲ Ἀρσακόμας οἴκοι μένων τοῖς τε ἡλικιώταις διελέγετο καὶ ὥπλιζε δύναμιν παρὰ τῶν οἰκείων, τέλος δὲ καὶ ἐπὶ τῆς βύρσης ἐκαθέζετο.", "st": "44.47"}, {"sp": "N", "t": "τὸ δὲ ἔθος ἡμῖν τὸ περὶ τὴν βύρσαν οὕτως ἔχει· ἐπειδὰν ἀδικηθείς τις πρὸς ἑτέρου, ἀμύνασθαι βουλόμενος, ἴδῃ καθ’ ἑαυτὸν οὐκ ἀξιόμαχος ὤν, βοῦν ἱερεύσας τὰ μὲν κρέα κατακόψας ἥψησεν, αὐτὸς δὲ ἐκπετάσας χαμαὶ τὴν βύρσαν κάθηται ἐπ’ αὐτῆς, εἰς τοὐπίσω παραγαγὼν τὼ χεῖρε ὥσπερ οἱ ἐκ τῶν ἀγκώνων δεδεμένοι. καὶ τοῦτό ἐστιν ἡμῖν ἡ μεγίστη ἱκετηρία. παρακειμένων δὲ τῶν κρεῶν τοῦ βοὸς προσιόντες οἱ οἰκεῖοι καὶ τῶν ἄλλων ὁ βουλόμενος μοῖραν ἕκαστος λαβὼν ἐπιβὰς τῇ βύρσῃ τὸν δεξιὸν πόδα ὑπισχνεῖται κατὰ δύναμιν, ὁ μὲν πέντε ἱππέας παρέξειν ἀσίτους καὶ ἀμίσθους, ὁ δὲ δέκα, ὁ δὲ πλείους, ὁ δὲ ὁπλίτας ἢ πεζοὺς ὁπόσους ἂν δύνηται, ὁ δὲ μόνον ἑαυτόν, ὁ πενέστατος. ἀθροίζεται οὖν ἐπὶ τῆς βύρσης πολὺ πλῆθος ἐνίοτε, καὶ τὸ τοιοῦτο σύνταγμα βεβαιότατόν τέ ἐστι συμμεῖναι καὶ ἀπρόσμαχον τοῖς ἐχθροῖς ἅτε καὶ ἔνορκον ὄν· τὸ γὰρ ἐπιβῆναι τῆς βύρσης ὅρκος ἐστίν.", "st": "44.48"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἀρσακόμας ἐν τούτοις ἦν, καὶ ἠθροίσθησαν αὐτῷ ἱππεὶς μὲν ἀμφὶ τοὺς πεντακισχιλίους, ὁπλῖται δὲ καὶ πεζοὶ συναμφότεροι δισμύριοι.", "st": "44.48"}, {"sp": "N", "t": "ὁ δὲ Λογχάτης ἀγνοούμενος παρελθὼν ἐς τὸν Βόσπορον προσέρχεται τῷ βασιλεῖ διοικουμένῳ τι τῆς ἀρχῆς καὶ φησὶν ἥκειν μὲν ἀπὸ τοῦ κοινοῦ τῶν Σκυθῶν, ἰδίᾳ δὲ αὐτῷ μεγάλα πράγματα κομίζων. τοῦ δὲ λέγειν κελεύσαντος, “οἱ μὲν Σκύθαι,” φησίν, “τὰ κοινὰ ταῦτα καὶ τὰ καθ’ ἡμέραν ἀξιοῦσιν, μὴ ὑπερβαίνειν τοὺς νομέας ὑμῶν ἐς τὸ πεδίον ἀλλὰ μέχρι τοῦ τράχωνος νέμειν· τοὺς δὲ λῃστὰς οὓς αἰτιᾶσθε ὡς κατατρέχοντας ὑμῶν τὴν χώραν οὐ φασὶν ἀπὸ κοινῆς γνώμης ἐκπέμπεσθαι, ἀλλὰ ἰδίᾳ ἕκαστον ἐπὶ τῷ κέρδει κλωπεύειν· εἰ δέ τις ἁλίσκοιτο αὐτῶν, σὲ κύριον εἶναι κολάζειν. ταῦτα μὲν ἐκεῖνοι ἐπεστάλκασιν,", "st": "44.49"}, {"sp": "N", "t": "ἐγὼ δὲ μηνύω σοι μεγάλην ἔφοδον ἐσομένην ἐφ’ ὑμᾶς ὑπ’ Ἀρσακόμα τοῦ Μαριάντα, ὃς ἐπρέσβευε πρῴην παρὰ σὲ καί, οἶμαι, διότι αἰτήσας τὴν θυγατέρα οὐκ ἔτυχε παρὰ σοῦ, ἀγανακτεῖ καὶ ἐπὶ τῆς βύρσης ἑβδόμην ἡμέραν ἤδη κάθηται καὶ συνῆκται στρατὸς οὐκ ὀλίγος αὐτῷ.”", "st": "44.50"}, {"sp": "N", "t": "“ἤκουσα,” ἔφη ὁ Λευκάνωρ, “καὶ αὐτὸς ἀθροίζεσθαι δύναμιν ἀπὸ βύρσης, ὅτι δ’ ἐφ’ ἡμᾶς συνίσταται καὶ ὅτι Ἀρσακόμας ὁ ἐλαύνων ἐστὶν ἠγνόουν.” “ἀλλ’ ἐπὶ σέ,” ἔφη ὁ Λογχάτης, “ἡ παρασκευή. ἐμοὶ δὲ ἐχθρὸς ὁ Ἀρσακόμας ἐστί, καὶ ἄχθεται διότι προτιμῶμαι αὐτοῦ ὑπὸ τῶν γεραιτέρων καὶ ἀμείνων τὰ πάντα δοκῶ εἶναι· εἰ δέ μοι ὑπόσχοιο τὴν ἑτέραν σου θυγατέρα Βαρκέτιν, οὐδὲ τὰ ἄλλα ἀναξίῳ ὑμῶν ὄντι, οὐκ εἰς μακράν σοι ἥξω τὴν κεφαλὴν αὐτοῦ κομίζων.” “ὑπισχνοῦμαι,” ἔφη ὁ βασιλεύς, μάλα περιδεὴς γενόμενος· ἔγνω γὰρ τὴν αἰτίαν τῆς ὀργῆς τῆς Ἀρσακόμα τὴν ἐπὶ τῷ γάμῳ, καὶ ἄλλως ὑπέπτησσεν ἀεὶ τοὺς Σκύθας.", "st": "44.50"}, {"sp": "N", "t": "ὁ δὲ Λογχάτης, “ὄμοσον,” εἶπεν, “ἦ μὴν φυλάξειν τὰς συνθήκας, μηδὲ ἀπαρνήσεσθαι τότε ἤδη, τούτων γενομένων.” καὶ ἐπεὶ ἀνατείνας εἰς τὸν οὐρανὸν ἤθελεν ὀμνύειν, “μὴ σύ γε ἐνταῦθα,” εἶπεν, “μὴ καί τις ὑπίδηται τῶν ὁρώντων ἐφ’ ὅτῳ ὁρκωμοτοῦμεν, ἀλλὰ εἰς τὸ ἱερὸν τοῦ Ἄρεως τουτὶ εἰσελθόντες, ἐπικλεισάμενοι τὰς θύρας ὀμνύωμεν, ἀκουσάτω δὲ μηδείς· εἰ γάρ τι τούτων πύθοιτο Ἀρσακόμας, δέδια μὴ προθύσηται με τοῦ πολέμου, χεῖρα οὐ μικρὰν ἤδη περιβεβλημένος.” “εἰσίωμεν,” ἔφη ὁ βασιλεύς, “ὑμεῖς δὲ ἀπόστητε ὅτι πορρωτάτω· μηδεὶς δὲ παρέστω ἐς τὸν νεὼν ὅντινα μὴ ἐγὼ καλέσω.”", "st": "44.50"}, {"sp": "N", "t": "Ἐπεὶ δὲ οἱ μὲν εἰσῆλθον, οἱ δορυφόροι δὲ ἀπέστησαν, σπασάμενος τὸν ἀκινάκην, ἐπισχὼν τῇ ἑτέρᾳ τὸ στόμα ὡς μὴ βοήσειε, παίει παρὰ τὸν μαστόν, εἶτα ἀποτεμὼν τὴν κεφαλὴν ὑπὸ τῇ χλαμύδι ἔχων ἐξῄει, μεταξὺ διαλεγόμενος δῆθεν αὐτῷ καὶ διὰ ταχέων ἥξειν λέγων, ὡς δὴ ἐπί τι πεμφθεὶς ὑπ’ ἐκείνου. καὶ οὕτως ἐπὶ τὸν τόπον ἀφικόμενος ἔνθα καταδεδεμένον καταλελοίπει τὸν ἵππον, ἀναβὰς ἀφιππάσατο εἰς τὴν Σκυθίαν. δίωξις δὲ οὐκ ἐγένετο αὐτοῦ, ἐπὶ πολὺ ἀγνοησάντων τὸ γεγονὸς τῶν Βοσπορανῶν, καὶ ὅτε ἔγνωσαν, ὑπὲρ τῆς βασιλείας στασιαζόντων.", "st": "44.50"}, {"sp": "N", "t": "ταῦτα μὲν ὁ Λογχάτης ἔπραξεν καὶ τὴν ὑπόσχεσιν ἀπεπλήρωσεν τῷ Ἀρσακόμᾳ παραδοὺς τὴν κεφαλὴν τοῦ Λευκάνορος. ὁ Μακέντης δὲ καθ’ ὁδὸν ἀκούσας τὰ ἐν Βοσπόρῳ γενόμενα ἧκεν εἰς τοὺς Μάχλυας καὶ πρῶτος ἀγγείλας αὐτοῖς τὸν φόνον τοῦ βασιλέως, “ἡ πόλις δέ,” ἔφη, “ὦ Ἀδύρμαχε, σὲ γαμβρὸν ὄντα ἐπὶ τὴν βασιλείαν καλεῖ· ὥστε σὺ μὲν προελάσας παραλάμβανε τὴν ἀρχήν, τεταραγμένοις τοῖς πράγμασιν ἐπιφανείς, ἡ κόρη δέ σοι κατόπιν ἐπὶ τῶν ἁμαξῶν ἑπέσθω· ῥᾷον γὰρ οὕτω προσάξεις Βοσπορανῶν τοὺς πολλούς, ἰδόντας τὴν Λευκάνορος θυγατέρα. ἐγὼ δὲ Ἀλανός τέ εἰμι καὶ τῇ παιδὶ ταύτῃ συγγενὴς μητρόθεν· παρ’ ἡμῶν γὰρ οὖσαν τὴν Μάστειραν ἠγάγετο ὁ Λευκάνωρ. καὶ νῦν σοι ἥκω παρὰ τῶν Μαστείρας ἀδελφῶν τῶν ἐν Ἀλανίᾳ παρακελευομένων ὅτι τάχιστα ἐλαύνειν ἐπὶ τὸν Βόσπορον καὶ μὴ περιιδεῖν ἐς Εὐβίοτον περιελθοῦσαν τὴν ἀρχήν, ὃς ἀδελφὸς ὢν νόθος Λευκάνορος Σκύθαις μὲν ἀεὶ φίλος ἐστίν, Ἀλανοῖς δὲ ἀπέχθεται.” Ταῦτα δὲ ἔλεγεν ὁ Μακέντης ὁμόσκευος καὶ ὁμόγλωττος τοῖς Ἀλανοῖς ὤν· κοινὰ γὰρ ταῦτα Ἀλανοῖς καὶ Σκύθαις, πλὴν ὅτι οὐ πάνυ κομῶσιν οἱ Ἀλανοὶ ὥσπερ οἱ Σκύθαι. ἀλλὰ ὁ Μακέντης καὶ τοῦτο εἴκαστο αὐτοῖς καὶ ἀποκεκάρκει τῆς κόμης ὁπόσον εἰκὸς ἦν ἔλαττον κομᾶν τὸν Ἀλανὸν τοῦ Σκύθου· ὥστε ἐπιστεύετο διὰ ταῦτα καὶ ἐδόκει Μαστείρας καὶ Μαζαίας συγγενὴς εἶναι.", "st": "44.51"}, {"sp": "N", "t": "“καὶ νῦν,” ἔφη, “ὦ Ἀδύρμαχε, ἐλαύνειν τε ἕτοιμος ἅμα σοι ἐπὶ τὸν Βόσπορον, ἢν ἐθέλῃς, μένειν τε, εἰ δέοι, καὶ τὴν παῖδα ἄγειν.” “τοῦτο,” ἔφη, “καὶ μᾶλλον,” ὁ Ἀδύρμαχος, “ἐθελήσαιμ’ ἄν, ἀφ’ αἵματος ὄντα σε Μαζαίαν ἄγειν. ἢν μὲν γὰρ ἅμα ἡμῖν ἴῃς ἐπὶ Βόσπορον, ἱππεῖ ἑνὶ πλείους ἂν γενοίμεθα· εἰ δέ μοι τὴν γυναῖκα ἄγοις, ἀντὶ πολλῶν ἂν γένοιο.” Ταῦτα ἐγίνετο καὶ ὁ μὲν ἀπήλαυνε παραδοὺς τῷ Μακέντῃ ἄγειν τὴν Μαζαίαν παρθένον ἔτι οὖσαν. ὁ δὲ ἡμέρας μὲν ἐπὶ τῆς ἁμάξης ἦγεν αὐτήν, ἐπεὶ δὲ νὺξ κατέλαβεν, ἀναθέμενος ἐπὶ τὸν ἵππον — ἐτεθεραπεύκει δὲ ἕνα σφίσιν ἄλλον ἱππέα ἕπεσθαι — ἀναπηδήσας καὶ αὐτὸς οὐκέτι παρὰ τὴν Μαιῶτιν ἤλαυνεν, ἀλλ’ ἀποτραπόμενος εἰς τὴν μεσόγειαν ἐν δεξιᾷ λαβὼν τὰ Μιτραίων ὄρη, διαναπαύων μεταξὺ τὴν παῖδα, τριταῖος ἐτέλεσεν ἐκ Μαχλύων ἐς Σκύθας. καὶ ὁ μὲν ἵππος αὐτῷ, ἐπειδὴ ἐπαύσατο τοῦ δρόμου, μικρὸν ἐπιστὰς ἀποθνήσκει,", "st": "44.52"}, {"sp": "N", "t": "ὁ δὲ Μακέντης ἐγχειρίσας τὴν Μαζαίαν τῷ Ἀρσακόμᾳ, “δέδεξο” εἶπεν, “καὶ παρ’ ἐμοῦ τὴν ὑπόσχεσιν.”", "st": "44.53"}, {"sp": "N", "t": "Τοῦ δὲ πρὸς τὸ ἀνέλπιστον τοῦ θεάματος καταπλαγέντος καὶ χάριν ὁμολογοῦντος, “παῦε,” ἔφη ὁ Μακέντης, “ἄλλον με ποιῶν σεαυτοῦ· τὸ γὰρ χάριν ἐμοὶ ὁμολογεῖν ἐφ’ οἷς ἔπραξα τούτοις τοιόνδε ἐστὶν ὥσπερ ἂν εἰ ἡ ἀριστερά μου χάριν εἰδείη τῇ δεξιᾷ διότι τρωθεῖσάν ποτε αὐτὴν ἐθεράπευσε καὶ φιλοφρόνως ἐπεμελήθη καμνούσης. γελοῖα τοίνυν καὶ ἡμεῖς ἂν ποιοῖμεν εἰ πάλαι ἀναμιχθέντες καὶ ὡς οἷόν τε ἦν εἰς ἕνα συνελθόντες ἔτι μέγα νομίζοιμεν εἶναι εἰ τὸ μέρος ἡμῶν ἔπραξέ τι χρηστὸν ὑπὲρ ὅλου τοῦ σώματος· ὑπὲρ αὑτοῦ γὰρ ἔπραττεν, μέρος ὂν τοῦ ὅλου εὖ πάσχοντος.”", "st": "44.53"}, {"sp": "N", "t": "Οὕτως μὲν ὁ Μακέντης ἔφη τῷ Ἀρσακόμᾳ χάριν ὁμολογήσαντι.", "st": "44.53"}, {"sp": "N", "t": "ὁ δὲ Ἀδύρμαχος ὡς ἤκουσε τὴν ἐπιβουλήν, εἰς μὲν τὸν Βόσπορον οὐκέτι ἦλθεν — ἤδη γὰρ Εὐβίοτος ἦρχεν, ἐπικληθεὶς ἐκ Σαυροματῶν, παρ’ οἷς διέτριβεν — εἰς δὲ τὴν αὑτοῦ ἐπανελθὼν καὶ στρατιὰν πολλὴν συναγαγὼν διὰ τῆς ὀρεινῆς εἰσέβαλεν εἰς τὴν Σκυθίαν· καὶ ὁ Εὐβίοτος οὐ μετὰ πολὺ καὶ οὗτος εἰσέπεσεν ἄγων πανδημεὶ μὲν τοὺς Ἕλληνας, Ἀλανοὺς δὲ καὶ Σαυρομάτας ἐπικλήτους ἑκατέρους δισμυρίους. ἀναμίξαντες δὲ τὰ στρατεύματα ὁ Εὐβίοτος καὶ ὁ Ἀδύρμαχος, ἐννέα μυριάδες ἅπαντες ἐγένοντο καὶ τούτων τὸ τρίτον ἱπποτοξόται.", "st": "44.54"}, {"sp": "N", "t": "ἡμεῖς δὲ — καὶ γὰρ αὐτὸς μετέσχον τῆς ἐξόδου αὐτοῖς, ἐπιδοὺς ἐν τῇ βύρσῃ τότε ἱππέας αὐτοτελεῖς ἑκατόν — οὐ πολλῷ ἔλαττον τῶν τρισμυρίων σὺν τοῖς ἱππεῦσιν ἀθροισθέντες ὑπεμένομεν τὴν ἔφοδον· ἐστρατήγει δὲ ὁ Ἀρσακόμας. καὶ ἐπειδὴ προσιόντας εἴδομεν αὐτούς, ἀντεπήγομεν, προεπαφέντες τὸ ἱππικόν. γενομένης δὲ ἐπὶ πολὺ μάχης καρτερᾶς ἐνεδίδου ἤδη τὰ ἡμέτερα καὶ παρερρήγνυτο ἡ φάλαγξ, καὶ τέλος εἰς δύο διεκόπη τὸ Σκυθικὸν ἅπαν, καὶ τὸ μὲν ὑπέφευγεν, οὐ πάνυ σαφῶς ἡττημένον, ἀλλ’ ἀναχώρησις ἐδόκει ἡ φυγή· οὐδὲ γὰρ οἱ Ἀλανοὶ ἐτόλμων ἐπὶ πολὺ διώκειν. τὸ δὲ ἥμισυ, ὅπερ καὶ ἔλαττον, περισχόντες οἱ Ἀλανοὶ καὶ Μάχλυες ἔκοπτον πανταχόθεν ἀφθόνως ἀφιέντες τῶν ὀϊστῶν καὶ ἀκοντίων, ὥστε πάνυ ἐπονοῦντο ἡμῶν οἱ περιεσχημένοι, καὶ ἤδη προΐεντο οἱ πολλοὶ τὰ ὅπλα.", "st": "44.54"}, {"sp": "N", "t": "ἐν τούτοις δὲ καὶ ὁ Λογχάτης καὶ ὁ Μακέντης ἔτυχον ὄντες καὶ ἐτέτρωντο ἤδη προκινδυνεύοντες, ὁ μὲν στυρακίῳ εἰς τὸν μηρόν, ὁ Λογχάτης, ὁ Μακέντης δὲ πελέκει εἰς τὴν κεφαλὴν καὶ κοντῷ εἰς τὸν ὦμον. ὅπερ αἰσθόμενος ὁ Ἀρσακόμας, ἐν ἡμῖν τοῖς ἄλλοις ὤν, δεινὸν ἡγησάμενος εἰ ἄπεισι καταλιπὼν τοὺς φίλους, προσβαλὼν τοὺς μύωπας τῷ ἵππῳ ἐμβοήσας ἤλαυνε διὰ τῶν πολεμίων κοπίδα διηρμένος, ὥστε τοὺς Μάχλυας μηδὲ ὑποστῆναι τὸ ῥόθιον τοῦ θυμοῦ, ἀλλὰ διαιρεθέντες ἔδωκαν αὐτῷ διεξελθεῖν.", "st": "44.55"}, {"sp": "N", "t": "Ὁ δὲ ἀνακτησάμενος τοὺς φίλους καὶ τοὺς ἄλλους ἅπαντας παρακαλέσας ὥρμησεν ἐπὶ τὸν Ἀδύρμαχον καὶ πατάξας τῇ κοπίδι παρὰ τὸν αὐχένα μέχρι τῆς ζώνης διέτεμεν. πεσόντος δὲ ἐκείνου διελύθη τὸ Μαχλυϊκὸν ἅπαν, καὶ τὸ Ἀλανικὸν οὐ μετὰ πολύ, καὶ οἱ Ἕλληνες ἐπὶ τούτοις· ὥστε ἐκρατοῦμεν ἐξ ὑπαρχῆς ἡμεῖς καὶ ἐπεξήλθομεν ἂν ἐπὶ πολὺ κτείνοντες, εἰ μὴ νὺξ τὸ ἔργον ἀφείλετο.", "st": "44.55"}, {"sp": "N", "t": "εἰς δὲ τὴν ἐπιοῦσαν ἱκέται παρὰ τῶν πολεμίων ἥκοντες ἐδέοντο φιλίαν ποιεῖσθαι, Βοσπορανοὶ μὲν ὑποτελέσειν διπλάσιον τὸν δασμὸν ὑπισχνούμενοι, Μάχλυες δὲ ὁμήρους δώσειν ἔφασαν, οἱ Ἀλανοὶ δὲ ἀντὶ τῆς ἐφόδου ἐκείνης Σινδιανοὺς ἡμῖν χειρώσασθαι ὑπέστησαν ἐκ πολλοῦ διεστῶτας. ἐπὶ τούτοις ἐπείσθημεν, δόξαν πολὺ πρότερον Ἀρσακόμᾳ καὶ Λογχάτῃ, καὶ ἐγένετο εἰρήνη ἐκείνων πρυτανευόντων ἕκαστα.", "st": "44.55"}, {"sp": "N", "t": "τοιαῦτα, ὦ Μνήσιππε, τολμῶσιν ποιεῖν Σκύθαι ὑπὲρ τῶν φίλων.", "st": "44.55"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> πάνυ τραγικά, ὦ Τόξαρι, καὶ μύθοις ὅμοια· καὶ ἵλεως μὲν ὁ Ἀκινάκης καὶ ὁ Ἄνεμος εἶεν, οὓς ὤμοσας· εἰ δ’ οὖν τις ἀπιστοίη αὐτοῖς, οὐ πάνυ μεμπτὸς εἶναι δόξειεν ἄν.", "st": "44.56"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> ἀλλ’ ὅρα, ὦ γενναῖε, μὴ φθόνος ὑμῶν ἡ ἀπιστία ᾖ. πλὴν οὐκ ἐμὲ ἀποτρέψεις ἀπιστῶν καὶ ἄλλα τοιαῦτα εἰπεῖν ἃ οἶδα ὑπὸ Σκυθῶν γενόμενα.", "st": "44.56"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> μὴ μακρὰ μόνον, ὦ ἄριστε, μηδὲ οὕτως ἀφέτοις χρώμενος τοῖς λόγοις· ὡς νῦν γε, ἄνω καὶ κάτω τὴν Σκυθίαν καὶ τὴν Μαχλυανὴν διαθέων καὶ εἰς τὸν Βόσπορον ἀπιών, εἶτ’ ἐπανιών, πάνυ μου κατεχρήσω τῇ σιωπῇ.", "st": "44.56"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> πειστέον καὶ ταῦτά σοι νομοθετοῦντι καὶ διὰ βραχέων λεκτέον, μὴ καὶ κάμῃς ἡμῖν τῇ ἀκοῇ συμπερινοστῶν.", "st": "44.56"}, {"sp": "N", "t": "μᾶλλον δὲ ἄκουσον ἐμοὶ αὐτῷ οἷα φίλος, Σισίννης τοὔνομα, ὑπηρέτησεν.", "st": "44.57"}, {"sp": "N", "t": "Ὅτε γὰρ Ἀθήναζε ἀπῄειν οἴκοθεν ἐπιθυμίᾳ παιδείας τῆς Ἑλληνικῆς, κατέπλευσα ἐς Ἄμαστριν τὴν Ποντικήν· ἐν προσβολῇ δέ ἐστιν τοῖς ἀπὸ Σκυθίας προσπλέουσιν, οὐ πολὺ τῆς Καράμβεως ἀπέχουσα, ἡ πόλις. εἵπετο δὲ ὁ Σισίννης ἑταῖρος ἐκ παιδὸς ὤν. ἡμεῖς μὲν οὖν καταγωγήν τινα ἐπὶ τῷ λιμένι σκεψάμενοι κἀκ τοῦ πλοίου ἐς αὐτὴν μετασκευασάμενοι ἠγοράζομεν, οὐδὲν πονηρὸν ὑφορώμενοι· ἐν τοσούτῳ δὲ κλῶπές τινες ἀνασπάσαντες τὸ κλεῖστρον ἐκφέρουσιν ἅπαντα, ὡς μηδὲ τὰ ἐς ἐκείνην τὴν ἡμέραν διαρκέσοντα καταλιπεῖν.", "st": "44.57"}, {"sp": "N", "t": "ἐπανελθόντες οὖν οἶκαδε καὶ τὸ γεγονὸς μαθόντες, δικάζεσθαι μὲν τοῖς γείτοσι πολλοῖς οὖσιν ἢ τῷ ξένῳ οὐκ ἐδοκιμάζομεν, δεδιότες μὴ συκοφάνται δόξωμεν τοῖς πολλοῖς λέγοντες ὡς ὑφείλετο ἡμῶν τις δαρεικοὺς τετρακοσίους καὶ ἐσθῆτα πολλὴν καὶ δάπιδάς τινας καὶ τὰ ἄλλα ὁπόσα εἴχομεν·", "st": "44.57"}, {"sp": "N", "t": "ἐσκοπούμεθα δὲ περὶ τῶν παρόντων ὅ τι πράξομεν, ἄποροι παντάπασιν ἐν τῇ ἀλλοδαπῇ γενόμενοι. κἀμοὶ μὲν ἐδόκει ὡς εἶχον αὐτοῦ παραβύσαντα ἐς τὴν πλευρὰν τὸν ἀκινάκην ἀπελθεῖν τοῦ βίου πρὶν ἀγεννές τι ὑποστῆναι λιμῷ ἢ δίψει πιεσθέντα, ὁ δὲ Σισίννης παρεμυθεῖτο καὶ ἱκέτευεν μηδὲν τοιοῦτο ποιεῖν· αὐτὸς γὰρ ἐπινοήσειν ὅθεν ἕξομεν ἱκανῶς τὰς τροφάς.", "st": "44.58"}, {"sp": "N", "t": "καὶ τότε μὲν ξύλα ἐκ τοῦ λιμένος παρεκόμισεν καὶ ἧκεν ἡμῖν ἀπὸ τοῦ μισθοῦ ἐπισιτισάμενος· ἕωθεν δὲ περιιὼν κατὰ τὴν ἀγορὰν εἶδε προπομπήν τινα, ὡς ἔφη, γενναίων καὶ καλῶν νεανίσκων. μονομαχεῖν δὲ οὗτοι ἐπὶ μισθῷ ἀνδρολογηθέντες εἰς τρίτην ἡμέραν διαγωνιεῖσθαι ἔμελλον. καὶ δὴ τὸ πᾶν ὡς εἶχεν ἀμφ’ αὐτοὺς πυθόμενος, ἐλθὼν ὡς ἐμέ, “μηκέτι, ὦ Τόξαρι,” ἔφη, “σαυτὸν πένητα λέγε, εἰς γὰρ τρίτην ἡμέραν πλούσιόν σε ἀποφανῶ.”", "st": "44.58"}, {"sp": "N", "t": "Ταῦτα εἶπε, καὶ πονηρῶς τὸ μεταξὺ ἀποζήσαντες, ἐνστάσης ἤδη τῆς θέας ἐθεώμεθα καὶ αὐτοί· παραλαβὼν γάρ με ὡς ἐπὶ τερπνόν τι καὶ παράδοξον θέαμα τῶν Ἑλληνικῶν ἄγει εἰς τὸ θέατρον. καὶ καθίσαντες ἑωρῶμεν τὸ μὲν πρῶτον θηρία κατακοντιζόμενα καὶ ὑπὸ κυνῶν διωκόμενα καὶ ἐπ’ ἀνθρώπους δεδεμένους ἀφιέμενα, κακούργους τινάς, ὡς εἰκάζομεν. ἐπεὶ δὲ εἰσῆλθον οἱ μονομάχοι καί τινα παραγαγὼν ὁ κῆρυξ εὐμεγέθη νεανίσκον εἶπεν, ὅστις ἂν ἐθέλῃ τούτῳ μονομαχῆσαι, ἥκειν εἰς τὸ μέσον δραχμὰς ληψόμενον μυρίας μισθὸν τῆς μάχης, ἐνταῦθα ἐξανίσταται ὁ Σισίννης καὶ καταπηδήσας ὑπέστη μαχεῖσθαι καὶ τὰ ὅπλα ᾔτει, καὶ τὸν μισθὸν λαβών, τὰς μυρίας ἐμοὶ φέρων ἐνεχείρισε, καὶ “εἰ μὲν κρατήσαιμι, ὦ Τόξαρι,” εἶπεν, “ἅμα ἄπιμεν ἔχοντες τὰ ἀρκοῦντα, ἢν δὲ πέσω, θάψας με ὑποχώρει ὀπίσω ἐς Σκύθας.”", "st": "44.59"}, {"sp": "N", "t": "ἐγὼ μὲν ἐπὶ τούτοις ἐκώκυον, ὁ δὲ λαβὼν τὰ ὅπλα τὰ μὲν ἄλλα περιεδήσατο, τὸ κράνος δὲ οὐκ ἐπέθηκεν, ἀλλ’ ἀπὸ γυμνῆς τῆς κεφαλῆς καταστὰς ἐμάχετο. καὶ τὸ μὲν πρῶτον τιτρώσκεται αὐτός, καμπύλῳ τῷ ξίφει ὑποτμηθεὶς τὴν ἰγνύαν, ὥστε αἷμα ἔρρει πολύ· ἐγὼ δὲ προετεθνήκειν ἤδη τῷ δέει. θρασύτερον δὲ ἐπιφερόμενον τηρήσας τὸν ἀντίπαλον παίει εἰς τὸ στέρνον καὶ διήλασεν, ὥστε αὐτίκα ἐπεπτώκει πρὸ τοῖν ποδοῖν αὐτοῦ. ὁ δὲ κάμνων καὶ αὐτὸς ἀπὸ τοῦ τραύματος ἐπεκάθιζε τῷ νεκρῷ, καὶ μικροῦ δεῖν ἀφῆκεν αὐτὸν ἡ ψυχή, ἀλλ’ ἐγὼ προσδραμὼν ἀνέστησα καὶ παρεμυθησάμην. ἐπεὶ δὲ ἀφεῖτο ἤδη νενικηκώς, ἀράμενος αὐτὸν ἐκόμισα εἰς τὴν οἰκίαν· καὶ ἐπὶ πολὺ θεραπευθεὶς ἐπέζησε μὲν καὶ ἔστι μέχρι νῦν ἐν Σκύθαις, γήμας τὴν ἐμὴν ἀδελφήν· χωλὸς δέ ἐστιν ὅμως ἀπὸ τοῦ τραύματος.", "st": "44.60"}, {"sp": "N", "t": "τοῦτο, ὦ Μνήσιππε, οὐκ ἐν Μάχλυσιν οὐδὲ ἐν Ἀλανίᾳ ἐγένετο, ὡς ἀμάρτυρον εἶναι καὶ ἀπιστεῖσθαι δύνασθαι, ἀλλὰ πολλοὶ πάρεισιν Ἀμαστριανῶν μεμνημένοι τὴν μάχην τοῦ Σισίννου.", "st": "44.60"}, {"sp": "N", "t": "πέμπτον ἔτι σοι τὸ Ἀβαύχα ἔργον διηγησάμενος παύσομαι. ἧκέν ποτε οὗτος ὁ Ἀβαύχας εἰς τὴν Βορυσθενιτῶν πόλιν ἐπαγόμενος καὶ γυναῖκα, ἧς ἤρα μάλιστα, καὶ παιδία δύο· τὸ μὲν ἐπιμαστίδιον ἄρρεν, τὸ δὲ ἕτερον, ἡ κόρη, ἑπτέτις ἦν. συναπεδήμει δὲ καὶ ἑταῖρος αὐτοῦ, Γυνδάνης, οὗτος μὲν καὶ νοσῶν ἀπὸ τραύματος ὃ ἐτέτρωτο κατὰ τὴν ὁδὸν ὑπὸ λῃστῶν ἐπιπεσόντων σφίσι· διαμαχόμενος γὰρ πρὸς αὐτοὺς ἐλαύνεται εἰς τὸν μηρόν, ὥστε οὐδὲ ἑστάναι ἐδύνατο ὑπὸ τῆς ὀδύνης. νύκτωρ δὲ καθευδόντων — ἔτυχον δὲ ἐν ὑπερῴῳ τινὶ οἰκοῦντες — πυρκαϊὰ μεγάλη ἐξανίσταται καὶ πάντα περιεκλείετο καὶ περιεῖχεν ἡ φλὸξ ἁπανταχόθεν τὴν οἰκίαν. ἐνταῦθα δὴ ἀνεγρόμενος ὁ Ἀβαύχας καταλιπὼν τὰ παιδία κλαυθμυριζόμενα καὶ τὴν γυναῖκα ἐκκρεμαννυμένην ἀποσεισάμενος καὶ σώζειν αὑτὴν παρακελευσάμενος, ἀράμενος τὸν ἑταῖρον κατῆλθεν καὶ ἔφθη διεκπαίσας καθ’ ὃ μηδέπω τελέως ἀπεκέκαυτο ὑπὸ τοῦ πυρός. ἡ γυνὴ δὲ φέρουσα τὸ βρέφος εἵπετο, ἀκολουθεῖν κελεύσασα καὶ τὴν κόρην. ἡ δὲ ἡμίφλεκτος ἀφεῖσα τὸ παιδίον ἐκ τῆς ἀγκάλης μόλις διεπήδησε τὴν φλόγα, καὶ ἡ παῖς σὺν αὐτῇ, παρὰ μικρὸν ἐλθοῦσα κἀκείνη ἀποθανεῖν. καὶ ἐπεὶ ὠνείδισέν τις ὕστερον τὸν Ἀβαύχαν διότι προδοὺς τὰ τέκνα καὶ τὴν γυναῖκα ὁ δὲ Γυνδάνην ἐξεκόμισεν, “ἀλλὰ παῖδας μέν,” ἔφη, “καὶ αὖθις ποιήσασθαί μοι ῥᾴδιον, καὶ ἄδηλον εἰ ἀγαθοὶ ἔσονται οὗτοι· φίλον δὲ οὐκ ἂν εὕροιμι ἄλλον ἐν πολλῷ χρόνῳ τοιοῦτον οἷος Γυνδάνης ἐστίν, πεῖράν μοι πολλὴν τῆς εὐνοίας παρεσχημένος.”", "st": "44.61"}, {"sp": "N", "t": "εἴρηκα, ὦ Μνήσιππε, ἀπὸ πολλῶν πέντε τούτους προχειρισάμενος. ἤδη δὲ καιρὸς ἂν εἴη κεκρίσθαι ὁπότερον ἡμῶν ἢ τὴν γλῶτταν ἢ τὴν δεξιὰν ἀποτετμῆσθαι δέοι. τίς οὖν ὁ δικάσων ἐστίν;", "st": "44.62"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> οὐδὲ εἷς· οὐ γὰρ ἐκαθίσαμέν τινα δικαστὴν τοῦ λόγου. ἀλλ’ οἶσθα ὃ δράσωμεν; ἐπειδὴ νῦν ἄσκοπα τετοξεύκαμεν, αὖθις ἑλόμενοι διαιτητὴν ἄλλους ἐπ’ ἐκείνῳ εἴπωμεν φίλους, εἶτα ὃς ἂν ἥττων γένηται, ἀποτετμήσεται τότε, ἢ ἐγὼ τὴν γλῶτταν ἢ σὺ τὴν δεξιάν. ἢ τοῦτο μὲν ἄγροικον, ἐπεὶ δὲ καὶ σὺ φιλίαν ἐπαινεῖν ἔδοξας, ἐγὼ δὲ οὐδὲν ἄλλο ἡγοῦμαι ἀνθρώποις εἶναι τούτου κτῆμα ἄμεινον ἢ κάλλιον, τί οὐχὶ καὶ ἡμεῖς συνθέμενοι πρὸς ἡμᾶς αὐτοὺς φίλοι τε αὐτόθεν εἶναι καὶ εἰσαεὶ ἔσεσθαι ἀγαπῶμεν ἄμφω νικήσαντες, τὰ μέγιστα ἆθλα προσλαβόντες, ἀντὶ μιᾶς γλώττης καὶ μιᾶς δεξιᾶς δύο ἑκάτερος ἐπικτησάμενοι καὶ προσέτι γε καὶ ὀφθαλμοὺς τέτταρας καὶ πόδας τέτταρας καὶ ὅλως διπλᾶ πάντα; τοιοῦτόν τι γάρ ἐστι συνελθόντες δύο ἢ τρεῖς φίλοι, ὁποῖον τὸν Γηρυόνην οἱ γραφεῖς ἐνδείκνυνται, ἄνθρωπον ἑξάχειρα καὶ τρικέφαλον· ἐμοὶ γὰρ δοκεῖν, τρεῖς ἐκεῖνοι ἦσαν ἅμα πράττοντες πάντα, ὥσπερ ἐστὶ δίκαιον φίλους γε ὄντας.", "st": "44.62"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> εὖ λέγεις· καὶ οὕτω ποιῶμεν.", "st": "44.63"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> ἀλλὰ μήτε αἵματος, ὦ Τόξαρι, μήτε ἀκινάκου δεώμεθα τὴν φιλίαν ἡμῖν βεβαιώσοντος· ὁ γὰρ λόγος ὁ παρὼν καὶ τὸ τῶν ὁμοίων ὀρέγεσθαι πολὺ πιστότερα τῆς κύλικος ἐκείνης ἣν πίνετε, ἐπεὶ τά γε τοιαῦτα οὐκ ἀνάγκης ἀλλὰ γνώμης δεῖσθαί μοι δοκεῖ.", "st": "44.63"}, {"sp": "N", "t": "<em>Τόξαρις.<\/em> ἐπαινῶ ταῦτα, καὶ ἤδη ὦμεν φίλοι καὶ ξένοι, ἐμοὶ μὲν σὺ ἐνταῦθα ἐπὶ τῆς Ἑλλάδος, ἐγὼ δὲ σοὶ εἴ ποτε ἐς τὴν Σκυθίαν ἀφίκοιο.", "st": "44.63"}, {"sp": "N", "t": "<em>Μνήσιππος.<\/em> καὶ μήν, εὖ ἴσθι, οὐκ ἂν ὀκνήσαιμι καὶ ἔτι πορρωτέρω ἐλθεῖν, εἰ μέλλω τοιούτοις φίλοις ἐντεύξεσθαι οἷος σύ, ὦ Τόξαρι, διεφάνης ἡμῖν ἀπὸ τῶν λόγων.", "st": "44.63"}, {"sp": "HDR", "t": "Περὶ Ὀρχήσεως"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἐπεὶ τοίνυν, ὦ Κράτων, δεινήν τινα ταύτην κατηγορίαν ἐκ πολλοῦ, οἶμαι, παρεσκευασμένος κατηγόρηκας ὀρχήσεών τε καὶ αὐτῆς ὀρχηστικῆς, καὶ προσέτι ἡμῶν γε τῶν χαιρόντων τῇ τοιαύτῃ θέᾳ ὡς ἐπὶ φαύλῳ καὶ γυναικείῳ πράγματι μεγάλην σπουδὴν ποιουμένων, ἄκουσον ὅσον τοῦ ὀρθοῦ διημάρτηκας καὶ ὡς λέληθας σεαυτὸν τοῦ μεγίστου τῶν ἐν τῷ βίῳ ἀγαθῶν κατηγορῶν. καὶ συγγνώμη σοι εἰ ἐξ ἀρχῆς βίῳ αὐχμηρῷ συζῶν καὶ μόνον τὸ σκληρὸν ἀγαθὸν ἡγούμενος ὑπ’ ἀπειρίας αὐτῶν κατηγορίας ἄξια εἶναι νενόμικας.", "st": "45.1"}, {"sp": "N", "t": "<em>Κράτων.<\/em> ἀνὴρ δὲ τίς ὢν ὅλως, καὶ ταῦτα παιδείᾳ σύντροφος καὶ φιλοσοφίᾳ τὰ μέτρια ὡμιληκώς, ἀφέμενος, ὦ Λυκῖνε, τοῦ περὶ τὰ βελτίω σπουδάζειν καὶ τοῖς παλαιοῖς συνεῖναι κάθηται καταυλούμενος, θηλυδρίαν ἄνθρωπον ὁρῶν ἐσθῆσι μαλακαῖς καὶ ᾄσμασιν ἀκολάστοις ἐναβρυνόμενον καὶ μιμούμενον ἐρωτικὰ γύναια, τῶν πάλαι τὰς μαχλοτάτας, Φαίδρας καὶ Παρθενόπας καὶ Ῥοδόπας τινάς, καὶ ταῦτα πάντα ὑπὸ κρούμασιν καὶ τερετίσμασι καὶ ποδῶν κτύπῳ, καταγέλαστα ὡς ἀληθῶς πράγματα καὶ ἥκιστα ἐλευθέρῳ ἀνδρὶ καὶ οἵῳ σοὶ πρέποντα; ὥστε ἔγωγε πυθόμενος ὡς ἐπὶ τοιαύτῃ θέᾳ σχολάζοις, οὐκ ᾐδέσθην μόνον ὑπὲρ σοῦ ἀλλὰ καὶ ἠνιάθην εἰ Πλάτωνος καὶ Χρυσίππου καὶ Ἀριστοτέλους ἐκλαθόμενος κάθησαι τὸ ὅμοιον πεπονθὼς τοῖς τὰ ὦτα πτερῷ κνωμένοις, καὶ ταῦτα μυρίων ἄλλων ὄντων ἀκουσμάτων καὶ θεαμάτων σπουδαίων, εἰ τούτων τις δέοιτο, τῶν κυκλίων αὐλητῶν καὶ τῶν κιθάρᾳ τὰ ἔννομα προσᾳδόντων, καὶ μάλιστα τῆς σεμνῆς τραγῳδίας καὶ τῆς φαιδροτάτης κωμῳδίας, ἅπερ καὶ ἐναγώνια εἶναι ἠξίωται.", "st": "45.2"}, {"sp": "N", "t": "πολλῆς οὖν, ὦ γενναῖε, τῆς ἀπολογίας σοι δεήσει πρὸς τοὺς πεπαιδευμένους, εἰ βούλει μὴ παντάπασιν ἐκκεκρίσθαι καὶ τῆς τῶν σπουδαίων ἀγέλης ἐξεληλάσθαι. καίτοι τό γε ἄμεινον ἐκεῖνό ἐστιν, οἶμαι, ἀρνήσει τὸ πᾶν ἰάσασθαι καὶ μηδὲ τὴν ἀρχὴν ὁμολογεῖν τι τοιοῦτον παρανενομῆσθαί σοι. πρὸς δ’ οὖν τοὐπιὸν ὅρα ὅπως μὴ λάθῃς ἡμῖν ἐξ ἀνδρὸς τοῦ πάλαι Λυδή τις ἢ Βάκχη γενόμενος, ὅπερ οὐ σὸν ἂν ἔγκλημα εἴη μόνον, ἀλλὰ καὶ ἡμῶν, εἰ μή σε κατὰ τὸν Ὀδυσσέα τοῦ λωτοῦ ἀποσπάσαντες ἐπὶ τὰς συνήθεις διατριβὰς ἐπανάξομεν πρὶν λάθῃς τελέως ὑπὸ τῶν ἐν τῷ θεάτρῳ Σειρήνων κατεσχημένος. καίτοι ἐκεῖναι μὲν τοῖς ὠσὶν μόνοις ἐπεβούλευον καὶ διὰ τοῦτο κηροῦ ἐδέησεν πρὸς τὸν παράπλουν αὐτῶν· σὺ δὲ καὶ δι’ ὀφθαλμῶν ἔοικας ὅλος δεδουλῶσθαι.", "st": "45.3"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> παπαῖ, ὦ Κράτων, ὡς κάρχαρόν τινα ἔλυσας ἐφ’ ἡμᾶς τὸν σαυτοῦ κύνα. πλὴν τό γε παράδειγμα, τὴν τῶν Λωτοφάγων καὶ Σειρήνων εἰκόνα, πάνυ ἀνομοιοτάτην μοι δοκεῖς εἰρηκέναι ὧν πέπονθα, παρ’ ὅσον τοῖς μὲν τοῦ λωτοῦ γευσαμένοις καὶ τῶν Σειρήνων ἀκούσασιν ὄλεθρος ἦν τῆς τε ἐδωδῆς καὶ τῆς ἀκροάσεως τοὐπιτίμιον, ἐμοὶ δὲ πρὸς τῷ τὴν ἡδονὴν παρὰ πολὺ ἡδίω πεφυκέναι καὶ τὸ τέλος ἀγαθὸν ἀποβέβηκεν· οὐ γὰρ εἰς λήθην τῶν οἴκοι οὐδ’ εἰς ἀγνωσίαν τῶν κατ’ ἐμαυτὸν περιίσταμαι, ἀλλ’ εἰ χρὴ μηδὲν ὀκνήσαντα εἰπεῖν, μακρῷ πινυτώτερος καὶ τῶν ἐν τῷ βίῳ διορατικώτερος ἐκ τοῦ θεάτρου σοι ἐπανελήλυθα. μᾶλλον δέ, τὸ τοῦ Ὁμήρου αὐτὸ εἰπεῖν καλόν, ὅτι ὁ τοῦτο ἰδὼν τὸ θέαμα “τερψάμενος νεῖται καὶ πλείονα εἰδώς.”", "st": "45.4"}, {"sp": "N", "t": "<em>Κράτων.<\/em> Ἡράκλεις, ὦ Λυκῖνε, οἷα πέπονθας, ὃς οὐδ’ αἰσχύνῃ ἐπ’ αὐτοῖς, ἀλλὰ καὶ σεμνυνομένῳ ἔοικας. τὸ γοῦν δεινότατον τοῦτό ἐστιν, ὅτι μηδὲ ἰάσεώς τινα ἡμῖν ὑποφαίνεις ἐλπίδα, ἐπαινεῖν τολμῶν τὰ οὕτως αἰσχρὰ καὶ κατάπτυστα.", "st": "45.4"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> εἰπέ μοι, ὦ Κράτων, ταυτὶ δὲ περὶ ὀρχήσεως καὶ τῶν ἐν τῷ θεάτρῳ γινομένων ἰδὼν πολλάκις αὐτὸς ἐπιτιμᾷς, ἢ ἀπείρατος ὢν τοῦ θεάματος ὅμως αἰσχρὸν αὐτὸ καὶ κατάπτυστον, ὡς φής, νομίζεις; εἰ μὲν γὰρ εἶδες, ἐξ ἴσου ἡμῖν καὶ σὺ γεγένησαι· εἰ δὲ μή, ὅρα μὴ ἄλογος ἡ ἐπιτίμησις εἶναί σου δόξῃ καὶ θρασεῖα, κατηγοροῦντος ὧν ἀγνοεῖς.", "st": "45.5"}, {"sp": "N", "t": "<em>Κράτων.<\/em> ἔτι γὰρ τοῦτό μοι τὸ λοιπὸν ἦν, ἐν βαθεῖ τούτῳ τῷ πώγωνι καὶ πολιᾷ τῇ κόμῃ καθῆσθαι μέσον ἐν τοῖς γυναίοις καὶ τοῖς μεμηνόσιν ἐκείνοις θεαταῖς, κροτοῦντά τε προσέτι καὶ ἐπαίνους ἀπρεπεστάτους ἐπιβοῶντα ὀλέθρῳ τινὶ ἀνθρώπῳ ἐς οὐδὲν δέον κατακλωμένῳ.", "st": "45.5"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> συγγνωστά σου ταῦτα, ὦ Κράτων. εἰ δέ μοι πεισθείης ποτὲ καὶ ὅσον πείρας ἕνεκα παράσχοις σεαυτὸν ἀναπετάσας τοὺς ὀφθαλμούς, εὖ οἶδα ὡς οὐκ ἀνάσχοιο ἂν μὴ οὐχὶ πρὸ τῶν ἄλλων θέαν ἐν ἐπιτηδείῳ καταλαμβάνων ὅθεν καὶ ὄψει ἀκριβῶς καὶ ἀκούσῃ ἅπαντα.", "st": "45.5"}, {"sp": "N", "t": "<em>Κράτων.<\/em> μὴ ὥρας ἄρα ἱκοίμην, εἴ τι τοιοῦτον ἀνασχοίμην ποτέ, ἔστ’ ἂν δασύς τε εἴην τὰ σκέλη καὶ τὸ γένειον ἀπαράτιλτος· ὡς νῦν γε καὶ σὲ ἤδη ἐλεῶ τελέως ἡμῖν ἐκβεβακχευμένον.", "st": "45.5"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> βούλει οὖν ἀφέμενος, ὦ ἑταῖρε, τῶν βλασφημιῶν τούτων ἀκοῦσαί μού τι περὶ ὀρχήσεως λέγοντος καὶ τῶν ἐν αὐτῇ καλῶν, καὶ ὡς οὐ τερπνὴ μόνον ἀλλὰ καὶ ὠφέλιμός ἐστιν τοῖς θεωμένοις, καὶ ὅσα παιδεύει καὶ ὅσα διδάσκει, καὶ ὡς ῥυθμίζει τῶν ὁρώντων τὰς ψυχάς, καλλίστοις θεάμασιν ἐγγυμνάζουσα καὶ ἀρίστοις ἀκούσμασιν ἐνδιατρίβουσα καὶ κοινόν τι ψυχῆς καὶ σώματος κάλλος ἐπιδεικνυμένη; τὸ γὰρ καὶ μετὰ μουσικῆς καὶ ῥυθμοῦ ταῦτα πάντα ποιεῖν οὐ ψόγος ἂν αὐτῆς ἀλλ’ ἔπαινος μᾶλλον εἴη.", "st": "45.6"}, {"sp": "N", "t": "<em>Κράτων.<\/em> ἐμοὶ μὲν οὐ πάνυ σχολὴ μεμηνότος ἀνθρώπου ἀκροᾶσθαι τὴν νόσον τὴν αὑτοῦ ἐπαινοῦντος· σὺ δὲ εἰ βούλει λῆρόν τινα κατασκεδάσαι μου, ἕτοιμος φιλικὴν ταύτην λειτουργίαν ὑποστῆναι καὶ παρασχεῖν τὰ ὦτα, καὶ ἄνευ κηροῦ παρακούειν τῶν φαύλων δυνάμενος. ὥστε ἤδη σιωπήσομαί σοι, καὶ λέγε ὁπόσα ἐθέλεις ὡς μηδὲ ἀκούοντός τινος.", "st": "45.6"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> εὖ γε, ὦ Κράτων, καὶ τούτου ἐδεόμην μάλιστα· εἴσῃ γὰρ μετ’ ὀλίγον εἰ λῆρος εἶναί σοι δόξει τὰ λεχθησόμενα. καὶ πρῶτόν γε ἐκεῖνο πάνυ ἠγνοηκέναι μοι δοκεῖς, ὡς οὐ νεώτερον τὸ τῆς ὀρχήσεως ἐπιτήδευμα τοῦτό ἐστιν οὐδὲ χθὲς καὶ πρῴην ἀρξάμενον, οἷον κατὰ τοὺς προπάτορας ἡμῶν ἢ τοὺς ἐκείνων, ἀλλ’ οἵ γε τἀληθέστατα ὀρχήσεως πέρι γενεαλογοῦντες ἅμα τῇ πρώτῃ γενέσει τῶν ὅλων φαῖεν ἄν σοι καὶ ὄρχησιν ἀναφῦναι, τῷ ἀρχαίῳ ἐκείνῳ Ἔρωτι συναναφανεῖσαν. ἡ γοῦν χορεία τῶν ἀστέρων καὶ ἡ πρὸς τοὺς ἀπλανεῖς τῶν πλανήτων συμπλοκὴ καὶ εὔρυθμος αὐτῶν κοινωνία καὶ εὔτακτος ἁρμονία τῆς πρωτογόνου ὀρχήσεως δείγματά ἐστιν. κατ’ ὀλίγον δὲ αὐξανομένη καὶ τῆς πρὸς τὸ βέλτιον ἀεὶ προσθήκης τυγχάνουσα, νῦν ἔοικεν ἐς τὸ ἀκρότατον ἀποτετελέσθαι καὶ γεγενῆσθαι ποικίλον τι καὶ παναρμόνιον καὶ πολύμουσον ἀγαθόν.", "st": "45.7"}, {"sp": "N", "t": "πρῶτον δέ φασιν Ῥέαν ἡσθεῖσαν τῇ τέχνῃ ἐν Φρυγίᾳ μὲν τοὺς Κορύβαντας, ἐν Κρήτῃ δὲ τοὺς Κουρῆτας ὀρχεῖσθαι κελεῦσαι, καὶ οὐ τὰ μέτρια ὤνατο τῆς τέχνης αὐτῶν, οἵ γε περιορχούμενοι διεσώσαντο αὐτῇ τὸν Δία, ὥστε καὶ σῶστρα εἰκότως ἂν ὁ Ζεὺς ὀφείλειν ὁμολογοίη αὐτοῖς, ἐκφυγὼν διὰ τὴν ἐκείνων ὄρχησιν τοὺς πατρῴους ὀδόντας. ἐνόπλιος δὲ αὐτῶν ἡ ὄρχησις ἦν, τὰ ξίφη μεταξὺ κροτούντων πρὸς τὰς ἀσπίδας καὶ πηδώντων ἔνθεόν τι καὶ πολεμικόν.", "st": "45.8"}, {"sp": "N", "t": "Μετὰ δέ, Κρητῶν οἱ κράτιστοι ἐνεργῶς ἐπιτηδεύσαντες αὐτὸ ἄριστοι ὀρχησταὶ ἐγένοντο, οὐχ οἱ ἰδιῶται μόνον, ἀλλὰ καὶ οἱ βασιλικώτεροι καὶ πρωτεύειν ἀξιοῦντες. ὁ γοῦν Ὅμηρος τὸν Μηριόνην, οὐκ αἰσχῦναι βουλόμενος ἀλλὰ κοσμῆσαι, ὀρχηστὴν προσεῖπεν, καὶ οὕτως ἄρα ἐπίσημος ἦν καὶ γνώριμος ἅπασιν ἐπὶ τῇ ὀρχηστικῇ ὥστε οὐχ οἱ Ἕλληνες μόνον ταῦτα ἠπίσταντο περὶ αὐτοῦ ἀλλὰ καὶ οἱ Τρῶες αὐτοί, καίτοι πολέμιοι ὄντες· ἑώρων γάρ, οἶμαι, καὶ τὴν ἐν τῷ πολεμεῖν αὐτοῦ κουφότητα καὶ εὐρυθμίαν, ἣν ἐξ ὀρχήσεως ἐκέκτητο. φησὶν δὲ τὰ ἔπη ὧδέ πως·<br>Μηριόνη, τάχα κέν σε καὶ ὀρχηστήν περ ἐόντα<br>ἔγχος ἐμὸν κατέπαυσε.<br>καὶ ὅμως οὐ κατέπαυσεν αὐτόν· ἅτε γὰρ ἠσκημένος ἐν τῇ ὀρχηστικῇ, ῥᾳδίως, οἶμαι, διεδίδρασκεν τὰς ἐπ’ αὐτὸν ἀφέσεις τῶν ἀκοντίων.", "st": "45.8"}, {"sp": "N", "t": "πολλοὺς δὲ καὶ ἄλλους τῶν ἡρώων εἰπεῖν ἔχων τοῖς αὐτοῖς ἐγγεγυμνασμένους καὶ τέχνην τὸ πρᾶγμα πεποιημένους, ἱκανὸν ἡγοῦμαι τὸν Νεοπτόλεμον, Ἀχιλλέως μὲν παῖδα ὄντα, πάνυ δὲ διαπρέψαντα ἐν τῇ ὀρχηστικῇ καὶ εἶδος τὸ κάλλιστον αὐτῇ προστεθεικότα, Πυρρίχιον ἀπ’ αὐτοῦ κεκλημένον· καὶ ὁ Ἀχιλλεύς, ταῦτα ὑπὲρ τοῦ παιδὸς πυνθανόμενος, μᾶλλον ἔχαιρεν, οἶμαι, ἢ ἐπὶ τῷ κάλλει καὶ τῇ ἄλλῃ ἀλκῇ αὐτοῦ. τοιγαροῦν τὴν Ἴλιον, τέως ἀνάλωτον οὖσαν, ἡ ἐκείνου ὀρχηστικὴ καθεῖλεν καὶ εἰς ἔδαφος κατέρριψεν.", "st": "45.9"}, {"sp": "N", "t": "Λακεδαιμόνιοι μέν, ἄριστοι Ἑλλήνων εἶναι δοκοῦντες, παρὰ Πολυδεύκους καὶ Κάστορος καρυατίζειν μαθόντες (ὀρχήσεως δὲ καὶ τοῦτο εἶδος, ἐν Καρύαις τῆς Λακωνικῆς διδασκόμενον) ἅπαντα μετὰ Μουσῶν ποιοῦσιν, ἄχρι τοῦ πολεμεῖν πρὸς αὐλὸν καὶ ῥυθμὸν καὶ εὔτακτον ἔμβασιν τοῦ ποδός· καὶ τὸ πρῶτον σύνθημα Λακεδαιμονίοις πρὸς τὴν μάχην ὁ αὐλὸς ἐνδίδωσιν. τοιγαροῦν καὶ ἐκράτουν ἁπάντων, μουσικῆς αὐτοῖς καὶ εὐρυθμίας ἡγουμένης.", "st": "45.10"}, {"sp": "N", "t": "ἴδοις δ’ ἂν νῦν ἔτι καὶ τοὺς ἐφήβους αὐτῶν οὐ μεῖον ὀρχεῖσθαι ἢ ὁπλομαχεῖν μανθάνοντας· ὅταν γὰρ ἀκροχειρισάμενοι καὶ παίσαντες καὶ παισθέντες ἐν τῷ μέρει παύσωνται, εἰς ὄρχησιν αὐτοῖς ἡ ἀγωνία τελευτᾷ, καὶ αὐλητὴς μὲν ἐν τῷ μέσῳ κάθηται ἐπαυλῶν καὶ κτυπῶν τῷ ποδί, οἱ δὲ κατὰ στοῖχον ἀλλήλοις ἑπόμενοι σχήματα παντοῖα ἐπιδείκνυνται πρὸς ῥυθμὸν ἐμβαίνοντες, ἄρτι μὲν πολεμικά, μετ’ ὀλίγον δὲ χορευτικά, ἃ Διονύσῳ καὶ Ἀφροδίτῃ φίλα.", "st": "45.10"}, {"sp": "N", "t": "τοιγαροῦν καὶ τὸ ᾆσμα ὃ μεταξὺ ὀρχούμενοι ᾄδουσιν Ἀφροδίτης ἐπίκλησίς ἐστιν καὶ Ἐρώτων, ὡς συγκωμάζοιεν αὐτοῖς καὶ συνορχοῖντο. καὶ θάτερον δὲ τῶν ᾀσμάτων — δύο γὰρ ᾄδεται — διδασκαλίαν ἔχει ὡς χρὴ ὀρχεῖσθαι. “πόρρω” γάρ, φασίν, “ὦ παῖδες, πόδα μετάβατε καὶ κωμάξατε βέλτιον,” τουτέστιν ἄμεινον ὀρχήσασθε.", "st": "45.11"}, {"sp": "N", "t": "ὅμοια δὲ καὶ οἱ τὸν ὅρμον καλούμενον ὀρχούμενοι ποιοῦσιν.", "st": "45.11"}, {"sp": "N", "t": "ὁ δὲ ὅρμος ὄρχησίς ἐστιν κοινὴ ἐφήβων τε καὶ παρθένων, παρ’ ἕνα χορευόντων καὶ ὡς ἀληθῶς ὅρμῳ ἐοικότων· καὶ ἡγεῖται μὲν ὁ ἔφηβος τὰ νεανικὰ ὀρχούμενος καὶ ὅσοις ὕστερον ἐν πολέμῳ χρήσεται, ἡ παρθένος δὲ ἕπεται κοσμίως τὸ θῆλυ χορεύειν διδάσκουσα, ὡς εἶναι τὸν ὅρμον ἐκ σωφροσύνης καὶ ἀνδρείας πλεκόμενον. καὶ αἱ γυμνοπαιδίαι δὲ αὐτοῖς ὁμοίως ὄρχησίς ἐστιν.", "st": "45.12"}, {"sp": "N", "t": "ἃ δὲ Ὅμηρος ὑπὲρ Ἀριάδνης ἐν τῇ ἀσπίδι πεποίηκεν καὶ τοῦ χοροῦ ὃν αὐτῇ Δαίδαλος ἤσκησεν ὡς ἀνεγνωκότι σοι παρίημι, καὶ τοὺς ὀρχηστὰς δὲ τοὺς δύο οὓς ἐκεῖ ὁ ποιητὴς κυβιστητῆρας καλεῖ, ἡγουμένους τοῦ χοροῦ, καὶ πάλιν ἃ ἐν τῇ αὐτῇ ἀσπίδι λέγει· “κοῦροι δ’ ὀρχηστῆρες ἐδίνεον,” ὥς τι κάλλιστον τοῦτο τοῦ Ἡφαίστου ἐμποιήσαντος τῇ ἀσπίδι. τοὺς μὲν γὰρ Φαίακας καὶ πάνυ εἰκὸς ἦν ὀρχήσει χαίρειν, ἁβρούς τε ὄντας καὶ ἐν πάσῃ εὐδαιμονίᾳ διατρίβοντας. ὁ γοῦν Ὅμηρος τοῦτο αὐτῶν μάλιστα θαυμάζοντα πεποίηκε τὸν Ὀδυσσέα καὶ τὰς μαρμαρυγὰς τῶν ποδῶν θεώμενον.", "st": "45.13"}, {"sp": "N", "t": "ἐν μέν γε Θεσσαλίᾳ τοσοῦτον ἐπέδωκεν τῆς ὀρχηστικῆς ἡ ἄσκησις, ὥστε τοὺς προστάτας καὶ προαγωνιστὰς αὐτῶν προορχηστῆρας ἐκάλουν· καὶ δηλοῦσι τοῦτο αἱ τῶν ἀνδριάντων ἐπιγραφαὶ οὓς τοῖς ἀριστεύουσιν ἀνίστασαν· “προὔκρινεν” γάρ, φασίν, “προορχηστῆρα ἁ πόλις.” καὶ αὖθις, “Εἰλατίωνι τὰν εἰκόνα ὁ δᾶμος εὖ ὀρχησαμένῳ τὰν μάχαν.”", "st": "45.14"}, {"sp": "N", "t": "ἐῶ λέγειν, ὅτι τελετὴν οὐδεμίαν ἀρχαίαν ἔστιν εὑρεῖν ἄνευ ὀρχήσεως, Ὀρφέως δηλαδὴ καὶ Μουσαίου καὶ τῶν τότε ἀρίστων ὀρχηστῶν καταστησαμένων αὐτάς, ὥς τι κάλλιστον καὶ τοῦτο νομοθετησάντων, σὺν ῥυθμῷ καὶ ὀρχήσει μυεῖσθαι. ὅτι δ’ οὕτως ἔχει, τὰ μὲν ὄργια σιωπᾶν ἄξιον τῶν ἀμυήτων ἕνεκα, ἐκεῖνο δὲ πάντες ἀκούουσιν, ὅτι τοὺς ἐξαγορεύοντας τὰ μυστήρια ἐξορχεῖσθαι λέγουσιν οἱ πολλοί.", "st": "45.15"}, {"sp": "N", "t": "ἐν Δήλῳ δέ γε οὐδὲ αἱ θυσίαι ἄνευ ὀρχήσεως ἀλλὰ σὺν ταύτῃ καὶ μετὰ μουσικῆς ἐγίγνοντο. παίδων χοροὶ συνελθόντες ὑπ’ αὐλῷ καὶ κιθάρᾳ οἱ μὲν ἐχόρευον, ὑπωρχοῦντο δὲ οἱ ἄριστοι προκριθέντες ἐξ αὐτῶν. τὰ γοῦν τοῖς χοροῖς γραφόμενα τούτοις ᾄσματα ὑπορχήματα ἐκαλεῖτο καὶ ἐμπέπληστο τῶν τοιούτων ἡ λύρα.", "st": "45.16"}, {"sp": "N", "t": "καὶ τί σοι τοὺς Ἕλληνας λέγω, ὅπου καὶ Ἰνδοὶ ἐπειδὰν ἕωθεν ἀναστάντες προσεύχωνται τὸν Ἥλιον, οὐχ ὥσπερ ἡμεῖς τὴν χεῖρα κύσαντες ἡγούμεθα ἐντελῆ ἡμῶν εἶναι τὴν εὐχήν, ἀλλ’ ἐκεῖνοι πρὸς τὴν ἀνατολὴν στάντες ὀρχήσει τὸν Ἥλιον ἀσπάζονται, σχηματίζοντες ἑαυτοὺς σιωπῇ καὶ μιμούμενοι τὴν χορείαν τοῦ θεοῦ· καὶ τοῦτ’ ἐστιν Ἰνδῶν καὶ εὐχὴ καὶ χοροὶ καὶ θυσία. διὸ καὶ τούτοις ἱλεοῦνται τὸν θεὸν δίς, καὶ ἀρχομένης καὶ δυομένης τῆς ἡμέρας.", "st": "45.17"}, {"sp": "N", "t": "Αἰθίοπες δέ γε καὶ πολεμοῦντες σὺν ὀρχήσει αὐτὸ δρῶσιν, καὶ οὐκ ἂν ἀφείη τὸ βέλος Αἰθίοψ ἀνὴρ ἀφελὼν τῆς κεφαλῆς — ταύτῃ γὰρ ἀντὶ φαρέτρας χρῶνται περιδέοντες αὐτῇ ἀκτινηδὸν τὰ βέλη — εἰ μὴ πρότερον ὀρχήσαιτο καὶ τῷ σχήματι ἀπειλήσειε καὶ προεκφοβήσειε τῇ ὀρχήσει τὸν πολέμιον.", "st": "45.18"}, {"sp": "N", "t": "ἄξιον δέ, ἐπεὶ τὴν Ἰνδικὴν καὶ τὴν Αἰθιοπίαν διεξεληλύθαμεν, καὶ ἐς τὴν γείτονα αὐτῶν Αἴγυπτον καταβῆναι τῷ λόγῳ. δοκεῖ γάρ μοι ὁ παλαιὸς μῦθος καὶ Πρωτέα τὸν Αἰγύπτιον οὐκ ἄλλο τι ἢ ὀρχηστήν τινα γενέσθαι λέγειν, μιμητικὸν ἄνθρωπον καὶ πρὸς πάντα σχηματίζεσθαι καὶ μεταβάλλεσθαι δυνάμενον, ὡς καὶ ὕδατος ὑγρότητα μιμεῖσθαι καὶ πυρὸς ὀξύτητα ἐν τῇ τῆς κινήσεως σφοδρότητι καὶ λέοντος ἀγριότητα καὶ παρδάλεως θυμὸν καὶ δένδρου δόνημα, καὶ ὅλως ὅ τι καὶ θελήσειεν. ὁ δὲ μῦθος παραλαβὼν πρὸς τὸ παραδοξότερον τὴν φύσιν αὐτοῦ διηγήσατο, ὡς γιγνομένου ταῦτα ἅπερ ἐμιμεῖτο. ὅπερ δὴ καὶ τοῖς νῦν ὀρχουμένοις πρόσεστιν, ἴδοις τ’ ἂν οὖν αὐτοὺς πρὸς τὸν καιρὸν ὠκέως διαλλαττομένους καὶ αὐτὸν μιμουμένους τὸν Πρωτέα. εἰκάζειν δὲ χρὴ καὶ τὴν Ἔμπουσαν τὴν ἐς μυρίας μορφὰς μεταβαλλομένην τοιαύτην τινὰ ἄνθρωπον ὑπὸ τοῦ μύθου παραδεδόσθαι.", "st": "45.19"}, {"sp": "N", "t": "ἐπὶ τούτοις δίκαιον μηδὲ τῆς Ῥωμαίων ὀρχήσεως ἀμνημονεῖν, ἣν οἱ εὐγενέστατοι αὐτῶν τῷ πολεμικωτάτῳ τῶν θεῶν Ἄρει, οἱ Σάλιοι καλούμενοι (ἱερωσύνης δὲ τοῦτο ὄνομα), ὀρχοῦνται, σεμνοτάτην τε ἅμα καὶ ἱερωτάτην.", "st": "45.20"}, {"sp": "N", "t": "Βιθυνὸς δὲ μῦθος, καὶ οὗτος οὐ πάνυ τῶν Ἰταλιωτικῶν ἀλλότριος, φησὶν τὸν Πρίαπον δαίμονα πολεμιστήν, τῶν Τιτάνων οἶμαι ἕνα ἢ τῶν Ἰδαίων Δακτύλων τοῦτο ἔργον πεποιημένον, τὰ ἐνόπλια παιδεύειν, παραλαβόντα παρὰ τῆς Ἥρας τὸν Ἄρη, παῖδα μὲν ἔτι, σκληρὸν δὲ καὶ πέρα τοῦ μετρίου ἀνδρικόν, μὴ πρότερον ὁπλομαχεῖν διδάξαι πρὶν τέλειον ὀρχηστὴν ἀπειργάσατο. καὶ ἐπὶ τούτῳ καὶ μισθὸς αὐτῷ παρὰ τῆς Ἥρας ἐγένετο, δεκάτην ἀεὶ τῶν ἐκ πολέμου περιγιγνομένων τῷ Ἄρει παρ’ αὐτοῦ λαμβάνειν.", "st": "45.21"}, {"sp": "N", "t": "τὰ μὲν γὰρ Διονυσιακὰ καὶ Βακχικὰ οἶμαί σε μὴ περιμένειν ἐμοῦ ἀκοῦσαι, ὅτι ὄρχησις ἐκεῖνα πάντα ἦν. τριῶν γοῦν οὐσῶν τῶν γενικωτάτων ὀρχήσεων, κόρδακος καὶ σικιννίδος καὶ ἐμμελείας, οἱ Διονύσου θεράποντες οἱ Σάτυροι ταύτας ἐφευρόντες ἀφ’ αὑτῶν ἑκάστην ὠνόμασαν, καὶ ταύτῃ τῇ τέχνῃ χρώμενος ὁ Διόνυσος, φασίν, Τυρρηνοὺς καὶ Ἰνδοὺς καὶ Λυδοὺς ἐχειρώσατο καὶ φῦλον οὕτω μάχιμον τοῖς αὑτοῦ θιάσοις κατωρχήσατο.", "st": "45.22"}, {"sp": "N", "t": "ὥστε, ὦ θαυμάσιε, ὅρα μὴ ἀνόσιον ᾖ κατηγορεῖν ἐπιτηδεύματος θείου τε ἅμα καὶ μυστικοῦ καὶ τοσούτοις θεοῖς ἐσπουδασμένου καὶ ἐπὶ τιμῇ αὐτῶν δρωμένου καὶ τοσαύτην τέρψιν ἅμα καὶ παιδείαν ὠφέλιμον παρεχομένου.", "st": "45.23"}, {"sp": "N", "t": "θαυμάζω δέ σου κἀκεῖνο, εἰδὼς Ὁμήρου καὶ Ἡσιόδου μάλιστα ἐραστὴν ὄντα σε (αὖθις γὰρ ἐπὶ τοὺς ποιητὰς ἐπάνειμι), πῶς ἀντιφθέγγεσθαι ἐκείνοις τολμᾷς πρὸ τῶν πάντων ὄρχησιν ἐπαινοῦσιν. ὁ μὲν γὰρ Ὅμηρος τὰ ἥδιστα καὶ κάλλιστα καταλέγων, ὕπνον καὶ φιλότητα καὶ μολπὴν καὶ ὄρχησιν, μόνην ταύτην ἀμύμονα ὠνόμασεν, προσμαρτυρήσας νὴ Δία καὶ τὸ ἡδὺ τῇ μολπῇ, ἅπερ ἀμφότερα τῇ ὀρχηστικῇ πρόσεστιν, καὶ ᾠδὴ γλυκερὰ καὶ ὀρχησμὸς ἀμύμων, ὃν σὺ νῦν μωμᾶσθαι ἐπινοεῖς. καὶ πάλιν ἐν ἑτέρῳ μέρει τῆς ποιήσεως·<br>ἄλλῳ μὲν γὰρ ἔδωκε θεὸς πολεμήϊα ἔργα,<br>ἄλλῳ δ’ ὀρχηστύν τε καὶ ἱμερόεσσαν ἀοιδήν.<br>ἱμερόεσσα γὰρ ὡς ἀληθῶς ἡ μετ’ ὀρχήσεως ᾠδὴ καὶ δῶρον θεῶν τοῦτο κάλλιστον. καὶ ἔοικεν εἰς δύο διῃρηκὼς ὁ Ὅμηρος τὰ πάντα πράγματα, πόλεμον καὶ εἰρήνην, τοῖς τοῦ πολέμου μόνα ταῦτα ὡς κάλλιστα ἀντιτεθεικέναι.", "st": "45.23"}, {"sp": "N", "t": "ὁ δὲ Ἡσίοδος, οὐ παρ’ ἄλλου ἀκούσας ἀλλ’ ἰδὼν αὐτὸς ἕωθεν εὐθὺς ὀρχουμένας τὰς Μούσας, ἐν ἀρχῇ τῶν ἐπῶν τοῦτο περὶ αὐτῶν τὸ μέγιστον ἐγκώμιον διηγεῖται, ὅτι “περὶ κρήνην ἰοειδέα πόσς’ ἁπαλοῖσιν ὀρχεῦνται,” τοῦ πατρὸς τὸν βωμὸν περιχορεύουσαι.", "st": "45.24"}, {"sp": "N", "t": "ἀλλὰ σὺ μέν, ὦ γενναῖε, μονονουχὶ θεομαχῶν ὑβρίζεις εἰς τὴν ὀρχηστικήν·", "st": "45.24"}, {"sp": "N", "t": "ὁ Σωκράτης δέ, σοφώτατος ἀνήρ, εἴ γε πιστευτέον τοῦτο περὶ αὐτοῦ λέγοντι τῷ Πυθίῳ, οὐ μόνον ἐπῄνει τὴν ὀρχηστικὴν ἀλλὰ καὶ ἐκμαθεῖν αὐτὴν ἠξίου, μέγιστον νέμων εὐρυθμίᾳ καὶ εὐμουσίᾳ καὶ κινήσει ἐμμελεῖ καὶ εὐσχημοσύνῃ τοῦ κινουμένου· καὶ οὐκ ᾐδεῖτο γέρων ἀνὴρ ἓν τῶν σπουδαιοτάτων μαθημάτων καὶ τοῦτο ἡγούμενος εἶναι. καὶ ἔμελλέν γε ἐκεῖνος περὶ ὀρχηστικὴν οὐ μετρίως σπουδάσεσθαι, ὅς γε καὶ τὰ μικρὰ οὐκ ὤκνει μανθάνειν, ἀλλὰ καὶ εἰς τὰ διδασκαλεῖα τῶν αὐλητρίδων ἐφοίτα καὶ παρ’ ἑταίρας γυναικὸς οὐκ ἀπηξίου σπουδαῖόν τι ἀκούειν, τῆς Ἀσπασίας. καίτοι ἐκεῖνος ἄρτι ἀρχομένην ἑώρα τότε τὴν τέχνην καὶ οὐδέπω εἰς τοσοῦτον κάλλος διηρθρωμένην. εἰ δὲ τοὺς νῦν ἐπὶ μέγιστον αὐτὴν προαγαγόντας ἐθεᾶτο, εὖ οἶδα, πάντων ἂν ἐκεῖνός γε ἀφέμενος μόνῳ τῷ θεάματι τούτῳ τὸν νοῦν ἂν προσεῖχεν καὶ τοὺς παῖδας οὐκ ἂν ἄλλο τι πρὸ αὐτοῦ ἐδιδάξατο.", "st": "45.25"}, {"sp": "N", "t": "δοκεῖς δέ μοι, ὅταν κωμῳδίαν καὶ τραγῳδίαν ἐπαινῇς, ἐπιλελῆσθαι ὅτι καὶ ἐν ἑκατέρᾳ ἐκείνων ὀρχήσεως ἴδιόν τι εἶδός ἐστιν, οἷον τραγικὴ μὲν ἡ ἐμμέλεια, κωμῳδικὴ δὲ ὁ κόρδαξ, ἐνίοτε δὲ καὶ τρίτης, σικιννίδος, προσλαμβανομένης. ἐπεὶ δὲ ἐν ἀρχῇ καὶ προετίμησας τῆς ὀρχήσεως τὴν τραγῳδίαν καὶ κωμῳδίαν καὶ αὐλητὰς κυκλίους καὶ κιθαρῳδίαν, ἐναγώνια ταῦτα καὶ διὰ τοῦτο σεμνὰ προσειπών, φέρε νῦν ἀντεξετάσωμεν τῇ ὀρχήσει ἕκαστον αὐτῶν. καίτοι τὸν μὲν αὐλόν, εἰ δοκεῖ, καὶ τὴν κιθάραν παρῶμεν· μέρη γὰρ τῆς τοῦ ὀρχηστοῦ ὑπηρεσίας καὶ ταῦτα.", "st": "45.26"}, {"sp": "N", "t": "τὴν τραγῳδίαν δέ γε ἀπὸ τοῦ σχήματος πρώτου καταμάθωμεν οἵα ἐστίν, ὡς εἰδεχθὲς ἅμα καὶ φοβερὸν θέαμα εἰς μῆκος ἄρρυθμον ἠσκημένος ἄνθρωπος, ἐμβάταις ὑψηλοῖς ἐποχούμενος, πρόσωπον ὑπὲρ κεφαλῆς ἀνατεινόμενον ἐπικείμενος καὶ στόμα κεχηνὸς πάμμεγα ὡς καταπιόμενος τοὺς θεατάς. ἐῶ λέγειν προστερνίδια καὶ προγαστρίδια, προσθετὴν καὶ ἐπιτεχνητὴν παχύτητα προσποιούμενος, ὡς μὴ τοῦ μήκους ἡ ἀρρυθμία ἐν λεπτῷ μᾶλλον ἐλέγχοιτο· εἶτ’ ἔνδοθεν αὐτὸς κεκραγώς, ἑαυτὸν ἀνακλῶν καὶ κατακλῶν, ἐνίοτε καὶ περιᾴδων τὰ ἰαμβεῖα καί, τὸ δὴ αἴσχιστον, μελῳδῶν τὰς συμφοράς, καὶ μόνης τῆς φωνῆς ὑπεύθυνον παρέχων ἑαυτόν· τὰ γὰρ ἄλλα τοῖς ποιηταῖς ἐμέλησεν πρὸ πολλοῦ ποτε γενομένοις. καὶ μέχρι μὲν Ἀνδρομάχη τις ἢ Ἑκάβη ἐστίν, φορητὸς ἡ ᾠδή· ὅταν δὲ Ἡρακλῆς αὐτὸς εἰσελθὼν μονῳδῇ, ἐπιλαθόμενος αὑτοῦ καὶ μήτε τὴν λεοντῆν αἰδεσθεὶς μήτε τὸ ῥόπαλον ὃ περίκειται, σολοικίαν εὖ φρονῶν εἰκότως φαίη ἄν τις τὸ πρᾶγμα.", "st": "45.27"}, {"sp": "N", "t": "καὶ γὰρ αὖ ὅπερ ἐνεκάλεις τῇ ὀρχηστικῇ, τὸ ἄνδρας ὄντας μιμεῖσθαι γυναῖκας, κοινὸν τοῦτο καὶ τῆς τραγῳδίας καὶ τῆς κωμῳδίας ἔγκλημα ἂν εἴη· πλείους γοῦν ἐν αὐταῖς τῶν ἀνδρῶν αἱ γυναῖκες.", "st": "45.28"}, {"sp": "N", "t": "ἡ κωμῳδία δὲ καὶ τῶν προσώπων αὐτῶν τὸ καταγέλαστον μέρος τοῦ τερπνοῦ αὑτῇ νενόμικεν, οἷα Δάων καὶ Τιβείων καὶ μαγείρων πρόσωπα.", "st": "45.29"}, {"sp": "N", "t": "τὸ δὲ τοῦ ὀρχηστοῦ σχῆμα ὡς μὲν κόσμιον καὶ εὐπρεπὲς οὐκ ἐμὲ χρὴ λέγειν, δῆλα γὰρ τοῖς μὴ τυφλοῖς ταῦτα· τὸ δὲ πρόσωπον αὐτὸ ὡς κάλλιστον καὶ τῷ ὑποκειμένῳ δράματι ἐοικός, οὐ κεχηνὸς δὲ ὡς ἐκεῖνα ἀλλὰ συμμεμυκός· ἔχει γὰρ πολλοὺς τοὺς ὑπὲρ αὐτοῦ βοῶντας.", "st": "45.29"}, {"sp": "N", "t": "πάλαι μὲν γὰρ αὐτοὶ καὶ ᾖδον καὶ ὠρχοῦντο· εἶτ’ ἐπειδὴ κινουμένων τὸ ἆσθμα τὴν ᾠδὴν ἐπετάραττεν, ἄμεινον ἔδοξεν ἄλλους αὐτοῖς ὑπᾴδειν.", "st": "45.30"}, {"sp": "N", "t": "αἱ δὲ ὑποθέσεις κοιναὶ ἀμφοτέροις, καὶ οὐδέν τι διακεκριμέναι τῶν τραγικῶν αἱ ὀρχηστικαί, πλὴν ὅτι ποικιλώτεραι αὗται καὶ πολυμαθέστεραι καὶ μυρίας μεταβολὰς ἔχουσαι.", "st": "45.31"}, {"sp": "N", "t": "εἰ δὲ μὴ ἐναγώνιος ἡ ὄρχησις, ἐκείνην εἶναί φημι αἰτίαν, τὸ δόξαι τοῖς ἀγωνοθέταις μεῖζον καὶ σεμνότερον τὸ πρᾶγμα ἢ ὥστε εἰς ἐξέτασιν καλεῖσθαι. ἐῶ λέγειν ὅτι πόλις ἐν Ἰταλίᾳ, τοῦ Χαλκιδικοῦ γένους ἡ ἀρίστη, καὶ τοῦτο ὥσπερ τι κόσμημα τῷ παρ’ αὐτοῖς ἀγῶνι προστέθεικεν.", "st": "45.32"}, {"sp": "N", "t": "ἐθέλω δέ σοι ἐνταῦθα ἤδη ἀπολογήσασθαι ὑπὲρ τῶν παραλελειμμένων τῷ λόγῳ παμπόλλων ὄντων, ὡς μὴ δόξαν ἀγνοίας ἢ ἀμαθίας παράσχωμαι. οὐ γάρ με λέληθεν ὅτι πολλοὶ πρὸ ἡμῶν περὶ ὀρχήσεως συγγεγραφότες τὴν πλείστην διατριβὴν τῆς γραφῆς ἐποιήσαντο πάντα τῆς ὀρχήσεως τὰ εἴδη ἐπεξιόντες καὶ ὀνόματα αὐτῶν καταλέγοντες καὶ οἵα ἑκάστη καὶ ὑφ’ ὅτου εὑρέθη, πολυμαθίας ταύτην ἐπίδειξιν ἡγούμενοι παρέξειν. ἐγὼ δὲ μάλιστα μὲν τὴν περὶ ταῦτα φιλοτιμίαν ἀπειρόκαλόν τε καὶ ὀψιμαθῆ καὶ ἐμαυτῷ ἄκαιρον οἴομαι εἶναι καὶ διὰ τοῦτο παρίημι·", "st": "45.33"}, {"sp": "N", "t": "ἔπειτα δὲ κἀκεῖνό σε ἀξιῶ ἐννοεῖν καὶ μεμνῆσθαι, ὅτι μοι νῦν οὐ πᾶσαν ὄρχησιν πρόκειται γενεαλογεῖν, οὐδὲ τοῦτον τὸν σκοπὸν ὑπεστησάμην τῷ λόγῳ, ὀρχήσεων ὀνόματα καταριθμήσασθαι, πλὴν ὅσων ἐν ἀρχῇ ὀλίγων ἐπεμνήσθην τὰς γενικωτέρας αὐτῶν προχειρισάμενος· ἀλλὰ τό γε ἐν τῷ παρόντι μοι κεφάλαιον τοῦ λόγου τοῦτό ἐστιν, τὴν νῦν ὄρχησιν καθεστῶσαν ἐπαινέσαι καὶ δεῖξαι ὅσα ἐν αὑτῇ τερπνὰ καὶ χρήσιμα περιλαβοῦσα ἔχει, οὐ πάλαι ἀρξαμένη ἐς τοσοῦτο κάλλος ἐπιδιδόναι, ἀλλὰ κατὰ τὸν Σεβαστὸν μάλιστα.", "st": "45.34"}, {"sp": "N", "t": "αἱ μὲν γὰρ πρῶται ἐκεῖναι ὥσπερ τινὲς ῥίζαι καὶ θεμέλιοι τῆς ὀρχήσεως ἦσαν, τὸ δὲ ἄνθος αὐτῆς καὶ τὸν τελεώτατον καρπόν, ὅσπερ νῦν μάλιστα ἐς τὸ ἀκρότατον ἀποτετέλεσται, τοῦτον οὖν ὁ ἡμέτερος λόγος διεξέρχεται, παρεὶς τὸ θερμαυστρίζειν καὶ γέρανον ὀρχεῖσθαι καὶ τὰ ἄλλα ὡς μηδὲν τῇ νῦν ταύτῃ ἔτι προσήκοντα. οὐδὲ γὰρ ἐκεῖνο τὸ Φρύγιον τῆς ὀρχήσεως εἶδος, τὸ παροίνιον καὶ συμποτικόν, μετὰ μέθης γιγνόμενον ἀγροίκων πολλάκις πρὸς αὔλημα γυναικεῖον ὀρχουμένων σφοδρὰ καὶ καματηρὰ πηδήματα, καὶ νῦν ἔτι ταῖς ἀγροικίαις ἐπιπολάζοντα, ὑπ’ ἀγνοίας παρέλιπον, ἀλλ’ ὅτι μηδὲν ταῦτα τῇ νῦν ὀρχήσει κοινωνεῖ. καὶ γὰρ ὁ Πλάτων ἐν τοῖς Νόμοις τὰ μέν τινα εἴδη ἐπαινεῖ ταύτης, τὰ δὲ πάνυ ἀπαξιοῖ, διαιρῶν αὐτὰ ἔς τε τὸ τερπνὸν καὶ τὸ χρήσιμον καὶ ἀπελαύνων αὐτῶν τὰ ἀσχημονέστερα, προτιμῶν δὲ καὶ θαυμάζων θάτερα.", "st": "45.34"}, {"sp": "N", "t": "καὶ περὶ μὲν αὐτῆς ὀρχήσεως τοσαῦτα· τὸ γὰρ πάντα ἐπεξιόντα μηκύνειν τὸν λόγον ἀπειρόκαλον. ἃ δὲ τὸν ὀρχηστὴν αὐτὸν ἔχειν χρὴ καὶ ὅπως δεῖ ἠσκῆσθαι καὶ ἃ μεμαθηκέναι καὶ οἷς κρατύνειν τὸ ἔργον, ἤδη σοι δίειμι, ὡς μάθῃς οὐ τῶν ῥᾳδίων καὶ τῶν εὐμεταχειρίστων οὖσαν τὴν τέχνην, ἀλλὰ πάσης παιδεύσεως ἐς τὸ ἀκρότατον ἀφικνουμένην, οὐ μουσικῆς μόνον ἀλλὰ καὶ ῥυθμικῆς καὶ μετρικῆς, καὶ τῆς σῆς φιλοσοφίας μάλιστα, τῆς τε φυσικῆς καὶ τῆς ἠθικῆς· τὴν γὰρ διαλεκτικὴν αὐτῆς περιεργίαν ἄκαιρον αὑτῇ νενόμικεν. οὐ μὴν οὐδὲ ῥητορικῆς ἀφέστηκεν, ἀλλὰ καὶ ταύτης μετέχει, καθ’ ὅσον ἤθους τε καὶ πάθους ἐπιδεικτική ἐστιν, ὧν καὶ οἱ ῥήτορες γλίχονται. οὐκ ἀπήλλακται δὲ καὶ γραφικῆς καὶ πλαστικῆς, ἀλλὰ καὶ τὴν ἐν ταύταις εὐρυθμίαν μάλιστα μιμουμένη φαίνεται, ὡς μηδὲν ἀμείνω μήτε Φειδίαν αὐτῆς μήτε Ἀπελλῆν εἶναι δοκεῖν.", "st": "45.35"}, {"sp": "N", "t": "πρὸ πάντων δὲ Μνημοσύνην καὶ τὴν θυγατέρα αὐτῆς Πολύμνιαν ἵλεων ἔχειν αὐτῇ πρόκειται, καὶ μεμνῆσθαι πειρᾶται ἁπάντων. κατὰ γάρ τοι τὸν Ὁμηρικὸν Κάλχαντα τὸν ὀρχηστὴν εἰδέναι χρὴ “τά τ’ ἐόντα τά τ’ ἐσσόμενα πρό τ’ ἐόντα,” ὡς μηδὲν αὐτὸν διαλανθάνειν, ἀλλ’ εἶναι πρόχειρον τὴν μνήμην αὐτῶν. καὶ τὸ μὲν κεφάλαιον τῆς ὑποσχέσεως, μιμητική τίς ἐστιν ἐπιστήμη καὶ δεικτικὴ καὶ τῶν ἐννοηθέντων ἐξαγορευτικὴ καὶ τῶν ἀφανῶν σαφηνιστική, καὶ ὅπερ ὁ Θουκυδίδης περὶ τοῦ Περικλέους ἔφη ἐπαινῶν τὸν ἄνδρα, τοῦτο καὶ τὸ τοῦ ὀρχηστοῦ ἀκρότατον ἂν ἐγκώμιον εἴη, γνῶναί τε τὰ δέοντα καὶ ἑρμηνεῦσαι αὐτά· ἑρμηνείαν δὲ νῦν τὴν σαφήνειαν τῶν σχημάτων λέγω. ἡ δὲ πᾶσα τῷ ἔργῳ χορηγία ἡ παλαιὰ ἱστορία ἐστίν, ὡς προεῖπον, καὶ ἡ πρόχειρος αὐτῆς μνήμη τε καὶ μετ’ εὐπρεπείας ἐπίδειξις·", "st": "45.36"}, {"sp": "N", "t": "ἀπὸ γὰρ χάους εὐθὺς καὶ τῆς πρώτης τοῦ κόσμου γενέσεως ἀρξάμενον χρὴ αὐτὸν ἅπαντα εἰδέναι ἄχρι τῶν κατὰ τὴν Κλεοπάτραν τὴν Αἰγυπτίαν.", "st": "45.37"}, {"sp": "N", "t": "τούτῳ γὰρ τῷ διαστήματι περιωρίσθω ἡμῖν ἡ τοῦ ὀρχηστοῦ πολυμαθία καὶ τὰ διὰ μέσου μάλιστα ἴστω, Οὐρανοῦ τομήν, Ἀφροδίτης γονάς, Τιτάνων μάχην, Διὸς γένεσιν, Ῥέας ἀπάτην, λίθου ὑποβολήν, Κρόνου δεσμά, τὸν τῶν τριῶν ἀδελφῶν κλῆρον.", "st": "45.37"}, {"sp": "N", "t": "εἶτα ἑξῆς Γιγάντων ἐπανάστασιν, πυρὸς κλοπήν, ἀνθρώπων πλάσιν, Προμηθέως κόλασιν, Ἔρωτος ἰσχὺν ἑκατέρου, καὶ μετὰ ταῦτα Δήλου πλάνην καὶ Λητοῦς ὠδῖνας καὶ Πύθωνος ἀναίρεσιν καὶ Τιτυοῦ ἐπιβουλὴν καὶ τὸ μέσον τῆς γῆς εὑρισκόμενον πτήσει τῶν ἀετῶν.", "st": "45.38"}, {"sp": "N", "t": "Δευκαλίωνα ἐπὶ τούτοις, καὶ τὴν μεγάλην ἐπ’ ἐκείνου τοῦ βίου ναυαγίαν, καὶ λάρνακα μίαν λείψανον τοῦ ἀνθρωπίνου γένους φυλάττουσαν, καὶ ἐκ λίθων ἀνθρώπους πάλιν. εἶτα Ἰάκχου σπαραγμὸν καὶ Ἥρας δόλον καὶ Σεμέλης κατάφλεξιν καὶ Διονύσου ἀμφοτέρας τὰς γονάς, καὶ ὅσα περὶ Ἀθηνᾶς καὶ ὅσα περὶ Ἡφαίστου καὶ Ἐριχθονίου, καὶ τὴν ἔριν τὴν περὶ τῆς Ἀττικῆς, καὶ Ἁλιρρόθιον καὶ τὴν πρώτην ἐν Ἀρείῳ πάγῳ κρίσιν, καὶ ὅλως τὴν Ἀττικὴν πᾶσαν μυθολογίαν·", "st": "45.39"}, {"sp": "N", "t": "ἐξαιρέτως δὲ τὴν Δήμητρος πλάνην καὶ Κόρης εὕρεσιν καὶ Κελεοῦ ξενίαν καὶ Τριπτολέμου γεωργίαν καὶ Ἰκαρίου ἀμπελουργίαν καὶ τὴν Ἠριγόνης συμφοράν, καὶ ὅσα περὶ Βορέου καὶ ὅσα περὶ Ὠρειθυίας καὶ Θησέως καὶ Αἰγέως. ἔτι δὲ τὴν Μηδείας ὑποδοχὴν καὶ αὖθις ἐς Πέρσας φυγὴν καὶ τὰς Ἐρεχθέως θυγατέρας καὶ τὰς Πανδίονος, ἅ τε ἐν Θρᾴκῃ ἔπαθον καὶ ἔπραξαν. εἶτα ὁ Ἀκάμας καὶ ἡ Φυλλὶς καὶ ἡ προτέρα δὲ τῆς Ἑλένης ἁρπαγὴ καὶ ἡ στρατεία τῶν Διοσκούρων ἐπὶ τὴν πόλιν καὶ τὸ Ἱππολύτου πάθος καὶ Ἡρακλειδῶν κάθοδος· Ἀττικὰ γὰρ καὶ ταῦτα εἰκότως ἂν νομίζοιτο.", "st": "45.40"}, {"sp": "N", "t": "ταῦτα μὲν τὰ Ἀθηναίων ὀλίγα πάνυ δείγματος ἕνεκα ἐκ πολλῶν τῶν παραλελειμμένων διῆλθον.", "st": "45.40"}, {"sp": "N", "t": "ἑξῆς δὲ τὰ Μέγαρα καὶ Νῖσος καὶ Σκύλλα καὶ πορφυροῦς πλόκαμος καὶ Μίνωος πόρος καὶ περὶ τὴν εὐεργέτιν ἀχαριστία. οἷς ἑξῆς ὁ Κιθαιρὼν καὶ τὰ Θηβαίων καὶ Λαβδακιδῶν πάθη καὶ Κάδμου ἐπιδημία καὶ βοὸς ὄκλασις καὶ ὄφεως ὀδόντες καὶ Σπαρτῶν ἀνάδοσις καὶ αὖθις τοῦ Κάδμου εἰς δράκοντα μεταβολὴ καὶ πρὸς λύραν τείχισις καὶ μανία τοῦ τειχοποιοῦ καὶ τῆς γυναικὸς αὐτοῦ τῆς Νιόβης ἡ μεγαλαυχία καὶ ἡ ἐπὶ τῷ πένθει σιγὴ καὶ τὰ Πενθέως καὶ Ἀκταίωνος καὶ τὰ Οἰδίποδος καὶ Ἡρακλῆς σὺν τοῖς ἄθλοις αὐτοῦ ἅπασιν καὶ ἡ τῶν παίδων σφαγή.", "st": "45.41"}, {"sp": "N", "t": "εἶθ’ ἡ Κόρινθος πλέα καὶ αὕτη μύθων, τὴν Γλαύκην καὶ τὸν Κρέοντα ἔχουσα, καὶ πρὸ αὐτῶν τὸν Βελλεροφόντην καὶ τὴν Σθενέβοιαν καὶ Ἡλίου μάχην καὶ Ποσειδῶνος, καὶ μετὰ ταῦτα τὴν Ἀθάμαντος μανίαν καὶ τῶν Νεφέλης παίδων ἐπὶ τοῦ κριοῦ τὴν διαέριον φυγήν, … Ἰνοῦς καὶ Μελικέρτου ὑποδοχήν.", "st": "45.42"}, {"sp": "N", "t": "ἐπὶ τούτοις τὰ Πελοπιδῶν καὶ Μυκῆναι καὶ τὰ ἐν αὐταῖς καὶ πρὸ αὐτῶν, Ἴναχος καὶ Ἰὼ καὶ ὁ φρουρὸς αὐτῆς Ἄργος καὶ Ἀτρεὺς καὶ Θυέστης καὶ Ἀερόπη, καὶ τὸ χρυσοῦν ἀρνίον καὶ Πελοπείας γάμος καὶ Ἀγαμέμνονος σφαγὴ καὶ Κλυταιμήστρας τιμωρία· καὶ ἔτι πρὸ τούτων ἡ τῶν ἑπτὰ λοχαγῶν στρατεία καὶ ἡ τῶν φυγάδων γαμβρῶν τοῦ Ἀδράστου ὑποδοχὴ καὶ ὁ ἐπ’ αὐτοῖς χρησμὸς καὶ ἡ τῶν πεσόντων ἀταφία καὶ Ἀντιγόνης διὰ ταῦτα καὶ Μενοικέως ἀπώλεια.", "st": "45.43"}, {"sp": "N", "t": "καὶ τὰ ἐν Νεμέᾳ δέ, ἡ Ὑψιπύλη καὶ Ἀρχέμορος, ἀναγκαιότατα τῷ ὀρχηστῇ μνημονεύματα. καὶ πρὸ αὐτῶν εἴσεται τὴν Δανάης παρθένευσιν καὶ Περσέως γένεσιν καὶ τὸν ἐπὶ τὰς Γοργόνας ἆθλον αὐτῷ προῃρημένον, ᾧ οἰκεία καὶ ἡ Αἰθιοπικὴ διήγησις, Κασσιέπεια καὶ Ἀνδρομέδα καὶ Κηφεύς, οὓς καὶ ἄστροις ἐγκατέλεξεν ἡ τῶν μετὰ ταῦτα πίστις. κἀκεῖνα δὲ τὰ ἀρχαῖα τὰ Αἰγύπτου καὶ Δαναοῦ εἴσεται καὶ τὴν ἐπιθαλάμιον ἐπιβουλήν.", "st": "45.44"}, {"sp": "N", "t": "οὐκ ὀλίγα δὲ καὶ ἡ Λακεδαίμων τοιαῦτα παρέχεται, τὸν Ὑάκινθον καὶ τὸν τοῦ Ἀπόλλωνος ἀντεραστὴν Ζέφυρον καὶ τὴν ὑπὸ τῷ δίσκῳ τοῦ μειρακίου σφαγὴν καὶ τὸ ἐκ τοῦ αἵματος ἄνθος καὶ τὴν ἐν αὐτῷ αἰάζουσαν ἐπιγραφήν, καὶ τὴν Τυνδάρεω ἀνάστασιν καὶ τὴν Διὸς ἐπὶ τούτῳ κατ’ Ἀσκληπιοῦ ὀργήν· ἔτι δὲ καὶ τὸν Πάριδος ξενισμὸν καὶ τὴν Ἑλένης ἁρπαγὴν μετὰ τὴν ἐπὶ τῷ μήλῳ κρίσιν.", "st": "45.45"}, {"sp": "N", "t": "νομιστέον γὰρ τῇ Σπαρτιατικῇ ἱστορίᾳ καὶ τὴν Ἰλιακὴν συνῆφθαι, πολλὴν οὖσαν καὶ πολυπρόσωπον· καθ’ ἕκαστον γοῦν τῶν ἐκεῖ πεσόντων δρᾶμα τῇ σκηνῇ πρόκειται· καὶ μεμνῆσθαι δὲ τούτων δεῖ μάλιστα, ἀπὸ τῆς ἁρπαγῆς εὐθὺς ἄχρι τῶν ἐν τοῖς νόστοις γεγενημένων καὶ τῆς Αἰνείου πλάνης καὶ Διδοῦς ἔρωτος.", "st": "45.46"}, {"sp": "N", "t": "ὧν οὐκ ἀλλότρια καὶ τὰ περὶ τὸν Ὀρέστην δράματα καὶ τὰ ἐν Σκυθίᾳ τῷ ἥρωϊ τετολμημένα. οὐκ ἀπῳδὰ δὲ καὶ τὰ πρὸ τούτων, ἀλλὰ τοῖς Ἰλιακοῖς συγγενῆ, Ἀχιλλέως ἐν Σκύρῳ παρθένευσις καὶ Ὀδυσσέως μανία καὶ Φιλοκτήτου ἐρημία, καὶ ὅλως ἡ πᾶσα Ὀδύσσειος πλάνη καὶ Κίρκη καὶ Τηλέγονος καὶ ἡ Αἰόλου τῶν ἀνέμων δυναστεία καὶ τὰ ἄλλα μέχρι τῆς τῶν μνηστήρων τιμωρίας· καὶ πρὸ τούτων ἡ κατὰ Παλαμήδους ἐπιβουλὴ καὶ ἡ Ναυπλίου ὀργὴ καὶ ἡ Αἴαντος μανία καὶ ἡ θατέρου ἐν ταῖς πέτραις ἀπώλεια.", "st": "45.46"}, {"sp": "N", "t": "ἔχει πολλὰς καὶ Ἦλις ἀφορμὰς τοῖς ὀρχεῖσθαι πειρωμένοις, τὸν Οἰνόμαον, τὸν Μυρτίλον, τὸν Κρόνον, τὸν Δία, τοὺς πρώτους τῶν Ὀλυμπίων ἀγωνιστάς.", "st": "45.47"}, {"sp": "N", "t": "πολλὴ δὲ καὶ ἡ κατ’ Ἀρκαδίαν μυθολογία, Δάφνης φυγή, Καλλιστοῦς θηρίωσις, Κενταύρων παροινία, Πανὸς γοναί, Ἀλφειοῦ ἔρως καὶ ὕφαλος ἀποδημία.", "st": "45.48"}, {"sp": "N", "t": "ἀλλὰ κἂν εἰς τὴν Κρήτην ἀφίκῃ τῷ λόγῳ, πάμπολλα κἀκεῖθεν ἡ ὄρχησις ἐρανίζεται, τὴν Εὐρώπην, τὴν Πασιφάην, τοὺς ταύρους ἀμφοτέρους, τὸν λαβύρινθον, τὴν Ἀριάδνην, τὴν Φαίδραν, τὸν Ἀνδρόγεων, τὸν Δαίδαλον, τὸν Ἴκαρον, τὸν Γλαῦκον, τὴν Πολυΐδου μαντικήν, τὸν Τάλω, τὸν χαλκοῦν τῆς Κρήτης περίπολον.", "st": "45.49"}, {"sp": "N", "t": "κἂν εἰς Αἰτωλίαν μετέλθῃς, κἀκεῖ πολλὰ ἡ ὄρχησις καταλαμβάνει, τὴν Ἀλθαίαν, τὸν Μελέαγρον, τὴν Ἀταλάντην, τὸν δαλόν, καὶ ποταμοῦ καὶ Ἡρακλέους πάλην καὶ Σειρήνων γένεσιν καὶ Ἐχινάδων ἀνάδοσιν καὶ μετὰ τὴν μανίαν Ἀλκμαίωνος οἴκησιν· εἶτα Νέσσον καὶ Δηϊανείρας ζηλοτυπίαν, ἐφ’ ᾗ τὴν ἐν Οἴτῃ πυράν.", "st": "45.50"}, {"sp": "N", "t": "ἔχει καὶ Θρᾴκη πολλὰ τῷ ὀρχησομένῳ ἀναγκαῖα, τὸν Ὀρφέα, τὸν ἐκείνου σπαραγμὸν καὶ τὴν λάλον αὐτοῦ κεφαλὴν τὴν ἐπιπλέουσαν τῇ λύρᾳ, καὶ τὸν Αἷμον καὶ τὴν Ῥοδόπην, καὶ τὴν Λυκούργου κόλασιν.", "st": "45.51"}, {"sp": "N", "t": "καὶ Θεσσαλία δὲ ἔτι πλείω παρέχεται, τὸν Πελίαν, τὸν Ἰάσονα, τὴν Ἄλκηστιν, τὸν τῶν πεντήκοντα νέων στόλον, τὴν Ἀργώ, τὴν λάλον αὐτῆς τρόπιν,", "st": "45.52"}, {"sp": "N", "t": "τὰ ἐν Λήμνῳ, τὸν Αἰήτην, τὸν Μηδείας ὄνειρον, τὸν Ἀψύρτου σπαραγμὸν καὶ τὰ ἐν τῷ παράπλῳ γενόμενα, καὶ μετὰ ταῦτα τὸν Πρωτεσίλαον καὶ τὴν Λαοδάμειαν.", "st": "45.53"}, {"sp": "N", "t": "κἂν εἰς τὴν Ἀσίαν πάλιν διαβῇς, πολλὰ κἀκεῖ δράματα· ἡ γὰρ Σάμος εὐθὺς καὶ τὸ Πολυκράτους πάθος καὶ τῆς θυγατρὸς αὐτοῦ μέχρι Περσῶν πλάνη, καὶ τὰ ἔτι ἀρχαιότερα, ἡ τοῦ Ταντάλου φλυαρία καὶ ἡ παρ’ αὐτῷ θεῶν ἑστίασις καὶ ἡ Πέλοπος κρεουργία καὶ ὁ ἐλεφάντινος ὦμος αὐτοῦ.", "st": "45.54"}, {"sp": "N", "t": "καὶ ἐν Ἰταλίᾳ δὲ ὁ Ἠριδανὸς καὶ Φαέθων καὶ αἴγειροι ἀδελφαὶ θρηνοῦσαι καὶ ἤλεκτρον δακρύουσαι.", "st": "45.55"}, {"sp": "N", "t": "εἴσεται δὲ ὁ τοιοῦτος καὶ τὰς Ἑσπερίδας καὶ τὸν φρουρὸν τῆς χρυσῆς ὀπώρας δράκοντα καὶ τὸν Ἄτλαντος μόχθον καὶ τὸν Γηρυόνην καὶ τὴν ἐξ Ἐρυθείας ἔλασιν τῶν βοῶν.", "st": "45.56"}, {"sp": "N", "t": "οὐκ ἀγνοήσει δὲ καὶ τὰς μυθικὰς μεταμορφώσεις ἁπάσας, ὅσοι εἰς δένδρα ἢ θηρία ἢ ὄρνεα ἠλλάγησαν καὶ ὅσαι ἐκ γυναικῶν ἄνδρες ἐγένοντο, τὸν Καινέα λέγω καὶ τὸν Τειρεσίαν καὶ τοὺς τοιούτους.", "st": "45.57"}, {"sp": "N", "t": "καὶ ἐν Φοινίκῃ δὲ Μύρραν καὶ τὸ Ἀσσύριον ἐκεῖνο πένθος μεριζόμενον, καὶ ταῦτα εἴσεται, καὶ τὰ νεώτερα δὲ ὅσα μετὰ τὴν Μακεδόνων ἀρχὴν ἐτολμήθη ὑπό τε Ἀντιπάτρου καὶ παρὰ Σελεύκῳ ἐπὶ τῷ Στρατονίκης ἔρωτι.", "st": "45.58"}, {"sp": "N", "t": "τὰ γὰρ Αἰγυπτίων, μυστικώτερα ὄντα, εἴσεται μέν, συμβολικώτερον δὲ ἐπιδείξεται· τὸν Ἔπαφον λέγω καὶ τὸν Ὄσιριν καὶ τὰς τῶν θεῶν εἰς τὰ ζῷα μεταβολάς.", "st": "45.59"}, {"sp": "N", "t": "πρὸ πάντων δὲ τὰ περὶ τοὺς ἔρωτας αὐτῶν καὶ αὐτοῦ τοῦ Διὸς καὶ εἰς ὅσα ἑαυτὸν μετεσκεύασεν εἴσεται,", "st": "45.59"}, {"sp": "N", "t": "καὶ τὴν ἐν Ἅιδου ἅπασαν τραγῳδίαν καὶ τὰς κολάσεις καὶ τὰς ἐφ’ ἑκάστῃ αἰτίας καὶ τὴν Πειρίθου καὶ Θησέως ἄχρι τοῦ Ἅιδου ἑταιρείαν.", "st": "45.60"}, {"sp": "N", "t": "συνελόντι δὲ εἰπεῖν, οὐδὲν τῶν ὑπὸ τοῦ Ὁμήρου καὶ Ἡσιόδου καὶ τῶν ἀρίστων ποιητῶν καὶ μάλιστα τῆς τραγῳδίας λεγομένων ἀγνοήσει.", "st": "45.61"}, {"sp": "N", "t": "Ταῦτα πάνυ ὀλίγα ἐκ πολλῶν, μᾶλλον δὲ ἀπείρων τὸ πλῆθος, ἐξελὼν τὰ κεφαλαιωδέστερα κατέλεξα, τὰ ἄλλα τοῖς τε ποιηταῖς ᾄδειν ἀφεὶς καὶ τοῖς ὀρχησταῖς αὐτοῖς δεικνύναι καὶ σοὶ προσεξευρίσκειν καθ’ ὁμοιότητα τῶν προειρημένων, ἅπερ ἅπαντα πρόχειρα καὶ πρὸς τὸν καιρὸν ἕκαστον τῷ ὀρχηστῇ προπεπορισμένα καὶ προτεταμιευμένα κεῖσθαι ἀναγκαῖον.", "st": "45.61"}, {"sp": "N", "t": "ἐπεὶ δὲ μιμητικός ἐστι καὶ κινήμασι τὰ ᾀδόμενα δείξειν ὑπισχνεῖται, ἀναγκαῖον αὐτῷ, ὅπερ καὶ τοῖς ῥήτορσι, σαφήνειαν ἀσκεῖν, ὡς ἕκαστον τῶν δεικνυμένων ὑπ’ αὐτοῦ δηλοῦσθαι μηδενὸς ἐξηγητοῦ δεόμενον, ἀλλ’ ὅπερ ἔφη ὁ Πυθικὸς χρησμός, δεῖ τὸν θεώμενον ὄρχησιν καὶ κωφοῦ συνιέναι καὶ μὴ λαλέοντος τοῦ ὀρχηστοῦ ἀκούειν.", "st": "45.62"}, {"sp": "N", "t": "Ὃ δὴ καὶ Δημήτριον τὸν Κυνικὸν παθεῖν λέγουσιν. ἐπεὶ γὰρ καὶ αὐτὸς ὅμοιά σοι κατηγόρει τῆς ὀρχηστικῆς, λέγων τοῦ αὐλοῦ καὶ τῶν συρίγγων καὶ τῶν κτύπων πάρεργόν τι τὸν ὀρχηστὴν εἶναι, μηδὲν αὐτὸν πρὸς τὸ δρᾶμα συντελοῦντα, κινούμενον δὲ ἄλογον ἄλλως κίνησιν καὶ μάταιον, οὐδενὸς αὐτῇ νοῦ προσόντος, τῶν δὲ ἀνθρώπων τοῖς περὶ τὸ πρᾶγμα γοητευομένων, ἐσθῆτι σηρικῇ καὶ προσωπείῳ εὐπρεπεῖ, αὐλῷ τε καὶ τερετίσμασι καὶ τῇ τῶν ᾀδόντων εὐφωνίᾳ, οἷς κοσμεῖσθαι μηδὲν ὂν τὸ τοῦ ὀρχηστοῦ πρᾶγμα, ὁ τότε κατὰ τὸν Νέρωνα εὐδοκιμῶν ὀρχηστής, οὐκ ἀσύνετος, ὥς φασιν, ἀλλ’ εἰ καί τις ἄλλος ἔν τε ἱστορίας μνήμῃ καὶ κινήσεως κάλλει διενεγκών, ἐδεήθη τοῦ Δημητρίου εὐγνωμονεστάτην, οἶμαι, τὴν δέησιν, ἰδεῖν ὀρχούμενον, ἔπειτα κατηγορεῖν αὐτοῦ· καὶ ὑπέσχετό γε ἄνευ αὐλοῦ καὶ ᾀσμάτων ἐπιδείξεσθαι αὐτῷ. καὶ οὕτως ἐποίησεν· ἡσυχίαν γὰρ τοῖς τε κτυποῦσι καὶ τοῖς αὐλοῦσι καὶ αὐτῷ παραγγείλας τῷ χορῷ, αὐτὸς ἐφ’ ἑαυτοῦ ὠρχήσατο τὴν Ἀφροδίτης καὶ Ἄρεος μοιχείαν, Ἥλιον μηνύοντα καὶ Ἥφαιστον ἐπιβουλεύοντα καὶ τοῖς δεσμοῖς ἀμφοτέρους, τήν τε Ἀφροδίτην καὶ τὸν Ἄρη, σαγηνεύοντα, καὶ τοὺς ἐφεστῶτας θεοὺς ἕκαστον αὐτῶν, καὶ αἰδουμένην μὲν τὴν Ἀφροδίτην, ὑποδεδοικότα δὲ καὶ ἱκετεύοντα τὸν Ἄρη, καὶ ὅσα τῇ ἱστορίᾳ ταύτῃ πρόσεστιν, ὥστε τὸν Δημήτριον ὑπερησθέντα τοῖς γιγνομένοις τοῦτον ἔπαινον ἀποδοῦναι τὸν μέγιστον τῷ ὀρχηστῇ· ἀνέκραγε γὰρ καὶ μεγάλῃ τῇ φωνῇ ἀνεφθέγξατο, “ἀκούω, ἄνθρωπε, ἃ ποιεῖς· οὐχ ὁρῶ μόνον, ἀλλά μοι δοκεῖς ταῖς χερσὶν αὐταῖς λαλεῖν.”", "st": "45.63"}, {"sp": "N", "t": "ἐπεὶ δὲ κατὰ τὸν Νέρωνά ἐσμεν τῷ λόγῳ, βούλομαι καὶ βαρβάρου ἀνδρὸς τὸ ἐπὶ τοῦ αὐτοῦ ὀρχηστοῦ γενόμενον εἰπεῖν, ὅπερ μέγιστος ἔπαινος ὀρχηστικῆς γένοιτ’ ἄν. τῶν γὰρ ἐκ τοῦ Πόντου βαρβάρων βασιλικός τις ἄνθρωπος κατά τι χρέος ἥκων ὡς τὸν Νέρωνα ἐθεᾶτο μετὰ τῶν ἄλλων τὸν ὀρχηστὴν ἐκεῖνον οὕτω σαφῶς ὀρχούμενον ὡς καίτοι μὴ ἐπακούοντα τῶν ᾀδομένων — ἡμιέλλην γάρ τις ὢν ἐτύγχανεν — συνεῖναι ἁπάντων. καὶ δὴ ἀπιὼν ἤδη ἐς τὴν οἰκείαν, τοῦ Νέρωνος δεξιουμένου καὶ ὅ τι βούλοιτο αἰτεῖν κελεύοντος καὶ δώσειν ὑπισχνουμένου, “τὸν ὀρχηστήν,” ἔφη, “δοὺς τὰ μέγιστα εὐφρανεῖς.” τοῦ δὲ Νέρωνος ἐρομένου, “τί ἄν σοι χρήσιμος γένοιτο ἐκεῖ;” “προσοίκους,” ἔφη, “βαρβάρους ἔχω, οὐχ ὁμογλώττους, καὶ ἑρμηνέων οὐ ῥᾴδιον εὐπορεῖν πρὸς αὐτούς. ἢν οὖν τινος δέωμαι, διανεύων οὗτος ἕκαστά μοι ἑρμηνεύσει.” τοσοῦτον ἄρα καθίκετο αὐτοῦ ἡ μίμησις τῆς ὀρχήσεως ἐπίσημός τε καὶ σαφὴς φανεῖσα.", "st": "45.64"}, {"sp": "N", "t": "ἡ δὲ πλείστη διατριβὴ καὶ ὁ σκοπὸς τῆς ὀρχηστικῆς ἡ ὑπόκρισίς ἐστιν, ὡς ἔφην, κατὰ τὰ αὐτὰ καὶ τοῖς ῥήτορσιν ἐπιτηδευομένη, καὶ μάλιστα τοῖς τὰς καλουμένας ταύτας μελέτας διεξιοῦσιν· οὐδὲν γοῦν καὶ ἐν ἐκείνοις μᾶλλον ἐπαινοῦμεν ἢ τὸ ἐοικέναι τοῖς ὑποκειμένοις προσώποις καὶ μὴ ἀπῳδὰ εἶναι τὰ λεγόμενα τῶν εἰσαγομένων ἀριστέων ἢ τυραννοκτόνων ἢ πενήτων ἢ γεωργῶν, ἀλλ’ ἐν ἑκάστῳ τούτων τὸ ἴδιον καὶ τὸ ἐξαίρετον δείκνυσθαι.", "st": "45.65"}, {"sp": "N", "t": "ἐθέλω γοῦν σοι καὶ ἄλλου βαρβάρου ῥῆσιν ἐπὶ τούτοις εἰπεῖν. ἰδὼν γὰρ πέντε πρόσωπα τῷ ὀρχηστῇ παρεσκευασμένα — τοσούτων γὰρ μερῶν τὸ δρᾶμα ἦν — ἐζήτει, ἕνα ὁρῶν τὸν ὀρχηστήν, τίνες οἱ ὀρχησόμενοι καὶ ὑποκρινούμενοι τὰ λοιπὰ προσωπεῖα εἶεν· ἐπεὶ δὲ ἔμαθεν ὅτι αὐτὸς ὑποκρινεῖται καὶ ὑπορχήσεται τὰ πάντα, “ἐλελήθεις,” ἔφη, “ὦ βέλτιστε, σῶμα μὲν τοῦτο ἕν, πολλὰς δὲ τὰς ψυχὰς ἔχων.”", "st": "45.66"}, {"sp": "N", "t": "ταῦτα μὲν ὁ βάρβαρος. οὐκ ἀπεικότως δὲ καὶ οἱ Ἰταλιῶται τὸν ὀρχηστὴν παντόμιμον καλοῦσιν, ἀπὸ τοῦ δρωμένου σχεδόν. καλὴ γὰρ ἡ ποιητικὴ παραίνεσις ἐκείνη, τό, “ὦ παῖ, ποντίου θηρὸς πετραίου νόον ἔχων πάσαις πολίεσσιν ὁμίλει,” καὶ τῷ ὀρχηστῇ ἀναγκαία· καὶ δεῖ προσφύντα τοῖς πράγμασιν συνοικειοῦν ἑαυτὸν ἑκάστῳ τῶν δρωμένων.", "st": "45.67"}, {"sp": "N", "t": "τὸ δὲ ὅλον ἤθη καὶ πάθη δείξειν καὶ ὑποκρινεῖσθαι ἡ ὄρχησις ἐπαγγέλλεται, νῦν μὲν ἐρῶντα, νῦν δὲ ὀργιζόμενόν τινα εἰσάγουσα, καὶ ἄλλον μεμηνότα καὶ ἄλλον λελυπημένον, καὶ ἅπαντα ταῦτα μεμετρημένως. τὸ γοῦν παραδοξότατον, τῆς αὐτῆς ἡμέρας ἄρτι μὲν Ἀθάμας μεμηνώς, ἄρτι δὲ Ἰνὼ φοβουμένη δείκνυται, καὶ ἄλλοτε Ἀτρεὺς ὁ αὐτός, καὶ μετὰ μικρὸν Θυέστης, εἶτα Αἴγισθος ἢ Ἀερόπη· καὶ πάντα ταῦτα εἷς ἄνθρωπός ἐστιν.", "st": "45.67"}, {"sp": "N", "t": "τὰ μὲν οὖν ἄλλα θεάματα καὶ ἀκούσματα ἑνὸς ἑκάστου ἔργου τὴν ἐπίδειξιν ἔχει· ἢ γὰρ αὐλός ἐστιν ἢ κιθάρα ἢ διὰ φωνῆς μελῳδία ἢ τραγικὴ δραματουργία ἢ κωμικὴ γελωτοποιία· ὁ δὲ ὀρχηστὴς τὰ πάντα ἔχει συλλαβών, καὶ ἔνεστιν ποικίλην καὶ παμμιγῆ τὴν παρασκευὴν αὐτοῦ ἰδεῖν, αὐλόν, σύριγγα, ποδῶν κτύπον, κυμβάλου ψόφον, ὑποκριτοῦ εὐφωνίαν, ᾀδόντων ὁμοφωνίαν.", "st": "45.68"}, {"sp": "N", "t": "ἔτι δὲ τὰ μὲν ἄλλα θατέρου τῶν ἐν τῷ ἀνθρώπῳ ἔργα ἐστίν, τὰ μὲν ψυχῆς, τὰ δὲ σώματος· ἐν δὲ τῇ ὀρχήσει ἀμφότερα συμμέμικται. καὶ γὰρ διανοίας ἐπίδειξιν τὰ γιγνόμενα ἔχει καὶ σωματικῆς ἀσκήσεως ἐνέργειαν, τὸ δὲ μέγιστον ἡ σοφία τῶν δρωμένων καὶ τὸ μηδὲν ἔξω λόγου. Λεσβῶναξ γοῦν ὁ Μυτιληναῖος, ἀνὴρ καλὸς καὶ ἀγαθός, χειρισόφους τοὺς ὀρχηστὰς ἀπεκάλει καὶ ᾔει ἐπὶ τὴν θέαν αὐτῶν ὡς βελτίων ἀναστρέψων ἀπὸ τοῦ θεάτρου. Τιμοκράτης δὲ ὁ διδάσκαλος αὐτοῦ ἰδών ποτε ἅπαξ, οὐκ ἐξεπίτηδες ἐπιστάς, ὀρχηστὴν τὰ αὑτοῦ ποιοῦντα, “οἵου με,” ἔφη “θεάματος ἡ πρὸς φιλοσοφίαν αἰδὼς ἀπεστέρηκεν.”", "st": "45.69"}, {"sp": "N", "t": "εἰ δ’ ἔστιν ἀληθῆ ἃ περὶ ψυχῆς ὁ Πλάτων λέγει, τὰ τρία μέρη αὐτῆς καλῶς ὁ ὀρχηστὴς δείκνυσιν, τὸ θυμικὸν ὅταν ὀργιζόμενον ἐπιδείκνυται, τὸ ἐπιθυμητικὸν ὅταν ἐρῶντας ὑποκρίνηται, τὸ λογιστικὸν ὅταν ἕκαστα τῶν παθῶν χαλιναγωγῇ· τοῦτο μέν γε ἐν ἅπαντι μέρει τῆς ὀρχήσεως καθάπερ ἡ ἁφὴ ἐν ταῖς αἰσθήσεσιν παρέσπαρται. κάλλους δὲ προνοῶν καὶ τῆς ἐν τοῖς ὀρχήμασιν εὐμορφίας, τί ἄλλο ἢ τὸ τοῦ Ἀριστοτέλους ἐπαληθεύει, τὸ κάλλος ἐπαινοῦντος καὶ μέρος τρίτον ἡγουμένου τἀγαθοῦ καὶ τοῦτο εἶναι; ἤκουσα δέ τινος καὶ περιττότερόν τι νεανιευομένου ὑπὲρ τῆς τῶν ὀρχηστικῶν προσωπείων σιωπῆς, ὅτι καὶ αὕτη Πυθαγορικόν τι δόγμα αἰνίττεται.", "st": "45.70"}, {"sp": "N", "t": "ἔτι δὲ τῶν ἄλλων ἐπιτηδευμάτων τῶν μὲν τὸ τερπνόν, τῶν δὲ τὸ χρήσιμον ὑπισχνουμένων, μόνη ὄρχησις ἄμφω ἔχει, καὶ πολύ γε τὸ χρήσιμον ὠφελιμώτερον ὅσῳ μετὰ τοῦ τερπνοῦ γίγνεται. πόσῳ γὰρ τοῦτο ὁρᾶν ἥδιον ἢ πυκτεύοντας νεανίσκους καὶ αἵματι ῥεομένους, καὶ παλαίοντας ἄλλους ἐν κόνει, οὓς ἡ ὄρχησις πολλάκις ἀσφαλέστερον ἅμα καὶ εὐμορφότερον καὶ τερπνότερον ἐπιδείκνυται. τὴν μὲν οὖν γε σύντονον κίνησιν τῆς ὀρχηστικῆς καὶ στροφὰς αὐτῆς καὶ περιαγωγὰς καὶ πηδήματα καὶ ὑπτιασμοὺς τοῖς μὲν ἄλλοις τερπνὰ εἶναι συμβέβηκεν ὁρῶσιν, τοῖς δὲ ἐνεργοῦσιν αὐτοῖς ὑγιεινότατα· γυμνασίων γὰρ τὸ κάλλιστόν τε ἅμα καὶ εὐρυθμότατον τοῦτο φαίην ἂν ἔγωγε εἶναι, μαλάττον μὲν τὸ σῶμα καὶ κάμπτον καὶ κουφίζον καὶ εὐχερὲς εἶναι πρὸς μεταβολὴν διδάσκον, ἰσχύν τε οὐ μικρὰν περιποιοῦν τοῖς σώμασιν.", "st": "45.71"}, {"sp": "N", "t": "πῶς οὖν οὐ παναρμόνιόν τι χρῆμα ὄρχησις, θήγουσα μὲν τὴν ψυχήν, ἀσκοῦσα δὲ καὶ τὸ σῶμα, τέρπουσα δὲ τοὺς ὁρῶντας, διδάσκουσα δὲ πολλὰ τῶν πάλαι ὑπ’ αὐλοῖς καὶ κυμβάλοις καὶ μελῶν εὐρυθμίᾳ καὶ κηλήσει διά τε ὀφθαλμῶν καὶ ἀκοῆς; εἴτ’ οὖν φωνῆς εὐμοιρίαν ζητεῖς, ποῦ ἂν ἀλλαχόθι εὕροις, ἢ ποῖον πολυφωνότερον ἄκουσμα ἢ ἐμμελέστερον; εἴτε αὐλοῦ καὶ σύριγγος τὸ λιγυρώτερον, ἅλις καὶ τούτων ἐν ὀρχήσει ἀπολαῦσαί σοι πάρεστιν. ἐῶ λέγειν ὡς ἀμείνων τὸ ἦθος ὁμιλῶν τῇ τοιαύτῃ θέᾳ γενήσῃ, ὅταν ὁρᾷς τὸ θέατρον μισοῦν μὲν τὰ κακῶς γιγνόμενα, ἐπιδακρῦον δὲ τοῖς ἀδικουμένοις, καὶ ὅλως τὰ ἤθη τῶν ὁρώντων παιδαγωγοῦν.", "st": "45.72"}, {"sp": "N", "t": "ὃ δέ ἐστι μάλιστα ἐπὶ τῶν ὀρχηστῶν ἐπαινέσαι, τοῦτο ἤδη ἐρῶ· τὸ γὰρ ἰσχύν τε ἅμα καὶ ὑγρότητα τῶν μελῶν ἐπιτηδεύειν ὁμοίως παράδοξον εἶναί μοι δοκεῖ ὡς εἴ τις ἐν τῷ αὐτῷ καὶ Ἡρακλέους τὸ καρτερὸν καὶ Ἀφροδίτης τὸ ἁβρὸν δεικνύοι.", "st": "45.73"}, {"sp": "N", "t": "ἐθέλω δὲ ἤδη καὶ ὑποδεῖξαί σοι τῷ λόγῳ ὁποῖον χρὴ εἶναι τὸν ἄριστον ὀρχηστὴν ἔν τε ψυχῇ καὶ σώματι. καίτοι τῆς μὲν ψυχῆς προεῖπον τὰ πλεῖστα· μνημονικόν τε γὰρ εἶναι καὶ εὐφυᾶ καὶ συνετὸν καὶ ὀξὺν ἐπινοῆσαι καὶ καιροῦ μάλιστα ἐστοχάσθαι φημὶ δεῖν αὐτόν, ἔτι δὲ κριτικόν τε ποιημάτων καὶ ᾀσμάτων καὶ μελῶν τῶν ἀρίστων διαγνωστικὸν καὶ τῶν κακῶς πεποιημένων ἐλεγκτικόν.", "st": "45.74"}, {"sp": "N", "t": "τὸ δὲ σῶμα κατὰ τὸν Πολυκλείτου κανόνα ἤδη ἐπιδείξειν μοι δοκῶ· μήτε γὰρ ὑψηλὸς ἄγαν ἔστω καὶ πέρα τοῦ μετρίου ἐπιμήκης μήτε ταπεινὸς καὶ νανώδης τὴν φύσιν, ἀλλ’ ἔμμετρος ἀκριβῶς, οὔτε πολύσαρκος, ἀπίθανον γάρ, οὔτε λεπτὸς ἐς ὑπερβολήν· σκελετῶδες τοῦτο καὶ νεκρικόν.", "st": "45.75"}, {"sp": "N", "t": "ἐθέλω γοῦν σοι καὶ δήμου τινὸς οὐ φαύλου τὰ τοιαῦτα ἐπισημαίνεσθαι βοὰς εἰπεῖν· οἱ γὰρ Ἀντιοχεῖς, εὐφυεστάτη πόλις καὶ ὄρχησιν μάλιστα πρεσβεύουσα, οὕτως ἐπιτηρεῖ τῶν λεγομένων καὶ τῶν γιγνομένων ἕκαστα, ὡς μηδένα μηδὲν αὐτῶν διαλανθάνειν. μικροῦ μὲν γὰρ ὀρχηστοῦ εἰσελθόντος καὶ τὸν Ἕκτορα ὀρχουμένου μιᾷ φωνῇ πάντες ἀνεβόησαν, “ὦ Ἀστυάναξ, Ἕκτωρ δὲ ποῦ;” ἄλλοτε δέ ποτε μηκίστου τινὸς ὑπὲρ τὸ μέτριον ὀρχεῖσθαι τὸν Καπανέα ἐπιχειροῦντος καὶ προσβάλλειν τοῖς Θηβαίων τείχεσιν, “ὑπέρβηθι,” ἔφησαν, “τὸ τεῖχος, οὐδέν σοι δεῖ κλίμακος.” καὶ ἐπὶ τοῦ παχέος δὲ καὶ πιμελοῦς ὀρχηστοῦ πηδᾶν μεγάλα πειρωμένου, “δεόμεθα,” ἔφασαν, “φεῖσαι τῆς θυμέλης.” τὸ δὲ ἐναντίον τῷ πάνυ λεπτῷ ἐπεβόησαν, “καλῶς ἔχε,” ὡς νοσοῦντι. τούτων οὐ τοῦ γελοίου ἕνεκα ἐπεμνήσθην, ἀλλ’ ὡς ἴδῃς ὅτι καὶ δῆμοι ὅλοι μεγάλην σπουδὴν ἐποιήσαντο ἐπὶ τῇ ὀρχηστικῇ, ὡς ῥυθμίζειν τὰ καλὰ καὶ τὰ αἰσχρὰ αὐτῆς δύνασθαι.", "st": "45.76"}, {"sp": "N", "t": "εὐκίνητος δὲ τὸ μετὰ τοῦτο πάντως ἔστω καὶ τὸ σῶμα λελυμένος τε ἅμα καὶ συμπεπηγώς, ὡς λυγίζεσθαί τε ὅπη καιρὸς καὶ συνεστάναι καρτερῶς, εἰ τούτου δέοι.", "st": "45.77"}, {"sp": "N", "t": "ὅτι δὲ οὐκ ἀπήλλακται ὄρχησις καὶ τῆς ἐναγωνίου χειρονομίας ἀλλὰ μετέχει καὶ τῶν Ἑρμοῦ καὶ Πολυδεύκους καὶ Ἡρακλέους ἐν ἀθλήσει καλῶν ἴδοις ἂν ἑκάστῃ τῶν μιμήσεων ἐπισχών.", "st": "45.78"}, {"sp": "N", "t": "Ἡροδότῳ μὲν οὖν τὰ δι’ ὀμμάτων φαινόμενα πιστότερα εἶναι τῶν ὤτων δοκεῖ· ὀρχήσει δὲ καὶ τὰ ὤτων καὶ ὀφθαλμῶν πρόσεστιν.", "st": "45.78"}, {"sp": "N", "t": "οὕτω δὲ θέλγει ὄρχησις ὥστε ἂν ἐρῶν τις εἰς τὸ θέατρον παρέλθοι, ἐσωφρονίσθη ἰδὼν ὅσα ἔρωτος κακὰ τέλη· καὶ λύπῃ ἐχόμενος ἐξέρχεται τοῦ θεάτρου φαιδρότερος ὥσπερ τι φάρμακον ληθεδανὸν καὶ κατὰ τὸν ποιητὴν νηπενθές τε καὶ ἄχολον πιών. σημεῖον δὲ τῆς πρὸς τὰ γιγνόμενα οἰκειότητος καὶ τοῦ γνωρίζειν ἕκαστον τῶν ὁρώντων τὰ δεικνύμενα τὸ καὶ δακρύειν πολλάκις τοὺς θεατάς, ὁπόταν τι οἰκτρὸν καὶ ἐλεεινὸν φαίνηται. ἡ μέν γε Βακχικὴ ὄρχησις ἐν Ἰωνίᾳ μάλιστα καὶ ἐν Πόντῳ σπουδαζομένη, καίτοι σατυρικὴ οὖσα, οὕτω κεχείρωται τοὺς ἀνθρώπους τοὺς ἐκεῖ ὥστε κατὰ τὸν τεταγμένον ἕκαστοι καιρόν, ἁπάντων ἐπιλαθόμενοι τῶν ἄλλων, κάθηνται δι’ ἡμέρας τιτᾶνας καὶ κορύβαντας καὶ σατύρους καὶ βουκόλους ὁρῶντες. καὶ ὀρχοῦνταί γε ταῦτα οἱ εὐγενέστατοι καὶ πρωτεύοντες ἐν ἑκάστῃ τῶν πόλεων, οὐχ ὅπως αἰδούμενοι ἀλλὰ καὶ μέγα φρονοῦντες ἐπὶ τῷ πράγματι μᾶλλον ἤπερ ἐπ’ εὐγενείαις καὶ λειτουργίαις καὶ ἀξιώμασι προγονικοῖς.", "st": "45.79"}, {"sp": "N", "t": "ἐπεὶ δὲ τὰς ἀρετὰς ἔφην τὰς ὀρχηστικάς, ἄκουε καὶ τὰς κακίας αὐτῶν. τὰς μὲν οὖν ἐν σώματι ἤδη ἔδειξα, τὰς δὲ τῆς διανοίας οὕτως ἐπιτηρεῖν, οἶμαι, δύναιο ἄν. πολλοὶ γὰρ αὐτῶν ὑπ’ ἀμαθίας — ἀμήχανον γὰρ ἅπαντας εἶναι σοφούς — καὶ σολοικίας δεινὰς ἐν τῇ ὀρχήσει ἐπιδείκνυνται, οἱ μὲν ἄλογα κινούμενοι καὶ μηδέν, ὥς φασι, πρὸς τὴν χορδήν, ἕτερα μὲν γὰρ ὁ πούς, ἕτερα δ’ ὁ ῥυθμὸς λέγει· οἱ δὲ εὔρυθμα μέν, τὰ πράγματα δὲ μετάχρονα ἢ πρόχρονα, οἷον ἐγώ ποτε ἰδὼν μέμνημαι. τὰς γὰρ Διὸς γονὰς ὀρχούμενός τις καὶ τὴν τοῦ Κρόνου τεκνοφαγίαν παρωρχεῖτο τὰς Θυέστου συμφοράς, τῷ ὁμοίῳ παρηγμένος. καὶ ἄλλος τὴν Σεμέλην ὑποκρινόμενος βαλλομένην τῷ κεραυνῷ τὴν Γλαύκην αὐτῇ εἴκαζε μεταγενεστέραν οὖσαν. ἀλλ’ οὐκ ἀπό γε τῶν τοιούτων ὀρχηστῶν ὀρχήσεως αὐτῆς, οἶμαι, καταγνωστέον οὐδὲ τὸ ἔργον αὐτὸ μισητέον, ἀλλὰ τοὺς μέν, ὥσπερ εἰσίν, ἀμαθεῖς νομιστέον, ἐπαινετέον δὲ τοὺς ἐννόμως καὶ κατὰ ῥυθμὸν τῆς τέχνης ἱκανῶς ἕκαστα δρῶντας.", "st": "45.80"}, {"sp": "N", "t": "ὅλως δὲ τὸν ὀρχηστὴν δεῖ πανταχόθεν ἀπηκριβῶσθαι, ὡς εἶναι τὸ πᾶν εὔρυθμον, εὔμορφον, σύμμετρον, αὐτὸ αὑτῷ ἐοικός, ἀσυκοφάντητον, ἀνεπίληπτον, μηδαμῶς ἐλλιπές, ἐκ τῶν ἀρίστων κεκραμένον, τὰς ἐνθυμήσεις ὀξύν, τὴν παιδείαν βαθύν, τὰς ἐννοίας ἀνθρώπινον μάλιστα. ὁ γοῦν ἔπαινος αὐτῷ τότ’ ἂν γίγνοιτο ἐντελὴς παρὰ τῶν θεατῶν ὅταν ἕκαστος τῶν ὁρώντων γνωρίζῃ τὰ αὑτοῦ, μᾶλλον δὲ ὥσπερ ἐν κατόπτρῳ τῷ ὀρχηστῇ ἑαυτὸν βλέπῃ καὶ ἃ πάσχειν αὐτὸς καὶ ἃ ποιεῖν εἴωθεν· τότε γὰρ οὐδὲ κατέχειν ἑαυτοὺς οἱ ἄνθρωποι ὑφ’ ἡδονῆς δύνανται, ἀλλ’ ἀθρόοι πρὸς τὸν ἔπαινον ἐκχέονται, τὰς τῆς ἑαυτοῦ ψυχῆς ἕκαστος εἰκόνας ὁρῶντες καὶ αὑτοὺς γνωρίζοντες. ἀτεχνῶς γὰρ τὸ Δελφικὸν ἐκεῖνο τὸ Γνῶθι σεαυτὸν ἐκ τῆς θέας αὐτοῖς περιγίγνεται, καὶ ἀπέρχονται ἀπὸ τοῦ θεάτρου ἅ τε χρὴ αἱρεῖσθαι καὶ ἃ φεύγειν μεμαθηκότες καὶ ἃ πρότερον ἠγνόουν διδαχθέντες.", "st": "45.81"}, {"sp": "N", "t": "γίνεται δέ, ὥσπερ ἐν λόγοις, οὕτω δὲ καὶ ἐν ὀρχήσει ἡ πρὸς τῶν πολλῶν λεγομένη κακοζηλία ὑπερβαινόντων τὸ μέτρον τῆς μιμήσεως καὶ πέρα τοῦ δέοντος ἐπιτεινόντων, καὶ εἰ μέγα τι δεῖξαι δέοι, ὑπερμέγεθες ἐπιδεικνυμένων, καὶ εἰ ἁπαλόν, καθ’ ὑπερβολὴν θηλυνομένων, καὶ τὰ ἀνδρώδη ἄχρι τοῦ ἀγρίου καὶ θηριώδους προαγόντων.", "st": "45.82"}, {"sp": "N", "t": "οἷον ἐγώ ποτε μέμνημαι ἰδὼν ποιοῦντα ὀρχηστὴν εὐδοκιμοῦντα πρότερον, συνετὸν μὲν τὰ ἄλλα καὶ θαυμάζεσθαι ὡς ἀληθῶς ἄξιον, οὐκ οἶδα δὲ ᾗτινι τύχῃ εἰς ἀσχήμονα ὑπόκρισιν δι’ ὑπερβολὴν μιμήσεως ἐξοκείλαντα. ὀρχούμενος γὰρ τὸν Αἴαντα μετὰ τὴν ἧτταν εὐθὺς μαινόμενον, εἰς τοσοῦτον ὑπερεξέπεσεν ὥστε οὐχ ὑποκρίνασθαι μανίαν ἀλλὰ μαίνεσθαι αὐτὸς εἰκότως ἄν τινι ἔδοξεν. ἑνὸς γὰρ τῶν τῷ σιδηρῷ ὑποδήματι κτυπούντων τὴν ἐσθῆτα κατέρρηξεν, ἑνὸς δὲ τῶν ὑπαυλούντων τὸν αὐλὸν ἁρπάσας τοῦ Ὀδυσσέως πλησίον ἑστῶτος καὶ ἐπὶ τῇ νίκῃ μέγα φρονοῦντος διεῖλε τὴν κεφαλὴν κατενεγκών, καὶ εἴ γε μὴ ὁ πῖλος ἀντέσχεν καὶ τὸ πολὺ τῆς πληγῆς ἀπεδέξατο, ἀπωλώλει ἂν ὁ κακοδαίμων Ὀδυσσεύς, ὀρχηστῇ παραπαίοντι περιπεσών. ἀλλὰ τό γε θέατρον ἅπαν συνεμεμήνει τῷ Αἴαντι καὶ ἐπήδων καὶ ἐβόων καὶ τὰς ἐσθῆτας ἀνερρίπτουν, οἱ μὲν συρφετώδεις καὶ αὐτὸ τοῦτο ἰδιῶται τοῦ μὲν εὐσχήμονος οὐκ ἐστοχασμένοι οὐδὲ τὸ χεῖρον ἢ τὸ κρεῖττον ὁρῶντες, ἄκραν δὲ μίμησιν τοῦ πάθους τὰ τοιαῦτα οἰόμενοι εἶναι· οἱ ἀστειότεροι δὲ συνιέντες μὲν καὶ αἰδούμενοι ἐπὶ τοῖς γινομένοις, οὐκ ἐλέγχοντες δὲ σιωπῇ τὸ πρᾶγμα, τοῖς δὲ ἐπαίνοις καὶ αὐτοὶ τὴν ἄνοιαν τῆς ὀρχήσεως ἐπικαλύπτοντες, καὶ ἀκριβῶς ὁρῶντες ὅτι οὐκ Αἴαντος ἀλλὰ ὀρχηστοῦ μανίας τὰ γιγνόμενα ἦν. οὐ γὰρ ἀρκεσθεὶς τούτοις ὁ γενναῖος ἄλλο μακρῷ τούτου γελοιότερον ἔπραξε· καταβὰς γὰρ εἰς τὸ μέσον ἐν τῇ βουλῇ δύο ὑπατικῶν μέσος ἐκαθέζετο, πάνυ δεδιότων μὴ καὶ αὐτῶν τινα ὥσπερ κριὸν μαστιγώσῃ λαβών.", "st": "45.83"}, {"sp": "N", "t": "καὶ τὸ πρᾶγμα οἱ μὲν ἐθαύμαζον, οἱ δὲ ἐγέλων, οἱ δὲ ὑπώπτευον μὴ ἄρα ἐκ τῆς ἄγαν μιμήσεως εἰς τὴν τοῦ πάθους ἀλήθειαν ὑπηνέχθη.", "st": "45.83"}, {"sp": "N", "t": "καὶ αὐτὸν μέντοι φασὶν ἀνανήψαντα οὕτως μετανοῆσαι ἐφ’ οἷς ἐποίησεν ὥστε καὶ νοσῆσαι ὑπὸ λύπης, ὡς ἀληθῶς ἐπὶ μανίᾳ κατεγνωσμένον. καὶ ἐδήλωσέ γε τοῦτο σαφῶς αὐτός· αἰτούντων γὰρ αὖθις τῶν στασιωτῶν αὐτοῦ τὸν Αἴαντα ὀρχήσασθαι αὐτοῖς, παραιτησάμενος, “τὸν ὑποκριτήν,” ἔφη πρὸς τὸ θέατρον, “ἱκανόν ἐστιν ἅπαξ μανῆναι.” μάλιστα δὲ αὐτὸν ἠνίασεν ὁ ἀνταγωνιστὴς καὶ ἀντίτεχνος· τοῦ γὰρ ὁμοίου Αἴαντος αὐτῷ γραφέντος οὕτω κοσμίως καὶ σωφρόνως τὴν μανίαν ὑπεκρίνατο ὡς ἐπαινεθῆναι, μείνας ἐντὸς τῶν τῆς ὀρχήσεως ὅρων καὶ μὴ παροινήσας εἰς τὴν ὑπόκρισιν.", "st": "45.84"}, {"sp": "N", "t": "ταῦτά σοι, ὦ φιλότης, ὀλίγα ἐκ παμπόλλων παρέδειξα ὀρχήσεως ἔργα καὶ ἐπιτηδεύματα, ὡς μὴ πάνυ ἄχθοιό μοι ἐρωτικῶς θεωμένῳ αὐτά. εἰ δὲ βουληθείης κοινωνῆσαί μοι τῆς θέας, εὖ οἶδα ἐγὼ πάνυ ἁλωσόμενόν σε καὶ ὀρχηστομανήσοντά γε προσέτι. ὥστε οὐδὲν δεήσομαι τὸ τῆς Κίρκης ἐκεῖνο πρὸς σὲ εἰπεῖν, τὸ<br>θαῦμά μ’ ἔχει ὡς οὔτι πιὼν τάδε φάρμακ’ ἐθέλχθης,<br>θελχθήσῃ γάρ, καὶ μὰ Δί’ οὐκ ὄνου κεφαλὴν ἢ συὸς καρδίαν ἕξεις, ἀλλ’ ὁ μὲν νόος σοι ἐμπεδώτερος ἔσται, σὺ δὲ ὑφ’ ἡδονῆς οὐδὲ ὀλίγον τοῦ κυκεῶνος ἄλλῳ μεταδώσεις πιεῖν. ὅπερ γὰρ ὁ Ὅμηρος περὶ τῆς Ἑρμοῦ ῥάβδου τῆς χρυσῆς λέγει, ὅτι καὶ “ἀνδρῶν ὄμματα θέλγει δι’” αὐτῆς<br>ὧν ἐθέλει, τοὺς δ’ αὖτε καὶ ὑπνώοντας ἐγείρει,<br>τοῦτο ἀτεχνῶς ὄρχησις ποιεῖ καὶ τὰ ὄμματα θέλγουσα καὶ ἐγρηγορέναι ποιοῦσα καὶ ἐπεγείρουσα τὴν διάνοιαν πρὸς ἕκαστα τῶν δρωμένων.", "st": "45.85"}, {"sp": "N", "t": "<em>Κράτων.<\/em> καὶ μὴν ἤδη ἐγώ, ὦ Λυκῖνε, πείθομαί τέ σοι καὶ ἀναπεπταμένα ἔχω καὶ τὰ ὦτα καὶ τὰ ὄμματα. καὶ μέμνησό γε, ὦ φιλότης, ἐπειδὰν εἰς τὸ θέατρον ἴῃς, κἀμοὶ παρὰ σαυτῷ θέαν καταλαμβάνειν, ὡς μὴ μόνος ἐκεῖθεν σοφώτερος ἡμῖν ἐπανίοις.", "st": "45.85"}, {"sp": "HDR", "t": "Λεξιφάνης"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> Λεξιφάνης ὁ καλὸς μετὰ βιβλίου;", "st": "46.1"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> νὴ Δί’, ὦ Λυκῖνε, γράμμα ἐστὶν τητινόν τι τῶν ἐμῶν κομιδῇ νεοχμόν.", "st": "46.1"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἤδη γάρ τι καὶ περὶ αὐχμῶν ἡμῖν γράφεις;", "st": "46.1"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> οὐ δῆτα, οὐδὲ αὐχμὸν εἶπον, ἀλλὰ ὥρα σοι τὸ ἀρτιγραφὲς οὕτω καλεῖν. σὺ δὲ κυψελόβυστα ἔοικας ἔχειν τὰ ὦτα.", "st": "46.1"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> σύγγνωθι, ὦ ἑταῖρε· πολὺ γὰρ τοῦ αὐχμοῦ τὸ νεοχμὸν μετέχει. ἀλλ’ εἰπέ μοι, τίς ὁ νοῦς τῷ συγγράμματι;", "st": "46.1"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> ἀντισυμποσιάζω τῷ Ἀρίστωνος ἐν αὐτῷ.", "st": "46.1"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> πολλοὶ μὲν οἱ Ἀρίστωνες· σὺ δὲ ὅσον ἀπὸ τοῦ συμποσίου τὸν Πλάτωνά μοι ἔδοξας λέγειν.", "st": "46.1"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> ὀρθῶς ἀνέγνως. τὸ δὲ λεγόμενον ὡς ἄλλῳ παντὶ ἀνόητον ἂν ἦν.", "st": "46.1"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> οὐκοῦν ὀλίγα μοι αὐτοῦ ἀνάγνωθι τοῦ βιβλίου, ὅπως μὴ παντάπασιν ἀπολειποίμην τῆς ἑστιάσεως· νέκταρος γάρ τινος ἔοικας οἰνοχοήσειν ἡμῖν ἀπ’ αὐτοῦ.", "st": "46.1"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> τὸν μὲν εἴρωνα πεδοῖ κατάβαλε· σὺ δὲ εὔπορα ποιήσας τὰ ὦτα ἤδη ἄκουε. ἀπέστω δὲ ἡ ἐπιβύστρα ἡ Κυψελίς.", "st": "46.1"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> λέγε θαρρῶν, ὡς ἔμοιγε οὔτε Κύψελός τις οὔτε Περίανδρος ἐν τοῖς ὠσὶν κάθηται.", "st": "46.1"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> σκόπει δὴ μεταξύ, ὅπως διαπεραίνομαι, ὦ Λυκῖνε, τὸν λόγον, εἰ εὔαρχός τέ ἐστι καὶ πολλὴν τὴν εὐλογίαν ἐπιδεικνύμενος καὶ εὔλεξις, ἔτι δὲ εὐώνυμος.", "st": "46.1"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἔοικε τοιοῦτος εἶναι σός γε ὤν. ἀλλ’ ἄρξαι ποτέ.", "st": "46.1"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> “εἶτα δειπνήσομεν,” ἦ δ’ ὃς ὁ Καλλικλῆς, “εἶτα τὸ δειλινὸν περιδινησόμεθα ἐν Λυκείῳ, νῦν δὲ ἤδη καιρός ἐστιν χρίεσθαι τὸ ἡλιοκαὲς καὶ πρὸς τὴν εἵλην θέρεσθαι καὶ λουσαμένους ἀρτοσιτεῖν· καὶ ἤδη γε ἀπιτητέα. σὺ δέ, ὦ παῖ, στλεγγίδα μοι καὶ βύρσαν καὶ φωσώνια καὶ ῥύμματα ναυστολεῖν ἐς τὸ βαλανεῖον καὶ τοὐπίλουτρον κομίζειν· ἔχεις δὲ χαμᾶζε παρὰ τὴν ἐγγυοθήκην δύ’ ὀβολώ. σὺ δὲ τί καὶ πράξεις, ὦ Λεξίφανες, ἥξεις ἢ ἐλινύσεις ἔτι αὐτόθι;”", "st": "46.2"}, {"sp": "N", "t": "“κἀγώ,” ἦν δὲ ἐγώ, “τρίπαλαι λουτιῶ· οὐκ εὐπόρως τε γὰρ ἔχω καὶ τὰ ἀμφὶ τὴν τράμιν μαλακίζομαι ἐπ’ ἀστράβης ὀχηθείς. ὁ γὰρ ἀστραβηλάτης ἐπέσπερχεν καίτοι ἀσκωλιάζων αὐτός. ἀλλὰ καὶ ἐν αὐτῷ οὐκ ἀκμὴς ἦν τῷ ἀγρῷ· κατέλαβον γὰρ τοὺς ἐργάτας λιγυρίζοντας τὴν θερινὴν ᾠδήν, τοὺς δὲ τάφον τῷ ἐμῷ πατρὶ κατασκευάζοντας. συντυμβωρυχήσας οὖν αὐτοῖς καὶ τοῖς ἀναχοῦσιν τὰ ἄνδηρα καὶ αὐτὸς ὀλίγα συγχειροπονήσας ἐκείνους μὲν διαφῆκα τοῦ τε κρύους ἕνεκα καὶ ὅτι καύματα ἦν· οἶσθα δὲ ὡς ἐν κρύει σφοδρῷ γίνεται τὰ καύματα. ἐγὼ δὲ περιελθὼν τὰ ἀρώματα σκόροδά τε εὗρον ἐν αὐτοῖς πεφυκότα καὶ γηπαττάλους τινὰς ἀνορύξας καὶ τῶν σκανδίκων καὶ βρακάνων λαχανευσάμενος, ἔτι δὲ κάχρυς πριάμενος — οὔπω δὲ οἱ λειμῶνες ἀνθοσμίαι ἦσαν, ὡς αὐτοποδητὶ βαδίζειν — ἀνατεθεὶς ἐπὶ τὴν ἀστράβην ἐδάρην τὸν ὄρρον· καὶ νῦν βαδίζω τε ὀδυνηρῶς καὶ ἰδίω θαμὰ καὶ μαλακιῶ τὸ σῶμα καὶ δέομαι διανεῦσαι ἐν τῷ ὕδατι ἐπὶ πλεῖστον· χαίρω δὲ μετὰ κάματον ἀπολούμενος.”", "st": "46.2"}, {"sp": "N", "t": "“ἀποθρέξομαι οὖν καὶ αὐτὸς ὡς τὸν παῖδα, ὃν εἰκὸς ἢ παρὰ τῇ λεκιθοπώλιδι ἢ παρὰ τῷ γρυμαιοπώλῃ με περιμένειν· καίτοι προηγόρευτο αὐτῷ ἐπὶ τὰ γέλγη ἀπαντᾶν.", "st": "46.3"}, {"sp": "N", "t": "ἀλλ’ εἰς καιρὸν οὑτοσὶ αὐτὸς ἐμπολήσας γε, ὡς ὁρῶ, πυριάτην τέ τινα καὶ ἐγκρυφίας καὶ γήτεια καὶ φύκας καὶ οἶβον τουτονὶ καὶ λωγάνιον καὶ τοῦ βοὸς τὸ πολύπτυχον ἔγκατον καὶ φώκτας. εὖ γε, ὦ Ἀττικίων, ὅτι μοι ἄβατον ἐποίησας τὸ πολὺ τῆς ὁδοῦ.” “ἐγὼ δέ,” ἦ δ’ ὅς, “σίλλος, ὦ δέσποτα, γεγένημαι σὲ περιορῶν. σὺ δὲ ποῦ χθὲς ἐδείπνεις; μῶν παρὰ Ὀνομακρίτῳ;” “οὔ, μὰ Δί’.” ἦν δ’ ἐγώ, “ἀλλ’ ἀγρόνδε ᾠχόμην ψύττα κατατείνας· οἶσθα δὲ ὡς φίλαγρός εἰμι. ὑμεῖς δὲ ἴσως ᾤεσθέ με λαταγεῖν κοττάβους. ἀλλ’ εἰσιὼν ταῦτά τε καὶ τὰ ἄλλα ἡδύνειν καὶ τὴν κάρδοπον σμῆν, ὡς θριδακίνας μάττοιτε ἡμῖν.", "st": "46.3"}, {"sp": "N", "t": "ἐγὼ δὲ ξηραλοιφήσω ἀπελθών.”", "st": "46.4"}, {"sp": "N", "t": "“καὶ ἡμεῖς,” ἦ δ’ ὃς ὁ Φιλῖνος, “ἐγώ τε καὶ Ὀνόμαρχος καὶ Ἑλλάνικος οὑτοσὶ ἑψόμεθα· καὶ γὰρ ὁ γνώμων σκιάζει μέσην τὴν πόλον, καὶ δέος μὴ ἐν λουτρίῳ ἀπολουσώμεθα κατόπιν τῶν Καριμάντων μετὰ τοῦ σύρφακος βύζην ὠστιζόμενοι.” καὶ ὁ Ἑλλάνικος ἔφη, “ἐγὼ δὲ καὶ δυσωπῶ· καὶ γὰρ τὰ κόρα μοι ἐπιτεθόλωσθον καὶ σκαρδαμύττω θαμὰ καὶ ἀρτίδακρύς εἰμι καὶ τὰ ὄμματά μοι φαρμακᾷ καὶ δέομαι Ἀσκληπιάδου τινὸς ὀφθαλμοσόφου, ὃς ταράξας καὶ ἐγχέας μοι φάρμακον ἀπερυθριᾶσαί τε ποιήσει τοὺς ὀφθαλμοὺς καὶ μηκέτι τι λημαλέους εἶναι μηδὲ διερὸν βλέπειν.”", "st": "46.4"}, {"sp": "N", "t": "τοιαῦτα ἄττα διεξιόντες ἅπαντες οἱ παρόντες ἀπῄειμεν· κἀπειδήπερ ἥκομεν εἰς τὸ γυμνάσιον ἀπησθημένοι ἤδη, ὁ μέν τις ἀκροχειριασμῷ, ὁ δὲ τραχηλισμῷ καὶ ὀρθοπάλῃ ἐχρῆτο, ὁ δὲ λίπα χρισάμενος ἐλυγίζετο, ὁ δὲ ἀντέβαλλε τῷ κωρύκῳ, ὁ δὲ μολυβδαίνας χερμαδίους δράγδην ἔχων ἐχειροβόλει. εἶτα συντριβέντες καὶ ἀλλήλους κατανωτισάμενοι καὶ ἐμπαίξαντες τῷ γυμνασίῳ ἐγὼ μὲν καὶ Φιλῖνος ἐν τῇ θερμῇ πυέλῳ καταιονηθέντες ἐξῄειμεν· οἱ λοιποὶ δὲ τὸ ψυχροβαφὲς κάρα δελφινίσαντες παρένεον ὑποβρύχιοι θαυμασίως.", "st": "46.5"}, {"sp": "N", "t": "ἀναστρέψαντες δὲ αὖθις ἄλλος ἄλλοσε ἄλλα ἐδρῶμεν. ἐγὼ μὲν ὑποδησάμενος ἐξυόμην τὴν κεφαλὴν τῇ ὀδοντωτῇ ξύστρᾳ· καὶ γὰρ οὐ κηπίον, ἀλλὰ σκάφιον ἐκεκάρμην, ὡς ἂν οὐ πρὸ πολλοῦ τὸν κόννον καὶ τὴν κορυφαίαν ἀποκεκομηκώς· ἄλλος ἐθερμοτράγει, ὁ δὲ ἤμει τὸν νῆστιν, ὁ δὲ ἀραιὰς ποιῶν τὰς ῥαφανῖδας ἐμυστιλᾶτο τοῦ ἰχθυηροῦ ζωμοῦ, ἄλλος ἤσθιεν φαυλίας, ὁ δὲ ἐρρόφει τῶν κριθῶν.", "st": "46.5"}, {"sp": "N", "t": "κἀπειδὴ καιρὸς ἦν, ἐπ’ ἀγκῶνος ἐδειπνοῦμεν· ἔκειντο δὲ καὶ ὀκλαδίαι καὶ ἀσκάνται. τὸ μὲν δὴ δεῖπνον ἦν ἀπὸ συμφορῶν. παρεσκεύαστο δὲ πολλὰ καὶ ποικίλα, δίχηλα ὕεια καὶ σχελίδες καὶ ἠτριαία καὶ τοκάδος ὑὸς τὸ ἐμβρυοδόχον ἔντερον καὶ λοβὸς ἐκ ταγήνου καὶ μυττωτὸς καὶ ἀβυρτάκη καὶ τοιαῦταί τινες καρυκεῖαι καὶ θρυμματίδες καὶ θρῖα καὶ μελιτοῦτται· τῶν δὲ ὑποβρυχίων τὰ σελάχια πολλὰ καὶ ὅσα ὀστράκινα τὸ δέρμα καὶ τεμάχη Ποντικὰ τῶν ἐκ σαργάνης καὶ κωπαΐδες καὶ ὄρνις σύντροφος καὶ ἀλεκτρυὼν ἤδη ἀπῳδὸς καὶ ἰχθὺς ἦν παράσιτος· καὶ οἶν δὲ ὅλον ἰπνοκαῆ εἴχομεν καὶ βοὸς λειπογνώμονος κωλῆν. ἄρτοι μέντοι ἦσαν σιφαῖοι, οὐ φαῦλοι, καὶ ἄλλοι νουμήνιοι, ὑπερήμεροι τῆς ἑορτῆς, καὶ λάχανα τά τε ὑπόγεια καὶ τὰ ὑπερφυῆ· οἶνος δὲ ἦν οὐ γέρων, ἀλλὰ τῶν ἀπὸ βύρσης, ἤδη μὲν ἀγλευκής, ἄπεπτος δὲ ἔτι.", "st": "46.6"}, {"sp": "N", "t": "ποτήρια δὲ ἔκειτο παντοῖα ἐπὶ τῆς δελφίδος τραπέζης, ὁ κρυψιμέτωπος καὶ τρυήλης Μεντορουργὴς εὐλαβῆ ἔχων τὴν κέρκον καὶ βομβυλιὸς καὶ δειροκύπελλον καὶ γηγενῆ πολλὰ οἷα Θηρικλῆς ὤπτα, εὐρυχαδῆ τε καὶ ἄλλα εὔστομα, τὰ μὲν Φωκαῆθεν, τὰ δὲ Κνιδόθεν, πάντα μέντοι ἀνεμοφόρητα καὶ ὑμενόστρακα. κυμβία δὲ ἦν καὶ φιαλίδες καὶ ποτήρια γραμματικά, ὥστε μεστὸν ἦν τὸ κυλικεῖον.", "st": "46.7"}, {"sp": "N", "t": "ὁ μέντοι ἰπνολέβης ὑπερπαφλάζων ἐς κεφαλὴν ἡμῖν ἐπέτρεπε τοὺς ἄνθρακας. ἐπίνομεν δὲ ἀμυστὶ καὶ ἤδη ἀκροθώρακες ἦμεν· εἶτ’ ἐχριόμεθα βακχάριδι καὶ εἰσεκύκλησέ τις ἡμῖν τὴν ποδοκτύπην καὶ τριγωνίστριαν· μετὰ δὲ ὁ μέν τις ἐπὶ τὴν κατήλιφα ἀναρριχησάμενος … ἐπιφόρημα ἐζήτει, ὁ δὲ ληκίνδα ἔπαιζεν, ἄλλος ἐρρικνοῦτο σὺν γέλωτι τὴν ὀσφῦν.", "st": "46.8"}, {"sp": "N", "t": "καὶ ἐν ταὐτῷ λελουμένοι εἰσεκώμασαν ἡμῖν αὐτεπάγγελτοι Μεγαλώνυμός τε ὁ δικοδίφης καὶ Χαιρέας ὁ χρυσοτέκτων ὁ κατὰ νώτου ποικίλος καὶ ὁ ὠτοκάταξις Εὔδημος. κἀγὼ ἠρόμην αὐτούς, τί παθόντες ὀψὲ ἥκοιεν. ὁ μὲν οὖν Χαιρέας, “ἐγώ,” ἦ δ’ ὅς, “λῆρόν τινα ἐκρότουν καὶ ἐλλόβια καὶ πέδας τῇ θυγατρὶ τῇ ἐμῇ καὶ διὰ τοῦτο ὑμῖν ἐπιδείπνιος ἀφῖγμαι,” “ἐγὼ δέ,” ἦ δ’ ὃς ὁ Μεγαλώνυμος, “περὶ ἄλλα εἶχον· ἦν μὲν γὰρ ἄδικος ἡ ἡμέρα, ὡς ἴστε, καὶ ἄλογος· ὡς ἂν οὖν ἐχεγλωττίας οὔσης οὔτε ῥησιμετρεῖν εἶχον οὔτε ἡμερολεγδὸν προσυδρονομεῖσθαι· πυθόμενος δὲ ὅτι ὁ στρατηγὸς ὀπτός ἐστιν, λαβὼν ἄχρηστα ἱμάτια εὐήτρια καὶ ἀφόρητα ὑποδήματα ἐξέφρησα ἐμαυτόν.", "st": "46.9"}, {"sp": "N", "t": "εἶτ’ εὐθὺς ἐντυγχάνω δᾳδούχῳ τε καὶ ἱεροφάντῃ καὶ τοῖς ἄλλοις ἀρρητοποιοῖς Δεινίαν σύρουσιν ἄγδην ἐπὶ τὴν ἀρχήν, ἔγκλημα ἐπάγοντας ὅτι ὠνόμαζεν αὐτούς, καὶ ταῦτα εὖ εἰδὼς ὅτι ἐξ οὗπερ ὡσιώθησαν, ἀνώνυμοί τέ εἰσι καὶ οὐκέτι ὀνομαστοὶ ὡς ἂν ἱερώνυμοι ἤδη γεγενημένοι.”", "st": "46.10"}, {"sp": "N", "t": "“οὐκ οἶδα,” ἦν δ’ ἐγώ, “ὃν λέγεις τὸν Δεινίαν· αἰκάλλει δ’ οὖν με τοὔνομα.” “ἔστιν,” ἦ δ’ ὅς, “ἐν τοῖς σκιραφείοις ἐγκαψικήδαλος ἄνθρωπος τῶν αὐτοληκύθων καὶ τῶν αὐτοκαβδάλων, ἀεὶ κουριῶν, ἐνδρομίδας ὑποδούμενος ἢ βαυκίδας, ἀμφιμάσχαλον ἔχων.” “τί οὖν,” ἦν δ’ ἐγώ, “ἔδωκεν ἀμηγέπη δίκην ἢ λὰξ πατήσας ᾤχετο;” “καὶ μὴν ἐκεῖνός γε,” ἦ δ’ ὅς, “ὁ τέως σαυλούμενος, ἤδη ἔμπεδός ἐστιν· ὁ γὰρ στρατηγὸς καίτοι ἀτιμαγελοῦντι καρπόδεσμά τε αὐτῷ περιθεὶς καὶ περιδέραιον ἐν ποδοκάκαις καὶ ποδοστράβαις ἐποίησεν εἶναι. ὥστε ἔνδεσμος ὢν ὑπέβδυλλέν τε ὁ κακοδαίμων ὑπὸ τοῦ δέους καὶ πορδαλέος ἦν καὶ χρήματα ἀντίψυχα διδόναι ἤθελεν.”", "st": "46.10"}, {"sp": "N", "t": "“ἐμὲ δέ,” ἦ δ’ ὃς ὁ Εὔδημος, “ὑπὸ τὸ ἀκροκνεφὲς μετεστείλατο Δαμασίας ὁ πάλαι μὲν ἀθλητὴς καὶ πολυνίκης, νῦν δὲ ἤδη ὑπὸ γήρως ἔξαθλος ὤν· οἶσθα τὸν χαλκοῦν τὸν ἑστῶτα ἐν τῇ ἀγορᾷ. καὶ τὰ μὲν πιττῶν τὰ δὲ εὕων διετέλεσεν, ἐξοικιεῖν γὰρ ἔμελλε τήμερον εἰς ἀνδρὸς τὴν θυγατέρα καὶ ἤδη ἐκάλλυνεν αὐτήν. εἶτα Τερμέριόν τι κακὸν ἐμπεσὸν διέκοψε τὴν ἑορτήν· ὁ γὰρ υἱὸς αὐτοῦ ὁ Δίων, οὐκ οἶδ’ ἐφ’ ὅτῳ λυπηθείς, μᾶλλον δὲ θεοσεχθρίᾳ σχεθείς, ἀπῆγξεν ἑαυτόν, καὶ εὖ ἴστε, ἀπωλώλει ἄν, εἰ μὴ ἐγὼ ἐπιστὰς ἀπηγχόνισά τε αὐτὸν καὶ παρέλυσα τῆς ἐμβροχῆς, ἐπὶ πολύ τε ὀκλὰξ παρακαθήμενος ἐπένυσσον τὸν ἄνθρωπον, βαυκαλῶν καὶ διακωδωνίζων, μή πῃ ἔτι συνεχὴς εἴη τὴν φάρυγγα. τὸ δὲ μάλιστα ὀνῆσαν ἐκεῖνο ἦν, ὅτι ἀμφοτέραις κατασχὼν αὐτοῦ τὰ ἄκρα διεπίεσα.”", "st": "46.11"}, {"sp": "N", "t": "“μῶν ἐκεῖνον,” ἦν δ’ ἐγώ, “φὴς Δίωνα τὸν καταπύγονα καὶ λακκοσχέαν, τὸν μύρτωνα καὶ σχινοτρώκταν νεανίσκον, ἀναφλῶντα καὶ βλιμάζοντα, ἤν τινα πεώδη καὶ πόσθωνα αἴσθηται; μίνθων ἐκεῖνός γε καὶ λαικαλέος.” “ἀλλὰ τοί γε τὴν θεόν,” ἦ δ’ ὃς ὁ Εὔδημος, “θαυμάσας — Ἄρτεμις γάρ ἐστιν αὐτοῖς ἐν μέσῃ τῇ αὐλῇ, Σκοπάδειον ἔργον — ταύτῃ προσπεσόντες ὅ τε Δαμασίας καὶ ἡ γυνὴ αὐτοῦ, πρεσβῦτις ἤδη καὶ τὴν κεφαλὴν πολιὰς ἀκριβῶς, ἱκέτευον ἐλεῆσαι σφᾶς· ἡ δὲ αὐτίκα ἐπένευσεν, καὶ σῶς ἦν, καὶ νῦν Θεόδωρον, μᾶλλον δὲ περιφανῶς Ἀρτεμίδωρον ἔχουσι τὸν νεανίσκον. ἀνέθεσαν οὖν αὐτῇ τά τε ἄλλα καὶ βέλη καὶ τόξα, ὅτι χαίρει τούτοις· τοξότις γὰρ καὶ ἑκηβόλος καὶ τηλέμαχος ἡ Ἄρτεμις.”", "st": "46.12"}, {"sp": "N", "t": "“πίνωμεν οὖν,” ἦ δ’ ὃς ὁ Μεγαλώνυμος, “καὶ γὰρ καὶ λάγυνον τουτονὶ παρηβηκότος ἥκω ὑμῖν κομίζων καὶ τυροῦ τροφαλίδας καὶ ἐλαίας χαμαιπετεῖς — φυλάττω δ’ αὐτὰς ὑπὸ σφραγῖσιν θριπηδέστοις — καὶ ἄλλας ἐλαίας νευστὰς καὶ πήλινα ταυτὶ ποτήρια, ὀξυόστρακα, εὐπυνδάκωτα, ὡς ἐξ αὐτῶν πίνοιμεν, καὶ πλακοῦντα ἐξ ἐντέρων κρωβυλώδη τὴν πλοκήν. σὺ δ’, ὦ παῖ, πλέον μοι τοῦ ὕδατος ἔγχει, ὡς μὴ καραιβαρεῖν ἀρξαίμην κᾆτά σοι τὸν παιδοβοσκὸν καλῶ ἐπὶ σέ· ἴστε γὰρ ὡς ὀδυνῶμαι καὶ διέμπιλον ἔχω τὴν κεφαλήν.", "st": "46.13"}, {"sp": "N", "t": "μετὰ δὲ τὸν ποτὸν συνυθλήσομεν οἷα καὶ ἅττ’ ἐώθαμεν· οὐ γὰρ ἄκαιρον δήπουθεν ἐν οἴνῳ φλύειν.”", "st": "46.14"}, {"sp": "N", "t": "“ἐπαινῶ τοῦτο,” ἦν δ’ ἐγώ, “καὶ γὰρ ὅτιπερ ὄφελός ἐσμεν τῆς ἀττικίσεως ἄκρον.” “εὖ λέγεις,” ἦ δ’ ὃς ὁ Καλλικλῆς· “τὸ γὰρ ἐρεσχηλεῖν ἀλλήλους συχνάκις λάλης θηγάνη γίγνεται.” “ἐγὼ δέ,” ἦ δ’ ὃς ὁ Εὔδημος — “κρύος γάρ ἐστιν — ἥδιον ἂν εὐζωροτέρῳ ὑποπυκνάζοιμι· καὶ γὰρ χειμοθνής εἰμι, καὶ χλιανθεὶς ἥδιον ἂν ἀκούοιμι τῶν χειρεσόφων τούτων, τοῦ τε αὐλητοῦ καὶ τῆς βαρβιτῳδοῦ.”", "st": "46.14"}, {"sp": "N", "t": "“τί ταῦτα ἔφησθα, ὦ Εὔδημε; ἦν” δ’ ἐγώ· “ἀλογίαν ἡμῖν ἐπιτάττεις ὡς ἀστόμοις οὖσι καὶ ἀπεγλωττισμένοις; ἐμοὶ δὲ ἡ γλῶττά τε ἤδη λογᾷ καὶ δὴ ἀνηγόμην γε ὡς ἀρχαιολογήσων ὑμῖν καὶ κατανίψων ἀπὸ γλώττης ἅπαντας. ἀλλὰ σὺ τὸ ὅμοιον εἰργάσω με ὥσπερ εἴ τις ὁλκάδα τριάρμενον ἐν οὐρίῳ πλέουσαν, ἐμπεπνευματωμένου τοῦ ἀκατίου, εὐφοροῦσάν τε καὶ ἀκροκυματοῦσαν, ἕκτοράς τινας ἀμφιστόμους καὶ ἰσχάδας σιδηρᾶς ἀφεὶς καὶ ναυσιπέδας ἀναχαιτίζοι τοῦ δρόμου τὸ ῥόθιον, φθόνῳ τῆς εὐηνεμίας.”", "st": "46.15"}, {"sp": "N", "t": "“Οὐκοῦν,” ἦ δ’ ὅς, “σὺ μέν, εἰ βούλει, πλεῖ καὶ νεῖ καὶ θεῖ κατὰ τοῦ κλύδωνος, ἐγὼ δὲ ἀπόγειος πίνων ἅμα ὥσπερ ὁ τοῦ Ὁμήρου Ζεὺς ἢ ἀπὸ φαλάκρων ἢ ἀπὸ τῆς ἀκρουρανίας ὄψομαι διαφερόμενόν σέ τε καὶ τὴν ναῦν πρύμνηθεν ὑπὸ τοῦ ἀνέμου κατουρουμένην.”", "st": "46.15"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> ἅλις, ὦ Λεξίφανες, καὶ ποτοῦ καὶ ἀναγνώσεως. ἐγὼ γοῦν ἤδη μεθύω σοι καὶ ναυτιῶ καὶ ἢν μὴ τάχιστα ἐξεμέσω πάντα ταῦτα ὁπόσα διεξελήλυθας, εὖ ἴσθι, κορυβαντιάσειν μοι δοκῶ περιβομβούμενος ὑφ’ ὧν κατεσκέδασάς μου ὀνομάτων. καίτοι τὸ μὲν πρῶτον γελᾶν ἐπῄει μοι ἐπ’ αὐτοῖς, ἐπειδὴ δὲ πολλὰ καὶ πάντα ὅμοια ἦν, ἠλέουν σε τῆς κακοδαιμονίας ὁρῶν εἰς λαβύρινθον ἄφυκτον ἐμπεπτωκότα καὶ νοσοῦντα νόσον τὴν μεγίστην, μᾶλλον δὲ μελαγχολῶντα.", "st": "46.16"}, {"sp": "N", "t": "ζητῶ οὖν πρὸς ἐμαυτὸν ὁπόθεν τὰ τοσαῦτα κακὰ συνελέξω καὶ ἐν ὁπόσῳ χρόνῳ καὶ ὅπου κατακλείσας εἶχες τοσοῦτον ἐσμὸν ἀτόπων καὶ διαστρόφων ὀνομάτων, ὧν τὰ μὲν αὐτὸς ἐποίησας, τὰ δὲ κατορωρυγμένα ποθὲν ἀνασπῶν κατὰ τὸ ἰαμβεῖον<br>ὄλοιο θνητῶν ἐκλέγων τὰς συμφοράς·<br>τοσοῦτον βόρβορον συνερανίσας κατήντλησάς μου μηδέν σε δεινὸν εἰργασμένου. δοκεῖς δέ μοι μήτε φίλον τινὰ ἢ οἰκεῖον ἢ εὔνουν ἔχειν μήτε ἀνδρὶ ἐλευθέρῳ πώποτε καὶ παρρησίαν ἄγοντι ἐντετυχηκέναι, ὃς τἀληθὲς εἰπὼν ἔπαυσεν ἄν σε ὑδέρῳ μὲν ἐχόμενον καὶ ὑπὸ τοῦ πάθους διαρραγῆναι κινδυνεύοντα, σαυτῷ δὲ εὔσαρκον εἶναι δοκοῦντα καὶ εὐρωστίαν οἰόμενον τὴν συμφορὰν καὶ ὑπὸ μὲν τῶν ἀνοήτων ἐπαινούμενον ἀγνοούντων ἃ πάσχεις, ὑπὸ δὲ τῶν πεπαιδευμένων εἰκότως ἐλεούμενον.", "st": "46.17"}, {"sp": "N", "t": "ἀλλ’ εἰς καλὸν γὰρ τουτονὶ Σώπολιν ὁρῶ τὸν ἰατρὸν προσιόντα, φέρε τούτῳ ἐγχειρίσαντές σε καὶ διαλεχθέντες ὑπὲρ τῆς νόσου ἴασίν τινά σοι εὑρώμεθα· συνετὸς γὰρ ἁνὴρ καὶ πολλοὺς ἤδη παραλαβὼν ὥσπερ σὲ ἡμιμανεῖς καὶ κορυζῶντας ἀπήλλαξεν ἐγχέας φάρμακον. χαῖρε, Σώπολι, καὶ τουτονὶ Λεξιφάνην παραλαβὼν ἑταῖρον, ὡς οἶσθα, ἡμῖν ὄντα, λήρῳ δὲ νῦν καὶ ξένῃ περὶ τὴν φωνὴν νόσῳ ξυνόντα καὶ κινδυνεύοντα ἤδη τελέως ἀπολωλέναι σῶσον ἑνί γέ τῳ τρόπῳ.", "st": "46.18"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> μὴ ἐμέ, Σώπολι, ἀλλὰ τουτονὶ Λυκῖνον, ὃς περιφανῶς μακκοᾷ καὶ ἄνδρας πεφρενωμένους ὀλισθογνωμονεῖν οἴεται καὶ κατὰ τὸν Μνησάρχου τὸν Σάμιον σιωπὴν καὶ γλωτταργίαν ἡμῖν ἐπιβάλλει. ἀλλὰ μὰ τὴν ἀναίσχυντον Ἀθηνᾶν καὶ τὸν μέγαν θηριομάχον Ἡρακλέα οὐδ’ ὅσον τοῦ γρῦ καὶ τοῦ φνεῖ φροντιοῦμεν αὐτοῦ· ὀττεύομαι γοῦν μηδὲ ὅλως ἐντυγχάνειν αὐτῷ. ἔοικα δὲ καὶ ῥιναυλήσειν τοιαῦτα ἐπιτιμῶντος ἀκούων. καὶ ἤδη γε ἄπειμι παρὰ τὸν ἑταῖρον Κλεινίαν, ὅτι πυνθάνομαι χρόνου ἤδη ἀκάθαρτον εἶναι αὐτῷ τὴν γυναῖκα καὶ ταύτην νοσεῖν, ὅτι μὴ ῥεῖ. ὥστε οὐκέτι οὐδ’ ἀναβαίνει αὐτήν, ἀλλ’ ἄβατος καὶ ἀνήροτός ἐστιν.", "st": "46.19"}, {"sp": "N", "t": "<em>Σώπολις.<\/em> τί δὲ νοσεῖ, ὦ Λυκῖνε, Λεξιφάνης;", "st": "46.20"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> αὐτὰ ταῦτα, ὦ Σώπολι. οὐκ ἀκούεις οἷα φθέγγεται; καὶ ἡμᾶς τοὺς νῦν προσομιλοῦντας καταλιπὼν πρὸ χιλίων ἐτῶν ἡμῖν διαλέγεται διαστρέφων τὴν γλῶτταν καὶ ταυτὶ τὰ ἀλλόκοτα συντιθεὶς καὶ σπουδὴν ποιούμενος ἐπ’ αὐτοῖς, ὡς δή τι μέγα ὄν, εἴ τι ξενίζοι καὶ τὸ καθεστηκὸς νόμισμα τῆς φωνῆς παρακόπτοι.", "st": "46.20"}, {"sp": "N", "t": "<em>Σώπολις.<\/em> μὰ Δί’ οὐ μικράν τινα λέγεις τὴν νόσον, ὦ Λυκῖνε. βοηθητέα γοῦν τῷ ἀνδρὶ πάσῃ μηχανῇ καὶ — κατὰ θεὸν γὰρ τῶν χολώντων τινι φάρμακον τουτὶ κερασάμενος ἀπῄειν, ὡς πιὼν ἐμέσειε — φέρε πρῶτος αὐτὸς πῖθι, ὦ Λεξίφανες, ὡς ὑγιὴς ἡμῖν καὶ καθαρὸς γένοιο, τῆς τοιαύτης τῶν λόγων ἀτοπίας κενωθείς. ἀλλὰ πείσθητί μοι καὶ πῖθι καὶ ῥᾴων ἔσῃ.", "st": "46.20"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> οὐκ οἶδ’ ὃ καὶ δράσετέ με, ὦ Σώπολι, σύ τε καὶ Λυκῖνος, πιπίσκοντες τουτουὶ τοῦ φαρμάκου. δέδοικα γοῦν μὴ πῶμα γένοιτό μοι τοῦτο τῶν λόγων τὸ πόμα.", "st": "46.20"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> πῖθι καὶ μὴ μέλλε, ὡς ἀνθρώπινα ἤδη φρονοίης καὶ λέγοις.", "st": "46.20"}, {"sp": "N", "t": "<em>Λεξιφάνης.<\/em> ἰδοὺ πείθομαι καὶ πίομαι. φεῦ, τί τοῦτο; πολὺς ὁ βορβορυγμός. ἐγγαστρίμυθόν τινα ἔοικα πεπωκέναι.", "st": "46.20"}, {"sp": "N", "t": "<em>Σώπολις.<\/em> ἄρξαι δὴ ἐμεῖν. βαβαί. πρῶτον τουτὶ τὸ μῶν, εἶτα μετ’ αὐτὸ ἐξελήλυθεν τὸ κᾆτα, εἶτα ἐπ’ αὐτοῖς τὸ ἦ δ’ ὅς καὶ ἀμηγέπη καὶ λῷστε καὶ δήπουθεν καὶ συνεχὲς τὸ ἄττα. βίασαι δ’ ὅμως, καὶ κάθες εἰς τὴν φάρυγγα τοὺς δακτύλους. οὐδέπω τὸ ἴκταρ ἐμήμεκας οὐδὲ τὸ σκορδινᾶσθαι οὐδὲ τὸ τευτάζεσθαι οὐδὲ τὸ σκύλλεσθαι. πολλὰ ἔτι ὑποδέδυκε καὶ μεστή σοι αὐτῶν ἡ γαστήρ. ἄμεινον δέ, εἰ καὶ κάτω διαχωρήσειεν ἂν ἔνια· ἡ γοῦν σιληπορδία μέγαν τὸν ψόφον ἐργάσεται συνεκπεσοῦσα μετὰ τοῦ πνεύματος.", "st": "46.21"}, {"sp": "N", "t": "ἀλλ’ ἤδη μὲν καθαρὸς οὑτοσὶ πλὴν εἴ τι μεμένηκεν ὑπόλοιπον ἐν τοῖς κάτω ἐντέροις. σὺ δὲ τὸ μετὰ τοῦτο παραλαβὼν αὐτόν, ὦ Λυκῖνε, μεταπαίδευε καὶ δίδασκε ἃ χρὴ λέγειν.", "st": "46.21"}, {"sp": "N", "t": "<em>Λυκῖνος.<\/em> οὕτω ποιήσομεν, ὦ Σώπολι, ἐπειδήπερ ἡμῖν προωδοποίηται τὰ παρὰ σοῦ· καὶ πρὸς σὲ τὸ λοιπόν, ὦ Λεξίφανες, ἡ συμβουλή. εἴπερ ἄρ’ ἐθέλεις ὡς ἀληθῶς ἐπαινεῖσθαι ἐπὶ λόγοις κἀν τοῖς πλήθεσιν εὐδοκιμεῖν, τὰ μὲν τοιαῦτα πάντα φεῦγε καὶ ἀποτρέπου, ἀρξάμενος δὲ ἀπὸ τῶν ἀρίστων ποιητῶν καὶ ὑπὸ διδασκάλοις αὐτοὺς ἀναγνοὺς μέτιθι ἐπὶ τοὺς ῥήτορας, καὶ τῇ ἐκείνων φωνῇ συντραφεὶς ἐπὶ τὰ Θουκυδίδου καὶ Πλάτωνος ἐν καιρῷ μέτιθι, πολλὰ καὶ τῇ καλῇ κωμῳδίᾳ καὶ τῇ σεμνῇ τραγῳδίᾳ ἐγγεγυμνασμένος· παρὰ γὰρ τούτων ἅπαντα τὰ κάλλιστα ἀπανθισάμενος ἔσῃ τις ἐν λόγοις· ὡς νῦν γε ἐλελήθεις σαυτὸν τοῖς ὑπὸ τῶν κοροπλάθων εἰς τὴν ἀγορὰν πλαττομένοις ἐοικώς, κεχρωσμένος μὲν τῇ μίλτῳ καὶ τῷ κυανῷ, τὸ δ’ ἔνδοθεν πήλινός τε καὶ εὔθρυπτος ὤν.", "st": "46.22"}, {"sp": "N", "t": "ἐὰν ταῦτα ποιῇς, πρὸς ὀλίγον τὸν ἐπὶ τῇ ἀπαιδευσίᾳ ἔλεγχον ὑπομείνας καὶ μὴ αἰδεσθεὶς μεταμανθάνων, θαρρῶν ὁμιλήσεις τοῖς πλήθεσι καὶ οὐ καταγελασθήσῃ ὥσπερ νῦν οὐδὲ διὰ στόματος ἐπὶ τῷ χείρονι τοῖς ἀρίστοις ἔσῃ, Ἕλληνα καὶ Ἀττικὸν ἀποκαλούντων σε τὸν μηδὲ βαρβάρων ἐν τοῖς σαφεστάτοις ἀριθμεῖσθαι ἄξιον. πρὸ πάντων δὲ ἐκεῖνο μέμνησό μοι, μὴ μιμεῖσθαι τῶν ὀλίγον πρὸ ἡμῶν γενομένων σοφιστῶν τὰ φαυλότατα μηδὲ περιεσθίειν ἐκεῖνα ὥσπερ νῦν, ἀλλὰ τὰ μὲν τοιαῦτα καταπατεῖν, ζηλοῦν δὲ τὰ ἀρχαῖα τῶν παραδειγμάτων. μηδέ σε θελγέτωσαν αἱ ἀνεμῶναι τῶν λόγων, ἀλλὰ κατὰ τὸν τῶν ἀθλητῶν νόμον ἡ στερρά σοι τροφὴ συνήθης ἔστω, μάλιστα δὲ Χάρισι καὶ Σαφηνείᾳ θῦε, ὧν πάμπολυ λίαν νῦν ἀπελέλειψο.", "st": "46.23"}, {"sp": "N", "t": "καὶ ὁ τῦφος δὲ καὶ ἡ μεγαλαυχία καὶ ἡ κακοήθεια καὶ τὸ βρενθύεσθαι καὶ λαρυγγίζειν ἀπέστω, καὶ τὸ διασιλλαίνειν τὰ τῶν ἄλλων καὶ οἴεσθαι ὅτι πρῶτος ἔσῃ αὐτός, ἢν τὰ πάντων συκοφαντῇς.", "st": "46.24"}, {"sp": "N", "t": "καὶ μὴν κἀκεῖνο οὐ μικρόν, μᾶλλον δὲ τὸ μέγιστον ἁμαρτάνεις, ὅτι οὐ πρότερον τὰς διανοίας τῶν λέξεων προπαρεσκευασμένος ἔπειτα κατακοσμεῖς τοῖς ῥήμασιν καὶ τοῖς ὀνόμασιν, ἀλλὰ ἤν που ῥῆμα ἔκφυλον εὕρῃς ἢ αὐτὸς πλασάμενος οἰηθῇς εἶναι καλόν, τούτῳ ζητεῖς διάνοιαν ἐφαρμόσαι καὶ ζημίαν ἡγῇ, ἂν μὴ παραβύσῃς αὐτό που, κἂν τῷ λεγομένῳ μηδ’ ἀναγκαῖον ᾖ, οἷον πρῴην τὸν θυμάλωπα οὐδὲ εἰδὼς ὅ τι σημαίνει, ἀπέρριψας οὐδὲν ἐοικότα τῷ ὑποκειμένῳ. καὶ οἱ μὲν ἰδιῶται πάντες ἐτεθήπεσαν ὑπὸ τοῦ ξένου πληγέντες τὰ ὦτα, οἱ πεπαιδευμένοι δὲ ἐπ’ ἀμφοτέροις, καὶ σοὶ καὶ τοῖς ἐπαινοῦσιν, ἐγέλων.", "st": "46.24"}, {"sp": "N", "t": "τὸ δὲ πάντων καταγελαστότατον ἐκεῖνό ἐστιν, ὅτι ὑπεράττικος εἶναι ἀξιῶν καὶ τὴν φωνὴν εἰς τὸ ἀρχαιότατον ἀπηκριβωμένος τοιαῦτα ἔνια, μᾶλλον δὲ τὰ πλεῖστα, ἐγκαταμιγνύεις τοῖς λόγοις ἃ μηδὲ παῖς ἄρτι μανθάνων ἀγνοήσειεν ἄν· οἷον ἐκεῖνα πῶς οἴει κατὰ γῆς δῦναι ηὐχόμην ἀκούων σου ἐπιδεικνυμένου, ὅτε χιτώνιον μὲν καὶ τὸ ἀνδρεῖον ᾤου λέγεσθαι, δουλάρια δὲ καὶ τοὺς ἄρρενας τῶν ἀκολούθων ἀπεκάλεις, ἃ τίς οὐκ οἶδεν ὅτι χιτώνιον μὲν γυναικὸς ἐσθής, δουλάρια δὲ τὰ θήλεα καλοῦσιν; καὶ ἄλλα πολὺ τούτων προφανέστερα, οἷον τὸ ἵπτατο καὶ τὸ ἀπαντώμενος καὶ τὸ καθεσθείς, οὐδὲ μετοικικὰ τῆς Ἀθηναίων φωνῆς. ἡμεῖς οὐδὲ ποιητὰς ἐπαινοῦμεν τοὺς κατάγλωττα γράφοντας ποιήματα. τὰ δὲ σά, ὡς πεζὰ μέτροις παραβάλλειν, καθάπερ ὁ Δωσιάδα Βωμὸς ἂν εἴη καὶ ἡ τοῦ Λυκόφρονος Ἀλεξάνδρα, καὶ εἴ τις ἔτι τούτων τὴν φωνὴν κακοδαιμονέστερος.", "st": "46.25"}, {"sp": "N", "t": "ἂν ταῦτα ζηλώσῃς καὶ μεταμάθῃς, ἄριστα βεβουλευμένος ὑπὲρ σεαυτοῦ ἔσῃ· ἢν δὲ λάθῃς αὖθις εἰς τὴν λιχνείαν κατολισθών, ἐμοὶ μὲν ἀποπεπλήρωται ἡ παραίνεσις, σὺ δὲ σεαυτὸν αἰτιάσῃ, ἄν γε καὶ ξυνῇς χείρων γενόμενος.", "st": "46.25"}, {"sp": "HDR", "t": "Θεῶν Ἐκκλησία"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> μηκέτι τονθορύζετε, ὦ θεοί, μηδὲ κατὰ γωνίας συστρεφόμενοι πρὸς οὖς ἀλλήλοις κοινολογεῖσθε, ἀγανακτοῦντες εἰ πολλοὶ ἀνάξιοι μετέχουσιν ἡμῖν τοῦ συμποσίου, ἀλλ’ ἐπείπερ ἀποδέδοται περὶ τούτων ἐκκλησία, λεγέτω ἕκαστος ἐς τὸ φανερὸν τὰ δοκοῦντά οἱ καὶ κατηγορείτω. σὺ δὲ κήρυττε, ὦ Ἑρμῆ, τὸ κήρυγμα τὸ ἐκ τοῦ νόμου.", "st": "50.1"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἄκουε, σίγα. τίς ἀγορεύειν βούλεται τῶν τελείων θεῶν οἷς ἔξεστιν; ἡ δὲ σκέψις περὶ τῶν μετοίκων καὶ ξένων.", "st": "50.1"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> ἐγὼ ὁ Μῶμος, ὦ Ζεῦ, εἴ μοι ἐπιτρέψειας εἰπεῖν.", "st": "50.1"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> τὸ κήρυγμα ἤδη ἐφίησιν· ὥστε οὐδὲν ἐμοῦ δεήσει.", "st": "50.1"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> φημὶ τοίνυν δεινὰ ποιεῖν ἐνίους ἡμῶν, οἷς οὐκ ἀπόχρη θεοὺς ἐξ ἀνθρώπων αὐτοῖς γεγενῆσθαι, ἀλλ’, εἰ μὴ καὶ τοὺς ἀκολούθους καὶ θεράποντας αὐτῶν ἰσοτίμους ἡμῖν ἀποφανοῦσιν, οὐδὲν μέγα οὐδὲ νεανικὸν οἴονται εἰργάσθαι. ἀξιῶ δέ, ὦ Ζεῦ, μετὰ παρρησίας μοι δοῦναι εἰπεῖν· οὐδὲ γὰρ ἂν ἄλλως δυναίμην, ἀλλὰ πάντες με ἴσασιν ὡς ἐλεύθερός εἰμι τὴν γλῶτταν καὶ οὐδὲν ἂν κατασιωπήσαιμι τῶν οὐ καλῶς γιγνομένων· διελέγχω γὰρ ἅπαντα καὶ λέγω τὰ δοκοῦντά μοι ἐς τὸ φανερὸν οὔτε δεδιώς τινα οὔτε ὑπ’ αἰδοῦς ἐπικαλύπτων τὴν γνώμην· ὥστε καὶ ἐπαχθὴς δοκῶ τοῖς πολλοῖς καὶ συκοφαντικὸς τὴν φύσιν, δημόσιός τις κατήγορος ὑπ’ αὐτῶν ἐπονομαζόμενος. πλὴν ἀλλ’ ἐπείπερ ἔξεστιν καὶ κεκήρυκται καὶ σύ, ὦ Ζεῦ, δίδως μετ’ ἐξουσίας εἰπεῖν·, οὐδὲν ὑποστειλάμενος ἐρῶ.", "st": "50.2"}, {"sp": "N", "t": "πολλοὶ γάρ, φημί, οὐκ ἀγαπῶντες ὅτι αὐτοὶ μετέχουσι τῶν αὐτῶν ἡμῖν ξυνεδρίων καὶ εὐωχοῦνται ἐπ’ ἴσης, καὶ ταῦτα θνητοὶ ἐξ ἡμισείας ὄντες, ἔτι καὶ τοὺς ὑπηρέτας καὶ θιασώτας τοὺς αὐτῶν ἀνήγαγον ἐς τὸν οὐρανὸν καὶ παρενέγραψαν, καὶ νῦν ἐπ’ ἴσης διανομάς τε νέμονται καὶ θυσιῶν μετέχουσιν, οὐδὲ καταβαλόντες ἡμῖν τὸ μετοίκιον.", "st": "50.3"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> μηδὲν αἰνιγματῶδες, ὦ Μῶμε, ἀλλὰ σαφῶς καὶ διαρρήδην λέγε, προστιθεὶς καὶ τοὔνομα, νῦν γὰρ ἐς τὸ μέσον ἀπέρριπταί σοι ὁ λόγος, ὡς πολλοὺς εἰκάζειν καὶ ἐφαρμόζειν ἄλλοτε ἄλλον τοῖς λεγομένοις. χρὴ δὲ παρρησιαστὴν ὄντα μηδὲν ὀκνεῖν λέγειν.", "st": "50.3"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> εὖ γε, ὦ Ζεῦ, ὅτι καὶ παροτρύνεις με πρὸς τὴν παρρησίαν· ποιεῖς γὰρ τοῦτο βασιλικὸν ὡς ἀληθῶς καὶ μεγαλόφρον, ὥστε ἐρῶ καὶ τοὔνομα. ὁ γάρ τοι γενναιότατος οὗτος Διόνυσος ἡμιάνθρωπος ὤν, οὐδὲ Ἕλλην μητρόθεν ἀλλὰ Συροφοίνικός τινος ἐμπόρου τοῦ Κάδμου θυγατριδοῦς, ἐπείπερ ἠξιώθη τῆς ἀθανασίας, οἷος μὲν αὐτός ἐστιν οὐ λέγω, οὔτε τὴν μίτραν οὔτε τὴν μέθην οὔτε τὸ βάδισμα· πάντες γάρ, οἶμαι, ὁρᾶτε ὡς θῆλυς καὶ γυναικεῖος τὴν φύσιν, ἡμιμανής, ἀκράτου ἕωθεν ἀποπνέων· ὁ δὲ καὶ ὅλην φατρίαν ἐσεποίησεν ἡμῖν καὶ τὸν χορὸν ἐπαγόμενος πάρεστι καὶ θεοὺς ἀπέφηνε τὸν Πᾶνα καὶ τὸν Σιληνὸν καὶ Σατύρους, ἀγροίκους τινὰς καὶ αἰπόλους τοὺς πολλούς, σκιρτητικοὺς ἀνθρώπους καὶ τὰς μορφὰς ἀλλοκότους· ὧν ὁ μὲν κέρατα ἔχων καὶ ὅσον ἐξ ἡμισείας ἐς τὸ κάτω αἰγὶ ἐοικὼς καὶ γένειον βαθὺ καθειμένος ὀλίγον τράγου διαφέρων ἐστίν, ὁ δὲ φαλακρὸς γέρων, σιμὸς τὴν ῥῖνα, ἐπὶ ὄνου τὰ πολλὰ ὀχούμενος, Λυδὸς οὗτος, οἱ δὲ Σάτυροι ὀξεῖς τὰ ὦτα, καὶ αὐτοὶ φαλακροί, κεράσται, οἷα τοῖς ἄρτι γεννηθεῖσιν ἐρίφοις τὰ κέρατα ὑποφύεται, Φρύγες τινὲς ὄντες· ἔχουσι δὲ καὶ οὐρὰς ἅπαντες. ὁρᾶτε οἵους ἡμῖν θεοὺς ποιεῖ ὁ γεννάδας;", "st": "50.4"}, {"sp": "N", "t": "εἶτα θαυμάζομεν εἰ καταφρονοῦσιν ἡμῶν οἱ ἄνθρωποι ὁρῶντες οὕτω γελοίους θεοὺς καὶ τεραστίους; ἐῶ γὰρ λέγειν ὅτι καὶ δύο γυναῖκας ἀνήγαγεν, τὴν μὲν ἐρωμένην οὖσαν αὐτοῦ, τὴν Ἀριάδνην, ἧς καὶ τὸν στέφανον ἐγκατέλεξε τῷ τῶν ἄστρων χορῷ, τὴν δὲ Ἰκαρίου τοῦ γεωργοῦ θυγατέρα. καὶ ὃ πάντων γελοιότατον, ὦ θεοί, καὶ τὸν κύνα τῆς Ἠριγόνης, καὶ τοῦτον ἀνήγαγεν, ὡς μὴ ἀνιῷτο ἡ παῖς εἰ μὴ ἕξει ἐν τῷ οὐρανῷ τὸ ξύνηθες ἐκεῖνο καὶ ὅπερ ἠγάπα κυνίδιον. ταῦτα οὐχ ὕβρις ὑμῖν δοκεῖ καὶ παροινία καὶ γέλως; ἀκούσατε δ’ οὖν καὶ ἄλλους.", "st": "50.5"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> μηδέν, ὦ Μῶμε, εἴπῃς μήτε περὶ Ἀσκληπιοῦ μήτε περὶ Ἡρακλέους· ὁρῶ γὰρ οἷ φέρῃ τῷ λόγῳ. οὗτοι γάρ, ὁ μὲν αὐτῶν ἰᾶται καὶ ἀνίστησιν ἐκ τῶν νόσων καὶ ἔστιν “πολλῶν ἀντάξιος ἄλλων,” ὁ δὲ Ἡρακλῆς υἱὸς ὢν ἐμὸς οὐκ ὀλίγων πόνων ἐπρίατο τὴν ἀθανασίαν· ὥστε μὴ κατηγόρει αὐτῶν.", "st": "50.6"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> σιωπήσομαι, ὦ Ζεῦ, διὰ σέ, πολλὰ εἰπεῖν ἔχων. καίτοι εἰ μηδὲν ἄλλο, ἔτι τὰ σημεῖα ἔχουσι τοῦ πυρός. εἰ δὲ ἐξῆν καὶ πρὸς αὐτὸν σὲ τῇ παρρησίᾳ χρῆσθαι, πολλὰ ἂν εἶχον εἰπεῖν.", "st": "50.6"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> καὶ μὴν πρὸς ἐμὲ ἔξεστιν μάλιστα. μῶν δ’ οὖν κἀμὲ ξενίας διώκεις;", "st": "50.6"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> ἐν Κρήτῃ μὲν οὐ μόνον τοῦτο ἀκοῦσαι ἔστιν, ἀλλὰ καὶ ἄλλο τι περὶ σοῦ λέγουσιν καὶ τάφον ἐπιδεικνύουσιν· ἐγὼ δὲ οὔτε ἐκείνοις πείθομαι οὔτε Ἀχαιῶν Αἰγιεῦσιν ὑποβολιμαῖόν σε εἶναι φάσκουσιν.", "st": "50.6"}, {"sp": "N", "t": "ἃ δὲ μάλιστα ἐλεγχθῆναι δεῖν ἡγοῦμαι, ταῦτα ἐρῶ.", "st": "50.7"}, {"sp": "N", "t": "τὴν γάρ τοι ἀρχὴν τῶν τοιούτων παρανομημάτων καὶ τὴν αἰτίαν τοῦ νοθευθῆναι ἡμῶν τὸ ξυνέδριον σύ, ὦ Ζεῦ, παρέσχες θνηταῖς ἐπιμιγνύμενος καὶ κατιὼν παρ’ αὐτὰς ἐν ἄλλοτε ἄλλῳ σχήματι, ὥστε ἡμᾶς δεδιέναι μή σε καταθύσῃ τις ξυλλαβών, ὁπόταν ταῦρος ᾖς, ἢ τῶν χρυσοχόων τις κατεργάσηται χρυσὸν ὄντα, καὶ ἀντὶ Διὸς ἢ ὅρμος ἢ ψέλιον ἢ ἐλλόβιον ἡμῖν γένῃ. πλὴν ἀλλὰ ἐμπέπληκάς γε τὸν οὐρανὸν τῶν ἡμιθέων τούτων· οὐ γὰρ ἂν ἄλλως εἴποιμι. καὶ τὸ πρᾶγμα γελοιότατόν ἐστιν, ὁπόταν τις ἄφνω ἀκούσῃ ὅτι ὁ Ἡρακλῆς μὲν θεὸς ἀπεδείχθη, ὁ δὲ Εὐρυσθεύς, ὃς ἐπέταττεν αὐτῷ, τέθνηκεν, καὶ πλησίον Ἡρακλέους νεὼς οἰκέτου ὄντος καὶ Εὐρυσθέως τάφος τοῦ δεσπότου αὐτοῦ, καὶ πάλιν ἐν Θήβαις Διόνυσος μὲν θεός, οἱ δ’ ἀνεψιοὶ αὐτοῦ ὁ Πενθεὺς καὶ ὁ Ἀκταίων καὶ ὁ Λέαρχος ἀνθρώπων ἁπάντων κακοδαιμονέστατοι.", "st": "50.7"}, {"sp": "N", "t": "ἀφ’ οὗ δὲ ἅπαξ σύ, ὦ Ζεῦ, ἀνέῳξας τοῖς τοιούτοις τὰς θύρας καὶ ἐπὶ τὰς θνητὰς ἐτράπου, ἅπαντες μεμίμηνταί σε, καὶ οὐχ οἱ ἄρρενες μόνον, ἀλλ’, ὅπερ αἴσχιστον, καὶ αἱ θήλειαι θεοί. τίς γὰρ οὐκ οἶδεν τὸν Ἀγχίσην καὶ τὸν Τιθωνὸν καὶ τὸν Ἐνδυμίωνα καὶ τὸν Ἰασίωνα καὶ τοὺς ἄλλους; ὥστε ταῦτα μὲν ἐάσειν μοι δοκῶ· μακρὸν γὰρ ἂν τὸ διελέγχειν γένοιτο.", "st": "50.8"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> μηδὲν περὶ τοῦ Γανυμήδους, ὦ Μῶμε, εἴπῃς· χαλεπανῶ γὰρ εἰ λυπήσεις τὸ μειράκιον ὀνειδίσας ἐς τὸ γένος.", "st": "50.8"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> οὐκοῦν μηδὲ περὶ τοῦ ἀετοῦ εἴπω, ὅτι καὶ οὗτος ἐν τῷ οὐρανῷ ἐστιν, ἐπὶ τοῦ βασιλείου σκήπτρου καθεζόμενος καὶ μονονουχὶ ἐπὶ κεφαλήν σοι νεοττεύων, θεὸς εἶναι δοκῶν;", "st": "50.8"}, {"sp": "N", "t": "ἢ καὶ τοῦτον τοῦ Γανυμήδους ἕνεκα ἐάσομεν;", "st": "50.9"}, {"sp": "N", "t": "ἀλλ’ ὁ Ἄττης γε, ὦ Ζεῦ, καὶ ὁ Κορύβας καὶ ὁ Σαβάζιος, πόθεν ἡμῖν ἐπεισεκυκλήθησαν οὗτοι, ἢ ὁ Μίθρης ἐκεῖνος, ὁ Μῆδος, ὁ τὸν κάνδυν καὶ τὴν τιάραν, οὐδὲ ἑλληνίζων τῇ φωνῇ, ὥστε οὐδ’ ἢν προπίῃ τις ξυνίησι; τοιγαροῦν οἱ Σκύθαι ταῦτα ὁρῶντες, οἱ Γέται αὐτῶν, μακρὰ ἡμῖν χαίρειν εἰπόντες αὐτοὶ ἀπαθανατίζουσι καὶ θεοὺς χειροτονοῦσιν οὓς ἂν ἐθελήσωσι, τὸν αὐτὸν τρόπον ὅνπερ καὶ Ζάμολξις δοῦλος ὢν παρενεγράφη οὐκ οἶδ’ ὅπως διαλαθών.", "st": "50.9"}, {"sp": "N", "t": "καίτοι πάντα ταῦτα, ὦ θεοί, μέτρια. σὺ δέ, ὦ κυνοπρόσωπε καὶ σινδόσιν ἐσταλμένε Αἰγύπτιε, τίς εἶ, ὦ βέλτιστε, ἢ πῶς ἀξιοῖς θεὸς εἶναι ὑλακτῶν; τί δὲ βουλόμενος καὶ ὁ ποικίλος οὗτος ταῦρος ὁ Μεμφίτης προσκυνεῖται καὶ χρᾷ καὶ προφήτας ἔχει; αἰσχύνομαι γὰρ ἴβιδας καὶ πιθήκους εἰπεῖν καὶ τράγους καὶ ἄλλα πολλῷ γελοιότερα οὐκ οἶδ’ ὅπως ἐξ Αἰγύπτου παραβυσθέντα ἐς τὸν οὐρανόν, ἃ ὑμεῖς, ὦ θεοί, πῶς ἀνέχεσθε ὁρῶντες ἐπ’ ἴσης ἢ καὶ μᾶλλον ὑμῶν προσκυνούμενα; ἢ σύ, ὦ Ζεῦ, πῶς φέρεις ἐπειδὰν κριοῦ κέρατα φύσωσί σοι;", "st": "50.10"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> αἰσχρὰ ὡς ἀληθῶς ταῦτα φὴς τὰ περὶ τῶν Αἰγυπτίων· ὅμως δ’ οὖν, ὦ Μῶμε, τὰ πολλὰ αὐτῶν αἰνίγματά ἐστιν, καὶ οὐ πάνυ χρὴ καταγελᾶν ἀμύητον ὄντα.", "st": "50.11"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> πάνυ γοῦν μυστηρίων, ὦ Ζεῦ, δεῖ ἡμῖν, ὡς εἰδέναι θεοὺς μὲν τοὺς θεούς, κυνοκεφάλους δὲ τοὺς κυνοκεφάλους.", "st": "50.11"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> ἔα, φημί, τὰ περὶ Αἰγυπτίων· ἄλλοτε γὰρ περὶ τούτων ἐπισκεψόμεθα ἐπὶ σχολῆς. σὺ δὲ τοὺς ἄλλους λέγε.", "st": "50.11"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> τὸν Τροφώνιον, ὦ Ζεῦ, καὶ ὃ μάλιστά με ἀποπνίγει, τὸν Ἀμφίλοχον, ὃς ἐναγοῦς ἀνθρώπου καὶ μητρολῴου υἱὸς ὢν μαντεύεται ὁ γενναῖος ἐν Κιλικίᾳ, ψευδόμενος τὰ πολλὰ καὶ γοητεύων τοῖν δυοῖν ὀβολοῖν ἕνεκα. τοιγαροῦν οὐκέτι σύ, ὦ Ἄπολλον, εὐδοκιμεῖς, ἀλλὰ ἤδη πᾶς λίθος καὶ πᾶς βωμὸς χρησμῳδεῖ, ὃς ἂν ἐλαίῳ περιχυθῇ καὶ στεφάνους ἔχῃ καὶ γόητος ἀνδρὸς εὐπορήσῃ, οἷοι πολλοί εἰσιν. ἤδη καὶ ὁ Πολυδάμαντος τοῦ ἀθλητοῦ ἀνδριὰς ἰᾶται τοὺς πυρέττοντας ἐν Ὀλυμπίᾳ καὶ ὁ Θεαγένους ἐν Θάσῳ, καὶ Ἕκτορι θύουσιν ἐν Ἰλίῳ καὶ Πρωτεσιλάῳ καταντικρὺ ἐν Χερρονήσῳ. ἀφ’ οὗ δ’ οὖν τοσοῦτοι γεγόναμεν, ἐπιδέδωκε μᾶλλον ἡ ἐπιορκία καὶ ἱεροσυλία, καὶ ὅλως καταπεφρονήκασιν ἡμῶν — εὖ ποιοῦντες.", "st": "50.12"}, {"sp": "N", "t": "καὶ ταῦτα μὲν περὶ τῶν νόθων καὶ παρεγγράπτων. ἐγὼ δὲ καὶ ξένα ὀνόματα πολλὰ ἤδη ἀκούων οὔτε ὄντων τινῶν παρ’ ἡμῖν οὔτε συστῆναι ὅλως δυναμένων, πάνυ, ὦ Ζεῦ, καὶ ἐπὶ τούτοις γελῶ. ἢ ποῦ γάρ ἐστιν ἡ πολυθρύλητος ἀρετὴ καὶ φύσις καὶ εἱμαρμένη καὶ τύχη, ἀνυπόστατα καὶ κενὰ πραγμάτων ὀνόματα ὑπὸ βλακῶν ἀνθρώπων τῶν φιλοσόφων ἐπινοηθέντα; καὶ ὅμως αὐτοσχέδια ὄντα οὕτω τοὺς ἀνοήτους πέπεικεν, ὥστε οὐδεὶς ἡμῖν οὐδὲ θύειν βούλεται, εἰδὼς ὅτι, κἂν μυρίας ἑκατόμβας παραστήσῃ, ὅμως τὴν τύχην πράξουσαν τὰ μεμοιραμένα καὶ ἃ ἐξ ἀρχῆς ἑκάστῳ ἐπεκλώσθη. ἡδέως ἂν οὖν ἐροίμην σε, ὦ Ζεῦ, εἴ που εἶδες ἢ ἀρετὴν ἢ φύσιν ἢ εἱμαρμένην; ὅτι μὲν γὰρ ἀεὶ καὶ σὺ ἀκούεις ἐν ταῖς τῶν φιλοσόφων διατριβαῖς, οἶδα, εἰ μὴ καὶ κωφός τις εἶ, ὡς βοώντων αὐτῶν μὴ ἐπαΐειν.", "st": "50.13"}, {"sp": "N", "t": "πολλὰ ἔτι ἔχων εἰπεῖν καταπαύσω τὸν λόγον· ὁρῶ γοῦν πολλοὺς ἀχθομένους μοι λέγοντι καὶ συρίττοντας, ἐκείνους μάλιστα ὧν καθήψατο ἡ παρρησία τῶν λόγων.", "st": "50.13"}, {"sp": "N", "t": "πέρας γοῦν, εἰ ἐθέλεις, ὦ Ζεῦ, ψήφισμά τι περὶ τούτων ἀναγνώσομαι ἤδη ξυγγεγραμμένον.", "st": "50.14"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> ἀνάγνωθι· οὐ πάντα γὰρ ἀλόγως ᾐτιάσω. καὶ δεῖ τὰ πολλὰ αὐτῶν ἐπισχεῖν, ὡς μὴ ἐπὶ πλεῖον ἂν γίγνηται.", "st": "50.14"}, {"sp": "N", "t": "<em>Μῶμος.<\/em> ἀγαθῇ τύχῃ. ἐκκλησίας ἐννόμου ἀγομένης ἑβδόμῃ ἱσταμένου ὁ Ζεὺς ἐπρυτάνευε καὶ προήδρευε Ποσειδῶν, ἐπεστάτει Ἀπόλλων, ἐγραμμάτευε Μῶμος Νυκτὸς καὶ ὁ Ὕπνος τὴν γνώμην εἶπεν.", "st": "50.14"}, {"sp": "N", "t": "Ἐπειδὴ πολλοὶ τῶν ξένων, οὐ μόνον Ἕλληνες ἀλλὰ καὶ βάρβαροι, οὐδαμῶς ἄξιοι ὄντες κοινωνεῖν ἡμῖν τῆς πολιτείας, παρεγγραφέντες οὐκ οἶδα ὅπως καὶ θεοὶ δόξαντες ἐμπεπλήκασι μὲν τὸν οὐρανὸν ὡς μεστὸν εἶναι τὸ συμπόσιον ὄχλου ταραχώδους πολυγλώσσων τινῶν καὶ ξυγκλύδων ἀνθρώπων, ἐπιλέλοιπε δὲ ἡ ἀμβροσία καὶ τὸ νέκταρ, ὥστε μνᾶς ἤδη τὴν κοτύλην εἶναι διὰ τὸ πλῆθος τῶν πινόντων· οἱ δὲ ὑπὸ αὐθαδείας παρωσάμενοι τοὺς παλαιούς τε καὶ ἀληθεῖς θεοὺς προεδρίας ἠξιώκασιν αὑτοὺς παρὰ πάντα τὰ πάτρια καὶ ἐν τῇ γῇ προτιμᾶσθαι θέλουσι·", "st": "50.14"}, {"sp": "N", "t": "δεδόχθαι τῇ βουλῇ καὶ τῷ δήμῳ ξυλλεγῆναι μὲν ἐκκλησίαν ἐν τῷ Ὀλύμπῳ περὶ τροπὰς χειμερινάς, ἑλέσθαι δὲ ἐπιγνώμονας τελείους θεοὺς ἑπτά, τρεῖς μὲν ἐκ τῆς παλαιᾶς βουλῆς τῆς ἐπὶ Κρόνου, τέτταρας δὲ ἐκ τῶν δώδεκα, καὶ ἐν αὐτοῖς τὸν Δία· τούτους δὲ τοὺς ἐπιγνώμονας αὐτοὺς μὲν καθέζεσθαι ὀμόσαντας τὸν νόμιμον ὅρκον τὴν Στύγα, τὸν Ἑρμῆν δὲ κηρύξαντα ξυναγαγεῖν ἅπαντας ὅσοι ἀξιοῦσι ξυντελεῖν ἐς τὸ ξυνέδριον, τοὺς δὲ ἥκειν μάρτυρας ἐπαγομένους ἐνωμότους καὶ ἀποδείξεις τοῦ γένους. τοὐντεῦθεν δὲ οἱ μὲν παρίτωσαν καθ’ ἕνα, οἱ δὲ ἐπιγνώμονες ἐξετάζοντες ἢ θεοὺς εἶναι ἀποφανοῦνται ἢ καταπέμψουσιν ἐπὶ τὰ σφέτερα ἠρία καὶ τὰς θήκας τὰς προγονικάς. ἢν δέ τις ἁλῷ τῶν ἀδοκίμων καὶ ἅπαξ ὑπὸ τῶν ἐπιγνωμόνων ἐκκριθέντων ἐπιβαίνων τοῦ οὐρανοῦ, ἐς τὸν Τάρταρον ἐμπεσεῖν τοῦτον.", "st": "50.15"}, {"sp": "N", "t": "ἐργάζεσθαι δὲ τὰ αὐτοῦ ἕκαστον, καὶ μήτε τὴν Ἀθηνᾶν ἰᾶσθαι μήτε τὸν Ἀσκληπιὸν χρησμῳδεῖν μήτε τὸν Ἀπόλλω τοσαῦτα μόνον ποιεῖν, ἀλλὰ ἕν τι ἐπιλεξάμενον μάντιν ἢ κιθαρῳδὸν ἢ ἰατρὸν εἶναι.", "st": "50.16"}, {"sp": "N", "t": "τοῖς δὲ φιλοσόφοις προειπεῖν μὴ ἀναπλάττειν κενὰ ὀνόματα μηδὲ ληρεῖν περὶ ὧν οὐκ ἴσασιν.", "st": "50.17"}, {"sp": "N", "t": "ὁπόσοι δὲ ἤδη ναῶν ἢ θυσιῶν ἠξιώθησαν, ἐκείνων μὲν καθαιρεθῆναι τὰ ἀγάλματα, ἐντεθῆναι δὲ ἢ Διὸς ἢ Ἥρας ἢ Ἀπόλλωνος ἢ τῶν ἄλλων τινός, ἐκείνοις δὲ τάφον χῶσαι τὴν πόλιν καὶ στήλην ἐπιστῆσαι ἀντὶ βωμοῦ. ἢν δέ τις παρακούσῃ τοῦ κηρύγματος καὶ μὴ ἐθελήσῃ ἐπὶ τοὺς ἐπιγνώμονας ἐλθεῖν, ἐρήμην αὐτοῦ καταδιαιτησάτωσαν.<br>τοῦτο μὲν ὑμῖν τὸ ψήφισμα.", "st": "50.18"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> δικαιότατον, ὦ Μῶμε· καὶ ὅτῳ δοκεῖ, ἀνατεινάτω τὴν χεῖρα· μᾶλλον δέ, οὕτω γιγνέσθω, πλείους γὰρ οἶδ’ ὅτι ἔσονται οἱ μὴ χειροτονήσοντες. ἀλλὰ νῦν μὲν ἄπιτε· ὁπόταν δὲ κηρύξῃ ὁ Ἑρμῆς, ἥκετε κομίζοντες ἕκαστος ἐναργῆ τὰ γνωρίσματα καὶ σαφεῖς τὰς ἀποδείξεις, πατρὸς ὄνομα καὶ μητρός, καὶ ὅθεν καὶ ὅπως θεὸς ἐγένετο, καὶ φυλὴν καὶ φράτορας. ὡς ὅστις ἂν μὴ ταῦτα παράσχηται, οὐδὲν μελήσει τοῖς ἐπιγνώμοσιν εἰ νεών τις μέγαν ἐν τῇ γῇ ἔχει καὶ οἱ ἄνθρωποι θεὸν αὐτὸν εἶναι νομίζουσιν.", "st": "50.19"}, {"sp": "HDR", "t": "Τυραννοκτόνος"}, {"sp": "N", "t": "ἀνῆλθεν τις ἐς τὴν ἀκρόπολιν ἀποκτενῶν τὸν τυραννον· αὐτὸν μὲν οὐχ εὗρεν, τὸν δε υἱὸν αὐτοὺ ἀποκτείνας κατέλιπε τὸ ξίφος ἐν τῷ σώματι. ἐλθὼν ὁ τύραννος καὶ τὸν υἱὸν ἰδὼν ἤδη νεκρὸν τῷ αὐτῷ ζίφει, ἑαυτὸν ἀπέκτεινεν. αἰτεῖ ὁ ἀνελθὼν καὶ τὸν τοῦ τυράννου υἱὸν ἀνελὼν γέρας ὡς τνραννοκτόνος.", "st": "51.0"}, {"sp": "N", "t": "δύο τυράννους ἀποκτείνας, ὦ ἄνδρες δικασταί, μιᾶς ἡμέρας, τὸν μὲν ἤδη παρηβηκότα, τὸν δὲ ἀκμάζοντα καὶ πρὸς διαδοχὴν τῶν ἀδικημάτων ἑτοιμότερον, ἥκω μίαν ὅμως ἐπ’ ἀμφοτέροις αἰτήσων δωρεὰν μόνος τῶν πώποτε τυραννοκτόνων πληγῇ μιᾷ δύο πονηροὺς ἀποσκευασάμενος καὶ φονεύσας τὸν μὲν παῖδα τῷ ξίφει, τὸν πατέρα δὲ τῇ πρὸς τὸν υἱὸν φιλοστοργίᾳ. ὁ μὲν οὖν τύραννος ἀνθ’ ὧν ἐποίησεν ἱκανὴν ἡμῖν δέδωκε τιμωρίαν, ζῶν μὲν τὸν υἱὸν ἐπιδὼν προανῃρημένον παρὰ τὴν τελευτήν, τελευταῖον δὲ ἠναγκασμένος, τὸ παραδοξότατον, αὐτὸς αὑτοῦ γενέσθαι τυραννοκτόνος. ὁ παῖς δὲ ὁ ἐκείνου τέθνηκεν μὲν ὑπ’ ἐμοῦ, ὑπηρέτησε δέ μοι καὶ ἀποθανὼν πρὸς ἄλλον φόνον, ζῶν μὲν συναδικῶν τῷ πατρί, μετὰ θάνατον δὲ πατροκτονήσας, ὡς ἐδύνατο.", "st": "51.1"}, {"sp": "N", "t": "τὴν μὲν οὖν τυραννίδα ὁ παύσας εἰμὶ ἐγὼ καὶ τὸ ξίφος ὃ πάντα εἴργασται ἐμόν, τὴν δὲ τάξιν ἐνήλλαξα τῶν φόνων καὶ τὸν τρόπον ἐκαινοτόμησα τῆς τῶν πονηρῶν τελευτῆς, τὸν μὲν ἰσχυρότερον καὶ ἀμύνασθαι δυνάμενον αὐτὸς ἀνελών, τὸν γέροντα δὲ μόνῳ παραχωρήσας τῷ ξίφει.", "st": "51.2"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν καὶ περιττότερόν τι ἐπὶ τούτοις ᾤμην γενήσεσθαί μοι παρ’ ὑμῶν καὶ δωρεὰς λήψεσθαι ἰσαρίθμους τοῖς ἀνῃρημένοις, ὡς ἂν οὐ τῶν παρόντων ἀπαλλάξας ὑμᾶς μόνον, ἀλλὰ καὶ τῆς τῶν μελλόντων κακῶν ἐλπίδος, καὶ τὴν ἐλευθερίαν βέβαιον παρασχών, οὐδενὸς παραλελειμμένου κληρονόμου τῶν ἀδικημάτων· μεταξὺ δὲ κινδυνεύω τοσαῦτα κατορθώσας ἀγέραστος ἀπελθεῖν παρ’ ὑμῶν καὶ μόνος στερέσθαι τῆς παρὰ τῶν νόμων ἀμοιβῆς, οὓς διεφύλαξα.", "st": "51.3"}, {"sp": "N", "t": "ὁ μὲν οὖν ἀντιλέγων οὑτοσὶ δοκεῖ μοι οὐ κηδόμενος, ὥς φησι, τῶν κοινῶν αὐτὸ ποιεῖν, ἀλλ’ ἐπὶ τοῖς τετελευτηκόσι λελυπημένος καὶ ἀμυνόμενος τὸν ἐκείνοις τοῦ θανάτου αἴτιον γεγενημένον.", "st": "51.3"}, {"sp": "N", "t": "ὑμεῖς δὲ ἀνάσχεσθέ μου, ὦ ἄνδρες δικασταί, πρὸς ὀλίγον τὰ ἐν τῇ τυραννίδι καίπερ εἰδόσιν ὑμῖν ἀκριβῶς διηγουμένου· καὶ γὰρ τὸ μέγεθος οὕτω μάθοιτ’ ἂν τῆς εὐεργεσίας τῆς ἐμῆς, καὶ αὐτοὶ μᾶλλον εὐφρανεῖσθε λογιζόμενοι ὧν ἀπηλλάγητε. οὐ γὰρ ὥσπερ ἄλλοις τισὶν ἤδη συνέβη πολλάκις, ἁπλῆν καὶ ἡμεῖς τυραννίδα καὶ μίαν δουλείαν ὑπεμείναμεν, οὐδὲ ἑνὸς ὑπηνέγκαμεν ἐπιθυμίαν δεσπότου, ἀλλὰ μόνοι τῶν πώποτε τὰ ὅμοια δυστυχησάντων δύο ἀνθ’ ἑνὸς τυράννους εἴχομεν καὶ πρὸς διττὰ οἱ δυστυχεῖς ἀδικήματα διῃρούμεθα. μετριώτερος δὲ ὁ πρεσβύτης ἦν παρὰ πολὺ καὶ πρὸς τὰς ὀργὰς ἠπιώτερος καὶ πρὸς τὰς κολάσεις ἀμβλύτερος καὶ πρὸς τὰς ἐπιθυμίας βραδύτερος, ὡς ἂν ἤδη τῆς ἡλικίας τὸ μὲν σφοδρότερον τῆς ὁρμῆς ἐπεχούσης, τὰς δὲ τῶν ἡδονῶν ὀρέξεις χαλιναγωγούσης. καὶ πρός γε τὴν ἀρχὴν τῶν ἀδικημάτων ὑπὸ τοῦ παιδὸς ἄκων προσῆχθαι ἐλέγετο, οὐ πάνυ τυραννικὸς αὐτὸς ὤν, ἀλλ’ εἴκων ἐκείνῳ· φιλότεκνος γὰρ ἐς ὑπερβολὴν ἐγένετο, ὡς ἔδειξεν, καὶ πάντα ὁ παῖς ἦν αὐτῷ καὶ ἐκείνῳ ἐπείθετο καὶ ἠδίκει ὅσα κελεύοι καὶ ἐκόλαζεν οὓς προστάττοι καὶ πάντα ὑπηρέτει, καὶ ὅλως ἐτυραννεῖτο ὑπ’ αὐτοῦ καὶ δορυφόρος τῶν τοῦ παιδὸς ἐπιθυμιῶν ἦν.", "st": "51.4"}, {"sp": "N", "t": "ὁ νεανίας δὲ τῆς μὲν τιμῆς παρεχώρει καθ’ ἡλικίαν ἐκείνῳ καὶ μόνου ἐξίστατο τοῦ τῆς ἀρχῆς ὀνόματος, τὸ δ’ ἔργον τῆς τυραννίδος καὶ τὸ κεφάλαιον αὐτὸς ἦν, καὶ τὸ μὲν πιστὸν καὶ ἀσφαλὲς ἀπ’ αὐτοῦ παρεῖχε τῇ δυναστείᾳ, τὴν δὲ ἀπόλαυσιν μόνος ἐκαρποῦτο τῶν ἀδικημάτων. ἐκεῖνος ἦν ὁ τοὺς δορυφόρους συνέχων, ὁ τὴν φρουρὰν κρατύνων, ὁ τοὺς τυραννουμένους φοβῶν, ὁ τοὺς ἐπιβουλεύοντας ἐκκόπτων, ἐκεῖνος ὁ τοὺς ἐφήβους ἀνασπῶν, ὁ ἐνυβρίζων τοῖς γάμοις· ἐκείνῳ αἱ παρθένοι ἀνήγοντο, καὶ εἴ τινες σφαγαὶ καὶ εἴ τινες φυγαὶ καὶ χρημάτων ἀφαιρέσεις καὶ βάσανοι καὶ ὕβρεις, πάντα ταῦτα τολμήματα ἦν νεανικά. ὁ γέρων δὲ ἐκείνῳ ἠκολούθει καὶ συνηδίκει καὶ ἐπῄνει μόνον τὰ τοῦ παιδὸς ἀδικήματα, καὶ τὸ πρᾶγμα ἡμῖν ἀφόρητον καθειστήκει· ὅταν γὰρ αἱ τῆς γνώμης ἐπιθυμίαι τὴν ἐκ τῆς ἀρχῆς ἐξουσίαν προσλάβωσιν, οὐδένα ὅρον ποιοῦνται τῶν ἀδικημάτων.", "st": "51.5"}, {"sp": "N", "t": "μάλιστα δὲ ἐκεῖνο ἐλύπει, τὸ εἰδέναι μακράν, μᾶλλον δὲ ἀΐδιον, τὴν δουλείαν ἐσομένην καὶ ἐκ διαδοχῆς παραδοθησομένην τὴν πόλιν ἄλλοτε ἄλλῳ δεσπότῃ καὶ πονηρῶν κληρονόμημα γενησόμενον τὸν δῆμον· ὡς τοῖς γε ἄλλοις οὐ μικρά τις ἐλπὶς αὕτη, τὸ λογίζεσθαι καὶ πρὸς αὐτοὺς λέγειν, “ἀλλ’ ἤδη παύσεται,” “ἀλλ’ ἤδη τεθνήξετα καὶ μετ’ ὀλίγον ἐλεύθεροι γενησόμεθα.” ἐπ’ ἐκείνων δὲ οὐδὲν τοιοῦτον ἠλπίζετο, ἀλλὰ ἑωρῶμεν ἤδη ἕτοιμον τὸν τῆς ἀρχῆς διάδοχον. τοιγαροῦν οὐδ’ ἐπιχειρεῖν τις ἐτόλμα τῶν γεννικῶν καὶ τὰ αὐτὰ ἐμοὶ προαιρουμένων, ἀλλ’ ἀπέγνωστο παντάπασιν ἡ ἐλευθερία καὶ ἄμαχος ἡ τυραννὶς ἐδόκει, πρὸς τοσούτους ἐσομένης τῆς ἐπιχειρήσεως.", "st": "51.6"}, {"sp": "N", "t": "ἀλλ’ οὐκ ἐμὲ ταῦτα ἐφόβησεν οὐδὲ τὸ δυσχερὲς τῆς πράξεως λογισάμενος ἀπώκνησα οὐδὲ πρὸς τὸν κίνδυνον ἀπεδειλίασα, μόνος δέ, μόνος πρὸς οὕτως ἰσχυρὰν καὶ πολλὴν τυραννίδα, μᾶλλον δὲ οὐ μόνος, ἀλλὰ μετὰ τοῦ ξίφους ἀνῄειν τοῦ συμμεμαχημένου καὶ τὸ μέρος συντετυραννοκτονηκότος, πρὸ ὀφθαλμῶν μὲν τὴν τελευτὴν ἔχων, ἀλλαξόμενος δὲ ὅμως τὴν κοινὴν ἐλευθερίαν τῆς σφαγῆς τῆς ἐμῆς. ἐντυχὼν δὲ τῇ πρώτῃ φρουρᾷ καὶ τρεψάμενος οὐ ῥᾳδίως τοὺς δορυφόρους καὶ τὸν ἐντυγχάνοντα κτείνων καὶ τὸ ἀνθιστάμενον πᾶν διαφθείρων ἐπὶ τὸ κεφάλαιον αὐτὸ τῶν ἔργων ἱέμην, ἐπὶ τὴν μόνην τῆς τυραννίδος ἰσχύν, ἐπὶ τὴν ὑπόθεσιν τῶν ἡμετέρων συμφορῶν· καὶ ἐπιστὰς τῷ τῆς ἀκροπόλεως φρουρίῳ καὶ ἰδὼν γεννικῶς ἀμυνόμενον καὶ ἀνθιστάμενον πολλοῖς τραύμασιν ὅμως ἀπέκτεινα.", "st": "51.7"}, {"sp": "N", "t": "καὶ ἡ μὲν τυραννὶς ἤδη καθῄρητο, καὶ πέρας εἶχέ μοι τὸ τόλμημα, καὶ τὸ ἀπ’ ἐκείνου πάντες ἦμεν ἐλεύθεροι, ἐλείπετο δὲ γέρων ἔτι μόνος, ἄνοπλος, ἀποβεβληκὼς τοὺς φύλακας, ἀπολωλεκὼς τὸν μέγαν ἐκεῖνον ἑαυτοῦ δορυφόρον, ἔρημος, οὐδὲ γενναίας ἔτι χειρὸς ἄξιος.", "st": "51.8"}, {"sp": "N", "t": "ἐνταῦθα τοίνυν πρὸς ἐμαυτόν, ὦ ἄνδρες δικασταί, τὰ τοιαῦτα ἐλογιζόμην· “πάντ’ ἔχει μοι καλῶς, πάντα πέπρακται, πάντα κατώρθωται. τίνα ἂν ὁ περίλοιπος κολασθείη τρόπον; ἐμοῦ μὲν γὰρ ἀνάξιός ἐστι καὶ τῆς ἐμῆς δεξιᾶς, καὶ μάλιστα ἐπ’ ἔργῳ λαμπρῷ καὶ νεανικῷ καὶ γενναίῳ ἀνῃρημένος, καταισχύνων κἀκείνην τὴν σφαγήν· ἄξιον δέ τινα δεῖ ζητῆσαι δήμιον, ἀλλαγὴν συμφορᾶς, μηδὲ τὴν αὐτὴν κερδαίνειν. ἰδέτω, κολασθήτω, παρακείμενον ἐχέτω τὸ ξίφος· τούτῳ τὰ λοιπὰ ἐντέλλομαι.” ταῦτα βουλευσάμενος αὐτὸς μὲν ἐκποδὼν ἀπηλλαττόμην, ὁ δέ, ὅπερ ἐγὼ προὐμαντευσάμην, διεπράξατο καὶ ἐτυραννοκτόνησεν καὶ τέλος ἐπέθηκε τῷ ἐμῷ δράματι.", "st": "51.8"}, {"sp": "N", "t": "πάρειμι οὖν κομίζων ὑμῖν τὴν δημοκρατίαν καὶ θαρρεῖν ἤδη προκηρύττων ἅπασι καὶ τὴν ἐλευθερίαν εὐαγγελιζόμενος. ἤδη οὖν ἀπολαύετε τῶν ἔργων τῶν ἐμῶν. κενὴ μέν, ὡς ὁρᾶτε, πονηρῶν ἡ ἀκρόπολις, ἐπιτάττει δὲ οὐδείς, ἀλλὰ καὶ τιμᾶν ἔξεστι καὶ δικάζειν καὶ ἀντιλέγειν κατὰ τοὺς νόμους, καὶ πάντα ταῦτα γεγένηται δι’ ἐμὲ ὑμῖν καὶ διὰ τὴν τόλμαν τὴν ἐμήν, κἀκ τοῦ ἑνὸς ἐκείνου φόνου, μεθ’ ὃν οὐκέτι ζῆν πατὴρ ἐδύνατο. ἀξιῶ δ’ οὖν ἐπὶ τούτοις τὴν ὀφειλομένην δοθῆναί μοι παρ’ ὑμῶν δωρεάν, οὐ φιλοκερδὴς οὐδὲ μικρολόγος τις ὢν οὐδὲ ἐπὶ μισθῷ τὴν πατρίδα εὐεργετεῖν προῃρημένος, ἀλλὰ βεβαιωθῆναί μοι βουλόμενος τὰ κατορθώματα τῇ δωρεᾷ καὶ μὴ διαβληθῆναι μηδὲ ἄδοξον γενέσθαι τὴν ἐπιχείρησιν τὴν ἐμὴν ὡς ἀτελῆ καὶ γέρως ἀναξίαν κεκριμένην.", "st": "51.9"}, {"sp": "N", "t": "οὑτοσὶ δὲ ἀντιλέγει καὶ φησὶν οὐκ εὔλογον ποιεῖν με τιμᾶσθαι θέλοντα καὶ δωρεὰν λαμβάνειν· οὐ γὰρ εἶναι τυραννοκτόνον οὐδὲ πεπρᾶχθαί μοί τι κατὰ τὸν νόμον, ἀλλ’ ἐνδεῖν τι τῷ ἔργῳ τῷ ἐμῷ πρὸς ἀπαίτησιν τῆς δωρεᾶς. πυνθάνομαι τοίνυν αὐτοῦ, “τί λοιπὸν ἀπαιτεῖς παρ’ ἡμῶν; οὐκ ἠβουλήθην; οὐκ ἀνῆλθον; οὐκ ἐφόνευσα; οὐκ ἠλευθέρωσα; μή τις ἐπιτάττει; μή τις κελεύει; μή τις ἀπειλεῖ δεσπότης; μή τίς με τῶν κακούργων διέφυγεν; οὐκ ἂν εἴποις. ἀλλὰ πάντα εἰρήνης μεστὰ καὶ πάντες οἱ νόμοι καὶ ἐλευθερία σαφὴς καὶ δημοκρατία βέβαιος καὶ γάμοι ἀνύβριστοι καὶ παῖδες ἀδεεῖς καὶ παρθένοι ἀσφαλεῖς καὶ ἑορτάζουσα τὴν κοινὴν εὐτυχίαν ἡ πόλις. τίς οὖν ὁ τούτων ἁπάντων αἴτιος; τίς ὁ ἐκεῖνα μὲν παύσας, τὰ δὲ παρεσχημένος; εἰ γάρ τίς ἐστι πρὸ ἐμοῦ τιμᾶσθαι δίκαιος, παραχωρῶ τοῦ γέρως, ἐξίσταμαι τῆς δωρεᾶς. εἰ δὲ μόνος ἐγὼ πάντα διεπραξάμην τολμῶν καὶ κινδυνεύων, ἀνιών, ἀναιρῶν, κολάζων, δι’ ἀλλήλων τιμωρούμενος, τί μου διαβάλλεις τὰ κατορθώματα; τί δὲ ἀχάριστον πρός με τὸν δῆμον ποιεῖς εἶναι;”", "st": "51.10"}, {"sp": "N", "t": "“οὐ γὰρ αὐτὸν ἐφόνευσας τὸν τύραννον· ὁ δὲ νόμος τυραννοκτόνῳ δίδωσιν τὴν δωρεάν.” διαφέρει δέ, εἰπέ μοι, τί ἢ αὐτὸν ἀνελεῖν ἢ τοῦ θανάτου παρασχεῖν τὴν αἰτίαν; ἐγὼ μὲν γὰρ οὐδὲν οἶμαι· ἀλλὰ τοῦτο μόνον ὁ νομοθέτης εἶδεν, τὴν ἐλευθερίαν, τὴν δημοκρατίαν, τὴν τῶν δεινῶν ἀπαλλαγήν. τοῦτ’ ἐτίμησεν, τοῦτ’ ἄξιον ἀμοιβῆς ὑπέλαβεν, ὅπερ οὐκ ἂν εἴποις μὴ δι’ ἐμὲ γεγενῆσθαι. εἰ γὰρ ἐφόνευσα δι’ ὃν ἐκεῖνος ζῆν οὐκ ἐδύνατο, αὐτὸς εἴργασμαι τὴν σφαγήν. ἐμὸς ὁ φόνος, ἡ χεὶρ ἐκείνου. μὴ τοίνυν ἀκριβολογοῦ ἔτι περὶ τοῦ τρόπου τῆς τελευτῆς μηδὲ ἐξέταζε ὅπως ἀπέθανεν, ἀλλ’ εἰ μηκέτ’ ἐστίν, εἰ δι’ ἐμὲ τὸ μηκέτ’ εἶναι ἔχει· ἐπεὶ κἀκεῖνο προσεξετάσειν μοι δοκεῖς καὶ συκοφαντήσειν τοὺς εὐεργέτας, εἴ τις μὴ ξίφει, ἀλλὰ λίθῳ ἢ ξύλῳ ἢ ἄλλῳ τῳ τρόπῳ ἀπέκτεινεν.", "st": "51.11"}, {"sp": "N", "t": "τί δέ, εἰ λιμῷ ἐξεπολιόρκησα τὸν τύραννον τὴν ἀνάγκην τῆς τελευτῆς παρέχων, ἀπῄτεις ἂν καὶ τότε παρ’ ἐμοῦ αὐτόχειρα τὴν σφαγήν, ἢ ἐνδεῖν ἔλεγές μοί τι πρὸς τὸν νόμον, καὶ ταῦτα χαλεπώτερον τοῦ κακούργου πεφονευμένου; ἓν μόνον ἐξέταζε, τοῦτο ἀπαίτει, τοῦτο πολυπραγμόνει, τίς τῶν πονηρῶν λείπεται, ἢ τίς ἐλπὶς τοῦ φόβου ἢ τί ὑπόμνημα τῶν συμφορῶν; εἰ δὲ καθαρὰ πάντα καὶ εἰρηνικά, συκοφαντοῦντός ἐστιν τῷ τρόπῳ τῶν πεπραγμένων χρώμενον ἀποστερεῖν ἐθέλειν τὴν ἐπὶ τοῖς πεπονημένοις δωρεάν.", "st": "51.11"}, {"sp": "N", "t": "ἐγὼ δὲ καὶ τοῦτο μέμνημαι διηγορευμένον ἐν τοῖς νόμοις (ἐκτὸς εἰ μὴ διὰ τὴν πολλὴν δουλείαν ἐπιλέλησμαι τῶν ἐν αὐτοῖς εἰρημένων) αἰτίας θανάτου εἶναι διττάς, καὶ εἴ τις μὴ αὐτὸς μὲν ἀπέκτεινε μηδὲ τῇ χειρὶ ἔδρασεν τὸ ἔργον, ἠνάγκασεν δὲ καὶ παρέσχεν ἀφορμὴν τοῦ φόνου, τὰ ἴσα καὶ τοῦτον ἀξιοῖ ὁ νόμος αὐτὸν ἀντικολάζεσθαι — μάλα δικαίως· οὐ γὰρ ἠβούλετο τοῦ πεπραγμένου ἥσσων γίνεσθαι τῷ τῆς ἀδείας· καὶ περιττὴ λοιπὸν ἡ ἐξέτασις τοῦ τρόπου τῆς σφαγῆς.", "st": "51.12"}, {"sp": "N", "t": "εἶτα τὸν μὲν οὕτως ἀποκτείναντα κολάζειν ὡς ἀνδροφόνον δικαιοῖς καὶ οὐδαμῶς ἀφεῖσθαι θέλεις, τὸν δὲ κατὰ τὸν αὐτὸν τούτῳ τρόπον εὖ πεποιηκότα τὴν πόλιν οὐ τῶν ὁμοίων ἀξιώσεις τοῖς εὐεργέταις;", "st": "51.12"}, {"sp": "N", "t": "οὐδὲ γὰρ ἐκεῖνο ἂν ἔχοις λέγειν, ὡς ἐγὼ μὲν ἁπλῶς αὐτὸ ἔπραξα, ἠκολούθησε δέ τι τέλος ἄλλως χρηστόν, ἐμοῦ μὴ θελήσαντος. τί γὰρ ἔτι ἐδεδίειν τοῦ ἰσχυροτέρου πεφονευμένου; τί δὲ κατέλιπον τὸ ξίφος ἐν τῇ σφαγῇ, εἰ μὴ πάντως τὸ ἐσόμενον αὐτὸ προεμαντευόμην; ἐκτὸς εἰ μὴ τοῦτο φής, ὡς οὐ τύραννος ὁ τεθνεὼς ἦν οὐδὲ ταύτην εἶχε τὴν προσηγορίαν, οὐδὲ δωρεὰς ἐπ’ αὐτῷ πολλάς, εἰ ἀποθάνοι, ἡδέως ἂν ὑμεῖς ἐδώκατε. ἀλλ’ οὐκ ἂν εἴποις.", "st": "51.13"}, {"sp": "N", "t": "Εἶτα τοῦ τυράννου πεφονευμένου τῷ τὴν αἰτίαν παρασχόντι τῆς σφαγῆς οὐκ ἀποδώσεις τὴν δωρεάν; ὢ τῆς πολυπραγμοσύνης. μέλει δέ σοι, πῶς ἀπέθανεν, ἀπολαύοντι τῆς ἐλευθερίας, ἢ τὸν τὴν δημοκρατίαν ἀποδεδωκότα περιττότερόν τι προσαπαιτεῖς; “καίτοι ὅ γε νόμος,” ὡς φής, “τὸ κεφάλαιον ἐξετάζει τῶν πεπραγμένων, τὰ διὰ μέσου δὲ πάντα ἐᾷ καὶ οὐκέτι πολυπραγμονεῖ.” τί γάρ; οὐχὶ καὶ ἐξελάσας τις τύραννον ἤδη τιμὴν ἔλαβεν τυραννοκτόνου; καὶ μάλα δικαίως· ἐλευθερίαν γὰρ κἀκεῖνος ἀντὶ δουλείας παρέσχηται. τὸ δ’ ὑπ’ ἐμοῦ γεγενημένον οὐ φυγὴ οὐδὲ δευτέρας ἐπαναστάσεως ἐλπίς, ἀλλὰ παντελὴς καθαίρεσις καὶ πανωλεθρία παντὸς τοῦ γένους καὶ ῥιζόθεν τὸ δεινὸν ἅπαν ἐκκεκομμένον.", "st": "51.13"}, {"sp": "N", "t": "καί μοι πρὸς θεῶν ἤδη ἀπ’ ἀρχῆς ἐς τέλος, εἰ δοκεῖ, πάντα ἐξετάσατε, εἴ τι τῶν πρὸς τὸν νόμον παραλέλειπται καὶ εἰ ἐνδεῖ τι τῶν προσεῖναι ὀφειλόντων τυραννοκτόνῳ. πρῶτα μὲν δὴ γνώμην προϋπάρχειν χρὴ γενναίαν καὶ φιλόπολιν καὶ πρὸ τῶν κοινῶν κινδυνεύειν ἐθέλουσαν καὶ τῷ οἰκείῳ θανάτῳ τὴν τῶν πολλῶν σωτηρίαν ὠνησομένην. ἆρ’ οὖν πρὸς τοῦτο ἐνεδέησα, ἐμαλακίσθην, ἢ προελόμενός τινα τῶν διὰ μέσου κινδύνων ἀπώκνησα; οὐκ ἂν εἴποις. μένε τοίνυν ἐπὶ τούτου ἔτι μόνου καὶ νόμιζε τοῦ θελῆσαι μόνον καὶ τοῦ βουλεύσασθαι ταῦτα, εἰ καὶ μὴ χρηστὸν ἀποβεβήκει, ἔκ γε τῆς γνώμης αὐτῆς καταστάντα με γέρας ἀξιοῦν ὡς εὐεργέτην λαμβάνειν. ἐμοῦ μὲν οὐ δυνηθέντος, ἄλλου δὲ μετ’ ἐμὲ τετυραννοκτονηκότος, ἄλογον, εἰπέ μοι, ἢ ἀγνῶμον ἦν παρασχεῖν; καὶ μάλιστα εἰ ἔλεγον, “ἄνδρες, ἐβουλόμην, ἠθέλησα, ἐπεχείρησα, ἐπειράθην· τῆς γνώμης μόνης ἄξιός εἰμι τιμᾶσθαι, τί” ἂν ἀπεκρίνω τότε;", "st": "51.14"}, {"sp": "N", "t": "νῦν δὲ οὐ τοῦτό φημι, ἀλλὰ καὶ ἀνῆλθον καὶ ἐκινδύνευσα καὶ μυρία πρὸ τῆς τοῦ νεανίσκου σφαγῆς ἐπόνησα· μὴ γὰρ οὕτω ῥᾷστον μηδὲ εὐχερὲς ὑπολάβητε εἶναι τὸ πρᾶγμα, φρουρὰν ὑπερβῆναι καὶ δορυφόρων κρατῆσαι καὶ τρέψασθαι τοσούτους μόνον, ἀλλὰ σχεδὸν τὸ μέγιστον ἐν τῇ τυραννοκτονίᾳ καὶ τὸ κεφάλαιον τῶν ἔργων τοῦτό ἐστιν. οὐ γὰρ δὴ αὐτός γε ὁ τύραννος μέγα καὶ δυσάλωτον καὶ δυσκατέργαστόν ἐστιν, ἀλλὰ τὰ φρουροῦντα καὶ συνέχοντα τὴν τυραννίδα, ἅ τις ἂν νικήσῃ, πάντα οὗτος κατώρθωσεν, καὶ τὸ λοιπὸν ὀλίγον. τὸ δὴ ἄχρι τῶν τυράννων προελθεῖν οὐκ ἂν ὑπῆρξέ μοι, μὴ οὐχὶ τῶν περὶ αὐτοὺς φυλάκων καὶ δορυφόρων ἁπάντων κεκρατηκότι κἀκείνους ἅπαντας προνενικηκότι. οὐδὲν ἔτι προστίθημι, ἀλλ’ ἐπὶ τούτων αὖθις μένω· φυλακῆς ἐκράτησα, δορυφόρους ἐνίκησα, τὸν τύραννον ἀφύλακτον, ἄνοπλον, γυμνὸν ἀπέδωκα. τιμῆς ἄξιος ἐπὶ τούτοις εἶναί σοι δοκῶ, ἢ ἔτι ἀπαιτεῖς παρ’ ἐμοῦ τὸν φόνον;", "st": "51.15"}, {"sp": "N", "t": "ἀλλ’ εἰ καὶ φόνον ζητεῖς, οὐδὲ τοῦτο ἐνδεῖ, οὐδὲ ἀναίμακτός εἰμι, ἀλλ’ εἴργασμαι μεγάλην καὶ γενναίαν σφαγὴν νεανίσκου ἀκμάζοντος καὶ πᾶσι φοβεροῦ, δι’ ὃν ἀνεπιβούλευτος κἀκεῖνος ἦν, ᾧ μόνῳ ἐθάρρει, ὃς ἀντὶ πολλῶν ἤρκει δορυφόρων. ἆρ’ οὖν οὐκ ἄξιος, ὦ οὗτος, δωρεᾶς, ἀλλὰ ἄτιμος ἐπὶ τηλικούτοις γένωμαι; τί γάρ, εἰ δορυφόρον ἕνα, τί δ’ εἰ ὑπηρέτην τινὰ τοῦ τυράννου ἀπέκτεινα, τί δ’ εἰ οἰκέτην τίμιον, οὐ μέγα ἂν ἔδοξεν καὶ τοῦτο, ἀνελθόντα ἐν μέσῃ τῇ ἀκροπόλει, ἐν μέσοις τοῖς ὅπλοις φόνον τινὸς ἐργάσασθαι τῶν τοῦ τυράννου φίλων; νῦν δὲ καὶ τὸν πεφονευμένον αὐτὸν ἰδέ. υἱὸς ἦν τυράννου, μᾶλλον δὲ τύραννος χαλεπώτερος καὶ δεσπότης ἀπαραίτητος καὶ κολαστὴς ὠμότερος καὶ ὑβριστὴς βιαιότερος, τὸ δὲ μέγιστον, κληρονόμος τῶν ὅλων καὶ διάδοχος καὶ ἐπὶ πολὺ παρατεῖναι τὰ τῆς ἡμετέρας συμφορᾶς δυνάμενος.", "st": "51.16"}, {"sp": "N", "t": "βούλει τοῦτο μόνον πεπρᾶχθαί μοι, ζῆν δὲ ἔτι τὸν τύραννον διαπεφευγότα; γέρας δὴ ἐπὶ τούτοις αἰτῶ. τί φατέ; οὐ δώσετε; οὐχὶ κἀκεῖνον ὑφεωρᾶσθε· οὐ δεσπότης; οὐ βαρύς; οὐκ ἀφόρητος ἦν;", "st": "51.17"}, {"sp": "N", "t": "νῦν δὲ καὶ τὸ κεφάλαιον αὐτὸ ἐννοήσατε· ὃ γὰρ οὗτος ἀπαιτεῖ παρ’ ἐμοῦ, τοῦτο ὡς ἐνῆν ἄριστα διεπραξάμην, καὶ τὸν τύραννον ἀπέκτεινα ἑτέρῳ φόνῳ, οὐχ ἁπλῶς οὐδὲ πληγῇ μιᾷ, ὅπερ εὐκταιότατον ἦν αὐτῷ ἐπὶ τηλικούτοις ἀδικήμασιν, ἀλλὰ λύπῃ προβασανίσας πολλῇ καὶ ἐν ὀφθαλμοῖς δείξας τὰ φίλτατα οἰκτρῶς προκείμενα, υἱὸν ἐν ἡλικίᾳ, εἰ καὶ πονηρόν, ἀλλ’ οὖν καὶ ἀκμάζοντα καὶ ὅμοιον τῷ πατρί, αἵματος καὶ λύθρου ἐμπεπλησμένον. ταῦτ’ ἔστι πατέρων τὰ τραύματα, ταῦτα ξίφη δικαίων τυραννοκτόνων, οὗτος θάνατος ἄξιος ὠμῶν τυράννων, αὕτη τιμωρία πρέπουσα τοσούτοις ἀδικήμασιν· τὸ δ’ εὐθὺς ἀποθανεῖν, τὸ δ’ ἀγνοῆσαι, τὸ δὲ μηδὲν τοιοῦτο θέαμα ἰδεῖν, οὐδὲν ἔχει τυραννικῆς κολάσεως ἄξιον.", "st": "51.17"}, {"sp": "N", "t": "οὐ γὰρ ἠγνόουν, ὦ οὗτος, οὐκ ἠγνόουν, οὐδὲ τῶν ἄλλων οὐδείς, ὅσην ἐκεῖνος εὔνοιαν πρὸς τὸν υἱὸν εἶχεν καὶ ὡς οὐκ ἂν ἠξίωσεν ἐπιβιῶναι οὐδ’ ὀλίγον αὐτῷ χρόνον. πάντες μὲν γὰρ πατέρες ἴσως πρὸς τοὺς παῖδας τοιοῦτοι, ὁ δὲ καὶ περιττότερόν τι τῶν ἄλλων εἶχεν, εἰκότως, ὁρῶν μόνον ἐκεῖνον κηδεμόνα καὶ φύλακα τῆς τυραννίδος καὶ μόνον προκινδυνεύοντα τοῦ πατρὸς καὶ τὴν ἀσφάλειαν τῇ ἀρχῇ παρεχόμενον. ὥστε εἰ καὶ μὴ διὰ τὴν εὔνοιαν, ἀλλὰ διὰ τὴν ἀπόγνωσιν εὐθὺς ἠπιστάμην τεθνηξόμενον αὐτὸν καὶ λογιούμενον ὡς οὐδὲν ἔτι τοῦ ζῆν ὄφελος τῆς ἐκ τοῦ παιδὸς ἀσφαλείας καθῃρημένης. ἅπαντα τοίνυν αὐτῷ ἀθρόα περιέστησα, τὴν φύσιν, τὴν λύπην, τὴν ἀπόγνωσιν, τὸν φόβον, τὰς ἐπὶ τῶν μελλόντων... ἐπ’ αὐτὸν ἐχρησάμην τοῖς συμμάχοις καὶ πρὸς τὴν τελευταίαν ἐκείνην σκέψιν κατηνάγκασα. ἀπέθανεν ὑμῖν ἄτεκνος, λελυπημένος, ὀδυρόμενος, δακρύων, πεπενθηκὼς πένθος ὀλιγοχρόνιον μέν, ἀλλ’ ἱκανὸν πατρί, καὶ τὸ δεινότατον, αὐτὸς ὑφ’ αὑτοῦ, ὅσπερ θανάτων οἴκτιστος καὶ πολλῷ χαλεπώτερος ἢ εἰ ὑπ’ ἄλλου γίγνοιτο.", "st": "51.18"}, {"sp": "N", "t": "ποῦ μοι τὸ ξίφος; μή τις ἄλλος τοῦτο γνωρίζει; μή τινος ἄλλου ὅπλον τοῦτο ἦν; τίς αὐτὸ ἐς τὴν ἀκρόπολιν ἀνεκόμισε; πρὸ τοῦ τυράννου τίς ἐχρήσατο; τίς αὐτὸ ἐπ’ ἐκεῖνον ἀπέστειλεν; ὦ ξίφος κοινωνὸν καὶ διάδοχον τῶν ἐμῶν κατορθωμάτων, μετὰ τοσούτους κινδύνους, μετὰ τοσούτους φόνους ἀμελούμεθα καὶ ἀνάξιοι δοκοῦμεν δωρεᾶς. εἰ γὰρ ὑπὲρ μόνου τούτου τὴν τιμὴν ᾔτουν παρ’ ὑμῶν, εἰ γὰρ ἔλεγον, “ἄνδρες, ἀποθανεῖν ἐθελήσαντι τῷ τυράννῳ καὶ ἀνόπλῳ ἐπὶ τοῦ καιροῦ κατειλημμένῳ ξίφος τοῦτο ἐμὸν ὑπηρέτησε καὶ πρὸς τὸ τέλος τῆς ἐλευθερίας συνήργησε πάντῃ, τοῦτο τιμῆς τε καὶ δωρεᾶς ἄξιον νομίσατε,” δεσπότην οὕτω δημοτικοῦ κτήματος οὐκ ἂν ἠμείψασθε; οὐκ ἂν ἐν τοῖς εὐεργέταις ἀνεγράψατε; οὐκ ἂν τὸ ξίφος ἐν τοῖς ἱεροῖς ἀνεθήκατε; οὐκ ἂν μετὰ τῶν θεῶν κἀκεῖνο προσεκυνήσατε;", "st": "51.19"}, {"sp": "N", "t": "νῦν μοι ἐννοήσατε οἷα πεποιηκέναι εἰκὸς τὸν τύραννον, οἷα δὲ εἰρηκέναι πρὸ τῆς τελευτῆς· ἐπεὶ γὰρ ὑπ’ ἐμοῦ φονευόμενος καὶ τιτρωσκόμενος πολλοῖς τραύμασιν ἐς τὰ φανερὰ τοῦ σώματος, ὡς ἂν μάλιστα λυπήσειν ἔμελλον τὸν γεγεννηκότα, ὡς ἂν ἐκ τῆς πρώτης θέας διασπαράξειν, ὁ μὲν ἀνεβόησεν οἰκτρόν, ἐπιβοώμενος τὸν γεγεννηκότα οὐ βοηθὸν οὐδὲ σύμμαχον — ᾔδει γὰρ πρεσβύτην ὄντα καὶ ἀσθενῆ — ἀλλὰ θεατὴν τῶν οἰκείων κακῶν· ἐγὼ γὰρ ἀπηλλαττόμην ποιητὴς μὲν τῆς ὅλης τραγῳδίας γεγενημένος, καταλιπὼν δὲ τῷ ὑποκριτῇ τὸν νεκρὸν καὶ τὴν σκηνὴν καὶ τὸ ξίφος καὶ τὰ λοιπὰ τοῦ δράματος· ἐπιστὰς δὲ ἐκεῖνος καὶ ἰδὼν υἱὸν ὃν εἶχεν μόνον ὀλίγον ἐμπνέοντα, ᾑμαγμένον, ἐμπεπλησμένον τοῦ φόνου καὶ τὰ τραύματα συνεχῆ καὶ πολλὰ καὶ καίρια, ἀνεβόησεν τοῦτο· “τέκνον, ἀνηρήμεθα, πεφονεύμεθα, τετυραννοκτονήμεθα, ποῦ ὁ σφαγεύς; τίνι με τηρεῖ; τίνι με φυλάττει διὰ σοῦ, τέκνον, προανῃρημένον; ἢ μή τι ὡς γέροντος ὑπερφρονεῖ, καὶ τῇ βραδυτῆτι, κολάζειν δέον, καὶ παρατείνει μοι τὸν φόνον καὶ μακροτέραν μοι τὴν σφαγὴν ποιεῖ;”", "st": "51.20"}, {"sp": "N", "t": "καὶ ταῦτα λέγων ἐζήτει τὸ ξίφος· αὐτὸς γὰρ ἄνοπλος ἦν διὰ τὸ πάντα τῷ παιδὶ θαρρεῖν. ἀλλ’ οὐδὲ τοῦτο ἐνεδέησεν, πάλαι δὲ ἦν ὑπ’ ἐμοῦ καὶ τοῦτο προπαρεσκευασμένον καὶ πρὸς τὸ μέλλον τόλμημα καταλελειμμένον. ἀποσπάσας δὴ τῆς σφαγῆς καὶ τοῦ τραύματος ἐξελὼν τὸ ξίφος φησί, “πρὸ μικροῦ μέν με ἀπέκτεινας, νῦν δὲ ἀνάπαυσον, ξίφος. πατρὶ πενθοῦντι παραμύθιον ἐλθὲ καὶ πρεσβυτικῇ χειρὶ δυστυχούσῃ συναγώνισαι. ἀπόσφαξον, τυραννοκτόνησον καὶ τοῦ πενθεῖν ἀπάλλαξον. εἴθε πρῶτός σοι ἐνέτυχον, εἴθε τὴν τάξιν προὔλαβον τοῦ φόνου. ἀπέθανον ἄν, ἀλλ’ ὡς τύραννος μόνον, ἀλλ’ ἔτι νομίζων ἕξειν ἔκδικον· νῦν δὲ ὡς ἄτεκνος, νῦν δὲ ὡς οὐδὲ φονέως εὐπορῶν.” Καὶ ταῦτα ἅμα λέγων ἐπῆγε τὴν σφαγὴν τρέμων, οὐ δυνάμενος, ἐπιθυμῶν μέν, ἀσθενῶν δὲ πρὸς τὴν ὑπηρεσίαν τοῦ τολμήματος.", "st": "51.21"}, {"sp": "N", "t": "πόσαι κολάσεις ταῦτα; πόσα τραύματα; πόσοι θάνατοι; πόσαι τυραννοκτονίαι; πόσαι δωρεαί; καὶ τέλος ἑωράκατε πάντες τὸν μὲν νεανίαν προκείμενον, οὐδὲ μικρὸν οὐδ’ εὐκαταγώνιστον ἔργον, τὸν πρεσβύτην δὲ αὐτῷ περικεχυμένον καὶ τὸ αἷμα ἀμφοῖν ἀνακεκραμένον, τὴν ἐλευθέριον ἐκείνην καὶ ἐπινίκιον σπονδήν, καὶ τὰ ἔργα τοῦ ξίφους τοῦ ἐμοῦ, αὐτὸ δὲ τὸ ξίφος ἐν μέσῳ ἀμφοτέρων, ἐπιδεικνύμενον ὡς οὐκ ἀνάξιον γεγένηται τοῦ δεσπότου καὶ μαρτυρόμενον ὅτι μοι πιστῶς διηκονήσατο. τοῦτο ὑπ’ ἐμοῦ γενόμενον μικρότερον ἦν· νῦν δὲ λαμπρότερόν ἐστι τῇ καινότητι. καὶ ὁ μὲν καθελὼν τὴν τυραννίδα πᾶσαν εἰμὶ ἐγώ· μεμέρισται δὲ ἐς πολλοὺς τὸ ἔργον ὥσπερ ἐν δράματι· καὶ τὰ μὲν πρῶτα ἐγὼ ὑπεκρινάμην, τὰ δεύτερα δὲ ὁ παῖς, τὰ τρίτα δὲ ὁ τύραννος αὐτός, τὸ ξίφος δὲ πᾶσιν ὑπηρέτησεν.", "st": "51.22"}, {"sp": "HDR", "t": "Ἀποκηρυττόμενος"}, {"sp": "N", "t": "ἀποκηρυχθείς τις ἰατρικὴν ἐξέμαθεν. μανέντα τὸν πατέρα καὶ ὑπὸ τῶν ἀλλων ἰατρῶν ἀπεγνωσμένον ἰασάμενος φαρμάκου δόσει ἀνελήφθη αὖθις ἐς τὸ γένος. μετὰ ταῦτα μεμηνυίαν τὴν μητρυιὰν ἰάσασθαι κελευόμενος … ἀποκηρύττεται.", "st": "52.0"}, {"sp": "N", "t": "οὐ καινὰ μὲν ταῦτα, ὦ ἄνδρες δικασταί, οὐδὲ παράδοξα τὰ ὑπὸ τοῦ πατρὸς ἐν τῷ παρόντι γιγνόμενα, οὐδὲ νῦν πρῶτον τὰ τοιαῦτα ὀργίζεται, ἀλλὰ πρόχειρος οὗτος ὁ νόμος αὐτῷ καὶ συνήθως ἐπὶ τοῦτ’ ἀφικνεῖται τὸ δικαστήριον. ἐκεῖνο δὲ καινότερον νῦν δυστυχῶ, ὅτι ἔγκλημα μὲν ἴδιον οὐκ ἔχω, κινδυνεύω δὲ τιμωρίαν ὑποσχεῖν ὑπὲρ τῆς τέχνης εἰ μὴ πάντα δύναται πείθεσθαι τούτῳ κελεύοντι, οὗ τί γένοιτ’ ἂν ἀτοπώτερον, θεραπεύειν ἐκ προστάγματος, οὐκέθ’ ὡς ἡ τέχνη δύναται, ἀλλ’ ὡς ὁ πατὴρ βούλεται; ἐβουλόμην μὲν οὖν τὴν ἰατρικὴν καὶ τοιοῦτόν τι ἔχειν φάρμακον ὃ μὴ μόνον τοὺς μεμηνότας ἀλλὰ καὶ τοὺς ἀδίκως ὀργιζομένους παύειν ἐδύνατο, ἵνα καὶ τοῦτο τοῦ πατρὸς τὸ νόσημα ἰασαίμην. νυνὶ δὲ τὰ μὲν τῆς μανίας αὐτῷ τέλεον πέπαυται, τὰ δὲ τῆς ὀργῆς μᾶλλον ἐπιτείνεται, καὶ τὸ δεινότατον, τοῖς μὲν ἄλλοις ἅπασιν σωφρονεῖ, κατ’ ἐμοῦ δὲ τοῦ θεραπεύσαντος μόνου μαίνεται. τὸν μὲν οὖν μισθὸν τῆς θεραπείας ὁρᾶτε οἷον ἀπολαμβάνω, ἀποκηρυττόμενος ὑπ’ αὐτοῦ πάλιν καὶ τοῦ γένους ἀλλοτριούμενος δεύτερον, ὥσπερ διὰ τοῦτ’ ἀναληφθεὶς πρὸς ὀλίγον ἵν’ ἀτιμότερος γένωμαι πολλάκις ἐκπεσὼν τῆς οἰκίας.", "st": "52.1"}, {"sp": "N", "t": "ἐγὼ δὲ ἐν μὲν τοῖς δυνατοῖς οὐδὲ κελευσθῆναι περιμένω· πρῴην γοῦν ἄκλητος ἧκον ἐπὶ τὴν βοήθειαν. ὅταν δέ τι ᾖ τελέως ἀπεγνωσμένον, οὐδ’ ἐπιχειρεῖν βούλομαι. ἐπὶ δὲ τῆς γυναικὸς ταύτης εἰκότως καὶ ἀτολμότερός εἰμι· λογίζομαι γὰρ οἷα πάθοιμ’ ἂν ὑπὸ τοῦ πατρὸς ἀποτυχών, ὃς οὐδὲ ἀρξάμενος τῆς θεραπείας ἀποκηρύττομαι. ἄχθομαι μὲν οὖν, ὦ ἄνδρες δικασταί, ἐπὶ τῇ μητρυιᾷ χαλεπῶς ἐχούσῃ (χρηστὴ γὰρ ἦν) καὶ ἐπὶ τῷ πατρὶ δι’ ἐκείνην ἀνιωμένῳ, τὸ δὲ μέγιστον, ἐπ’ ἐμαυτῷ ἀπειθεῖν δοκοῦντι καὶ ἃ προστάττομαι ὑπουργεῖν οὐ δυναμένῳ καὶ δι’ ὑπερβολὴν τῆς νόσου καὶ ἀσθένειαν τῆς τέχνης. πλὴν οὐ δίκαιον οἶμαι ἀποκηρύττεσθαι τὸν ἃ μὴ δύναται ποιεῖν μηδὲ τὴν ἀρχὴν ὑπισχνούμενον.", "st": "52.2"}, {"sp": "N", "t": "Δῐ ἃς μὲν οὖν αἰτίας καὶ πρότερον ἀπεκήρυξέ με ῥᾴδιον συνιδεῖν ἐκ τῶν παρόντων. ἐγὼ δὲ καὶ πρὸς ἐκείνας μέν, ὡς οἴομαι, ἱκανῶς τῷ μετὰ ταῦτα βίῳ ἀπελογησάμην, καὶ ταυτὶ δὲ ἃ νῦν ἐγκαλεῖ ὡς ἂν οἷός τε ὦ ἀπολύσομαι, μικρὰ ὑμῖν διηγησάμενος τῶν ἐμῶν.", "st": "52.3"}, {"sp": "N", "t": "ὁ γὰρ δυσάγωγος καὶ δυσπειθὴς ἐγώ, ὁ καταισχύνων τὸν πατέρα καὶ ἀνάξια πράττων τοῦ γένους, τότε μὲν αὐτῷ τὰ πολλὰ ἐκεῖνα βοῶντι καὶ διατεινομένῳ ὀλίγα χρῆναι ἀντιλέγειν ᾠόμην. ἀπελθὼν δὲ τῆς οἰκίας ἐνόμιζόν μοι δικαστήριον ἔσεσθαι μέγα καὶ ψῆφον ἀληθῆ τὸν μετὰ ταῦτα βίον καὶ τὸ φαίνεσθαι πάμπολυ τῶν τοῦ πατρὸς ἐγκλημάτων ἐκείνων ἀφεστηκότα καὶ περὶ τὰ κάλλιστα τῶν ἐπιτηδευμάτων ἐσπουδακότα καὶ τοῖς ἀρίστοις συνόντα. προεωρώμην δὲ καὶ τοιοῦτό τι καὶ ὑπώπτευον ἤδη ὡς οὐ σφόδρα καθεστηκότος πατρὸς ἀδίκως ὀργίζεσθαι καὶ ἐγκλήματα ψευδῆ καθ’ υἱοῦ συντιθέναι· καὶ ἦσάν τινες οἱ μανίας ἀρχὴν ταῦτα εἶναι νομίζοντες καὶ ἀπειλὴν καὶ ἀκροβολισμὸν οὐκ ἐς μακρὰν ἐπιπεσουμένου τοῦ κακοῦ, μῖσος ἄλογον καὶ νόμον ἀπηνῆ καὶ βλασφημίας προχείρους καὶ δικαστήριον σκυθρωπὸν καὶ βοὴν καὶ ὀργὴν καὶ ὅλως χολῆς μεστὰ πάντα. διὸ δὴ τάχα μοι καὶ ἰατρικῆς δεήσειν ποτὲ προσεδόκων.", "st": "52.3"}, {"sp": "N", "t": "ἀποδημήσας οὖν καὶ τοῖς εὐδοκιμωτάτοις τῶν ἐπὶ τῆς ἀλλοδαπῆς ἰατρῶν συγγενόμενος καὶ πόνῳ πολλῷ καὶ προθυμίᾳ λιπαρεῖ χρησάμενος ἐξέμαθον τὴν τέχνην. ἐπανελθὼν δὲ καταλαμβάνω τὸν πατέρα σαφῶς ἤδη μεμηνότα καὶ ὑπὸ τῶν ἐπιχωρίων ἰατρῶν ἀπεγνωσμένον, οὐκ ἐς βάθος ὁρώντων οὐδ’ ἀκριβῶς φυλοκρινούντων τὰς νόσους. πλὴν ὅπερ γε εἰκὸς ἦν ποιεῖν χρηστὸν υἱόν, οὔτε ἐμνησικάκησα τῆς ἀποκηρύξεως οὔτε μετάπεμπτος γενέσθαι περιέμεινα· οὐδὲ γὰρ εἶχόν τι αὐτῷ ἴδιον ἐγκαλεῖν, ἀλλὰ πάντα ἐκεῖνα ἦν ἀλλότρια τὰ ἁμαρτήματα καὶ ὥσπερ ἔφην ἤδη, τῆς νόσου. παρελθὼν οὖν ἄκλητος οὐκ εὐθὺς ἰασάμην· οὐ γὰρ οὕτω ποιεῖν ἔθος ἐστὶν ἡμῖν οὐδὲ ταῦτα ἡ τέχνη παραινεῖ, ἀλλὰ πάντων πρῶτον τοῦτο διδασκόμεθα συνορᾶν εἴτε ἰάσιμόν ἐστι τὸ νόσημα εἴτε ἀνήκεστον καὶ ὑπερβεβηκὸς τοὺς ὅρους τῆς τέχνης. καὶ τηνικαῦτα, ἢν μὲν εὐμεταχείριστον ᾖ, ἐπιχειροῦμεν καὶ πᾶσαν σπουδὴν ἐσφερόμεθα σῶσαι τὸν νοσοῦντα· ἢν δὲ κεκρατηκὸς ἤδη καὶ νενικηκὸς τὸ πάθος ἴδωμεν, οὐδὲ τὴν ἀρχὴν προσαπτόμεθα, νόμον τινὰ παλαιὸν τῶν προπατόρων τῆς τέχνης ἰατρῶν φυλάττοντες, οἵ φασι μὴ δεῖν ἐπιχειρεῖν τοῖς κεκρατημένοις.", "st": "52.4"}, {"sp": "N", "t": "ἰδὼν οὖν τὸν πατέρα ἔτι ἐντὸς τῆς ἐλπίδος καὶ τὸ πάθος οὐχ ὑπὲρ τὴν τέχνην, ἐπὶ πολὺ τηρήσας καὶ ἀκριβῶς ἐξετάσας ἕκαστα ἐπεχείρουν ἤδη καὶ τὸ φάρμακον τεθαρρηκότως ἐνέχεον, καίτοι πολλοὶ τῶν παρόντων ὑπώπτευον τὴν δόσιν καὶ τὴν ἴασιν διέβαλλον καὶ πρὸς κατηγορίας παρεσκευάζοντο.", "st": "52.4"}, {"sp": "N", "t": "παρῆν δὲ καὶ ἡ μητρυιὰ φοβουμένη καὶ ἀπιστοῦσα, οὐ τῷ μισεῖν ἐμέ, ἀλλὰ τῷ δεδιέναι καὶ ἀκριβῶς εἰδέναι πονηρῶς ἐκεῖνον διακείμενον· ἠπίστατο γὰρ μόνη τὰ πάντα συνοῦσα καὶ ὁμοδίαιτος τῇ νόσῳ. πλὴν ἀλλ’ ἔγωγε οὐδὲν ἀποδειλιάσας — ἠπιστάμην γὰρ οὐ ψευσόμενά με τὰ σημεῖα οὐδὲ προδώσουσαν τὴν τέχνην — ἐπῆγον τὴν ἴασιν ἐν καιρῷ τῆς ἐπιχειρήσεως, καίτοι κἀμοί τινες τῶν φίλων συνεβούλευον μὴ θρασύνεσθαι, μὴ καὶ διαβολήν τινα μείζω ἐνέγκῃ μοι τὸ ἀποτυχεῖν ὡς ἀμυνομένῳ τὸν πατέρα φαρμάκῳ καὶ μνησικακήσαντι ὧν ἐπεπόνθειν ὑπ’ αὐτοῦ.", "st": "52.5"}, {"sp": "N", "t": "καὶ τὸ κεφάλαιον, σῶος μὲν οὗτος εὐθὺς ἦν καὶ ἐσωφρόνει πάλιν καὶ πάντα διεγίγνωσκεν· οἱ παρόντες δὲ ἐθαύμαζον, ἐπῄνει δὲ καὶ ἡ μητρυιὰ καὶ φανερὰ πᾶσιν ἦν χαίρουσα κἀμοὶ εὐδοκιμοῦντι κἀκείνῳ σωφρονοῦντι. οὗτος δ’ οὖν (μαρτυρεῖν γὰρ αὐτῷ ἔχω) μήτε μελλήσας μήτε σύμβουλόν τινα περὶ τούτων προσλαβών, ἐπειδὴ τὸ πᾶν ἤκουσε τῶν παρόντων, ἔλυε μὲν τὴν ἀποκήρυξιν, υἱὸν δὲ ἐξ ὑπαρχῆς ἐποιεῖτό με, σωτῆρα καὶ εὐεργέτην ἀποκαλῶν καὶ ἀκριβῆ πεῖραν εἰληφέναι ὁμολογῶν καὶ περὶ τῶν ἔμπροσθεν ἐκείνων ἀπολογούμενος. τοῦτο γενόμενον εὔφραινε μὲν πολλούς, ὅσοι παρῆσαν χρηστοί, ἐλύπει δὲ ἐκείνους ὅσοις ἀποκήρυξις υἱοῦ ἡδίων ἀναλήψεως. εἶδον γοῦν τότε οὐ πάντας ὁμοίως ἡδομένους τῷ πράγματι, ἀλλ’ εὐθύς τινος καὶ χρόαν τρεπομένην καὶ βλέμμα τεταραγμένον καὶ πρόσωπον ὠργισμένον, οἷον ἐκ φθόνου καὶ μίσους γίνεται.", "st": "52.5"}, {"sp": "N", "t": "ἡμεῖς μὲν οὖν, ὡς τὸ εἰκός, ἐν εὐφροσύναις καὶ θυμηδίαις ἦμεν, ἀλλήλους ἀπειληφότες·", "st": "52.5"}, {"sp": "N", "t": "ἡ μητρυιὰ δὲ μετὰ μικρὸν εὐθὺς νοσεῖν ἤρξατο νόσον, ὦ ἄνδρες δικασταί, χαλεπὴν καὶ παράλογον· ἀρχόμενον γὰρ εὐθὺς τὸ δεινὸν παρεφύλαξα. οὐ γὰρ ἁπλοῦν οὐδὲ ἐπιπόλαιον τῆς μανίας τὸ εἶδος, ἀλλά τι παλαιὸν ὑποικουροῦν ἐν τῇ ψυχῇ κακὸν ἀπέρρηξε καὶ ἐς τοὐμφανὲς ἐξενίκησε. πολλὰ μὲν οὖν καὶ ἄλλα ἡμῖν ἐστι σημεῖα τῶν ἀνιάτως μεμηνότων, ἓν δὲ ἐκεῖνο καινὸν ἐπὶ τῆς γυναικὸς ταύτης παρεφύλαξα· πρὸς μὲν γὰρ τοὺς ἄλλους ἡμερωτέρα καὶ πραεῖά ἐστι καὶ παρόντων εἰρήνην ἄγει ἡ νόσος, ἂν δέ τινα ἰατρὸν ἴδῃ καὶ τοῦτ’ ἀκούσῃ μόνον, κατ’ ἐκείνου μάλιστα παροξύνεται, ὅπερ καὶ αὐτὸ τοῦ πονηρῶς καὶ ἀνηκέστως ἔχειν ἐστὶ τεκμήριον.", "st": "52.6"}, {"sp": "N", "t": "ταῦτα ὁρῶν ἐγὼ μὲν ἠνιώμην καὶ τὴν γυναῖκα ᾤκτειρον ἀξίαν οὖσαν καὶ παρὰ τὸ προσῆκον δυστυχοῦσαν.", "st": "52.6"}, {"sp": "N", "t": "ὁ πατὴρ δὲ ὑπὸ ἰδιωτείας (οὐ γὰρ οἶδεν οὔτε ἀρχὴν τοῦ κατέχοντος κακοῦ οὔτε τὴν αἰτίαν οὔτε τὸ μέτρον τοῦ πάθους) ἐκέλευεν ἰᾶσθαι καὶ τὸ ὅμοιον ἐκχέαι φάρμακον· οἴεται γὰρ ἓν εἶναι μανίας εἶδος καὶ μίαν τὴν νόσον καὶ τἀρρώστημα ταὐτὸν καὶ παραπλησίαν τὴν θεραπείαν δεχόμενον. ἐπεὶ δέ, ὅπερ ἀληθέστατον, ἀδύνατον εἶναί φημι σώζεσθαι τὴν γυναῖκα καὶ ἡττῆσθαι ὑπὸ τῆς νόσου ὁμολογῶ, ἀγανακτεῖ καὶ ὀργίζεται καί φησιν ἑκόντα καθυφίεσθαι καὶ προδιδόναι τὴν ἄνθρωπον, ἐγκαλῶν ἐμοὶ τὴν ἀσθένειαν τῆς τέχνης. καὶ πάσχει μὲν σύνηθες τοῖς λυπουμένοις· ὀργίζονται γοῦν ἅπαντες τοῖς μετὰ παρρησίας τἀληθῆ λέγουσιν. πλὴν ἔγωγε ὡς ἂν οἷός τε ὦ δικαιολογήσομαι πρὸς αὐτὸν καὶ ὑπὲρ ἐμαυτοῦ καὶ τῆς τέχνης.", "st": "52.7"}, {"sp": "N", "t": "καὶ πρῶτόν γε ἀπὸ τοῦ νόμου ἄρξομαι καθ’ ὃν οὗτός με ἀποκηρῦξαι βούλεται, ἵν’ εἰδῇ οὐκέθ’ ὁμοίαν οὖσαν αὐτῷ νῦν τε καὶ πρότερον τὴν ἐξουσίαν. οὐ γὰρ ἅπασιν, ὦ πάτερ, ὁ νομοθέτης οὐδὲ πάντας υἱέας οὐδὲ ὁσάκις ἂν ἐθέλωσιν ἀποκηρύττειν συγκεχώρηκεν οὐδ’ ἐπὶ πάσαις αἰτίαις, ἀλλ’ ὥσπερ τοῖς πατράσιν τὰ τηλικαῦτα ὀργίζεσθαι ἐφῆκεν, οὕτω καὶ τῶν παίδων προὐνόησεν, ὡς μὴ ἀδίκως αὐτὸ πάσχωσιν· καὶ διὰ τοῦτο οὐκ ἐλευθέραν ἐφῆκε γίγνεσθαι οὐδὲ ἄκριτον τὴν τιμωρίαν, ἀλλ’ ἐς δικαστήριον ἐκάλεσε καὶ δοκιμαστὰς ἐκάθισε τοὺς μήτε πρὸς ὀργὴν μήτε διαβολὴν τὸ δίκαιον κρινοῦντας. ᾔδει γὰρ πολλοῖς πολλάκις ἀλόγους αἰτίας ὀργῆς παρισταμένας, καὶ τὸν μὲν ψευδεῖ τινι διαβολῇ πειθόμενον, τὸν δὲ οἰκέτῃ πιστεύοντα ἢ γυναίῳ ἐχθρῷ. οὔκουν ἡγεῖτο ἀδίκαστον γίγνεσθαι τὸ πρᾶγμα οὐδ’ ἐξ ἐρήμης τοὺς παῖδας εὐθὺς ἁλίσκεσθαι, ἀλλὰ καὶ ὕδωρ ἐγχεῖται καὶ λόγος ἀποδίδοται καὶ ἀνεξέταστον οὐδὲν καταλείπεται.", "st": "52.8"}, {"sp": "N", "t": "ἐπεὶ τοίνυν ἔξεστιν, καὶ τοῦ μὲν ἐγκαλεῖν μόνου ὁ πατὴρ κύριος, τοῦ κρῖναι δὲ εἰ εὔλογα αἰτιᾶται ὑμεῖς οἱ δικάζοντες, αὐτὸ μὲν ὅ μοι ἐπιφέρει καὶ ἐφ’ ᾧ νῦν ἀγανακτεῖ μηδέπω σκοπεῖτε, πρότερον δὲ ἐκεῖνο ἐξετάσατε, εἰ ἔτι δοτέον ἀποκηρύττειν αὐτῷ ἅπαξ ἀποκηρύξαντι καὶ χρησαμένῳ τῇ παρὰ τοῦ νόμου ἐξουσίᾳ καὶ ἀποπληρώσαντι τὴν πατρικὴν ταύτην δυναστείαν, εἶτ’ αὖθις ἀναλαβόντι καὶ λύσαντι τὴν ἀποκήρυξιν. ἐγὼ μὲν γὰρ ἀδικώτατον εἶναί φημι τὸ τοιοῦτον, ἀπεράντους γίνεσθαι καὶ τῶν παίδων τὰς τιμωρίας καὶ πολλὰς τὰς καταδίκας καὶ τὸν φόβον ἀΐδιον καὶ τὸν νόμον ἄρτι μὲν συνοργίζεσθαι, μετὰ μικρὸν δὲ λύεσθαι, καὶ πάλιν ὁμοίως ἰσχυρὸν εἶναι, καὶ ὅλως ἄνω καὶ κάτω στρέφεσθαι τὰ δίκαια πρὸς τὸ ἐπὶ καιροῦ δοκοῦν πατράσιν. ἀλλὰ τὸ μὲν πρῶτον ἄξιον ἐφιέναι καὶ ἀγανακτοῦντι συναγανακτεῖν καὶ κύριον τῆς τιμωρίας ποιεῖν τὸν γεγεννηκότα· ἢν δὲ ἅπαξ ἀναλώσῃ τὴν ἐξουσίαν καὶ καταχρήσηται τῷ νόμῳ καὶ ἐμπλησθῇ τῆς ὀργῆς, εἶτα μετὰ ταῦτα ἀναλάβῃ, χρηστὸν εἶναι μεταπεισθείς, ἐπὶ τούτων ἀνάγκη μένειν καὶ μηκέτι μεταπηδᾶν μηδὲ μεταβουλεύεσθαι μηδὲ μεταποιεῖν τὴν κρίσιν.", "st": "52.9"}, {"sp": "N", "t": "τοῦ μὲν γὰρ τὸν γεννηθέντα πονηρὸν ἢ χρηστὸν ἀποβήσεσθαι οὐδέν, οἶμαι, γνώρισμα ἦν, καὶ διὰ τοῦτο τοὺς ἀναξίους τοῦ γένους παραιτεῖσθαι συγκεχώρηται τοῖς ὅτε ἠγνόουν ἀναθρεψαμένοις.", "st": "52.9"}, {"sp": "N", "t": "ὅταν δὲ μὴ κατ’ ἀνάγκην ἀλλ’ ἐπ’ ἐξουσίας αὐτός τις ἀφ’ ἑαυτοῦ καὶ δοκιμάσας ἀναλάβῃ, τίς ἔτι μηχανὴ μεταβάλλεσθαι, ἢ τίς ἔτι χρῆσις ὑπόλοιπος τοῦ νόμου; φαίη γὰρ ἂν πρὸς σὲ ὁ νομοθέτης, “εἰ πονηρὸς οὗτος ἦν καὶ τοῦ ἀποκηρυχθῆναι ἄξιος, τί παθὼν ἀνεκάλεις; τί δ’ αὖθις ἐπανῆγες ἐς τὴν οἰκίαν; τί δ’ ἔλυες τὸν νόμον; ἐλεύθερος γὰρ ἦσθα καὶ τοῦ μὴ ποιεῖν ταῦτα κύριος. οὐ γὰρ δὴ ἐντρυφᾶν σοι δοτέον τοῖς νόμοις οὐδὲ πρὸς τὰς σὰς μεταβολὰς συνάγεσθαι τὰ δικαστήρια, οὐδὲ ἄρτι μὲν λύεσθαι ἄρτι δὲ κυρίους εἶναι τοὺς νόμους καὶ τοὺς δικαστὰς καθῆσθαι μάρτυρας, μᾶλλον δὲ ὑπηρέτας, τῶν σοὶ δοκούντων, ὁτὲ μὲν κολάζοντας ὁτὲ δὲ διαλλάττοντας, ὁπόταν σοι δοκῇ. ἅπαξ γεγέννηκας, ἅπαξ ἀνατέτραφας, ἅπαξ καὶ τὸ ἀποκηρύττειν ἀντὶ τούτων ἔχεις, καὶ τότε, ἢν δικαίως αὐτὸ ποιεῖν δοκῇς· τὸ δ’ ἄπαυστον τοῦτο καὶ ἀΐδιον καὶ πολὺ ῥᾴδιον μεῖζον ἤδη τῆς πατρικῆς ἐστιν ἐξουσίας.”", "st": "52.10"}, {"sp": "N", "t": "μὴ δή, πρὸς Διός, ὦ ἄνδρες δικασταί, συγχωρήσητε αὐτῷ ἑκούσιον τὴν ἀνάληψιν πεποιημένῳ καὶ λύσαντι τὴν γνῶσιν τοῦ πάλαι δικαστηρίου καὶ ἀκυρώσαντι τὴν ὀργὴν αὖθις τὴν αὐτὴν τιμωρίαν ἀνακαλεῖν καὶ ἐπὶ τὴν ἐξουσίαν τὴν πατρικὴν ἀνατρέχειν, ἧς ἔξωρος ἤδη καὶ ἕωλος ἡ προθεσμία καὶ μόνῳ τούτῳ ἄκυρος καὶ προδεδαπανημένη. ὁρᾶτε γάρ που καὶ ἐν τοῖς ἄλλοις δικαστηρίοις ὡς ἀπὸ μὲν τῶν κλήρῳ λαχόντων δικαστῶν, ἤν τις ἄδικον οἴηται γεγενῆσθαι τὴν κρίσιν, δίδωσιν ὁ νόμος ἐς ἕτερον ἐφεῖναι δικαστήριον· ἢν δέ τινες ἑκόντες αὐτοὶ σύνθωνται δικαστὰς καὶ προελόμενοι ἐπιτρέψωσιν διαιτᾶν, οὐκέτι. οἷς γὰρ ἐξῆν μηδὲ τὴν ἀρχὴν ἐμμένειν, εἰ τούτους τις αὐθαίρετος εἵλετο, στέργειν ἐστὶ δίκαιος τοῖς ἐγνωσμένοις. οὕτω δὴ καὶ σύ, ὃν ἐξῆν μηκέτ’ ἀναλαμβάνειν εἰ ἀνάξιος ἐδόκει τοῦ γένους, τοῦτον εἰ χρηστὸν ἡγησάμενος εἶναι πάλιν ἀνείληφας, οὐκέτ’ ἀποκηρύττειν ἕξεις· ὅτι γὰρ οὐκ ἄξιος αὖθις παθεῖν ταῦτα, ὑπ’ αὐτοῦ σοῦ μεμαρτύρηται καὶ χρηστὸς ἤδη ἀνωμολόγηται. ἀμετανόητον οὖν τὴν ἀνάληψιν καὶ τὴν διαλλαγὴν βέβαιον εἶναι προσήκει μετὰ κρίσιν οὕτω πολλὴν καὶ δύο δικαστήρια, ἓν μὲν τὸ πρῶτον, ἐφ’ οὗ παρῃτήσω, δεύτερον δὲ τὸ σόν, ὅτε μετεβουλεύσω καὶ ἀνάδαστον ἐποίησας· τὰ πρότερον ἐγνωσμένα λύσας βεβαιοῖς τὰ μετ’ ἐκεῖνα βεβουλευμένα. μένε τοίνυν ἐπὶ τῶν τελευταίων καὶ φύλαττε τὴν σαυτοῦ κρίσιν· πατέρα σε εἶναι δεῖ· τοῦτο γὰρ ἔδοξέ σοι, τοῦτ’ ἐδοκίμασας, τοῦτ’ ἐκύρωσας.", "st": "52.11"}, {"sp": "N", "t": "ἐγὼ μὲν οὐδ’ εἰ μὴ φύσει παῖς ἦν, θέμενος δὲ ἀποκηρύττειν ἤθελες, ἐξεῖναι ἄν σοι ᾠόμην· ὃ γὰρ τὴν ἀρχὴν μὴ ποιεῖν δυνατὸν ἦν, τοῦτ’ ἄδικον λύειν ἅπαξ γενόμενον. τὸν δὲ καὶ φύσει καὶ αὖθις προαιρέσει καὶ γνώμῃ ἐσπεποιημένον, πῶς εὔλογον αὖθις ἀπωθεῖσθαι καὶ πολλάκις τῆς μιᾶς οἰκειότητος ἀποστερεῖν; εἰ δ’ οἰκέτης ὢν ἐτύγχανον, καὶ τὸ μὲν πρῶτον πονηρὸν οἰόμενος ἐπέδησας, μεταπεισθεὶς δὲ ὡς οὐδὲν ἠδίκουν ἐλεύθερον ἀφῆκας εἶναι, ἆρ’ ἄν σοι πρὸς καιρὸν ὀργισθέντι αὖθις ἐξῆν ἐς τὴν ὁμοίαν δουλείαν ἐπανάγειν; οὐδαμῶς. τὰ γὰρ τοιαῦτα βέβαια καὶ διὰ παντὸς κύρια ὑπάρχειν οἱ νόμοι ἀξιοῦσιν.", "st": "52.12"}, {"sp": "N", "t": "ὑπὲρ μὲν οὖν τοῦ μηκέτι ἐξεῖναι τούτῳ ἀποκηρύττειν ὃν ἅπαξ ἀποκηρύξας ἑκὼν ἀνέλαβεν ἔτι πολλὰ εἰπεῖν ἔχων ὅμως παύσομαι.", "st": "52.12"}, {"sp": "N", "t": "σκέψασθε δὲ ἤδη ὅντινα ὄντα καὶ ἀποκηρύξει· καὶ οὐ δή που τοῦτό φημι, ὡς τότε μὲν ἰδιώτην, νῦν δὲ ἰατρόν· οὐδὲν γὰρ ἂν πρὸς τοῦτο ἡ τέχνη συναγωνίσαιτο· οὐδ’ ὅτι τότε μὲν νέον, νῦν δὲ ἤδη καὶ προβεβηκότα καὶ τὸ πιστὸν τοῦ μηδὲν ἀδικῆσαι ἂν παρὰ τῆς ἡλικίας ἔχοντα· μικρὸν γὰρ ἴσως καὶ τοῦτο. ἀλλὰ τότε μέν, εἰ καὶ μηδὲν ἠδικημένος, ὡς ἂν ἔγωγε φαίην, ἀλλ’ οὐδὲ εὖ πεπονθὼς παρῃτεῖτο τῆς οἰκίας, νῦν δὲ σωτῆρα ἔναγχος καὶ εὐεργέτην γεγενημένον. οὗ τί γένοιτ’ ἂν ἀχαριστότερον, σωθέντα δι’ ἐμὲ καὶ τηλικοῦτον κίνδυνον διαπεφευγότα τοῖς τοιούτοις εὐθὺς ἀμείβεσθαι, τῆς θεραπείας ἐκείνης οὐδένα λόγον ἔχοντα, ἀλλ’ οὕτω ῥᾳδίως ἐπιλελῆσθαι καὶ ἐπὶ τὴν ἐρημίαν ἐλαύνειν τὸν ἐφησθέντ’ ἂν δικαίως ἐφ’ οἷς ἀδίκως ἐξεβέβλητο, μὴ μόνον δ’ οὐ μνησικακήσαντα, ἀλλὰ καὶ σώσαντα καὶ σωφρονεῖν παρασκευάσαντα;", "st": "52.13"}, {"sp": "N", "t": "οὐ γὰρ σμικρόν, ὦ ἄνδρες δικασταί, οὐδὲ τὸ τυχὸν εὖ πεποιηκὼς αὐτόν, ὅμως τῶν τοιούτων νῦν ἀξιοῦμαι. ἀλλ’ εἰ καὶ οὗτος ἀγνοεῖ τὰ τότε, πάντες ὑμεῖς ἴστε οἷα ποιοῦντα αὐτὸν καὶ πάσχοντα καὶ ὅπως διακείμενον ἐγὼ παραλαβών, τῶν μὲν ἄλλων ἰατρῶν ἀπεγνωκότων, τῶν δὲ οἰκείων φευγόντων καὶ μηδὲ πλησίον προσιέναι τολμώντων, τοιοῦτον ἀπέφηνα ὡς καὶ κατηγορεῖν δύνασθαι καὶ περὶ τῶν νόμων διαλέγεσθαι. μᾶλλον δέ, ὁρᾷς, ὦ πάτερ, τὸ παράδειγμα· τοιοῦτον ὄντα σε παρ’ ὀλίγον οἵα νῦν ἡ γυνή ἐστιν, πρὸς τὴν ἀρχαίαν φρόνησιν ἐπανήγαγον. οὐ δὴ δίκαιον τοιαύτην μοι γενέσθαι ἀντ’ ἐκείνων τὴν ἀμοιβὴν οὐδὲ κατ’ ἐμοῦ σε μόνου σωφρονεῖν· ὅτι γὰρ μὴ μικρὰ ὑπ’ ἐμοῦ εὐηργέτησαι, καὶ ἀπ’ αὐτῶν ὧν ἐγκαλεῖς δῆλόν ἐστιν· ὃν γὰρ ὡς ἐν ἐσχάτοις οὖσαν τὴν γυναῖκα καὶ παμπονηρῶς ἔχουσαν οὐκ ἰώμενον μισεῖς, πῶς οὐ πολὺ μᾶλλον ὅτι σε τῶν ὁμοίων ἀπήλλαξα ὑπεραγαπᾷς καὶ χάριν ὁμολογεῖς, τῶν οὕτω δεινῶν ἀπηλλαγμένος; σὺ δέ, ὅπερ ἀγνωμονέστατον, σωφρονήσας εὐθὺς ἐς δικαστήριον ἄγεις καὶ σεσωσμένος κολάζεις καὶ ἐπὶ τὸ ἀρχαῖον ἐκεῖνο μῖσος ἀνατρέχεις καὶ τὸν αὐτὸν ἀναγινώσκεις νόμον. καλὸν γοῦν τὸν μισθὸν ἀποδίδως τῇ τέχνῃ καὶ ἀξίας ἀμοιβὰς τῶν φαρμάκων ἐπὶ τὸν ἰατρὸν ὑγιαίνων μόνον.", "st": "52.14"}, {"sp": "N", "t": "ὑμεῖς δέ, ὦ ἄνδρες δικασταί, τὸν εὐεργέτην τούτῳ κολάζειν ἐπιτρέψετε καὶ τὸν σώσαντα ἐξελαύνειν καὶ τὸν σωφρονίσαντα μισεῖν καὶ τὸν ἀναστήσαντα τιμωρεῖσθαι; οὔκ, ἤν γε τὰ δίκαια ποιῆτε. καὶ γὰρ εἰ τὰ μέγιστα νῦν ἁμαρτάνων ἐτύγχανον, ἦν μοί τις οὐ μικρὰ προοφειλομένη χάρις, ἐς ἣν ἀποβλέποντα τοῦτον καὶ ἧς μεμνημένον καλῶς εἶχε τῶν μὲν παρόντων καταφρονεῖν, δι’ ἐκεῖνα δὲ πρόχειρον τὴν συγγνώμην ἔχειν, καὶ μάλιστα εἰ τηλικαύτη τις ἡ εὐεργεσία τυγχάνοι ὡς πάντα ὑπερπαίειν τὰ μετὰ ταῦτα. ὅπερ οἶμαι κἀμοὶ πρὸς τοῦτον ὑπάρχειν, ὃν ἔσωσα, καὶ ὃς τοῦ βίου παντὸς χρεώστης ἐστί μοι, καὶ ᾧ τὸ εἶναι καὶ τὸ σωφρονεῖν καὶ τὸ συνιέναι παρέσχημαι, καὶ μάλιστα ὅτε οἱ ἄλλοι πάντες ἤδη ἀπεγνώκεσαν καὶ ἥττους εἶναι ὡμολόγουν τῆς νόσου.", "st": "52.15"}, {"sp": "N", "t": "τοῦτο γὰρ μείζω οἶμαι ποιεῖν τὴν ἐμὴν εὐεργεσίαν, ὃς οὔτε υἱὸς ὢν τότε οὔτε ἀναγκαίαν τῆς θεραπείας ἔχων αἰτίαν ἀλλὰ ἐλεύθερος καθεστὼς καὶ ἀλλότριος, τῆς φυσικῆς αἰτίας ἀφειμένος, ὅμως οὐ περιεῖδον, ἀλλ’ ἐθελοντής, ἄκλητος, αὐτεπάγγελτος ἧκον· ἐβοήθησα, προσελιπάρησα, ἰασάμην, ἀνέστησα, καὶ τὸν πατέρα ἐμαυτῷ διεφύλαξα, καὶ ὑπὲρ τῆς ἀποκηρύξεως ἀπελογησάμην, καὶ τῇ εὐνοίᾳ τὴν ὀργὴν ἔπαυσα, καὶ τὸν νόμον ἔλυσα τῇ φιλοστοργίᾳ, καὶ μεγάλης εὐεργεσίας τὴν ἐς τὸ γένος ἐπάνοδον ἐπριάμην, καὶ ἐν οὕτως ἐπισφαλεῖ καιρῷ τὴν πρὸς τὸν πατέρα πίστιν ἐπεδειξάμην, καὶ μετὰ τῆς τέχνης ἐμαυτὸν ἐσεποίησα, καὶ γνήσιος υἱὸς ἐν τοῖς δεινοῖς ἀνεφάνην.", "st": "52.16"}, {"sp": "N", "t": "πόσα γὰρ οἴεσθε παθεῖν με, πόσα καμεῖν παρόντα, ὑπηρετοῦντα, καιροφυλακοῦντα, νῦν μὲν εἴκοντα τῇ τοῦ πάθους ἀκμῇ, νῦν δὲ τὴν τέχνην ἐπάγοντα πρὸς ὀλίγον ἐνδιδόντος τοῦ κακοῦ; ἔστιν δὲ τῶν ὄντων ἁπάντων τούτων ἐν τῇ ἰατρικῇ τὸ ἐπισφαλέστατον τοὺς τοιούτους ἰᾶσθαι καὶ πλησιάζειν οὕτω διακειμένοις· ἐς γὰρ τοὺς πλησίον πολλάκις ἀφιᾶσι τὴν λύτταν, ἐπιζέσαντος τοῦ πάθους. καὶ ὅμως πρὸς οὐδὲν τούτων ἀπώκνησα οὐδὲ ἀπεδειλίασα, συνὼν δὲ καὶ πάντα τρόπον ἀντεξεταζόμενος τῇ νόσῳ τὸ τελευταῖον ἐκράτησα τῷ φαρμάκῳ.", "st": "52.16"}, {"sp": "N", "t": "μὴ γὰρ τοῦτ’ ἀκούσας εὐθὺς ὑπολάβῃ τις “ποῖος δὲ ἢ πόσος ὁ κάματος ἐγχέαι φάρμακον;” πολλὰ γὰρ πρὸ τούτου γενέσθαι δεῖ, καὶ προοδοποιῆσαι τῇ πόσει καὶ προπαρασκευάσαι ῥᾴδιον ἐς ἴασιν τὸ σῶμα καὶ τῆς ἁπάσης ἕξεως φροντίσαι κενοῦντα καὶ ἰσχναίνοντα καὶ οἷς χρὴ τρέφοντα καὶ κινοῦντα ἐς ὅσον χρήσιμον καὶ ὕπνους ἐπινοοῦντα καὶ ἠρεμίας μηχανώμενον, ἅπερ οἱ μὲν ἄλλο τι νοσοῦντες ῥᾳδίως πεισθεῖεν ἄν, οἱ μεμηνότες δὲ διὰ τὴν ἐλευθερίαν τοῦ νοῦ δυσάγωγοι καὶ δυσηνιόχητοι καὶ τῷ ἰατρῷ ἐπισφαλεῖς καὶ τῇ θεραπείᾳ δυσκαταγώνιστοι. ὅταν γοῦν πολλάκις οἰήθωμεν ἤδη πλησίον γενέσθαι τοῦ τέλους καὶ ἐλπίσωμεν, ἐμπεσόν τι μικρὸν ἁμάρτημα ἐπακμάσαντος τοῦ πάθους ἅπαντα ῥᾳδίως ἐκεῖνα ἀνέτρεψε καὶ ἐνεπόδισε τὴν θεραπείαν καὶ τὴν τέχνην διέσφηλε.", "st": "52.17"}, {"sp": "N", "t": "τὸν οὖν ταῦτα πάντα ὑπομεμενηκότα καὶ οὕτω χαλεπῷ νοσήματι προσπαλαίσαντα καὶ πάθος ἁπάντων παθῶν τὸ δυσαλωτότατον νενικηκότα ἔτι τούτῳ ἀποκηρύττειν ἐπιτρέψετε, καὶ τοὺς νόμους ὡς βούλεται ἑρμηνεύειν κατ’ εὐεργέτου συγχωρήσετε, καὶ τῇ φύσει πολεμεῖν αὐτὸν ἐάσετε;", "st": "52.18"}, {"sp": "N", "t": "ἐγὼ τῇ φύσει πειθόμενος, ὦ ἄνδρες δικασταί, σώζω καὶ διαφυλάττω τὸν πατέρα ἐμαυτῷ κἂν ἀδικῇ· οὑτοσὶ δὲ τὸν εὐεργετηκότα παῖδα τοῖς νόμοις, ὥς φησιν, ἀκολουθῶν διαφθείρει καὶ τοῦ γένους ἀποστερεῖ. μισόπαις οὗτος, ἐγὼ φιλοπάτωρ γίγνομαι. ἐγὼ τὴν φύσιν ἀσπάζομαι, οὗτος τὰ τῆς φύσεως παρορᾷ καὶ καθυβρίζει δίκαια. ὢ πατρὸς μισοῦντος ἀδίκως· ὢ παιδὸς φιλοῦντος ἀδικώτερον. ἐγκαλῶ γὰρ ἐμαυτῷ, τοῦ πατρὸς ἀναγκάζοντος, ὅτι μισούμενος οὐ δέον φιλῶ καὶ φιλῶ πλέον ἢ προσῆκεν. καίτοι γε ἡ φύσις τοῖς πατράσιν τοὺς παῖδας μᾶλλον ἢ τοῖς παισὶν τοὺς πατέρας ἐπιτάττει φιλεῖν. ἀλλ’ οὗτος ἑκὼν καὶ τοὺς νόμους παρορᾷ, οἳ τοὺς οὐδὲν ἠδικηκότας παῖδας τῷ γένει φυλάττουσιν, καὶ τὴν φύσιν, ἣ τοὺς γεννήσαντας ἕλκει πρὸς πόθον τῶν γεγεννημένων πολύν. οὐχ ὅπως μείζους ἀρχὰς εὐνοίας ἔχων πρὸς ἐμὲ μείζονα τὰ δίκαιά μοι τῆς εὐνοίας ἐσφέρει καὶ ἐπιδίδωσιν, ἢ τό γε ἔλαττον ἐμὲ μιμεῖται καὶ ζηλοῖ τοῦ φίλτρου· ἀλλ’, οἴμοι τῆς συμφορᾶς, προσέτι καὶ μισεῖ φιλοῦντα καὶ ἀγαπῶντα ἐλαύνει καὶ εὐεργετοῦντα ἀδικεῖ καὶ ἀσπαζόμενον ἀποκηρύττει, καὶ τοὺς φιλόπαιδας νόμους ὡς μισόπαιδας κατ’ ἐμοῦ μεταχειρίζεται. ὢ μάχης ἣν ἐσάγεις, πάτερ, τοῖς νόμοις κατὰ τῆς φύσεως.", "st": "52.18"}, {"sp": "N", "t": "οὐκ ἔστι ταῦτα, οὐκ ἔστιν ὡς θέλεις· κακῶς ἑρμηνεύεις, ὦ πάτερ, καλῶς κειμένους τοὺς νόμους. οὐ πολεμεῖ φύσις καὶ νόμος ἐν ταῖς εὐνοίαις, ἀλλ’ ἀκολουθοῦσιν ἀλλήλοις ἐνταῦθα καὶ συναγωνίζονται τῇ λύσει τῶν ἀδικημάτων. ὑβρίζεις τὸν εὐεργέτην, ἀδικεῖς τὴν φύσιν. τί καὶ τοὺς νόμους συναδικεῖς τῇ φύσει; οὓς καλοὺς καὶ δικαίους καὶ φιλόπαιδας εἶναι θέλοντας οὐ συγχωρεῖς, καθ’ ἑνὸς παιδὸς ὡς κατὰ πολλῶν κινῶν πολλάκις καὶ ἡσυχάζειν οὐκ ἐῶν ἐν ταῖς τιμωρίαις τοὺς ἐν ταῖς τῶν παίδων πρὸς τοὺς πατέρας εὐνοίαις ἡσυχάζειν ἐθέλοντας, καίτοι γε ἐπὶ τοῖς μηδὲν ἡμαρτηκόσιν μηδὲ κειμένους. καὶ μὴν οἵ γε νόμοι καὶ ἀχαριστίας δικάζεσθαι διδόασιν κατὰ τῶν τοὺς εὐεργέτας μὴ ἀντευποιούντων. ὁ δὲ πρὸς τῷ μὴ ἀμείβεσθαι καὶ ἐπ’ αὐτοῖς οἷς πέπονθε κολάζειν ἀξιῶν, σκέψασθε εἴ τινα ὑπερβολὴν ἀδικίας ἀπολέλοιπεν.", "st": "52.19"}, {"sp": "N", "t": "ὡς μὲν οὖν οὔτε ἀποκηρύττειν ἔτι τούτῳ ἔξεστιν ἅπαξ ἤδη τὴν πατρικὴν ἐξουσίαν ἀποπληρώσαντι καὶ χρησαμένῳ τοῖς νόμοις, οὔτε ἄλλως δίκαιον εὐεργέτην ἐς τὰ τηλικαῦτα γεγενημένον ἀπωθεῖσθαι καὶ τῆς οἰκίας παραιτεῖσθαι, ἱκανῶς, οἶμαι, δέδεικται.", "st": "52.19"}, {"sp": "N", "t": "ἤδη δὲ καὶ ἐπ’ αὐτὴν τὴν αἰτίαν ἔλθωμεν τῆς ἀποκηρύξεως καὶ τὸ ἔγκλημα ἐξετάσωμεν ὁποῖόν ἐστιν. ἀνάγκη δὲ αὖθις ἐπὶ τὴν γνώμην ἀναδραμεῖν τοῦ νομοθέτου· ἵνα γάρ σοι τοῦτο πρὸς ὀλίγον δῶμεν, τὸ ἐξεῖναι ὁσάκις ἂν θέλῃς ἀποκηρύττειν, καὶ κατά γε τοῦ εὐεργέτου προσέτι τὴν ἐξουσίαν ταύτην συγχωρήσωμεν, οὐχ ἁπλῶς, οἶμαι, οὐδὲ ἐπὶ πάσαις αἰτίαις ἀποκηρύξεις. οὐδὲ τοῦθ’ ὁ νομοθέτης φησίν, ὅ τι ἂν τύχῃ ὁ πατὴρ αἰτιασάμενος, ἀποκηρυττέτω, καὶ ἀπόχρη θελῆσαι μόνον καὶ μέμψασθαι. τί γὰρ ἂν ἔδει δικαστηρίου; ἀλλ’ ἐν ὑμῖν ποιεῖ τοῦτο, ὦ ἄνδρες δικασταί, σκοπεῖν εἴτε ἐπὶ μεγάλοις καὶ δικαίοις ὁ πατὴρ ὀργίζεται εἴτε καὶ μή. οὐκοῦν τοῦτο ἤδη ἐξετάσατε. ἄρξομαι δὲ ἀπὸ τῶν μετὰ τὴν μανίαν εὐθύς.", "st": "52.20"}, {"sp": "N", "t": "τὰ μὲν δὴ πρῶτα τῆς σωφροσύνης τοῦ πατρὸς λύσις ἦν τῆς ἀποκηρύξεως, καὶ σωτὴρ καὶ εὐεργέτης καὶ πάντα ἦν ἐγώ. καὶ οὐδέν, οἶμαι, τούτοις ἔγκλημα προσεῖναι ἐδύνατο. τὰ μετὰ ταῦτα δέ, τί τῶν πάντων αἰτιᾷ; τίνα θεραπείαν, τίνα ἐπιμέλειαν υἱοῦ παρῆκα; πότε ἀπόκοιτος ἐγενόμην; τίνας πότους ἀκαίρους, τίνας κώμους ἐγκαλεῖς; τίς ἀσωτία; τίς πορνοβοσκὸς ὕβρισται; τίς ᾐτιάσατο; οὐδὲ εἷς. καὶ μὴν ταῦτ’ ἐστὶν ἐφ’ οἷς μάλιστα ὁ νόμος ἀποκηρύττειν ἐφίησιν.", "st": "52.21"}, {"sp": "N", "t": "“ἀλλὰ νοσεῖν ἤρξατο ἡ μητρυιά.” τί οὖν; ἐμοὶ τοῦτ’ ἐγκαλεῖς καὶ νόσου δίκην ἀπαιτεῖς;", "st": "52.21"}, {"sp": "N", "t": "“οὔ,” φησίν. ἀλλὰ τί; “θεραπεύειν προσταττόμενος οὐ θέλεις, καὶ διὰ τοῦτ’ ἄξιος ἂν εἴης ἀποκηρύξεως ἀπειθῶν τῷ πατρί.” ἐγὼ δὲ τὸ μὲν οἷα προστάττοντι αὐτῷ ὑπακούειν οὐ δυνάμενος ἀπειθεῖν δοκῶ πρὸς ὀλίγον ὑπερθήσομαι· πρότερον δὲ ἁπλῶς ἐκεῖνό φημι, ὡς οὐ πάντα προστάττειν οὔτε τούτῳ δίδωσιν ὁ νόμος οὔτ’ ἐμοὶ τὸ πείθεσθαι πᾶσιν πάντως ἀναγκαῖον. ἐν δ’ οὖν τοῖς τῶν προσταγμάτων τὰ μὲν ἀνεύθυνά ἐστιν, τὰ δὲ ὀργῆς καὶ τιμωρίας ἄξια. ἐὰν νοσῇς αὐτός, ἐγὼ δὲ ἀμελῶ· ἐὰν τῶν κατ’ οἶκον ἐπιμελεῖσθαι κελεύῃς, ἐγὼ δὲ ὀλιγωρῶ· ἐὰν τὰ κατ’ ἀγρὸν ἐπισκοπεῖν προστάττῃς, ἐγὼ δὲ ὀκνῶ — πάντα ταῦτα καὶ τὰ τοιαῦτα εὐλόγους ἔχει τὰς προφάσεις καὶ τὰς μέμψεις πατρικάς. τὰ δὲ ἄλλα ἐφ’ ἡμῖν ἐστιν τοῖς παισίν, ὄντα τῶν τεχνῶν καὶ τῆς τούτων χρήσεως, καὶ μάλιστα εἰ μηδὲν ὁ πατὴρ αὐτὸς ἀδικοῖτο. ἐπεί τοι ἂν τῷ γραφεῖ πατὴρ προστάττῃ, “ταῦτα μέν, τέκνον, γράφε, ταυτὶ δὲ μή,” καὶ τῷ μουσικῷ, “τήνδε μὲν τὴν ἁρμονίαν κροῦε, ταύτην δὲ μή,” καὶ τῷ χαλκεύοντι, “τοιαῦτα μὲν χάλκευε, τοιαῦτα δὲ μή,” ἆρ’ ἄν τις ἀνάσχοιτο ἀποκηρύττοντα, ὅτι μὴ κατὰ τὰ ἐκείνῳ δοκοῦντα ὁ παῖς χρῆται τῇ τέχνῃ; οὐδὲ εἷς, οἶμαι.", "st": "52.22"}, {"sp": "N", "t": "τὸ δὲ τῆς ἰατρικῆς ὅσῳ σεμνότερόν ἐστιν καὶ τῷ βίῳ χρησιμώτερον, τοσούτῳ καὶ ἐλευθεριώτερον εἶναι προσήκει τοῖς χρωμένοις, καί τινα προνομίαν ἔχειν τὴν τέχνην δίκαιον τῇ ἐξουσίᾳ τῆς χρήσεως, ἀναγκάζεσθαι δὲ μηδὲν μηδὲ προστάττεσθαι πρᾶγμα ἱερὸν καὶ θεῶν παίδευμα καὶ ἀνθρώπων σοφῶν ἐπιτήδευμα, μηδ’ ὑπὸ δουλείαν γενέσθαι νόμου μηδ’ ὑπὸ ψῆφον καὶ τιμωρίαν δικαστηρίου, μηδὲ ὑπὸ φόβον καὶ πατρὸς ἀπειλὴν καὶ ὀργὴν ἰδιωτικήν. ὥστε καὶ εἰ τοῦτό σοι σαφῶς οὑτωσὶ καὶ διαρρήδην ἔλεγον, “οὐ βούλομαι οὐδὲ θεραπεύω δυνάμενος, ἀλλ’ ἐμαυτῷ μόνῳ τὴν τέχνην οἶδα καὶ πατρί, τοῖς δὲ ἄλλοις ἅπασιν ἰδιώτης εἶναι βούλομαι,” τίς τύραννος οὕτω βίαιος ὡς ἀναγκάσαι ἂν καὶ ἄκοντα χρῆσθαι τῇ τέχνῃ; τὰ γὰρ τοιαῦτα ἱκετείαις καὶ δεήσεσιν, οὐ νόμοις καὶ ὀργαῖς καὶ δικαστηρίοις ὑπάγειν, οἶμαι, προσήκει· πείθεσθαι τὸν ἰατρὸν χρή, οὐ κελεύεσθαι· βούλεσθαι, οὐ φοβεῖσθαι· ἐπὶ τὴν θεραπείαν οὐκ ἄγεσθαι, ἑκόντα δὲ ἐρχόμενον ἥδεσθαι. πατρικῆς δὲ ἀνάγκης ἄμοιρος ἡ τέχνη, ὅπου γε τοῖς ἰατροῖς καὶ δημοσίᾳ αἱ πόλεις τιμὰς καὶ προεδρίας καὶ ἀτελείας καὶ προνομίας διδόασιν.", "st": "52.23"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἁπλῶς ἂν εἶχον εἰπεῖν ὑπὲρ τῆς τέχνης, εἰ καὶ σοῦ διδαξαμένου με καὶ πολλὰ ἐπιμεληθέντος καὶ ἀναλώσαντος ὡς μάθοιμι πρὸς μίαν ὅμως θεραπείαν ταύτην, δυνατὴν οὖσαν, ἀντέλεγον. νυνὶ δὲ κἀκεῖνο ἐννόησον, ὡς παντάπασιν ἄγνωμον ποιεῖς οὐκ ἐῶν με χρῆσθαι μετ’ ἐλευθερίας ἐμῷ κτήματι. ταύτην ἐγὼ τὴν τέχνην οὐχ υἱὸς ὢν σὸς ἐξέμαθον οὐδὲ τῷ σῷ νόμῳ ὑποκείμενος, καὶ ὅμως αὐτὴν μεμάθηκά σοι — καὶ πρῶτος αὐτῆς ἀπολέλαυκας — οὐδὲν παρὰ σοῦ πρὸς τὸ μαθεῖν ἔχων. τίνα διδάσκαλον ἐμισθώσω; τίνα φαρμάκων παρασκευήν; οὐδ’ ἡντιναοῦν· ἀλλὰ πενόμενος ἐγὼ καὶ τῶν ἀναγκαίων ἀπορούμενος καὶ ὑπὸ τῶν διδασκάλων ἐλεούμενος ἐπαιδευόμην, καί μοι τοιαῦτα παρὰ τοῦ πατρὸς ἦν πρὸς τὸ μαθεῖν ἐφόδια, λύπη καὶ ἐρημία καὶ ἀπορία καὶ μῖσος οἰκείων καὶ ἀποστροφὴ συγγενῶν. ἀντὶ τούτων τοίνυν χρῆσθαί μου τῇ τέχνῃ ἀξιοῖς καὶ δεσπότης εἶναι θέλεις τῶν ὅτ’ οὐκ ἦσθα δεσπότης πεπορισμένων; ἀγάπα εἴ τί σε καὶ πρότερον ἑκὼν οὐ προοφείλων εὖ ἐποίησα, μηδεμίαν μηδὲ τότε χάριν ἀπαιτεῖσθαι δυνάμενος.", "st": "52.24"}, {"sp": "N", "t": "οὐ δὴ δεῖ τὴν εὐποιίαν τὴν ἐμὴν ἀνάγκην ἐς τὸ λοιπόν μοι γενέσθαι, οὐδὲ τὸ ἑκόντα εὐεργετῆσαι ἀφορμὴν τοῦ ἄκοντα κελεύεσθαι καταστῆναι, οὐδὲ ἔθος ὑπάρξαι τοῦτο, τὸ ἅπαξ τινὰ ἰασάμενον πάντας ἐς ἀεὶ θεραπεύειν ὁπόσους ἂν ὁ θεραπευθεὶς θέλῃ· ἐπεὶ δεσπότας ἂν οὕτως καθ’ ἡμῶν εἴημεν τοὺς θεραπευομένους κεχειροτονηκότες καὶ μισθὸν τὸ δουλεύειν αὐτοῖς καὶ τὸ πάντα κελεύουσιν ὑπηρετεῖν προσδεδωκότες, οὗ τί γένοιτ’ ἂν ἀδικώτερον; διότι σε νοσήσαντα χαλεπῶς οὕτως ἀνέστησα, διὰ τοῦτο νομίζεις ἐξεῖναί σοι καταχρῆσθαί μου τῇ τέχνῃ;", "st": "52.25"}, {"sp": "N", "t": "ταῦτα μὲν οὖν εἶχον ἂν λέγειν, εἰ καὶ δυνατὰ μὲν οὗτος προσέταττεν, ἐγὼ δὲ μὴ πάντως ἅπασι μηδὲ πρὸς ἀνάγκην ὑπήκουον. νῦν δὲ ἤδη σκέψασθε καὶ οἷά ἐστιν αὐτοῦ τὰ ἐπιτάγματα· “ἐπεὶ γὰρ ἐμὲ ἰάσω,” φησίν, “μεμηνότα, μέμηνεν δὲ καὶ ἡ γυνὴ καὶ ὅμοια πάσχει —” τοῦτο γὰρ οἴεται — “καὶ ὑπὸ τῶν ἄλλων ὁμοίως ἀπέγνωσται, δύνασαι δὲ σὺ πάντα ὡς ἔδειξας, ἰῶ καὶ ταύτην καὶ ἀπάλλαττε ἤδη τῆς νόσου.” τοῦτο δέ, οὑτωσὶ μὲν ἁπλῶς ἀκοῦσαι, πάνυ εὔλογον ἂν δόξειεν, καὶ μάλιστα ἰδιώτῃ καὶ ἀπείρῳ ἰατρικῆς· εἰ δέ μου ἀκούσαιτε ὑπὲρ τῆς τέχνης δικαιολογουμένου, μάθοιτ’ ἂν ὡς οὔτε πάντα ἡμῖν δυνατά ἐστιν οὔθ’ αἱ τῶν νοσημάτων φύσεις παραπλήσιοι οὔτ’ ἴασις ἡ αὐτὴ οὔτε φάρμακα τὰ αὐτὰ ἐπὶ πάντων ἰσχυρά, καὶ τότ’ ἔσται δῆλον ὡς πάμπολυ τοῦ μὴ βούλεσθαί τι τὸ μὴ δύνασθαι διαφέρει. ἀνάσχεσθε δέ μου τὰ περὶ τούτων φιλοσοφοῦντος, καὶ μὴ ἀπειρόκαλον μηδὲ ἐξαγώνιον μηδὲ ἀλλότριον ἢ ἄκαιρον ἡγήσησθε τὸν περὶ τῶν τοιούτων λόγον.", "st": "52.26"}, {"sp": "N", "t": "πρῶτα μὲν δὴ σωμάτων φύσεις καὶ κράσεις οὐχ αἱ αὐταί, κἂν ὅτι μάλιστα ἐκ τῶν ὁμοίων συνεστάναι ὁμολογῶνται, ἀλλὰ τὰ μὲν τῶνδε, τὰ δὲ τῶνδε μᾶλλον ἢ ἔλαττον μετέχει. καὶ λέγω τοῦτο ἔτι περὶ τῶν ἀνδρείων, ὡς οὐδὲ ταῦτα πᾶσιν ἴσα ἢ ὅμοια οὔτε τῇ κράσει οὔτε τῇ συστάσει. διάφορα δὴ καὶ μεγέθει καὶ εἴδει ἀνάγκη καὶ τὰ νοσήματα ἐγγίγνεσθαι αὐτοῖς, καὶ τὰ μὲν εὐίατα εἶναι καὶ πρὸς τὴν θεραπείαν ἀναπεπταμένα, τὰ δὲ τέλεον ἀπεγνωσμένα καὶ ῥᾳδίως ἁλισκόμενα καὶ κατὰ κράτος ὑπὸ τῶν νοσημάτων λαμβανόμενα. τὸ τοίνυν οἴεσθαι πάντα πυρετὸν ἢ πᾶσαν φθόην ἢ περιπλευμονίαν ἢ μανίαν μίαν καὶ τὴν αὐτὴν οὖσαν τῷ γένει ὁμοίαν ἐπὶ παντὸς εἶναι σώματος, οὐ σωφρονούντων οὐδὲ λελογισμένων οὐδὲ τὰ τοιαῦτα ἐξητακότων ἐστὶν ἀνθρώπων, ἀλλὰ τὸ αὐτὸ ἐν μὲν τῷδε ῥᾴδιον ἰᾶσθαι, ἐν δὲ τῷδε οὐκέτι. ὥσπερ οἶμαι καὶ πυρὸν ἢν τὸν αὐτὸν ἐς διαφόρους χώρας ἐμβάλῃς, ἄλλως μὲν ἐν τῇ πεδινῇ καὶ βαθείᾳ καὶ ποτιζομένῃ καὶ εὐηλίῳ καὶ εὐηνέμῳ καὶ ἐξειργασμένῃ ἀναφύσεται, εὐθαλὴς οἶμαι καὶ εὔτροφος καὶ πολύχους καρπός, ἄλλως δὲ ἐν ὄρει καὶ ὑπολίθῳ γηδίῳ, ἄλλως δὲ ἐν δυσηλίῳ, ἄλλως δὲ ἐν ὑπωρείᾳ, καὶ ὅλως διαφόρως καθ’ ἑκάστους τόπους. οὕτω δὲ καὶ τὰ νοσήματα παρὰ τοὺς ὑποδεξαμένους τόπους ἢ εὔφορα καὶ εὔτροφα ἢ ἐλάττω γίγνεται. τοῦτο τοίνυν ὑπερβὰς ὁ πατὴρ καὶ ὅλον ἀνεξέταστον καταλιπὼν ἀξιοῖ πᾶσαν μανίαν τὴν ἐν ἅπαντι σώματι ὁμοίαν εἶναι καὶ τὴν θεραπείαν ἴσην.", "st": "52.27"}, {"sp": "N", "t": "πρὸς δὲ τούτοις τοσούτοις οὖσιν, ὅτι τὰ γυναικεῖα σώματα πάμπολυ τῶν ἀνδρείων διαφέρει πρός τε νόσου διαφορὰν καὶ πρὸς θεραπείας ἐλπίδα ἢ ἀπόγνωσιν ῥᾴδιον καταμαθεῖν· τὰ μὲν γὰρ τῶν ἀνδρῶν εὐπαγῆ καὶ εὔτονα, πόνοις καὶ κινήσεσιν καὶ ὑπαιθρίῳ διαίτῃ γεγυμνασμένα, τὰ δὲ ἔκλυτα καὶ ἀσυμπαγῆ, ἐνσκιᾳτροφημένα καὶ λευκὰ αἵματος ἐνδείᾳ καὶ θερμοῦ ἀπορίᾳ καὶ ὑγροῦ περιττοῦ ἐπιρροίᾳ. εὐαλωτότερα τοίνυν τῶν ἀνδρείων καὶ ταῖς νόσοις ἐκκείμενα καὶ τὴν ἴασιν οὐ περιμένοντα καὶ μάλιστα πρὸς μανίας εὐχερέστερα· ἅτε γὰρ πολὺ μὲν τὸ ὀργίλον καὶ κοῦφον καὶ ὀξυκίνητον ἔχουσαι, ὀλίγην δὲ τὴν τοῦ σώματος αὐτοῦ δύναμιν, ῥᾳδίως ἐς τὸ πάθος τοῦτο κατολισθάνουσιν.", "st": "52.28"}, {"sp": "N", "t": "οὐ δίκαιον τοίνυν παρὰ τῶν ἰατρῶν τὴν ὁμοίαν ἐπ’ ἀμφοῖν θεραπείαν ἀπαιτεῖν, εἰδότας ὡς πολὺ τοὐν μέσῳ, βίῳ παντὶ καὶ πράξεσιν ὅλαις καὶ πᾶσιν ἐπιτηδεύμασιν ἐξ ἀρχῆς εὐθὺς κεχωρισμένων. ὅταν τοίνυν λέγῃς ὅτι μέμηνε, προστίθει καὶ ὅτι γυνὴ οὖσα μέμηνε, καὶ μὴ σύγχει πάντα ταῦτα τῷ τῆς μανίας ὑπάγων ὀνόματι ἑνὶ καὶ τῷ αὐτῷ δοκοῦντι, ἀλλὰ χωρίσας, ὥσπερ ἐστὶ δίκαιον, τῇ φύσει, τὸ δυνατὸν ἐφ’ ἑκάστου σκόπει. καὶ γὰρ ἡμεῖς, ὅπερ ἐν ἀρχῇ τῶν λόγων εἰπὼν μέμνημαι, τοῦτο πρῶτον ἐπισκοποῦμεν, φύσιν σώματος τοῦ νοσοῦντος καὶ κρᾶσιν, καὶ τίνος πλείονος μετέχει, καὶ εἰ θερμότερον ἢ ψυχρότερον, καὶ ἀκμάζον ἢ παρηβηκός, καὶ μέγα ἢ μικρόν, καὶ πιμελὲς ἢ ὀλιγόσαρκον, καὶ πάντα τὰ τοιαῦτα. καὶ ὅλως ἄν τις αὐτὰ προεξετάσῃ, πάνυ ἀξιόπιστος ἂν εἴη ἀπογιγνώσκων τι ἢ ὑπισχνούμενος.", "st": "52.29"}, {"sp": "N", "t": "ἐπεὶ καὶ τῆς μανίας αὐτῆς μυρία εἴδη ἐστὶν καὶ παμπόλλας ἔχει τὰς αἰτίας καὶ οὐδὲ τὰς προσηγορίας αὐτὰς ὁμοίας· οὐ γὰρ ταὐτὸν παρανοεῖν καὶ παραπαίειν καὶ λυττᾶν καὶ μεμηνέναι, ἀλλὰ ταῦτα πάντα τοῦ μᾶλλον ἢ ἧττον ἔχεσθαι τῇ νόσῳ ὀνόματά ἐστιν. αἰτίαι τε τοῖς μὲν ἀνδράσιν ἄλλαι, ταῖς δὲ γυναιξὶν ἕτεραι, καὶ τῶν ἀνδρῶν αὐτῶν τοῖς μὲν νέοις ἄλλαι, τοῖς δὲ γεγηρακόσιν διάφοροι, οἷον νέοις μὲν πλῆθος ὡς τὸ πολύ, γέροντας δὲ καὶ διαβολὴ ἄκαιρος καὶ ὀργὴ ἄλογος πολλάκις κατ’ οἰκείων ἐμπεσοῦσα τὸ μὲν πρῶτον διετάραξεν, εἶτα κατ’ ὀλίγον ἐς μανίαν περιέτρεψεν. γυναικῶν δὲ πολλὰ καθικνεῖται καὶ ῥᾳδίως ἐς τὴν νόσον ἐπάγεται, μάλιστα δὲ μῖσος κατά τινος πολὺ ἢ φθόνος ἐπ’ ἐχθρῷ εὐτυχοῦντι ἢ λύπη τις ἢ ὀργή· κατ’ ὀλίγον ταῦτα ὑποτυφόμενα καὶ μακρῷ χρόνῳ ἐντρεφόμενα μανίαν ἀποτελεῖ.", "st": "52.30"}, {"sp": "N", "t": "τοιαῦτά σοι, ὦ πάτερ, καὶ ἡ γυνὴ πέπονθεν καὶ ἴσως τι λελύπηκεν αὐτὴν ἔναγχος· οὐδὲν γὰρ ἐκείνη ἐμίσει. πλὴν ἔχεταί γε καὶ οὐκ ἂν ἐκ τῶν παρόντων ὑπ’ ἰατροῦ θεραπευθῆναι δύναιτο· ὡς εἴ γε ἄλλος τις ὑπόσχοιτο, εἴ τις ἀπαλλάξειε, μίσει τότε ὡς ἀδικοῦντα ἐμέ. καὶ μὴν κἀκεῖνο, ὦ πάτερ, οὐκ ἂν ὀκνήσαιμι εἰπεῖν, ὅτι εἰ καὶ μὴ τελέως οὕτως ἀπέγνωστο, ἀλλά τις ἔτι σωτηρίας ἐλπὶς ὑπεφαίνετο, οὐκ ἂν οὐδὲ οὕτω ῥᾳδίως προσηψάμην οὐδ’ αὖ προχείρως φάρμακον ἐγχέαι ἐτόλμησα, δεδιὼς τὴν τύχην καὶ τὴν παρὰ τῶν πολλῶν δυσφημίαν. ὁρᾷς ὡς οἴονται πάντες εἶναί τι μῖσος πρὸς τοὺς προγόνους πάσαις μητρυιαῖς, κἂν ὦσι χρησταί, καί τινα κοινὴν μανίαν ταύτην γυναικείαν αὐτὰς μεμηνέναι. τάχ’ ἂν οὖν τις ὑπώπτευσεν, ἄλλως χωρήσαντος τοῦ κακοῦ καὶ τῶν φαρμάκων οὐ δυνηθέντων, κακοήθη καὶ δολερὰν τὴν θεραπείαν γεγονέναι.", "st": "52.31"}, {"sp": "N", "t": "καὶ τὰ μὲν τῆς γυναικός, ὦ πάτερ, οὕτως ἔχει, καὶ πάνυ σοι τετηρηκὼς λέγω — οὔ ποτε ῥᾷον ἕξει, κἂν μυριάκις πίῃ τοῦ φαρμάκου. διὰ τοῦτ’ ἐπιχειρεῖν οὐκ ἄξιον, εἰ μὴ πρὸς μόνον τὸ ἀποτυχεῖν με κατεπείγεις καὶ κακοδοξίᾳ περιβαλεῖν θέλεις. ἔασον ὑπὸ τῶν ὁμοτέχνων φθονεῖσθαι. ἐὰν δέ με ἀποκηρύξῃς πάλιν, ἐγὼ μὲν καίτοι πάντων ἔρημος γενόμενος οὐδὲν κατὰ σοῦ δεινὸν εὔξομαι· τί δ’ ἄν, ὅπερ μὴ γένοιτο, αὖθις ἡ νόσος ἐπανέλθῃ; φιλεῖ γάρ πως τὰ τοιαῦτα ἐρεθιζόμενα παλινδρομεῖν. τί με πρᾶξαι δεήσει; θεραπεύσω μὲν εὖ ἴσθι καὶ τότε καὶ οὔ ποτε λείψω τὴν τάξιν ἣν τοὺς παῖδας ἔταξεν ἡ φύσις, οὐδὲ τοῦ γένους τὸ ἐπ’ ἐμαυτῷ ἐπιλήσομαι. εἶτ’ ἂν σωφρονήσῃς, αὖθις ἀναλαμβάνειν πώποτε πιστεῦσαί με δεῖ; ὁρᾷς; ἤδη καὶ ταῦτα ποιῶν ἐπισπᾷ τὴν νόσον καὶ ὑπομιμνήσκεις τὸ πάθος. χθὲς καὶ πρῴην ἐκ τηλικούτων κακῶν ἀνασφήλας διατείνῃ καὶ βοᾷς, καὶ τὸ μέγιστον, ὀργίζῃ καὶ πρὸς μῖσος τρέπῃ καὶ τοὺς νόμους ἀνακαλεῖς. οἴμοι, πάτερ, ταῦτ’ ἦν σου καὶ τῆς πάλαι μανίας τὰ προοίμια.", "st": "52.32"}, {"sp": "HDR", "t": "Πῶς δεῖ Ἱστορίαν συγγράφειν"}, {"sp": "N", "t": "Ἀβδηρίταις φασὶ Λυσιμάχου ἤδη βασιλεύοντος ἐμπεσεῖν τι νόσημα, ὦ καλὲ Φίλων, τοιοῦτο· πυρέττειν μὲν γὰρ τὰ πρῶτα πανδημεὶ ἅπαντας ἀπὸ τῆς πρώτης εὐθὺς ἐρρωμένως καὶ λιπαρεῖ τῷ πυρετῷ, περὶ δὲ τὴν ἑβδόμην τοῖς μὲν αἷμα πολὺ ἐκ ῥινῶν ῥυέν, τοῖς δ’ ἱδρὼς ἐπιγενόμενος, πολὺς καὶ οὗτος, ἔλυσε τὸν πυρετόν. ἐς γελοῖον δέ τι πάθος περιίστα τὰς γνώμας αὐτῶν· ἅπαντες γὰρ ἐς τραγῳδίαν παρεκίνουν καὶ ἰαμβεῖα ἐφθέγγοντο καὶ μέγα ἐβόων, μάλιστα δὲ τὴν Εὐριπίδου Ἀνδρομέδαν ἐμονῴδουν καὶ τὴν τοῦ Περσέως ῥῆσιν ἐν μέρει διεξῄεσαν, καὶ μεστὴ ἦν ἡ πόλις ὠχρῶν ἁπάντων καὶ λεπτῶν τῶν ἑβδομαίων ἐκείνων τραγῳδῶν,<br>σὺ δ’ ὦ θεῶν τύραννε κἀνθρώπων Ἔρως,<br>καὶ τὰ ἄλλα μεγάλῃ τῇ φωνῇ ἀναβοώντων καὶ τοῦτο ἐπὶ πολύ, ἄχρι δὴ χειμὼν καὶ κρύος δὲ μέγα γενόμενον ἔπαυσε ληροῦντας αὐτούς. αἰτίαν δέ μοι δοκεῖ τοῦ τοιούτου παρασχεῖν Ἀρχέλαος ὁ τραγῳδός, εὐδοκιμῶν τότε, μεσοῦντος θέρους ἐν πολλῷ τῷ φλογμῷ τραγῳδήσας αὐτοῖς τὴν Ἀνδρομέδαν, ὡς πυρέξαι τε ἀπὸ τοῦ θεάτρου τοὺς πολλοὺς καὶ ἀναστάντας ὕστερον ἐς τὴν τραγῳδίαν παρολισθαίνειν, ἐπὶ πολὺ ἐμφιλοχωρούσης τῆς Ἀνδρομέδας τῇ μνήμῃ αὐτῶν καὶ τοῦ Περσέως ἔτι σὺν τῇ Μεδούσῃ τὴν ἑκάστου γνώμην περιπετομένου.", "st": "53.1"}, {"sp": "N", "t": "ὡς οὖν ἕν, φασίν, ἑνὶ παραβαλεῖν, τὸ Ἀβδηριτικὸν έκεῖνο πάθος καὶ νῦν τοὺς πολλοὺς τῶν πεπαιδευμένων περιελήλυθεν, οὐχ ὥστε τραγῳδεῖν — ἔλαττον γὰρ ἂν τοῦτο παρέπαιον ἀλλοτρίοις ἰαμβείοις, οὐ φαύλοις κατεσχημένοι — ἀλλ’ ἀφ’ οὗ δὴ τὰ ἐν ποσὶ ταῦτα κεκίνηται, ὁ πόλεμος ὁ πρὸς τοὺς βαρβάρους καὶ τὸ ἐν Ἀρμενίᾳ τραῦμα καὶ αἱ συνεχεῖς νῖκαι, οὐδεὶς ὅστις οὐχ ἱστορίαν συγγράφει, μᾶλλον δὲ Θουκυδίδαι καὶ Ἡρόδοτοι καὶ Ξενοφῶντες ἡμῖν ἅπαντες, καὶ ὡς ἔοικεν, ἀληθὲς ἄρ’ ἦν ἐκεῖνο τό “πόλεμος ἁπάντων πατήρ”, εἴ γε καὶ συγγραφέας τοσούτους ἀνέφυσεν ὑπὸ μιᾷ τῇ ὁρμῇ.", "st": "53.2"}, {"sp": "N", "t": "ταῦτα τοίνυν, ὦ φιλότης, ὁρῶντα καὶ ἀκούοντά με τὸ τοῦ Σινωπέως ἐκεῖνο εἰσῆλθεν· ὁπότε γὰρ ὁ Φίλιππος ἐλέγετο ἤδη ἐπελαύνειν, οἱ Κορίνθιοι πάντες ἐταράττοντο καὶ ἐν ἔργῳ ἦσαν, ὁ μὲν ὅπλα ἐπισκευάζων, ὁ δὲ λίθους παραφέρων, ὁ δὲ ὑποικοδομῶν τοῦ τείχους, ὁ δὲ ἔπαλξιν ὑποστηρίζων, ὁ δὲ ἄλλος ἄλλο τι τῶν χρησίμων ὑπουργῶν. ὁ δὴ Διογένης ὁρῶν ταῦτα, ἐπεὶ μηδὲν εἶχεν ὅ τι καὶ πράττοι — οὐδεὶς γὰρ αὐτῷ ἐς οὐδὲν ἐχρῆτο — διαζωσάμενος τὸ τριβώνιον σπουδῇ μάλα καὶ αὐτὸς ἐκύλιε τὸν πίθον, ἐν ᾧ ἐτύγχανεν οἰκῶν, ἄνω καὶ κάτω τοῦ Κρανείου· καί τινος τῶν συνήθων ἐρομένου, Τί ταῦτα ποιεῖς, ὦ Διόγενες; Κυλίω, ἔφη, κἀγὼ τὸν πίθον, ὡς μὴ μόνος ἀργεῖν δοκοίην ἐν τοσούτοις ἐργαζομένοις.", "st": "53.3"}, {"sp": "N", "t": "καὐτὸς οὖν, ὦ Φίλων, ὡς μὴ μόνος ἄφωνος εἴην ἐν οὕτω πολυφώνῳ τῷ καιρῷ μηδ’ ὥσπερ κωμικὸν δορυφόρημα κεχηνὼς σιωπῇ παραφεροίμην, καλῶς ἔχειν ὑπέλαβον ὡς δυνατόν μοι κυλῖσαι τὸν πίθον, οὐχ ὡς ἱστορίαν συγγράφειν οὐδὲ πράξεις αὐτὰς διεξιέναι· οὐχ οὕτω μεγαλότολμος ἐγώ, μηδὲ τοῦτο δείσῃς περὶ ἐμοῦ· οἶδα γάρ, ἡλίκος ὁ κίνδυνος, εἰ κατὰ τῶν πετρῶν κυλίοι τις, καὶ μάλιστα οἷον τοὐμὸν τοῦτο πιθάκνιον οὐδὲ πάνυ καρτερῶς κεκεραμευμένον· δεήσει γὰρ αὐτίκα μάλα πρὸς μικρόν τι λιθίδιον προσπταίσαντα συλλέγειν τὰ ὄστρακα. τί οὖν ἔγνωσταί μοι καὶ πῶς ἀσφαλῶς μεθέξω τοῦ πολέμου, αὐτὸς ἔξω βέλους ἑστώς, ἐγώ σοι φράσω. “τούτου μὲν καπνοῦ καὶ κύματος” καὶ φροντίδων, ὅσαι τῷ συγγραφεῖ ἔνεισιν, ἀνέξω ἐμαυτὸν εὖ ποιῶν, παραίνεσιν δέ τινα μικρὰν καὶ ὑποθήκας ταύτας ὀλίγας ὑποθήσομαι τοῖς συγγράφουσιν, ὡς κοινωνήσαιμι αὐτοῖς τῆς οἰκοδο μίας, εἰ καὶ μὴ τῆς ἐπιγραφῆς, ἄκρῳ γε τῷ δακτύλῳ τοῦ πηλοῦ προσαψάμενος.", "st": "53.4"}, {"sp": "N", "t": "καίτοι οὐδὲ παραινέσεως οἱ πολλοὶ δεῖν οἴονται σφίσιν ἐπὶ τὸ πρᾶγμα, οὐ μᾶλλον ἢ τέχνης τινὸς ἐπὶ τὸ βαδίζειν ἢ βλέπειν ἢ ἐσθίειν, ἀλλὰ πάνυ ῥᾷστον καὶ πρόχειρον καὶ ἅπαντος εἶναι ἱστορίαν συγγράψαι, ἤν τις ἑρμηνεῦσαι τὸ ἐπελθὸν δύνηται· τὸ δὲ οἶσθά που καὶ αὐτός, ὦ ἑταῖρε, ὡς οὐ τῶν εὐμεταχειρίστων οὐδὲ ῥᾳθύμως συντεθῆναι δυναμένων τοῦτ’ ἐστίν, ἀλλά, εἴ τι ἐν λόγοις καὶ ἄλλο, πολλῆς τῆς φροντίδος δεόμενον, ἤν τις, ὡς ὁ Θουκυδίδης φησίν, ἐς ἀεὶ κτῆμα συντιθείη. οἶδα μὲν οὖν οὐ πάνυ πολλοὺς αὐτῶν ἐπιστρέψων, ἐνίοις δὲ καὶ πάνυ ἐπαχθὴς δόξων, καὶ μάλιστα ὁπόσοις ἀποτετέλεσται ἤδη καὶ ἐν τῷ κοινῷ δέδεικται ἡ ἱστορία. εἰ δὲ καὶ ἐπῄνηται ὑπὸ τῶν τότε ἀκροασαμένων, μανία ἥ γε ἐλπίς, ὡς οἱ τοιοῦτοι μεταποιήσουσιν ἢ μετεγγράψουσί τι τῶν ἅπαξ κεκυρωμένων καὶ ὥσπερ ἐς τὰς βασιλείους αὐλὰς ἀποκειμένων. ὅμως δὲ οὐ χεῖρον καὶ πρὸς αὐτοὺς ἐκείνους εἰρῆσθαι, ἵν’, εἴ ποτε πόλεμος ἄλλος συσταίη, ἢ Κελτοῖς πρὸς Γέτας ἢ Ἰνδοῖς πρὸς Βακτρίους —οὐ γὰρ πρὸς ἡμᾶς γε τολμήσειεν ἄν τις, ἁπάντων ἤδη κεχειρωμένων — ἔχωσιν ἄμεινον συντιθέναι τὸν κανόνα τοῦτον προσάγοντες, ἤνπερ γε δόξῃ αὐτοῖς ὀρθὸς εἶναι· εἰ δὲ μή, αὐτοὶ μὲν καὶ τότε τῷ αὐτῷ πήχει ὥσπερ καὶ νῦν μετρούντων τὸ πρᾶγμα· ὁ ἰατρὸς δὲ οὐ πάνυ ἀνιάσεται, ἢν πάντες Ἀβδηρῖται ἑκόντες Ἀνδρομέδαν τραγῳδῶσι.", "st": "53.5"}, {"sp": "N", "t": "Διττοῦ δὲ ὄντος τοῦ τῆς συμβουλῆς ἔργου, τὰ μεν γὰρ αἱρεῖσθαι, τὰ δὲ φεύγειν διδάσκει, φέρε πρῶτα εἴπωμεν ἅτινα φευκτέον τῷ ἱστορίαν συγγράφοντι καὶ ὧν μάλιστα καθαρευτέον, ἔπειτα οἷς χρώμενος οὐκ ἂν ἁμάρτοι τῆς ὀρθῆς καὶ ἐπ’ εὐθὺ ἀγούσης, ἀρχήν τε οἵαν αὐτῷ ἀρκτέον καὶ τάξιν ἥντινα τοῖς ἔργοις ἐφαρμοστέον καὶ μέτρον ἑκάστου καὶ ἃ σιωπητέον καὶ οἷς ἐνδιατριπτέον καὶ ὅσα παραδραμεῖν ἄμεινον καὶ ὅπως ἑρμηνεῦσαι αὐτὰ καὶ συναρμόσαι. ταῦτα μὲν καὶ τὰ τοιαῦτα ὕστερον· νῦν δὲ τὰς κακίας ἤδη εἴπωμεν, ὁπόσαι τοῖς φαύλως συγγράφουσι παρακολουθοῦσιν. ἃ μὲν οὖν κοινὰ πάντων λόγων ἐστὶν ἁμαρτήματα ἔν τε φωνῇ καὶ ἁρμονίᾳ καὶ διανοίᾳ καὶ τῇ ἄλλῃ ἀτεχνίᾳ, μακρόν τε ἂν εἴη ἐπελθεῖν καὶ τῆς παρούσης ὑποθέσεως οὐκ ἴδιον· κοινὰ γάρ, ὡς ἔφην, ἁπάντων λόγων ἐστὶν ἁμαρτήματα [ἔν τε φωνῇ καὶ ἁρμονίᾳ].", "st": "53.6"}, {"sp": "N", "t": "ἃ δ’ ἐν ἱστορίᾳ διαμαρτάνουσι, τὰ τοιαῦτα ἂν εὕροις ἐπιτηρῶν, οἷα κἀμοὶ πολλάκις ἀκροωμένῳ ἔδοξε, καὶ μάλιστα ἢν ἅπασιν αὐτοῖς ἀναπετάσῃς τὰ ὦτα. οὐκ ἄκαιρον δὲ μεταξὺ καὶ ἀπομνημονεῦσαι ἔνια παραδείγματος ἕνεκα τῶν ἤδη οὕτω συγγεγραμμένων, καὶ πρῶτόν γε ἐκεῖνο, ἡλίκον ἁμαρτάνουσιν, ἐπισκοπήσωμεν· ἀμελήσαντες γὰρ οἱ πολλοὶ αὐτῶν τοῦ ἱστορεῖν τὰ γεγενημένα τοῖς ἐπαίνοις ἀρχόντων καὶ στρατηγῶν ἐνδιατρίβουσι, τοὺς μὲν οἰκείους εἰς ὕψος ἐπαίροντες, τοὺς πολεμίους δὲ πέρα τοῦ μετρίου καταρρίπτοντες, ἀγνοοῦντες ὡς οὐ στενῷ τῷ ἰσθμῷ διώρισται καὶ διατετείχισται ἡ ἱστορία πρὸς τὸ ἐγκώμιον, ἀλλά τι μέγα τεῖχος ἐν μέσῳ ἐστὶν αὐτῶν καὶ τὸ τῶν μουσικῶν δὴ τοῦτο, δὶς διὰ πασῶν ἐστι πρὸς ἄλληλα, εἴ γε τῷ μὲν ἐγκωμιάζοντι μόνου ἑνὸς μέλει, ὁπωσοῦν ἐπαινέσαι καὶ εὐφρᾶναι τὸν ἐπαινούμενον, καὶ εἰ ψευσαμένῳ ὑπάρχει τυχεῖν τοῦ τέλους, ὀλίγον ἂν φροντίσειεν· ἡ δὲ οὐκ ἄν τι ψεῦδος ἐμπεσὸν ἡ ἱστορία, οὐδὲ ἀκαριαῖον ἀνάσχοιτο, οὐ μᾶλλον ἢ τὴν ἀρτηρίαν ἰατρῶν παῖδές φασι τὴν τραχεῖαν παραδέξασθαι ἄν τι ἐς αὐτὴν καταποθέν.", "st": "53.7"}, {"sp": "N", "t": "ἔτι ἀγνοεῖν ἐοίκασιν οἱ τοιοῦτοι ὡς ποιητικῆς μὲν καὶ ποιημάτων ἄλλαι ὑποσχέσεις καὶ κανόνες ἴδιοι, ἱστορίας δὲ ἄλλοι· ἐκεῖ μὲν γὰρ ἀκρατὴς ἡ ἐλευθερία καὶ νόμος εἷς, τὸ δόξαν τῷ ποιητῇ· ἔνθεος γὰρ καὶ κάτοχος ἐκ Μουσῶν, κἂν ἵππων ὑποπτέρων ἅρμα ζεύξασθαι ἐθέλῃ, κἂν ἐφ’ ὕδατος ἄλλους ἢ ἐπ’ ἀνθερίκων ἄκρων θευσομένους ἀναβιβάσηται, φθόνος οὐδείς, οὐδὲ ὁπόταν ὁ Ζεὺς αὐτῶν ἀπὸ μιᾶς σειρᾶς ἀνασπάσας αἰωρῇ ὁμοῦ γῆν καὶ θάλατταν, δεδίασι μὴ ἀπορραγείσης ἐκείνης συντριβῇ τὰ πάντα κατενεχθέντα· ἀλλὰ κἂν Ἀγαμέμνονα ἐπαινέσαι θέλωσιν, οὐδεὶς ὁ κωλύσων Διὶ μὲν αὐτὸν ὅμοιον εἶναι τὴν κεφαλὴν καὶ τὰ ὄμματα, τὸ στέρνον δὲ τῷ ἀδελφῷ αὐτοῦ τῷ Ποσειδῶνι, τὴν δὲ ζώνην τῷ Ἄρει, καὶ ὅλως σύνθετον ἐκ πάντων θεῶν γενέσθαι δεῖ τὸν Ἀτρέως καὶ Ἀερόπης· οὐ γὰρ ἱκανὸς ὁ Ζεὺς οὐδὲ ὁ Ποσειδῶν οὐδὲ ὁ Ἄρης μόνος ἕκαστος ἀναπληρῶσαι τὸ κάλλος αὐτοῦ. ἡ ἱστορία δὲ ἤν τινα κολακείαν τοιαύτην προσλάβῃ, τί ἄλλο ἢ πεζή τις ποιητικὴ γίγνεται, τῆς μεγαλοφωνίας μὲν ἐκείνης ἐστερημένη, τὴν λοιπὴν δὲ τερατείαν γυμνὴν τῶν μέτρων καὶ δι’ αὐτὸ ἐπισημοτέραν ἐκφαίνουσα; μέγα τοίνυν, μᾶλλον δὲ ὑπέρμεγα τοῦτο κακόν, εἰ μὴ εἰδείη τις χωρίζειν τὰ ἱστορίας καὶ τὰ ποιητικῆς, ἀλλ’ ἐπεισάγει τῇ ἱστορίᾳ τὰ τῆς ἑτέρας κομμώματα, τὸν μῦθον καὶ τὸ ἐγκώμιον καὶ τὰς ἐν τούτοις ὑπερβολάς, ὥσπερ ἂν εἴ τις ἀθλητὴν τῶν καρτερῶν τούτων καὶ κομιδῇ πρινίνων ἁλουργίσι περιβάλοι καὶ τῷ ἄλλῳ κόσμῳ τῷ ἑταιρικῷ καὶ φυκίον ἐντρίβοι καὶ ψιμύθιον τῷ προσώπῳ, Ἡράκλεις ὡς καταγέλαστον αὐτὸν ἀπεργάσαιτο αἰσχύνας τῷ κόσμῳ ἐκείνῳ.", "st": "53.8"}, {"sp": "N", "t": "καὶ οὐ τοῦτό φημι, ὡς οὐχὶ καὶ ἐπαινετέον ἐν ἱστορίᾳ ἐνίοτε· ἀλλ’ ἐν καιρῷ τῷ προσήκοντι ἐπαινετέον καὶ μέτρον ἐπακτέον τῷ πράγματι, τὸ μὴ ἐπαχθὲς τοῖς ὕστερον ἀναγνωσομένοις αὐτά, καὶ ὅλως πρὸς τὰ ἔπειτα κανονιστέον τὰ τοιαῦτα, ἅπερ μικρὸν ὕστερον ἐπιδείξομεν. οἵ δὲ οἴονται καλῶς διαιρεῖν ἐς δύο τὴν ἱστορίαν, εἰς τὸ τερπνὸν καὶ χρήσιμον, καὶ διὰ τοῦτο εἰσποιοῦσι καὶ τὸ ἐγκώμιον ἐς αὐτὴν ὡς τερπνὸν καὶ εὐφραῖνον τοὺς ἐντυγχάνοντας, ὁρᾷς ὅσον τἀληθοῦς ἡμαρτήκασι; πρῶτον μὲν κιβδήλῳ τῇ διαιρέσει χρώμενοι· ἓν γὰρ ἔργον ἱστορίας καὶ τέλος, τὸ χρήσιμον, ὅπερ ἐκ τοῦ ἀληθοῦς μόνου συνάγεται. τὸ τερπνὸν δὲ ἄμεινον μὲν εἰ καὶ αὐτὸ παρακολουθήσειεν, ὥσπερ καὶ κάλλος ἀθλητῇ, εἰ δὲ μή, οὐδὲν κωλύσει ἀφ’ Ἡρακλέους γενέσθαι καὶ Νικόστρατον Ἰσιδότου, γεννάδαν ὄντα καὶ τῶν ἀνταγωνιστῶν ἑκατέρων ἀλκιμώτερον, εἰ αὐτὸς μὲν αἴσχιστος ὀφθῆναι εἴη τὴν ὄψιν, Ἀλκαῖος δὲ ὁ καλὸς ὁ Μιλήσιος ἀνταγωνίζοιτο αὐτῷ, καὶ ἐρώμενος, ὥς φασι, τοῦ Νικοστράτου ὤν. καὶ τοίνυν ἡ ἱστορία, εἰ μὲν ἄλλως τὸ τερπνὸν παρεμπορεύσαιτο, πολλοὺς ἂν τοὺς ἐραστὰς ἐπισπάσαιτο, ἄχρι δ’ ἂν καὶ μόνον ἔχῃ τὸ ἴδιον ἐντελές, λέγω δὲ τὴν τῆς ἀληθείας δήλωσιν, ὀλίγον τοῦ κάλλους φροντιεῖ.", "st": "53.9"}, {"sp": "N", "t": "ἔτι κἀκεῖνο εἰπεῖν ἄξιον, ὅτι οὐδὲ τερπνὸν ἐν αὐτῇ τὸ κομιδῇ μυθῶδες καὶ τὸ τῶν ἐπαίνων μάλιστα πρόσαντες παρ’ ἑκάτερον τοῖς ἀκούουσιν, ἢν μὴ τὸν συρφετὸν καὶ τὸν πολὺν δῆμον ἐπινοῇς, ἀλλὰ τοὺς δικαστικῶς καὶ νὴ Δία συκοφαντικῶς προσέτι γε ἀκροασομένους, οὓς οὐκ ἄν τι λάθοι παραδραμόν, ὀξύτερον μὲν τοῦ Ἄργου ὁρῶντας καὶ πανταχόθεν τοῦ σώματος, ἀργυραμοιβικῶς δὲ τῶν λεγομένων ἕκαστα ἐξετάζοντας, ὡς τὰ μὲν παρακεκομμένα εὐθὺς ἀπορρίπτειν, παραδέχεσθαι δὲ τὰ δόκιμα καὶ ἔννομα καὶ ἀκριβῆ τὸν τύπον, πρὸς οὓς ἀποβλέποντα χρὴ συγγράφειν, τῶν δὲ ἄλλων ὀλίγον φροντίζειν, κἂν διαρραγῶσιν ἐπαινοῦντες. ἢν δὲ ἀμελήσας ἐκείνων ἡδύνῃς πέρα τοῦ μετρίου τὴν ἱστορίαν μύθοις καὶ ἐπαίνοις καὶ τῇ ἄλλῃ θωπείᾳ, τάχιστ’ ἂν ὁμοίαν αὐτὴν ἐξεργάσαιο τῷ ἐν Λυδίᾳ Ἡρακλεῖ· ἑωρακέναι γάρ σέ που εἰ κὸς γεγραμμένον, τῇ Ὀμφάλῃ δουλεύοντα, πάνυ ἀλλόκοτον σκευὴν ἐσκευασμένον, ἐκείνην μὲν τὸν λέοντα αὐτοῦ περιβεβλημένην καὶ τὸ ξύλον ἐν τῇ χειρὶ ἔχουσαν, ὡς Ἡρακλέα δῆθεν οὖσαν, αὐτὸν δὲ ἐν κροκωτῷ καὶ πορφυρίδι ἔρια ξαίνοντα καὶ παιόμενον ὑπὸ τῆς Ὀμφάλης τῷ σανδαλίῳ· καὶ τὸ θέαμα αἴσχιστον, ἀφεστῶσα ἡ ἐσθὴς τοῦ σώματος καὶ μὴ προσιζάνουσα καὶ τοῦ θεοῦ τὸ ἀνδρῶδες ἀσχημόνως καταθηλυνόμενον.", "st": "53.10"}, {"sp": "N", "t": "καὶ οἱ μὲν πολλοὶ ἴσως καὶ ταῦτά σου ἐπαινέσονται, οἱ ὀλίγοι δὲ ἐκεῖνοι, ὧν σὺ καταφρονεῖς, μάλα ἡδὺ καὶ ἐς κόρον γελάσονται, ὁρῶντες τὸ ἀσύμφυλον καὶ ἀνάρμοστον καὶ δυσκόλλητον τοῦ πράγματος. ἑκάστου γὰρ δὴ ἴδιόν τι καλόν ἐστιν· εἰ δὲ τοῦτο ἐναλλάξειας, ἀκαλλὲς τὸ αὐτὸ παρὰ τὴν χρῆσιν γίγνεται. ἐῶ λέγειν ὅτι οἱ ἔπαινοι ἑνὶ μὲν ἴσως τερπνοί, τῷ ἐπαινουμένῳ, τοῖς δ’ ἄλλοις ἐπαχθεῖς, καὶ μάλιστα ἢν ὑπερφυεῖς τὰς ὑπερβολὰς ἔχωσιν, οἵους αὐτοὺς οἱ πολλοὶ ἀπεργάζονται, τὴν εὔνοιαν τὴν παρὰ τῶν ἐπαινουμένων θηρώμενοι καὶ ἐνδιατρίβοντες ἄχρι τοῦ πᾶσι προφανῆ τὴν κολακείαν ἐξεργάσασθαι· οὐδὲ γὰρ κατὰ τέχνην αὐτὸ δρᾶν ἴσασιν οὐδ’ ἐπισκιάζουσι τὴν θωπείαν, ἀλλ’ ἐμπεσόντες ἀθρόα πάντα καὶ ἀπίθανα καὶ γυμνὰ διεξίασιν.", "st": "53.11"}, {"sp": "N", "t": "ὥστ’ οὐδὲ τυγχάνουσιν οὗ μάλιστα ἐφίενται· οἱ γὰρ ἐπαινούμενοι πρὸς αὐτῶν μισοῦσι μᾶλλον καὶ ἀποστρέφονται ὡς κόλακας, εὖ ποιοῦντες, καὶ μάλιστα ἢν ἀνδρώδεις τὰς γνώμας ὦσιν· ὥσπερ Ἀριστόβουλος μονομαχίαν γράψας Ἀλεξάνδρου καὶ Πώρου, καὶ ἀναγνόντος αὐτῷ τοῦτο μάλιστα τὸ χωρίον τῆς γραφῆς — ᾤετο γὰρ χαριεῖσθαι τὰ μέγιστα τῷ βασιλεῖ ἐπιψευδομενος ἀριστείας τινὰς αὐτῷ καὶ ἀναπλάττων ἔργα μείζω τῆς ἀληθείας — λαβὼν ἐκεῖνος τὸ βιβλίον — πλέοντες δὲ ἐτύγχανον ἐν τῷ ποταμῷ τῷ Ὑδάσπῃ — ἔρριψεν ἐπὶ κεφαλὴν ἐς τὸ ὕδωρ ἐπειπών, Καὶ σὲ δὲ οὕτως ἐχρῆν, ὦ Ἀριστόβουλε, τοιαῦτα ὑπὲρ ἐμοῦ μονομαχοῦντα καὶ ἐλέφαντας ἑνὶ ἀκοντίῳ φονεύοντα. καὶ ἔμελλέ γε οὕτως ἀγανακτήσειν ὁ Ἀλέξανδρος, ὅς γε οὐδὲ τὴν τοῦ ἀρχιτέκτονος τόλμαν ἠνέσχετο, ὑποσχομένου τὸν Ἄθω εἰκόνα ποιήσειν αὐτοῦ καὶ μετακοσμήσειν τὸ ὄρος εἰς ὁμοιότητα τοῦ βασιλέως, ἀλλὰ κόλακα εὐθὺς ἐπιγνοὺς τὸν ἄνθρωπον οὐκέτ’ οὐδ’ ἐς τὰ ἄλλα ὁμοίως ἐχρῆτο.", "st": "53.12"}, {"sp": "N", "t": "ποῦ τοίνυν τὸ τερπνὸν ἐν τούτοις, ἐκτὸς εἰ μή τις κομιδῇ ἀνόητος εἴη, ὡς χαίρειν τὰ τοιαῦτα ἐπαινούμενος, ὧν παρὰ πόδας οἱ ἔλεγχοι; ὥσπερ οἱ ἄμορφοι τῶν ἀνθρώπων, καὶ μάλιστά γε τὰ γύναια τοῖς γραφεῦσι παρακελευόμενα ὡς καλλίστας αὐτὰς γράφειν· οἴονται γὰρ ἄμεινον ἕξειν τὴν ὄψιν, ἢν ὁ γραφεὺς αὐταῖς ἐρύθημά τε πλεῖον ἐπανθίσῃ καὶ τὸ λευκὸν ἐγκαταμίξῃ πολὺ τῷ φαρμάκῳ. τοιοῦτοι τῶν συγγραφόντων οἱ πολλοί εἰσι τὸ τήμερον καὶ τὸ ἴδιον καὶ τὸ χρειῶδες, ὅ τι ἂν ἐκ τῆς ἱστορίας ἐλπίσωσι, θεραπεύοντες, οὓς μισεῖσθαι καλῶς εἶχεν, ἐς μὲν τὸ παρὸν κόλακας προδήλους καὶ ἀτέχνους ὄντας, ἐς τοὐπιὸν δὲ ὕποπτον ταῖς ὑπερβολαῖς τὴν ὅλην πραγματείαν ἀποφαίνοντας. εἰ δέ τις πάντως τὸ τερπνὸν ἡγεῖται καταμεμῖχθαι δεῖν τῇ ἱστορίᾳ πάσῃ, ἀλλὰ ἃ σὺν ἀληθείᾳ τερπνά ἐστιν ἐν τοῖς ἄλλοις κάλλεσι τοῦ λόγου, ὧν ἀμελήσαντες οἱ πολλοὶ τὰ μηδὲν προσήκοντα ἐπεισκυκλοῦσιν.", "st": "53.13"}, {"sp": "N", "t": "ἐγὼ δ’ οὖν καὶ διηγήσομαι ὁπόσα μέμνημαι ἔναγχος ἐν Ἰωνίᾳ συγγραφέων τινῶν, καὶ νὴ Δία ἐν Ἀχαΐα πρῴην ἀκούσας τὸν αὐτὸν τοῦτον πόλεμον διηγουμένων· καὶ πρὸς Χαρίτων μηδεὶς ἀπιστήσῃ τοῖς λεχθησομένοις· ὅτι γὰρ ἀληθῆ ἐστι κἂν ἐπωμοσάμην, εἰ ἀστεῖον ἦν ὅρκον ἐντιθέναι συγγράμματι. εἷς μέν τις αὐτῶν ἀπὸ Μουσῶν εὐθὺς ἤρξατο παρακαλῶν τὰς θεὰς συνεφάψασθαι τοῦ συγγράμματος. ὁρᾷς ὡς ἐμμελὴς ἡ ἀρχὴ καὶ περὶ πόδα τῇ ἱστορίᾳ καὶ τῷ τοιούτῳ εῖδει τῶν λόγων πρέπουσα; εἶτα μικρὸν ὑποβὰς Ἀχιλλεῖ μὲν τὸν ἡμέτερον ἄρχοντα εἴκαζε, Θερσίτῃ δὲ τὸν τῶν Περσῶν βασιλέα, οὐκ εἰδὼς ὅτι ὁ Ἀχιλλεὺς ἀμείνων ἦν αὐτῷ, εἰ Ἕκτορα μᾶλλον ἢ Θερσίτην καθῄρει, καὶ εἰ πρόσθεν μὲν ἔφευγεν ἐσθλός τις,<br>ἐδίωκε δέ μιν μέγ’ ἀμείνων.<br>εἶτ’ ἐπῆγεν ὑπὲρ αὐτοῦ τι ἐγκώμιον, καὶ ὡς ἄξιος εἴη συγγράψαι τὰς πράξεις οὕτω λαμπρὰς οὔσας. ἤδη δὲ κατιὼν ἐπῄνει καὶ τὴν πατρίδα τὴν Μίλητον, προστιθεὶς ὡς ἄμεινον ποιοῖ τοῦτο τοῦ Ὁμήρου μηδὲν μνησθέντος τῆς πατρίδος. εἶτ’ ἐπὶ τέλει τοῦ φροιμίου ὑπισχνεῖτο διαρρήδην καὶ σαφῶς, ἐπὶ μεῖζον μὲν αἴρειν τὰ ἡμέτερα, τοὺς βαρβάρους δὲ καταπολεμήσειν καὶ αὐτός, ὡς ἂν δύνηται· καὶ ἤρξατό γε τῆς ἱστορίας οὕτως, αἴτια ἅμα τῆς τοῦ πολέμου ἀρχῆς διεξιών· “ὁ γὰρ μιαρώτατος καὶ κάκιστα ἀπολούμενος Οὐολόγεσος ἤρξατο πολεμεῖν δι’ αἰτίαν τοιάνδε.”", "st": "53.14"}, {"sp": "N", "t": "οὗτος μὲν τοιαῦτα. ἕτερος δὲ Θουκυδίδου ζηλωτὴς ἄκρος, οἷος εὖ μάλα τῷ ἀρχετύπῳ εἰκασμένος, καὶ τὴν ἀρχὴν ὡς ἐκεῖνος σὺν τῷ ἑαυτοῦ ὀνόματι ἤρξατο, χαριεστάτην ἀρχῶν ἁπασῶν καὶ θύμου τοῦ Ἀττικοῦ ἀποπνέουσαν. ὅρα γάρ· “Κρεπέρῃος Καλπουρνιανὸς Πομπηϊουπολίτης συνέγραψε τὸν πόλεμον τῶν Παρθυαίων καὶ Ῥωμαίων, ὡς ἐπολέμησαν πρὸς ἀλλήλους, ἀρξάμενος εὐθὺς ξυνισταμένου.” ὥστε μετά γε τοιαύτην ἀρχὴν τί ἄν σοι τὰ λοιπὰ λέγοιμι, ὁποῖα ἐν Ἀρμενίᾳ ἐδημηγόρησε τὸν Κερκυραῖον αὐτὸν ῥήτορα παραστησάμενος, ἢ οἷον Νισιβηνοῖς λοιμὸν τοῖς μὴ τὰ Ῥωμαίων αἱρουμένοις ἐπήγαγε παρὰ Θουκυδίδου χρησάμενος ὅλον ἄρδην πλὴν μόνου τοῦ Πελασγικοῦ καὶ τῶν τειχῶν τῶν μακρῶν, ἐν οἷς οἱ τότε λοιμώξαντες ᾤκησαν; τὰ δ’ ἄλλα καὶ ἀπὸ Αἰθιοπίας ἤρξατο, ὥστε καὶ ἐς Αἴγυπτον κατέβη καὶ ἐς τὴν βασιλέως γῆν τὴν πολλήν, καὶ ἐν ἐκείνῃ γε ἔμεινεν εὖ ποιῶν. ἐγὼ γοῦν θάπτοντα ἔτι αὐτὸν καταλιπὼν τοὺς ἀθλίους Ἀθηναίους ἐν Νισίβι ἀπῆλθον ἀκριβῶς εἰδὼς καὶ ὅσα ἀπελθόντος ἐρεῖν ἔμελλε. καὶ γὰρ αὖ καὶ τοῦτο ἐπιεικῶς πολὺ νῦν ἐστι, τὸ οἴεσθαι τοῦτ’ εἶναι τοῖς Θουκυδίδου ἐοικότα λέγειν, εἰ ὀλίγον ἐντρέψας τὰ αὐτοῦ ἐκείνου λέγοι τις, μικρὰ ῥάκια, ὅπως καὶ αὐτὸς ἂν φαίης, οὐ δι’ αὐτήν. νὴ Δία κἀκεῖνο ὀλίγου δεῖν παρέλιπον· ὁ γὰρ αὐτὸς οὗτος συγγραφεὺς πολλὰ καὶ τῶν ὅπλων καὶ τῶν μηχανημάτων, ὡς Ῥωμαῖοι αὐτὰ ὀνομάζουσιν, οὕτως ἀνέγραψε, καὶ τάφρον ὡς ἐκεῖνοι καὶ γέφυραν καὶ τὰ τοιαῦτα. καί μοι ἐννόησον ἡλίκον τὸ ἀξίωμα τῆς ἱστορίας καὶ ὡς Θουκυδίδῃ πρέπον, μεταξὺ τῶν Ἀττικῶν ὀνομάτων τὰ Ἰταλιωτικὰ ταῦτα ἐγκεῖσθαι, ὥσπερ τὴν πορφύραν ἐπικοσμοῦντα καὶ ἐμπρέποντα καὶ πάντως συνᾴδοντα.", "st": "53.15"}, {"sp": "N", "t": "ἄλλος δέ τις αὐτῶν ὑπόμνημα τῶν γεγονότων γυμνὸν συναγαγὼν ἐν γραφῇ κομιδῇ πεζὸν καὶ χαμαιπετές, οἷον καὶ στρατιώτης ἄν τις τὰ καθ’ ἡμέραν ἀπογραφόμενος συνέθηκεν ἢ τέκτων ἢ κάπηλός τις συμπερινοστῶν τῇ στρατιᾷ. πλὴν ἀλλὰ μετριώτερός γε ὁ ἰδιώτης οὗτος ἦν, αὐτὸς μὲν αὐτίκα δῆλος ὢν οἷος ἦν, ἄλλῳ δέ τινι χαρίεντι καὶ δυνησομένῳ ἱστορίαν μεταχειρίσασθαι προπεπονηκώς. τοῦτο μόνον ᾐτιασάμην αὐτοῦ, ὅτι οὕτως ἐπέγραψε τὰ βιβλία τραγικώτερον ἢ κατὰ τὴν τῶν συγγραμμάτων τύχην· “Καλλιμόρφου ἰατροῦ τῆς τῶν κοντοφόρων ἕκτης ἱστοριῶν Παρθικῶν·” καὶ ὑπεγέγραπτο ἑκάστῃ ὁ ἀριθμός. καὶ νὴ Δία καὶ τὸ προοίμιον ὑπέρψυχρον ἐποίησεν οὕτως συναγαγών· οἰκεῖον εἶναι ἰατρῷ ἱστορίαν συγγράφειν, εἴ γε ὁ Ἀσκληπιὸς μὲν Ἀπόλλωνος υἱός, Ἀπόλλων δὲ Μουσηγέτης καὶ πάσης παιδείας ἄρχων· καὶ ὅτι ἀρξάμενος ἐν τῇ Ἰάδι γράφειν οὐκ οἶδα ὅ τι δόξαν αὐτίκα μάλα ἐπὶ τὴν κοινὴν μετῆλθεν, ἰητρείην μὲν λέγων καὶ πείρην καὶ ὁκόσα καὶ νοῦσοι, τὰ δ’ ἄλλα ὁμοδίαιτα τοῖς πολλοῖς καὶ τὰ πλεῖστα οἷα ἐκ τριόδου.", "st": "53.16"}, {"sp": "N", "t": "εἰ δέ με δεῖ καὶ σοφοῦ ἀνδρὸς μνησθῆναι, τὸ μὲν ὄνομα ἐν ἀφανεῖ κείσθω, τὴν γνώμην δὲ ἐρῶ καὶ τὰ πρῴην ἐν Κορίνθῳ συγγράμματα, κρείττω πάσης ἐλπίδος· ἐν ἀρχῇ μὲν γὰρ εὐθὺς ἐν τῇ πρώτῃ τοῦ φροιμίου περιόδῳ συνηρώτησε τοὺς ἀναγινώσκοντας λόγον πάνσοφον δεῖξαι σπεύδων, ὡς μόνῳ ἂν τῷ σοφῷ πρέποι ἱστορίαν συγγράφειν. εἶτα μετὰ μικρὸν ἄλλος συλλογισμός, εἶτα ἄλλος· καὶ ὅλως ἐν ἅπαντι σχήματι συνηρώτητο αὐτῷ τὸ προοίμιον. τὸ τῆς κολακείας ἐς κόρον, καὶ τὰ ἐγκώμια φορτικὰ καὶ κομιδῇ βωμολοχικά, οὐκ ἀσυλλόγιστα μέντοι, ἀλλὰ συνηρωτημένα κἀκεῖνα. καὶ μὴν κἀκεῖνο φορτικὸν ἔδοξέ μοι καὶ ἥκιστα σοφῷ ἀνδρὶ καὶ πώγωνι πολιῷ καὶ βαθεῖ πρέπον, τὸ ἐν τῷ προοιμίῳ εἰπεῖν, ὡς ἐξαίρετον τοῦτο ἕξει ὁ ἡμέτερος ἄρχων, οὗ γε τὰς πράξεις καὶ φιλόσοφοι ἤδη συγγράφειν ἀξιοῦσι· τὸ γὰρ τοιοῦτον, εἴπερ ἄρα, ἡμῖν ἔδει καταλιπεῖν λογίζεσθαι ἢ αὐτὸν εἰπεῖν.", "st": "53.17"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκείνου ὅσιον ἀμνημονῆσαι, ὃς τοιάνδε ἀρχὴν ἤρξατο· “ἔρχομαι ἐρέων περὶ Ῥωμαίων καὶ Περσέων,” καὶ μικρὸν ὕστερον· “ἔδεε γὰρ Πέρσῃσι γενέσθαι κακῶς”, καὶ πάλιν· “ἦν Ὀσρόης, τὸν οἱ Ἕλληνες Ὀξυρόην ὀνυμέουσι”, καὶ ἄλλα πολλὰ τοιαῦτα. ὁρᾷς; ὅμοιος αὐτὸς ἐκείνῳ, παρ’ ὅσον ὁ μὲν Θουκυδίδῃ, οὗτος δὲ Ἡροδότῳ εὖ μάλα ἐῴκει.", "st": "53.18"}, {"sp": "N", "t": "ἄλλος τις ἀοίδιμος ἐπὶ λόγων δυνάμει Θουκυδίδῃ καὶ αὐτὸς ὅμοιος ἢ ὀλίγῳ ἀμεινων αὐτοῦ, πάσας πόλεις καὶ πάντα ὄρη καὶ πεδία καὶ ποταμοὺς ἑρμηνεύσας πρὸς τὸ σαφέστατον καὶ ἰσχυρότατον, ὡς ᾤετο· τὸ δὲ ἐς ἐχθρῶν κεφαλὰς ὁ ἀλεξίκακος τρέψειε· τοσαύτη ψυχρότης ἐνῆν ὑπὲρ τὴν Κασπίαν χιό, να καὶ τὸν κρύσταλλον τὸν Κελτικόν. ἡ γοῦν ἀσπὶς ἡ τοῦ αὐτοκράτορος ὅλῳ βιβλίῳ μόγις ἐξηρμηνεύθη αὐτῷ, καὶ Γοργὼν ἐπὶ τοῦ ὀμφαλοῦ καὶ οἱ ὀφθαλμοὶ αὐτῆς ἐκ κυανοῦ καὶ λευκοῦ καὶ μέλανος καὶ ζώνη ἰριοειδὴς καὶ δράκοντες ἑλικηδὸν καὶ βοστρυχηδόν. ἡ μὲν γὰρ Οὐολογέσου ἀναξυρὶς ἢ ὁ χαλινὸς τοῦ ἵππου, Ἡράκλεις, ὅσαι μυριάδες ἐπῶν ἕκαστον τούτων, καὶ οἵα ἦν ἡ Ὀσρόου κόμη, διανέοντος τὸν Τίγρητα, καὶ ἐς οἷον ἄντρον κατέφυγε, κιττοῦ καὶ μυρρίνης καὶ δάφνης ἐς ταὐτὸ συμπεφυκότων καὶ σύσκιον ἀκριβῶς ποιούντων αὐτό. σκόπει ὡς ἀναγκαῖα τῇ ἱστορίᾳ ταῦτα, καὶ ὧν ἄνευ οὐκ ἂν ᾔδειμέν τι τῶν ἐκεῖ πραχθέντων.", "st": "53.19"}, {"sp": "N", "t": "ὑπὸ γὰρ ἀσθενείας τῆς ἐν τοῖς χρησίμοις ἢ ἀγνοίας τῶν λεκτέων ἐπὶ τὰς τοιαύτας τῶν χωρίων καὶ ἄντρων ἐκφράσεις τρέπονται, καὶ ὁπόταν ἐς πολλὰ καὶ μεγάλα πράγματα ἐμπέσωσιν, ἐοίκασιν οἰκέτῃ νεοπλούτῳ, ἄρτι κληρονομήσαντι τοῦ δεσπότου, ὃς οὔτε τὴν ἐσθῆτα οἶδεν ὡς χρὴ περιβαλέσθαι οὔτε δειπνῆσαι κατὰ νόμον, ἀλλ’ ἐμπηδήσας, πολλάκις ὀρνίθων καὶ συείων καὶ λαγῴων προκειμένων, ὑπερεμπίπλαται ἔτνους τινὸς ἢ ταρίχους, ἔστ’ ἂν διαρραγῇ ἐσθίων. οὗτος δ’ οὖν, ὃν προεῖπον, καὶ τραύματα συνέγραψε πάνυ ἀπίθανα καὶ θανάτους ἀλλοκότους, ὡς εἰς δάκτυλον τοῦ ποδὸς τὸν μέγαν τρωθείς τις αὐτίκα ἐτελεύτησε, καὶ ὡς ἐμβοήσαντος μόνον Πρίσκου τοῦ στρατηγοῦ ἑπτὰ καὶ εἴκοσι τῶν πολεμίων ἐξέθανον. ἔτι δὲ καὶ ἐν τῷ τῶν νεκρῶν ἀριθμῷ, τοῦτο μὲν καὶ παρὰ τὰ γεγραμμένα ἐν ταῖς τῶν ἀρχόντων ἐπιστολαῖς ἐψεύσατο· ἐπὶ γὰρ Εὐρώπῳ τῶν μὲν πολεμίων ἀποθανεῖν μυριάδας ἑπτὰ καὶ τριάκοντα καὶ ἓξ πρὸς τοῖς διακοσίοις, Ῥωμαίων δὲ μόνους δύο, καὶ τραυματίας γενέσθαι ἐννέα. ταῦτα οὐκ οἶδα εἴ τις ἂν εὖ φρονῶν ἀνάσχοιτο.", "st": "53.20"}, {"sp": "N", "t": "καὶ μὴν κἀκεῖνο λεκτέον, οὐ μικρὸν ὄν· ὑπὸ γὰρ τοῦ κομιδῇ Ἀττικὸς εἶναι καὶ ἀποκεκαθάρθαι τὴν φωνὴν ἐς τὸ ἀκριβέστατον ἠξίωσεν οὗτος καὶ τὰ ὀνόματα μεταποιῆσαι τὰ Ρωμαίων καὶ μετεγγράψαι ἐς τὸ Ἑλληνικόν, ὡς Κρόνιον μὲν Σατουρνῖνον λέγειν, Φρόντιν δὲ τὸν Φρόντωνα, Τιτάνιον δὲ τὸν Τιτιανὸν καὶ ἄλλα πολλῷ γελοιότερα. ἔτι ὁ αὐτὸς οὗτος περὶ τῆς Σευηριανοῦ τελευτῆς ἔγραψεν ὡς οἱ μὲν ἄλλοι ἅπαντες ἐξηπάτηνται οἰόμενοι ξίφει τεθνάναι αὐτόν, ἀποθάνοι δὲ ὁ ἀνὴρ σιτίων ἀποσχόμενος· τοῦτον γὰρ αὐτῷ ἀλυπότατον δόξαι τὸν θάνατον· οὐκ εἰδὼς ὅτι τὸ μὲν πάθος ἐκεῖνο πᾶν τριῶν οἶμαι ἡμερῶν ἐγένετο, ἀπόσιτοι δὲ καὶ ἐς ἑβδόμην διαρκοῦσιν οἱ πολλοί, ἐκτὸς εἰ μὴ τοῦθ’ ὑπολάβοι τις, ὡς Ὀσρόης τις εἱστήκει περιμένων, ἔστ’ ἂν Σευηριανὸς λιμῷ ἀπόληται, καὶ διὰ τοῦτο οὐκ ἐπῆγε διὰ τῆς ἑβδόμης.", "st": "53.21"}, {"sp": "N", "t": "τοὺς δὲ καὶ ποιητικοῖς ὀνόμασιν, ὦ καλὲ Φίλων, ἐν ἱστορίᾳ χρωμένους ποῦ δ’ ἄν τις θείη, τοὺς λέγοντας, “ἐλέλιξε μὲν ἡ μηχανή, τὸ τεῖχος δὲ πεσὸν μεγάλως ἐδούπησε,” καὶ πάλιν ἐν ἑτέρῳ μέρει τῆς καλῆς ἱστορίας· “Ἔδεσσα μὲν δὴ οὕτω τοῖς ὅπλοις περιεσμαραγεῖτο καὶ ὄτοβος ἦν καὶ κόναβος ἅπαντα ἐκεῖνα,” καὶ “ὁ στρατηγὸς ἐμερμήριζεν ᾧ τρόπῳ μάλιστα προσαγάγοι πρὸς τὸ τεῖχος.” εἶτα μεταξὺ οὕτως εὐτελῆ ὀνόματα καὶ δημοτικὰ καὶ πτωχικὰ πολλὰ παρενεβέβυστο, τό “ἐπέστειλεν ὁ στρατοπεδάρχης τῷ κυρίῳ,” καί “οἱ στρατιῶται ἠγόραζον τὰ ἐγχρῄζοντα,” καί “ἤδη λελουμένοι περὶ αὐτοὺς ἐγίγνοντο,” καὶ τὰ τοιαῦτα· ὥστε τὸ πρᾶγμα ἐοικὸς εἶναι τραγῳδῷ τὸν ἕτερον μὲν πόδα ἐπ’ ἐμβάτου ὑψηλοῦ βεβηκότι, θάτερον δὲ σανδάλῳ ὑποδεδεμένῳ.", "st": "53.22"}, {"sp": "N", "t": "καὶ μὴν καὶ ἄλλους ἴδοις ἂν τὰ μὲν προοίμια λαμπρὰ καὶ τραγικὰ καὶ εἰς ὑπερβολὴν μακρὰ συγγράφοντας, ὡς ἐλπίσαι θαυμαστὰ ἡλίκα τὰ μετὰ ταῦτα πάντως ἀκούσεσθαι, τὸ σῶμα δὲ αὐτὸ τὸ τῆς ἱστορίας μικρόν τι καὶ ἀγεννὲς ἐπαγαγόντας, ὡς καὶ τοῦτο ἐοικέναι παιδίῳ, εἴ που Ἔρωτα εἶδες παίζοντα, προσωπεῖον Ἡρακλέους πάμμεγα ἢ Τιτᾶνος περικείμενον· εὐθὺς γοῦν οἱ ἀκούσαντες ἐπιφθέγγονται αὐτοῖς τό, Ὤδινεν ὄρος. χρὴ δὲ οἶμαι μὴ οὕτως, ἀλλ’ ὅμοια τὰ πάντα καὶ ὁμόχροα εἶναι καὶ συνᾷδον τῇ κεφαλῇ τὸ ἄλλο σῶμα, ὡς μὴ χρυσοῦν μὲν τὸ κράνος εἴη, θώραξ δὲ πάνυ γελοῖος ἐκ ῥακῶν ποθεν ἢ ἐκ δερμάτων σαπρῶν συγκεκαττυμένος καὶ ἡ ἀσπὶς οἰσυΐνη καὶ χοιρίνη περὶ ταῖς κνήμαις. ἴδοις γὰρ ἂν ἀφθόνους τοιούτους συγγραφέας, τοῦ Ῥοδίου κολοσσοῦ τὴν κεφαλὴν ναννώδει σώματι ἐπιτιθέντας· ἄλλους αὖ ἔμπαλιν ἀκέφαλα τὰ σώματα εἰσάγοντας, ἀπροοιμίαστα καὶ εὐθὺς ἐπὶ τῶν πραγμάτων, οἳ καὶ προσεταιρίζονται τὸν Ξενοφῶντα οὕτως ἀρ· ξάμενον· “Δαρείου καὶ Παρυσάτιδος παῖδες γίγνονται δύο”, καὶ ἄλλους τῶν παλαιῶν, οὐκ εἰδότες ὡς δυνάμει τινὰ προοίμιά ἐστι λεληθότα τοὺς πολλούς, ὡς ἐν ἄλλοις δείξομεν.", "st": "53.23"}, {"sp": "N", "t": "καίτοι ταῦτα πάντα φορητὰ ἔτι, ὅσα ἢ ἑρμηνείας ἢ τῆς ἄλλης διατάξεως ἁμαρτήματά ἐστι, τὸ δὲ καὶ περὶ τοὺς τόπους αὐτοὺς ψεύδεσθαι, οὐ παρασάγγας μόνον, ἀλλὰ καὶ σταθμοὺς ὅλους, τίνι τῶν καλῶν ἔοικεν; εἷς γοῦν οὕτω ῥᾳθύμως συνήγαγε τὰ πράγματα, οὔτε Σύρῳ τινὶ ἐντυχὼν οὔτε τὸ λεγόμενον δὴ τοῦτο τῶν ἐπὶ κουρείων τὰ τοιαῦτα μυθολογούντων ἀκούσας, ὥστε περὶ Εὐρώπου λέγων οὕτως ἔφη· “ἡ δὲ Εὔρωπος κεῖται μὲν ἐν τῇ Μεσοποταμίᾳ σταθμοὺς δύο τοῦ Εὐφράτου ἀπέχουσα, ἀπῴκισαν δὲ αὐτὴν Ἐδεσσαῖοι”. καὶ οὐδὲ τοῦτο ἀπέχρησεν αὐτῷ, ἀλλὰ καὶ τὴν ἐμὴν πατρίδα τὰ Σαμόσατα ὁ αὐτὸς ἐν τῷ αὐτῷ βιβλίῳ ἀράμενος ὁ γενναῖος αὐτῇ ἀκροπόλει καὶ τείχεσι μετέθηκεν εἰς τὴν Μεσοποταμίαν, ὡς περιρρεῖσθαι αὐτὴν ὑπ’ ἀμφοτέρων τῶν ποταμῶν, ἑκατέρωθεν ἐν χρῷ παραμειβομένων καὶ μονονουχὶ τοῦ τείχους ψαυόντων. τὸ δὲ καὶ γελοῖον, εἴ σοι νῦν, ὦ Φίλων, ἀπολογοίμην, ὡς οὐ Παρθυαίων οὐδὲ Μεσοποταμίτης σοι ἐγώ, οἷ με φέρων ὁ θαυμαστὸς συγγραφεὺς ἀπῴκισε.", "st": "53.24"}, {"sp": "N", "t": "νὴ Δία κἀκεῖνο κομιδῇ πιθανὸν περὶ τοῦ Σευηριανοῦ ὁ αὐτὸς οὗτος εἶπεν ἐπομοσάμενος, ἦ μὴν ἀκοῦσαί τινος τῶν ἐξ αὐτοῦ τοῦ ἔργου διαφυγόντων· οὔτε γὰρ ξίφει ἐθελῆσαι αὐτὸν ἀποθανεῖν οὔτε φαρμάκου πιεῖν οὔτε βρόχου ἅψασθαι, ἀλλά τινα θάνατον ἐπινοῆσαι τραγικὸν καὶ τῇ τόλμῃ ξενίζοντα· τυχεῖν μὲν γὰρ αὐτὸν ἔχοντα παμμεγέθη ἐκπώματα ὑάλινα τῆς καλλίστης ὑάλου· ἐπεὶ δὲ πάντως ἀποθανεῖν ἔγνωστο, κατάξαντα τὸν μέγιστον τῶν σκύφων ἑνὶ τῶν θραυσμάτων χρήσασθαι εἰς τὴν σφαγὴν ἐντεμόντα τῇ ὑάλῳ τὸν λαιμόν. οὕτως οὐ ξιφίδιον, οὐ λογχάριον εὗρεν, ὡς ἀνδρεῖός γε αὐτῷ καὶ ἡρωϊκὸς ὁ θάνατος γένοιτο.", "st": "53.25"}, {"sp": "N", "t": "εἶτ’ ἐπειδὴ Θουκυδίδης ἐπιτάφιόν τινα εἶπε τοῖς πρώτοις τοῦ πολέμου ἐκείνου νεκροῖς, καὶ αὐτὸς ἡγήσατο χρῆναι ἐπειπεῖν τῷ Σευηριανῷ· ἅπασι γὰρ αὐτοῖς πρὸς τὸν οὐδὲν αἴτιον τῶν ἐν Ἀρμενίᾳ κακῶν, τὸν Θουκυδίδην, ἡ ἅμιλλα. θάψας οὖν τὸν Σευηριανὸν μεγαλοπρεπῶς ἀναβιβάζεται ἐπὶ τὸν τάφον Ἀφράνιόν τινα Σίλωνα ἑκατόνταρχον, ἀνταγωνιστὴν Περικλέους, ὃς τοιαῦτα καὶ τοσαῦτα ἐπερρητόρευσεν αὐτῷ, ὥστε με νὴ τὰς Χάριτας πολλὰ πάνυ δακρῦσαι ὑπὸ τοῦ γέλωτος, καὶ μάλιστα ὁπότε ὁ ῥήτωρ ὁ Ἀφράνιος ἐπὶ τέλει τοῦ λόγου δακρύων ἅμα σὺν οἰμωγῇ περιπαθεῖ ἐμέμνητο τῶν πολυτελῶν ἐκείνων δείπνων καὶ προπόσεων, εἶτα ἐπέθηκεν Αἰάντειόν τινα τὴν κορωνίδα· σπασάμενος γὰρ τὸ ξίφος, εὐγενῶς πάνυ καὶ ὡς Ἀφράνιον εἰκὸς ἦν, πάντων ὁρώντων ἀπέσφαξεν ἑαυτὸν ἐπὶ τῷ τάφῳ, οὐκ ἀνάξιος ὢν μὰ τὸν Ἐνυάλιον πρὸ πολλοῦ ἀποθανεῖν ἢ τοιαῦτα ἐρρητόρευε. καὶ τοῦτο ἐφη ἰδόντας τοὺς παρόντας ἅπαντας θαυμάσαι καὶ ὑπερεπαινέσαι τὸν Ἀφράνιον. ἐγὼ δὲ καὶ τὰ ἄλλα μὲν αὐτοῦ κατεγίγνωσκον, μονονουχὶ ζωμῶν καὶ λοπάδων μεμνημένου καὶ ἐπιδακρύοντος τῇ τῶν πλακούντων μνήμῃ, τοῦτο δὲ μάλιστα ᾐτιασάμην, ὅτι μὴ τὸν συγγραφέα καὶ διδάσκαλον τοῦ δράματος προαποσφάξας ἀπέθανε.", "st": "53.26"}, {"sp": "N", "t": "πολλοὺς δὲ καὶ ἄλλους ὁμοίους τούτοις ἔχων σοι, ὦ ἑταῖρε, καταριθμήσασθαι, ὀλίγων ὅμως ἐπιμνησθεὶς ἐπὶ τὴν ἑτέραν ὑπόσχεσιν ἤδη μετελεύσομαι, τὴν συμβουλὴν ὅπως ἂν ἄμεινον συγγράφοι τις· εἰσὶ γάρ τινες, οἳ τὰ μεγάλα μὲν τῶν πεπραγμένων καὶ ἀξιομνημόνευτα παραλείπουσιν ἢ παραθέουσιν, ὑπὸ δὲ ἰδιωτείας καὶ ἀπειροκαλίας καὶ ἀγνοίας τῶν λεκτέων ἢ σιωπητέων τὰ μικρότατα πάνυ λιπαρῶς καὶ φιλοπόνως ἑρμηνεύουσιν ἐμβραδύνοντες, ὥσπερ ἂν εἴ τις τοῦ Διὸς τοῦ ἐν Ὀλυμπίᾳ τὸ μὲν ὅλον κάλλος τοσοῦτον καὶ τοιοῦτον ὂν μὴ βλέποι μηδὲ ἐπαινοίη μηδὲ τοῖς οὐκ εἰδόσιν ἐξηγοῖτο, τοῦ ὑποποδίου δὲ τό τε εὐθυεργὲς καὶ τὸ εὔξεστον θαυμάζοι καὶ τῆς κρηπῖδος τὸ εὔρυθμον, καὶ ταῦτα πάνυ μετὰ πολλῆς φροντίδος διεξιών.", "st": "53.27"}, {"sp": "N", "t": "ἐγὼ γοῦν ἤκουσά τινος τὴν μὲν ἐπ’ Εὐρώπῳ μάχην ἐν οὐδ’ ὅλοις ἑπτὰ ἔπεσι παραδραμόντος, εἴκοσι δὲ μέτρα ἢ ἔτι πλείω ὕδατος ἀναλωκότος ἐς ψυχρὰν καὶ οὐδὲν ἡμῖν προσήκουσαν διήγησιν, ὡς Μαῦρός τις ἱππεὺς Μαυσάκας τοὔνομα ὑπὸ δίψους πλανώμενος ἀνὰ τὰ ὄρη καταλάβοι Σύρους τινὰς τῶν ἀγροίκων, ἄριστον παρατιθεμένους, καὶ ὅτι τὰ μὲν πρῶτα ἐκεῖνοι φοβηθεῖεν αὐτόν, εἶτα μέντοι μαθόντες ὡς τῶν φίλων εἴη κατεδέξαντο καὶ εἱστίασαν· καὶ γάρ τινα τυχεῖν αὐτῶν ἀποδεδημηκότα καὶ αὐτὸν ἐς τὴν τῶν Μαύρων, ἀδελφοῦ αὐτῷ ἐν τῇ γῇ στρατευομένου. μῦθοι τὸ μετὰ τοῦτο μακροὶ καὶ διηγήσεις, ὡς θηράσειεν αὐτὸς ἐν τῇ Μαυρουσίᾳ καὶ ὡς ἴδοι τοὺς ἐλέφαντας πολλοὺς ἐν τῷ αὐτῷ συννεμομένους καὶ ὡς ὑπὸ λέοντος ὀλίγου δεῖν καταβρωθείη, καὶ ἡλίκους ἰχθῦς ἐπρίατο ἐν Καισαρείᾳ· καὶ ὁ θαυμαστὸς συγγραφεὺς ἀφεὶς τὰς ἐν Εὐρώπῳ γιγνομένας σφαγὰς τοσαύτας καὶ ἐπελάσεις καὶ σπονδὰς ἀναγκαίας καὶ φυλακὰς καὶ ἀντιφυλακὰς ἄχρι βαθείας ἑσπέρας ἐφειστήκει ὁρῶν Μαλχίωνα τὸν Σύρον ἐν Καισαρείᾳ σκάρους παμμεγέθεις ἀξίους ὠνούμενον· εἰ δὲ μὴ νὺξ κατέλαβε, τάχ’ ἂν καὶ συνεδείπνει μετ’ αὐτοῦ ἤδη τῶν σκάρων ἐσκευασμένων. ἅπερ εἰ μὴ ἐνεγέγραπτο ἐπιμελῶς τῇ ἱστορίᾳ, μεγάλα ἂν ἡμεῖς ἠγνοηκότες ἦμεν, καὶ ἡ ζημία Ῥωμαίοις ἀφόρητος, εἰ Μαυσάκας ὁ Μαῦρος διψῶν μὴ εὗρε πιεῖν, ἀλλ’ ἄδειπνος ἐπανῆλθεν ἐπὶ τὸ στρατόπεδον. καίτοι πόσα ἄλλα μακρῷ ἀναγκαιότερα ἑκὼν ἐγὼ νῦν παρίημι; ὡς καὶ αὐλητρὶς ἧκεν ἐκ τῆς πλησίον κώμης αὐτοῖς καὶ ὡς δῶρα ἀλλήλοις ἀντέδοσαν, ὁ Μαῦρος μὲν τῷ Μαλχίωνι λόγχην, ὁ δὲ τῷ Μαυσάκᾳ πόρπην, καὶ ἄλλα πολλὰ τοιαῦτα τῆς ἐπ’ Εὐρώπῳ μάχης αὐτὰ δὴ τὰ κεφάλαια. τοιγάρτοι εἰκότως ἄν τις εἴποι τοὺς τοιούτους τὸ μὲν ῥόδον αὐτὸ μὴ βλέπειν, τὰς ἀκάνθας δὲ αὐτοῦ τὰς παρὰ τὴν ῥίζαν ἀκριβῶς ἐπισκοπεῖν.", "st": "53.28"}, {"sp": "N", "t": "ἄλλος, ὦ Φίλων, μάλα καὶ οὗτος γελοῖος, οὐδὲ τὸν ἕτερον πόδα ἐκ Κορίνθου πώποτε προβεβηκὼς οὐδ’ ἄχρι Κεγχρεῶν ἀποδημήσας, οὔτι γε Συρίαν ἢ Ἀρμενίαν ἰδών, ὧδε ἤρξατο — μέμνημαι γάρ — “ὦτα ὀφθαλμῶν ἀπιστότερα. γράφω τοίνυν ἃ εἶδον, οὐχ ἃ ἤκουσα.” καὶ οὕτως ἀκριβῶς ἅπαντα ἑωράκει, ὥστε τοὺς δράκοντας ἔφη τῶν Παρθυαίων — σημεῖον δὲ πλήθους τοῦτο αὐτοῖς· χιλίους γὰρ οἶμαι ὁ δράκων ἄγει — ζῶντας δράκοντας παμμεγέθεις εἶναι γεννωμένους ἐν τῇ Περσίδι μικρὸν ὑπὲρ τὴν Ἰβηρίαν, τούτους δὲ τέως μὲν ἐπὶ κοντῶν μεγάλων ἐκδεδεμένους ὑψηλοὺς αἰωρεῖσθαι καὶ πόρρωθεν ἐπελαυνόντων δέος ἐμποιεῖν, ἐν αὐτῷ δὲ τῷ ἔργῳ ἐπειδὰν ὁμοῦ ἴωσι, λύσαντες αὐτοὺς ἐπαφιᾶσι τοῖς πολεμίοις· ἀμέλει πολλοὺς τῶν ἡμετέρων οὕτω καταποθῆναι καὶ ἄλλους. περισπειραθέντων αὐτοῖς, ἀποπνιγῆναι καὶ συγκλασθῆναι· ταῦτα δὲ ἐφεστὼς ὁρᾶν αὐτός, ἐν ἀσφαλεῖ μέντοι ἀπὸ δένδρου ὑψηλοῦ ποιούμενος τὴν σκοπήν. καὶ εὖ γε ἐποίησε μὴ ὁμόσε χωρήσας τοῖς θηρίοις, ἐπεὶ οὐκ ἂν ἡμεῖς οὕτω θαυμαστὸν συγγραφέα νῦν εἴχομεν καὶ ἀπὸ χειρὸς αὐτὸν μεγάλα καὶ λαμπρὰ ἐν τῷ πολέμῳ τούτῳ ἐργασάμενον· καὶ γὰρ ἐκινδύνευσε πολλὰ καὶ ἐτρώθη περὶ Σοῦραν, ἀπὸ τοῦ Κρανείου δῆλον ὅτι βαδίζων ἐπὶ τὴν Λέρναν. καὶ ταῦτα Κορινθίων ἀκουόντων ἀνεγίγνωσκε τῶν ἀκριβῶς εἰδότων, ὅτι μηδὲ κατὰ τοίχου γεγραμμένον πόλεμον ἑωράκει. ἀλλ’ οὐδὲ ὅπλα ἐκεῖνός γε ᾔδει οὐδὲ μηχανήματα οἷά ἐστιν οὐδὲ τάξεων ἢ καταλοχισμῶν ὀνόματα· πάνυ γοῦν ἔμελεν αὐτῷ πλαγίαν μὲν τὴν φάλαγγα, ἐπὶ κέρως δὲ λέγειν τὸ ἐπὶ μετώπου ἄγειν.", "st": "53.29"}, {"sp": "N", "t": "εἷς δέ τις βέλτιστος ἅπαντα ἐξ ἀρχῆς ἐς τέλος τὰ πεπραγμένα, ὅσα ἐν Ἀρμενίᾳ, ὅσα ἐν Συρίᾳ, ὅσα ἐν Μεσοποταμίᾳ, τὰ ἐπὶ τῷ Τίγρητι, τὰ ἐν Μηδίᾳ, πεντακοσίοις οὐδ’ ὅλοις ἔπεσι περιλαβὼν συνέτριψε καὶ τοῦτο ποιήσας ἱστορίαν συγγεγραφέναι φησί. τὴν μέντοι ἐπιγραφὴν ὀλίγου δεῖν μακροτέραν τοῦ βιβλίου ἐπέγραψεν, “Ἀντιοχιανοῦ τοῦ Ἀπόλλωνος ἱερονίκου” — δόλιχον γάρ που οἶμαι ἐν παισὶ νενίκηκε — “τῶν ἐν Ἀρμενίᾳ καὶ Μεσοποταμίᾳ καὶ ἐν Μηδίᾳ νῦν Ῥωμαίοις πραχθέντων ἀφήγησις”.", "st": "53.30"}, {"sp": "N", "t": "ἤδη δ’ ἐγώ τινος καὶ τὰ μέλλοντα συγγεγραφότος ἤκουσα, καὶ τὴν λῆψιν τὴν Οὐολογέσου καὶ τὴν Ὀσρόου σφαγήν, ὡς παραβληθήσεται τῷ λέοντι, καὶ ἐπὶ πᾶσι τὸν τριπόθητον ἡμῖν θρίαμβον. οὕτω μαντικῶς ἅμα ἔχων ἔσπευδεν ἤδη πρὸς τὸ τέλος τῆς γραφῆς. ἀλλὰ καὶ πόλιν ἤδη ἐν τῃ Μεσοποταμίᾳ ᾤκισε μεγέθει τε μεγίστην καὶ κάλλει καλλίστην· ἔτι μέντοι ἐπισκοπεῖ καὶ διαβουλεύεται εἴτε Νίκαιαν αὐτὴν ἀπὸ τῆς νίκης χρὴ ὀνομάζεσθαι εἴτε Ὁμόνοιαν εἴτε Εἰρηνίαν. καὶ τοῦτο μὲν ἔτι ἄκριτον καὶ ἀνώνυμος ἡμῖν ἡ καλὴ πόλις ἐκείνη, λήρου πολλοῦ καὶ κορύζης συγγραφικῆς γέμουσα· τὰ δ’ ἐν Ἰνδοῖς πραχθησόμενα ὑπέσχετο ἤδη γράψειν καὶ τὸν περίπλουν τῆς ἔξω θαλάττης, καὶ οὐχ ὑπόσχεσις ταῦτα μόνον, ἀλλὰ καὶ τὸ προοίμιον τῆς Ἰνδικῆς ἤδη συντέτακται, καὶ τὸ τρίτον τάγμα καὶ οἱ Κελτοὶ καὶ Μαύρων μοῖρα ὀλίγη σὺν Κασσίῳ πάντες οὗτοι ἐπεραιώθησαν τὸν Ἰνδὸν ποταμόν· ὅ τι δὲ καὶ πράξουσιν ἢ πῶς δέξονται τὴν τῶν ἐλεφάντων ἐπέλασιν, οὐκ εἰς μακρὰν ἡμῖν ὁ θαυμαστὸς συγγραφεὺς ἀπὸ Μουζίριδος ἢ ἀπ’ Ὀξυδρακῶν ἐπιστελεῖ.", "st": "53.31"}, {"sp": "N", "t": "τοιαῦτα πολλὰ ὑπὸ ἀπαιδευσίας ληροῦσι, τὰ μὲν ἀξιόρατα οὔτε ὁρῶντες οὔτ’, εἰ βλέποιεν, κατ’ ἀξίαν εἰπεῖν δυνάμενοι, ἐπινοοῦντες δὲ καὶ ἀναπλάττοντες, ὅ τι κεν ἐπ’ ἀκαιρίμαν γλῶσσαν, φασίν, ἔλθῃ, καὶ ἐπὶ τῷ ἀριθμῷ τῶν βιβλίων ἔτι σεμνυνόμενοι, καὶ μάλιστα ἐπὶ ταῖς ἐπιγραφαῖς· καὶ γὰρ αὖ καὶ αὗται παγγέλοιοι· τοῦ δεῖνος Παρθικῶν νικῶν τοσάδε· καὶ αὖ· Παρθίδος πρῶτον, δεύτερον, ὡς Ἀτθίδος δῆλον ὅτι. ἄλλος ἀστειότερον παρὰ πολύ — ἀνέγνων γάρ — Δημητρίου Σαγαλασσέως Παρθονικικά· οὐδ’ ὡς ἐν γέλωτι ποιήσασθαι καὶ ἐπισκῶψαι τὰς ἱστορίας οὕτω καλὰς οὔσας, ἀλλὰ τοῦ χρησίμου ἕνεκα ὡς ὅστις ἂν ταῦτα καὶ τὰ τοιαῦτα φεύγῃ, πολὺ μέρος ἤδη ἐς τὸ ὀρθῶς συγγράφειν οὗτος προείληφε, μᾶλλον δὲ ὀλίγων ἔτι προσδεῖται, εἴ γε ἀληθὲς ἐκεῖνό φησιν ἡ διαλεκτική, ὡς τῶν ἀμέσων ἡ θατέρου ἄρσις τὸ ἕτερον πάντως ἀντεισάγει.", "st": "53.32"}, {"sp": "N", "t": "καὶ δὴ τὸ χωρίον σοι, φαίη τις ἄν, ἀκριβῶς ἀνακεκάθαρται καὶ αἵ τε ἄκανθαι, ὁπόσαι ἦσαν, καὶ βάτοι ἐκκεκομμέναι εἰσί, τὰ δὲ τῶν ἄλλων ἐρείπια ἤδη ἐκπεφόρηται, καὶ εἴ τι τραχύ, ἤδη καὶ τοῦτο λεῖόν ἐστιν. ὥστε οἰκοδόμει τι ἤδη καὶ αὐτός, ὡς δείξῃς οὐκ ἀνατρέψαι μόνον τὸ τῶν ἄλλων γεννάδας ὤν, ἀλλά τι καὶ αὐτὸς ἐπινοῆσαι δεξιὸν καὶ ὃ οὐδεὶς ἄν, ἀλλ’ οὐδ’ ὁ Μῶμος μωμήσασθαι δύναιτο.", "st": "53.33"}, {"sp": "N", "t": "φημὶ τοίνυν τὸν ἄριστα ἱστορίαν συγγράφοντα δύο μὲν ταῦτα κορυφαιότατα οἴκοθεν ἔχοντα ἥκειν, σύνεσίν τε πολιτικὴν καὶ δύναμιν ἑρμηνευτικήν, τὴν μὲν ἀδίδακτόν τι τῆς φύσεως δῶρον, ἡ δύναμις δὲ πολλῇ τῇ ἀσκήσει καὶ συνεχεῖ τῷ πόνῳ καὶ ζήλῳ τῶν ἀρχαίων προσγεγενημένη ἔστω. ταῦτα μὲν οὖν ἄτεχνα καὶ οὐδὲν ἐμοῦ συμβούλου δεόμενα· οὐ γὰρ συνετοὺς καὶ ὀξεῖς ἀποφαίνειν τοὺς μὴ παρὰ τῆς φύσεως τοιούτους φησὶ τοῦτο ἡμῖν τὸ βιβλίον· ἐπεὶ πολλοῦ [ἄν], μᾶλλον δὲ τοῦ παντὸς ἦν ἄξιον, εἰ μεταπλάσαι καὶ μετακοσμῆσαι τὰ τηλικαῦτα ἠδύνατο ἢ ἐκ μολύβδου χρυσὸν ἀποφῆναι ἢ ἄργυρον ἐκ κασσιτέρου ἢ ἀπὸ Κόνωνος Τίτορμον ἢ ἀπὸ Λεωτροφίδου Μίλωνα ἐξεργάσασθαι.", "st": "53.34"}, {"sp": "N", "t": "ἀλλὰ ποῦ τὸ τῆς τέχνης καὶ τὸ τῆς συμβουλῆς χρήσιμον; οὐκ ἐς ποίησιν τῶν προσόντων, ἀλλ’ ἐς χρῆσιν αὐτῶν τὴν προσήκουσαν· οἷόν τι ἀμέλει καὶ Ἴκκος καὶ Ἡρόδικος καὶ Θέων καὶ εἴ τις ἄλλος γυμναστής, οὐχ ὑπόσχοιντο ἄν σοί που τὸν Περδίκκαν παραλαβόντες — εἰ δὴ οὗτός ἐστιν ὁ τῆς μητρυιᾶς ἐρασθεὶς καὶ διὰ ταῦτα κατεσκληκώς, ἀλλὰ μὴ Ἀντίοχος ὁ τοῦ Σελεύκου [Στρατονίκης ἐκείνης] — ἀποφαίνειν Ὀλυμπιονίκην καὶ Θεαγένει τῷ Θασίῳ ἢ Πολυδάμαντι τῷ Σκοτουσσαίῳ ἀντίπαλον, ἀλλὰ τὴν δοθεῖσαν ὑπόθεσιν εὐφυᾶ πρὸς ὑποδοχὴν τῆς γυμναστικῆς παρὰ πολὺ ἀμείνω ἀποφαίνειν μετὰ τῆς τέχνης. ὥστε ἀπέστω καὶ ἡμῶν τὸ ἐπίφθονον τοῦτο τῆς ὑποσχέσεως, εἰ τέχνην φαμὲν ἐφ’ οὕτω μεγάλῳ καὶ χαλεπῷ τῷ πράγματι εὑρηκέναι· οὐ γὰρ ὁντινοῦν παραλαβόντες ἀποφαίνειν συγγραφέα φαμέν, ἀλλὰ τῷ φύσει συνετῷ καὶ ἄριστα πρὸς λόγους ἠσκημένῳ ὑποδείξειν ὁδους τινας ὀρθάς, εἰ δὴ τοιαῦται φαίνονται, αἷς χρώμενος θᾶττον ἂν καὶ εὐμαρέστερον τελέσειεν ἄχρι πρὸς τὸν σκοπόν.", "st": "53.35"}, {"sp": "N", "t": "καίτοι οὐ γὰρ ἂν φαίης ἀπροσδεῆ τὸν συνετὸν εἶναι τῆς τέχνης καὶ διδασκαλίας ὧν ἀγνοεῖ· ἐπεὶ κἂν ἐκιθάριζε μὴ μαθὼν καὶ ηὔλει καὶ πάντα ἂν ἠπίστατο. νῦν δὲ μὴ μαθὼν οὐκ ἄν τι αὐτῶν χειρουργήσειεν, ὑποδείξαντος δέ τινος ῥᾷστά τε ἂν μάθοι καὶ εὖ μεταχειρίσαιτο ἐφ’ αὑτοῦ.", "st": "53.36"}, {"sp": "N", "t": "καὶ τοίνυν καὶ ἡμῖν τοιοῦτός τις ὁ μαθητὴς νῦν παραδεδόσθω, συνεῖναί τε καὶ εἰπεῖν οὐκ ἀγεννής, ἀλλ’ ὀξὺ δεδορκώς, οἷος καὶ πράγμασι χρήσασθαι ἄν, εἰ ἐπιτραπείη, καὶ γνώμην στρατιωτικήν, ἀλλὰ μετὰ τῆς πολιτικῆς καὶ ἐμπειρίαν στρατηγικὴν ἔχειν, καὶ νὴ Δία καὶ ἐν στρατοπέδῳ γεγονώς ποτε καὶ γυμναζομένους ἢ ταττομένους στρατιώτας ἑωρακὼς καὶ ὅπλα εἰδὼς καὶ μηχανήματα, ἔτι δὲ καὶ τί ἐπὶ κέρως καὶ τί ἐπὶ μετώπου, πῶς οἱ λόχοι, πῶς οἱ ἱππεῖς καὶ πόθεν καὶ τί ἐξελαύνειν ἢ περιελαύνειν, καὶ ὅλως, οὐ τῶν κατοικιδίων τις οὐδ’ οἷος πιστεύειν μόνον τοῖς ἀπαγγέλλουσι.", "st": "53.37"}, {"sp": "N", "t": "μάλιστα δὲ καὶ πρὸ τῶν πάντων ἐλεύθερος ἔστω τὴν γνώμην καὶ μήτε φοβείσθω μηδένα μήτε ἐλπιζέτω μηδέν, ἐπεὶ ὅμοιος ἔσται τοῖς φαύλοις δικασταῖς πρὸς χάριν ἢ πρὸς ἀπέχθειαν ἐπὶ μισθῷ δικάζουσιν. ἀλλὰ μὴ μελέτω αὐτῷ μήτε Φίλιππος ἐκκεκομμένος τὸν ὀφθαλμὸν ὑπὸ Ἀστέρος τοῦ Ἀμφιπολίτου τοῦ τοξότου ἐν Ὀλύνθῳ, ἀλλὰ τοιοῦτος οἷος ἦν δειχθήσεται· μήτ’ εἰ Ἀλέξανδρος ἀνιάσεται ἐπὶ τῇ Κλείτου σφαγῇ ὠμῶς ἐν τῷ συμποσίῳ γενομένῃ, εἰ σαφῶς ἀναγράφοιτο· οὐδὲ Κλέων αὐτὸν φοβήσει μέγα ἐν τῇ ἐκκλησίᾳ δυνάμενος καὶ κατέχων τὸ βῆμα, ὡς μὴ εἰπεῖν ὅτι ὀλέθριος καὶ μανικὸς ἄνθρωπος οὗτος ἦν· οὐδὲ ἡ σύμπασα πόλις τῶν Ἀθηναίων, ἢν τὰ ἐν Σικελίᾳ κακὰ ἱστορῇ καὶ τὴν Δημοσθένους λῆψιν καὶ τὴν Νικίου τελευτὴν καὶ ὡς ἐδίψων καὶ οἷον τὸ ὕδωρ ἔπινον καὶ ως ἐφονεύοντο πίνοντες οἱ πολλοί. ἡγήσεται γὰρ — ὅπερ δικαιότατον — ὑπ’ οὐδενὸς τῶν νοῦν ἐχόντων αὐτὸς ἕξειν τὴν αἰτίαν, ἢν τὰ δυστυχῶς ἢ ἀνοήτως γεγενημένα ὡς ἐπράχθη διηγῆται· οὐ γὰρ ποιητὴς αὐτῶν, ἀλλὰ μηνυτὴς ἦν. ὥστε κἂν καταναυμαχῶνται τότε, οὐκ ἐκεῖνος ὁ καταδύων ἐστί, κἂν φεύγωσιν, οὐκ ἐκεῖνος ὁ διώκων, ἐκτὸς εἰ μή, εὔξασθαι δέον, παρέλειπεν· ἐπεί τοί γε εἰ σιωπήσας αὐτὰ ἢ πρὸς τοὐναντίον εἰπὼν ἐπανορθώσασθαι ἐδύνατο, ῥᾷστον ἦν ἑνὶ καλάμῳ λεπτῷ τὸν Θουκυδίδην ἀνατρέψαι μὲν τὸ ἐν ταῖς Ἐπιπολαῖς παρατείχισμα, καταδῦσαι δὲ τὴν Ἑρμοκράτους τριήρη καὶ τὸν κατάρατον Γύλιππον διαπεῖραι μεταξὺ ἀποτειχίζοντα καὶ ἀποταφρεύοντα τὰς ὁδούς, καὶ τέλος Συρακουσίους μὲν ἐς τὰς λιθοτομίας ἐμβαλεῖν, τοὺς δὲ Ἀθηναίους περιπλεῖν Σικελίαν καὶ Ἰταλίαν μετὰ τῶν πρώτων τοῦ Ἀλκιβιάδου ἐλπίδων. ἀλλ’, οἶμαι, τὰ μὲν πραχθέντα οὐδὲ Κλωθὼ ἂν ἔτι ἀνακλώσειεν οὐδὲ Ἄτροπος μετατρέψειε.", "st": "53.38"}, {"sp": "N", "t": "τοῦ δὴ συγγραφέως ἔργον ἕν, ὡς ἐπράχθη, εἰπεῖν. τοῦτο δ’ οὐκ ἂν δύναιτο, ἄχρι ἂν ἢ φοβῆται Ἀρτοξέρξην ἰατρὸς αὐτοῦ ὤν, ἢ ἐλπίζῃ κάνδυν πορφυροῦν καὶ στρεπτὸν χρυσοῦν καὶ ἵππον τῶν Νισαίων λήψεσθαι μισθὸν τῶν ἐν τῇ γραφῇ ἐπαίνων. ἀλλ’ οὐ Ξενοφῶν αὐτὸ ποιήσει, δίκαιος συγγραφεύς, οὐδὲ Θουκυδίδης. ἀλλὰ κἂν ἰδίᾳ μισῇ τινας, πολὺ ἀναγκαιότερον ἡγήσεται τὸ κοινὸν καὶ τὴν ἀλήθειαν περὶ πλείονος ποιήσεται τῆς ἔχθρας, κἂν φιλῇ, ὅμως οὐκ ἀφέξεται ἁμαρτάνοντος· ἓν γάρ, ὡς ἔφην, τοῦτο ἴδιον ἱστορίας, καὶ μόνῃ θυτέον τῇ ἀληθείᾳ, εἴ τις ἱστορίαν γράψων ἴῃ, τῶν δὲ ἄλλων ἁπάντων ἀμελητέον αὐτῷ, καὶ ὅλως πῆχυς εἷς καὶ μέτρον ἀκριβές, ἀποβλέπειν μὴ εἰς τοὺς νῦν ἀκούοντας, ἀλλ’ εἰς τοὺς μετὰ ταῦτα συνεσομένους τοῖς συγγράμμασιν.", "st": "53.39"}, {"sp": "N", "t": "εἰ δὲ τὸ παραυτίκα τις θεραπεύοι, τῆς τῶν κολακευόντων μερίδος εἰκότως ἂν νομισθείη, οὓς πάλαι ἡ ἱστορία καὶ ἐξ ἀρχῆς εὐθὺς ἀπέστραπτο, οὐ μεῖον ἢ κομμωτικὴν ἡ γυμναστική. Ἀλεξάνδρου γοῦν καὶ τοῦτο ἀπομνημονεύουσιν, ὅς, Ἡδέως ἄν, ἔφη, πρὸς ὀλίγον ἀνεβίουν, ὦ Ὀνησίκριτε, ἀποθανών, ὡς μάθοιμι ὅπως ταῦτα οἱ ἄνθρωποι τότε ἀναγιγνώσκουσιν. εἰ δὲ νῦν αὐτὰ ἐπαινοῦσι καὶ ἀσπάζονται, μὴ θαυμάσῃς· οἴονται γὰρ οὐ μικρῷ τινι τῷ δελέατι τούτῳ ἀνασπάσειν ἕκαστος τὴν παρ’ ἡμῶν εὔνοιαν. Ὁμήρῳ γοῦν, καίτοι πρὸς τὸ μυθῶδες τὰ πλεῖστα συγγεγραφότι ὑπὲρ τοῦ Ἀχιλλέως, ἤδη καὶ πιστεύειν τινὲς ὑπάγονται, μόνον τοῦτο εἰς ἀπόδειξιν τῆς ἀληθείας μέγα τεκμήριον τιθέμενοι, ὅτι μὴ περὶ ζῶντος ἔγραφεν· οὐ γὰρ εὑρίσκουσιν οὗτινος ἕνεκα ἐψεύδετ’ ἄν.", "st": "53.40"}, {"sp": "N", "t": "τοιοῦτος οὖν μοι ὁ συγγραφεὺς ἔστω, ἄφοβος, ἀδέκαστος, ἐλεύθερος, παρρησίας καὶ ἀληθείας φίλος, ὡς ὁ κωμικός φησι, τὰ σῦκα σῦκα, τὴν σκάφην δὲ σκάφην ὀνομάσων, οὐ μίσει οὐδὲ φιλίᾳ τι νέμων οὐδὲ φειδόμενος ἢ ἐλεῶν ἢ αἰσχυνόμενος ἢ δυσωπούμενος, ἴσος δικαστής, εὔνους ἅπασιν ἄχρι τοῦ μὴ θατέρῳ ἀπονεῖμαι πλεῖον τοῦ δέοντος, ξένος ἐν τοῖς βιβλίοις καὶ ἄπολις, αὐτόνομος, ἀβασίλευτος, οὐ τί τῷδε ἢ τῷδε δόξει λογιζόμενος, ἀλλὰ τί πέπρακται λέγων.", "st": "53.41"}, {"sp": "N", "t": "ὁ δ’ οὖν Θουκυδίδης εὖ μάλα τοῦτ’ ἐνομοθέτησε καὶ διέκρινεν ἀρετὴν καὶ κακίαν συγγραφικήν, ὁρῶν μάλιστα θαυμαζόμενον τὸν Ἡρόδοτον, ἄχρι τοῦ καὶ Μούσας κληθῆναι αὐτοῦ τὰ βιβλία· κτῆμα γάρ φησι μᾶλλον ἐς ἀεὶ συγγράφειν ἤπερ ἐς τὸ παρὸν ἀγώνισμα, καὶ μὴ τὸ μυθῶδες ἀσπάζεσθαι, ἀλλὰ τὴν ἀλήθειαν τῶν γεγενημένων ἀπολείπειν τοῖς ὕστερον. καὶ ἐπάγει τὸ χρήσιμον καὶ ὃ τέλος ἄν τις εὖ φρονῶν ὑπόθοιτο ἱστορίας, ὡς εἴ ποτε καὶ αὖθις τὰ ὅμοια καταλάβοι, ἔχοιεν, φησί, πρὸς τὰ προγεγραμμένα ἀποβλέποντες εὖ χρῆσθαι τοῖς ἐν ποσί.", "st": "53.42"}, {"sp": "N", "t": "καὶ τὴν μὲν γνώμην τοιαύτην ἔχων ὁ συγγραφεὺς ἡκέτω μοι, τὴν δὲ φωνὴν καὶ τὴν τῆς ἑρμηνείας ἰσχύν, τὴν μὲν σφοδρὰν ἐκείνην καὶ κάρχαρον καὶ συνεχῆ ταῖς περιόδοις καὶ ἀγκύλην ταῖς ἐπιχειρήσεσι καὶ τὴν ἄλλην τῆς ῥητορείας δεινότητα μὴ κομιδῇ τεθηγμένος ἀρχέσθω τῆς γραφῆς, ἀλλ’ εἰρηνικώτερον διακείμενος. καὶ ὁ μὲν νοῦς σύστοιχος ἔστω καὶ πυκνός, ἡ λέξις δὲ σαφὴς καὶ πολιτική, οἵα ἐπισημότατα δηλοῦν τὸ ὑποκείμενον.", "st": "53.43"}, {"sp": "N", "t": "ὡς γὰρ τῇ γνώμῃ τοῦ συγγραφέως σκοποὺς ὑπεθέμεθα παρρησίαν καὶ ἀλήθειαν, οὕτω δὲ καὶ τῇ φωνῇ αὐτοῦ εἷς σκοπὸς ὁ πρῶτος, σαφῶς δηλῶσαι καὶ φανότατα ἐμφανίσαι τὸ πρᾶγμα, μήτε ἀπορρήτοις καὶ ἔξω πάτου ὀνόμασι μήτε τοῖς ἀγοραίοις τούτοις καὶ καπηλικοῖς, ἀλλ’ ὡς μὲν τοὺς πολλοὺς συνεῖναι, τοὺς δὲ πεπαιδευμένους ἐπαινέσαι. καὶ μὴν καὶ σχήμασι κεκοσμήσθω ἀνεπαχθέσι καὶ τὸ ἀνεπιτήδευτον μάλιστα ἔχουσιν· ἐπεὶ τοῖς κατηρτυμένοις τῶν ζωμῶν ἐοικότας ἀποφαίνει τοὺς λόγους.", "st": "53.44"}, {"sp": "N", "t": "καὶ ἡ μὲν γνώμη κοινωνείτω καὶ προσαπτέσθω τι καὶ ποιητικῆς, παρ’ ὅσον μεγαληγόρος καὶ διηρμένη καὶ ἐκείνη, καὶ μάλισθ’ ὁπόταν παρατάξεσι καὶ μάχαις καὶ ναυμαχίαις συμπλέκηται· δεήσει γὰρ τότε ποιητικοῦ τινος ἀνέμου ἐπουριάσοντος τὰ ἀκάτια καὶ συνδιοίσοντος ὑψηλὴν καὶ ἐπ’ ἄκρων τῶν κυμάτων τὴν ναῦν. ἡ λέξις δὲ ὅμως ἐπὶ γῆς βεβηκέτω, τῷ μὲν κάλλει καὶ τῷ μεγέθει τῶν λεγομένων συνεπαιρομένη καὶ ὡς ἔνι μάλιστα ὁμοιουμένη, ξενίζουσα δὲ μηδ’ ὑπὲρ τὸν καιρὸν ἐνθουσιῶσα· κίνδυνος γὰρ αὐτῇ τότε μέγιστος παρακινῆσαι καὶ κατενεχθῆναι ἐς τὸν τῆς ποιητικῆς κορύβαντα, ὥστε μάλιστα πειστέον τηνικαῦτα τῷ χαλινῷ καὶ σωφρονητέον, εἰδότας ὡς ἱπποτυφία τις καὶ ἐν λόγοις πάθος οὐ μικρὸν γίγνεται. ἄμεινον οὖν ἐφ’ ἵππου ὀχουμένῃ τότε τῇ γνώμῃ τὴν ἑρμηνείαν πεζῇ συμπαραθεῖν, ἐχομένην τοῦ ἐφιππίου, ὡς μὴ ἀπολείποιτο τῆς φορᾶς.", "st": "53.45"}, {"sp": "N", "t": "καὶ μὴν καὶ συνθήκῃ τῶν ὀνομάτων εὐκράτῳ καὶ μέσῃ χρηστέον, οὔτε ἄγαν ἀφιστάντα καὶ ἀπαρτῶντα — τραχὺ γάρ — οὔτε ῥυθμῷ παρ’ ὀλίγον, ὡς οἱ πολλοί, συνάπτοντα· τὸ μὲν γὰρ ἐπαίτιον, τὸ δὲ ἀηδὲς τοῖς ἀκούουσι.", "st": "53.46"}, {"sp": "N", "t": "τὰ δὲ πράγματα αὐτὰ οὐχ ὡς ἔτυχε συνακτέον, ἀλλὰ φιλοπόνως καὶ ταλαιπώρως πολλάκις περὶ τῶν αὐτῶν ἀνακρίναντα, καὶ μάλιστα μὲν παρόντα καὶ ἐφορῶντα, εἰ δὲ μή, τοῖς ἀδεκαστότερον ἐξηγουμένοις προσέχοντα καὶ οὓς εἰκάσειεν ἄν τις ἥκιστα πρὸς χάριν ἢ ἀπέχθειαν ἀφαιρήσειν ἢ προσθήσειν τοῖς γεγονόσι. κἀνταῦθα ἤδη καὶ στοχαστικός τις καὶ συνθετικὸς τοῦ πιθανωτέρου ἔστω.", "st": "53.47"}, {"sp": "N", "t": "καὶ ἐπειδὰν ἀθροίσῃ ἅπαντα ἢ τὰ πλεῖστα, πρῶτα μὲν ὑπόμνημά τι συνυφαινέτω αὐτῶν καὶ σῶμα ποιείτω ἀκαλλὲς ἔτι καὶ ἀδιάρθρωτον· εἶτα ἐπιθεὶς τὴν τάξιν ἐπαγέτω τὸ κάλλος καὶ χρωννύτω τῇ λέξει καὶ σχηματιζέτω καὶ ῥυθμιζέτω.", "st": "53.48"}, {"sp": "N", "t": "καὶ ὅλως ἐοικέτω τότε τῷ τοῦ Ὁμήρου Διὶ ἄρτι μὲν τὴν τῶν ἱπποπόλων Θρῃκῶν γῆν ὁρῶντι, ἄρτι δὲ τὴν Μυσῶν· κατὰ ταῦτα καὶ αὐτὸς ἄρτι μὲν τὰ ἴδια ὁράτω καὶ δηλούτω ἡμῖν οἷα ἐφαίνετο αὐτῷ ἀφ’ ὑψηλοῦ ὁρῶντι, ἄρτι δὲ τὰ Περσῶν, εἶτ’ ἀμφότερα, εἰ μάχοιντο. καὶ ἐν αὐτῇ δὲ τῇ παρατάξει μὴ πρὸς ἓν μέρος ὁράτω μηδὲ ἐς ἕνα ἱππέα ἢ πεζόν, εἰ μὴ Βρασίδας τις εἴη προπηδῶν ἢ Δημοσθένης ἀνακόπτων τὴν ἐπίβασιν· ἐς τοὺς στρατηγοὺς μέντοι τὰ πρῶτα, καὶ εἴ τι παρεκελεύσαντο, κἀκεῖνο ἀκηκούσθω, καὶ ὅπως καὶ ᾗτινι γνώμῃ καὶ ἐπινοίᾳ ἔταξαν. ἐπειδὰν δὲ ἀναμιχθῶσι, κοινὴ ἔστω ἡ θέα, καὶ ζυγοστατείτω τότε ὥσπερ ἐν τρυτάνῃ τὰ γιγνόμενα καὶ συνδιωκέτω καὶ συμφευγέτω.", "st": "53.49"}, {"sp": "N", "t": "καὶ πᾶσι τούτοις μέτρον ἐπέστω, μὴ ἐς κόρον μηδὲ ἀπειροκάλως μηδὲ νεαρῶς, ἀλλὰ ῥᾳδίως ἀπολυέσθω· καὶ στήσας ἐνταῦθά που ταῦτα ἐπ’ ἐκεῖνα μεταβαινέτω, ἢν κατεπείγῃ· εἶτα ἐπανίτω λυθείς, ὁπόταν ἐκεῖνα καλῇ· καὶ πρὸς πάντα σπευδέτω καὶ ὡς δυνατὸν ὁμοχρονείτω καὶ μεταπετέσθω ἀπ’ Ἀρμενίας μὲν εἰς Μηδίαν, ἐκεῖθεν δὲ ῥοιζήματι ἑνὶ εἰς Ἰβηρίαν, εἶτα εἰς Ἰταλίαν, ὡς μηδενὸς καιροῦ ἀπολείποιτο.", "st": "53.50"}, {"sp": "N", "t": "μάλιστα δὲ κατόπτρῳ ἐοικυῖαν παρασχέσθω τὴν γνώμην ἀθόλῳ καὶ στιλπνῷ καὶ ἀκριβεῖ τὸ κέντρον, καὶ ὁποίας ἂν δέξηται τὰς μορφὰς τῶν ἔργων, τοιαῦτα καὶ δεικνύτω αὐτά, διάστροφον δὲ ἢ παράχρουν ἢ ἑτερόσχημον μηδέν· οὐ γὰρ ὥσπερ τοῖς ῥήτορσι γράφουσιν, ἀλλὰ τὰ μὲν λεχθησόμενα ἔστι καὶ εἰρήσεται· πέπρακται γὰρ ἤδη· δεῖ δὲ τάξαι καὶ εἰπεῖν αὐτά. ὥστε οὐ τί εἴπωσι ζητητέον αὐτοῖς, ἀλλ’ ὅπως εἴπωσιν. ὅλως δὲ νομιστέον τὸν ἱστορίαν συγγράφοντα Φειδίᾳ χρῆναι ἢ Πραξιτέλει ἐοικέναι ἢ Ἀλκαμένει ἢ τῳ ἄλλῳ ἐκείνων. οὐδὲ γὰρ οὐδ’ ἐκεῖνοι χρυσὸν ἢ ἄργυρον ἢ ἐλέφαντα ἢ τὴν ἄλλην ὕλην ἐποίουν, ἀλλ’ ἡ μὲν ὑπῆρχε καὶ προϋπεβέβλητο, Ἠλείων ἢ Ἀθηναίων ἢ Ἀργείων πεπορισμένων, οἱ δὲ ἔπλαττον μόνον καὶ ἔπριον τὸν ἐλέφαντα καὶ ἔξεον καὶ ἐκόλλων καὶ ἐρρύθμιζον καὶ ἐπήνθιζον τῷ χρυσῷ, καὶ τοῦτο ἦν ἡ τέχνη αὐτοῖς ἐς δέον οἰκονομήσασθαι τὴν ὕλην. τοιοῦτο δή τι καὶ τὸ τοῦ συγγραφέως ἔργον, εἰς καλὸν διαθέσθαι τὰ πεπραγμένα καὶ εἰς δύναμιν ἐναργέστατα ἐπιδεῖξαι αὐτά. καὶ ὅταν τις ἀκροώμενος οἴηται μετὰ ταῦτα ὁρᾶν τὰ λεγόμενα καὶ μετὰ τοῦτο ἐπαινῇ, τότε δὴ τότε ἀπηκρίβωται καὶ τὸν σἰκεῖον ἔπαινον ἀπείληφε τὸ ἔργον τῷ τῆς ἱστορίας Φειδίᾳ.", "st": "53.51"}, {"sp": "N", "t": "πάντων δὲ ἤδη παρεσκευασμένων, καὶ ἀπροοιμίαστον μέν ποτε ποιήσεται τὴν ἀρχήν, ὁπόταν μὴ πάνυ κατεπείγῃ τὸ πρᾶγμα προδιοικήσασθαί τι ἐν τῷ προοιμίῳ· δυνάμει δὲ καὶ τότε φροιμίῳ χρήσεται τῷ ἀποσαφοῦντι περὶ τῶν λεκτέων.", "st": "53.52"}, {"sp": "N", "t": "ὁπόταν δὲ καὶ φροιμιάζηται, ἀπὸ δυοῖν μόνον ἄρξεται, οὐχ ὥσπερ οἱ ῥήτορες ἀπὸ τριῶν, ἀλλὰ τὸ τῆς εὐνοίας παρεὶς προσοχὴν καὶ εὐμάθειαν εὐπορήσει τοῖς ἀκούουσι. προσέξουσι μὲν γὰρ αὐτῷ, ἢν δείξῃ ὡς περὶ μεγάλων ἢ ἀναγκαίων ἢ οἰκείων ἢ χρησίμων ἐρεῖ· εὐμαθῆ δὲ καὶ σαφῆ τὰ ὕστερον ποιήσει, τὰς αἰτίας προεκτιθέμενος καὶ περιορίζων τὰ κεφάλαια τῶν γεγενημένων.", "st": "53.53"}, {"sp": "N", "t": "τοιούτοις προοιμίοις οἱ ἄριστοι τῶν συγγραφέων ἐχρήσαντο, Ἡρόδοτος μέν, ὡς μὴ τὰ γενόμενα ἐξίτηλα τῷ χρόνῳ γένηται, μεγάλα καὶ θαυμαστὰ ὄντα, καὶ ταῦτα νίκας Ἑλληνικὰς δηλοῦντα καὶ ἥττας βαρβαρικάς· Θου κυδίδης δέ, μέγαν τε καὶ αὐτὸς ἐλπίσας ἔσεσθαι καὶ ἀξιολογώτατον καὶ μείζω τῶν προγεγενημένων ἐκεῖνον τὸν πόλεμον· καὶ γὰρ παθήματα ἐν αὐτῷ μεγάλα ξυνέβη γενέσθαι.", "st": "53.54"}, {"sp": "N", "t": "μετὰ δὲ τὸ προοίμιον, ἀνάλογον τοῖς πράγμασιν ἢ μηκυνόμενον ἢ βραχυνόμενον, εὐαφὴς καὶ εὐάγωγος ἔστω ἡ ἐπὶ τὴν διήγησιν μετάβασις· ἅπαν γὰρ ἀτεχνῶς τὸ λοιπὸν σῶμα τῆς ἱστορίας διήγησις μακρά ἐστιν· ὥστε ταῖς τῆς διηγήσεως ἀρεταῖς κατακεκοσμήσθω, λείως τε καὶ ὁμαλῶς προϊοῦσα καὶ αὐτὴ ὁμοίως, ὥστε μὴ προὔχειν μηδὲ κοιλαίνεσθαι· ἔπειτα τὸ σαφὲς ἐπανθείτω, τῇ τε λέξει, ὡς ἔφην, μεμηχανημένον καὶ τῇ συμπεριπλοκῇ τῶν πραγμάτων. ἀπόλυτα γὰρ καὶ ἐντελῆ πάντα ποιήσει, καὶ τὸ πρῶτον ἐξεργασάμενος ἐπάξει τὸ δεύτερον ἐχόμενον αὐτοῦ καὶ ἁλύσεως τρόπον συνηρμοσμένον, ὡς μὴ διακεκόφθαι μηδὲ διηγήσεις πολλὰς εἶναι ἀλλήλαις παρακειμένας, ἀλλ’ ἀεὶ τὸ πρῶτον τῷ δευτέρῳ μὴ γειτνιᾶν μόνον, ἀλλὰ καὶ κοινωνεῖν καὶ ἀνακεκρᾶσθαι κατὰ τὰ ἄκρα.", "st": "53.55"}, {"sp": "N", "t": "τάχος ἐπὶ πᾶσι χρήσιμον, καὶ μάλιστα εἰ μὴ ἀπορία τῶν λεκτέων εἴη· καὶ τοῦτο πορίζεσθαι χρὴ μὴ τοσοῦτον ἀπὸ τῶν ὀνομάτων ἢ ῥημάτων, ὅσον ἀπὸ τῶν πραγμάτων· λέγω δέ, εἰ παραθέοις μὲν τὰ μικρὰ καὶ ἧττον ἀναγκαῖα, λέγοις δὲ ἱκανῶς τὰ μεγάλα· μᾶλλον δὲ καὶ παραλειπτέον πολλά. οὐδὲ γὰρ ἢν ἑστιᾷς τοὺς φίλους καὶ πάντα ᾖ παρεσκευασμένα, διὰ τοῦτο ἐν μέσοις τοῖς πέμμασι καὶ τοῖς ὀρνέοις καὶ λοπάσι τοσαύταις καὶ συσὶν ἀγρίοις καὶ λαγωοῖς καὶ ὑπογαστρίοις καὶ σαπέρδην ἐνθήσεις καὶ ἔτνος, ὅτι κἀκεῖνο παρεσκεύαστο, ἀμελήσεις δὲ τῶν εὐτελεστέρων.", "st": "53.56"}, {"sp": "N", "t": "μάλιστα δὲ σωφρονητέον ἐν ταῖς τῶν ὀρῶν ἢ τειχῶν ἢ ποταμῶν ἑρμηνείαις, ὡς μὴ δύναμιν λόγων ἀπειροκάλως παρεπιδείκνυσθαι δοκοίης καὶ τὸ σαυτοῦ δρᾶν παρεὶς τὴν ἱστορίαν, ἀλλ’ ὀλίγον προσαψάμενος, τοῦ χρησίμου καὶ σαφοῦς ἕνεκα, μεταβήσῃ ἐκφυγὼν τὸν ἰξὸν τὸν ἐν τῷ πράγματι καὶ τὴν τοιαύτην ἅπασαν λιχνείαν, οἷον ὁρᾷς καὶ Ὅμηρος ὁ μεγαλόφρων ποιεῖ· καίτοι ποιητὴς ὢν παραθεῖ τὸν Τάνταλαν καὶ τὸν Ἰξίονα καὶ τὸν Τιτυὸν καὶ τοὺς ἄλλους. εἰ δὲ Παρθένιος ἢ Εὐφορίων ἢ Καλλίμαχος ἔλεγε, πόσοις ἂν οἴει ἔπεσι τὸ ὕδωρ ἄχρι πρὸς τὸ χεῖλος τοῦ Ταντάλου ἤγαγεν; εἶτα πόσοις ἂν Ἰξίονα ἐκύλισε; μᾶλλον δὲ ὁ Θουκυδίδης αὐτὸς ὀλίγα τῷ τοιούτῳ εἴδει τοῦ λόγου χρησάμενος σκέψαι ὅπως εὐθὺς ἀφίσταται ἢ μηχάνημα ἑρμηνεύσας ἢ πολιορκίας σχῆμα δηλώσας, ἀναγκαῖον καὶ χρειῶδες ὄν, ἢ Ἐπιπολῶν σχῆμα ἢ Συρακουσίων λιμένα· ὅταν μὲν γὰρ τὸν λοιμὸν διηγῆται καὶ μακρὸς εἶναι δοκῇ, σὺ τὰ πράγματα ἐννόησον· εἴσῃ γὰρ οὕτω τὸ τάχος καὶ ὡς φεύγοντος ὅμως ἐπιλαμβάνεται αὐτοῦ τὰ γεγενημένα πολλὰ ὄντα.", "st": "53.57"}, {"sp": "N", "t": "ἢν δέ ποτε καὶ λόγους ἐροῦντά τινα δεήσῃ εἰσάγειν, μάλιστα μὲν ἐοικότα τῷ προσώπῳ καὶ τῷ πράγματι οἰκεῖα λεγέσθω, ἔπειτα ὡς σαφέστατα καὶ ταῦτα. πλὴν ἐφεῖταί σοι τότε καὶ ῥητορεῦσαι καὶ ἐπιδεῖξαι τὴν τῶν λόγων δεινότητα.", "st": "53.58"}, {"sp": "N", "t": "ἔπαινοι μὲν γὰρ ἢ ψόγοι πάνυ πεφεισμένοι καὶ περιεσκεμμένοι καὶ ἀσυκοφάντητοι καὶ μετὰ ἀποδείξεων καὶ ταχεῖς καὶ μὴ ἄκαιροι, ἐπεὶ ἔξω τοῦ δικαστηρίου ἐκεῖνοί εἰσι, καὶ τὴν αὐτὴν Θεοπόμπῳ αἰτίαν ἕξεις φιλαπεχθημόνως κατηγοροῦντι τῶν πλείστων καὶ διατριβὴν ποιουμένῳ τὸ πρᾶγμα, ὡς κατηγορεῖν μᾶλλον ἢ ἱστορεῖν τὰ πεπραγμένα.", "st": "53.59"}, {"sp": "N", "t": "καὶ μὴν καὶ μῦθος εἴ τις παρεμπέσοι, λεκτέος μέν, οὐ μὴν πιστωτέος πάντως, ἀλλ’ ἐν μέσῳ θετέος τοῖς ὅπως ἂν ἐθέλωσιν εἰκάσουσι περὶ αὐτοῦ· σὺ δ’ ἀκίνδυνος καὶ πρὸς οὐδέτερον ἐπιρρεπέστερος.", "st": "53.60"}, {"sp": "N", "t": "τὸ δ’ ὅλον ἐκείνου μοι μέμνησο — πολλάκις γὰρ τοῦτο ἐρῶ — καὶ μὴ πρὸς τὸ παρὸν μόνον ὁρῶν γράφε, ὡς οἱ νῦν ἐπαινέσονταί σε καὶ τιμήσουσιν, ἀλλὰ τοῦ σύμπαντος αἰῶνος ἐστοχασμένος πρὸς τοὺς ἔπειτα μᾶλλον σύγγραφε καὶ παρ’ ἐκείνων ἀπαίτει τὸν μισθὸν τῆς γραφῆς, ὡς λέγηται καὶ περὶ σοῦ· “ἐκεῖνος μέντοι ἐλεύθερος ἀνὴρ ἦν καὶ παρρησίας μεστός, οὐδὲν οὔτε κολακευτικὸν οὔτε δουλοπρεπές, ἀλλ’ ἀλήθεια ἐπὶ πᾶσι.” τοῦτ’, εἰ σωφρονοίη τις, ὑπὲρ πάσας τὰς νῦν ἐλπίδας θεῖτο ἄν, οὕτως ὀλιγοχρονίους οὔσας.", "st": "53.61"}, {"sp": "N", "t": "ὁρᾷς τὸν Κνίδιον ἐκεῖνον ἀρχιτέκτονα, οἷον ἐποίησεν; οἰκοδομήσας γὰρ τὸν ἐπὶ τῇ Φάρῳ πύργον, μέγιστον καὶ κάλλιστον ἔργων ἁπάντων, ὡς πυρσεύοιτο ἀπ’ αὐτοῦ τοῖς ναυτιλλομένοις ἐπὶ πολὺ τῆς θαλάττης καὶ μὴ καταφέροιντο εἰς τὴν Παραιτονίαν, παγχάλεπον, ὥς φασιν, οὖσαν καὶ ἄφυκτον, εἴ τις ἐμπέσοι εἰς τὰ ἕρματα· οἰκοδομήσας οὖν αὐτὸ τὸ ἔργον ἔνδοθεν μὲν κατὰ τῶν λίθων τὸ αὐτοῦ ὄνομα ἔγραψεν, ἐπιχρίσας δὲ τιτάνῳ καὶ ἐπικαλύψας ἐπέγραψε τοὔνομα τοῦ τότε βασιλεύοντος, εἰδώς, ὅπερ καὶ ἐγένετο, πάνυ ὀλίγου χρόνου συνεκπεσούμενα μὲν τῷ χρίσματι τὰ γράμματα, ἐκφανησόμενον δέ, “Σώστρατος Δεξιφάνους Κνίδιος θεοῖς σωτῆρσιν ὑπὲρ τῶν πλωϊζομένων.” οὕτως οὐδ’ ἐκεῖνος ἐς τὸν τότε καιρὸν οὐδὲ τὸν αὐτοῦ βίον τὸν ὀλίγου ἑώρα, ἀλλ’ εἰς τὸν νῦν καὶ τὸν ἀεί, ἄχρι ἂν ἑστήκῃ ὁ πύργος καὶ μένῃ αὐτοῦ ἡ τέχνη.", "st": "53.62"}, {"sp": "N", "t": "χρὴ τοίνυν καὶ τὴν ἱστορίαν οὕτω γράφεσθαι σὺν τῷ ἀληθεῖ μᾶλλον πρὸς τὴν μέλλουσαν ἐλπίδα ἤπερ σὺν κολακείᾳ πρὸς τὸ ἡδὺ τοῖς νῦν ἐπαινουμένοις. οὗτός σοι κανων καὶ στάθμη ἱστορίας δικαίας. καὶ εἰ μὲν σταθμήσονταί τινες αὐτῇ, εὖ ἂν ἔχοι καὶ εἰς δέον ἡμῖν γέγραπται, εἰ δὲ μή, κεκύλισται ὁ πίθος ἐν Κρανείῳ.", "st": "53.63"}, {"sp": "HDR", "t": "Περὶ τῶν Διψάδων"}, {"sp": "N", "t": "τῆς Λιβύης τὰ νότια ψάμμος ἐστὶ βαθεῖα καὶ γῆ διακεκαυμένη, ἔρημος ἐπὶ πολύ, ἀκριβῶς ἄκαρπος, πεδινὴ ἅπασα, οὐ χλόην οὐ πόαν οὐ φυτὸν οὐχ ὕδωρ ἔχουσα, ἢ εἴ που ἄρα ἐν κοίλοις συνεστηκὸς ὑετοῦ ὀλίγου λείψανον, παχὺ καὶ τοῦτο καὶ δυσῶδες, οὐδὲ πάνυ διψῶντι ἀνθρώπῳ πότιμον. ἀοίκητος γοῦν ἐστι διὰ ταῦτα· ἢ πῶς γὰρ ἂν οἰκοῖτο ἀνήμερος οὕτω καὶ ξηρὰ καὶ ἄφορος οὖσα καὶ πολλῷ τῷ αὐχμῷ πιεζομένη; καὶ τὸ θάλπος δὲ αὐτὸ καὶ ὁ ἀὴρ κομιδῇ πυρώδης καὶ φλογερὸς ὢν καὶ ἡ ψάμμος ὑπερζέουσα παντελῶς ἄβατον τὴν χώραν τίθησι.", "st": "54.1"}, {"sp": "N", "t": "Γαράμαντες μόνοι πρόσοικοι ὄντες, εὐσταλὲς καὶ κοῦφον ἔθνος, ἄνθρωποι σκηνῖται, ἀπὸ θήρας τὰ πολλὰ ζῶντες, ἐνίοτε οὗτοι ἐσβάλλουσι θηράσοντες ἀμφὶ τροπὰς τὰς χειμερινὰς μάλιστα, ὕοντα τὸν θεὸν τηρήσαντες, ὁπότε τὸ πολὺ τοῦ καύματος σβεσθείη καὶ ἡ ψάμμος νοτισθείη καὶ ἀμηέπη βατὴ γένοιτο. ἡ θήρα δέ ἐστιν ὄνων τε τῶν ἀγρίων καὶ στρουθῶν τῶν μεγάλων χαμαιπετῶν καὶ πιθήκων μάλιστα καὶ ἐλεφάντων ἐνίοτε· ταῦτα γὰρ μόνα διαρκεῖ πρὸς τὸ δίψος καὶ ἀνέχεται ἐπὶ πολὺ ταλαιπωρούμενα ὑπὸ πολλῷ καὶ ὀξεῖ τῷ ἡλίῳ. καὶ ὅμως οἱ Γαράμαντες ἐπειδὰν τὰ σιτία καταναλώσωσιν ἅπερ ἔχοντες ἀφίκοντο, ἀπελαύνουσιν ὀπίσω εὐθὺς δεδιότες μὴ σφίσιν ἡ ψάμμος ἀναφλεγεῖσα δύσβατος καὶ ἄπορος γένηται, εἶτα ὥσπερ ἐντὸς ἀρκύων ληφθέντες καὶ αὐτοὶ ἀπόλωνται μετὰ τῆς ἄγρας· ἄφυκτα γάρ ἐστιν, ἢν ὁ ἥλιος ἀνασπάσας τὴν ἰκμάδα καὶ τάχιστα ξηράνας τὴν χώραν ὑπερζέσῃ, ἀκμαιοτέραν τὴν ἀκτῖνα προσβαλὼν ἅτε πρὸς τὴν νοτίδα παρατεθηγμένην· τροφὴ γὰρ αὕτη τῷ πυρί.", "st": "54.2"}, {"sp": "N", "t": "καίτοι ταῦτα πάντα ὁπόσα εἶπον, τὸ θάλπος, τὸ δίψος, ἡ ἐρημία, τὸ μηδὲν ἔχειν ἐκ τῆς γῆς λαβεῖν, ἧττον ὑμῖν δυσχερῆ εἶναι δόξει τοῦ λεχθησομένου, καὶ δι’ ὃ φευκτέα πάντως ἡ χώρα ἐκείνη· ἑρπετὰ γὰρ ποικίλα μεγέθει τε μέγιστα καὶ πλήθει πάμπολλα καὶ τὰς μορφὰς ἀλλόκοτα καὶ τὸν ἰὸν ἄμαχα ἐπινέμεται τὴν γῆν, τὰ μὲν ὑποβρύχια, φωλεύοντα ἐν μυχῷ τῆς ψάμμου, τὰ δὲ ἄνω ἐπιπολάζοντα, φύσαλοι καὶ ἀσπίδες καὶ ἔχιδναι καὶ κεράσται καὶ βουπρήστεις καὶ ἀκοντίαι καὶ ἀμφίσβαιναι καὶ δράκοντες καὶ σκορπίων γένος διττόν, τὸ μὲν ἕτερον ἐπίγειόν τε καὶ πεζόν, ὑπέρμεγα καὶ πολυσφόνδυλον, θάτερον δὲ ἐναέριον καὶ πτηνόν, ὑμενόπτερον δὲ οἷα ταῖς ἀκρίσι καὶ τέττιξι καὶ νυκτερίσι τὰ πτερά. τοιαῦτα ὄρνεα πολλὰ ἐπιπετόμενα οὐκ εὐπρόσιτον ἀπεργάζεται τὴν Λιβύην ἐκείνην.", "st": "54.3"}, {"sp": "N", "t": "τὸ δὲ δὴ πάντων ἑρπετῶν δεινότατον ὧν ἡ ψάμμος τρέφει, ἡ διψάς ἐστιν, ὄφις οὐ πάνυ μέγας, ἐχίδνῃ ὅμοιος, τὸ δῆγμα βίαιος, τὸν ἰὸν ταχύς, ὀδύνας μὲν ἀλήκτους ἐπάγων εὐθύς· ἐκκαίει τε γὰρ καὶ σήπει καὶ πίμπρασθαι ποιεῖ, καὶ βοῶσιν ὥσπερ οἱ ἐν πυρᾷ κείμενοι. τὸ δὲ μάλιστα καταπονοῦν καὶ κατατρῦχον αὐτοὺς ἐκεῖνό ἐστιν, ὁμώνυμον πάθος τῷ ἑρπετῷ· διψῶσι γὰρ εἰς ὑπερβολήν, καὶ τὸ παραδοξότατον, ὅσῳπερ ἂν πίνωσι, τοσούτῳ μᾶλλον ὀρέγονται τοῦ ποτοῦ, καὶ ἡ ἐπιθυμία πολὺ πλέον ἐπιτείνεται αὐτοῖς· οὐδ’ ἂν σβέσειάς ποτε τὸ δίψος, οὐδ’ ἢν τὸν Νεῖλον αὐτὸν ἢ τὸν Ἴστρον ὅλον ἐκπιεῖν παράσχῃς, ἀλλα προσεκκαύσεις ἐπάρδων τὴν νόσον, ὥσπερ ἂν εἴ τις ἐλαίῳ πῦρ κατασβεννύοι.", "st": "54.4"}, {"sp": "N", "t": "λέγουσιν ἰατρῶν παῖδες ἐκείνην τὴν αἰτίαν εἶναι, παχὺν τὸν ἰὸν ὄντα ἔπειτα δευόμενον τῷ ποτῷ ὀξυκίνητον γίγνεσθαι, ὑγρότερον, ὡς τὸ εἰκός, καθιστάμενον καὶ ἐπὶ πλεῖστον διαχεόμενον.", "st": "54.5"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν οὐδένα τοῦτο πεπονθότα εἶδον, μηδέ, ὦ θεοί, ἴδοιμι οὕτω κολαζόμενον ἄνθρωπον, ἀλλ’ οὐδὲ ἐπέβην τῆς Λιβύης τὸ παράπαν εὖ ποιῶν· ἐπίγραμμα δέ τι ἤκουσα, ὅ μοι τῶν ἑταίρων τις ἔλεγεν αὐτος ἐπὶ στήλης ἀνεγνωκέναι ἀνδρὸς οὕτως ἀποθανόντος· ἐκ Λιβυης ἔφη ἀπιὼν ἐς Αἴγυπτον παρὰ τὴν μεγάλην Σύρτιν ποιεῖσθαι τὴν πορείαν· οὐ γὰρ εἶναι ἄλλως· ἔνθα δὴ ταφῳ ἐντυχεῖν παρὰ τὴν ἠϊόνα ἐπ’ αὐτῷ τῷ κλύσματι καὶ στήλην ἐφεστάναι δηλοῦσαν τοῦ ὀλέθρου τὸν τρόπον· κεκολάφθαι γὰρ ἐπ’ αὐτῇ ἄνθρωπον μὲν τινα οἷον τὸν Τάνταλον γράφουσιν ἐν λίμνῃ ἑστῶτα καὶ ἀρυομενον τοῦ ὕδατος, ὡς πίοι δή, τὸ θηρίον δὲ τὴν διψάδα ἐμπεφυκὸς αὐτῷ περιεσπειρᾶσθαι τῷ ποδί, καί τινας γυναῖκας ὑδροφορούσας ἅμα πολλὰς καταχεῖν τὸ ὕδωρ αὐτοῦ πλησίον δὲ ᾠὰ κεῖσθαι οἷα τῶν στρουθῶν ἐκείνων, οὓς ἔφην θηρᾶν τοὺς Γαράμαντας· γεγράφθαι δὲ πρὸς τοὐπίγραμμα, οὐ χεῖρον δὲ καὶ αὐτὸ εἰπεῖν,<br>τοῖα παθόντ’, οἶμαι, καὶ Τάνταλον αἴθοπος ἰοῦ<br>μηδαμὰ κοιμῆσαι διψαλέην ὀδύνην.<br>καὶ Δαναοῖο κόρας τοῖον πίθον οὐκ ἀναπλῆσαι<br>αἰὲν ἐπαντλούσας ὑδροφόρῳ καμάτῳ.<br>ἔτι καὶ ἄλλα ἔπη τέτταρά ἐστι περὶ τῶν ᾠῶν, καὶ ὡς ἀναιρούμενος αὐτὰ ἐδήχθη· ἀλλ’ οὐκέτι μέμνημαι ἐκείνων.", "st": "54.6"}, {"sp": "N", "t": "συλλέγουσι δὲ ἄρα τὰ ᾠὰ καὶ ἐσπουδάκασι περὶ αὐτὰ οἱ περίοικοι, οὐχ ὡς φαγεῖν μόνον, ἀλλὰ καὶ σκεύεσι χρῶνται κενώσαντες καὶ ἐκπώματα ποιοῦνται ἀπ’ αὐτῶν· οὐ γὰρ ἔχουσι κεραμεύειν διὰ τὸ ψάμμον εἶναι τὴν γῆν. εἰ δὲ καὶ μεγάλα εὑρεθείη, καὶ πῖλοι γίγνονται δύο ἐκ τοῦ ᾠοῦ ἑκάστου· τὸ γὰρ ἡμίτομον ἑκάτερον ἀποχρῶν τῇ κεφαλῇ πῖλός ἐστιν.", "st": "54.7"}, {"sp": "N", "t": "ἐκεῖ τοίνυν λοχῶσιν αἱ διψάδες παρὰ τὰ ᾠά, καὶ ἐπειδὰν προσέλθῃ ὁ ἄνθρωπος, ἐκ τῆς ψάμμου ἐξερπύσασαι δάκνουσι τὸν κακοδαίμονα· ὁ δὲ πάσχει ἐκεῖνα τὰ μικρὸν ἔμπροσθεν εἰρημένα πίνων ἀεὶ καὶ μᾶλλον διψῶν καὶ πιμπλάμενος οὐδέποτε.", "st": "54.8"}, {"sp": "N", "t": "ταυτὶ οὐ μὰ Δία πρὸς Νίκανδρον τὸν ποιητὴν φιλοτιμούμενος διεξῆλθον, οὐδ’ ὅπως ὑμεῖς μάθοιτε ὡς οὐκ ἀμελὲς γεγένηταί μοι φύσεις τῶν Λιβυκῶν ἑρπετῶν εἰδέναι· ἰατρῶν γὰρ ἂν μᾶλλον ὁ ἔπαινος εἴη, οἷς ἀνάγκη εἰδέναι ταῦτα, ὡς καὶ ἀμύνασθαι αὐτὰ μετὰ τῆς τέχνης ἔχοιεν· ἀλλά μοι δοκῶ — καὶ πρὸς φιλίου μὴ δυσχεράνητε τὴν εἰκόνα θηριώδη οὖσαν — ὅμοιόν τι καὶ αὐτὸς παθεῖν πρὸς ὑμᾶς, οἷον ἐκεῖνοι πάσχουσι πρὸς τὸ ποτὸν οἱ δηχθέντες ὑπὸ τῆς διψάδος· ὅσῳ γὰρ ἂν ἐπὶ πλέον παρίω ἐς ὑμᾶς, τοσούτῳ μᾶλλον ὀρέγομαι τοῦ πράγματος καὶ τὸ δίψος ἄσχετον ὑπεκκαίεταί μοι καὶ ἔοικα οὐδ’ ἐμπλησθήσεσθαί ποτε τοῦ τοιούτου ποτοῦ. μάλα εἰκότως. ποῦ γὰρ ἂν οὕτω διειδεῖ τε καὶ καθαρῷ ὕδατι ἐντύχοιμι; ὥστε σύγγνωτε, εἰ δηχθεὶς καὶ αὐτος τὴν ψυχὴν ἡδίστῳ τούτῳ καὶ ὑγιεινοτάτῳ τῷ δήγματι ἐμφοροῦμαι χανδὸν ὑποθεὶς τῷ κρουνῷ τὴν κεφαλήν· εἴη μόνον μὴ ἐπιλιπεῖν τὰ παρ’ ὑμῶν ἐπιρρέοντα μηδὲ χυθεῖσαν τὴν σπουδὴν τῆς ἀκροάσεως κεχηνότα ἔτι καὶ διψῶντα καταλιπεῖν· ὡς δίψους γε ἕνεκα τοὐμοῦ πρὸς ὑμᾶς οὐδὲν ἂν ἐκώλυε πίνειν ἀεί· κατὰ γὰρ τὸν σοφὸν Πλάτωνα κόρος οὐδεὶς τῶν καλῶν.", "st": "54.9"}, {"sp": "HDR", "t": "Τὰ πρὸς Κρόνον"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> ὦ κρόνε, σὺ γὰρ ἔοικας ἄρχειν τό γε νῦν εἶναι καὶ σοὶ τέθυται καὶ κεκαλλιέρηται παρ’ ἡμῶν, τί ἂν μάλιστα ἐπὶ τῶν ἱερῶν αἰτήσας λάβοιμι παρὰ σοῦ;", "st": "55.1"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> τοῦτο μὲν αὐτόν σε καλῶς ἔχει ἐσκέφθαι ὅ τι σοι εὐκταῖον, εἰ μὴ καὶ μάντιν ἅμα ἐθέλεις εἶναι τὸν ἄρχοντα, εἰδέναι τί σοι ἥδιον αἰτεῖν· ἐγὼ δὲ τά γε δυνατὰ οὐκ ἀνανεύσω πρὸς τὴν εὐχήν.", "st": "55.1"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> ἀλλὰ πάλαι ἔσκεμμαι· ἐρῶ γὰρ τὰ κοινὰ ταυτὶ καὶ πρόχειρα, πλοῦτον καὶ χρυσὸν πολὺν καὶ ἀγρῶν δεσπότην εἶναι καὶ ἀνδράποδα πολλὰ κεκτῆσθαι καὶ ἐσθῆτας εὐανθεῖς καὶ μαλακὰς καὶ ἄργυρον καὶ ἐλέφαντα καὶ τἆλλα ὁπόσα τίμια. τούτων οὖν, ὦ ἄριστε Κρόνε, δίδου μοι, ὥς τι καὶ αὐτὸν ἀπολαῦσαι τῆς σῆς ἀρχῆς μηδὲ ἄμοιρον εἶναι μόνον αὐτὸν διὰ παντὸς τοῦ βίου.", "st": "55.1"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> ὁρᾷς; οὐ κατ’ ἐμὲ τοῦτο ᾔτησας· οὐ γὰρ ἐμὸν διανέμειν τὰ τοιαῦτα. ὥστε μὴ ἄχθου, εἰ ἀτυχήσειας αὐτῶν, ἀλλ’ αἴτει παρὰ τοῦ Διός, ὁπόταν εἰς ἐκεῖνον ἡ ἀρχὴ περιέλθῃ μετ’ ὀλίγον. ἐγὼ δ’ ἐπὶ ῥητοῖς παραλαμβάνω τὴν δυναστείαν· ἑπτὰ μὲν ἡμερῶν ἡ πᾶσα βασιλεία, καὶ ἢν ἐκπρόθεσμος τούτων γένωμαι, ἰδιώτης εὐθύς εἰμι καὶ τοῦ πολλοῦ δήμου εἷς· ἐν αὐταῖς δὲ ταῖς ἑπτὰ σπουδαῖον μὲν οὐδὲν οὐδὲ ἀγοραῖον διοικήσασθαί μοι συγκεχώρηται, πίνειν δὲ καὶ μεθύειν καὶ βοᾶν καὶ παίζειν καὶ κυβεύειν καὶ ἄρχοντας καθιστάναι καὶ τοὺς οἰκέτας εὐωχεῖν καὶ γυμνὸν ᾅδειν καὶ κροτεῖν ὑποτρέμοντα, ἐνίοτε δὲ καὶ ἐς ὕδωρ ψυχρὸν ἐπὶ κεφαλὴν ὠθεῖσθαι ἀσβόλῳ κεχρισμένον τὸ πρόσωπον, ταῦτα ἐφεῖταί μοι ποιεῖν. τὰ μεγάλα δὲ ἐκεῖνα, τὸν πλοῦτον καὶ τὸ χρυσίον, ὁ Ζεὺς διαδίδωσιν οἷς ἂν ἐθέλῃ.", "st": "55.2"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> ἀλλ’ οὐδ’ ἐκεῖνος, ὦ Κρόνε, ῥᾳδίως καὶ προχείρως. ἐγὼ γοῦν ἤδη ἀπηγόρευκα αἰτῶν μεγάλῃ τῇ φωνῇ, ὁ δ’ οὐκ ἐπαΐει τὸ παράπαν, ἀλλὰ τὴν αἰγίδα ἐπισείων καὶ τὸν κεραυνὸν ἐπανατεινόμενος δριμὺ ἐνορῶν ἐκπλήττει τοὺς ἐνοχλοῦντας· ἢν δέ ποτε καὶ ἐπινεύσῃ τινὶ καὶ πλούσιον ποιῇ, πολὺ τὸ ἄκριτον ἐνταῦθα, καὶ τοὺς ἀγαθοὺς ἐνίοτε καὶ συνετοὺς ἀφεὶς ὁ δὲ παμπονήροις τε καὶ ἀνοήτοις ἀνδράσι περιχεῖ τὸν πλοῦτον, μαστιγίαις ἢ ἀνδρογύνοις τοῖς πλείστοις αὐτῶν. πλὴν τά γε σοὶ δυνατὰ ἐθέλω εἰδέναι τίνα ταῦτά ἐστιν.", "st": "55.3"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> οὐ μικρὰ ὅλως οὐδὲ παντάπασιν εὐκαταφρόνητα ὡς πρὸς τὴν δύναμιν ἐξετάζεσθαι τῆς συμπάσης ἀρχῆς, εἰ μή σοί γε μικρὸν δοκεῖ τὸ νικᾶν κυβεύοντα καὶ τοῖς ἄλλοις ἐς τὴν μονάδα κυλιομένου τοῦ κύβου σοὶ τὴν ἑξάδα ὑπεράνω ἀεὶ φαίνεσθαι· πολλοὶ γοῦν ἐς κόρον ἀπὸ τοῦ τοιούτου ἐπεσιτίσαντο, οἷς ἵλεως καὶ φορὸς ὁ κύβος ἐπινεύσει· οἱ δὲ ἔμπαλιν γυμνοὶ ἐξενήξαντο συντριβέντος αὐτοῖς τοῦ σκάφους περὶ οὕτω μικρῷ ἕρματι τῷ κύβῳ. καὶ μὴν καὶ πιεῖν ἐς τὸ ἥδιστον καὶ ᾠδικώτερον ἄλλου δόξαι ᾆσαι ἐν τῷ συμποσίῳ καὶ διακονουμένων τοὺς μὲν ἄλλους ἐς τὸ ὕδωρ ἐμπεσεῖν — τοῦτο γὰρ τοὐπιτίμιον τῆς ἀδεξίου διακονίας — σὲ δὲ ἀνακηρυχθῆναι καλλίνικον καὶ τἆθλα φέρεσθαι τὸν ἀλλᾶντα ὁρᾷς ἡλίκον τὸ ἀγαθόν; ἔτι καὶ βασιλέα μόνον ἐφ’ ἁπάντων γενέσθαι τῷ ἀστραγάλῳ κρατήσαντα, ὡς μήτε ἐπιταχθείης γελοῖα ἐπιτάγματα καὶ αὐτὸς ἐπιτάττειν ἔχοις, τῷ μὲν αἰσχρόν τι περὶ αὐτοῦ ἀναβοῆσαι, τῷ δὲ γυμνὸν ὀρχήσασθαι καὶ ἀράμενον τὴν αὐλητρίδα τρὶς τὴν οἰκίαν περιελθεῖν, πῶς οὐχὶ καὶ ταῦτα δείγματα μεγαλοδωρίας τῆς ἐμῆς; εἰ δὲ τὸ μὴ ἀληθῆ μηδὲ βέβαιον γίγνεσθαι τὴν τοιαύτην βασιλείαν αἰτιάσῃ, ἄγνωμον ποιήσεις ὁρῶν αὐτὸν ἐμὲ τὸν ταῦτα διανέμοντα ὀλιγοχρόνιον τὴν ἀρχὴν ἔχοντα. τούτων δ’ οὖν ἅ μοι δυνατὰ δοῦναι, τῶν πεττῶν, τοῦ ἄρχειν, τοῦ ᾅδειν καὶ τῶν ἃ κατηριθμησάμην, θαρρῶν αἴτει, ὡς ἐμοῦ πρὸς οὐδὲν δεδιξομένου σε τῇ αἰγίδι καὶ τῷ κεραυνῷ.", "st": "55.4"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> ἀλλ’, ὦ Τιτάνων ἄριστε, τῶν μὲν τοιούτων οὐ δέομαι, σὺ δὲ ἀλλ’ ἐκεῖνό μοι ἀπόκριναι, ὃ μάλιστα ἐπόθουν εἰδέναι, καὶ μοι ἢν εἴπῃς αὐτό, ἱκανὴν ἔσῃ τὴν ἀμοιβὴν ἀποδεδωκὼς ἀντὶ τῆς θυσίας, καὶ πρὸς τὸ λοιπὸν ἀφίημί σοι τὰ χρέα.", "st": "55.5"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> ἐρώτα μόνον· ἀποκρινοῦμαι γάρ, ἢν εἰδὼς τύχω.", "st": "55.5"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> τὸ μὲν πρῶτον ἐκεῖνο, εἰ ἀληθῆ ταῦτά ἐστιν ἃ περὶ σοῦ ἀκούομεν, ὡς κατήσθιες τὰ γεννώμενα ὑπὸ τῆς Ῥέας, ἐκείνη δὲ ὑφελομένη τὸν Δία λίθον ὑποβαλλομένη ἀντὶ τοῦ βρέφους ἔδωκέ σοι καταπιεῖν, ὁ δὲ εἰς ἡλικίαν ἀφικόμενος ἐξήλασέ σε τῆς ἀρχῆς πολέμῳ κρατήσας, εἶτα ἐς τὸν Τάρταρον φέρων ἐνέβαλε πεδήσας αὐτόν τε καὶ τὸ συμμαχικὸν ἅπαν, ὁπόσον μετὰ σοῦ παρετάττετο.", "st": "55.5"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> εἰ μὴ ἑορτήν, ὦ οὗτος, ἤγομεν καὶ μεθύειν ἐφεῖτο καὶ λοιδορεῖσθαι τοῖς δεσπόταις ἐπ’ ἐξουσίας, ἔγνως ἄν ὡς ὀργίζεσθαι γοῦν ἐφεῖταί μοι, τοιαῦτα ἐρωτήσας, οὐκ αἰδεσθεὶς πολιὸν οὕτω καὶ πρεσβύτην θεόν.", "st": "55.5"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> κἀγὼ ταῦτα, ὦ Κρόνε, οὐ παρ’ ἐμαυτοῦ φημι, ἀλλ’ Ἡσίοδος καὶ Ὅμηρος, ὀκνῶ γὰρ λέγειν ὅτι καὶ οἱ ἄλλοι ἅπαντες ἄνθρωποι σχεδὸν ταῦτα πεπιστεύκας· περὶ σοῦ.", "st": "55.5"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> οἴει γὰρ τὸν ποιμένα ἐκεῖνον,τὸν ἀλαζόνα, ὑγιές τι περὶ ἐμοῦ εἰδέναι; σκόπει δὲ οὕτως. ἔσθ’ ὅστις ἄνθρωπος — οὐ γὰρ θεὸν ἐρῶ — ὑπομείνειεν ἂν ἑκὼν αὐτὸς καταφαγεῖν τὰ τέκνα, εἰ μὴ τις Θυέστης ἦν καὶ ἀσεβεῖ ἀδελφῷ περιπεσὼν ἤσθιε; καὶ τοῦτό γ’ ἂν εἴη, πῶς δ’ ἀγνοήσει λίθον ἀντὶ βρέφους ἐσθίων, εἰ μὴ ἀνάλγητος εἴη τοὺς ὀδόντας; ἀλλ’ οὔτε ἐπολεμήσαμεν οὔτε ὁ Ζεὺς βίᾳ τὴν ἀρχὴν ἀφείλετο, ἑκόντος δέ μου παραδόντος αὐτῷ καὶ ὑπεκστάντος ἄρχειν· ὅτι μὲν γὰρ οὔτε πεπέδημαι οὔτε ἐν τῷ Ταρτάρῳ εἰμί, καὶ αὐτὸς ὁρᾷς, οἶμαι εἰ μὴ τυφλὸς ὥσπερ Ὅμηρος εἶ.", "st": "55.6"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> τί παθὼν δέ, ὦ Κρόνε, ἀφῆκας τὴν ἀρχήν;", "st": "55.7"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> ἐγώ σοι φράσω· τὸ μὲν ὅλου, γέρων ἤδη καὶ ποδαγρὸς ὑπὸ τοῦ κρόνου ὤν — διὸ καὶ πεπεδῆσθαί με οἱ πολλοὶ εἴκασαν —· οὐ γὰρ ἠδυνάμην διαρκεῖν πρὸς οὕτω πολλὴν τὴν ἀδικίαν τῶν νῦν, ἀλλ’ ἀεὶ ἀναθεῖν ἔδει ἄνω καὶ κάτω τὸν κεραυνὸν διηρμένον τοὺς ἐπιόρκους ἢ ἱεροσύλους ἢ βιαίους καταφλέγοντα, καὶ τὸ πρᾶγμα πάνυ ἐργῶδες ἦν καὶ νεανικόν· ἐξέστην οὖν εὖ ποιῶν τῷ Διί. καὶ ἄλλως δὲ καλῶς ἔχειν ἐδόκει μοι διανείμαντα τοῖς παισὶν οὖσι τὴν ἀρχὴν αὐτὸν εὐωχεῖσθαι τὰ πολλὰ ἐφ’ ἡσυχίας οὔτε τοῖς εὐχομένοις χρηματίζοντα οὔτε ὑπὸ τῶν τἀναντία αἰτούντων ἐνοχλούμενον οὔτε βροντῶντα ἢ ἀστράπτοντα ἢ χάλαζαν ἐνίοτε βάλλειν ἀναγκαζόμενον· ἀλλὰ πρεσβυτικόν τινα τοῦτον ἥδιστον βίον διάγω ζωρότερον πίνων τὸ νέκταρ, τῷ Ἰαπετῷ καὶ τοῖς ἄλλοις τοῖς ἡλικιώταις προσμυθολογῶν· ὁ δὲ ἄρχει μυρία ἔχων πράγματα. πλὴν ὀλίγας ταύτας ἡμέρας ἐφ’ οἷς εἶπον ὑπεξελέσθαι μοι ἔδοξε καὶ ἀναλαμβάνω τὴν ἀρχήν, ὡς ὑπομνήσαιμι τοὺς ἀνθρώπους οἷος ἦν ὁ ἐπ’ ἐμοῦ βίος, ὁπότε ἄσπορα καὶ ἀνήροτα πάντα ἐφυετο αὐτοῖς, οὐ στάχυες, ἀλλ’ ἕτοιμος ἄρτος καὶ κρέα ἐσκευασμένα, καὶ ὁ οἶνος ἔρρει ποταμηδόν καὶ πηγαὶ μέλιτος καὶ γάλακτος· ἀγαθοὶ γὰρ ἦσαν καὶ χρυσοῖ ἅπαντες. αὕτη μοι ἡ αἰτία τῆς ὀλιγοχρονίου ταύτης δυναστείας, καὶ διὰ τοῦτο ἁπαν ταχοῦ κρότος καὶ ᾠδὴ καὶ παιδιὰ καὶ ἰσοτιμία πᾶσι καἰ δούλοις καὶ ἐλευθέροις· οὐδεὶς γὰρ ἐπ’ ἐμοῦ δοῦλος ἦν.", "st": "55.7"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> ἐγὼ δέ, ὦ Κρόνε, καὶ τοῦτο εἴκαζον τὸ εἰς τοὺς δούλους καὶ πεδότριβας φιλάνθρωπον ἐκ τοῦ μύθου ἐκείνου ποιεῖν σε τιμῶντα τοὺς τὰ ὅμοια πάσχοντας, ἅτε καὶ αὐτὸν δουλεύοντα, μεμνημένον τῆς πέδης.", "st": "55.8"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> οὐ παύσῃ γὰρ τοιαῦτα ληρῶν;", "st": "55.8"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> εὖ λέγεις, καὶ παύσομαι· πλὴν ἔτι μοι καὶ τοῦτο ἀπόκριναι. τὸ πεττεύειν σύνηθες ἦν καὶ ἐπὶ σοῦ τοῖς ἀνθρώποις;", "st": "55.8"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> καὶ μάλα, οὐ μὴν περὶ ταλάντων γε καὶ μυριάδων ὥσπερ ὑμῖν, ἀλλὰ περὶ καρύων τὸ μέγιστον, ὡς μὴ ἀνιᾶσθαι ἡττηθέντα μηδὲ δακρύειν ἀεὶ ἄσιτον ὄντα μόνον τῶν ἄλλων.", "st": "55.8"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> εὖ γε ἐκεῖνοι ποιοῦντες. ὑπὲρ τίνος γὰρ ἂν καὶ ἐπέττευον αὐτοὶ ὁλόχρυσοι ὄντες; ὡς ἔγωγε καὶ μεταξὺ λέγοντός σου τοιόνδε τι ἐνενόησα· εἴ τις ἕνα τῶν ἀνδρῶν ἐκείνων τῶν χρυσηλάτων ἐς τὸν ἡμέτερον τοῦτον βίον ἀγαγὼν ἔδειξε τοῖς πολλοῖς, οἷα ἔπαθεν ἂν ὁ ἄθλιος ὐπ’ αὐτῶν; διεσπάσαντο γὰρ ἂν αὐτὸν εὖ οἶδ’ ὅτι ἐπιδραμόντες ὥσπερ τὸν Πενθέα αἱ Μαινάδες ἢ αἱ Θρᾷτται τὸν Ὀρφέα ἢ τὸν Ἀκταίωνα αϊ κύνες, περὶ τοῦ μεῖζον ἀπενέγκασθαι τὸ μέρος πρὸς ἀλλήλους ἕκαστος ἁμιλλώμενοι, οἵ γε οὐδὲ ἑορτάζοντες ἔξω τοῦ φιλοκερδοῦς εἰσιν, ἀλλἀ πρόσοδον οἱ πολλοὶ πεποίηνται τὴν ἑορτήν. εἷτα οἱ μὲν ἀπέρχονται λῃστεύοντες ἐν τῷ συμποσίῳ τοὺς φίλους, οἱ δέ σοί τε λοιδοροῦνται, οὐδὲν δέον, καὶ τοὺς κύβους συντρίβουσιν ἀναιτίους ὄντας αὐτοῖς ὧν ἑκόντες ποιοῦσιν. ἀτὰρ εἰπέ μοι καὶ τόδε, τί δή ποτε ἁβρὸς οὕτω θεὸς ὢν καὶ γέρων ἐπιλεξάμενος τὸ ἀτερπέστατον, ὁπότε ἡ χιὼν ἐπέχει τὰ πάντα καὶ ὁ βορρᾶς πολὺς καὶ οὐδὲν ὅ τι οὐ πέπηγεν ὑπὸ τοῦ κρύους καὶ τὰ δένδρα ξηρὰ καὶ γυμνὰ καὶ ἄφυλλα καὶ οἱ λειμῶνες ἄμορφοι καὶ ἀπηνθηκότες καὶ οἱ ἄνθρωποι ἐπικεκυφότες ὥσπερ οἱ πάνυ γεγηρακότες, ἀμφὶ τὴν κάμινον οἱ πολλοί, τηνικαῦτα ἑορτάζεις; οὐ γὰρ πρεσβυτικός γε ὁ καιρὸς οὐδὲ ἐπιτήδειος τοῖς τρυφῶσι.", "st": "55.8"}, {"sp": "N", "t": "<em>Κρόνος.<\/em> πολλά με ἀνακρίνεις, ὦ οὗτος, ἤδη πίνειν δέον· παρῄρησαι γοῦν μου χρόνον τῆς ἑορτῆς οὐκ ὀλίγον οὐ πάνυ ἀναγκαῖά μοι ταῦτα προσφιλοσοφῶν. ὥστε νῦν μὲν ἄφες αὐτά, εὐωχώμεθα δὲ ἤδη καὶ κροτῶμεν καὶ ἐπὶ τῇ ἑορτῇ ἐλευθεριάζωμεν, εἶτα πεττεύωμεν ἐς τὸ ἀρχαῖον ἐπὶ καρύων καὶ βασιλέας χειροτονῶμεν καὶ πειθαρχῶμεν αὐτοῖς· οὕτω γὰρ ἂν τὴν παροιμίαν ἐπαληθεύσαιμι, ἥ φησι, παλίμπαιδας τοὺς γέροντας γίγνεσθαι.", "st": "55.9"}, {"sp": "N", "t": "<em>Ἱερεύς.<\/em> ἀλλὰ μὴ δύναιτο διψῶν πιεῖν, ὦ Κρόνε, ὅτῳ μὴ ταῦτα ἃ λέγεις ἡδέα. ὥστε πίνωμεν· ἱκανὰ γὰρ ἀποκέκρισαι καὶ τὰ πρῶτα. καί μοι δοκῶ γραψάμενος εἰς βιβλίον ταύτην ἡμῶν τὴν συνουσίαν ἅ τε αὐτὸς ἠρώτησα καὶ σὺ πρὸς ταῦτα ἵλεως ἀπεκρίνω παρέξειν ἀναγνῶναι τῶν φίλων, ὅσοι γ’ ἐπακοῦσαι τῶν σῶν λόγων αξιοι.", "st": "55.9"}, {"sp": "SEC", "t": "Κρονοσόλων", "st": "55.10"}, {"sp": "N", "t": "τάδε λέγει Κρονοσόλων ἱερεὺς καὶ προφήτης τοῦ Κρόνου καὶ νομοθέτης τῶν ἀμφὶ τὴν ἑορτήν· ἃ μὲν τοὺς πένητας χρὴ ποιεῖν, αὐτοῖς ἐκείνοις ἔπεμψα ἄλλο βιβλίον, ἐγγράψας, καὶ εὖ οἶδ’ ὅτι ἐμμενοῦσι κἀκεῖνοι τοῖς νόμοις, ἢ αὐτίκα ἔνοχοι ἔσονται τοῖς ἐπιτιμίοις, ἃ κατὰ τῶν ἀπειθούντων μεγάλα ὥρισται. ὑμεῖς δέ, ὦ πλούσιοι, ὁρᾶτε ὅπως μὴ παρανομήσητε μηδὲ παρακούσητε τῶνδε τῶν προσταγμάτων· ὡς ὅστις ἂν οὕτω μὴ ποιήσῃ, ἴστω οὗτος οὐκ ἐμοῦ νομοθέτου ἀμελήσων, ἀλλ’ εἰς τὸν Κρόνον αὐτόν, ὅς με προείλετο νομοθετῆσαι ἐς τὴν ἑορτὴν οὐκ ὄναρ ἐπιστάς, ἀλλὰ πρῴην ἐγρηγορότι ἐναργὴς συγγενόμενος. ἦν δὲ οὐ πεδήτης οὐδὲ αὐχμοῦ πλέως, οἷον αὐτὸν οἱ ζωγράφοι παρὰ τῶν λήρων τῶν ποιητῶν παραδεξάμενοι ἐπιδείκνυνται, ἀλλὰ τὴν μὲν ἅρτην εἶχε πάνυ τεθηγμένην· τὰ δ’ ἄλλα φαιδρός τε ἦν καὶ καρτερὸς καὶ βασιλικῶς ἐνεσκεύαστο. μορφὴν μὲν τοιόσδε ὤφθη μοι, ἃ δὲ εἶπε, πάνυ θεσπέσια καὶ ταῦτα, προειρῆσθαι ὑμῖν ἄξια.", "st": "55.10"}, {"sp": "N", "t": "ἰδὼν γάρ με σκυθρωπόν, ἐπὶ συννοίας βαδίζοντα, ὥσπερ εἰκὸς ἦν θεόν, ἔγνω αὐτίκα τὴν αἰτίαν τῆς λύπης τίς ἐστί μοι, καὶ ὡς τὴν πενίαν δυσχεραίνοιμι οὐ κατὰ τὴν ὥραν μονοχίτων· καὶ γὰρ κρύος καὶ βορρᾶς πολὺς καὶ κρύσταλλοι καὶ χιών· ἐγὼ δὲ ἥκιστα ἐπεφράγμην πρὸς αὐτά. ἀλλ’ ὅτι καὶ τῆς ἑορτῆς πάνυ πλησιαζούσης ἑώρων τοὺς μὲν ἄλλους παρασκευαζομένους ὅπως θύσωσι καὶ εὐωχήσωνται, ἐμαυτῷ δὲ οὐ πάνυ ἑορτάσιμα ὄντα. καὶ δὴ προσελθὼν ὄπισθεν καὶ τοῦ ὠτός μου λαβόμενος καὶ διασείσας, ὥσπερ μοι προσπελάζειν εἴωθε, Τί ταῦτα, ἔφη, ὦ Κρονοσόλων, ἀνιωμένῳ ἔοικας; οὐ γὰρ ἄξιον, ἔφην, ὦ δέσποτα, ὅταν καταράτους μὲν καὶ μιαροὺς ἀνθρώπους ὑπερπλουτοῦντας καὶ μόνους τρυφῶντας ὁρῶ, αὐτὸς δὲ καὶ ἄλλοι συχνοὶ τῶν πεπαιδευμένων ἀπορίᾳ καὶ ἀμηχανίᾳ σύνεσμεν; ἀλλ’ οὐδὲ σύ, ὦ δέσποτα, θέλεις παῦσαι ταῦτα καὶ μετακοσμῆσαι πρὸς τὸ ἰσόμοιρον. τὰ μὲν ἄλλα, ἔφη, οὐ ῥάδιον ἀλλάττειν ὁπόσα ἐκ Κλωθοῦς καὶ τῶν ἄλλων Μοιρῶν πάσχετε, ἃ δέ ἐστι τῆς ἑορτῆς, ἐπανορθώσομαι ὑμῖν τὴν πενίαν, ἡ δὲ ἐπανόρθωσις ἥδε ἔστω· ἴθι, ὦ Κρονοσόλων, καὶ γράψον μοι νόμους τινάς, ἃ χρὴ πράττειν ἐν τῇ ἑορτῇ, ὡς μὴ καθ’ αὑτοὺς οἱ πλούσιοι ἑορτάζοιεν, κοινωνοῖεν δὲ ὑμῖν τῶν ἀγαθῶν. ἀλλ’ οὐκ οἶδα, ἔφην.", "st": "55.11"}, {"sp": "N", "t": "ἐγώ, ἦ δ’ ὅς, διδάξομαί σε· κᾆτα ἀρξάμενος ἐδίδασκεν. εἶτα ἐπειδὴ πάντα ἠπιστάμην, Καὶ εἰπὲ αὐτοῖς, ἔφη, ὅτι ἢν μὴ τοῦτο ποιῶσι, μὴ μάτην ἐγὼ τὴν ἅρπην ταύτην ὀξεῖαν περιφέρω, ἢ γελοῖος ἂν εἴην τὸν μὲν πατέρα ἐκτομίαν πεποιηκὼς τὸν Οὐρανόν, τοὺς δὲ πλουσίους μὴ εὐνουχίζων, ὁπόσοι ἂν παρανομήσωσιν, ὡς ἀγείροιεν τῇ μητρὶ σὺν αὐλοῖς καὶ τυμπάνοις βάκηλοι γενόμενοι. ταῦτα ἠπείλησεν. ὥστε καλῶς ἔχει ὑμῖν μὴ παραβαίνειν τοὺς θεσμούς.", "st": "55.12"}, {"sp": "SEC", "t": "Νόμοι Πρῶτοι", "st": "55.13"}, {"sp": "N", "t": "μηδένα μηδὲν μήτε ἀγοραῖον μήτε ἴδιον πράττειν ἐντὸς τῆς ἑορτῆς ἢ ὅσα ἐς παιδιὰν καὶ τρυφὴν καὶ θυμηδίαν, ὀψοποιοὶ μόνοι καὶ πεμματουργοὶ ἐνεργοὶ ἔστωσαν. ἰσοτιμία πᾶσιν ἔστω καὶ δούλοις καὶ ἐλευθέροις καὶ πένησι καὶ πλουσίοις. ὀργίζεσθαι ἢ ἀγανακτεῖν ἢ ἀπειλεῖν μηδενὶ ἐξέστω. λογισμοὺς παρὰ τῶν ἐπιμελουμένων Κρονίοις λαμβάνειν μηδὲ τοῦτο ἐξέστω. μηδεὶς τὸν ἄργυρον ἢ τὴν ἐσθῆτα ἐξεταζέτω μηδὲ ἀναγραφέτω ἐν τῇ ἑορτῇ μηδὲ γυμναζέσθω Κρονίοις μηδὲ λόγους ἀσκεῖν ἢ ἐπιδείκνυσθαι, πλὴν εἴ τινες ἀστεῖοι καὶ φαιδροὶ σκῶμμα καὶ παιδιὰν ἐμφαίνοντες.", "st": "55.13"}, {"sp": "SEC", "t": "Νόμοι Δεύτεροι", "st": "55.14"}, {"sp": "N", "t": "πρὸ πολλοῦ τῆς ἑορτῆς οἱ πλούσιοι γραφόντων κὲν ἐς πινάκιον ἑκάστου τῶν φίλων τοὔνομα, ἐχόντων δὲ καὶ ἀργύριον ἕτοιμον ὅσον τῶν κατ’ ἔτος προσιόντων τὸ δέκατον καὶ ἐσθῆτα τῆς οὔσης τὴν περιττὴν καὶ ὅση παχυτέρα ἢ κατ’ αὐτοὺς κατασκευή, καὶ τῶν ἀργυρῶν οὐκ ὀλίγα. ταῦτα μὲν πρόχειρα ἔστω. τῇ δὲ πρὸ τῆς ἑορτῆς καθάρσιον μέν τι περιφερέσθω καὶ ὑπ’ αὐτῶν ἐξελαυνέσθω ἐκ τῆς οἰκίας μικρολογία καὶ φιλαργυρία καὶ φιλοκερδία καὶ ὅσα τοιαῦτα ἄλλα σύνοικα τοῖς πλείστοις αὐτῶν. ἐπειδὰν δὲ καθαρὰν τὴν οἰκίαν ἐξεργάσωνται, θυόντων Διὶ πλουτοδότῃ καὶ Ἑρμῇ δώτορι καὶ Ἀπόλλωνι μεγαλοδώρῳ. εἶτα περὶ δείλην ὀψίαν ἀναγινωσκέσθω μὲν σφίσι τὸ φιλικὸν ἐκεῖνο πινάκιον.", "st": "55.14"}, {"sp": "N", "t": "κατανείμαντες δὲ αὐτοὶ κατ’ ἀξίαν ἑκάστῳ πρὶν ἥλιον δῦναι πεμπόντων τοῖς φίλοις. οἱ δὲ ἀποκομίζοντες μὴ πλείους τριῶν ἢ τεττάρων, οἱ πιστότατοι τῶν οἰκετῶν, ἤδη πρεσβῦται. ἐγγραψάσθω δὲ ἐς γραμμάτιον ὅ τι τὸ πεμπόμενον καὶ ὅσον, ὡς μὴ ἀμφότεροι ὑποπτεύοιεν τοὺς διακομίζοντας. αὐτοὶ δὲ οἱ οἰκέται μίαν κύλικα ἕκαστος πιόντες ἀποτρεχόντων, ἀπαιτούντων δὲ μηδὲν πλέον. τοῖς πεπαιδευμένοις διπλάσια πάντα πεμπέσθω· ἄξιον γὰρ διμοιρίτας εἶναι. τὰ δὲ ἐπὶ τοῖς δώροις λεγόμενα ὡς μετριώτατα καὶ ὀλίγιστα ἔστω· ἐπαχθὲς δὲ μηδεὶς μηδὲν συνεπιστελλέτω μηδὲ ἐπαινείτω τὰ πεμπόμενα. πλούσιος πλουσίῳ μηδὲν πεμπέτω μηδὲ ἑστιάτω Κρονίοις ὁ πλούσιος τὸν ίσότιμον. τῶν εἰς τὸ πεμφθῆναι προχειρισθέντων φυλαττέσθω μηδὲν μηδὲ μετάνοια εἰσίτω ἐπὶ τῇ δωρεᾷ. εἴ τις πέρυσιν ἀποδημῶν δι’ αὐτὸ ἄμοιρος κατέστη, ἀπολαμβανέτω κἀκεῖνα. διαλυόντων δὲ οἱ πλούσιοι καὶ χρέα ὑπὲρ τῶν φίλων τῶν πενήτων καὶ τὸ ἐνοίκιον, οἵτινες ἂν καὶ τοῦτο ὀφείλοντες καταβαλεῖν μὴ ἔχωσι· καὶ ὅλως, πρὸ πολλοῦ μελέτω αὐτοῖς εἰδέναι ὅτου μάλιστα δέονται.", "st": "55.15"}, {"sp": "N", "t": "ἀπέστω δὲ καὶ τῶν λαμβανόντων μεμψιμοιρία, καὶ τὸ πεμφθὲν ὁποῖον ἂν ᾖ, μέγα δοκείτω. οἴνου ἀμφορεὺς ἢ λαγὼς ἢ ὄρνις παχεῖα Κρονίων δῶρον μὴ δοκείτω· μηδὲ τὰς Κρονικὰς δωρεὰς εἰς γέλωτα φερέτωσαν. ἀντιπεμπέτω δὲ ὁ πένης τῷ πλουσίῳ ὁ μὲν πεπαιδευμένος βιβλίον τῶν παλαιῶν, εἴ τι εὔφημον καὶ συμποτικόν, ἢ αὐτοῦ σύγγραμμα ὁποῖον ἂν δύνηται, καὶ τοῦτο λαμβανέτω ὁ πλούσιος πάνυ φαιδρῷ τῷ προσώπῳ καὶ λαβὼν ἀναγινωσκέτω εὐθύς, ἢν δὲ ἀπωθῆται ἢ ἀπορρίψῃ, ἴστω τῆ τῆς ἅρπης ἀπειλῇ ἔνοχος ὤν, κἂν πέμψῃ ὅσα ἐχρῆν· οἱ δὲ ἄλλοι οἱ μὲν στεφάνους, οἱ δὲ λιβανωτοῦ χόνδρους πεμπόντων. ἢν δὲ πένης ἐσθῆτα ἢ ἄργυρον ἢ χρυσὸν παρὰ τὴν δύναμιν πέμψῃ πλουσίῳ, τὸ μὲν πεμφθὲν ἔστω δημόσιον καὶ καταπραθὲν ἐμβαλλέσθω εἰς τὸν θησαυρὸν τοῦ Κρόνου, ὁ δὲ πένης ἐς τὴν ὑστεραίαν πληγὰς παρὰ τοῦ πλουσίου λαμβανέτω τῷ νάρθηκι εἰς τὰς χεῖρας οὐκ ἐλάττους διακοσίων καὶ πεντήκοντα.", "st": "55.16"}, {"sp": "SEC", "t": "Νόμοι Συμποτικοί", "st": "55.17"}, {"sp": "N", "t": "λούεσθαι μὲν ὁπόταν τὸ στοιχεῖον ἑξάπουν ᾖ, τὰ δὲ πρὸ τοῦ λουτροῦ κάρυα καὶ πεττοὶ ἔστωσαν. κατακείσθω ὅπου ἂν τύχῃ ἕκαστος· ἀξίωμα ἢ γένος ἢ πλοῦτος ὀλίγον συντελείτω ἐς προνομήν. οἴνου τοῦ αὐτοῦ πίνειν ἅπαντας· μηδ’ ἔστω πρόφασις τῷ πλουσίῳ ἢ στομάχου ἢ κεφαλῆς ὀδύνη, ὡς μόνον δι’ αὐτὴν πίνειν τοῦ κρείττονος. μοῖρα χρεῶν κατ’ ἴσον ἅπασιν· οἱ διάκονοι πρὸς χάριν μηδενὶ μηδέν, ἀλλὰ μηδὲ βραδυνέτωσαν μηδὲ παραπετέσθωσαν ἔστ’ ἂν αὐτοῖς δοκῇ, ὁπόσα χρὴ ἀποφέρειν. μηδὲ τῷ μὲν μεγάλα, τῷ δὲ κομιδῇ μικρά παρατιθέσθω, μηδὲ τῷ μὲν ὁ μηρός, τῷ ἡ γνάθος συός, ἀλλ’ ἰσότης ἐπὶ πᾶσιν.", "st": "55.17"}, {"sp": "N", "t": "ὁ οἰνοχόος ὀξὺ δεδορκέτω ἐκ περιωπῆς ἐς ἕκαστον, καὶ ἔλαττον ἐς τὸν δεσπότην, καὶ ἐπ’ ὀξύτερον ἀκουέτω. καὶ κύλικες παντοῖαι. καὶ ἐξέστω παρέχειν, ἤν τις ἐθέλῃ, φιλοτησίαν. πάντες πᾶσι προπινέτωσαν, ἢν ἐθέλωσι, προπιόντος τοῦ πλουσίου. μὴ ἐπάναγκες ἔστω πίνειν, ἤν τις μὴ δύνηται. εἰς τὸ συμπόσιον μήτε ὀρχηστὴν μήτε κιθαριστὴν αὐτοὺς ἄγειν ἄρτι μανθάνοντα ἐξέστω, ἤν τις ἐθέλῃ. σκώμματος μέτρον ἔστω τὸ ἄλυπον ἐπὶ πᾶσιν. ἐπὶ πᾶσι πεττευέτωσαν ἐπὶ καρύων· ἤν τις ἐπ’ ἀργυρίῳ πεττεύσῃ, ἄσιτος ἐς τὴν ὑστεραίαν ἔστω. καὶ μενέτω καὶ ἀπίτω ἕκαστος, ὁπόταν βούληται. ἐπὰν δὲ τοὺς οἰκέτας ὁ πλούσιος εὐωχῇ, διακονούντων καὶ οἱ φίλοι σὺν αὐτῷ. τοὺς νόμους τούτους ἕκαστον τῶν πλουσίων ἐγγράψαντα ἐς χαλκῆν στήλην ἔχειν ἐν μεσαιτάτῳ τῆς αὐλῆς, καὶ ἀναγινωσκέτω. δεῖ δὲ εἰδέναι ὅτι ἔστ’ ἂν αὕτη ἡ στήλη μένῃ, οὔτε λιμὸς οὔτε λοιμὸς οὔτε πυρκαϊὰ οὔτε ἄλλο χαλεπὸν οὐδὲν εἴσεισιν εἰς τὴν οἰκίαν αὐτοῖς. ἢν δέ ποτε — ὅπερ μὴ γένοιτο — καθαιρεθῇ, ἀποτρόπαιον οἷα πείσονται.", "st": "55.18"}, {"sp": "SEC", "t": "Ἐπιστολαὶ Κρονικαί. Αʹ", "st": "55.19"}, {"sp": "N", "t": "Ἐγὼ Κρόνῳ χαίρειν. ἐγεγράφειν μὲν ἤδη σοι καὶ πρότερον δηλῶν ἐν οἷς εἴην καὶ ὡς ὑπὸ πενίας κινδυνεύοιμι μόνος ἄμοιρος εἶναι τῆς ἑορτῆς, ἣν ἐπήγγελκας, ἔτι καὶ τοῦτο προσθεὶς — μέμνημαι γάρ — ἀλογώτατον εἶναι τοὺς μὲν ἡμῶν ὑπερπλουτεῖν καὶ τρυφᾶν δὐ κοινωνοῦντας ὧν ἔχουσι τοῖς πενεστέροις, τοὺς δὲ λιμῷ διαφθείρεσθαι, καὶ ταῦτα Κρονίων ἐνεστώτων· ἐπεὶ δέ μοι τότε οὐδὲν ἀντεπέστειλας, ἡγησάμην δεῖν αὖθις ἀναμνῆσαί σε τῶν αὐτῶν. ἐχρῆν γάρ σε, ὦ ἄριστε Κρόνε, τὸ ἄνισον τοῦτο ἀφελόντα καὶ τὰ ἀγαθὰ ἐς τὸ μέσον ἅπασι καταθέντα ἔπειτα κελεύειν ἑορτάζειν. ὡς δὲ νῦν ἔχομεν, μύρμηξ ἢ κάμηλος, ὡς ἡ παροιμία φησί. μᾶλλον δὲ τραγικὸν ὑποκριτὴν ἐννόησον θατέρῳ μὲν τοῖν ποδοῖν ἐφ’ ὑψηλοῦ βεβηκότα, οἷοί εἰσι τραγικοὶ ἐμβάται, ὁ δ’ ἕτερος ἀνυπόδητος ἔστω. εἰ τοίνυν βαδίζοι οὕτως ἔχων, ὁρᾷς ὅτι ἀναγκαῖον αὐτῷ ἄρτι μὲν ὑψηλῷ, ἄρτι δὲ ταπεινῷ γενέσθαι, καθ’ ὁπότερον ἂν πόδα προβαίνῃ. τοσοῦτον κἀν τῷ βίῳ ἡμῶν τὸ ἄνισον· καὶ οἱ μὲν ὑποδησάμενοι ἐμβάτας τῆς τύχης χορηγούσης ἐντραγῳδοῦσιν ἡμῖν, οἱ πολλοὶ δὲ πεζῇ καὶ χαμαὶ βαδίζομεν δυνάμενοι ἄν, εὖ ἴσθι, μὴ χεῖρον αὐτῶν ὑποκρίνεσθαι καὶ διαβαίνειν, εἴ τις καὶ ἡμᾶς ἐνεσκεύασε παραπλησίως ἐκείνοις.", "st": "55.19"}, {"sp": "N", "t": "καίτοι ἀκούω τῶν ποιητῶν λεγόντων ὡς τὸ παλαιὸν οὐ τοιαῦτα ἦν τοῖς ἀνθρώποις τὰ πράγματα σοῦ ἔτι μοναρχοῦντος, ἀλλ’ ἡ μὲν γῆ ἄσπορος καὶ ἀνήροτος ἔφυεν αὐτοῖς τὰ ἀγαθά, δεῖπνον ἕτοιμον ἑκάστῳ ἐς κόρον, ποταμοὶ δὲ οἱ μὲν οἶνον, οἱ δὲ γάλα, εἰσὶ δὲ οἳ καὶ μέλι ἔρρεον· τὸ δὲ μέγιστον, αὐτοὺς ἐκείνους φασὶ τοὺς ἀνθρώπους χρυσοῦς εἶναι, πενίαν δὲ μηδὲ τὸ παράπαν αὐτοῖς πλησιάζειν. ἡμεῖς δὲ αὐτοὶ μὲν οὐδὲ μόλυβδος ἄν εἰκότως δοκοίημεν, ἀλλ’ εἴ τι καὶ τούτου ἀτιμότερον, ἡ τροφὴ δὲ μετὰ πόνων τοῖς πλείστοις, ἡ πενία δὲ καὶ ἀπορία καὶ ἀμηχανία καὶ τὸ οἴμοι καὶ τὸ πόθεν ἄν μοι γένοιτο καὶ ὢ τῆς τύχης πολλὰ τοιαῦτα παρὰ γοῦν ἡμῖν τοῖς πένησι. καὶ ἧττον ἄν, εὖ ἴσθι, ἠνιώμεθα ἂν ἐπ’ αὐτοῖς, εἰ μὴ τοὺς πλουσίους ἑωρῶμεν τοσαύτῃ εὐδαιμονίᾳ συνόντας, οἳ τοσοῦτον μὲν χρυσόν, τοσοῦτον δὲ ἄργυρον ἐγκλεισάμενοι, ἐσθῆτας δὲ ὅσας ἔχοντες, ἀνδράποδα δὲ καὶ ζεύγη καὶ συνοικίας καὶ ἀγρούς, πάμπολλα δὲ ταῦτα ἕκαστα κεκτημένοι οὐχ ὅπως μετέδοσαν ἡμῖν ποτε αὐτῶν, ἀλλ’ οὐδὲ προσβλέπειν τοὺς πολλοὺς ἀξιοῦσι.", "st": "55.20"}, {"sp": "N", "t": "ταῦτα ἡμᾶς μάλιστα ἀποπνίγει, ὦ Κρόνε, καὶ ἀφόρητον ἡγούμεθα τὸ πρᾶγμα, τὸν μὲν ἐφ’ ἁλουργίδων κατακείμενον τοσούτοις ἀγαθοῖς ἐντρυφᾶν ἐρυγγάνοντα καὶ ὑπὸ τῶν συνόντων εὐδαιμονιζόμενον ἀεὶ ἑορτάζοντα, ἐμὲ δὲ καὶ τοὺς ὁμοίους ὀνειροπολεῖν, εἴ ποθεν ὀβολοὶ τέτταρες γένοιντο, ὡς ἔχοιμεν ἄρτων γοῦν ἢ ἀλφίτων ἐμπεπλησμένοι καθεύδειν κάρδαμον ἢ θύμον ἢ κρόμμυον ἐπιτρώγοντες. ἢ τοίνυν ταῦτα, ὦ Κρόνε, ἀλλάττειν καὶ μεταποιεῖν ἐς τὸ ἰσοδίαιτον, ἢ τὸ ὕστατον, αὐτούς γε ἐκείνους κελεύειν τοὺς πλουσίους μὴ μόνους ἀπολαύειν τῶν ἀγαθῶν, ἀλλὰ ἀπὸ μεδίμνων τοσούτων χρυσίου χοίνικά γε ἡμῶν πάντων κατασκεδάσαι, ἀπὸ δὲ ἱματίων ὅσα κἂν ὑπὸ σητῶν διαβρωθέντα οὐκ ἂν αὐτοὺς ἀνιάσειε· ταῦτα γοῦν πάντως ἀπολλύμενα καὶ ὑπὸ τοῦ χρόνου διαφθαρησόμενα ἡμῖν δοῦναι περιβαλέσθαι μᾶλλον ἢ ἐν ταῖς κοίταις καὶ κίσταις εὐρῶτι πολλῷ κατασαπῆναι.", "st": "55.21"}, {"sp": "N", "t": "καὶ μὴν καὶ δειπνίζειν ἕκαστον ἄρτι μὲν τέτταρας, ἄρτι δὲ πέντε τῶν πενήτων παραλαμβάνοντας, μὴ μέντοι ἐς τὸν νῦν τρόπον τῶν δείπνων, ἀλλ’ ἐς τὸ δημοτικώτερον, ὡς ἐπ’ ἴσης μετέχειν ἅπαντας καὶ μὴ τὸν μὲν ἐμφορεῖσθαι τῶν ὄψων καὶ τὸν οἰκέτην περιμένειν ἑστῶτα, ἔστ’ ἂν ἀπαγορεύσῃ ἐσθίων, ἐφ’ ἡμᾶς δὲ ἐλθόντα, ἔτι παρασκευαζομένων ὡς ἐπιβάλοιμεν τὴν χεῖρα, παραμείβεσθαι δείξαντα μόνον τὴν λοπάδα ἢ ὅσον ἐστὶ τοῦ πλακοῦντος τὸ λοιπόν· μηδὲ ἐσκομισθέντος ὑὸς διανέμοντα τῷ κὲν δεσπότῃ παρατιθέναι τὸ ἡμίτομον ὅλον σὺν τῇ κεφαλῇ, τοῖς δὲ ἄλλοις ὀστᾶ φέρειν ἐγκεκαλυμμένα. προειπεῖν δὲ καὶ τοῖς οἰνοχόοις μὴ περιμένειν, ἔστ’ ἂν ἑπτάκις αἰτήσῃ πιεῖν ἡμῶν ἕκαστος, ἀλλὰ ἢν ἅπαξ κελεύσῃ, αὐτίκα ἐγχέαι καὶ ἀναδοῦναι μεγάλην κύλικα ἐμπλησαμένους ὥσπερ τῷ δεσπότῃ· καὶ τὸν οἶνον δὲ αὐτὸν πᾶσι τοῖς συμπόταις ἕνα καὶ τὸν αὐτὸν εἶναι. ἢ ποῦ γὰρ γεγράφθαι τοῦτον τὸν νόμον, τὸν μὲν ἀνθοσμίου μεθύσκεσθαι, ἐμοὶ δὲ ὑπὸ τοῦ γλεύκους διαρρήγνυσθαι τὴν γαστέρα;", "st": "55.22"}, {"sp": "N", "t": "ἢν ταῦτα ἐπανορθώσῃς καὶ μετακοσμήσῃς, ὦ Κρόνε, βίον μὲν τὸν βίον, ἑορτὴν δὲ τὴν ἑορτὴν ἔσῃ πεποιηκώς, εἰ δὲ μή, ἐκεῖνοι μὲν ἑορταζόντων, ἡμεῖς δὲ καθεδούμεθα εὐχόμενοι, ἐπειδὰν λουσάμενοι ἥκωσι, τὸν παῖδα μὲν αὐτοῖς ἀνατρέψαντα τὸν ἀμφορέα κατᾶξαι, τὸν μάγειρον δὲ τὸν ζωμὸν κνισῶσαι καὶ ἐπιλαθόμενον τὸ τάριχος μὲν ἐς τὴν φακῆν ἐμβαλεῖν [τῶν ἰχθύων]· τὴν κυνα δὲ παρεισπεσοῦσαν τόν τε ἀλλᾶντα ὅλον καταφαγεῖν, περὶ τἆλλα τῶν ὀψοποιῶν ἐχόντων, καὶ τοῦ πλακοῦντος τὸ ἥμισυ· τὸν δὲ ὗν καὶ τὸν ἔλαφον καὶ τὰ δελφάκια μεταξὺ ὀπτώμενα τὸ ὅμοιον ποιεῖν, ὅπερ Ὅμηρος περὶ τῶν Ἡλίου βοῶν φησι· μᾶλλον δὲ μὴ ἕρπειν μόνον, ἀλλ’ ἀναπηδήσαντα φεύγειν εἰς τὸ ὄρος αὐτοῖς ὀβελοῖς· καὶ τὰς ὄρνεις δὲ τὰς παχείας, καίτοι ἀπτέρους ἤδη οὔσας καὶ ἐσκευασμένας, ἀναπταμένας οἴχεσθαι καὶ ταύτας, ὡς μὴ μόνοι ἀπολαύοιεν αὐτῶν.", "st": "55.23"}, {"sp": "N", "t": "ὃ δὲ δὴ μάλιστα ἂν αὐτοὺς ἀνιάσειε, τὸ μὲν χρυσίον μύρμηκάς τινας οἵους τοὺς Ἰνδικοὺς ἀνορύττοντας ἐκ τῶν θησαυρῶν ἐκφέρειν νύκτωρ ἐς τὸ δημόσιον· τὴν ἐσθῆτα δὲ ὀλιγωρίᾳ τῶν ἐπιμελητῶν κοσκινηδὸν διατερυπῆσθαι ὑπὸ τῶν βελτίστων μυῶν, ὡς σαγήνης θυννευτικῆς μηδὲν διαφέρειν· παῖδας δὲ αὐτῶν τοὺς ὡραίους καὶ κομήτας, οὓς Ὑακίνθους ἢ Ἀχιλλέας ἢ Ναρκίσσους ὀνομάζουσι, μεταξὺ ὀρέγοντας σφίσι τὸ ἔκπωμα φαλακροὺς γίνεσθαι ὑπορρεούσης τῆς κόμης καὶ πώγωνα φύειν ὀξύν, οἷοί εἰσιν ἐν ταῖς κωμῳδίαις οἱ σφηνοπώγωνες, καὶ τὸ παρὰ τοῖς κροτάφοις πάνυ λάσιον καὶ κάρτα ἐκκεντοῦν, τὸ μεταξὺ δὲ λεῖον καὶ γυμνὸν εἶναι. ταῦτα καὶ πλείω τούτων εὐξαίμεθ’ ἄν, εἰ μὴ θέλωσι τὸ ἄγαν φίλαυτον τοῦτ’ ἀφέντες ἐς τὸ κοινὸν πλουτεῖν καὶ μεταδιδόναι ἡμῖν τῶν μετρίων.", "st": "55.24"}, {"sp": "SEC", "t": "Βʹ", "st": "55.25"}, {"sp": "N", "t": "Κρόνος ἐμοὶ τῷ τιμιωτάτῳ χαίρειν. τί ταῦτα ληρεῖς, ὦ οὗτος, ἐμοὶ περὶ τῶν παρόντων ἐπιστέλλων καὶ ἀναδασμὸν τῶν ἀγαθῶν ποιεῖν κελεύων; τὸ δὲ ἑτέρου ἂν εἴη, τοῦ νῦν ἄρχοντος. θαυμάζω γὰρ εἰ μόνος τῶν ἁπάντων ἀγνώσσεις ὡς ἐγὼ μὲν πάλαι βασιλεὺς ὢν πέπαυμαι, τοῖς παισὶ διανείμας τὴν ἀρχήν, ὁ δὲ Ζεὺς μάλιστα τῶν τοιούτων ἐπιμελεῖται· τὰ δὲ ἡμέτερα ταῦτα μέχρι πεττῶν καὶ κρότου καὶ ᾠδῆς καὶ μέθης, καὶ τοῦτο οὐ πλέον ἡμερῶν ἑπτά. ὥστε περὶ τῶν μειζόνων ἃ φής, ἀφελεῖν τὸ ἄνισον καὶ ἐκ τῆς ὁμοίας ἢ πένεσθαι ἢ πλουτεῖν ἅπαντας, ὁ Ζεὺς ἂν χρηματίσειεν ὑμῖν. εἰ δέ τι τῶν ἐκ τῆς ἑορτῆς ἀδικοῖτό τις ἢ πλεονεκτοῖτο, ἐμὸν ἂν εἴη δικάζειν· καὶ ἐπιστέλλω δὲ τοῖς πλουσίοις περὶ τῶν δείπνων καὶ τοῦ χοίνικος τοῦ χρυσίου καὶ τῶν ἐσθήτων, ὡς καὶ ὑμῖν πέμποιεν ἐς τὴν ἑορτήν· δίκαια γάρ ταῦτα καὶ ἄξια αὐτοὺς ποιεῖν, ὡς φατέ, εἰ μή τι εὔλογον ἐκεῖνοι πρὸς ταῦτα λέγειν ἔχωσι.", "st": "55.25"}, {"sp": "N", "t": "τὸ δὲ ὅλον, ἴστε οἱ πέ νητες ὑμεῖς ἐξηπατημένοι καὶ οὐκ ὀρθῶς δοξάζοντες περὶ τῶν πλουσίων, οἵ γε πανευδαίμονας αὐτοὺς οἴεσθε εἶναι καὶ μόνους ἡδύν τινα βιοῦν τὸν βίον, ὅτι δειπνεῖν τε πολυτελῶς ἔστιν αὐτοῖς καὶ μεθύσκεσθαι οἴνου ἡδέος καὶ παισὶν ὡραίοις καὶ γυναιξὶν ὁμιλεῖν καὶ ἐσθῆσι μαλακαῖς χρῆσθαι· τὸ δὲ πάνυ ἀγνοεῖτε ὁποῖον ἐστιν. αἵ τε γὰρ φροντίδες αἱ περὶ τούτων οὐ μικραί, ἀλλ’ ἀνάγκη ἐπαγρυπνεῖν ἑκάστοις, μή τι ὁ οἰκονόμος βλακεύσας ἢ ὑφελόμενος λάθῃ, μὴ ὁ οἶνος ὀξυνθῇ, μὴ ὁ σῖτος φθειρὶ ζέσῃ, ἢ ὁ λῃστὴς ὑφέληται τὰ ἐκπώματα, μὴ πιστεύσῃ τοῖς συκοφάνταις ὁ δῆμος λέγουσι τυραννεῖν αὐτὸν ἐθέλειν ταῦτα δὲ πάντα οὐδὲ τὸ πολλοστὸν ἄν εἴη μέρος τῶν ἀνιώντων αὐτούς· εἰ γοῦν ἠπίστασθε τοὺς φόβους καὶ τὰς μερίμνας ἃς ἔχουσι, πάνυ ἂν ὑμῖν φευκτέον ὁ πλοῦτος ἔδοξεν.", "st": "55.26"}, {"sp": "N", "t": "ἐπεί τοι οἴει με αὐτὸν οὕτως ἄν ποτε κορυβαντιᾶσαι, ὡς εἰ καλὸν ἦν τὸ πλουτεῖν καὶ βασιλεύειν, ἀφέντα ἂν αὐτὰ καὶ παραχωρήσαντα ἄλλοις καθῆσθαι ἰδιωτεύοντα καὶ ἀνέχεσθαι ὑπ’ ἄλλῳ ταττόμενον; ἀλλὰ τὰ πολλὰ ταῦτα εἰδώς, ἃ τοῖς πλουσίοις καὶ ἄρχουσι προσεῖναι ἀνάγκη, ἀφῆκα τὴν ἀρχὴν εὖ ποιῶν.", "st": "55.27"}, {"sp": "N", "t": "καὶ γὰρ ἅ νῦν ἐποτνιῶ πρός με, ὡς τοὺς μὲν ὑῶν καὶ πλακούντων ἐμφορουμένους, ὑμᾶς δὲ κάρδαμον ἢ θύμον ἢ κρόμμυον ἐπιτρώγοντας ἐν τῇ ἑορτῇ, σκέψαι ὁποῖά ἐστι· πρὸς μὲν γὰρ τὸ παρὸν ἡδὺ καὶ οὐχ ἀνιαρὸν ἴσως ἑκάτερον αὐτῶν, πρὸς δὲ τὰ μετὰ ταῦτα ἔμπαλιν ἀναστρέφεται τὸ πρᾶγμα. εἶτα ὑμεῖς μὲν οὔτε καρηβαροῦντες ἀνασταίητ’ ἂν ἐς τὴν ὑστεραίαν ὥσπερ ἐκεῖνοι ὑπὸ τῆς μέθης οὔτε ὑπὸ τῆς ἄγαν πλησμονῆς δυσῶδές τι καὶ καπνωδέστερον ἐρυγγάνοντες· οἱ δὲ τούτων τε ἀπολαύουσι καὶ τὸ πολὺ τῆς νυκτὸς ἢ παισὶν ἢ γυναιξὶν ἢ ὅπως ἂν ὁ τράγος κελεύῃ συναναφυρέντες ἢ φθόην ἢ περιπνευμονίαν ἢ ὕδερον οὐ χαλεπῶς συνελέξαντο ἐκ τῆς πολλῆς τρυφῆς. ἢ τίνα ἂν αὐτῶν ῥᾳδίως δεῖξαι δύναιο μὴ πάντως ὠχρὸν ὄντα πολὺ τὸ νεκρῶδες ἐμφαίνοντα; τίνα δὲ ἐς γῆρας ἀφικόμενον τοῖς αὐτοῦ ποσίν, ἀλλὰ μὴ φοράδην ἐπὶ τεττάρων ὀχούμενον, ὁλόχρυσον μὲν τὰ ἔξω, κατάρραφον δὲ τὰ ἔνδον, ὥσπερ αἱ τραγικαὶ ἐσθῆτες ἐκ ῥαχῶν πάνυ εὐτελῶν συγκεκαττυμέναι; ὑμεῖς δὲ ἰχθύων μὲν ἄγευστοι καὶ ἄσιτοι, ποδάγρας δὲ ἢ περιπνευμονίας οὐχ ὁρᾶθ’ ὅτι καὶ τούτων ἄπειροί ἐστε, ἢ εἴ τι κατ’ ἄλληνσς τινὰ αἰτίαν συμβαίνει; καίτοι οὐδ’ αὐτοῖς ἐκείνοις ἡδύ ἐστιν αὐτὸ καθ’ ἡμέραν καὶ πέρα τοῦ κόρου ἐσθίειν τούτων, ἀλλὰ ἴδοις ἂν αὐτοὺς οὕτω λαχάνων καὶ θύμου ὀρεγομένους ἐνίοτε, ὥσπερ οὐδὲ σὺ τῶν λαγωῶν καὶ ὑῶν.", "st": "55.28"}, {"sp": "N", "t": "ἐῶ λέγειν ὅσα ἄλλα λυπεῖ αὐτούς, υἱὸς ἀκόλαστος ἢ γυνὴ τοῦ οἰκέτου ἐρῶσα ἢ ἐρώμενος πρὸς ἀνάγκην μᾶλλον ἢ πρὸς ἡδονὴν συνών· καὶ ὅλως πολλά ἐστιν ἅπερ ὑμεῖς ἀγνοοῦντες τὸν χρυσὸν ὁρᾶτε αὐτῶν μόνον καὶ τὴν πορφύραν, καὶ ἢν ἴδητέ ποτε ἐξελαύνοντας ἐπὶ λευκοῦ ζεύγους, κεχήνατε καὶ προσκυνεῖτε. εἰ δὲ ὑπερεωρᾶτε αὐτῶν καὶ κατεφρονεῖτε καὶ μήτε ἐπεστρέφεσθε πρὸς τὴν ἀργυρᾶν ἁρμάμαξαν μήτε μεταξὺ διαλεγομένων εἰς τὸν ἐν τῷ δακτυλίῳ σμάραγδον ἀφεωρᾶτε καὶ τῶν ἱματίων παραπτόμενοι τὸ μαλακὸν ἐθαυμάζετε, ἀλλ’ εἰᾶτε καθ’ ἑαυτοὺς πλουτεῖν, εὖ ἴστε, αὐτοὶ ἐφ’ ὑμᾶς ἰόντες ἐδέοντο συνδειπνεῖν, ὡς ἐπιδείξαιντο ὑμῖν τὰς κλίνας καὶ τὰς τραπέζας καὶ τὰ ἐκπώματα, ὧν οὐδὲν ὄφελος, εἰ ἀμάρτυρος ἡ κτῆσις εἴη.", "st": "55.29"}, {"sp": "N", "t": "τά γέ τοι πλεῖστα εὕροιτε ἂν αὐτοὺς ὑμῶν ἕνεκα κτωμένους, οὐχ ὅπως αὐτοὶ χρήσωνται, ἀλλ’ ὅπως ὑμεῖς θαυμάζοιτε. ταῦτα ὑμᾶς παραμυθοῦμαι εἰδὼς τὸν βίον ἑκάτερον, καὶ ἄξιον ἑορτάζειν ἐνθυμουμένους ὅτι μετ’ ὀλίγον ἅπαντας δεήσει ἀπιέναι ἐκ τοῦ βίου κἀκείνους τὸν πλοῦτον καὶ ὑμᾶς τὴν πενίαν ἀφέντας. πλὴν ἐπιστελῶ γε αὐτοῖς ὥσπερ ὑπεσχόμην, καὶ οἶδ’ ὅτι οὐκ ὀλιγωρήσουσι τῶν ἐμῶν γραμμάτων.", "st": "55.30"}, {"sp": "SEC", "t": "Γʹ", "st": "55.31"}, {"sp": "N", "t": "Κρόνος τοῖς πλουσίοις χαίρειν. οἱ πένητες ἔναγχος ἐπεστάλκασί μοι αἰτιώμενοι ὑμᾶς μὴ μεταδιδόναι σφίσιν ὧν ἔχετε, καὶ τὸ μὲν ὅλον ἠξίουν με κοινὰ πᾶσι ποιεῖν τἀγαθὰ καὶ τὸ μέρος ἕκαστον αὐτῶν ἔχειν· δίκαιον γὰρ εἶναι ἰσοτιμίαν καθεστηκέναι καὶ μὴ τῷ μὲν πλέον, τῷ δὲ μηδ’ ὅλως μετεῖναι τῶν ἡδέων. ἐγὼ δὲ περὶ μὲν τούτων ἔφην ἄμεινον σκέψασθαι τὸν Δία, περὶ δὲ τῶν παρόντων καὶ ὧν ἀδικεῖσθαι ᾤοντο κατὰ τὴν ἑορτὴν ἑώρων ἐπ’ ἐμὲ καθήκουσαν τὴν κρίσιν, καὶ ὑπεσχόμην γράψειν πρὸς ὑμᾶς. ἔστι δὲ ἅπερ ἀξιοῦσι ταῦτα μέτρια, ὡς ἐμοὶ ἔδοξε. πῶς γάρ, φασί, ῥιγοῦντες τοσούτῳ κρύει καὶ λιμῷ ἐχόμενοι προσέτι ἑορτάζοιμεν ἄν; εἰ τοίνυν ἐθέλοιμι κἀκείνους μετέχειν τῆς ἑορτῆς, ἐκέλευόν με ἀναγκάσαι ὑμᾶς ἐσθήτων τε ὧν ἔχετε μεταδοῦναι αὐτοῖς, εἴ τινες περιτταὶ καὶ παχύτεραι ἢ καθ’ ὑμᾶς, καὶ τοῦ χρυσίου ὀλίγον ἐπιστάξαι αὐτοῖς· εἰ γὰρ ταῦτα, φασί, ποιήσετε, μηδὲ ἀμφισβητεῖν ὑμῖν ἔτι τῶν ἀγαθῶν ἐπὶ τοῦ Διός, εἰ δὲ μή, ἀπειλοῦσι προσκαλέσασθαι ἐπὶ τὸν ἀναδασμόν, ἐπειδὰν τὸ πρῶτον δίκας ὁ Ζεὺς προθῇ. ταῦτά ἐστιν οὐ πάνυ χαλεπὰ ὑμῖν ἀπὸ τοσούτων ἃ καλῶς ποιοῦντες ἔχετε.", "st": "55.31"}, {"sp": "N", "t": "νὴ Δία καὶ τῶν δείπνων πέρι, ὡς συνδειπνοῖεν ὑμῖν, καὶ τοῦτο προσθεῖναι ἠξίουν τῇ ἐπιστολῇ ὡς νῦν γε μόνους ὑμᾶς τρυφᾶν ἐπικλεισαμένους τὰς θύρας· εἰ δέ ποτε κἀκείνων τινὰς ἑστιᾶν διὰ μακροῦ ἐθελήσετε, πλέον τοῦ εὐφραίνοντος ἐνεῖναι τὸ ἀνιαρὸν τῷ δείπνῳ, καὶ τὰ πολλὰ ἐφ’ ὕβρει αὐτῶν γίνεσθαι, οἷον ἐκεῖνο τὸ μὴ τοῦ αὐτοῦ οἴνου συμπίνειν, Ἡράκλεις, ὡς ἀνελεύθερον· καὶ καταγινώσκειν αὐτῶν ἐκείνων ἄξιον, ὅτι μὴ μεταξὺ ἀναστάντες οἴχονται ὅλον ὑμῖν τὸ συμπόσιον καταλιπόντες. ἀλλ’ οὐδὲ ἐς κόρον ὅμως φασὶ πίνειν· τοὺ γὰρ οἰνοχόους ὑμῶν ὥσπερ τοὺς Ὀδυσσέως ἑταίρους κηρῷ βεβύσθαι τὰ ὦτα. τὰ μὲν γὰρ ἄλλα οὕτως αἰσχρά ἐστιν, ὥστε ὀκνῶ λέγειν, ἃ περὶ τῆς νομῆς τῶν κρεῶν αἰτιῶνται καὶ τῶν διακόνων, ὑμῖν μὲν παρεστώτων, ἔστ’ ἂν ὑπερεμφορηθῆτε, ἐκείνους δὲ παραθεόντων, καὶ ἄλλα πολλὰ τοιαῦτα μικροπρεπῆ καὶ ἥκιστα ἐλευθέροις πρέποντα. τὸ γοῦν ἥδιστον καὶ συμποτικώτερον ἡ ἰσοτιμία ἐστί, καὶ ὁ ἰσοδαίτης τούτου ἕνεκα ἡγεῖται ὑμῖν τῶν συμποσίων, ὡς τὸ ἴσον ἅπαντες ἔχοιεν.", "st": "55.32"}, {"sp": "N", "t": "ὁρᾶτε οὖν ὅπως μηκέτι ὑμᾶς αἰτιάσωνται, ἀλλὰ τιμήσωσι καὶ φιλήσωσι τῶν ὀλίγων τούτων μεταλαμβάνοντες, ὧν ὑμῖν μὲν ἡ δαπάνη ἀνεπαίσθητος, ἐκείνοις δὲ ἐν καιρῷ τῆς χρείας ἡ δόσις ἀείμνηστος. ἄλλως τε οὐδ’ ἂν οἰκεῖν δύναισθε τὰς πόλεις μὴ οὐχὶ καὶ πενήτων συμπολιτευομένων, καὶ μυρία πρὸς τὴν εὐδαιμονίαν ὑμῖν συντελούντων, οὐδ’ ἂν ἔχοιτε τοὺς θαυμάζοντας ὑμῶν τὸν πλοῦτον, ἢν μόνοι καὶ ἰδίᾳ καὶ ὑπὸ σκότῳ πλουτῆτε. ἰδέτωσαν οὖν πολλοὶ καὶ θαυμασάτωσαν ὑμῶν τὸν ἄργυρον καὶ τὰς τραπέζας καὶ προπινόντων φιλοτησίας, μεταξὺ πίνοντες περισκοπείτωσαν τὸ ἔκπωμα καὶ τὸ βάρος ἴστωσαν αὐτοὶ διαβαστάσαντες καὶ τῆς ἱστορίας τὸ ἀκριβὲς καὶ τὸν χρυσὸν ὅσος, ὃς ἐπανθεῖ τῇ τέχνῃ. πρὸς γὰρ τῷ χρηστοὺς καὶ φιλανθρώπους ἀκούειν καὶ τοῦ φθονεῖσθαι ὑπ’ αὐτῶν ἔξω γενήσεσθε. τίς γὰρ ἄν φθονήσειε τῷ κοινωνοῦντι καὶ διδόντι τῶν μετρίων; τίς δ’ οὐκ ἄν εὔξαιτο εἰς τὸ μήκιστον διαβιῶναι αὐτὸν ἀπολαύοντα τῶν ἀγαθῶν; ὡς δὲ νῶν ἔχετε, ἀμάρτυρος μὲν ἡ εὐδαιμονία, ἐπίφθονος δὲ ὁ πλοῦτος, ἀηδὴς δὲ ὁ βίος.", "st": "55.33"}, {"sp": "N", "t": "Οὐδὲ γὰρ οὐδὲ ὁμοίως ἡδὺ, οἶμαι, μόνον ἐμπίπλασθαι, ὥσπερ τοὺς λέοντάς φασι καὶ τοὺς μονιοὺς τῶν λύκων, καὶ συνόντας δεξιοῖς ἀνδράσι καὶ πάντα χαρίζεσθαι πειρωμενοις, οἳ πρῶτα μὲν οὐ κωφὸν καὶ ἄφωνον ἐάσουσι τὸ συμπόσιον εἶναι, ἀλλ’ ἐν μύθοις συμποτικοῖς καὶ σκώμμασιν ἀνεπαχθέσι καὶ φιλοφροσύναις ποικίλαις συνέσονται, οἷαι ἥδισται διατριβαί, φίλαι μὲν Διονύσῳ καὶ Ἀφροδίτῃ, φίλαι δὲ Χάρισιν, ἔπειτα δὲ πρὸς ἅπαντας ἐς τὴν ὑστεραίαν διηγούμενοι ὑμῶν τὴν δεξιότητα φιλεῖσθαι παρασκευάσουσι. ταῦτα πολλοῦ πρίασθαι καλῶς εἶχεν.", "st": "55.34"}, {"sp": "N", "t": "ἐπεὶ ἐρήσομαι ὑμᾶς, εἰ μύοντες οἱ πένητες βαδίζοιεν — ὑποθώμεθα γὰρ οὕτως — οὐκ ἂν ὑμᾶς ἠνίασεν οὐκ ἔχοντας οἷς ἐπιδείξαισθε τὰς ἁλουργεῖς ἐσθῆτας καὶ τῶν ἀκολουθούντων τὸ πλῆθος ἢ τῶν δακτυλίωι τὸ μέγεθος; ἐῶ λέγειν ὡς καὶ ἐπιβουλὰς καὶ μίση παρὰ τῶν πενήτων ἀναγκαῖον ἐγγίνεσθαι πρὸς ὑμᾶς, ἢν μόνοι τρυφᾶν ἐθέλητε· ἃ μὲν γὰρ εὔξασθαι καθ’ ὑμῶν ἀπειλοῦσιν, ἀποτρόπαια, μηδὲ γένοιτο εἰς ἀνάγκην αὐτοὺς καταστῆναι τῆς εὐχῆς· ἐπεὶ οὔτε ἀλλάντων γεύσεσθε οὔτε πλακοῦντος ἢ εἴ τι λείψανον τῆς κυνός, ἡ φακῆ δὲ ὑμῖν σαπέρδην ἐντετηκότα ἕξει, ὗς δὲ καὶ ἔλαφος ὀπτώμενοι μεταξὺ δρασμὸν βουλεύσουσιν ἐκ τοῦ ὀπτανείου ἐς τὸ ὄρος, καὶ ὄρνις ψύττα κατατείνασαι ἄπτεροι καὶ αὗται παρ’ αὐτοὺς τοὺς πένητας ἐκπετήσονται· τὸ δὲ μέγιστον, οἱ ὡραιότατοι τῶν οἰνοχόων φαλακροὶ ἐν ἀκαρεῖ τοῦ χρόνου ὑμῖν γενήσονται, ἐπὶ κατεαγότι καὶ ταῦτα τῷ ἀμφορεῖ. πρὸς τάδε βουλεύεσθε ἃ καὶ τῇ ἑορτῇ πρέποντα γένοιτ’ ἂν καὶ ὑμῖν ἀσφαλέστατα, καὶ ἐπικουφίζετε πολλὴν τὴν πενίαν αὐτοῖς ἀπ’ ὀλίγου τελέσματος φίλους οὐ μεμπτοὺς ἕξοντες.", "st": "55.35"}, {"sp": "SEC", "t": "Δʹ", "st": "55.36"}, {"sp": "N", "t": "οἱ πλούσιοι τῷ Κρόνῳ χαίρειν. πρὸς γὰρ σὲ οἴει μόνον ὑπὸ τῶν πενήτων ταῦτα γεγράφθαι, ὦ Κρόνε, οὐχὶ δὲ καὶ ὁ Ζεὺς ἤδη ἐκκεκώφηται πρὸς αὐτῶν ἀναβοώντων καὶ αὐτὰ δὴ ταῦτα τὸν ἀναδασμὸν ἀξιούντων γενέσθαι καὶ αἰτιωμένων τήν τε εἱμαρμένην ὡς ἄνισον τὴν νομὴν πεποιημένην καὶ ἡμᾶς ὅτι μηδενὸς αὐτοῖς μεταδιδόναι ἀξιοῦμεν; ἀλλ’ οἶδεν ἐκεῖνος, ἅτε Ζεὺς ὤν, παρ’ οἷστισιν ἡ αἰτία, καὶ διὰ τοῦτο παρακούει αὐτῶν τὰ πολλά. σοὶ δὲ ὅμως ἀπολογησόμεθα, ἐπείπερ ἄρχεις γε νῦν ἡμῶν. ἡμεῖς μὲν γὰρ ἅπαντα πρὸ ὀφθαλμῶν λαβόντες ἅ γέγραφας, ὡς καλὸν ἐπικουρεῖν ἀπὸ πολλῶν τοῖς δεομένοις καὶ ὡς ἥδιον συνεῖναι καὶ συνευωχεῖσθαι τοῖς πένησιν, ἀεὶ διετελοῦμεν οὕτως ποιοῦντες ἰσοδίαιτοι καθεστῶτες, ὡς ἂν μηδὲ τὸν συνδαίτην αὐτὸν αἰτιάσασθαί τι.", "st": "55.36"}, {"sp": "N", "t": "οἱ δὲ ὀλίγων ἐν ἀρχῇ δεῖσθαι φάσκοντες, ἐπειδήπερ ἅπαξ αὐτοῖς ἀνεπετάσαμεν τὰς θύρας, οὐκ ἀνίεσαν ἄλλα ἐπ’ ἄλλοις αἰτοῦντες· εἰ δὲ μὴ πάντα εὐθὺς μηδὲ πρὸς ἔπος λαμβάνοιεν, ὀργὴ καὶ μῖσος καὶ πρόχειροι αἱ βλασφημίαι· κἂν εἴ τι ἐπιψεύδοιντο ἡμῖν, ἀλλ’ οἵ γε ἀκούοντες ἐπίστευον ἂν ὡς ἀκριβῶς εἰδόσιν ἐκ τοῦ συγγεγονέναι. ὥστε δυοῖν θάτερον, ἤ μὴ διδόντα ἐχθρὸν εἶναι πάντως ἔδει ἢ πάντα προϊέμενον αὐτίκα μάλα πένεσθαι καὶ τῶν αἰτούντων καὶ αὐτὸν εἶναι.", "st": "55.37"}, {"sp": "N", "t": "καὶ τὰ μὲν ἄλλα μέτρια· ἐν δὲ τοῖς δείπνοις αὐτοῖς ἀμελήσαντες τοῦ ἐμπίπλασθαι καὶ γαστρίζεσθαι καὶ αὐτοί, ἐπειδὰν πλεῖον τοῦ ἱκανοῦ ἐμπίωσιν, ἢ παιδὸς ὡραίου μεταξὺ ἀναδόντος τὸ ἔκπωμα ἔνυξαν τὴν χεῖρα ἢ παλλακῇ ἢ γαμετῇ γυναικὶ ἐπεχείρησαν· εἶτα κατεμέσαντες τοῦ συμποσίου ἐς τὴν ὑστεραίαν λοιδοροῦνται ἡμῖν κατελθόντες, ὡς ἐδίψησαν καὶ ὡς λιμῷ συνῆσαν διηγούμενοι. καὶ εἴ σοι ταῦτα καταψεύδεσθαι αὐτῶν δοκοῦμεν, τὸν ὑμέτερον παράσιτον ἀναμνήσθητι τὸν Ἰξίονα, ὃς ἀξιωθεὶς κοινῆς τραπέζης, ἀξίωμα ἴσον ἔχων ὑμῖν, τῇ Ἥρᾳ μεθυσθεὶς ἐπεχείρει ὁ γενναῖος.", "st": "55.38"}, {"sp": "N", "t": "ταῦτ’ ἐστὶ καὶ τὰ τοιαῦτα, ὑφ’ ὧν ἡμεῖς ἐβουλευσάμεθα πρὸς τὸ λοιπὸν ἀσφαλείας τῆς ἡμετέρας ἕνεκεν μηκέτι ἐπιβατὸν αὐτοῖς ποιεῖν τὴν οἰκίαν. εἰ δὲ ἐπὶ σοῦ συνθοῖντο μετρίων δεήσεσθαι, ὥσπερ νῦν φασι, μηδὲν δὲ ὑβριστικὸν ἐν τοῖς συμποσίοις ὥσπερ νῦν φασι, μηδὲν δὲ ὑβριστικὸν ἐν τοῖς συμποσίοις ἐργάσεσθαι, κοινωνούντων ἡμῖν καὶ συνδειπνούντων τύχῃ τῇ ἀγαθῇ. καὶ τῶν ἱματίων, ὡς σὺ κελεύεις, πέμψομεν καὶ τοῦ χρυσίου ὁπόσον οἷόν τε καὶ προσδαπανήσομεν, καὶ ὅλως οὐδὲν ἐλλείψομεν· καὶ αὐτοὶ δὲ ἀφέμενοι τοῦ κατὰ τέχνην ὁμιλεῖν ἡμῖν φίλοι ἀντὶ κολάκων καὶ παρασίτων ἔστωσαν. ὡς ἡμᾶς γε οὐδὲν ἂν αἰτιάσαιο κἀκείνων τὰ δέοντα ποιεῖν ἐθελόντων.", "st": "55.39"}], []);})();
